Object.assign(window.TEM8_DICTIONARY, {"steering":{"media":{"uk":"media/uk/steering__gb_1.mp3","us":"media/us/steering__us_1.mp3"},"oxford":{"phon":"ˈstɪərɪŋ","pos":"noun","senses":[{"en":"the equipment in a vehicle that you use to control the direction it goes in","cn":"（车辆等的）转向装置"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(车辆等的)转向装置","en":"The steering in a car or other vehicle is the mechanical parts of it which make it possible to steer."},{"pos":"ADJ 形容词","cn":"(委员会或小组)筹划指导的","en":"A steering committee or a steering group is a group of people that organizes the early stages of a project, and makes sure it progresses in a satisfactory way.","ex":{"en":"There will be an economic steering committee with representatives of each of the republics.","cn":"将设立一个由各共和国代表组成的经济指导委员会。"}}]},"examples":[{"en":"power steering","cn":"动力转向装置"}]},"staffing":{"media":{"uk":"media/uk/staffing__gb_1.mp3","us":"media/us/staffing__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人员配备","en":"Staffing refers to the number of workers employed to work in a particular organization or building.","ex":{"en":"Staffing levels in prisons are too low.","cn":"监狱管理人员数量太少。"}}]},"examples":[{"en":"staffing levels","cn":"人员配备情况"},{"en":"The centre is staffed mainly by volunteers.","cn":""}],"oxford":{"phon":"ˈstɑːfɪŋ","pos":"noun","senses":[{"en":"the number of people who work in an institution, a company, etc.","cn":"人员配备：在机构，公司等中工作的人数。","ex":{"en":"staffing levels","cn":"人员配备水平"}}]}},"student":{"media":{"uk":"media/uk/student__gb_1.mp3","us":"media/us/student__us_1.mp3"},"oxford":{"phon":"ˈstjuːdnt","pos":"noun","senses":[{"en":"a person who is studying at a university or college","cn":"大学生；研究生","lab":"British English","ex":{"en":"a college/university student","cn":"大学生"}},{"en":"a person who is studying at a school, especially a secondary school","cn":"学生；（尤指）中学生","lab":"British English","ex":{"en":"a 15-year-old high school student","cn":"15 岁的中学生"}},{"en":"a person who is very interested in a particular subject","cn":"研究者；学者","lab":"formal","ex":{"en":"a keen student of human nature","cn":"热衷于探究人性的人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大学或学院的)学生;大学生","en":"A student is a person who is studying at a university or college.","ex":{"en":"Warren's eldest son is an art student, at St Martin's.","cn":"沃伦的大儿子是圣马丁学院艺术系的学生。"}},{"pos":"N-COUNT 可数名词","cn":"中学生","en":"A student is a child who is studying at a secondary school."},{"pos":"N-COUNT 可数名词","cn":"研究者;学者","en":"Someone who is a student of a particular subject is interested in the subject and spends time learning about it.","ex":{"en":"...a passionate student of nineteenth century history.","cn":"热衷于 19 世纪历史的研究者"}}]},"examples":[{"en":"Since she was a schoolgirl she had dreamed of going on the stage.","cn":"自从上学以来她就一直梦想着成为演员。"},{"en":"Any high school student could tell you the answer.","cn":"随便一个高中生都可以告诉你答案。"}]},"steak":{"media":{"img":["media/pic/cutlery_diningroom_comp.jpg","media/thumb/steak.jpg"],"uk":"media/uk/steak__gb_1.mp3","us":"media/us/steak__us_1.mp3"},"oxford":{"phon":"steɪk","pos":"noun","senses":[{"en":"a thick slice of good quality beef","cn":"牛排","g":"[uncountable, countable]","lab":"less frequent","ex":{"en":"fillet/rump/sirloin steak","cn":"里脊／臀肉／腰肉牛排"}},{"en":"a thick slice of any type of meat","cn":"肉排；肉块","g":"[uncountable, countable]","ex":{"en":"pork steak","cn":"猪排"}},{"en":"beef that is not of the best quality, often sold in small pieces and used in pies, stews, etc.","cn":"碎牛肉（不是最佳部位，常剁碎出售，可以炖或做馅等）","g":"[uncountable]","ex":{"en":"braising/stewing steak","cn":"适合于炖的牛肉块"}},{"en":"a large thick piece of fish","cn":"鱼排；鱼块","g":"[countable]","ex":{"en":"a cod steak","cn":"鳕鱼排"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"牛排","en":"A steak is a large flat piece of beef without much fat on it. You cook it by grilling or frying it."},{"pos":"N-UNCOUNT 不可数名词","cn":"(常指切成块出售、供炖焖用的)牛肉","en":"Steak is beef that is used for making stews. It is often cut into cubes to be sold.","ex":{"en":"...steak and kidney pie.","cn":"牛肉腰子馅饼"}},{"pos":"N-COUNT 可数名词","cn":"鱼片;鱼排","en":"A fish steak is a large piece of fish that contains few bones.","ex":{"en":"...fresh salmon steaks.","cn":"鲜鲑鱼鱼排"}}]},"examples":[{"en":"How would you like your steak done?","cn":"您要求您的牛排做到几成熟？"},{"en":"a steak knife (= one with a special blade for eating steak with)","cn":"牛排餐刀"}]},"starvation":{"media":{"uk":"media/uk/starvation__gb_1.mp3","us":"media/us/starvation__us_1.mp3"},"oxford":{"phon":"stɑːˈveɪʃn","pos":"noun","senses":[{"en":"the state in which somebody suffers or dies because they have no food","cn":"饥饿；挨饿；饿死","ex":{"en":"to die of/from starvation","cn":"饿死"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"极度饥饿;饿死","en":"Starvation is extreme suffering or death, caused by lack of food.","ex":{"en":"Over three hundred people have died of starvation since the beginning of the year.","cn":"从年初起，已有 300 多人饿死。"}}]},"examples":[{"en":"Millions will face starvation next year as a result of the drought.","cn":"由于发生旱灾，明年将有数百万人面临饥饿的威胁。"},{"en":"They were on starvation wages (= extremely low wages).","cn":"他们挣的工资不够维持基本生活。"}]},"stark":{"media":{"uk":"media/uk/stark__gb_1.mp3","us":"media/us/stark__us_1.mp3"},"oxford":{"phon":"stɑːk","pos":"adjective","senses":[{"en":"unpleasant; real, and impossible to avoid","cn":"严酷的；赤裸裸的；真实而无法回避的","ex":{"en":"The author paints a stark picture of life in a prison camp.","cn":"作者描绘出一幅冷酷而真实的战俘营生活画面。"}},{"en":"very different from something in a way that is easy to see","cn":"（指区别）明显的，鲜明的","ex":{"en":"stark differences","cn":"鲜明的区别"}},{"en":"looking severe and without any colour or decoration","cn":"毫无修饰的；荒凉的；粗陋的","ex":{"en":"I think white would be too stark for the bedroom.","cn":"我觉得卧室里用白色未免太素了。"}},{"en":"complete and total","cn":"完全的；十足的","g":"[only before noun]","ex":{"en":"The children watched in stark terror.","cn":"孩子们极端恐惧地看着。"}},{"en":"wearing no clothes","cn":"一丝不挂；赤裸","pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(选择、陈述等)严峻的，令人不快的","en":"Stark choices or statements are harsh and unpleasant.","ex":{"en":"UK companies face a stark choice if they want to stay competitive","cn":"英国公司如果想要保持竞争力就不得不面对严峻的选择。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对比)鲜明的","en":"If two things are in stark contrast to one another, they are very different from each other in a way that is very obvious.","ex":{"en":"...secret cooperation between London and Washington that was in stark contrast to official policy.","cn":"与官方的政策形成鲜明对比的伦敦和华盛顿之间的秘密合作"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"光秃的;简易的;荒凉的","en":"Something that is stark is very plain in appearance.","ex":{"en":"...the stark white, characterless fireplace in the drawing room.","cn":"客厅里简易的、毫无特色的白色壁炉"}}]},"examples":[{"en":"The good weather was in stark contrast to the storms of previous weeks.","cn":"这时的好天气和前几个星期的暴风雨形成鲜明的对比。"},{"en":"The author paints a stark picture of life in a prison camp.","cn":"作者描绘出一幅冷酷而真实的战俘营生活画面。"}]},"stream":{"media":{"uk":"media/uk/stream__gb_1.mp3","us":"media/us/stream__us_1.mp3"},"oxford":{"phon":"striːm","pos":"noun","senses":[{"en":"a small, narrow river","cn":"小河；溪","ex":{"en":"a mountain stream","cn":"山涧"}},{"en":"a continuous flow of liquid or gas","cn":"流；（液）流；（气）流","ex":{"en":"a jet stream","cn":"急流"}},{"en":"a continuous flow of people or vehicles","cn":"（人）流；（车）流","ex":{"en":"I've had a steady stream of visitors.","cn":"我不断有客人。"}},{"en":"a continuous supply of something; a large number of things that happen one after the other","cn":"源源不断（的事情）；一连串；接二连三","ex":{"en":"The agency provided me with a steady stream of work.","cn":"这介绍所让我不断有活干。"}},{"en":"a continuous flow of video or sound sent over the internet; a continuous flow of computer data or instructions","cn":"（音视频、计算机数据或指令的）流","lab":"computing","ex":{"en":"You can listen to the live audio stream.","cn":"你可以收听实时音频流。"}},{"en":"a group of students of the same age and level of ability in some schools","cn":"（将同龄学生按能力编在一起的）班，组","lab":"especially British English","ex":{"en":"She was put into the fast stream.","cn":"她被分在快班。"}},{"en":"to move or pour out in a continuous flow; to produce a continuous flow of liquid or gas","cn":"流；流动；流出","g":"[intransitive, transitive]","ex":{"en":"Tears streamed down his face.","cn":"泪水顺着他的脸往下流。"},"pos":"verb"},{"en":"to move somewhere in large numbers, one after the other","cn":"鱼贯而行；一个接一个地移动","g":"[intransitive]","ex":{"en":"People streamed across the bridge.","cn":"桥上行人川流不息。"},"pos":"verb"},{"en":"to move freely, especially in the wind or water","cn":"飘动；飘扬；漂动；漂游","g":"[intransitive]","ex":{"en":"Her scarf streamed behind her.","cn":"她的围巾在身后飘动。"},"pos":"verb"},{"en":"to put school students into groups according to their ability","cn":"按能力分班（或分组）","g":"[transitive, usually passive]","lab":"especially British English","ex":{"en":"Pupils are streamed for French and maths.","cn":"学生上法语课和数学课时按能力分成小组。"},"pos":"verb"},{"en":"to play video or sound on a computer by receiving it as a continuous stream, from the internet for example, rather than needing to wait until the whole of the material has been downloaded","cn":"用流式传输，流播（无须待整个文件下载到计算机便可播放互联网上的视频或音频文件）","g":"[transitive]","lab":"computing","ex":{"en":"You can stream the song for a single listen.","cn":"您可以流式传输歌曲以供单次收听。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小河;溪","en":"A stream is a small narrow river.","ex":{"en":"There was a small stream at the end of the garden.","cn":"花园的尽头有一条小河。"}},{"pos":"N-COUNT 可数名词","cn":"(烟、气、液体的)流，股","en":"A stream of smoke, air, or liquid is a narrow moving mass of it.","ex":{"en":"He breathed out a stream of cigarette smoke","cn":"他吐出一缕烟。"}},{"pos":"N-COUNT 可数名词","cn":"(车)流;(人)流","en":"A stream of vehicles or people is a long moving line of them.","ex":{"en":"There was a stream of traffic behind him.","cn":"在他身后是长长的车流。"}},{"pos":"N-COUNT 可数名词","cn":"一连串;接二连三;源源不断","en":"A stream of things is a large number of them occurring one after another.","ex":{"en":"The discovery triggered a stream of readers' letters.","cn":"该发现引来了读者接二连三的来信。"}},{"pos":"VERB 动词","cn":"流;流动;流出","en":"If a liquid streams somewhere, it flows or comes out in large amounts.","ex":{"en":"Tears streamed down their faces","cn":"泪水顺着他们的脸颊流下。"}},{"pos":"VERB 动词","cn":"流眼泪;流鼻涕","en":"If your eyes are streaming, liquid is coming from them, for example because you have a cold. You can also say that your nose is streaming .","ex":{"en":"Her eyes were streaming now from the wind","cn":"她的眼睛被风吹得直流泪。"}},{"pos":"VERB 动词","cn":"鱼贯而行;涌动;蜂拥","en":"If people or vehicles stream somewhere, they move there quickly and in large numbers.","ex":{"en":"Refugees have been streaming into Travnik for months","cn":"几个月来不断有难民涌入特拉夫尼克。"}},{"pos":"VERB 动词","cn":"照射","en":"When light streams into or out of a place, it shines strongly into or out of it.","ex":{"en":"Sunlight was streaming into the courtyard.","cn":"阳光照到院子里。"}},{"pos":"VERB 动词","cn":"飘动;飘扬","en":"If something such as a flag or someone's hair streams in the wind, it is blown so that it is almost horizontal.","ex":{"en":"She was wearing a flimsy pink dress that streamed out behind her","cn":"她穿的那件轻薄的粉红色连衣裙在身后飘舞。"}},{"pos":"N-COUNT 可数名词","cn":"(把孩子按年龄和能力编在一起的)班，组","en":"In a school, a stream is a group of children of the same age and ability who are taught together.","ex":{"en":"Examinations may be used to choose which pupils are to move into the top streams.","cn":"可以采取考试的方式来决定让哪些学生进入高阶班。"}},{"pos":"VERB 动词","cn":"按能力分班(或分组)","en":"To stream pupils means to divide them into groups according to their ability.","ex":{"en":"He advocates streaming children, and educating them according to their needs.","cn":"他提倡把学生按能力分班，因需施教。"}},{"pos":"PHRASE 短语","cn":"(投入)生产;(投入)使用","en":"If something such as a new factory or a new system comes on stream or is brought on stream, it begins to operate or becomes available.","ex":{"en":"As new mines come on stream, Chile's share of world copper output will increase sharply","cn":"新矿投产后，智利在世界铜产量中所占的份额将大幅增加。"}}]},"examples":[{"en":"Pupils are streamed for French and Maths.","cn":"学生按能力分成法语组和数学组。"},{"en":"The new computer system comes on stream next month.","cn":"新的计算机系统下月投入使用。"}]},"stocks":{"oxford":{"phon":"stɒk","pos":"noun","senses":[{"en":"a supply of goods that is available for sale in a shop/store （","cn":"商店的）现货，存货，库存"},{"en":"a supply of sth that is available for use","cn":"储备物；备用物；供应物"}]}},"stay":{"media":{"uk":"media/uk/stay__gb_1.mp3","us":"media/us/stay__us_1.mp3"},"oxford":{"phon":"steɪ","pos":"verb","senses":[{"en":"to continue to be in a particular place for a period of time without moving away","cn":"停留；待","g":"[intransitive]","lab":"North American English also","ex":{"en":"Stay there and don't move!","cn":"待在那儿别动！"}},{"en":"to live in a place temporarily as a guest or visitor","cn":"暂住；逗留","g":"[intransitive]","ex":{"en":"My sister's coming to stay next week.","cn":"下星期我妹妹要来住几天。"}},{"en":"to continue to be in a particular state or situation","cn":"保持；继续是","g":"[intransitive]","ex":{"en":"I can't stay awake any longer.","cn":"我困得再也熬不住了。"}},{"en":"a period of staying; a visit","cn":"停留；逗留（时间）；做客","ex":{"en":"I enjoyed my stay in Prague.","cn":"我在布拉格逗留期间过得很开心。"},"pos":"noun"},{"en":"a rope or wire that supports a ship’s mast, a pole, etc.","cn":"（船桅的）支索；（杆子等的）牵索，撑条","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"停留;逗留;留下","en":"If you stay where you are, you continue to be there and do not leave.","ex":{"en":"'Stay here,' Trish said. 'I'll bring the car down the drive to take you back.'","cn":"“呆这别动，”特里西说,“我会把车开过来送你回去。”"}},{"pos":"VERB 动词","cn":"(在某城市、旅馆或别人家)暂住，逗留","en":"If you stay in a town, or hotel, or at someone's house, you live there for a short time.","ex":{"en":"Gordon stayed at The Park Hotel, Milan","cn":"戈登下榻在米兰的帕克饭店。"}},{"pos":"V-LINK 连系动词","cn":"保持;维持","en":"If someone or something stays in a particular state or situation, they continue to be in it.","ex":{"en":"The Republican candidate said he would 'work like crazy to stay ahead'.","cn":"共和党候选人说他将“拼命保持领先优势”。"}},{"pos":"VERB 动词","cn":"不去,远离(某地)","en":"If you stay away from a place, you do not go there.","ex":{"en":"Government employees and officers also stayed away from work during the strike","cn":"政府雇员和官员在罢工期间也没去上班。"}},{"pos":"VERB 动词","cn":"不参与;不卷入","en":"If you stay out of something, you do not get involved in it.","ex":{"en":"In the past, the UN has stayed out of the internal affairs of countries unless invited in","cn":"在过去，除非有国家提出请求,否则联合国不会干涉各国内政。"}},{"pos":"PHRASE 短语","cn":"被普遍接受","en":"If you say that something is here to stay, you mean that people have accepted it and it has become a part of everyday life.","ex":{"en":"Satellite TV is here to stay","cn":"卫星电视已被普遍接受。"}},{"pos":"PHRASE 短语","cn":"固定不动;留在原地","en":"If you stay put, you remain somewhere.","ex":{"en":"He was forced by his condition to stay put and remain out of politics","cn":"他的健康状况迫使他留在原处,置身于政坛之外。"}},{"pos":"PHRASE 短语","cn":"住一晚;过夜","en":"If you stay the night in a place, you sleep there for one night.","ex":{"en":"They had invited me to come to supper and stay the night.","cn":"他们邀请我去吃晚饭并住上一晚。"}},{"pos":"","cn":"","en":"相关词组：stay in stay on stay out stay up"}]},"examples":[{"en":"‘Do you want a drink?’ ‘No, thanks, I can't stay.’ “","cn":"你要不要喝一杯？” “不，谢谢，我不能久待。”"},{"en":"Can you stay behind after the others have gone and help me clear up?","cn":"你能不能等别人走后留下来帮我收拾收拾？"}]},"strict":{"media":{"uk":"media/uk/strict__gb_1.mp3","us":"media/us/strict__us_1.mp3"},"oxford":{"phon":"strɪkt","pos":"adjective","senses":[{"en":"that must be obeyed exactly","cn":"严格的（指必须恪守）","ex":{"en":"strict rules/regulations","cn":"严格的规则／规章制度"}},{"en":"demanding that rules, especially rules about behaviour, should be obeyed","cn":"要求严格的；严厉的","ex":{"en":"a strict teacher/parent/disciplinarian","cn":"严格的教师／父亲（或母亲）／执行纪律者"}},{"en":"obeying the rules of a particular religion, belief, etc. exactly","cn":"恪守教规（或信条等）的","ex":{"en":"a strict follower of the faith","cn":"信仰的严格追随者"}},{"en":"very exact and clearly defined","cn":"严密的；严谨的；精确的","g":"[usually before noun]","ex":{"en":"It wasn’t illegal in the strict sense (of the word).","cn":"严格说来，这不算违法。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严明的;严格的;必须恪守的","en":"A strict rule or order is very clear and precise or severe and must always be obeyed completely.","ex":{"en":"The officials had issued strict instructions that we were not to get out of the jeep","cn":"有关官员严令禁止我们下吉普车。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"要求严格的;严厉的","en":"If a parent or other person in authority is strict, they regard many actions as unacceptable and do not allow them.","ex":{"en":"My parents were very strict.","cn":"父母对我要求非常严格。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严谨的;精确的;严密的","en":"If you talk about the strict meaning of something, you mean the precise meaning of it.","ex":{"en":"It's not quite peace in the strictest sense of the word, rather the absence of war.","cn":"严格说来，这并不是真正的和平，只是没有战争罢了。"}},{"pos":"ADJ 形容词","cn":"恪守信条的;严格的","en":"You use strict to describe someone who never does things that are against their beliefs.","ex":{"en":"Four million Britons are now strict vegetarians","cn":"目前有400万英国人是严格的素食者。"}}]},"examples":[{"en":"He told me in the strictest confidence (= on the understanding that I would tell nobody else).","cn":"他相信我绝对口紧，便告诉了我。"},{"en":"She's very strict about things like homework.","cn":"她对作业之类的事要求非常严格。"}]},"stood":{"collins":{"senses":[{"pos":"","cn":"","en":"Stood is the past tense and past participle of stand."}]},"media":{"uk":"media/uk/stood__gb_1.mp3","us":"media/us/stood__us_1.mp3"}},"stupendous":{"media":{"uk":"media/uk/stupendous__gb_1.mp3","us":"media/us/stupendous__us_1.mp3"},"oxford":{"phon":"stjuːˈpendəs","pos":"adjective","senses":[{"en":"extremely large or impressive, especially greater or better than you expect","cn":"极大的；令人惊叹的；了不起的","ex":{"en":"stupendous achievements","cn":"极大的成就"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极大的;令人惊叹的;了不起的","en":"Something that is stupendous is surprisingly impressive or large.","ex":{"en":"He was a man of stupendous stamina and energy","cn":"他是个有着超强耐力、精力充沛的人。"}}]},"examples":[{"en":"stupendous achievements","cn":"极大的成就"},{"en":"stupendous costs","cn":"惊人的花销"}]},"straight":{"media":{"uk":"media/uk/straight__gb_1.mp3","us":"media/us/straight__us_1.mp3"},"oxford":{"phon":"streɪt","pos":"adverb","senses":[{"en":"not in a curve or at an angle; in a straight line","cn":"笔直地；平正地；成直线","sc":"not in curve","ex":{"en":"Keep straight on for two miles.","cn":"一直向前走两英里。"}},{"en":"by a direct route; immediately","cn":"直接；径直；立即","sc":"immediately","ex":{"en":"Come straight home after school.","cn":"放学后直接回家来。"}},{"en":"in or into a level or vertical position; in or into the correct position","cn":"正；直；平正地","sc":"in level/correct position","ex":{"en":"Sit up straight!","cn":"坐直了！"}},{"en":"honestly and directly","cn":"坦率地；直截了当地","sc":"honestly","ex":{"en":"I told him straight that I didn't like him.","cn":"我坦率地告诉他说我不喜欢他。"}},{"en":"continuously without being interrupted","cn":"连续不断地；一连","sc":"continuously","ex":{"en":"They had been working for 16 hours straight.","cn":"他们已经一连工作了 16 个小时。"}},{"en":"without a bend or curve; going in one direction only","cn":"直的","sc":"without curves","ex":{"en":"a straight road","cn":"笔直的公路"},"pos":"adjective"},{"en":"positioned in the correct way; level, vertical or parallel to something","cn":"平正的；正的；直的；与…平行的","sc":"in level/correct position","ex":{"en":"Is my tie straight?","cn":"我的领带正不正？"},"pos":"adjective"},{"en":"not fitting close to the body and not curving away from the body","cn":"直筒型（非紧身）的","sc":"clothing","ex":{"en":"a straight skirt","cn":"直筒裙"},"pos":"adjective"},{"en":"going directly to the correct place","cn":"准的；正中目标的","sc":"aim/blow","ex":{"en":"a straight punch to the face","cn":"不偏不倚打在脸上的一拳"},"pos":"adjective"},{"en":"clean and neat, with everything in the correct place","cn":"整洁；整齐；井井有条","g":"[not usually before noun]","sc":"clean/neat","ex":{"en":"It took hours to get the house straight.","cn":"用了好半天才把房子收拾出来。"},"pos":"adjective"},{"en":"honest and direct","cn":"坦率的；直率的","sc":"honest","ex":{"en":"I expect a straight answer to a straight question.","cn":"我问得直率，希望答得坦诚。"},"pos":"adjective"},{"en":"simple; involving only two clear choices","cn":"简单明了的；非此即彼的","g":"[only before noun]","lab":"British English","sc":"choice","ex":{"en":"It was a straight choice between taking the job and staying out of work.","cn":"要么接受这份工作，要么继续失业，此外别无其他选择。"},"pos":"adjective"},{"en":"not connected with comedy or musical theatre, but with serious theatre","cn":"严肃的，正统的（与喜剧、音乐剧无关）","g":"[only before noun]","sc":"actor/play","pos":"adjective"},{"en":"one after another in a series that is not interrupted","cn":"连续的；不间断的","g":"[only before noun]","sc":"without being interrupted","ex":{"en":"The team has had five straight wins.","cn":"这支队已连赢五场比赛了。"},"pos":"adjective"},{"en":"not mixed with water or anything else","cn":"未掺水（或其他东西）的；纯的","lab":"British English also","sc":"alcoholic drink","pos":"adjective"},{"en":"you can use straight to describe a person who is normal and ordinary, but who you consider boring","cn":"规矩老实的；本分无趣的；正统的","lab":"informal","sc":"normal/boring","pos":"adjective"},{"en":"heterosexual","cn":"异性恋的","lab":"informal","sc":"sex","pos":"adjective"},{"en":"a person who has sexual relationships with people of the opposite sex, rather than the same sex","cn":"异性恋者","lab":"informal","sc":"sex","ex":{"en":"gays and straights","cn":"同性恋者和异性恋者"},"pos":"noun"},{"en":"a straight part of a racetrack or road","cn":"直道部分；直道","lab":"North American English also","sc":"of road/track","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"直的;笔直的","en":"A straight line or edge continues in the same direction and does not bend or curve.","ex":{"en":"Keep the boat in a straight line","cn":"让船保持直线航行。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)直的，不卷曲的","en":"Straight hair has no curls or waves in it.","ex":{"en":"Grace had long straight dark hair which she wore in a bun.","cn":"格雷斯把一头长长的黑色直发盘成发髻。"}},{"pos":"ADV 副词","cn":"笔直地;径直地","en":"You use straight to indicate that the way from one place to another is very direct, with no changes of direction.","ex":{"en":"The ball fell straight to the feet of Klinsmann","cn":"球直接落到了克林斯曼的脚上。"}},{"pos":"ADV 副词","cn":"立刻;马上","en":"If you go straight to a place, you go there immediately.","ex":{"en":"As always, we went straight to the experts for advice","cn":"像往常一样，我们马上去找专家咨询。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"直截了当的;直率的;坦诚的","en":"If you give someone a straight answer, you answer them clearly and honestly.","ex":{"en":"What a shifty arguer he is, refusing ever to give a straight answer.","cn":"他真是个狡诈的辩论家，总是拒绝给出直截了当的回答。"}},{"pos":"ADJ 形容词","cn":"连续的;不间断的","en":"Straight means following one after the other, with no gaps or intervals.","ex":{"en":"They'd won 12 straight games before they lost.","cn":"他们在输掉比赛之前已连续赢了12场。"}},{"pos":"ADJ 形容词","cn":"只涉及两人(或两物)的;(选择)非此即彼的","en":"A straight choice or a straight fight involves only two people or things.","ex":{"en":"It's a straight choice between low-paid jobs and no jobs","cn":"只有两个选择：要么是报酬很低的工作，要么就是失业。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"正经的;正统的;规矩本分的","en":"If you describe someone as straight, you mean that they are normal and conventional, for example in their opinions and in the way they live.","ex":{"en":"Dorothy was described as a very straight woman, a very strict Christian who was married to her job.","cn":"多萝西被形容成一个非常正统的女人，一个尽职尽责、非常虔诚的基督徒。"}},{"pos":"ADJ 形容词","cn":"异性恋的;非同性恋的","en":"If you describe someone as straight, you mean that they are heterosexual rather than homosexual.","ex":{"en":"His sexual orientation was a lot more gay than straight","cn":"从他的性取向来看，他不像异性恋，更像个同性恋。"}},{"pos":"ADJ 形容词","cn":"(尤指酒精饮料)纯的，不掺水的","en":"A straight drink, especially an alcoholic drink, has not had another liquid such as water added to it.","ex":{"en":"...a large straight whiskey without ice","cn":"不加冰的大杯纯威士忌"}},{"pos":"N-COUNT 可数名词","cn":"(赛道的)直道(部分)","en":"On a racetrack, a straight is a section of the track that is straight, rather than curved.","ex":{"en":"Our cars were clearly too slow along the straights","cn":"我们的赛车在直道上跑得显然太慢了。"}},{"pos":"PHRASE 短语","cn":"把…弄清楚;明确","en":"If you get something straight, you make sure that you understand it properly or that someone else does.","ex":{"en":"You need to get your facts straight","cn":"你需要讲清楚你的情况。"}},{"pos":"PHRASE 短语","cn":"改过自新;改邪归正;重新做人","en":"If a criminal is going straight, they are no longer involved in crime."},{"pos":"PHRASE 短语","cn":"走正路;过正当的生活","en":"If something keeps people on the straight and narrow, it helps to keep them living an honest or healthy life.","ex":{"en":"All her efforts to keep him on the straight and narrow have been rewarded.","cn":"她为了让他走正道所作出的一切努力都得到了回报。"}},{"pos":"","cn":"","en":"a straight face→see: ; to set the record straight→see: ;"}]},"examples":[{"en":"It was a straight choice between taking the job and staying out of work.","cn":"要么接受这份工作，要么继续失业，此外别无其他选择。"},{"en":"Let's get this straight — you really had no idea where he was?","cn":"我们把这个明确一下，你当时真的不知道他在哪儿？"}]},"start":{"media":{"uk":"media/uk/start__gb_1.mp3","us":"media/us/start__us_1.mp3"},"oxford":{"phon":"stɑːt","pos":"verb","senses":[{"en":"to begin doing or using something","cn":"开始，着手，动手（做或使用）","g":"[transitive, intransitive]","lab":"British English","sc":"doing something","ex":{"en":"I start work at nine.","cn":"我每天九点开始工作。"}},{"en":"to begin happening; to make something begin happening","cn":"（使）发生，开始进行","g":"[intransitive, transitive]","sc":"happening","ex":{"en":"Work is due to start this weekend.","cn":"本周末开始工作。"}},{"en":"when you start a machine or a vehicle or it starts, it begins to operate","cn":"开动；发动；启动","g":"[transitive, intransitive]","sc":"machine/vehicle","ex":{"en":"Start the engines!","cn":"发动引擎！"}},{"en":"to begin to exist; to make something begin to exist","cn":"（使）出现；发起；创办；开办","g":"[intransitive, transitive]","sc":"existing","ex":{"en":"The company started in 1894 in Pennsylvania.","cn":"该公司于 1894 年在宾夕法尼亚州成立。"}},{"en":"to begin from a particular place, amount or situation; to begin in a particular way","cn":"（从…）开始；（由…）起；（以…方式）开始","g":"[intransitive]","sc":"from place/level/in particular way","ex":{"en":"The trail starts just outside the town.","cn":"小径从刚出城的地方开始。"}},{"en":"to begin, or to begin something such as a career, in a particular way that changed later","cn":"以…起步（或起家）；起初是","g":"[intransitive, transitive]","sc":"from place/level/in particular way","ex":{"en":"She started as a secretary but ended up running the department.","cn":"她起初只是一个秘书，但最后掌管起了整个部门。"}},{"en":"to begin a journey; to leave","cn":"出发；动身；起程","g":"[intransitive]","sc":"journey","ex":{"en":"What time are we starting tomorrow?","cn":"我们明天什么时候出发？"}},{"en":"to begin to move in a particular direction","cn":"起身走向；向…而去","g":"[intransitive]","sc":"going/walking","ex":{"en":"I started after her (= began to follow her) to tell her the news.","cn":"我起身朝她追去，好把消息告诉她。"}},{"en":"to move suddenly and quickly because you are surprised or afraid","cn":"突然一惊","g":"[intransitive]","sc":"move suddenly","ex":{"en":"The sudden noise made her start.","cn":"突如其来的声音吓了她一跳。"}},{"en":"the point at which something begins","cn":"开头；开端","g":"[countable, usually singular]","lab":"informal","sc":"beginning","ex":{"en":"If we don't hurry, we'll miss the start.","cn":"如果我们不快点的话，我们就会错过开始的机会。"},"pos":"noun"},{"en":"the act or process of beginning something","cn":"开始","g":"[countable, usually singular]","sc":"beginning","ex":{"en":"We need to get an early start in the morning.","cn":"我们早上得早点儿出发。"},"pos":"noun"},{"en":"the opportunity that you are given to begin something in a successful way","cn":"起始优势；良好的基础条件","g":"[countable, usually singular]","sc":"opportunity","ex":{"en":"Many critics got their start writing for this magazine.","cn":"很多批评家都是从为这家杂志撰稿起步的。"},"pos":"noun"},{"en":"the place where a race begins","cn":"起点","g":"[singular]","sc":"in race","ex":{"en":"The runners lined up at the start.","cn":"赛跑运动员在起跑线上一字排开。"},"pos":"noun"},{"en":"an amount of time or distance that somebody has as an advantage over other people at the beginning of a race","cn":"起点优势（时间或距离）","g":"[countable, usually singular]","sc":"in race","ex":{"en":"I gave the younger children a start.","cn":"我让年幼的孩子提前起跑。"},"pos":"noun"},{"en":"an occasion when somebody/something competes in a race or competition, or when somebody is a member of a team that starts a game","cn":"（参加的）比赛","g":"[countable, usually plural]","lab":"sport","sc":"in race","ex":{"en":"She has been beaten only once in six starts.","cn":"她参加了六次比赛，只败过一次。"},"pos":"noun"},{"en":"an act of moving your body quickly and suddenly because you are surprised, afraid, etc.","cn":"突然一惊","g":"[countable, usually singular]","sc":"sudden movement","ex":{"en":"You gave me quite a start!","cn":"你吓了我一大跳！"},"pos":"noun"},{"en":"Strategic Arms Reduction Talks","cn":"削减战略武器会谈（美苏之间于1983年开始的一系列削减武器的谈判；1987年和1991年先后签署《中程核力量条约》和《削减战略武器条约》）","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"开始(做某事)","en":"If you start to do something, you do something that you were not doing before and you continue doing it.","ex":{"en":"John then unlocked the front door and I started to follow him up the stairs","cn":"约翰接着打开前门，我开始跟他上楼。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)开始;(使)发生","en":"When something starts, or if someone starts it, it takes place from a particular time.","ex":{"en":"The fire is thought to have started in an upstairs room","cn":"火灾被认为是从楼上的一个房间里开始燃起的。"}},{"pos":"VERB 动词","cn":"(从…)开始;(从…)着手","en":"If you start by doing something, or if you start with something, you do that thing first in a series of actions.","ex":{"en":"I started by asking how many day-care centers were located in the United States","cn":"我一开始先问了问美国有多少所日托中心。"}},{"pos":"VERB 动词","cn":"第一份工作是…","en":"You use start to say what someone's first job was. For example, if their first job was that of a factory worker, you can say that they started as a factory worker.","ex":{"en":"Betty started as a shipping clerk at the clothes factory","cn":"贝蒂的第一份工作是在服装厂里当运务员。"}},{"pos":"VERB 动词","cn":"开办;创办","en":"When someone starts something such as a new business, they create it or cause it to begin.","ex":{"en":"George Granger has started a health centre and I know he's looking for qualified staff","cn":"乔治·格兰杰开办了一个保健中心，我知道他正在物色合格的职员。"}},{"pos":"V-ERG 及物/不及物动词","cn":"开动，发动(发动机、汽车、机器等)","en":"If you start an engine, car, or machine, or if it starts, it begins to work.","ex":{"en":"He started the car, which hummed smoothly","cn":"他发动了汽车，车发出平稳的嗡嗡声。"}},{"pos":"VERB 动词","cn":"惊起;吓一跳;激灵","en":"If you start, your body suddenly moves slightly as a result of surprise or fear.","ex":{"en":"She put the bottle on the table, banging it down hard. He started at the sound","cn":"她砰的一声把瓶子放到了桌子上，把他吓了一跳。"}},{"pos":"PHRASE 短语","cn":"首先;第一","en":"You use for a start or to start with to introduce the first of a number of things or reasons that you want to mention or could mention.","ex":{"en":"You must get her name and address, and that can be a problem for a start","cn":"你必须先打听到她的姓名和地址，而那可能就是第一个难题。"}},{"pos":"PHRASE 短语","cn":"开局顺利/开局不顺","en":"If you get off to a good start, you are successful in the early stages of doing something. If you get off to a bad start, you are not successful in the early stages of doing something.","ex":{"en":"The new Prime Minister has got off to a good start, but he still has to demonstrate what manner of leader he is going to be","cn":"新首相上任后开了个好头，但他仍得展现出自己的执政风格。"}},{"pos":"PHRASE 短语","cn":"(事情、过程等)开始时，一开始","en":"To start with means at the very first stage of an event or process.","ex":{"en":"To start with, the pressure on her was very heavy, but it's eased off a bit now","cn":"一开始，她的压力很大，但现在已经好些了。"}},{"pos":"","cn":"","en":"in fits and starts→see: ; to get off to a flying start→see: ;"},{"pos":"","cn":"","en":"相关词组：start off start on start out start over start up"}]},"examples":[{"en":"She went into the second round with a five-minute start on the rest of the cyclists.","cn":"她进入了第二轮比赛，并取得比其他自行车选手提前五分钟出发的优势。"},{"en":"I started out to write a short story, but it soon developed into a novel.","cn":"我起先打算写一篇短篇小说，但很快就写成了长篇小说。"}]},"statue":{"oxford":{"phon":"ˈstætʃuː","pos":"noun","senses":[{"en":"a figure of a person or an animal in stone, metal, etc., usually the same size as in real life or larger","cn":"雕塑，雕像，塑像（大小通常等于或大于真人或实物）","lab":"US English","ex":{"en":"a bronze/marble statue","cn":"铜像；大理石像"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(石头或金属的)雕像，雕塑","en":"A statue is a large sculpture of a person or an animal, made of stone or metal."}]},"media":{"uk":"media/uk/statue__gb_1.mp3","us":"media/us/statue__us_1.mp3","img":["media/ldoce/img/statue.jpg"]},"examples":[{"en":"Churchill’s statue stands outside the parliament building.","cn":"丘吉尔的塑像矗立在议会大厦外。"},{"en":"A bronze statue was erected in his honour.","cn":"人们立了一座铜像纪念他。"}]},"stretched":{"oxford":{"phon":"stretʃ","pos":"verb","senses":[{"en":"to make sth longer, wider or looser, for example by pulling it; to become longer, etc. in this way","cn":"拉长；拽宽；撑大；抻松"},{"en":"to become bigger or longer when you pull it and return to its original shape when you stop","cn":"有弹性（或弹力）"}]},"media":{"uk":"media/uk/stretch__gb_1.mp3","us":"media/us/stretch__us_1.mp3"}},"story":{"media":{"uk":"media/uk/story__gb_1.mp3","us":"media/us/story__us_1.mp3"},"oxford":{"phon":"ˈstɔːri","pos":"noun","senses":[{"en":"a description of events and people that the writer or speaker has invented in order to entertain people","cn":"（虚构的）故事；小说","lab":"US English","ex":{"en":"a tragic love story","cn":"悲剧爱情故事"}},{"en":"the series of events in a book, film, play, etc.","cn":"（书、电影、戏剧等的）情节","ex":{"en":"Her novels always have the same basic story.","cn":"她的小说基本情节都一样。"}},{"en":"an account of past events or of how something has developed","cn":"对往事的叙述","ex":{"en":"The film is based on a true story.","cn":"这部电影以真实事件为蓝本。"}},{"en":"an account, often spoken, of what happened to somebody or of how something happened","cn":"（真实情况的）叙述，描述","ex":{"en":"The police didn't believe her story.","cn":"警方不相信她对事情的描述。"}},{"en":"a report in a newspaper, magazine or news broadcast","cn":"新闻报道","ex":{"en":"a front-page story","cn":"头版报道"}},{"en":"something that somebody says which is not true","cn":"谎言；假话","lab":"informal","ex":{"en":"She knew the child had been telling stories again.","cn":"她知道这孩子又在说谎了。"}},{"en":"a level of a building; a floor","cn":"楼层","lab":"US English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(虚构的)故事，小说","en":"A story is a description of imaginary people and events, which is written or told in order to entertain.","ex":{"en":"The second story in the book is titled 'The Scholar'","cn":"书中的第二个故事题为《学者》。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指口头的)叙述，描述","en":"A story is a description of an event or something that happened to someone, especially a spoken description of it.","ex":{"en":"The parents all shared interesting stories about their children","cn":"父母之间都会分享自己孩子的一些趣事。"}},{"pos":"N-COUNT 可数名词","cn":"传记;史话;纪事","en":"The story of something is a description of all the important things that have happened to it since it began.","ex":{"en":"...the story of the women's movement in Ireland.","cn":"爱尔兰妇女运动的记载"}},{"pos":"N-COUNT 可数名词","cn":"谎言;假话;虚构之事","en":"If someone invents a story, they give a false explanation or account of something.","ex":{"en":"He invented some story about a cousin.","cn":"他骗别人说自己有位堂兄。"}},{"pos":"N-COUNT 可数名词","cn":"新闻报道","en":"A news story is a piece of news in a newspaper or in a news broadcast.","ex":{"en":"Those are some of the top stories in the news","cn":"那些是报纸上的头条新闻。"}},{"pos":"","cn":"","en":"→see: ; →see: ;"},{"pos":"PHRASE 短语","cn":"但那是另一回事了;那就不相干了","en":"You say 'but that's another story' when you have mentioned a subject that you are not going to talk about or explain in detail.","ex":{"en":"I'd met him at a dance I'd gone to on my own. But that's another story.","cn":"我有一次独自去参加舞会时遇上了他。但那是题外话了。"}},{"pos":"PHRASE 短语","cn":"长话短说;简而言之","en":"In British English, you use to cut a long story short to indicate that you are going to state the final result of an event and not give any more details. In American English, you say to make a long story short .","ex":{"en":"To cut a long story short, I ended up as managing director.","cn":"长话短说，我最终当上了总经理。"}},{"pos":"PHRASE 短语","cn":"另一回事，不同情况(通常指不好的一面)","en":"You use a different story to refer to a situation, usually a bad one, which exists in one set of circumstances when you have mentioned that it does not exist in another set of circumstances.","ex":{"en":"Where Marcella lives, the rents are fairly cheap, but a little further north it's a different story.","cn":"玛塞拉居住的地方，租金比较便宜，但稍稍再往北一点情况就不同了。"}},{"pos":"PHRASE 短语","cn":"又来了，又是老一套(表示不好的事情似乎总是重复发生)","en":"If you say it's the same old story or it's the old story, you mean that something unpleasant or undesirable seems to happen again and again.","ex":{"en":"It's the same old story. They want one person to do three people's jobs.","cn":"又是老一套。他们想让 1 个人做 3 个人的工作。"}},{"pos":"PHRASE 短语","cn":"不是事情的全部;只是部分情况","en":"If you say that something is only part of the story or is not the whole story, you mean that the explanation or information given is not enough for a situation to be fully understood.","ex":{"en":"This may be true but it is only part of the story","cn":"这可能是真的，但它并不是事情的全部。"}},{"pos":"PHRASE 短语","cn":"对事情的说法;辩解","en":"If someone tells you their side of the story, they tell you why they behaved in a particular way and why they think they were right, when other people think that person behaved wrongly.","ex":{"en":"He had already made up his mind before even hearing her side of the story.","cn":"他没等听到她的解释就已经作出了决定。"}}]},"examples":[{"en":"We must stick to our story about the accident.","cn":"对事故的说法我们必须一口咬定，再不改口。"},{"en":"Many years later I returned to Africa but that's another story (= I am not going to talk about it now).","cn":"多年以后我又重返非洲，不过这是后话了。"}]},"stereotyped":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to decide that someone or something belongs to a particular group of people or things that have similar qualities","cn":""},{"en":"to put things or people into particular groups, especially according to an official or scientific system","cn":""}]},"examples":[{"en":"Homeless people are stereotyped as alcoholics or addicts.","cn":"","src":"ld"}],"media":{"uk":"media/uk/stereotyped__gb_1.mp3","us":"media/us/stereotyped__us_1.mp3"},"oxford":{"phon":"ˈsteriətaɪpt","pos":"adjective","senses":[{"en":"based on fixed ideas about a person or thing which may not really be true","cn":"对…形成模式化（或类型化）的看法","ex":{"en":"a play full of stereotyped characters","cn":"充斥着模式化角色的戏剧"}}]}},"stand":{"media":{"img":["media/pic/laboratory_equipment_comp.jpg","media/thumb/stand.jpg"],"uk":"media/uk/stand__gb_1.mp3","us":"media/us/stand__us_1.mp3"},"oxford":{"phon":"stænd","pos":"verb","senses":[{"en":"to be on your feet; to be in a vertical position","cn":"站立；立；直立","g":"[intransitive]","sc":"on feet/be vertical","ex":{"en":"She was too weak to stand.","cn":"她虚弱得站都站不住。"}},{"en":"to get up onto your feet from another position","cn":"站起来；起立","g":"[intransitive]","sc":"on feet/be vertical","ex":{"en":"Everyone stood when the president came in.","cn":"总统进来时大家都起立。"}},{"en":"to put something/somebody in a vertical position somewhere","cn":"使直立；竖放；使站立","g":"[transitive]","sc":"put upright","ex":{"en":"Stand the ladder up against the wall.","cn":"把梯子靠墙立好。"}},{"en":"used especially in negative sentences and questions to emphasize that you do not like somebody/something","cn":"（尤用于否定句和疑问句，强调不喜欢）容忍，忍受","g":"[transitive, no passive]","sc":"dislike","ex":{"en":"I can't stand his brother.","cn":"他弟弟让我受不了。"}},{"en":"used especially with can/could or will to say that somebody/something can survive something or can tolerate something without being hurt or damaged","cn":"（尤与 can／could 或 will 连用）经受，承受，经得起","g":"[transitive]","sc":"survive treatment","ex":{"en":"His heart won't stand the strain much longer.","cn":"他的心脏对这种压力承受不了多久。"}},{"en":"to be in a particular place","cn":"位于（某处）；坐落在；被放在","g":"[intransitive]","sc":"be in place/condition","ex":{"en":"The castle stands on the site of an ancient battlefield.","cn":"那座城堡坐落在一片古战场上。"}},{"en":"to be in a particular condition or situation","cn":"处于（某种状态或情形）","g":"[intransitive]","sc":"be in place/condition","ex":{"en":"The house stood empty for a long time.","cn":"那所房子空了好长一段时间。"}},{"en":"to be a candidate in an election","cn":"做候选人；参选","g":"[intransitive]","lab":"especially British English","sc":"in election","ex":{"en":"He stood for election in Colchester.","cn":"他在科尔切斯特参加了竞选。"}},{"en":"to be a particular height","cn":"高度为；高达","g":"[intransitive]","sc":"be at height/level","ex":{"en":"The tower stands 30 metres high.","cn":"塔高 30 米。"}},{"en":"to be at a particular level, amount, height, etc.","cn":"达特定水平（或数量、高度等）","g":"[intransitive]","sc":"be at height/level","ex":{"en":"Interest rates stand at 3 per cent.","cn":"利率为 3%。"}},{"en":"to be in a particular place, especially while waiting to go somewhere","cn":"停；停靠","g":"[intransitive]","sc":"of car/train, etc.","ex":{"en":"The train standing at platform 3 is for London, Victoria.","cn":"停在第 3 站台的火车开往伦敦维多利亚站。"}},{"en":"to remain still, without moving or being moved","cn":"停滞；不流动；搁置","g":"[intransitive]","sc":"of liquid/mixture","ex":{"en":"Mix the batter and let it stand for twenty minutes.","cn":"搅好面糊后，放上二十分钟。"}},{"en":"if an offer, a decision, etc. made earlier stands, it is still available or relevant or still exists","cn":"保持有效；维持不变","g":"[intransitive]","sc":"offer/decision","ex":{"en":"My offer still stands.","cn":"我的出价仍然算数。"}},{"en":"to be in a situation where you are likely to do something","cn":"很可能做某事","g":"[intransitive]","sc":"be likely to do something","ex":{"en":"You stand to make a lot from this deal.","cn":"你很可能会从这笔生意中大赚一笔。"}},{"en":"to have a particular attitude or opinion about something or towards somebody","cn":"（对某事）持某种态度，有某一观点，采取某种立场","g":"[intransitive]","sc":"have opinion","ex":{"en":"Where do you stand on private education?","cn":"你对私立教育持什么观点？"}},{"en":"to buy a drink or meal for somebody","cn":"花钱请（某人喝饮料或吃饭）；买…请客","g":"[transitive, no passive]","sc":"buy drink/meal","ex":{"en":"He stood drinks all round.","cn":"他请客，让大家喝了饮料。"}},{"en":"an attitude towards something or an opinion that you make clear to people","cn":"态度；立场；观点","g":"[usually singular]","sc":"opinion","ex":{"en":"He has avoided taking a firm stand.","cn":"他故意不表明立场。"},"pos":"noun"},{"en":"a strong effort to defend yourself or your opinion about something","cn":"保卫；捍卫；维护；抵抗","g":"[usually singular]","sc":"defence","ex":{"en":"They are willing to take a stand and defend what they believe in.","cn":"他们愿意进行抵抗，捍卫自己的信仰。"},"pos":"noun"},{"en":"a table or structure that goods are sold from, especially in the street or at a market","cn":"货摊；售货亭","sc":"for showing/holding something","ex":{"en":"a lemonade/hot dog/newspaper stand","cn":"柠檬味汽水／热狗售卖亭；报摊"},"pos":"noun"},{"en":"a table or a vertical structure where things are displayed or advertised, for example at an exhibition","cn":"（展示或推介物品的）桌，台，摊位","lab":"especially British English","sc":"for showing/holding something","ex":{"en":"a display/an exhibition stand","cn":"展位"},"pos":"noun"},{"en":"a piece of equipment or furniture that you use for holding a particular type of thing","cn":"架；座","sc":"for showing/holding something","ex":{"en":"a bicycle/microphone/cake stand","cn":"自行车停靠架；麦克风架；蛋糕座"},"pos":"noun"},{"en":"a large sloping structure at a stadium with rows where people sit or stand to watch the game","cn":"看台","sc":"at sports ground","ex":{"en":"We had seats in the east stand.","cn":"我们在东看台有座位。"},"pos":"noun"},{"en":"the place in court where people stand to give evidence","cn":"（法庭上的）证人席","g":"[usually singular]","lab":"British English also","sc":"in court","ex":{"en":"He took the stand as the first witness.","cn":"他第一个出庭做证。"},"pos":"noun"},{"en":"the period of time in which two people who are batting (= hitting the ball) play together and score points","cn":"两个击球员同时在场上并跑动得分的阶段；双人配对","g":"[usually singular]","sc":"in cricket","ex":{"en":"Clinch and Harris shared an opening stand of 69.","cn":"克林奇和哈里斯两位击球员，比赛一开始时搭档，共得 69 分。"},"pos":"noun"},{"en":"a place where taxis, buses, etc. park while they are waiting for passengers","cn":"停车处；站","sc":"for taxis/buses, etc.","pos":"noun"},{"en":"a group of plants or trees of one kind","cn":"林分","lab":"specialist","sc":"of plants/trees","ex":{"en":"a stand of pines","cn":"松树丛"},"pos":"noun"},{"en":"a piece of land that you can buy and use for building a house, etc. on","cn":"（建房等用的）地皮，地块","lab":"South African English","sc":"of land","ex":{"en":"A developer bought the land and divided it into stands.","cn":"开发商买下这块土地将其分为多块建筑用地。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"站;立;站立","en":"When you are standing, your body is upright, your legs are straight, and your weight is supported by your feet.","ex":{"en":"She was standing beside my bed staring down at me","cn":"她站在我的床边低头盯着我。"}},{"pos":"VERB 动词","cn":"站起来;起立","en":"When someone who is sitting stands, they change their position so that they are upright and on their feet.","ex":{"en":"Becker stood and shook hands with Ben.","cn":"贝克尔站起来和本握手。"}},{"pos":"VERB 动词","cn":"站到一边/ 往后站","en":"If you stand aside or stand back, you move a short distance sideways or backwards, so that you are standing in a different place.","ex":{"en":"I stood aside to let her pass me","cn":"我站到一边，让她从我身旁过去。"}},{"pos":"VERB 动词","cn":"(建筑物、家具等)位于","en":"If something such as a building or a piece of furniture stands somewhere, it is in that position, and is upright.","ex":{"en":"The house stands alone on top of a small hill","cn":"房子孤零零地坐落在一座小山顶上。"}},{"pos":"VERB 动词","cn":"(建筑物在周围其他建筑物倒塌或被毁后)依然存在，矗立","en":"You can say that a building is standing when it remains after other buildings around it have fallen down or been destroyed.","ex":{"en":"The palace, which was damaged by bombs in World War II, still stood","cn":"二战中遭到轰炸的那座宫殿依然矗立着。"}},{"pos":"VERB 动词","cn":"将…竖放于","en":"If you stand something somewhere, you put it there in an upright position.","ex":{"en":"Stand the plant in the open in a sunny, sheltered place.","cn":"把这株植物放在一个阳光充足、上方有遮盖物的开阔处。"}},{"pos":"VERB 动词","cn":"(将食物或调拌物等)搁置不动","en":"If you leave food or a mixture of something to stand, you leave it without disturbing it for some time.","ex":{"en":"The salad improves if made in advance and left to stand.","cn":"色拉如果能事先做好再搁置一会儿，味道会更好。"}},{"pos":"N-COUNT 可数名词","cn":"态度;立场","en":"If you take or make a stand, you do something or say something in order to make it clear what your attitude to a particular thing is.","ex":{"en":"He felt the need to make a stand against racism in South Africa","cn":"他感觉有必要表明自己对南非的种族主义持反对态度。"}},{"pos":"VERB 动词","cn":"持…态度(或立场)","en":"If you ask someone where or how they stand on a particular issue, you are asking them what their attitude or view is.","ex":{"en":"The amendment will force senators to show where they stand on the issue of sexual harassment","cn":"修订案将迫使参议员们表明自己对性骚扰问题的立场。"}},{"pos":"VERB 动词","cn":"在…眼里被如何看待","en":"If you do not know where you stand with someone, you do not know exactly what their attitude to you is.","ex":{"en":"No-one knows where they stand with him; he is utterly unpredictable","cn":"谁也不知道他怎样看待他们;他是个完全不可捉摸的人。"}},{"pos":"V-LINK 连系动词","cn":"处于(某种状况或局面)","en":"You can use stand instead of 'be' when you are describing the present state or condition of something or someone.","ex":{"en":"The alliance stands ready to do what is necessary","cn":"联盟已准备好采取必要行动。"}},{"pos":"VERB 动词","cn":"(决定、法规或提议)继续有效","en":"If a decision, law, or offer stands, it still exists and has not been changed or cancelled.","ex":{"en":"Although exceptions could be made, the rule still stands","cn":"虽然可能有例外，但该规定仍然有效。"}},{"pos":"VERB 动词","cn":"处于(某一水平)","en":"If something that can be measured stands at a particular level, it is at that level.","ex":{"en":"The inflation rate now stands at 3.6 per cent","cn":"通货膨胀率目前为 3.6%。"}},{"pos":"VERB 动词","cn":"身高为…;高度为…","en":"You can describe how tall or high someone or something is by saying that they stand a particular height.","ex":{"en":"She stood five feet five inches tall and weighed 120 pounds","cn":"她身高 5 英尺 5 英寸，体重 120 磅。"}},{"pos":"VERB 动词","cn":"经得起，承受得住(困难、考验)","en":"If something can stand a situation or a test, it is good enough or strong enough to experience it without being damaged, harmed, or shown to be inadequate.","ex":{"en":"These are the first machines that can stand the wear and tear of continuously crushing glass","cn":"这些就是第一批能经受住不停碾碎玻璃所造成的磨损的机器。"}},{"pos":"VERB 动词","cn":"忍受;容忍","en":"If you cannot stand something, you cannot bear it or tolerate it.","ex":{"en":"I can't stand any more. I'm going to run away","cn":"我再也受不了了。我要逃走。"}},{"pos":"VERB 动词","cn":"容忍;忍受","en":"If you cannot stand someone or something, you dislike them very strongly.","ex":{"en":"I can't stand that man and his arrogance","cn":"我讨厌那个男人和他的傲慢。"}},{"pos":"VERB 动词","cn":"可能获得/ 可能失去","en":"If you stand to gain something, you are likely to gain it. If you stand to lose something, you are likely to lose it.","ex":{"en":"The management group would stand to gain millions of dollars if the company were sold","cn":"如果该公司被卖掉，管理层会获得几百万美元。"}},{"pos":"VERB 动词","cn":"参加(选举);当候选人","en":"If you stand in an election, you are a candidate in it.","ex":{"en":"He has not yet announced whether he will stand in the election","cn":"他尚未宣布自己是否会参选。"}},{"pos":"VERB 动词","cn":"请(某人吃饭、喝酒)","en":"If you stand someone a meal or a drink, you buy it for them.","ex":{"en":"You can stand me a pint.","cn":"你可以请我喝一品脱啤酒。"}},{"pos":"N-COUNT 可数名词","cn":"(设在户外或大型公共建筑物内的)小店，售货摊","en":"A stand is a small shop or stall, outdoors or in a large public building.","ex":{"en":"He ran a newspaper stand outside the American Express office","cn":"他在美国运通公司办公大楼外经营一家报摊。"}},{"pos":"N-COUNT 可数名词","cn":"(运动场上的)观众台，看台","en":"A stand at a sports ground is a large structure where people sit or stand to watch what is happening.","ex":{"en":"The people in the stands at Candlestick Park are standing and cheering with all their might.","cn":"烛台体育场看台上的人们都站在那里拼命喊加油。"}},{"pos":"N-COUNT 可数名词","cn":"(供放置物品的)架，台","en":"A stand is an object or piece of furniture that is designed for supporting or holding a particular kind of thing.","ex":{"en":"The teapot came with a stand to catch the drips.","cn":"那把茶壶配有一个可以接滴水的茶托。"}},{"pos":"N-COUNT 可数名词","cn":"(出租车、公共汽车的)停车候客处","en":"A stand is an area where taxis or buses can wait to pick up passengers.","ex":{"en":"Luckily there was a taxi stand nearby.","cn":"幸好附近就有一个出租车候客处。"}},{"pos":"N-SING 单数名词","cn":"(法庭上的)证人席","en":"In a law court, the stand is the place where a witness stands to answer questions.","ex":{"en":"When the father took the stand today, he contradicted his son's testimony","cn":"那位父亲今天出庭作证时，驳斥了自己儿子的证词。"}},{"pos":"PHRASE 短语","cn":"真实性取决于;成败在于","en":"If an idea, claim, or attempt stands or falls on something, its truth or success depends on that thing.","ex":{"en":"Airlines should stand or fall on their ability to attract passengers.","cn":"航空公司的成败应该取决于它们吸引乘客的能力。"}},{"pos":"PHRASE 短语","cn":"最后的抵抗","en":"You can describe someone's final attempt to defend themselves before they are defeated as their last stand .","ex":{"en":"There they made their tragic and heroic last stand against the Roman legions.","cn":"他们在那里对罗马军团进行了最后的抵抗，场面英勇而悲壮。"}},{"pos":"PHRASE 短语","cn":"合乎情理;显然","en":"If you say it stands to reason that something is true or likely to happen, you mean that it is obvious.","ex":{"en":"It stands to reason that if you are considerate and friendly to people you will get a lot more back","cn":"显然，如果你通情达理，对人友善，那么你肯定会获得更多回报。"}},{"pos":"PHRASE 短语","cn":"妨碍;阻碍","en":"If you stand in the way of something or stand in a person's way, you prevent that thing from happening or prevent that person from doing something.","ex":{"en":"The British government would not stand in the way of such a proposal","cn":"英国政府不会阻止这样一项提议。"}},{"pos":"","cn":"","en":"to stand a chance→see: ; to stand up and be counted→see: ; to stand firm→see: ; to stand on your own two feet→see: ; to stand your ground→see: ; to stand someone in good stead→see: ; to stand trial→see: ;"},{"pos":"","cn":"","en":"相关词组：stand aside stand back stand by stand down stand for stand in stand out stand up stand up for stand up to"}]},"examples":[{"en":"‘The book's by T.C. Smith.’ ‘What does the ‘T.C.’ stand for?’ “","cn":"这部书是 T.C. Smith 写的。” “ T.C. 是哪两个字的缩写？”"},{"en":"You never know where you stand with her — one minute she's friendly, the next she'll hardly speak to you.","cn":"你从来拿不准你和她的关系如何，她一会儿跟你亲热，一会儿连话也不大跟你说。"}]},"startle":{"oxford":{"phon":"ˈstɑːtl","pos":"verb","senses":[{"en":"to surprise somebody suddenly in a way that slightly shocks or frightens them","cn":"使惊吓；使吓一跳；使大吃一惊","ex":{"en":"I didn't mean to startle you.","cn":"我不是存心要吓唬你。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"惊吓;使吓一跳","en":"If something sudden and unexpected startles you, it surprises and frightens you slightly.","ex":{"en":"The telephone startled him","cn":"电话铃声吓了他一跳。"}}]},"media":{"uk":"media/uk/startle__gb_1.mp3","us":"media/us/startle__us_1.mp3"},"examples":[{"en":"It startled me to find her sitting in my office.","cn":"我一进办公室，发现她坐在里面，把我吓了一跳。"},{"en":"She jumped back like a startled rabbit.","cn":"她像受惊的兔子似的跳了回去。"}]},"stem":{"media":{"uk":"media/uk/stem__gb_1.mp3","us":"media/us/stem__us_1.mp3","img":["media/ldoce/img/rose.jpg"]},"oxford":{"phon":"stem","pos":"noun","senses":[{"en":"the main long, thin part of a plant above the ground from which the leaves or flowers grow; a smaller part that grows from this and supports flowers or leaves","cn":"（花草的）茎；（花或叶的）梗，柄","ex":{"en":"long, trailing stems of ivy","cn":"常春藤的长茎"}},{"en":"the long, thin part of a wine glass between the bowl and the base","cn":"（高脚酒杯的）脚"},{"en":"the thin tube of a tobacco pipe","cn":"烟斗柄"},{"en":"having one or more stems of the type mentioned","cn":"有…茎（或梗）的","ex":{"en":"a long-stemmed rose","cn":"一枝长茎玫瑰"}},{"en":"the main part of a word that stays the same when endings are added to it","cn":"词干","lab":"grammar","ex":{"en":"‘Writ’ is the stem of the forms ‘writes’, ‘writing’ and ‘written’.","cn":"writ 是 writes、writing 和 written 三个词的词干。"}},{"en":"science, technology, engineering and mathematics (used to refer to these subjects as a group in the context of education and jobs)","cn":"“主干”学科，科学、技术、工程和数学教育（在教育和职业范畴对这四门学科的统称）","ex":{"en":"We need to encourage more girls to enrol on STEM courses.","cn":"我们要鼓励更多的女孩报读科学、技术、工程和数学的课程。"},"pos":"abbreviation"},{"en":"to stop something that is flowing from spreading or increasing","cn":"阻止；封堵；遏止","ex":{"en":"The cut was bandaged to stem the bleeding.","cn":"伤口已包扎止血。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"起源于;来自;由…造成","en":"If a condition or problem stems from something, it was caused originally by that thing.","ex":{"en":"All my problems stem from drink","cn":"我所有的问题都源于酗酒。"}},{"pos":"VERB 动词","cn":"阻止;遏制;制止","en":"If you stem something, you stop it spreading, increasing, or continuing.","ex":{"en":"Austria has sent three army battalions to its border with Hungary to stem the flow of illegal immigrants","cn":"奥地利已派出 3 个营的兵力去本国和匈牙利交界的边境地区阻止非法移民的流入。"}},{"pos":"N-COUNT 可数名词","cn":"(植物的)秆，茎，梗","en":"The stem of a plant is the thin, upright part on which the flowers and leaves grow.","ex":{"en":"He stooped down, cut the stem for her with his knife and handed her the flower.","cn":"他弯下腰，用刀替她将花茎割断，然后将花递给她。"}},{"pos":"N-COUNT 可数名词","cn":"(酒杯的)颈，柄脚","en":"The stem of a wine glass is the long thin part which connects the bowl to the base."},{"pos":"N-COUNT 可数名词","cn":"(烟斗)柄","en":"The stem of a pipe is the long thin part through which smoke is sucked.","ex":{"en":"He chewed the stem of his pipe and eyed her sceptically.","cn":"他嘴里衔着烟斗柄，满腹狐疑地打量着她。"}},{"pos":"N-COUNT 可数名词","cn":"(语法中的)词干","en":"In grammar, the stem of a word is the main part of it, which does not change when the ending changes."},{"pos":"PHRASE 短语","cn":"从船首到船尾","en":"If something happens from stem to stern on a boat, it involves the whole of the boat.","ex":{"en":"A South African television report said the ship was ablaze from stem to stern.","cn":"南非一则电视新闻报道称，那艘船从头到尾都着了火。"}}]},"examples":[{"en":"‘Writ’ is the stem of the forms ‘writes’, ‘writing’ and ‘written’. * writ","cn":"是 writes、writing 和 written 三个词的词干。"},{"en":"They discussed ways of stemming the flow of smuggled drugs.","cn":"他们讨论了遏制走私毒品流通的办法。"}]},"still":{"media":{"uk":"media/uk/still__gb_1.mp3","us":"media/us/still__us_1.mp3","img":["media/ldoce/img/ldoce_318.png"]},"oxford":{"phon":"stɪl","pos":"adverb","senses":[{"en":"continuing until a particular point in time and not finishing","cn":"还；还是；仍然；依旧","ex":{"en":"I am very happy that you all are still alive and well.","cn":"我很高兴你们都还健在。"}},{"en":"despite what has just been said","cn":"（虽然…）还是，但，不过","ex":{"en":"Although he promised faithfully to come, I still didn't think he would.","cn":"尽管他忠实地答应会来，但我仍然认为他不会来。"}},{"en":"used for making a comparison stronger","cn":"（加强比较级）还要，更","ex":{"en":"The next day was warmer still.","cn":"第二天更暖和了。"}},{"en":"even more","cn":"还有（更多）","ex":{"en":"There was still more bad news to come.","cn":"随后还传来了其他的坏消息。"}},{"en":"not moving; calm and quiet","cn":"静止的；平静的；安静的；寂静的","ex":{"en":"A fallen tree floated in the still water.","cn":"一棵倒下的树漂浮在静止的水中。"},"pos":"adjective"},{"en":"a still photograph or image does not move, in contrast to a moving image from a film or video","cn":"定格的；静态的","g":"[not before noun]","ex":{"en":"At this time cinema began to influence both still photography and painting.","cn":"此时，电影开始影响静态摄影和绘画。"},"pos":"adjective"},{"en":"with no wind","cn":"无风的","ex":{"en":"a still summer’s day","cn":"无风的夏日"},"pos":"adjective"},{"en":"not containing bubbles of gas; not fizzy","cn":"不含碳酸气的；不起泡的","lab":"British English","ex":{"en":"still mineral water","cn":"无汽矿泉水"},"pos":"adjective"},{"en":"a photograph of a scene from a film or video","cn":"（电影或视频的）定格画面，剧照","ex":{"en":"a publicity still from his new movie","cn":"他的新电影的宣传剧照"},"pos":"noun"},{"en":"a piece of equipment that is used for making strong alcoholic drinks","cn":"（制酒的）蒸馏器","ex":{"en":"a whisky still","cn":"威士忌蒸馏器"},"pos":"noun"},{"en":"to become calm and quiet; to make something calm and quiet","cn":"（使）静止，平静，安静","lab":"figurative","ex":{"en":"The wind stilled.","cn":"风停了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"还是;还;仍然;依然","en":"If a situation that used to exist still exists, it has continued and exists now.","ex":{"en":"I still dream of home","cn":"我依然做梦梦见家。"}},{"pos":"ADV 副词","cn":"仍然，还是(会或可能)","en":"If something that has not yet happened could still happen, it is possible that it will happen. If something that has not yet happened is still to happen, it will happen at a later time.","ex":{"en":"Big money could still be made if the crisis keeps oil prices high","cn":"如果这场危机让油价居高不下的话，仍然有可能赚大钱。"}},{"pos":"ADV 副词","cn":"(用以强调剩余物)还有","en":"If you say that there is still an amount of something left, you are emphasizing that there is that amount left.","ex":{"en":"Bardi coloured the milk with the slightest touch of coffee, of which there was still plenty","cn":"巴尔迪只加了少许咖啡给牛奶调色，还剩下很多。"}},{"pos":"ADV 副词","cn":"但是;尽管如此;(虽然…)还是","en":"You use still to emphasize that something remains the case or is true in spite of what you have just said.","ex":{"en":"I'm average for my height. But I still feel I'm fatter than I should be","cn":"从身高来看，我算是中等身材。但我还是觉得自己胖了点。"}},{"pos":"ADV 副词","cn":"(表示不必担心)然而，不过","en":"You use still to indicate that a problem or difficulty is not really worth worrying about.","ex":{"en":"Their luck had simply run out. Still, never fear","cn":"他们的好运已经到头了。不过，别担心。"}},{"pos":"ADV 副词","cn":"(与 further, another, more 等连用强调数量惊人或极大)更，还","en":"You use still in expressions such as still further ,still another, and still more to show that you find the number or quantity of things you are referring to surprising or excessive.","ex":{"en":"We look forward to strengthening still further our already close co-operation with the police service","cn":"我们期盼着进一步加强和警方的合作，形成更加紧密的合作关系。"}},{"pos":"ADV 副词","cn":"(与比较级连用强调某种特点)更，还要","en":"You use still with comparatives to indicate that something has even more of a quality than something else.","ex":{"en":"Formula One motor car racing is supposed to be dangerous. 'Indycar' racing is supposed to be more dangerous still.","cn":"据说，一级方程式赛车很危险，而“印第赛车”相比更危险。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"静止的;不动的","en":"If you stay still, you stay in the same position and do not move.","ex":{"en":"David had been dancing about like a child, but suddenly he stood still and looked at Brad","cn":"戴维一直像个孩子似的蹦蹦跳跳，但突然他停了下来看着布拉德。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(空气或水)静止的，不流动的","en":"If air or water is still, it is not moving.","ex":{"en":"The night air was very still","cn":"夜晚没有什么风。"}},{"pos":"ADJ 形容词","cn":"(饮料)不含碳酸气的，不冒泡的","en":"Drinks that are still do not contain any bubbles of carbon dioxide.","ex":{"en":"...a glass of still orange.","cn":"一杯无汽橘子水"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宁静的;寂静的","en":"If a place is still, it is quiet and shows no sign of activity.","ex":{"en":"In the room it was very still.","cn":"房间里十分宁静。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)安静；(使)无声","en":"If a sound stills or is stilled, it becomes quiet.","ex":{"en":"Her crying slowly stilled","cn":"她的哭声慢慢静了下来。"}},{"pos":"N-COUNT 可数名词","cn":"电影剧照","en":"A still is a photograph taken from a cinema film which is used for publicity purposes."},{"pos":"N-COUNT 可数名词","cn":"(制酒的)蒸馏器","en":"A still is a piece of equipment used to make strong alcoholic drinks by a process called distilling."}]},"examples":[{"en":"I wrote to them last month and I'm still waiting for a reply.","cn":"我上个月给他们写了信，到现在还在等回音。"},{"en":"It was, and still is, my favourite movie.","cn":"那部影片以前是我最喜欢的，现在仍然是。"}]},"striven":{"oxford":{"phon":"straɪv","pos":"verb","senses":[{"en":"to try very hard to achieve sth","cn":"努力；奋斗；力争；力求"}]}},"stupid":{"media":{"uk":"media/uk/stupid__gb_1.mp3","us":"media/us/stupid__us_1.mp3"},"oxford":{"phon":"ˈstjuːpɪd","pos":"adjective","senses":[{"en":"showing a lack of thought or good judgement","cn":"欠考虑的；糊涂的","ex":{"en":"a stupid mistake/question/idea","cn":"愚蠢的错误／问题／主意"}},{"en":"not clever or intelligent; slow to learn or understand","cn":"笨的；傻的；脑子不好使的","lab":"sometimes offensive","ex":{"en":"He'll manage—he isn't stupid.","cn":"他可以的，他不笨。"}},{"en":"used to emphasize that you are annoyed with somebody/something","cn":"（用以加强语气）讨厌的，恼人的","g":"[only before noun]","lab":"informal","ex":{"en":"I can't get the stupid thing open!","cn":"这破玩意儿我怎么也打不开！"}},{"en":"an offensive word for somebody who you think is not being very intelligent","cn":"傻子，笨蛋（常用于开玩笑）","ex":{"en":"Yes, stupid, it's you I'm talking to!","cn":"对，傻子，我在跟你说话呢！"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"糊涂的;头脑迟钝的;愚蠢的","en":"If you say that someone or something is stupid, you mean that they show a lack of good judgment or intelligence and they are not at all sensible.","ex":{"en":"I'll never do anything so stupid again","cn":"我再也不会做这种傻事了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"讨厌的;恼人的;无足轻重的","en":"You say that something is stupid to indicate that you do not like it or care about it, or that it annoys you.","ex":{"en":"I wouldn't call it art. It's just stupid and tasteless","cn":"我不认为这是艺术。它简直无聊透顶，毫无品位。"}}]},"examples":[{"en":"I was stupid enough to believe him.","cn":"我可真够糊涂的，竟然相信他的话。"},{"en":"Forgetting my notes made me look stupid.","cn":"我忘了带笔记，弄得自己像个傻瓜。"}]},"stoics":{"oxford":{"phon":"ˈstəʊɪk","pos":"noun","senses":[{"en":"a person who is able to suffer pain or trouble without complaining or showing what they are feeling","cn":"斯多葛派人（对痛苦或困难能默默承受或泰然处之）"}]}},"stand-in":{"oxford":{"phon":"ˈstænd ɪn","pos":"noun","senses":[{"en":"a person who does somebody’s job for a short time when they are not available","cn":"代行职务者","ex":{"en":"I acted as Tom’s stand-in when he was away.","cn":"汤姆不在时我替他顶班。"}},{"en":"a person who replaces an actor in some scenes in a film, especially dangerous ones","cn":"（尤指影视中做危险动作的）替身演员","ex":{"en":"Most of the stunts are performed by stand-ins.","cn":"大部分特技由替身演员完成。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(别人生病或不在时的)临时替代者，顶替者","en":"A stand-in is a person who takes someone else's place or does someone else's job for a while, for example because the other person is ill or away.","ex":{"en":"He was a stand-in for my regular doctor.","cn":"他临时代替平常给我看病的那位医生。"}}]},"media":{"uk":"media/uk/stand_in_1_gb_1.mp3","us":"media/us/stand_in_1_us_1.mp3"},"examples":[{"en":"Gilbert failed to find a stand-in and so could not go to the party.","cn":"吉尔伯特找不到人临时替他﹐因此无法参加派对。"},{"en":"a stand-in for Tom Cruise","cn":"汤姆•克鲁斯的替身"}]},"stick":{"media":{"img":["media/pic/stick_comp.jpg","media/thumb/stick.jpg"],"uk":"media/uk/stick__gb_1.mp3","us":"media/us/stick__us_1.mp3"},"oxford":{"phon":"stɪk","pos":"verb","senses":[{"en":"to fix something to something else, usually with a sticky substance; to become fixed to something in this way","cn":"粘贴；粘住","g":"[transitive, intransitive]","sc":"attach","ex":{"en":"He stuck a stamp on the envelope.","cn":"他把一张邮票贴到信封上。"}},{"en":"to become fixed in one position and impossible to move","cn":"（在某物中）卡住，陷住，动不了","g":"[intransitive]","sc":"become fixed","ex":{"en":"This drawer keeps sticking.","cn":"这个抽屉老卡住。"}},{"en":"to push something, usually a sharp object, into something; to be pushed into something","cn":"将…刺入（或插入）；刺；戳；插入","g":"[transitive, intransitive]","sc":"push something in","ex":{"en":"The nurse stuck the needle into my arm.","cn":"护士把针扎进我的胳膊。"}},{"en":"to put something in a place, especially quickly or carelessly","cn":"（尤指迅速或随手）放置","g":"[transitive]","lab":"informal","sc":"put","ex":{"en":"Stick your bags down there.","cn":"把你们的包搁到那儿吧。"}},{"en":"used to say in a rude and angry way that you are not interested in what somebody has, offers, does, etc.","cn":"（无礼或生气地表示）对…不感兴趣","g":"[transitive]","lab":"informal","sc":"put","ex":{"en":"I got sick of my boss's moaning and told him he could stick the job.","cn":"我烦透了老板的牢骚，便跟他说那活儿他自己干吧，我才不稀罕。"}},{"en":"to accept a difficult or unpleasant situation or person","cn":"容忍；忍受","g":"[transitive]","lab":"British English, informal，，","sc":"difficult situation","ex":{"en":"I don't know how you stick that job.","cn":"我不知道那活儿你怎么受得了。"}},{"en":"to become accepted","cn":"被接受；被证明成立","g":"[intransitive]","sc":"become accepted","ex":{"en":"The police couldn't make the charges stick (= show them to be true).","cn":"警方无法证明那些指控成立。"}},{"en":"to say that you will not take any more cards","cn":"不再要牌；停牌","g":"[intransitive]","sc":"in card games"},{"en":"a thin piece of wood that has fallen or been broken from a tree","cn":"枝条；枯枝；柴火棍儿","g":"[countable]","sc":"from tree","ex":{"en":"We collected dry sticks to start a fire.","cn":"我们捡了些枯枝生起火来。"},"pos":"noun"},{"en":"a stick that you carry and use as a support when you are walking","cn":"手杖；拐棍","g":"[countable]","lab":"especially British English","sc":"for walking","ex":{"en":"He walks with a stick these days, but he still gets about.","cn":"他最近拄上拐棍了，但还是到处走动。"},"pos":"noun"},{"en":"a long, thin object that is used in some sports to hit or control the ball","cn":"球棍","g":"[countable]","sc":"in sport","ex":{"en":"a hockey stick","cn":"曲棍球球棍"},"pos":"noun"},{"en":"a long, thin piece of something","cn":"条状物；棍状物","g":"[countable]","lab":"North American English","sc":"long thin piece","ex":{"en":"The man had sticks of dynamite strapped to his chest.","cn":"该男子胸前绑着炸药棒。"},"pos":"noun"},{"en":"a thin piece of wood or plastic that you use for a particular purpose","cn":"（木料或塑料制成的有特定用途的）棍，条，签","g":"[countable]","sc":"long thin piece","ex":{"en":"pieces of pineapple on sticks","cn":"一串串插在小棍上的菠萝块"},"pos":"noun"},{"en":"a quantity of a substance, such as solid glue (= a sticky substance), that is sold in a small container with round ends and straight sides, and can be pushed further out of the container as it is used","cn":"一管，一支（胶棒等）","g":"[countable]","sc":"container of glue","pos":"noun"},{"en":"a stick with a handle in a plane that is used to control direction or height","cn":"（飞机的）操纵杆，驾驶杆","g":"[countable]","lab":"especially North American English, informal，，","sc":"in plane/vehicle","pos":"noun"},{"en":"a handle used to change the gears of a vehicle","cn":"（车辆的）变速杆，换挡杆","g":"[countable]","lab":"especially North American English, informal，，","sc":"in plane/vehicle","pos":"noun"},{"en":"a baton, used by the person who conducts an orchestra","cn":"指挥棒","g":"[countable]","sc":"for orchestra","pos":"noun"},{"en":"criticism or severe words","cn":"批评；指责","g":"[uncountable]","lab":"British English, informal，，","sc":"criticism","ex":{"en":"The referee got a lot of stick from the home fans.","cn":"裁判饱受主队球迷的指责。"},"pos":"noun"},{"en":"country areas, a long way from cities","cn":"边远乡村地区","g":"[plural]","lab":"informal, usually disapproving，，","sc":"country areas","ex":{"en":"We live out in the sticks.","cn":"我们住在偏远的乡村。"},"pos":"noun"},{"en":"a person","cn":"人；家伙","g":"[countable]","lab":"British English, old-fashioned, informal，，，，","sc":"person","ex":{"en":"He's not such a bad old stick.","cn":"他老兄人不算坏。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枯枝;柴枝","en":"A stick is a thin branch which has fallen off a tree.","ex":{"en":"...people carrying bundles of dried sticks to sell for firewood.","cn":"背着成捆的干树枝去当薪柴卖的人们"}},{"pos":"N-COUNT 可数名词","cn":"杖;棍;棒","en":"A stick is a long thin piece of wood which is used for supporting someone's weight or for hitting people or animals.","ex":{"en":"He looks old and walks with a stick","cn":"他看起来很老，走路时拄着一根拐棍。"}},{"pos":"N-COUNT 可数名词","cn":"(用于某一特定用途的)木条，木棍","en":"A stick is a long thin piece of wood which is used for a particular purpose.","ex":{"en":"...kebab sticks.","cn":"烤肉扦"}},{"pos":"N-COUNT 可数名词","cn":"(体育运动中使用的)杖，棍，棒","en":"Some long thin objects that are used in sports are called sticks .","ex":{"en":"...lacrosse sticks.","cn":"兜网球棍"}},{"pos":"N-COUNT 可数名词","cn":"条状物;棒状物;棍状物","en":"A stick of something is a long thin piece of it.","ex":{"en":"...a stick of celery.","cn":"一根芹菜"}},{"pos":"N-UNCOUNT 不可数名词","cn":"严厉的批评;大肆的取笑","en":"If you give someone some stick, you criticize them or tease them roughly.","ex":{"en":"It's not motorists who give you the most stick, it's the general public","cn":"对你批评最严厉的并不是驾车人，而是普通民众。"}},{"pos":"N-PLURAL 复数名词","cn":"偏远乡村;边远地区","en":"If you say that someone lives in the sticks, you mean that they live a long way from any large cities.","ex":{"en":"He lived out in the sticks somewhere.","cn":"他住在某个偏远的乡村。"}},{"pos":"PHRASE 短语","cn":"批评别人的依据","en":"If you say that something is a stick to beat someone with, you mean that it is used, or could be used, as a basis for criticism.","ex":{"en":"Unfortunately historic American fiction is constantly being used as a stick to beat contemporary British writers with.","cn":"不幸的是，经典的美国小说经常被用来作为批评当代英国作家的依据。"}},{"pos":"PHRASE 短语","cn":"(完全)误解;错误地理解","en":"If someone gets the wrong end of the stick or gets hold of the wrong end of the stick, they do not understand something correctly and get the wrong idea about it."},{"pos":"PHRASE 短语","cn":"很多","en":"If you say that there are more things than you could or can shake a stick at, you are emphasizing in a humorous way that there are a lot of them.","ex":{"en":"...a man with more medals than you can shake a stick at.","cn":"拥有很多奖章的人"}},{"pos":"VERB 动词","cn":"(随便地)放，搁，塞","en":"If you stick something somewhere, you put it there in a rather casual way.","ex":{"en":"He folded the papers and stuck them in his desk drawer","cn":"他将文件叠起来，塞进自己的书桌抽屉里。"}},{"pos":"V-ERG 及物/不及物动词","cn":"刺;扎;戳","en":"If you stick a pointed object in something, or if it sticks in something, it goes into it or through it by making a cut or hole.","ex":{"en":"They sent in loads of male nurses and stuck a needle in my back","cn":"他们派来了很多男护士，在我的背上扎了一针。"}},{"pos":"VERB 动词","cn":"突出/扎进","en":"If something is sticking out from a surface or object, it extends up or away from it. If something is sticking into a surface or object, it is partly in it.","ex":{"en":"They lay where they had fallen from the crane, sticking out of the water","cn":"它们还在从起重机上掉落的地方，一部分露出水面。"}},{"pos":"VERB 动词","cn":"(用胶水、胶带等)粘，粘贴","en":"If you stick one thing to another, you attach it using glue, sticky tape, or another sticky substance.","ex":{"en":"Don't forget to clip the token and stick it on your card","cn":"别忘了剪下标志，贴到你的卡上。"}},{"pos":"VERB 动词","cn":"黏附;附着在","en":"If one thing sticks to another, it becomes attached to it and is difficult to remove.","ex":{"en":"The soil sticks to the blade and blocks the plough","cn":"土粘在犁铧上，卡住了犁。"}},{"pos":"VERB 动词","cn":"铭记在心;经久不忘","en":"If something sticks in your mind, you remember it for a long time.","ex":{"en":"The incident stuck in my mind because it was the first example I had seen of racism in that country","cn":"这件事一直萦绕在我的脑海里，因为这是我在那个国家看到的首起种族主义实例。"}},{"pos":"VERB 动词","cn":"(名字)流传开去，被众人采用","en":"If you give someone or something a name and the name sticks, it becomes the name which most people use to refer to that person or thing.","ex":{"en":"A friend dubbed it 'The Sanctuary' and the name stuck.","cn":"有位朋友戏谑地称它为“避难所”，然后这个名称就沿用了下来。"}},{"pos":"VERB 动词","cn":"(证明…)属实,成立","en":"If someone manages to make a charge or accusation stick, they show that the person accused is guilty of the crime or action they are accused of.","ex":{"en":"I don't see how they'll make the charges stick","cn":"我不知道他们将如何证明这些指控属实。"}},{"pos":"VERB 动词","cn":"固定不动","en":"If something which can usually be moved sticks, it becomes fixed in one position.","ex":{"en":"The needle on the dial went right round to fifty feet, which was as far as it could go, and there it stuck","cn":"仪表盘上的指针一下转到了 50 英尺处，也就是到头了，然后就停在那里不动了。"}},{"pos":"VERB 动词","cn":"忍受;容忍","en":"If you are in an unpleasant or difficult situation and you say that you cannot stick it, you mean that you cannot bear to remain there long.","ex":{"en":"Got a job bottle-washing at the brewery. I lasted a fortnight. I couldn't stick it","cn":"我找了份在啤酒厂洗瓶子的工作。干了两星期，就再也受不了了。"}},{"pos":"PHRASE 短语","cn":"去他的(工作);杵一边去","en":"If you say that someone can stick something, especially a job, or if you tell them where to stick it, you are rudely refusing it or emphasizing that you do not want it or like it.","ex":{"en":"It's a rotten play, so they can stick it","cn":"这部剧糟透了，他们趁早拉倒吧。"}},{"pos":"","cn":"","en":"to stick in your throat→see: ;"},{"pos":"","cn":"","en":"相关词组：stick around stick at stick by stick out stick out for stick to stick together stick up for stick with"}]},"examples":[{"en":"‘Shall we meet on Friday this week?’ ‘No, let's stick to Saturday.’ “","cn":"这个星期我们星期五见面怎么样？” “不，还是照旧在星期六吧。”"},{"en":"I got sick of my boss's moaning and told him he could stick the job.","cn":"我烦透了老板的牢骚，便跟他说那活儿他自己干吧，我才不稀罕。"}]},"stoic":{"oxford":{"phon":"ˈstəʊɪk","pos":"noun","senses":[{"en":"a person who is able to suffer pain or trouble without complaining or showing what they are feeling","cn":"斯多葛派人（对痛苦或困难能默默承受或泰然处之）"},{"en":"able to suffer pain or trouble without complaining or showing what you are feeling","cn":"斯多葛派人（对痛苦或困难能默默承受或泰然处之）","ex":{"en":"her stoic endurance","cn":"她默默承受一切的坚忍性格"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同 stoical","en":"Stoic means the same as stoical .","ex":{"en":"The kids of Kobe try to be as stoic as their parents in this tragic situation.","cn":"在这种悲惨的情形面前，神户的孩子们努力学着像他们的父母一样去坦然面对。"}},{"pos":"N-COUNT 可数名词","cn":"坚忍克己的人;坦然面对困难的人","en":"If you say that someone is a stoic, you approve of them because they do not complain or show they are upset in bad situations."}]},"media":{"uk":"media/uk/stoic__gb_1.mp3","us":"media/us/stoic__us_1.mp3"},"examples":[{"en":"her stoic endurance","cn":"她默默承受一切的坚忍性格"},{"en":"his stoical acceptance of death","cn":"他坦然面对死亡的态度"}]},"straw":{"oxford":{"phon":"strɔː","pos":"noun","senses":[{"en":"stems of wheat or other grain plants that have been cut and dried. Straw is used for making mats, hats, etc., for packing things to protect them, and as food for animals or for them to sleep on.","cn":"（收割后干燥的）禾秆，麦秆，稻草","g":"[uncountable]","ex":{"en":"a mattress filled with straw","cn":"稻草填充的垫子"}},{"en":"a single stem or piece of straw","cn":"一根禾秆（或麦秆、稻草）","g":"[countable]","ex":{"en":"He was leaning over the gate chewing on a straw.","cn":"他嘴里嚼着一根麦秆，靠到栅门上。"}},{"en":"a thin tube of plastic or paper that you drink a liquid through","cn":"（喝饮料用的）吸管","ex":{"en":"She drank her milkshake through a straw.","cn":"她用吸管喝奶昔。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(干的)稻草，麦秆，禾秆","en":"Straw consists of the dried, yellowish stalks from crops such as wheat or barley.","ex":{"en":"The barn was full of bales of straw","cn":"谷仓里堆满了成捆的稻草。"}},{"pos":"N-COUNT 可数名词","cn":"(喝饮料用的)吸管","en":"A straw is a thin tube of paper or plastic, which you use to suck a drink into your mouth.","ex":{"en":"...a bottle of lemonade with a straw in it.","cn":"一瓶插着吸管的柠檬水"}},{"pos":"PHRASE 短语","cn":"抓救命稻草;采取极端措施;作绝望的挣扎","en":"If you are clutching at straws or grasping at straws, you are trying unusual or extreme ideas or methods because other ideas or methods have failed.","ex":{"en":"...a badly thought-out scheme from a Government clutching at straws.","cn":"政府情急之下采取的考虑欠周的计划"}},{"pos":"PHRASE 短语","cn":"压垮骆驼的最后一根稻草;最终使人不堪忍受的事","en":"If an event is the last straw or the straw that broke the camel's back, it is the latest in a series of unpleasant or undesirable events, and makes you feel that you cannot tolerate a situation any longer.","ex":{"en":"For him the Church's decision to allow the ordination of women had been the last straw","cn":"教会同意授给女性神职的决定使他终于忍无可忍。"}},{"pos":"PHRASE 短语","cn":"下下签;苦差","en":"If you draw the short straw, you are chosen from a number of people to perform a job or duty that you will not enjoy.","ex":{"en":"...if a few of your guests have drawn the short straw and agreed to drive others home after your summer barbecue.","cn":"如果你的一些客人不幸被抓了壮丁，同意在夏日烧烤野餐结束后开车把其他人送回家"}},{"pos":"PHRASE 短语","cn":"迹象;苗头;征兆","en":"If you say that an incident or piece of news is a straw in the wind, you mean that it gives an indication of what might happen in the future.","ex":{"en":"The latest straw in the wind is a pick-up in sales among the nation's retail giants.","cn":"最新的迹象是该国几家零售巨头的销售额有所上升。"}}]},"media":{"uk":"media/uk/straw__gb_1.mp3","us":"media/us/straw__us_1.mp3","img":["media/ldoce/img/straws.jpg"]},"examples":[{"en":"He was leaning over the gate chewing on a straw.","cn":"他嘴里嚼着一根麦秆，靠到栅门上。"},{"en":"a mattress filled with straw","cn":"稻草填充的垫子"}]},"startling":{"media":{"uk":"media/uk/startling__gb_1.mp3","us":"media/us/startling__us_1.mp3"},"oxford":{"phon":"ˈstɑːtlɪŋ","pos":"adjective","senses":[{"en":"extremely unusual and surprising","cn":"惊人的；让人震惊的","ex":{"en":"a startling discovery","cn":"惊人的发现"}},{"en":"extremely bright","cn":"极鲜亮的","ex":{"en":"startling blue eyes","cn":"蓝盈盈的眼睛"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人吃惊的;惊人的;不寻常的","en":"Something that is startling is so different, unexpected, or remarkable that people react to it with surprise.","ex":{"en":"Sometimes the results may be rather startling.","cn":"有时结果可能会令人吃惊。"}}]},"examples":[{"en":"startling blue eyes","cn":"蓝盈盈的眼睛"},{"en":"a startling discovery","cn":"惊人的发现"}]},"storytelling":{"media":{"uk":"media/uk/storytelling__gb_1.mp3","us":"media/us/storytelling__us_1.mp3"},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"讲故事;说书;写小说","en":"Storytelling is the activity of telling or writing stories.","ex":{"en":"The programme is 90 minutes of dynamic Indian folk dance, live music and storytelling.","cn":"该节目为 90 分钟，其中有动感印度民间舞蹈、现场音乐表演和说书。"}}]},"oxford":{"phon":"ˈstɔːritelɪŋ","pos":"noun","senses":[{"en":"the activity of telling or writing stories","cn":"讲故事：讲故事或写故事的活动","ex":{"en":"She has a gift for storytelling.","cn":"她有讲故事的天分。"}}]}},"structure":{"media":{"uk":"media/uk/structure__gb_1.mp3","us":"media/us/structure__us_1.mp3"},"oxford":{"phon":"ˈstrʌktʃə(r)","pos":"noun","senses":[{"en":"the way in which the parts of something are connected together, arranged or organized; a particular arrangement of parts","cn":"结构；构造","g":"[uncountable, countable]","ex":{"en":"the structure of the building","cn":"这座建筑物的结构"}},{"en":"a thing that is made of several parts, especially a building","cn":"结构体；（尤指）建筑物","g":"[countable]","lab":"British English","ex":{"en":"a stone/brick/wooden structure","cn":"石／砖／木结构建筑物"}},{"en":"the state of being well organized or planned with all the parts linked together; a careful plan","cn":"精心组织；周密安排；体系","g":"[uncountable, countable]","ex":{"en":"Your essay needs (a) structure.","cn":"你这篇文章组织不好。"}},{"en":"to arrange or organize something into a system or pattern","cn":"使形成体系；系统安排；精心组织","ex":{"en":"How well does the teacher structure the lessons?","cn":"老师对课程组织安排得如何？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"结构;构造;组织","en":"The structure of something is the way in which it is made, built, or organized.","ex":{"en":"The typical family structure of Freud's patients involved two parents and two children","cn":"弗洛伊德的病人的典型家庭结构是父母二人和两个孩子。"}},{"pos":"N-COUNT 可数名词","cn":"结构体","en":"A structure is something that consists of parts connected together in an ordered way.","ex":{"en":"The feet are highly specialised structures made up of 26 small delicate bones.","cn":"脚的结构非常特殊，由 26 块细小的骨头组成。"}},{"pos":"N-COUNT 可数名词","cn":"建筑物","en":"A structure is something that has been built.","ex":{"en":"About half of those funds has gone to repair public roads, structures and bridges","cn":"那些基金中大约有一半已被用来维修公路、公共建筑物和桥梁。"}},{"pos":"VERB 动词","cn":"系统安排;精心组织;使形成体系","en":"If you structure something, you arrange it in a careful, organized pattern or system.","ex":{"en":"By structuring the course this way, we're forced to produce something the companies think is valuable.","cn":"这样制定发展规划后，我们不得不生产各公司认为有价值的东西。"}}]},"examples":[{"en":"As a photographer, shape and form were more important to him than colour.","cn":"作为摄影师，形状和结构对他来说比颜色更重要。"},{"en":"changes in the social and economic structure of society","cn":"一个社会在社会结构和经济结构上的变化"}]},"stationery":{"oxford":{"phon":"ˈsteɪʃənri","pos":"noun","senses":[{"en":"materials for writing and for using in an office, for example paper, pens and envelopes","cn":"文具"},{"en":"special paper for writing letters on","cn":"信纸；信笺","ex":{"en":"The logo featured on the letterhead stationery for the Association.","cn":"协会专用信笺在信头印有协会标志。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"文具","en":"Stationery is paper, envelopes, and other materials or equipment used for writing."}]},"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/folder.jpg"],"uk":"media/uk/stationery__gb_1.mp3","us":"media/us/stationery__us_1.mp3"},"examples":[{"en":"a letter on hotel stationery","cn":"用酒店信纸写的信"}]},"stylist":{"media":{"uk":"media/uk/stylist__gb_1.mp3","us":"media/us/stylist__us_1.mp3"},"oxford":{"phon":"ˈstaɪlɪst","pos":"noun","senses":[{"en":"a person whose job is cutting and shaping people’s hair","cn":"发型师","ex":{"en":"She was the salon’s top stylist.","cn":"她是沙龙的顶级造型师。"}},{"en":"a person who designs fashionable clothes or advises people on fashion","cn":"时装设计师；时装搭配师","ex":{"en":"He became a fashion stylist and design consultant.","cn":"他成为一名时尚造型师和设计顾问。"}},{"en":"a writer who takes great care to write or say something in a beautiful or unusual way","cn":"语言风格优美（或独特）的人；文体家","ex":{"en":"Cela was a stylist who loved the rhythm and sound of words.","cn":"塞拉是一位热爱文字节奏和声音的造型师。"}},{"en":"a person whose job is to create or design a particular style or image for a product, a person, an advertisement, etc.","cn":"（产品、人、广告等的）造型设计师，形象设计师","ex":{"en":"She worked as a food stylist for a major publishing house.","cn":"她曾在一家大型出版社担任食品设计师。"}},{"en":"a person who performs with style","cn":"表现得有格调的人","ex":{"en":"As a footballer, he is a supreme stylist.","cn":"作为一名足球运动员，他是一位至高无上的造型师。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"发型师","en":"A stylist is a person whose job is to cut and arrange people's hair.","ex":{"en":"Choose a stylist recommended by someone whose hair you like.","cn":"选择一个你觉得发型很好看的人向你推荐的发型师。"}},{"pos":"N-COUNT 可数名词","cn":"(广告、明星形象等的)造型设计师","en":"A stylist is someone whose job is to create the style of something such as an advertisement or the image of people such as pop singers.","ex":{"en":"She is now a writer and fashion stylist.","cn":"她现在是作家兼时尚造型师。"}},{"pos":"N-COUNT 可数名词","cn":"文体家;追求风格的人","en":"If you describe someone as a stylist, you mean that they pay a lot of attention to the way they write, say, or do something so that it is attractive and elegant.","ex":{"en":"He is the finest stylist in the English language of today.","cn":"他是当今英语世界中文采最好的。"}}]},"examples":[{"en":"Renee was the top stylist at the salon.","cn":"勒妮是这家美发厅最好的发型师。"},{"en":"Billie Holiday, one of jazz’s most distinctive stylists","cn":"比利·霍利戴﹐爵士乐界最具独特风格的歌手之一"}]},"sti":{"oxford":{"phon":"ˌes tiː ˈaɪ","pos":"noun","senses":[{"en":"an infection that is passed from one person to another during sexual activity (the abbreviation for ‘sexually transmitted infection’)","cn":"性传播感染（全写为 sexually transmitted infection）","ex":{"en":"a fact sheet on the symptoms and treatment of STIs","cn":"关于性传播感染的症状和治疗的情况说明书"}}]},"media":{"uk":"media/uk/sti_1_gb_1.mp3","us":"media/us/sti_1_us_1.mp3"}},"station":{"media":{"uk":"media/uk/station__gb_1.mp3","us":"media/us/station__us_1.mp3"},"oxford":{"phon":"ˈsteɪʃn","pos":"noun","senses":[{"en":"a place where trains stop so that passengers can get on and off; the buildings connected with this","cn":"火车站","lab":"British English also","sc":"for trains/buses","ex":{"en":"the main station","cn":"中心车站"}},{"en":"a place where buses stop; the buildings connected with this","cn":"公共汽车站；长途汽车站","lab":"British English also","sc":"for trains/buses","ex":{"en":"We waited for him at the bus station.","cn":"我们在公交车站等他。"}},{"en":"a place or building where a service is organized and provided or a special type of work is done","cn":"站；所；局","lab":"British English","sc":"for work/service","ex":{"en":"Report the theft at the nearest police station.","cn":"向最近的警察局报告盗窃案。"}},{"en":"a radio or television company and the programmes it broadcasts","cn":"电台；电视台","sc":"radio/TV company","ex":{"en":"a local radio/television/TV station","cn":"地方广播电台／电视台"}},{"en":"your social position","cn":"社会地位；身份","lab":"old-fashioned or formal","sc":"social position","ex":{"en":"She was definitely getting ideas above her station.","cn":"她明显是抱有超出自己身份的想法。"}},{"en":"a place where somebody has to wait and watch or be ready to do work if needed","cn":"须坚守的位置；岗位","sc":"position","ex":{"en":"You are not to leave your station without permission.","cn":"未经允许，不得离开岗位。"}},{"en":"a large sheep or cattle farm in Australia or New Zealand","cn":"（澳大利亚或新西兰放养牛或羊的）大型牧场","sc":"large farm"},{"en":"a small base for the army or navy; the people living in it","cn":"军事基地；驻军","sc":"for soldiers, sailors","ex":{"en":"a naval station","cn":"海军基地"}},{"en":"to send somebody, especially from one of the armed forces, to work in a place for a period of time","cn":"派驻；使驻扎","g":"[often passive]","sc":"armed forces","ex":{"en":"troops stationed abroad","cn":"驻扎在国外的部队"},"pos":"verb"},{"en":"to go somewhere and stand or sit there, especially to wait for something; to send somebody somewhere to do this","cn":"到某处站（或坐）；把…安置到（某处）","lab":"formal","sc":"go to position","ex":{"en":"She stationed herself at the window to await his return.","cn":"她待在窗前等他回来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火车站","en":"A station is a building by a railway line where trains stop so that people can get on or off.","ex":{"en":"Ingrid went with him to the railway station to see him off","cn":"英格丽德和他一起去火车站送他。"}},{"pos":"N-COUNT 可数名词","cn":"(公共汽车)站","en":"A bus station is a building, usually in a town or city, where buses stop, usually for a while, so that people can get on or off."},{"pos":"N-COUNT 可数名词","cn":"广播电台(或电视台)","en":"If you talk about a particular radio or television station, you are referring to the programmes broadcast by a particular radio or television company.","ex":{"en":"...an independent local radio station","cn":"独立的地方电台"}},{"pos":"V-PASSIVE 被动动词","cn":"安置,派驻(士兵或官员);使驻扎","en":"If soldiers or officials are stationed in a place, they are sent there to do a job or to work for a period of time.","ex":{"en":"Reports from the capital, Lome, say troops are stationed on the streets","cn":"来自首都洛美的报道称，部队驻扎在大街上。"}},{"pos":"VERB 动词","cn":"(常指为某一特定目的)在…守候","en":"If you station yourself somewhere, you go there and wait, usually for a particular purpose.","ex":{"en":"The musicians stationed themselves quickly on either side of the stairs","cn":"乐师们很快就静候在了楼梯的两边。"}}]},"examples":[{"en":"She was definitely getting ideas above her station.","cn":"她明显是抱有超出自己身分的想法。"},{"en":"You are not to leave your station without permission.","cn":"未经允许，不得离开岗位。"}]},"struck":{"collins":{"senses":[{"pos":"","cn":"","en":"Struck is the past tense and past participle of strike."}]},"media":{"uk":"media/uk/struck__gb_1.mp3","us":"media/us/struck__us_1.mp3"}},"stony":{"media":{"uk":"media/uk/stony__gb_1.mp3","us":"media/us/stony__us_1.mp3"},"oxford":{"phon":"ˈstəʊni","pos":"adjective","senses":[{"en":"having a lot of stones on it or in it","cn":"多石的；石头的","ex":{"en":"stony soil","cn":"多石的土壤"}},{"en":"showing a lack of feeling or sympathy","cn":"冷漠的；无情的；铁石心肠的","ex":{"en":"They listened to him in stony silence.","cn":"他们冷漠地静静听他讲。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地)多石的，不平的","en":"Stony ground is rough and contains a lot of stones.","ex":{"en":"The steep, stony ground is well drained.","cn":"陡峭的石头地面排水性能很好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(表情或态度)冷酷的，无情的，冰冷的","en":"A stony expression or attitude does not show any sympathy or friendliness.","ex":{"en":"She gave me the stoniest look I ever got","cn":"她看我的眼神冷酷无比。"}}]},"examples":[{"en":"They listened to him in stony silence.","cn":"他们冷漠地静静听他讲。"},{"en":"stony soil","cn":"多石的土壤"}]},"stoop":{"media":{"uk":"media/uk/stoop__gb_1.mp3","us":"media/us/stoop__us_1.mp3"},"oxford":{"phon":"stuːp","pos":"verb","senses":[{"en":"to bend your body forwards and downwards","cn":"俯身；弯腰","g":"[intransitive]","ex":{"en":"She stooped down to pick up the child.","cn":"她俯身抱起孩子。"}},{"en":"to stand or walk with your head and shoulders bent forwards","cn":"（站立或行走时）弓背","g":"[intransitive]","ex":{"en":"He tends to stoop because he's so tall.","cn":"他个子太高了，所以时常弓着背。"}},{"en":"if somebody has a stoop, their shoulders are always bent forward","cn":"曲背；驼背","g":"[singular]","pos":"noun"},{"en":"a raised area outside the door of a house with steps leading up to it","cn":"门廊","g":"[countable]","lab":"North American English","ex":{"en":"the front stoop","cn":"前面的弯腰"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(站立或行走时)弓背，驼背","en":"If you stoop, you stand or walk with your shoulders bent forwards.","ex":{"en":"She was taller than he was and stooped slightly.","cn":"她比他高，而且略微有些驼背。"}},{"pos":"VERB 动词","cn":"弯腰;俯身","en":"If you stoop, you bend your body forwards and downwards.","ex":{"en":"He stooped to pick up the carrier bag of groceries","cn":"他俯下身去提装着食品杂货的购物袋。"}},{"pos":"VERB 动词","cn":"堕落(或卑鄙)到去做","en":"If you say that a person stoops to doing something, you are criticizing them because they do something wrong or immoral that they would not normally do.","ex":{"en":"He had not, until recently, stooped to personal abuse","cn":"他以前从未像最近这样卑鄙到进行人身攻击。"}},{"pos":"N-COUNT 可数名词","cn":"门廊;门阶","en":"A stoop is a small platform at the door of a building, with steps leading up to it.","ex":{"en":"They stood together on the stoop and rang the bell.","cn":"他们一起站在门廊上按响了门铃。"}}]},"examples":[{"en":"She was unwilling to believe anyone would stoop so low as to steal a ring from a dead woman's finger.","cn":"她无法相信真有人会龌龊到这种地步，竟然从一个死去的女人手指上偷戒指。"},{"en":"You surely don't think I'd stoop to that!","cn":"你不会认为我会下作到那种地步吧！"}]},"stimulus":{"media":{"uk":"media/uk/stimulus__gb_1.mp3","us":"media/us/stimulus__us_1.mp3"},"oxford":{"phon":"ˈstɪmjələs","pos":"noun","senses":[{"en":"something that helps somebody/something to develop better or more quickly","cn":"促进因素；激励因素；刺激物","g":"[usually singular]","ex":{"en":"Books provide children with ideas and a stimulus for play.","cn":"书不仅给孩子们提供想法，而且使他们玩得更有意思。"}},{"en":"something that produces a reaction in a human, an animal or a plant","cn":"（使生物产生反应的）刺激，刺激物","ex":{"en":"sensory/verbal/visual stimuli","cn":"感官／言语／视觉刺激"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"刺激物;促进因素","en":"A stimulus is something that encourages activity in people or things.","ex":{"en":"Interest rates could fall soon and be a stimulus to the US economy","cn":"利率可能很快就会下调，从而刺激美国经济。"}}]},"examples":[{"en":"Books provide children with ideas and a stimulus for play.","cn":"书不仅给孩子们提供想法，而且使他们玩得更有意思。"},{"en":"The animals were conditioned to respond to auditory stimuli (= sounds).","cn":"经过训练，那些动物对声音形成了条件反射。"}]},"stockings":{"oxford":{"phon":"ˈstɒkɪŋ","pos":"noun","senses":[{"en":"either of a pair of thin pieces of clothing that fit closely over a woman's legs and feet","cn":"长筒女袜"},{"en":"wearing socks or stockings but not shoes","cn":"只穿袜不穿鞋"}]}},"static":{"oxford":{"phon":"ˈstætɪk","pos":"adjective","senses":[{"en":"not moving, changing or developing","cn":"静止的；静态的；停滞的","ex":{"en":"The balance sheet provides a static picture of the financial position at a point in time.","cn":"资产负债表提供了某个时间点财务状况的静态图景。"}},{"en":"acting as a weight but not producing movement","cn":"静力的","lab":"physics","ex":{"en":"static pressure","cn":"静压"}},{"en":"noise or other effects that interrupt radio or television signals and are caused by particular conditions in the atmosphere","cn":"天电（干扰）","pos":"noun"},{"en":"electricity that gathers on or in an object that is not a conductor of electricity","cn":"静电","ex":{"en":"My hair gets full of static when I brush it.","cn":"我梳头时头发就有好多静电。"},"pos":"noun"},{"en":"the science that deals with the forces that balance each other to keep objects in a state of rest","cn":"静力学","pos":"noun"},{"en":"angry or critical comments or behaviour","cn":"抨击；指责；愤慨","lab":"North American English, informal，，","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"静止的;不变化的","en":"Something that is static does not move or change.","ex":{"en":"The number of young people obtaining qualifications has remained static or decreased","cn":"获得资格证的年轻人数量一直维持不变或出现下降。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"静电","en":"Static or static electricity is electricity which can be caused by things rubbing against each other and which collects on things such as your body or metal objects."},{"pos":"N-UNCOUNT 不可数名词","cn":"(广播、电视里的)静电噪声，静电干扰","en":"If there is static on the radio or television, you hear a series of loud noises which spoils the sound."}]},"media":{"uk":"media/uk/static__gb_1.mp3","us":"media/us/static__us_1.mp3"},"examples":[{"en":"Prices on the stock market, which have been static, are now rising again.","cn":"股市价格一直停滞不动，现在又在上涨了。"},{"en":"My hair gets full of static when I brush it.","cn":"我梳头时头发就有好多静电。"}]},"stripes":{"oxford":{"phon":"strɪp","pos":"verb","senses":[{"en":"to take off all or most of your clothes or another person's clothes","cn":"脱光衣服；脱掉大部分衣服；扒光 … 的衣服"},{"en":"to take off your clothes as a form of entertainment; to perform a striptease","cn":"进行脱衣表演；表演脱衣舞"}]},"media":{"uk":"media/uk/strip__gb_1.mp3","us":"media/us/strip__us_1.mp3"}},"staircase":{"media":{"img":["media/ldoce/img/staircase.jpg","media/pic/staircase.jpg"],"uk":"media/uk/staircase__gb_1.mp3","us":"media/us/staircase__us_1.mp3"},"oxford":{"phon":"ˈsteəkeɪs","pos":"noun","senses":[{"en":"a set of stairs inside a building including the banisters (= posts and bars that are fixed at the side)","cn":"（建筑物内带扶手的）楼梯","ex":{"en":"a marble/stone/wooden staircase","cn":"大理石／石头／木楼梯"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(建筑物内的)楼梯","en":"A staircase is a set of stairs inside a building.","ex":{"en":"They walked down the staircase together.","cn":"他们一起下了楼梯。"}}]},"examples":[{"en":"a marble/stone/wooden staircase","cn":"大理石/石/木楼梯"}]},"storyline":{"media":{"uk":"media/uk/storyline__gb_1.mp3","us":"media/us/storyline__us_1.mp3"},"oxford":{"phon":"ˈstɔːrilaɪn","pos":"noun","senses":[{"en":"the basic story in a novel, play, film, etc.","cn":"（小说、戏剧、电影等的）故事情节，本事","ex":{"en":"Her novels always have the same basic storyline.","cn":"她的小说总是依据一个相同的本事。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(书、电影或戏剧的)故事情节","en":"The storyline of a book, film, or play is its story and the way in which it develops.","ex":{"en":"The surprise twists in the storyline are the film's greatest strength.","cn":"该影片最精彩之处就是剧情的曲折离奇。"}}]}},"strategic":{"media":{"uk":"media/uk/strategic__gb_1.mp3","us":"media/us/strategic__us_1.mp3"},"oxford":{"phon":"strəˈtiːdʒɪk","pos":"adjective","senses":[{"en":"done as part of a plan that is meant to achieve a particular purpose or to gain an advantage","cn":"根据全局而安排的；战略性的","ex":{"en":"strategic planning","cn":"全局性规划"}},{"en":"connected with getting an advantage in a war or other military situation","cn":"战略性的；战略上的","ex":{"en":"Malta was of vital strategic importance during the war.","cn":"在那次战争中，马耳他的战略意义至为关键。"}},{"en":"intended to be fired at an enemy’s country rather than used in a battle","cn":"战略性的","ex":{"en":"strategic missiles","cn":"战略导弹"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"战略(性)的;策略(上)的","en":"Strategic means relating to the most important, general aspects of something such as a military operation or political policy, especially when these are decided in advance.","ex":{"en":"...the new strategic thinking which NATO leaders produced at the recent London summit","cn":"北约领导人在最近召开的伦敦首脑会议上提出的新的战略思想"}},{"pos":"ADJ 形容词","cn":"(武器)战略性的","en":"Strategic weapons are very powerful missiles that can be fired only after a decision to use them has been made by a political leader.","ex":{"en":"...strategic nuclear weapons.","cn":"战略性核武器"}},{"pos":"ADJ 形容词","cn":"(位置)具有战略意义的，重要的，合适的","en":"If you put something in a strategic position, you place it cleverly in a position where it will be most useful or have the most effect.","ex":{"en":"...the marble benches Eve had placed at strategic points throughout the gardens, where the views were spectacular.","cn":"伊芙在各花园景色迷人的地方巧妙安置的大理石长凳"}}]},"examples":[{"en":"Malta was of vital strategic importance during the war.","cn":"在那次战争中，马耳他的战略意义至为关键。"},{"en":"Cameras were set up at strategic points (= in places where they would be most effective) along the route.","cn":"在沿途一些最佳位置架设了摄像机。"}]},"stretch":{"media":{"uk":"media/uk/stretch__gb_1.mp3","us":"media/us/stretch__us_1.mp3"},"oxford":{"phon":"stretʃ","pos":"verb","senses":[{"en":"to make something longer, wider or looser, for example by pulling it; to become longer, etc. in this way","cn":"拉长；拽宽；撑大；抻松","g":"[transitive, intransitive]","sc":"make/become bigger/looser","ex":{"en":"Is there any way of stretching shoes?","cn":"有什么办法能把鞋撑大吗？"}},{"en":"to become bigger or longer when you pull it and return to its original shape when you stop","cn":"有弹性（或弹力）","g":"[intransitive]","sc":"make/become bigger/looser","ex":{"en":"The jeans stretch to provide a perfect fit.","cn":"这条牛仔裤有弹性，可以完全贴身。"}},{"en":"to pull something so that it is smooth and tight","cn":"拉紧；拉直；绷紧","g":"[transitive]","sc":"pull tight","ex":{"en":"Stretch the fabric tightly over the frame.","cn":"把布在架子上绷紧。"}},{"en":"to put your arms or legs out straight and contract your muscles","cn":"伸展；舒展","g":"[intransitive, transitive]","sc":"your body","ex":{"en":"He stretched and yawned lazily.","cn":"他伸了伸懒腰，打了个哈欠。"}},{"en":"to put out an arm or a leg in order to reach something","cn":"伸出，伸长（胳膊、腿）","g":"[intransitive, transitive]","sc":"reach with arm","ex":{"en":"She stretched across the table for the butter.","cn":"她伸手到桌子那头去拿黄油。"}},{"en":"to spread over an area of land","cn":"延伸；绵延","g":"[intransitive]","sc":"over area","ex":{"en":"Fields and hills stretched out as far as we could see.","cn":"放眼望去，田野山丘绵延不绝。"}},{"en":"to continue over a period of time","cn":"延续","g":"[intransitive]","sc":"over time","ex":{"en":"The town's history stretches back to before 1500.","cn":"该镇的历史可以上溯到公元 1500 年以前。"}},{"en":"to be enough to buy or pay for something","cn":"足够买（或支付）","g":"[intransitive]","sc":"money/supplies/time","ex":{"en":"I need a new car, but my savings won't stretch to it.","cn":"我需要一辆新车，但我的积蓄不够。"}},{"en":"to make use of a lot of your money, supplies, time, etc.","cn":"（大量地）使用，消耗","g":"[transitive]","sc":"money/supplies/time","ex":{"en":"The pandemic has stretched healthcare resources to the limit.","cn":"大流行使医疗资源达到极限。"}},{"en":"to increase your lead over somebody in a game or competition","cn":"（比赛中）扩大领先优势","g":"[transitive]","sc":"the lead","ex":{"en":"A minute later, Kelly stretched their lead to eight points.","cn":"一分钟后，凯莉把她们的领先优势扩大到了八分。"}},{"en":"to make use of all somebody’s skill, intelligence, etc.","cn":"使竭尽所能；使全力以赴；使发挥出全部本领","g":"[transitive]","sc":"somebody’s skill/intelligence","ex":{"en":"I need a job that will stretch me.","cn":"我需要一份能让我充分发挥才智的工作。"}},{"en":"to use something in a way that would not normally be considered fair, acceptable, etc.","cn":"滥用；随意歪曲","g":"[transitive]","sc":"truth/belief","ex":{"en":"He admitted that he had maybe stretched the truth a little (= not been completely honest).","cn":"他承认可能有点言过其实了。"}},{"en":"an area of land or water, especially a long one","cn":"一片；一泓；一段","g":"[countable]","sc":"area of land/water","ex":{"en":"a particularly dangerous stretch of road","cn":"特别危险的路段"},"pos":"noun"},{"en":"a continuous period of time","cn":"（连续的）一段时间","g":"[countable]","sc":"period of time","ex":{"en":"They worked in four-hour stretches.","cn":"他们工作四小时一班。"},"pos":"noun"},{"en":"a period of time that somebody spends in prison","cn":"服刑期","g":"[countable, usually singular]","lab":"informal","sc":"period of time","ex":{"en":"He did a ten-year stretch for fraud.","cn":"他因欺诈罪服刑十年。"},"pos":"noun"},{"en":"an act of stretching out your arms or legs or your body and pulling the muscles tight; the state of being stretched","cn":"伸展；舒展","g":"[countable, uncountable]","sc":"of body","ex":{"en":"We got out of the car and had a good stretch.","cn":"我们下车好好舒展了一下身体。"},"pos":"noun"},{"en":"the ability to be made longer or wider without breaking or tearing","cn":"弹性；伸缩性","g":"[uncountable]","sc":"of fabric","ex":{"en":"You need a material with plenty of stretch in it.","cn":"你需要一种弹性很大的布料。"},"pos":"noun"},{"en":"a straight part at the end of a racing track","cn":"（终点）直道","g":"[countable, usually singular]","lab":"figurative","sc":"on racetrack","ex":{"en":"the finishing stretch","cn":"最后的拉伸"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"延伸;绵延","en":"Something that stretches over an area or distance covers or exists in the whole of that area or distance.","ex":{"en":"The procession stretched for several miles","cn":"游行队伍长达数英里。"}},{"pos":"N-COUNT 可数名词","cn":"一片;一泓;一段","en":"A stretch of road, water, or land is a length or area of it.","ex":{"en":"It's a very dangerous stretch of road","cn":"这是一段非常危险的路。"}},{"pos":"VERB 动词","cn":"伸展;舒展","en":"When you stretch, you put your arms or legs out straight and tighten your muscles.","ex":{"en":"He yawned and stretched","cn":"他打了个呵欠，伸了伸懒腰。"}},{"pos":"N-COUNT 可数名词","cn":"一段时间","en":"A stretch of time is a period of time.","ex":{"en":"He was fluent in French, having spent stretches of time in Southern France.","cn":"他曾在法国南部呆过一段时间，法语流利。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)延续;(使)持续","en":"If an event or activity stretches or is stretched into a further period of time, it continues into that period, which is later than expected.","ex":{"en":"...as anti-abortion protests stretched into their second week","cn":"随着反堕胎抗议进入第二周"}},{"pos":"VERB 动词","cn":"(从一个时间)持续(至另一个时间)","en":"If something stretches from one time to another, it begins at the first time and ends at the second, which is longer than expected.","ex":{"en":"...a working day that stretches from seven in the morning to eight at night.","cn":"从早上 7 点持续到晚上 8 点的工作日"}},{"pos":"VERB 动词","cn":"包括;涉及;囊括","en":"If a group of things stretch from one type of thing to another, the group includes a wide range of things.","ex":{"en":"...a trading empire, with interests that stretched from chemicals to sugar.","cn":"从化学制品到食糖均有涉足的贸易帝国"}},{"pos":"V-ERG 及物/不及物动词","cn":"(把…)拉长;(把…)撑大;(把…)拉细","en":"When something soft or elastic stretches or is stretched, it becomes longer or bigger as well as thinner, usually because it is pulled.","ex":{"en":"The cables are designed not to stretch","cn":"该电缆不能拉伸。"}},{"pos":"ADJ 形容词","cn":"(织物)有弹性的，有弹力的","en":"Stretch fabric is soft and elastic and stretches easily.","ex":{"en":"...stretch fabrics such as Lycra.","cn":"莱卡等有弹性的织物"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)延长使用;节俭地使用","en":"If you stretch an amount of something or if it stretches, you make it last longer than it usually would by being careful and not wasting any of it.","ex":{"en":"They're used to stretching their budgets","cn":"他们习惯于精打细算。"}},{"pos":"VERB 动词","cn":"刚能够节约下来(或支付)","en":"If your resources can stretch to something, you can just afford to do it.","ex":{"en":"She suggested to me that I might like to start regular savings and I said Well, I don't know whether I can stretch to that.","cn":"她建议我可以开始定期存钱，我说我还不知道钱是不是够花呢。"}},{"pos":"VERB 动词","cn":"耗尽，竭尽(财力或物力)","en":"If something stretches your money or resources, it uses them up so you have hardly enough for your needs.","ex":{"en":"The drought there is stretching American resources","cn":"那里的旱灾正在耗尽美国的财力物力。"}},{"pos":"VERB 动词","cn":"使竭尽所能;使全力以赴;使拿出全部本领","en":"If you say that a job or task stretches you, you mean that you like it because it makes you work hard and use all your energy and skills so that you do not become bored or achieve less than you should.","ex":{"en":"I'm trying to move on and stretch myself with something different","cn":"我正想换工作，想尝试点不一样的事情来挑战一下自己。"}},{"pos":"PHRASE 短语","cn":"(通常指为够到某东西而)尽量伸长手臂","en":"If you are at full stretch, your arm is straight and extended as far as possible, usually because you are trying to reach something that is almost too far away.","ex":{"en":"He offered his lighter at full stretch.","cn":"他伸长胳膊把打火机递了过去。"}},{"pos":"PHRASE 短语","cn":"竭尽全力;全力以赴","en":"If you are at full stretch, you are using the maximum amount of effort or energy.","ex":{"en":"Everyone would be working at full stretch.","cn":"每个人都将全力以赴。"}},{"pos":"PHRASE 短语","cn":"任凭怎么想也(不);再怎么说也(不)","en":"If you say that something is not true or possible by any stretch of the imagination, you are emphasizing that it is completely untrue or absolutely impossible.","ex":{"en":"Her husband was not a womaniser by any stretch of the imagination","cn":"她老公绝对不是个拈花惹草的人。"}},{"pos":"PHRASE 短语","cn":"(久坐之后)散散步，活动活动腿脚","en":"If you stretch your legs, you go for a short walk, usually after you have been sitting down for a long time.","ex":{"en":"I stopped at the square and got out to stretch my legs.","cn":"我在广场处停下来，下车活动活动腿脚。"}},{"pos":"PHRASE 短语","cn":"牵强附会;勉强说得过去","en":"If you stretch a point, you describe something in a way which is not accurate, although it may be partly true.","ex":{"en":"It is stretching a point to call this censorship.","cn":"把这称为审查有点儿牵强。"}},{"pos":"","cn":"","en":"相关词组：stretch out"}]},"examples":[{"en":"We can't take on any more work — we're fully stretched as it is.","cn":"我们不能再接受其他工作了，现在我们已经满负荷了。"},{"en":"The town's history stretches back to before 1500.","cn":"该镇的历史可以上溯到公元 1500 年以前。"}]},"strive":{"oxford":{"phon":"straɪv","pos":"verb","senses":[{"en":"to try very hard to achieve something","cn":"努力；奋斗；力争；力求","ex":{"en":"We encourage all members to strive for the highest standards.","cn":"我们鼓励所有成员为达到最高标准而努力。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"努力;奋斗;力争;力求","en":"If you strive to do something or strive for something, you make a great effort to do it or get it.","ex":{"en":"He strives hard to keep himself very fit","cn":"他努力地保持身体健康。"}}]},"media":{"uk":"media/uk/strive__gb_1.mp3","us":"media/us/strive__us_1.mp3"},"examples":[{"en":"We encourage all members to strive for the highest standards.","cn":"我们鼓励所有成员为达到最高标准而努力。"},{"en":"Newspaper editors all strive to be first with a story.","cn":"报纸编辑都力争率先报道。"}]},"stealing":{"oxford":{"phon":"stiːl","pos":"verb","senses":[{"en":"to take sth from a person, shop/store, etc. without permission and without intending to return it or pay for it","cn":"偷；窃取"},{"en":"to move secretly and quietly so that other people do not notice you","cn":"偷偷地（或悄悄地）移动"}]},"media":{"uk":"media/uk/steal__gb_1.mp3","us":"media/us/steal__us_1.mp3"}},"stock":{"oxford":{"phon":"stɒk","pos":"noun","senses":[{"en":"a supply of goods that is available for sale in a shop","cn":"（商店的）现货，存货，库存","g":"[uncountable, countable]","lab":"especially British English","sc":"supply","ex":{"en":"We have a fast turnover of stock.","cn":"我们的货物周转快。"}},{"en":"a supply of something that is available for use","cn":"储备物；备用物；供应物","g":"[countable, uncountable]","sc":"supply","ex":{"en":"Food stocks are running low.","cn":"贮存的食物快吃完了。"}},{"en":"the value of the shares in a company that have been sold","cn":"股本；资本","g":"[uncountable]","sc":"finance","ex":{"en":"The company's stock hit an all-time high of $94.66.","cn":"该公司的股价创出了 94.66 美元的历史高点。"}},{"en":"a share that somebody has bought in a company or business","cn":"股份；股票","g":"[countable, usually plural]","lab":"British English","sc":"finance","ex":{"en":"stock prices","cn":"股票价格"}},{"en":"money that is lent to a government at a fixed rate of interest; an official document that gives details of this","cn":"公债；公债券","g":"[uncountable, countable]","lab":"British English","sc":"finance","ex":{"en":"government stock","cn":"政府债券"}},{"en":"farm animals, such as cows and sheep, that are kept for their meat, wool, etc.","cn":"家畜；牲畜","g":"[uncountable]","sc":"farm animals","ex":{"en":"breeding stock","cn":"种畜"}},{"en":"having the type of family or ancestors mentioned","cn":"家族；世系；出身","g":"[uncountable]","sc":"family/ancestors"},{"en":"a liquid made by cooking bones, meat, etc. in water, used for making soups and sauces","cn":"高汤；原汤","g":"[uncountable, countable]","sc":"food","ex":{"en":"vegetable stock","cn":"菜汤"}},{"en":"a wooden structure with holes for the feet, used in the past to lock criminals in as a form of punishment, especially in a public place","cn":"足枷","g":"[plural]","sc":"for punishment"},{"en":"the degree to which somebody is respected or liked by other people","cn":"名声；声望；评价","g":"[uncountable]","lab":"formal","sc":"respect","ex":{"en":"Their stock is high/low.","cn":"他们的声望高／低。"}},{"en":"the part of a gun that you hold against your shoulder when firing it","cn":"枪托","g":"[countable]","sc":"of gun"},{"en":"a garden plant with brightly coloured flowers with a sweet smell","cn":"紫罗兰","g":"[uncountable, countable]","sc":"plant"},{"en":"a theatre company that does several different plays in a season; a repertory company","cn":"保留剧目轮演剧团","g":"[countable]","lab":"North American English","sc":"theatre"},{"en":"to keep a supply of a particular type of goods to sell","cn":"存货","ex":{"en":"Do you stock green tea?","cn":"你们的库存有绿茶吗？"},"pos":"verb"},{"en":"to fill something with food, books, etc.","cn":"贮备，贮存（食物、书籍等）","g":"[often passive]","ex":{"en":"The pond was well stocked with fish.","cn":"池塘里养了许多鱼。"},"pos":"verb"},{"en":"a stock excuse, answer, etc. is one that is often used because it is easy and convenient, but that is not very original","cn":"老一套的；陈腐的","lab":"disapproving","ex":{"en":"‘No comment,’ was the actor's stock response.","cn":"“无可奉告。”那位演员回答什么问题都是这一句老话。"},"pos":"adjective"},{"en":"usually available for sale in a shop","cn":"（商店里）常备的，通常有的","ex":{"en":"stock sizes","cn":"常备尺码"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"股票;证券","en":"Stocks are shares in the ownership of a company, or investments on which a fixed amount of interest will be paid.","ex":{"en":"...the buying and selling of stocks and shares","cn":"证券和股票买卖"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(公司的)股本，股份","en":"A company's stock is the amount of money which the company has through selling shares.","ex":{"en":"Two years later, when Compaq went public, their stock was valued at $38 million","cn":"康柏公司两年后上市时，他们的股本为 3,800 万美元。"}},{"pos":"VERB 动词","cn":"(商店)存(货)，储备","en":"If a shop stocks particular goods, it keeps a supply of them to sell.","ex":{"en":"The shop stocks everything from cigarettes to recycled loo paper.","cn":"商店货品齐全，从香烟到再生厕纸应有尽有。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(商店的)全部存货，库存","en":"A shop's stock is the total amount of goods which it has available to sell.","ex":{"en":"We took the decision to withdraw a quantity of stock from sale.","cn":"我们决定将一批存货下架。"}},{"pos":"VERB 动词","cn":"在…中储备(或贮存)","en":"If you stock something such as a cupboard, shelf, or room, you fill it with food or other things.","ex":{"en":"I worked stocking shelves in a grocery store","cn":"我在一家杂货店工作，负责为货架上货。"}},{"pos":"N-COUNT 可数名词","cn":"贮存;储备","en":"If you have a stock of things, you have a supply of them stored in a place ready to be used.","ex":{"en":"I keep a stock of cassette tapes describing various relaxation techniques","cn":"我收集了一些介绍各种放松技巧的卡带。"}},{"pos":"N-SING 单数名词","cn":"供应量;储备量;现有量","en":"The stock of something is the total amount of it that is available in a particular area.","ex":{"en":"...the stock of accommodation available to be rented.","cn":"可供租赁的住房储备量"}},{"pos":"N-UNCOUNT 不可数名词","cn":"出身;种族;家系","en":"If you are from a particular stock, you are descended from a particular group of people.","ex":{"en":"We are both from working class stock.","cn":"我们俩都出身于工人家庭。"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指经过特殊饲养的)家畜，牲畜","en":"Stock are cattle, sheep, pigs, or other animals which are kept by a farmer, usually ones which have been specially bred.","ex":{"en":"I am carefully selecting the breeding stock","cn":"我正在精心挑选种畜。"}},{"pos":"ADJ 形容词","cn":"(回答、说法或做事方式)老一套的，陈腐的","en":"A stock answer, expression, or way of doing something is one that is very commonly used, especially because people cannot be bothered to think of something new.","ex":{"en":"My boss had a stock response — 'If it ain't broke, don't fix it!'","cn":"我上司总是这一句——“别没事找事！”"}},{"pos":"N-MASS 物质名词","cn":"高汤;原汤","en":"Stock is a liquid, usually made by boiling meat, bones, or vegetables in water, that is used to give flavour to soups and sauces."},{"pos":"N-PLURAL 复数名词","cn":"(旧时惩罚犯人用的)手足枷","en":"In former times, the stocks were an instrument of punishment. A criminal's hands and legs were locked into holes in a wooden frame while people threw things at them."},{"pos":"PHRASE 短语","cn":"有货/缺货","en":"If goods are in stock, a shop has them available to sell. If they are out of stock, it does not.","ex":{"en":"Check that your size is in stock","cn":"查查你的尺码是否有货。"}},{"pos":"PHRASE 短语","cn":"作出整体估量;全面分析","en":"If you take stock, you pause to think about all the aspects of a situation or event before deciding what to do next.","ex":{"en":"It was time to take stock of the situation","cn":"是时候统观一下形势了。"}},{"pos":"","cn":"","en":"lock, stock, and barrel→see: ;"},{"pos":"","cn":"","en":"相关词组：stock up"}]},"media":{"uk":"media/uk/stock__gb_1.mp3","us":"media/us/stock__us_1.mp3"},"examples":[{"en":"‘No comment,’ was the actor's stock response. “","cn":"无可奉告。”那位演员回答什么问题都是这一句老话。"},{"en":"Our new model is already on the stocks and will be available in the spring.","cn":"我们已着手生产新的款式，明年春天就可以上市。"}]},"star":{"oxford":{"phon":"stɑː(r)","pos":"noun","senses":[{"en":"a large ball of burning gas in space that we see as a point of light in the sky at night","cn":"恒星；星","g":"[countable]","sc":"in sky","ex":{"en":"There was a big moon and hundreds of stars were shining overhead.","cn":"头顶是一轮明月和成百上千颗闪烁的星星。"}},{"en":"an object, a decoration, a mark, etc., usually with five or six points, whose shape represents a star","cn":"星状物；星形饰物；星号","g":"[countable]","sc":"shape","ex":{"en":"a horse with a white star on its forehead","cn":"前额有一块星形白斑的马"}},{"en":"a mark that represents a star and tells you how good something is, especially a hotel or restaurant","cn":"（尤指旅馆或餐馆的）星级","g":"[countable, usually singular]","sc":"mark of quality","ex":{"en":"three-/four-/five-star hotels","cn":"三／四／五星级饭店"}},{"en":"a famous and excellent singer, performer, sports player, etc.","cn":"歌唱（或表演）明星；体坛高手；才华出众者","g":"[countable]","sc":"performer","ex":{"en":"pop/rock/Hollywood/TV stars","cn":"流行音乐歌星；摇滚歌星；好莱坞影星；电视明星"}},{"en":"a person who has the main part, or one of the main parts, in a film, play, etc.","cn":"（电影、戏剧等的）主角，主演","g":"[countable]","sc":"performer","ex":{"en":"The star of the show was a young Italian singer.","cn":"那台节目的主角是位年轻的意大利歌唱家。"}},{"en":"a person or thing that is the best of a group","cn":"最优秀（或出色、成功）者","g":"[countable]","sc":"best of group","ex":{"en":"a star student","cn":"最优秀的学生"}},{"en":"used to show that you feel very grateful for something that somebody has done or that you think they are wonderful","cn":"（表示万分感激或赞叹）","g":"[countable, usually singular]","lab":"informal","sc":"helpful person","ex":{"en":"Thanks! You're a star!","cn":"多谢多谢！你真是个大好人！"}},{"en":"a description of what somebody thinks is going to happen to somebody in the future, based on the position of the stars and planets when they were born","cn":"星象（根据人出生时天体的位置而描述的命运）","g":"[plural]","sc":"influence on somebody’s future","ex":{"en":"Do you read your stars in the paper?","cn":"你读不读报上的星座运程，看自己的运气如何？"}},{"en":"to have one of the main parts in a film, play, etc.","cn":"主演；担任主角","g":"[intransitive]","lab":"British English","sc":"perform in movie/play","ex":{"en":"He starred in that movie about the crazy professor.","cn":"他主演了一部关于疯狂教授的电影。"},"pos":"verb"},{"en":"if a film, play, etc. stars somebody, that person has one of the main parts","cn":"使主演；由…担任主角","g":"[transitive, no passive]","sc":"perform in movie/play","ex":{"en":"a movie starring Jennifer Lawrence and Chris Pratt","cn":"由詹妮弗·劳伦斯和克里斯·普拉特主演的电影"},"pos":"verb"},{"en":"to put a symbol with a shape like a star (= an asterisk) next to a word, etc. in order to make people notice it","cn":"给…标星号","g":"[transitive, usually passive]","sc":"mark with symbol","ex":{"en":"Treat all the sections that have been starred as priority.","cn":"优先处理所有标星号的部分。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"星;恒星","en":"A star is a large ball of burning gas in space. Stars appear to us as small points of light in the sky on clear nights.","ex":{"en":"The night was dark, the stars hidden behind cloud.","cn":"夜很黑，星星都躲在云的后面。"}},{"pos":"N-COUNT 可数名词","cn":"星状;星形物","en":"You can refer to a shape or an object as a star when it has four, five, or more points sticking out of it in a regular pattern.","ex":{"en":"Children at school receive coloured stars for work well done.","cn":"学校里的孩子表现得好会得到彩色星星。"}},{"pos":"N-COUNT 可数名词","cn":"(饭店、宾馆等的)星级标志","en":"You can say how many stars something such as a hotel or restaurant has as a way of talking about its quality, which is often indicated by a number of star-shaped symbols. The more stars something has, the better it is.","ex":{"en":"...five star hotels.","cn":"五星级宾馆"}},{"pos":"N-COUNT 可数名词","cn":"明星","en":"Famous actors, musicians, and sports players are often referred to as stars .","ex":{"en":"...Gemma, 41, star of the TV series Pennies From Heaven","cn":"杰玛，41 岁，电视连续剧《飞来横财》中的明星"}},{"pos":"VERB 动词","cn":"(在戏剧或电影中)担任主角，主演","en":"If an actor or actress stars in a play or film, he or she has one of the most important parts in it.","ex":{"en":"The previous year Adolphson had starred in a play in which Ingrid had been an extra","cn":"上一年，阿道夫森在一部戏剧里担任主角，当时英格丽在剧中还只是个临时演员。"}},{"pos":"VERB 动词","cn":"(戏剧或电影)由…主演","en":"If a play or film stars a famous actor or actress, he or she has one of the most important parts in it.","ex":{"en":"...the BBC's new satirical show, That Was The Week That Was, which starred David Frost.","cn":"由戴维·弗罗斯特主持的英国广播公司新讽刺节目《那一周》"}},{"pos":"N-PLURAL 复数名词","cn":"(报纸、杂志上登载的)星象","en":"Predictions about people's lives which are based on astrology and appear regularly in a newspaper or magazine are sometimes referred to as the stars .","ex":{"en":"There was nothing in my stars to say I'd have travel problems!","cn":"我的星象预测中没有说我会在旅行中遇到麻烦！"}},{"pos":"PHRASE 短语","cn":"多亏运气好","en":"If you say that someone should thank their lucky stars that something is the case, you mean that they should be very grateful that it is the case, because otherwise their situation would be a lot worse.","ex":{"en":"Thank your lucky stars you're out of London.","cn":"你不在伦敦真是走运了。"}}]},"media":{"uk":"media/uk/star__gb_1.mp3","us":"media/us/star__us_1.mp3"},"examples":[{"en":"The studio wants to star her in a sequel to last year's hit.","cn":"制片厂为去年一部大获成功的影片筹拍续集，想聘她担任主角。"},{"en":"She starred opposite Cary Grant in ‘Bringing up Baby’.","cn":"她和加利 · 格兰特在《育婴奇谭》中联袂出演男女主角。"}]},"stroke":{"media":{"uk":"media/uk/stroke__gb_1.mp3","us":"media/us/stroke__us_1.mp3","img":["media/ldoce/img/stroke.jpg"]},"oxford":{"phon":"strəʊk","pos":"noun","senses":[{"en":"an act of hitting a ball, for example with a bat or racket","cn":"击球（动作）","g":"[countable]","sc":"hitting movement","ex":{"en":"What a beautiful stroke!","cn":"击球动作多漂亮呀！"}},{"en":"a single movement of the arm when hitting somebody/something","cn":"（打、击等的）一下，一击","g":"[countable]","sc":"hitting movement","ex":{"en":"His punishment was six strokes of the cane.","cn":"给他的惩罚是挨六教鞭。"}},{"en":"a single successful action or event","cn":"（成功的）举动；（高明的）举措；（巧妙的）办法；（成功的）事情","g":"[countable]","sc":"action","ex":{"en":"Your idea was a stroke of genius.","cn":"你的主意很高明。"}},{"en":"a sudden serious illness when a blood vessel (= tube) in the brain bursts (= breaks open) or is blocked, which can cause death or the loss of the ability to move or to speak clearly","cn":"脑卒中；中风","g":"[countable, uncountable]","sc":"illness","ex":{"en":"to have/suffer a stroke","cn":"患中风"}},{"en":"any of a series of repeated movements in swimming or rowing","cn":"划水动作；划桨动作","g":"[countable]","sc":"in swimming/rowing","ex":{"en":"She took a few more strokes to reach the bank.","cn":"她又划几下，游到了岸边。"}},{"en":"a style of swimming","cn":"游泳姿势","g":"[countable]","sc":"in swimming/rowing","ex":{"en":"Butterfly is the only stroke I can't do.","cn":"只有蝶泳我不会。"}},{"en":"the person who sets the speed at which everyone in a boat rows","cn":"（指挥船上其他桨手的）尾桨手","g":"[countable]","sc":"in swimming/rowing"},{"en":"an act of moving your hand gently over a surface, usually several times","cn":"轻抚；抚摩","g":"[countable, usually singular]","lab":"especially British English","sc":"gentle touch","ex":{"en":"He gave the cat a stroke.","cn":"他抚摩了一下猫。"}},{"en":"a mark made by moving a pen, brush, etc. once across a surface","cn":"一笔；一画；笔画","g":"[countable]","lab":"figurative","sc":"of pen/brush","ex":{"en":"to paint with fine brush strokes","cn":"一小刷一小刷地刷漆"}},{"en":"each of the sounds made by a clock or bell giving the hours","cn":"钟声；鸣；敲","g":"[countable]","sc":"of clock","ex":{"en":"At the first stroke it will be 9 o'clock exactly.","cn":"等到钟敲第一下时就是 9 点整。"}},{"en":"to move your hand gently and slowly over an animal’s fur or hair","cn":"轻抚，抚摩（动物的毛皮）","lab":"especially British English","sc":"touch gently","ex":{"en":"He's a beautiful dog. Can I stroke him?","cn":"这只狗真漂亮，我可以摸一摸吗？"},"pos":"verb"},{"en":"to move your hand gently over a surface, somebody’s hair, etc.","cn":"轻抚，抚摩（物体表面或头发等）","sc":"touch gently","ex":{"en":"He stroked her hair affectionately.","cn":"他深情地抚摩着她的头发。"},"pos":"verb"},{"en":"to move something somewhere with a gentle movement","cn":"轻挪；轻触；轻拭","sc":"move something gently","ex":{"en":"She stroked away his tears.","cn":"她轻轻拭去他的眼泪。"},"pos":"verb"},{"en":"to be very nice to somebody, especially to get them to do what you want","cn":"待（某人）非常好；（尤指）顺着（某人）以便为自己办事","lab":"especially North American English, informal，，","sc":"be nice to somebody","pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"轻抚;抚摩","en":"If you stroke someone or something, you move your hand slowly and gently over them.","ex":{"en":"Carla, curled up on the sofa, was smoking a cigarette and stroking her cat","cn":"卡拉正蜷缩在沙发上，一边吸着烟，一边轻抚着她的猫咪。"}},{"pos":"N-COUNT 可数名词","cn":"中风;脑卒中","en":"If someone has a stroke, a blood vessel in their brain bursts or becomes blocked, which may kill them or make them unable to move one side of their body.","ex":{"en":"He had a minor stroke in 1987, which left him partly paralysed.","cn":"他 1987 年曾患轻度中风，之后就半身不遂了。"}},{"pos":"N-COUNT 可数名词","cn":"(铅笔、刷子的)一笔，一挥，笔画","en":"The strokes of a pen or brush are the movements or marks that you make with it when you are writing or painting.","ex":{"en":"Fill in gaps by using short, upward strokes of the pencil.","cn":"用铅笔向上短短地勾画几道来填充空白。"}},{"pos":"N-COUNT 可数名词","cn":"划水动作;划桨动作;(游泳或划船的)一次划水","en":"When you are swimming or rowing, your strokes are the repeated movements that you make with your arms or the oars.","ex":{"en":"I turned and swam a few strokes further out to sea","cn":"我转身向海里又游了几下。"}},{"pos":"N-COUNT 可数名词","cn":"游泳姿势;游法","en":"A swimming stroke is a particular style or method of swimming.","ex":{"en":"She spent hours practising the breast stroke.","cn":"她花了数小时练习蛙泳。"}},{"pos":"N-COUNT 可数名词","cn":"钟声;鸣;敲","en":"The strokes of a clock are the sounds that indicate each hour.","ex":{"en":"On the stroke of 12, fireworks suddenly exploded into the night.","cn":"12 点的钟声刚敲响，焰火便在夜空中绽放。"}},{"pos":"N-COUNT 可数名词","cn":"击球(动作);一击;一抽","en":"In sports such as tennis, baseball, cricket, and golf, a stroke is the action of hitting the ball.","ex":{"en":"Compton was sending the ball here, there, and everywhere with each stroke.","cn":"康普顿一会将球打到这里，一会打到那里，每一拍的落点都不同。"}},{"pos":"N-SING 单数名词","cn":"一件(幸运的)事","en":"A stroke of luck or good fortune is something lucky that happens.","ex":{"en":"It didn't rain, which turned out to be a stroke of luck.","cn":"天没下雨，结果成了件幸事。"}},{"pos":"N-SING 单数名词","cn":"(灵感的)突发;(天才的)一举","en":"A stroke of genius or inspiration is a very good idea that someone suddenly has.","ex":{"en":"At the time, his appointment seemed a stroke of genius.","cn":"当时，对他的任命犹如神来之笔。"}},{"pos":"PHRASE 短语","cn":"一下子;一举","en":"If something happens at a stroke or in one stroke, it happens suddenly and completely because of one single action.","ex":{"en":"The disease wiped out 40 million rabbits at a stroke","cn":"该疾病一下子就使 4,000 万只兔子丧命。"}},{"pos":"PHRASE 短语","cn":"动一动;干一点","en":"If someone does not do a stroke of work, they are very lazy and do no work at all.","ex":{"en":"I never did a stroke of work at college.","cn":"我在上大学时懒得要命。"}}]},"examples":[{"en":"At the stroke of a pen (= by signing sth) they removed thousands of people from the welfare system.","cn":"他们大笔一挥，就把成千上万的人排除在福利制度之外。"},{"en":"It was a bold stroke to reveal the identity of the murderer on the first page.","cn":"在头版上披露谋杀犯的身分，这是一个大胆的举措。"}]},"stressful":{"media":{"uk":"media/uk/stressful__gb_1.mp3","us":"media/us/stressful__us_1.mp3"},"oxford":{"phon":"ˈstresfl","pos":"adjective","senses":[{"en":"causing a lot of worry","cn":"压力重的；紧张的","ex":{"en":"a stressful job","cn":"造成沉重压力的工作"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(状况、经历)压力大的，令人紧张的","en":"If a situation or experience is stressful, it causes the person involved to feel stress.","ex":{"en":"I think I've got one of the most stressful jobs there is.","cn":"我想我得到的这份工作是其中最繁重的工作之一。"}}]},"examples":[{"en":"It was a stressful time for all of us.","cn":"对我们所有人来说，那是一段艰难的时期。"},{"en":"a stressful job","cn":"造成沉重压力的工作"}]},"stunning":{"media":{"uk":"media/uk/stunning__gb_1.mp3","us":"media/us/stunning__us_1.mp3"},"oxford":{"phon":"ˈstʌnɪŋ","pos":"adjective","senses":[{"en":"extremely attractive or impressive","cn":"极有魅力的；绝妙的；给人以深刻印象的","ex":{"en":"You look absolutely stunning!","cn":"你看上去漂亮极了！"}},{"en":"that surprises or shocks you very much","cn":"令人震惊的；极不寻常的","ex":{"en":"He suffered a stunning defeat in the election.","cn":"他在选举中惨败。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极有魅力的;给人以深刻印象的;绝妙的","en":"A stunning person or thing is extremely beautiful or impressive.","ex":{"en":"She was 55 and still a stunning woman","cn":"她已经 55 岁了，但依然美艳动人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人惊奇万分的;令人震惊的;极不寻常的","en":"A stunning event is extremely unusual or unexpected.","ex":{"en":"The minister resigned last night after a stunning defeat in Sunday's vote","cn":"在周日的选举中意外惨败后，部长于昨晚辞职。"}}]},"examples":[{"en":"You look absolutely stunning!","cn":"你看上去漂亮极了！"},{"en":"a stunning view of the lake","cn":"无比优美的湖光水色"}]},"stylus":{"media":{"uk":"media/uk/stylus__gb_1.mp3","us":"media/us/stylus__us_1.mp3"},"oxford":{"phon":"ˈstaɪləs","pos":"noun","senses":[{"en":"a device on a record player that looks like a small needle and is placed on the record in order to play it","cn":"（唱机的）唱针"},{"en":"a special pen used to write text or draw an image on a special computer screen","cn":"触控笔（用以在电脑屏幕上书写、画画等）","lab":"computing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(唱机的)唱针","en":"The stylus on a record player is the small needle that picks up the sound signals on the records."},{"pos":"N-COUNT 可数名词","cn":"(计算机的)手写笔，触笔","en":"A stylus is a device like a pen with which you can input written text or drawing directly into a computer.","ex":{"en":"It has a stylus-operated on-screen keyboard that takes great skill to master.","cn":"它有触笔屏幕键盘，需要使用者掌握很高的技巧。"}}]}},"stages":{"oxford":{"phon":"steɪdʒ","pos":"noun","senses":[{"en":"a period or state that sth/sb passes through while developing or making progress （","cn":"发展或进展的）时期，阶段，状态"},{"en":"a separate part that a process, etc. is divided into","cn":"段；步；步骤"}]},"media":{"uk":"media/uk/stage__gb_1.mp3","us":"media/us/stage__us_1.mp3"}},"stuffed":{"media":{"uk":"media/uk/stuffed__gb_1.mp3","us":"media/us/stuffed__us_1.mp3"},"oxford":{"phon":"stʌft","pos":"adjective","senses":[{"en":"having eaten so much that you cannot eat anything else","cn":"饱","ex":{"en":"I couldn’t eat another thing. I’m absolutely stuffed.","cn":"我再也吃不下了，我真的饱了。"}}]},"examples":[{"en":"No, no dessert – I’m stuffed.","cn":"不﹐不要甜点了﹐我吃饱了。"}]},"steered":{"oxford":{"phon":"stɪə(r)","pos":"verb","senses":[{"en":"to control the direction in which a boat, car, etc. moves","cn":"驾驶（船、汽车等）；掌方向盘"},{"en":"to move in a particular direction","cn":"行驶"}]}},"sturdily":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easily broken or damaged","cn":""},{"en":"strong – used especially about something that can be used a lot without damaging it or making it weaker","cn":""}]},"examples":[{"en":"That chair doesn’t look very sturdy.","cn":"","src":"ld"},{"en":"They kept up a sturdy opposition to the plan.","cn":"","src":"ld"}],"media":{"uk":"media/uk/sturdily__gb_1.mp3","us":"media/us/sturdily__us_1.mp3"},"oxford":{"phon":"ˈstɜːdɪli","pos":"adverb","senses":[{"en":"strong and not easily damaged","cn":"结实的；坚固的","ex":{"en":"The boat was sturdily made.","cn":"这艘船打造得很坚实。"}},{"en":"a sturdily built person is physically strong and not very tall or thin","cn":"结实：一个结实的人身体强壮，不是很高或瘦弱","ex":{"en":"a sturdily built young man","cn":"体格健壮的年轻男子"}},{"en":"in a way that is not easily influenced or changed by other people","cn":"坚决的；坚定的；顽强的","ex":{"en":"a sturdily independent community","cn":"坚定独立的社区"}}]}},"stuff":{"media":{"uk":"media/uk/stuff__gb_1.mp3","us":"media/us/stuff__us_1.mp3"},"oxford":{"phon":"stʌf","pos":"noun","senses":[{"en":"used to refer to a substance, material, group of objects, etc. when you do not know the name, when the name is not important or when it is obvious what you are talking about","cn":"（事物名称不详、无关紧要或所指事物明显时用）东西，物品，玩意儿","lab":"informal","ex":{"en":"What's all that sticky stuff on the carpet?","cn":"地毯上那黏乎乎的都是什么玩意儿？"}},{"en":"used to refer in a general way to things that people do, say, think, etc.","cn":"（泛指）活儿，话，念头，东西","lab":"informal","ex":{"en":"Peter's article had lots of interesting stuff in it.","cn":"彼得的文章中有很多有趣的内容。"}},{"en":"the most important feature of something; something that something else is based on or is made from","cn":"基本特征；特质；根本；基础；原料","lab":"formal or literary","ex":{"en":"The trip was magical; the stuff of which dreams are made.","cn":"那次旅行很奇妙，宛如梦境。"}},{"en":"to fill a space or container tightly with something","cn":"填满；装满；塞满；灌满","ex":{"en":"She had 500 envelopes to stuff with leaflets.","cn":"她得在 500 个信封里装上传单。"},"pos":"verb"},{"en":"to push something quickly and carelessly into a small space","cn":"把…塞进（或填进）","ex":{"en":"She stuffed the money under a cushion.","cn":"她把钱塞到软垫底下。"},"pos":"verb"},{"en":"to fill a vegetable, chicken, etc. with another type of food","cn":"在（蔬菜、鸡等）里填入（另外一种食物）；给…装馅","ex":{"en":"Are you going to stuff the turkey?","cn":"你打算给火鸡加填料吗？"},"pos":"verb"},{"en":"to eat a lot of food or too much food; to give somebody a lot or too much to eat","cn":"（使）吃撑，吃足，吃得过饱","lab":"informal","ex":{"en":"He sat at the table stuffing himself.","cn":"他坐在桌前大吃大嚼。"},"pos":"verb"},{"en":"to fill the dead body of an animal with material and preserve it, so that it keeps its original shape and appearance","cn":"制作（动物）标本","g":"[usually passive]","ex":{"en":"They had had their pet dog stuffed.","cn":"他们请人把他们的宠物狗制成了标本。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(泛指的)东西，物品，玩意儿","en":"You can use stuff to refer to things such as a substance, a collection of things, events, or ideas, or the contents of something in a general way without mentioning the thing itself by name.","ex":{"en":"I'd like some coffee, and I don't object to the powdered stuff if it's all you've got","cn":"我想来点咖啡，如果你只有速溶的那种也可以。"}},{"pos":"VERB 动词","cn":"把…塞进(或填进)","en":"If you stuff something somewhere, you push it there quickly and roughly.","ex":{"en":"I stuffed my hands in my pockets","cn":"我把手插进口袋里。"}},{"pos":"VERB 动词","cn":"填满;装满;塞满","en":"If you stuff a container or space with something, you fill it with something or with a quantity of things until it is full.","ex":{"en":"He grabbed my purse, opened it and stuffed it full, then gave it back to me","cn":"他抢过我的钱包，打开并塞满钱，然后还给了我。"}},{"pos":"VERB 动词","cn":"(使)吃撑;(使)吃足;(使)吃得过饱","en":"If you stuff yourself, you eat a lot of food.","ex":{"en":"I could stuff myself with ten chocolate bars and half an hour later eat a big meal.","cn":"我可以一口气吃10块巧克力，半小时后再吃一顿大餐。"}},{"pos":"VERB 动词","cn":"给…装馅儿;给(鸡、辣椒等食物里)加填料","en":"If you stuff a bird such as a chicken or a vegetable such as a pepper, you put a mixture of food inside it before cooking it.","ex":{"en":"Will you stuff the turkey and shove it in the oven for me?","cn":"你能帮我给火鸡填上料然后放进烤箱里吗？"}},{"pos":"VERB 动词","cn":"将(动物)制作成标本","en":"If a dead animal is stuffed, it is filled with a substance so that it can be preserved and displayed.","ex":{"en":"A pike weighing 29 lb 8 oz taken in 1878 was stuffed and is on display at the estate office","cn":"一条 1878 年捕获的重 29 磅 8 盎司的梭子鱼被制成标本陈列在庄园管理处。"}},{"pos":"N-SING 单数名词","cn":"基本特征;特质;根本;基础","en":"If you say that one thing is the stuff of another, you mean that the first thing is a very important feature or characteristic of the second thing, or that the second thing can be based or built on the first thing.","ex":{"en":"The idea that we can be whatever we want has become the stuff of television commercials.","cn":"每个人皆无所不能，这一理念已经成为电视广告的精髓。"}},{"pos":"EXCLAM 感叹语","cn":"滚开;去你的;别烦我","en":"If you are angry with someone for something that they have said or done, you might say 'Get stuffed!' to them."},{"pos":"VERB 动词","cn":"(用在名词前表示强调)不稀罕，不在乎","en":"Stuff is used in front of nouns to emphasize that you do not care about something, or do not want it.","ex":{"en":"Ultimately my attitude was: stuff them","cn":"我最终的态度是：去他们的。"}},{"pos":"PHRASE 短语","cn":"露一手;施展自己的本事","en":"If you do your stuff, you perform an activity in the way that people expect.","ex":{"en":"Once I get on the pitch I know I can do my stuff","cn":"我一上场就知道是我大显身手的时候了。"}},{"pos":"PHRASE 短语","cn":"很内行;精通;懂行","en":"If you say that someone knows their stuff, you mean that they are good at doing something because they know a lot about it.","ex":{"en":"These chaps know their stuff after seven years of war.","cn":"7年的战争过后，这些家伙都成了作战行家。"}},{"pos":"","cn":"","en":"to strut your stuff→see: ;"}]},"examples":[{"en":"I didn't want a part in the play, then I thought — stuff it — why not?","cn":"我本来没想在剧中扮演角色，然后又一想，管它呢！干吗不演？"},{"en":"What's all this ‘Mrs Smith’ stuff? Call me Anna.","cn":"哪来的什么“史密斯夫人”那一套？叫我安娜就好了。"}]},"standard":{"media":{"uk":"media/uk/standard__gb_1.mp3","us":"media/us/standard__us_1.mp3"},"oxford":{"phon":"ˈstændəd","pos":"noun","senses":[{"en":"a level of quality, especially one that people think is acceptable","cn":"（品质的）标准，水平，规格，规范","g":"[countable, uncountable]","sc":"level of quality","ex":{"en":"There has been a fall in living standards.","cn":"生活水平有所下降。"}},{"en":"a level of quality that is normal or acceptable for a particular person or in a particular situation","cn":"正常的水平；应达到的标准","g":"[countable, usually plural]","sc":"level of quality","ex":{"en":"You'd better lower your standards if you want to find somewhere cheap to live.","cn":"要想找个便宜的地方住，你最好降低要求。"}},{"en":"a level of behaviour that somebody considers to be morally acceptable","cn":"行为标准；道德水准","g":"[plural]","sc":"level of behaviour","ex":{"en":"a man of high moral standards","cn":"道德水准高的人"}},{"en":"a unit of measurement that is officially used; an official rule used when producing something","cn":"法定度量衡标准；法定含量；技术规范；产品规格","g":"[countable]","sc":"unit of measurement","ex":{"en":"a reduction in the weight standard of silver coins","cn":"银币法定重量标准的降低"}},{"en":"a flag that is used during official ceremonies, especially one connected with a particular military group","cn":"仪式上使用的旗帜；（尤指）军旗","g":"[countable]","sc":"flag","ex":{"en":"the royal standard","cn":"王旗。"}},{"en":"a song that has been recorded by many different singers","cn":"（很多歌手录制过的）经典曲目","g":"[countable]","sc":"song"},{"en":"average or normal rather than having special or unusual features","cn":"普通的；正常的；通常的；标准的","sc":"average/normal","ex":{"en":"the standard rate of tax (= paid by everyone)","cn":"标准税率"},"pos":"adjective"},{"en":"following a particular standard set, for example, by an industry","cn":"（符合）标准的；按一定规格制作的","sc":"size/measurement","ex":{"en":"standard sizes of clothes","cn":"服装的标准尺寸"},"pos":"adjective"},{"en":"read by most people who are studying a particular subject","cn":"权威性的","g":"[only before noun]","sc":"book/writer","ex":{"en":"the author of the standard textbook on the topic","cn":"该主题标准教科书的作者"},"pos":"adjective"},{"en":"believed to be correct and used by most people","cn":"标准的；规范的","g":"[usually before noun]","sc":"language","ex":{"en":"Standard English","cn":"规范的英语"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指合格的)水平，水准","en":"A standard is a level of quality or achievement, especially a level that is thought to be acceptable.","ex":{"en":"The standard of professional cricket has never been lower","cn":"职业板球的水平从来没有这么低过。"}},{"pos":"N-COUNT 可数名词","cn":"(用以衡量质量的)标准，基准","en":"A standard is something that you use in order to judge the quality of something else.","ex":{"en":"...systems that were by later standards absurdly primitive.","cn":"以后来的标准来衡量显得非常原始的系统"}},{"pos":"N-PLURAL 复数名词","cn":"道德准则;行为规范","en":"Standards are moral principles which affect people's attitudes and behaviour.","ex":{"en":"My father has always had high moral standards.","cn":"我父亲一直具有很高的道德准则。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"普通的;常规的","en":"You use standard to describe things which are usual and normal.","ex":{"en":"It was standard practice for untrained clerks to advise in serious cases such as murder","cn":"让未经过训练的书记员在诸如谋杀等重大案件中提供建议是普遍的做法。"}},{"pos":"ADJ 形容词","cn":"(作品等)受广泛阅读的，最受推崇的，最具权威性的","en":"A standard work or text on a particular subject is one that is widely read and often recommended."}]},"examples":[{"en":"He failed to reach the required standard , and did not qualify for the race.","cn":"他未能达到所要求的标准，因而不具备参赛资格。"},{"en":"It is standard practice to search visitors as they enter the building.","cn":"对进入这栋建筑物的来访者进行搜查是例行做法。"}]},"steadfastness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing to support a person, party, belief etc for a long time","cn":""},{"en":"supporting a particular person, party, set of beliefs, etc – used especially about someone you can can trust and depend on to support you","cn":""}]},"examples":[{"en":"her father’s steadfast love for her","cn":"","src":"ld"},{"en":"Dr Faraday remained steadfast in his plea of innocence.","cn":"","src":"ld"}],"media":{"uk":"media/uk/steadfastness__gb_1.mp3","us":"media/us/steadfastness__us_1.mp3"},"oxford":{"phon":"ˈstedfɑːstnəs","pos":"noun","senses":[{"en":"the quality of not changing in your attitudes or aims","cn":"坚定的；不动摇的","ex":{"en":"their steadfastness in the face of adversity","cn":"他们面对逆境的坚定"}}]}},"stature":{"media":{"uk":"media/uk/stature__gb_1.mp3","us":"media/us/stature__us_1.mp3"},"oxford":{"phon":"ˈstætʃə(r)","pos":"noun","senses":[{"en":"the importance and respect that a person has because of their ability and achievements","cn":"声望；名望","ex":{"en":"She was an actress of considerable stature.","cn":"她是一位颇具地位的女演员。"}},{"en":"a person’s height","cn":"身高；个子","ex":{"en":"a woman of short stature","cn":"身材矮小的女人"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"身高;个子","en":"Someone's stature is their height.","ex":{"en":"It's more than his physical stature that makes him remarkable","cn":"他的与众不同之处不光是他的身高。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"地位;声望","en":"The stature of a person is the importance and reputation that they have.","ex":{"en":"Who can deny his stature as the world's greatest cellist?","cn":"谁能否认他是世界上最伟大的大提琴演奏家呢？"}}]},"examples":[{"en":"The orchestra has grown in stature.","cn":"这支管弦乐队的声望有所提高。"},{"en":"He is small in stature.","cn":"他个头小。"}]},"sticky":{"media":{"uk":"media/uk/sticky__gb_1.mp3","us":"media/us/sticky__us_1.mp3"},"oxford":{"phon":"ˈstɪki","pos":"adjective","senses":[{"en":"made of or covered in a substance that sticks to things that touch it","cn":"黏（性）的","ex":{"en":"sticky fingers covered in jam","cn":"粘满果酱的黏糊糊的手指"}},{"en":"with glue (= a sticky substance) on one side so that you can stick it to a surface","cn":"一面带黏胶的","ex":{"en":"sticky tape","cn":"透明胶带"}},{"en":"hot and slightly wet","cn":"闷热的","lab":"informal","ex":{"en":"a sticky, humid afternoon","cn":"一个粘稠潮湿的下午"}},{"en":"feeling hot and uncomfortable","cn":"感到热得难受的","lab":"informal","ex":{"en":"She felt hot and sticky after six hours on the bus.","cn":"坐了六个小时后，她感到又热又粘。"}},{"en":"difficult or unpleasant","cn":"难办的；棘手的；让人为难的","lab":"informal","ex":{"en":"I always seem to get into sticky situations on holiday.","cn":"我好像总是在假期里陷入窘境。"}},{"en":"so interesting and well organized that the people who visit it stay there for a long time","cn":"用户黏着度高的；富有吸引力的","lab":"computing"},{"en":"a small piece of sticky paper that you use for writing a note on, and that can be easily removed","cn":"告事贴","ex":{"en":"Never write your password on a sticky note!","cn":"千万不要将密码写到便利贴上！"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"黏性的;涂有黏性物质的","en":"A sticky substance is soft, or thick and liquid, and can stick to other things. Sticky things are covered with a sticky substance.","ex":{"en":"...sticky toffee","cn":"黏牙的太妃糖"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(情况)棘手的，令人为难的","en":"A sticky situation involves problems or is embarrassing.","ex":{"en":"Inevitably the transition will yield some sticky moments","cn":"过渡时期难免会出现一些困难的时候。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)湿热的，闷热的","en":"Sticky weather is unpleasantly hot and damp.","ex":{"en":"...four desperately hot, sticky days in the middle of August.","cn":"8 月中旬极其闷热的 4 天"}},{"pos":"PHRASE 短语","cn":"下场很悲惨;死得很惨","en":"If someone comes to a sticky end or meets a sticky end, they suffer very badly or die in an unpleasant way.","ex":{"en":"Arminius also came to a sticky end, murdered by his own troops.","cn":"阿米尼乌斯也死得很惨，被自己的部下害死了。"}}]},"examples":[{"en":"Stir in the milk to make a soft but not sticky dough.","cn":"把牛奶搅进去，和成软而不黏的面团。"},{"en":"sticky fingers covered in jam","cn":"粘满果酱的黏乎乎的手指"}]},"stocking":{"oxford":{"phon":"ˈstɒkɪŋ","pos":"noun","senses":[{"en":"either of a pair of thin pieces of clothing that fit closely over the legs and feet, usually worn under other clothes","cn":"长筒女袜","ex":{"en":"a pair of silk stockings","cn":"一双长筒丝袜"}},{"en":"a long sock that children leave out when they go to bed on Christmas Eve so that it can be filled with presents","cn":"圣诞袜（圣诞夜小孩睡前留在外边供装圣诞礼物的长袜）","ex":{"en":"The stockings were hung by the chimney.","cn":"长袜挂在烟囱旁。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(女式)长筒袜","en":"Stockings are items of women's clothing which fit closely over their feet and legs. Stockings are usually made of nylon or silk and are held in place by suspenders.","ex":{"en":"...a pair of nylon stockings.","cn":"一双尼龙长筒袜"}},{"pos":"N-COUNT 可数名词","cn":"同 Christmas stocking","en":"A stocking is the same as a Christmas stocking ."}]},"media":{"uk":"media/uk/stocking__gb_1.mp3","us":"media/us/stocking__us_1.mp3"},"examples":[{"en":"a pair of silk stockings","cn":"一双长筒丝袜"}]},"store":{"media":{"uk":"media/uk/store__gb_1.mp3","us":"media/us/store__us_1.mp3"},"oxford":{"phon":"stɔː(r)","pos":"noun","senses":[{"en":"a large shop that sells many different types of goods","cn":"（大型）百货商店","g":"[countable]","ex":{"en":"It's available at London's three biggest stores.","cn":"这个在伦敦的三大百货商店都能买到。"}},{"en":"a shop, large or small","cn":"商店；店铺","g":"[countable]","lab":"North American English","ex":{"en":"I'm going to the store.","cn":"我要去商店了。"}},{"en":"a website that sells things","cn":"购物网站","ex":{"en":"an online store","cn":"线上商店"}},{"en":"a quantity or supply of something that you have and use","cn":"贮存物；备用物","g":"[countable]","ex":{"en":"her secret store of chocolate","cn":"她私下存放的巧克力"}},{"en":"goods of a particular kind or for a particular purpose","cn":"（某类或作某用途的）商品，物品","g":"[plural]","ex":{"en":"medical stores","cn":"医疗用品"}},{"en":"a place where goods of a particular kind are kept","cn":"仓库；贮藏所","g":"[countable]","ex":{"en":"The grain store holds several thousand tonnes.","cn":"这个粮仓可以存放几千吨粮食。"}},{"en":"to put something somewhere and keep it there to use later","cn":"贮存；贮藏；保存","ex":{"en":"We do not have adequate space to store these documents.","cn":"我们没有那么多地方存放这些文件。"},"pos":"verb"},{"en":"to keep information or facts in a computer or in your brain","cn":"（在计算机里）存储；记忆","ex":{"en":"to store data/information","cn":"存储数据／信息"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商店(英国英语中主要指大型百货商店，而美国英语中可指任何规模的商店)","en":"A store is a building or part of a building where things are sold. In British English, store is used mainly to refer to a large shop selling a variety of goods, but in American English a store can be any size of shop.","ex":{"en":"Bombs were planted in stores in Manchester and Blackpool.","cn":"炸弹被安放在曼彻斯特和布莱克浦的几家商店里。"}},{"pos":"VERB 动词","cn":"贮存;储备;存放","en":"When you store things, you put them in a container or other place and leave them there until they are needed.","ex":{"en":"Store the cookies in an airtight tin","cn":"把饼干贮存在一个密封罐里。"}},{"pos":"VERB 动词","cn":"(在计算机里)存储;记忆;记录","en":"When you store information, you keep it in your memory, in a file, or in a computer.","ex":{"en":"Where in the brain do we store information about colours?","cn":"我们在大脑的哪个部位储存有关颜色的信息？"}},{"pos":"N-COUNT 可数名词","cn":"(事物的)储存，储备","en":"A store of things is a supply of them that you keep somewhere until you need them.","ex":{"en":"I handed over my secret store of chocolate biscuits","cn":"我交出了自己偷偷藏起来的巧克力饼干。"}},{"pos":"N-COUNT 可数名词","cn":"仓库;储存处","en":"A store is a place where things are kept while they are not being used.","ex":{"en":"...a decision taken in 1982 to build a store for spent fuel from submarines.","cn":"1982 年作出的为潜艇废燃料建立一个储存库的决定"}},{"pos":"N-COUNT 可数名词","cn":"大量;丰富","en":"If you have a store of knowledge, jokes, or stories, you have a large amount of them ready to be used.","ex":{"en":"He possessed a vast store of knowledge","cn":"他知识渊博。"}},{"pos":"PHRASE 短语","cn":"就要出现在…身上;即将发生在…身上","en":"If something is in store for you, it is going to happen at some time in the future.","ex":{"en":"There were also surprises in store for me","cn":"也有一些令人吃惊的事在等着我。"}},{"pos":"PHRASE 短语","cn":"重视;珍惜;认为…极为必要","en":"If you set great store by something, you think that it is extremely important or necessary.","ex":{"en":"...a retail group which sets great store by traditional values.","cn":"重视传统价值观念的零售团体"}},{"pos":"","cn":"","en":"相关词组：store away store up"}]},"examples":[{"en":"If she had known what lay in store for her, she would never have agreed to go.","cn":"要是她事先知道会有什么遭遇的话，她是决不会同意去的。"},{"en":"We don't know what life holds in store for us.","cn":"我们不知道等待我们的将是什么样的生活。"}]},"studio":{"media":{"uk":"media/uk/studio__gb_1.mp3","us":"media/us/studio__us_1.mp3"},"oxford":{"phon":"ˈstjuːdiəʊ","pos":"noun","senses":[{"en":"a room where radio or television programmes are recorded and broadcast from, or where music is recorded","cn":"（广播或电视节目的）录制室，演播室；（音乐）录音棚","ex":{"en":"a television/recording studio","cn":"电视演播室；录音室"}},{"en":"a place where films are made or produced","cn":"（电影）摄影棚","ex":{"en":"The tour guide is showing a group of tourists around a movie studio.","cn":"导游正在带领一群游客参观电影制片厂。"}},{"en":"a company that makes films","cn":"电影公司；电影制片厂","ex":{"en":"She works for a major Hollywood studio.","cn":"她在好莱坞一家大电影公司工作。"}},{"en":"a room where an artist works","cn":"（艺术家的）工作室","ex":{"en":"I wanted to turn the room into an artist's studio.","cn":"我想把这个房间改造成艺术工作室。"}},{"en":"a place where dancing is taught or where dancers practise","cn":"（舞蹈）练功房","ex":{"en":"a dance studio","cn":"舞蹈练功房"}},{"en":"a small flat with one main room for living and sleeping in and usually a kitchen and bathroom","cn":"单间公寓，小套房（客厅和卧室在同一个空间里，通常带厨房和浴室）","lab":"British English also"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"画室;摄影室;工作室","en":"A studio is a room where a painter, photographer, or designer works.","ex":{"en":"She was in her studio again, painting onto a large canvas.","cn":"她又回到了画室，在一张大帆布上作画。"}},{"pos":"N-COUNT 可数名词","cn":"(广播、电视的)录音室，录像室，演播室;(唱片、电影的)录音棚，制作室","en":"A studio is a room where radio or television programmes are recorded, CDs are produced, or films are made.","ex":{"en":"She's much happier performing live than in a recording studio.","cn":"与在录音棚里录音相比，她更喜欢现场表演。"}},{"pos":"N-COUNT 可数名词","cn":"电影公司;电影制片厂;唱片公司","en":"You can also refer to film-making or recording companies as studios .","ex":{"en":"She wrote to Paramount Studios and asked if they would audition her.","cn":"她写信给派拉蒙电影公司，询问他们是否同意让她去试镜。"}},{"pos":"N-COUNT 可数名词","cn":"单间公寓(一个房间兼作起居室和卧室，带厨房和卫生间)","en":"A studio is a small flat with one room for living and sleeping in, a kitchen, and a bathroom. You can also talk about a studio flat in British English or a studio apartment in American English.","ex":{"en":"I live on my own in a studio flat.","cn":"我自己住在一个单间公寓里。"}}]},"examples":[{"en":"She works for a major Hollywood studio.","cn":"她为好莱坞一家大电影公司工作。"},{"en":"a studio audience (= one in a studio, that can be seen or heard as a programme is broadcast)","cn":"演播室现场的观众（或听众）"}]},"steep":{"media":{"uk":"media/uk/steep__gb_1.mp3","us":"media/us/steep__us_1.mp3"},"oxford":{"phon":"stiːp","pos":"adjective","senses":[{"en":"rising or falling quickly, not gradually","cn":"陡的；陡峭的","ex":{"en":"a steep hill/slope","cn":"陡峭的山；陡坡"}},{"en":"sudden and very big","cn":"突然的；急剧的；大起大落的","g":"[usually before noun]","ex":{"en":"a steep decline in the birth rate","cn":"出生率的骤降"}},{"en":"too much; unreasonable","cn":"过高的；过分的；不合理的","lab":"informal","ex":{"en":"£4 for a cup of coffee seems a little steep to me.","cn":"一杯咖啡 4 英镑在我看来有点贵得离谱。"}},{"en":"if you steep food in a liquid or leave it to steep, you put it in the liquid and leave it for some time so that it becomes soft and takes in the taste of the liquid","cn":"（在液体中）浸泡，腌制（食物）","ex":{"en":"Steep the fruit in brandy overnight.","cn":"将水果浸泡在白兰地中过夜。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"陡的;陡峭的;陡直的","en":"A steep slope rises at a very sharp angle and is difficult to go up.","ex":{"en":"San Francisco is built on 40 hills and some are very steep.","cn":"旧金山建在 40 座小山丘上，其中一些非常陡峭。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(增加或减少)急剧的，大幅度的","en":"A steep increase or decrease in something is a very big increase or decrease.","ex":{"en":"Consumers are rebelling at steep price increases.","cn":"消费者在抗议物价飞涨。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(价格)过高的，昂贵的","en":"If you say that the price of something is steep, you mean that it is expensive.","ex":{"en":"The annual premium can be a little steep, but will be well worth it if your dog is injured.","cn":"每年要交的保险费可能有点高，但如果你的狗受了伤就会很值了。"}},{"pos":"VERB 动词","cn":"浸泡(食物)","en":"To steep food in a liquid means to put the food in the liquid for some time so that the food gets flavour from the liquid.","ex":{"en":"It's a drink made by steeping pineapple rind in water.","cn":"这是用菠萝皮泡在水里做的饮料。"}}]},"examples":[{"en":"£2 for a cup of coffee seems a little steep to me.","cn":"一杯咖啡 2 英镑在我看来有点贵得离谱。"},{"en":"They spent a month steeping themselves in Chinese culture.","cn":"他们花了一个月时间潜心钻研中国文化。"}]},"storm":{"media":{"uk":"media/uk/storm__gb_1.mp3","us":"media/us/storm__us_1.mp3"},"oxford":{"phon":"stɔːm","pos":"noun","senses":[{"en":"very bad weather with strong winds and rain, and often thunder and lightning","cn":"暴风雨","lab":"British English","ex":{"en":"fierce/heavy/severe/violent storms","cn":"狂风暴雨"}},{"en":"very bad weather of the type mentioned","cn":"和风暴有关的恶劣天气","ex":{"en":"She had to brave an ice storm to get to the interview.","cn":"她不得不冒着冰暴去参加面试。"}},{"en":"a situation in which a lot of people suddenly express very strong feelings about something","cn":"（群情迸发的）浪潮","ex":{"en":"His comments created a storm of protest in the media.","cn":"他的评论在媒体引起了抗议的浪潮。"}},{"en":"a sudden loud noise that is caused by emotion or excitement","cn":"（因激动或兴奋而爆发出的）暴风雨般的声音，轰鸣","ex":{"en":"a storm of applause","cn":"如雷掌声"}},{"en":"to suddenly attack a place","cn":"突袭；攻占","g":"[transitive, intransitive]","ex":{"en":"Police stormed the building and captured the gunman.","cn":"警察突袭那栋楼房，抓获了持枪歹徒。"},"pos":"verb"},{"en":"to go somewhere quickly and in an angry, noisy way","cn":"气呼呼地疾走；闯；冲","g":"[intransitive]","ex":{"en":"She stormed into my office waving a newspaper.","cn":"她挥舞着一张报纸怒气冲冲地闯进我的办公室。"},"pos":"verb"},{"en":"to say something in a loud angry way","cn":"怒吼；大发雷霆","g":"[transitive]","ex":{"en":"‘Don't you know who I am?’ she stormed.","cn":"“你不知道我是谁吗？”她怒喝道。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暴风雨","en":"A storm is very bad weather, with heavy rain, strong winds, and often thunder and lightning.","ex":{"en":"...the violent storms which whipped America's East Coast.","cn":"席卷美国东海岸的猛烈暴风雨"}},{"pos":"N-COUNT 可数名词","cn":"强烈的反应;群情激愤;激动人心","en":"If something causes a storm, it causes an angry or excited reaction from a large number of people.","ex":{"en":"The photos caused a storm when they were first published","cn":"照片最初刊登出来时曾引起了一片公愤。"}},{"pos":"N-COUNT 可数名词","cn":"(掌声等的)爆发，迸发","en":"A storm of applause or other noise is a sudden loud amount of it made by an audience or other group of people in reaction to something.","ex":{"en":"His speech was greeted with a storm of applause","cn":"人们对他的演讲报以雷鸣般的掌声。"}},{"pos":"VERB 动词","cn":"气冲冲地疾走;冲;闯","en":"If you storm into or out of a place, you enter or leave it quickly and noisily, because you are angry.","ex":{"en":"After a bit of an argument, he stormed out","cn":"争吵了几句后，他气冲冲地走了出去。"}},{"pos":"VERB 动词","cn":"怒吼;大发雷霆","en":"If you storm, you say something in a very loud voice, because you are extremely angry.","ex":{"en":"'It's a fiasco,' he stormed.","cn":"“这是场彻底的失败，”他怒吼道。"}},{"pos":"VERB 动词","cn":"猛攻;袭击","en":"If a place that is being defended is stormed, a group of people attack it, usually in order to get inside it.","ex":{"en":"Government buildings have been stormed and looted","cn":"政府大楼遭到了攻击和抢劫。"}},{"pos":"PHRASE 短语","cn":"在…大获成功","en":"If someone or something takes a place by storm, they are extremely successful.","ex":{"en":"Kenya's long distance runners have taken the athletics world by storm.","cn":"肯尼亚的长跑运动员在田径界获得了巨大成功。"}},{"pos":"PHRASE 短语","cn":"经受住考验;渡过难关","en":"If someone weathers the storm, they succeed in reaching the end of a very difficult period without much harm or damage.","ex":{"en":"He insists he will not resign and will weather the storm.","cn":"他坚称自己不会辞职，一定渡过难关。"}},{"pos":"","cn":"","en":"the eye of the storm→see: ; a storm in a teacup→see: ;"}]},"examples":[{"en":"She stormed into my office waving a newspaper.","cn":"她挥舞着一张报纸怒气冲冲地闯进我的办公室。"},{"en":"A political storm is brewing over the Prime Minister's comments.","cn":"首相的评论即将酝酿出一场政治风暴。"}]},"steppe":{"media":{"uk":"media/uk/steppe__gb_1.mp3","us":"media/us/steppe__us_1.mp3"},"oxford":{"phon":"step","pos":"noun","senses":[{"en":"a large area of land with grass but few trees, especially in south-east Europe and Siberia","cn":"草原；（尤指东南欧及西伯利亚的）干草原","ex":{"en":"the vast Russian steppes","cn":"辽阔的俄罗斯大草原"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大草原，干草原(尤指从东欧横穿苏联南部直至西伯利亚的大片地区)","en":"Steppes are large areas of flat grassy land where there are no trees, especially the area that stretches from Eastern Europe across the south of the former Soviet Union to Siberia."}]},"examples":[{"en":"the vast Russian steppes","cn":"辽阔的俄罗斯大草原"}]},"striptease":{"oxford":{"phon":"ˈstrɪptiːz","pos":"noun","senses":[{"en":"a form of entertainment, for example in a bar or club, when a performer removes his or her clothes in a sexually exciting way, usually to music, in front of an audience","cn":"脱衣舞"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"脱衣舞(表演)","en":"Striptease is a form of entertainment in which someone slowly takes off their clothes in a sexually exciting way, usually while music is played.","ex":{"en":"Oscar, much the worse for vodka, did a striptease.","cn":"奥斯卡喝了伏特加后醉醺醺地跳起了脱衣舞。"}}]},"media":{"uk":"media/uk/striptease__gb_1.mp3","us":"media/us/striptease__us_1.mp3"}},"stern":{"media":{"uk":"media/uk/stern__gb_1.mp3","us":"media/us/stern__us_1.mp3"},"oxford":{"phon":"stɜːn","pos":"adjective","senses":[{"en":"serious and often showing that you do not approve of somebody/something; expecting somebody to obey you","cn":"严厉的；苛刻的；要求别人服从的","ex":{"en":"a stern face/expression/look","cn":"严厉的面容／表情／目光"}},{"en":"serious and difficult","cn":"严峻的；难对付的","ex":{"en":"a stern test of nerves","cn":"对神经的严峻考验"}},{"en":"the back end of a ship or boat","cn":"船尾","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(话语或行动)严厉的，严正的","en":"Stern words or actions are very severe.","ex":{"en":"Mr Straw issued a stern warning to those who persist in violence","cn":"斯特劳先生向那些坚持进行暴力活动的人发出了严正警告。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)严厉的，严格的，苛刻的","en":"Someone who is stern is very serious and strict.","ex":{"en":"Her father was stern and hard to please.","cn":"她父亲很苛刻，让他满意很难。"}},{"pos":"N-COUNT 可数名词","cn":"船尾;艉部 from stem to stern","en":"The stern of a boat is the back part of it. →see: ;"},{"pos":"PHRASE 短语","cn":"(人)性格坚强的，坚忍的","en":"If you say that someone is made of sterner stuff, you mean that they have a strong personality and are capable of overcoming difficulties and problems.","ex":{"en":"Whoever this woman is, she's made of sterner stuff than I am.","cn":"不管这个女人是谁，她都比我坚强。"}}]},"examples":[{"en":"The police are planning sterner measures to combat crime.","cn":"警方正制订更严厉的措施打击犯罪活动。"},{"en":"We face stern opposition.","cn":"我们遇到激烈的反对。"}]},"stipend":{"media":{"uk":"media/uk/stipend__gb_1.mp3","us":"media/us/stipend__us_1.mp3"},"oxford":{"phon":"ˈstaɪpend","pos":"noun","senses":[{"en":"an amount of money that is paid regularly to somebody, especially a priest, as wages or money to live on","cn":"（尤指神职人员的）生活津贴，薪俸；献仪","lab":"especially North American English","ex":{"en":"a monthly stipend","cn":"月俸"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指地方法官或神职人员的)薪俸，生活津贴","en":"A stipend is a sum of money that is paid regularly, especially to a magistrate or a member of the clergy, as a salary or for their living expenses."},{"pos":"N-COUNT 可数名词","cn":"助学金;奖学金","en":"A stipend is a sum of money that is paid to a student for their living expenses."}]},"examples":[{"en":"( especially NAmE ) a summer internship with a small stipend","cn":"薪水微薄的暑期实习"},{"en":"a summer internship with a small stipend","cn":""}]},"staffer":{"media":{"uk":"media/uk/staffer__gb_1.mp3","us":"media/us/staffer__us_1.mp3"},"oxford":{"phon":"ˈstɑːfə(r)","pos":"noun","senses":[{"en":"a member of staff in a big organization","cn":"（大机构）职员"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指政治组织或新闻机构的一名)工作人员，职员","en":"A staffer is a member of staff, especially in political organizations or in journalism.","ex":{"en":"The Sky News TV station is largely run by ex-BBC news staffers.","cn":"空中新闻电视台主要是由原英国广播公司的新闻工作人员运作的。"}}]}},"staff":{"media":{"uk":"media/uk/staff__gb_1.mp3","us":"media/us/staff__us_1.mp3"},"oxford":{"phon":"stɑːf","pos":"noun","senses":[{"en":"all the workers employed in an organization considered as a group","cn":"全体职工（或雇员）","g":"[countable, usually singular, uncountable]","lab":"British English","ex":{"en":"medical/nursing/teaching/coaching staff","cn":"全体医务人员／护士／教师／教练"}},{"en":"the people who work at a school, college or university, but who do not teach students","cn":"（大、中、小学的）管理人员，行政人员","g":"[singular]","lab":"North American English","ex":{"en":"Students, faculty and staff were all men in those days.","cn":"那时候，学生和教职员都是男性。"}},{"en":"a group of senior army officers who help a commanding officer","cn":"（军队的）全体参谋人员","g":"[countable + singular or plural verb]","ex":{"en":"a staff officer","cn":"参谋"}},{"en":"a long stick used as a support when walking or climbing, as a weapon, or as a symbol of authority","cn":"拐杖；棍棒；权杖","g":"[countable]","lab":"old-fashioned or formal"},{"en":"a set of five lines on which music is written","cn":"五线谱","g":"[countable]","lab":"especially North American English"},{"en":"to work in an institution, a company, etc.; to provide people to work there","cn":"在…工作；任职于；为…配备职员","ex":{"en":"The advice centre is staffed entirely by volunteers.","cn":"在咨询中心工作的全部是志愿者。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(一组织的)全体工作人员，全体，职员","en":"The staff of an organization are the people who work for it.","ex":{"en":"The staff were very good","cn":"职员都很出色。"}},{"pos":"N-PLURAL 复数名词","cn":"(全体工作人员中的)部分成员","en":"People who are part of a particular staff are often referred to as staff .","ex":{"en":"10 staff were allocated to the task","cn":"10名员工被分配来完成这项任务。"}},{"pos":"VERB 动词","cn":"由…担任工作人员;由…供职","en":"If an organization is staffed by particular people, they are the people who work for it.","ex":{"en":"They are staffed by volunteers","cn":"它们的工作人员都是志愿者。"}},{"pos":"N-COUNT 可数名词","cn":"(结实的)杖，杆","en":"A staff is a strong stick or pole."},{"pos":"","cn":"五线谱","en":"A staff is the five lines that music is written on."}]},"examples":[{"en":"The charity provided money to staff and equip two hospitals.","cn":"这个慈善机构提供资金装备了两家医院并配备了人员。"},{"en":"a staff of ten (but not ten staff )","cn":"职工十人（但不作 ten staff）"}]},"strengthen":{"oxford":{"phon":"ˈstreŋkθn","pos":"verb","senses":[{"en":"to become more powerful or effective; to make somebody/something more powerful or effective","cn":"加强；增强；巩固","g":"[intransitive, transitive]","ex":{"en":"Her position in the party has strengthened in recent weeks.","cn":"最近几个星期以来，她在党内的地位得到巩固。"}},{"en":"to become physically stronger","cn":"增强（体质等）；使变得强壮","g":"[transitive]","ex":{"en":"The exercises are designed to strengthen your stomach muscles.","cn":"这些运动旨在增强你的腹部肌肉。"}},{"en":"to make a feeling, an opinion or a relationship stronger; to become stronger","cn":"加强，加深（感情、观念、关系）；（使）变得更深刻；（使）更坚定","g":"[transitive, intransitive]","ex":{"en":"This temporary setback merely strengthened her resolve.","cn":"这一时的挫折只加强了她的决心。"}},{"en":"to become stronger","cn":"增强；加强","g":"[intransitive]","ex":{"en":"The wind had strengthened overnight.","cn":"夜里，风更大了。"}},{"en":"to become stronger; to make a currency or an economy stronger","cn":"增强；（使）更强势","g":"[intransitive, transitive]","ex":{"en":"Yesterday the pound strengthened against the dollar.","cn":"昨天，英镑对美元的汇率上升了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"巩固(地位);增强，加强(实力)","en":"If something strengthens a person or group or if they strengthen their position, they become more powerful and secure, or more likely to succeed.","ex":{"en":"...the new constitution, which strengthens the government and enables it to balance and check the powers of parliament and president","cn":"巩固了政府的地位并使其能够制衡国会和总统权力的新宪法"}},{"pos":"VERB 动词","cn":"支持，强化(论点或论据);使更有说服力","en":"If something strengthens a case or argument, it supports it by providing more reasons or evidence for it.","ex":{"en":"He does not seem to be familiar with research which might have strengthened his own arguments.","cn":"他对那些本可以为他的观点提供佐证的研究似乎并不熟悉。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(经济、工业)坚挺，壮大;(使)(货币)升值","en":"If a currency, economy, or industry strengthens, or if something strengthens it, it increases in value or becomes more successful.","ex":{"en":"The dollar strengthened against most other currencies","cn":"美元相对大多数其他货币都升值了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"加强，加大(法律、措施)的力度;(使)变得更严格","en":"If a government strengthens laws or measures or if they strengthen, they are made more severe.","ex":{"en":"I am also looking urgently at how we can strengthen the law","cn":"我也在急切地关注我们该如何加强法制。"}},{"pos":"VERB 动词","cn":"增强(决心或毅力);使更具信心;使更加坚定","en":"If something strengthens you or strengthens your resolve or character, it makes you more confident and determined.","ex":{"en":"Any experience can teach and strengthen you, but particularly the more difficult ones","cn":"任何经历都能使你从中受益并让你变得坚强，而那些比较艰难的经历尤其如此。"}},{"pos":"V-ERG 及物/不及物动词","cn":"增进(关系或联系);(使)变得更紧密","en":"If something strengthens a relationship or link, or if a relationship or link strengthens, it makes it closer and more likely to last for a long time.","ex":{"en":"It will draw you closer together, and it will strengthen the bond of your relationship","cn":"这将使你们走得更近，并将增进你们之间的关系。"}},{"pos":"V-ERG 及物/不及物动词","cn":"加强，加深(印象、感情、信念);(使)变得比较深刻;(使)坚定","en":"If something strengthens an impression, feeling, or belief, or if it strengthens, it becomes greater or affects more people.","ex":{"en":"His speech strengthens the impression he is the main power in the organization","cn":"他的演讲让人更加确信他才是该组织的主心骨。"}},{"pos":"VERB 动词","cn":"增强(体质);使强健","en":"If something strengthens your body or a part of your body, it makes it healthier, often in such a way that you can move or carry heavier things.","ex":{"en":"Cycling is good exercise. It strengthens all the muscles of the body","cn":"骑自行车是一项不错的锻炼方式。它能使身体各部分的肌肉更强健。"}},{"pos":"VERB 动词","cn":"加强，加固(物体或结构)","en":"If something strengthens an object or structure, it makes it able to be treated roughly or able to support heavy weights, without being damaged or destroyed.","ex":{"en":"The builders will have to strengthen the existing joists with additional timber.","cn":"施工人员将不得不另外用木料加固现有的托梁。"}},{"pos":"VERB 动词","cn":"(风、水流等)增大，增强","en":"If the wind, current, or other force strengthens, it becomes faster or more powerful.","ex":{"en":"As it strengthened the wind was veering southerly","cn":"风越刮越大，逐渐转为南风。"}}]},"media":{"uk":"media/uk/strengthen__gb_1.mp3","us":"media/us/strengthen__us_1.mp3"},"examples":[{"en":"The move is clearly intended to strengthen the President's position as head of state.","cn":"这一举措显然意在加强总统作为国家元首的地位。"},{"en":"The new manager has strengthened the side by bringing in several younger players.","cn":"新经理通过引进几名年轻队员加强了队伍的实力。"}]},"stable":{"media":{"uk":"media/uk/stable__gb_1.mp3","us":"media/us/stable__us_1.mp3"},"oxford":{"phon":"ˈsteɪbl","pos":"adjective","senses":[{"en":"fixed or steady; not likely to move, change or fail","cn":"稳定的；稳固的；牢固的","ex":{"en":"The patient's condition is stable (= it is not getting worse).","cn":"患者病情稳定。"}},{"en":"calm and reasonable; not easily upset","cn":"稳重的；沉稳的；持重的","ex":{"en":"Mentally, she is not very stable.","cn":"她的心理状态不十分稳定。"}},{"en":"staying in the same chemical or atomic state","cn":"（化学状态或原子状态）稳定的","lab":"specialist","ex":{"en":"chemically stable","cn":"化学状态稳定的"}},{"en":"a building in which horses are kept","cn":"马厩","g":"[countable]","ex":{"en":"The horse was led back to its stable.","cn":"那匹马被牵回了马厩。"},"pos":"noun"},{"en":"an organization that keeps horses for a particular purpose","cn":"（养马作特定用途的）养马场，马房","g":"[countable + singular or plural verb]","lab":"British English also","ex":{"en":"a riding/racing stables","cn":"骑乘马／赛马养马场"},"pos":"noun"},{"en":"a group of racehorses owned or trained by the same person","cn":"统称某人拥有（或训练）的赛马","g":"[countable]","ex":{"en":"There have been just three winners from his stable this season.","cn":"这个赛季他的马只有三匹获胜。"},"pos":"noun"},{"en":"a group of people who work or trained in the same place; a group of products made by the same company","cn":"（在同一地方工作或训练的）一批人；（同一公司生产的）系列产品","g":"[singular]","ex":{"en":"actors from the same stable","cn":"同一剧团的演员"},"pos":"noun"},{"en":"to put or keep a horse in a stable","cn":"使（马）入厩；把（马）拴在马厩","ex":{"en":"Where do you stable your pony?","cn":"你的矮种马养在哪儿？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳定的;稳固不变的","en":"If something is stable, it is not likely to change or come to an end suddenly.","ex":{"en":"The price of oil should remain stable for the rest of 1992.","cn":"油价会在 1992 年剩下的时间里保持稳定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(性格)平和稳重的，持重的","en":"If someone has a stable personality, they are calm and reasonable and their mood does not change suddenly.","ex":{"en":"Their characters are fully formed and they are both very stable children.","cn":"他们的性格已经完全形成，两人都是非常持重的孩子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(病人)病情稳定的","en":"You can describe someone who is seriously ill as stable when their condition has stopped getting worse.","ex":{"en":"The injured man was in a stable condition.","cn":"伤者情况稳定。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(化学物质)稳定的","en":"Chemical substances are described as stable when they tend to remain in the same chemical or atomic state.","ex":{"en":"The less stable compounds were converted into a compound called Delta-A THC.","cn":"不太稳定的化合物被转换成了一种叫做Delta-A THC的化合物。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳固的;牢固的","en":"If an object is stable, it is firmly fixed in position and is not likely to move or fall.","ex":{"en":"This structure must be stable.","cn":"这一结构必须得很稳固。"}},{"pos":"N-COUNT 可数名词","cn":"马厩","en":"A stable or stables is a building in which horses are kept."},{"pos":"N-COUNT 可数名词","cn":"(繁殖、训练赛马的)养马场","en":"A stable or stables is an organization that breeds and trains horses for racing.","ex":{"en":"Miss Curling won on two horses from Mick Trickey's stable.","cn":"柯林小姐在来自米克·特里齐养马场的两匹马身上下了注，结果她赢了。"}},{"pos":"VERB 动词","cn":"把(马)关进马厩","en":"When horses are stabled, they are put into a stable.","ex":{"en":"The animals had been fed and stabled","cn":"牲畜已经喂好并关进厩里了。"}},{"pos":"N-COUNT 可数名词","cn":"接受同一经纪人服务的一群人","en":"You can say that someone has a stable of people when they manage and promote the careers of that group of people.","ex":{"en":"As chief executive, he assembled a polished stable of celebrities.","cn":"作为首席执行官，他手下云集了一批优雅的名人名士。"}},{"pos":"PHRASE 短语","cn":"亡羊补牢","en":"If you say that someone has closed or shut the stable door after the horse has bolted, you mean that they have tried to prevent something happening but they have done so too late to prevent damage being done."}]},"examples":[{"en":"There have been just three winners from his stable this season.","cn":"这个赛季他的马只有三匹获胜。"},{"en":"Mentally, she is not very stable.","cn":"她的心理状态不十分稳定。"}]},"stewed":{"media":{"uk":"media/uk/stewed__gb_1.mp3","us":"media/us/stewed__us_1.mp3"},"oxford":{"phon":"stjuːd","pos":"adjective","senses":[{"en":"tasting too strong and bitter because it has been left in the pot too long","cn":"（因久泡）太酽的，泡苦了的"}]}},"status":{"media":{"uk":"media/uk/status__gb_1.mp3","us":"media/us/status__us_1.mp3"},"oxford":{"phon":"ˈsteɪtəs","pos":"noun","senses":[{"en":"the legal position of a person, group or country","cn":"法律地位（或身份）","g":"[uncountable, countable, usually singular]","ex":{"en":"They were granted refugee status.","cn":"他们获得了难民身份。"}},{"en":"the social or professional position of somebody/something in relation to others","cn":"地位；身份；职位","g":"[uncountable, countable, usually singular]","ex":{"en":"She achieved celebrity status overnight.","cn":"她一夜之间成为名流。"}},{"en":"high rank or social position","cn":"高级职位；社会上层地位","g":"[uncountable]","ex":{"en":"The job brings with it status and a high income.","cn":"担任这一职务既有显贵的地位又有丰厚的收入。"}},{"en":"the level of importance that is given to something","cn":"重视（或崇尚）程度","g":"[uncountable, countable, usually singular]","ex":{"en":"This reflects the high status accorded to science in our culture.","cn":"这反映出我们的文化对科学的高度崇尚。"}},{"en":"the situation at a particular time during a process","cn":"（进展的）状况，情形","g":"[uncountable]","ex":{"en":"What is the current status of our application for funds?","cn":"我们申请资金目前进展如何？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"社会地位;专业资格;职位","en":"Your status is your social or professional position.","ex":{"en":"People of higher status tend more to use certain drugs.","cn":"社会地位较高的人往往更容易吸食某种毒品。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(在公众或某一团体中的)威望，地位,身份","en":"Status is the importance and respect that someone has among the public or a particular group.","ex":{"en":"Nurses are undervalued, and they never enjoy the same status as doctors","cn":"护士的作用被人们低估了，她们从未享有和医生同样的地位。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"重要性","en":"The status of something is the importance that people give it.","ex":{"en":"Those things that can be assessed by external tests are being given unduly high status","cn":"那些可以通过外部测试来评估的东西被过于重视了。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(个人、组织或地方的)法律地位，法律身份，状况","en":"A particular status is an official description that says what category a person, organization, or place belongs to, and gives them particular rights or advantages.","ex":{"en":"Bristol regained its status as a city in the local government reorganisation.","cn":"布里斯托尔在地方政府重组过程中重新获得了自己作为一个城市的法律地位。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"状况;情况","en":"The status of something is its state of affairs at a particular time.","ex":{"en":"The Council unanimously directed city staff to prepare a status report on the project","cn":"委员会一致要求市政府工作人员就该项目准备一份进度报告。"}}]},"examples":[{"en":"The job brings with it status and a high income.","cn":"担任这一职务既有显贵的地位又有丰厚的收入。"},{"en":"Women are only asking to be given equal status with men.","cn":"妇女只是要求得到和男人平等的地位。"}]},"steal":{"media":{"uk":"media/uk/steal__gb_1.mp3","us":"media/us/steal__us_1.mp3"},"oxford":{"phon":"stiːl","pos":"verb","senses":[{"en":"to take something from a person, shop, etc. without permission and without intending to return it or pay for it","cn":"偷；窃取","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"I'll report you to the police if I catch you stealing again.","cn":"如果我再抓到你偷东西我就报警。"}},{"en":"to move secretly and quietly so that other people do not notice you","cn":"偷偷地（或悄悄地）移动","g":"[intransitive]","lab":"figurative","ex":{"en":"She stole out of the room so as not to wake the baby.","cn":"她生怕惊醒婴儿，蹑手蹑脚地从房间里出来。"}},{"en":"to run to the next base before another player from your team hits the ball, so that you are closer to scoring","cn":"偷（垒）","g":"[transitive]","ex":{"en":"He tried to steal second base but was out.","cn":"他试图盗二垒但被杀出局。"}},{"en":"an act of stealing something","cn":"偷盗，行窃","lab":"especially North American English","ex":{"en":"The robbery from the Met was the greatest art steal in history.","cn":"大都会博物馆抢劫案是历史上最大的艺术品盗窃案。"},"pos":"noun"},{"en":"the act of running to another base while the pitcher is throwing the ball","cn":"偷垒","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"偷;窃取","en":"If you steal something from someone, you take it away from them without their permission and without intending to return it.","ex":{"en":"He was accused of stealing a small boy's bicycle","cn":"他被指控偷了一个小男孩的自行车。"}},{"pos":"VERB 动词","cn":"剽窃，窃取(别人的想法)","en":"If you steal someone else's ideas, you pretend that they are your own.","ex":{"en":"A writer is suing director Steven Spielberg for allegedly stealing his film idea","cn":"一名作家正控告导演史蒂文·斯皮尔伯格涉嫌剽窃了他的电影创意。"}},{"pos":"VERB 动词","cn":"偷偷移动至;悄悄走到","en":"If someone steals somewhere, they move there quietly, in a secret way.","ex":{"en":"They can steal away at night and join us","cn":"他们可以晚上偷偷溜出来和我们碰面。"}},{"pos":"N-SING 单数名词","cn":"很便宜的东西","en":"If you describe something as a steal, you mean that it is very good value.","ex":{"en":"At only £3.50, this champagne is a steal.","cn":"这瓶香槟酒只卖 3.50英镑，太便宜了。"}},{"pos":"","cn":"","en":"to steal a glance→see: ; to steal a march on someone→see: ; to steal the show→see: ; to steal someone's thunder→see: ;"}]},"examples":[{"en":"She stole out of the room so as not to wake the baby.","cn":"她生怕惊醒婴儿，蹑手蹑脚地从房间里出来。"},{"en":"This suit is a steal at $80.","cn":"这套西服只卖 80 元，跟白给差不多了。"}]},"structural":{"media":{"uk":"media/uk/structural__gb_1.mp3","us":"media/us/structural__us_1.mp3"},"oxford":{"phon":"ˈstrʌktʃərəl","pos":"adjective","senses":[{"en":"connected with the way in which something is built or organized","cn":"结构（或构造）上的","ex":{"en":"Storms have caused structural damage to hundreds of homes.","cn":"数场暴风雨使几百间住房的结构受损。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"结构上的;构造上的","en":"Structural means relating to or affecting the structure of something.","ex":{"en":"The explosion caused little structural damage to the office towers themselves.","cn":"爆炸对办公大楼本身几乎没有造成结构上的损坏。"}}]},"examples":[{"en":"Storms have caused structural damage to hundreds of homes.","cn":"几场暴风雨使几百间住房的结构受损。"},{"en":"The languages are structurally different.","cn":"这些语言在结构上有差别。"}]},"striking":{"media":{"uk":"media/uk/striking__gb_1.mp3","us":"media/us/striking__us_1.mp3"},"oxford":{"phon":"ˈstraɪkɪŋ","pos":"adjective","senses":[{"en":"interesting and unusual enough to attract attention","cn":"引人注目的；异乎寻常的；显著的","ex":{"en":"a striking feature","cn":"显著的特征"}},{"en":"very attractive, often in an unusual way","cn":"妩媚动人的；标致的；俊秀的","ex":{"en":"striking good looks","cn":"姣好的面容"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引人注目的;异乎寻常的;显著的","en":"Something that is striking is very noticeable or unusual.","ex":{"en":"The most striking feature of those statistics is the high proportion of suicides","cn":"那些统计数据最引人注目之处是其极高的自杀率。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"妩媚动人的;标致的;俊秀的","en":"Someone who is striking is very attractive, in a noticeable way.","ex":{"en":"She was a striking woman with long blonde hair.","cn":"她是个留着金色长发的俏女郎。"}}]},"examples":[{"en":"In striking contrast to their brothers, the girls were both intelligent and charming.","cn":"姑娘们既聪明伶俐，又妩媚动人，跟她们的兄弟形成鲜明的对照。"},{"en":"The two polls produced strikingly different results.","cn":"两次投票产生的结果截然不同。"}]},"stabilize":{"media":{"uk":"media/uk/stabilize__gb_1.mp3","us":"media/us/stabilize__us_1.mp3"},"oxford":{"phon":"ˈsteɪbəlaɪz","pos":"verb","senses":[{"en":"to become or to make something become steady and unlikely to change; to make something stable","cn":"（使）稳定，稳固","ex":{"en":"The patient's condition stabilized.","cn":"患者的病情稳定下来。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)稳定;(使)安定","en":"If something stabilizes, or is stabilized, it becomes stable.","ex":{"en":"Although her illness is serious, her condition is beginning to stabilize","cn":"虽然她病得很重，但病情正开始趋于稳定。"}}]},"examples":[{"en":"Doctors stabilized the patient's condition.","cn":"大夫们使患者的病情稳定下来。"},{"en":"The patient's condition stabilized.","cn":"患者的病情稳定下来。"}]},"striped":{"oxford":{"phon":"straɪpt","pos":"adjective","senses":[{"en":"marked with a pattern of stripes","cn":"有条纹的","ex":{"en":"a striped shirt","cn":"条纹衬衫"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有条纹的","en":"Something that is striped has stripes on it.","ex":{"en":"...a bottle green and maroon striped tie.","cn":"有深绿色和栗色条纹的领带"}}]},"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/striped.jpg"],"uk":"media/uk/striped__gb_1.mp3","us":"media/us/striped__us_1.mp3"},"examples":[{"en":"a blue and white striped jacket","cn":"蓝白条上衣"},{"en":"a striped shirt","cn":"条纹衬衫"}]},"style":{"media":{"uk":"media/uk/style__gb_1.mp3","us":"media/us/style__us_1.mp3"},"oxford":{"phon":"staɪl","pos":"noun","senses":[{"en":"the particular way in which something is done","cn":"方式；作风","g":"[countable, uncountable]","sc":"way something is done","ex":{"en":"a wide range of musical styles","cn":"多种音乐风格"}},{"en":"a particular design of something, especially clothes","cn":"（尤指服装的）样式，款式","g":"[countable]","lab":"North American English also","sc":"design of clothes/hair","ex":{"en":"We stock a wide variety of styles and sizes.","cn":"我们有各种款式各种尺码的货品。"}},{"en":"the quality of being fashionable in the clothes that you wear","cn":"（指服装）时新，时髦，流行式样","g":"[uncountable]","sc":"design of clothes/hair","ex":{"en":"style-conscious teenagers","cn":"讲究时髦的青少年"}},{"en":"the quality of being attractive and made or done to a high standard","cn":"品位；风度；气派","g":"[uncountable]","sc":"being attractive","ex":{"en":"The hotel has been redecorated but it's lost a lot of its style.","cn":"旅馆已重新装修，但昔日的优雅格调所剩无几。"}},{"en":"the features of a book, painting, building, etc. that make it typical of a particular author, artist, historical period, etc.","cn":"风格；体","g":"[countable, uncountable]","sc":"of book/painting/building","ex":{"en":"a style of architecture","cn":"建筑风格"}},{"en":"the correct use of language","cn":"语言规范；好的文风","g":"[uncountable, countable]","sc":"use of language","ex":{"en":"It's not considered good style to start a sentence with ‘but’.","cn":"人们认为，一句话用 but 开头不是好的文风。"}},{"en":"having the type of style mentioned","cn":"…式的；…风格的","sc":"-style","ex":{"en":"Italian-style gardens","cn":"意大利风格的花园"}},{"en":"the long, thin part of a flower that carries the stigma","cn":"花柱","lab":"biology","sc":"in a plant"},{"en":"to design, make or shape something in a particular way","cn":"把…设计（或缝制、做）成某种式样","sc":"clothes/hair, etc.","ex":{"en":"an elegantly styled jacket","cn":"式样高雅的上衣"},"pos":"verb"},{"en":"to give somebody/something/yourself a particular name or title","cn":"称呼；命名；称","lab":"formal","sc":"give name/title","ex":{"en":"He styled himself Major Carter.","cn":"他自称卡特少校。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"行为方式;作风;风格","en":"The style of something is the general way in which it is done or presented, which often shows the attitudes of the people involved.","ex":{"en":"Our children's different needs and learning styles created many problems","cn":"孩子们不同的需求和学习方式给我们带来了许多问题。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"风度;气派;格调","en":"If people or places have style, they are smart and elegant.","ex":{"en":"Bournemouth, you have to admit, has style","cn":"你不得不承认伯恩茅斯是个很有格调的地方。"}},{"pos":"N-VAR 可变名词","cn":"款式","en":"The style of a product is its design.","ex":{"en":"His 50 years of experience have given him strong convictions about style","cn":"50 年的经验使得他在款式上有自己的独到见解。"}},{"pos":"N-COUNT 可数名词","cn":"(某群艺术家或某文艺时期的)风格","en":"In the arts, a particular style is characteristic of a particular period or group of people.","ex":{"en":"...six scenes in the style of a classical Greek tragedy.","cn":"6 个古典希腊悲剧式的场景"}},{"pos":"VERB 动词","cn":"设计;使具有…风格","en":"If something such as a piece of clothing, a vehicle, or someone's hair is styled in a particular way, it is designed or shaped in that way.","ex":{"en":"His thick blond hair had just been styled before his trip.","cn":"他在旅行前刚把浓密的金发修剪了一番。"}},{"pos":"PHRASE 短语","cn":"不是…的风格;不符合…的喜好","en":"If you say that something is not someone's style, you mean that it is not the way in which they usually do things, or it is different from the sort of thing they usually like. to cramp someone's style→see: ;","ex":{"en":"Mr Blair was not off guard. That is not his style","cn":"布莱尔先生没有放松警惕，这不是他的风格。"}}]},"examples":[{"en":"I'm surprised he rides a motorbike — I'd have thought big cars were more his style (= what suited him).","cn":"没想到他骑的是摩托车。我还以为他喜欢大轿车呢。"},{"en":"It's not considered good style to start a sentence with ‘but’.","cn":"人们认为，一句话用 but 开头不是好的文风。"}]},"study":{"media":{"uk":"media/uk/study__gb_1.mp3","us":"media/us/study__us_1.mp3"},"oxford":{"phon":"ˈstʌdi","pos":"noun","senses":[{"en":"the activity of learning or gaining knowledge, either from books or by examining things in the world","cn":"学习；研究","g":"[uncountable]","sc":"activity of learning","ex":{"en":"a room set aside for private study","cn":"单留出来的书房"}},{"en":"a particular person’s learning activities, for example at a college or university","cn":"功课；课业；学业","g":"[plural]","lab":"formal","sc":"activity of learning","ex":{"en":"to continue your studies","cn":"继续学业"}},{"en":"used in the names of some academic subjects","cn":"（用于某些学科名称）","g":"[uncountable + singular or plural verb]","sc":"academic subject","ex":{"en":"business/media/American studies","cn":"商学；传媒学；美国研究"}},{"en":"a piece of research that examines a subject or question in detail","cn":"（专题）研究，调查","g":"[countable]","sc":"research","ex":{"en":"to conduct/undertake a study","cn":"进行研究"}},{"en":"an academic book or article on a particular topic","cn":"（某一主题的）学术著作，论文","g":"[countable]","sc":"research","ex":{"en":"a study of Jane Austen's novels","cn":"关于简·奥斯丁小说的一篇论文"}},{"en":"the act of considering or examining something in detail","cn":"细致考虑；仔细检查；审视","g":"[uncountable]","sc":"research","ex":{"en":"These proposals deserve careful study.","cn":"这些建议值得认真研究。"}},{"en":"a room, especially in somebody’s home, used for reading and writing","cn":"书房","g":"[countable]","sc":"room","ex":{"en":"She crossed the hallway and opened the door to her private study.","cn":"她穿过门厅，打开了通往她私人书房的门。"}},{"en":"a drawing or painting of something, especially one done for practice or before doing a larger picture","cn":"习作；试作；试画","g":"[countable]","sc":"art","ex":{"en":"a study of Chartres Cathedral","cn":"一幅沙特尔大教堂的习作"}},{"en":"the act of showing or describing somebody/something in literature or another art form, especially a character or an aspect of behaviour","cn":"（通过文学作品或其他艺术形式的）描绘，刻画","g":"[countable]","sc":"character","ex":{"en":"The novel is a character study of a city and its people.","cn":"小说描绘了一座城市及其居民的性格。"}},{"en":"a piece of music designed to give a player practice in technical skills","cn":"练习曲","g":"[countable]","sc":"music"},{"en":"a perfect example of something","cn":"典型；范例","g":"[singular]","lab":"formal","sc":"perfect example","ex":{"en":"His face was a study in concentration.","cn":"他脸上完全是一副全神贯注的表情。"}},{"en":"to spend time learning about a subject by reading, going to college, etc.","cn":"学习；攻读","g":"[transitive, intransitive]","lab":"British English","sc":"learn","ex":{"en":"He sat up very late that night, studying.","cn":"他那晚学习到深夜。"},"pos":"verb"},{"en":"to watch or to look at somebody/something carefully in order to find out something","cn":"审视；端详；细看","g":"[transitive]","sc":"examine carefully","ex":{"en":"Scientists are studying photographs of the planet for signs of life.","cn":"科学家仔细察看行星照片，看有无生命迹象。"},"pos":"verb"},{"en":"to examine something carefully in order to understand it","cn":"研究；调查","g":"[transitive]","sc":"examine carefully","ex":{"en":"We will study the report carefully before making a decision.","cn":"我们将认真研究这份报告，然后再做决定。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"学习;研读","en":"If you study, you spend time learning about a particular subject or subjects.","ex":{"en":"...a relaxed and happy atmosphere that will allow you to study to your full potential","cn":"能让人充分发挥学习潜质的轻松愉快的环境"}},{"pos":"N-UNCOUNT 不可数名词","cn":"学习;研究","en":"Study is the activity of studying.","ex":{"en":"...the use of maps and visual evidence in the study of local history","cn":"利用地图和图像资料研究当地历史"}},{"pos":"N-COUNT 可数名词","cn":"研究;调查;研究成果","en":"A study of a subject is a piece of research on it.","ex":{"en":"Recent studies suggest that as many as 5 in 1000 new mothers are likely to have this problem.","cn":"最近的研究成果表明在 1000 个刚生产完的妈妈中，有 5 个可能存在这样的问题。"}},{"pos":"N-PLURAL 复数名词","cn":"研究科目;学科;课题","en":"You can refer to educational subjects or courses that contain several elements as studies of a particular kind.","ex":{"en":"...a new centre for Islamic studies","cn":"新的伊斯兰教研究中心"}},{"pos":"VERB 动词","cn":"审视;端详;细看","en":"If you study something, you look at it or watch it very carefully, in order to find something out.","ex":{"en":"Debbie studied her friend's face for a moment.","cn":"黛比仔细端详了一会她朋友的脸。"}},{"pos":"VERB 动词","cn":"研究;调查;仔细观察","en":"If you study something, you consider it or observe it carefully in order to be able to understand it fully.","ex":{"en":"I know that you've been studying chimpanzees for thirty years now","cn":"我知道你研究黑猩猩至今已有30年了。"}},{"pos":"N-COUNT 可数名词","cn":"习作;试画;试作","en":"A study by an artist is a drawing which is done in preparation for a larger picture."},{"pos":"N-COUNT 可数名词","cn":"书房","en":"A study is a room in a house which is used for reading, writing, and studying."}]},"examples":[{"en":"The group will study how the region coped with the loss of thousands of jobs.","cn":"该小组将考察这一地区是如何应对减少几千个工作岗位的局面的。"},{"en":"Don't disturb Jane, she's studying for her exams.","cn":"不要打扰简，她正在温习功课，准备考试呢。"}]},"stone":{"media":{"uk":"media/uk/stone__gb_1.mp3","us":"media/us/stone__us_1.mp3"},"oxford":{"phon":"stəʊn","pos":"noun","senses":[{"en":"a hard solid mineral substance that is found in the ground, often used for building","cn":"石头；石料；岩石","g":"[uncountable]","sc":"hard substance","ex":{"en":"Most of the houses are built of stone.","cn":"这些房子多数是用石头建造的。"}},{"en":"a small piece of rock of any shape","cn":"石块；石子","g":"[countable]","lab":"especially British English","sc":"hard substance","ex":{"en":"a pile of stones","cn":"一堆石块"}},{"en":"a piece of stone shaped for a particular purpose","cn":"（加工成某形状为某用途的）石块","g":"[countable]","sc":"hard substance","ex":{"en":"These words are carved on the stone beside his grave.","cn":"在他的墓碑上刻着这样的话。"}},{"en":"a rare valuable stone, such as a diamond, that is used in jewellery","cn":"宝石","g":"[countable]","sc":"jewel","ex":{"en":"She had the stone set in a ring.","cn":"她请人把宝石镶嵌在戒指上。"}},{"en":"a hard shell containing the nut or seed in the middle of some types of fruit","cn":"果核","g":"[countable]","lab":"especially British English","sc":"in fruit","ex":{"en":"cherry/peach stones","cn":"樱桃核；桃核"}},{"en":"a small piece of hard material that can form in the bladder or kidney and cause pain","cn":"（膀胱或肾脏中的）结石","g":"[countable]","sc":"in body","ex":{"en":"kidney stones","cn":"肾结石"}},{"en":"(in the UK) a unit for measuring weight, equal to 6.35 kilograms or 14 pounds","cn":"英石（英国重量单位，相当于 6.35 千克或 14 磅）","g":"[countable]","sc":"measurement of weight","ex":{"en":"He weighs over 15 stone.","cn":"他体重超过 15 英石。"}},{"en":"to throw stones at somebody/something","cn":"向…扔石块；用石头砸","sc":"throw stones","ex":{"en":"Shops were looted and vehicles stoned.","cn":"商店遭哄抢，车辆被砸坏。"},"pos":"verb"},{"en":"to remove the stone from the inside of a fruit","cn":"去掉…的果核","lab":"British English","sc":"fruit","ex":{"en":"stoned black olives","cn":"去核黑橄榄"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"石头;石料","en":"Stone is a hard solid substance found in the ground and often used for building houses.","ex":{"en":"He could not tell whether the floor was wood or stone","cn":"他无法确定地板是木头的还是石头的。"}},{"pos":"N-COUNT 可数名词","cn":"石子;小石块","en":"A stone is a small piece of rock that is found on the ground.","ex":{"en":"He removed a stone from his shoe","cn":"他从鞋子里倒出一块石子。"}},{"pos":"N-COUNT 可数名词","cn":"(作为宗教标志的)石碑;纪念碑","en":"A stone is a large piece of stone put somewhere in memory of a person or event, or as a religious symbol.","ex":{"en":"The monument consists of a circle of gigantic stones.","cn":"该遗址由一圈巨大的石碑组成。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(表示观念或规则固定而不可改变)板上钉钉，铁板钉钉","en":"Stone is used in expressions such as set in stone and tablets of stone to suggest that an idea or rule is firm and fixed, and cannot be changed.","ex":{"en":"He is merely throwing the idea forward for discussion, it is not cast in stone","cn":"他只是提出这个观点供讨论，它还没板上钉钉。"}},{"pos":"N-COUNT 可数名词","cn":"宝石","en":"You can refer to a jewel as a stone .","ex":{"en":"...a diamond ring with three stones.","cn":"镶有 3 颗钻石的戒指"}},{"pos":"N-COUNT 可数名词","cn":"结石","en":"A stone is a small hard ball of minerals and other substances which sometimes forms in a person's kidneys or gall bladder.","ex":{"en":"He had kidney stones.","cn":"他有肾结石。"}},{"pos":"N-COUNT 可数名词","cn":"果核","en":"The stone in a plum, cherry, or other fruit is the large hard seed in the middle of it."},{"pos":"VERB 动词","cn":"给…去核","en":"If you stone a fruit, you remove its stone.","ex":{"en":"Then stone the fruit and process the plums to a puree.","cn":"然后去核再将李子加工成糊状。"}},{"pos":"VERB 动词","cn":"向…扔石头;用石头砸","en":"If people stone someone or something, they throw stones at them.","ex":{"en":"Youths burned cars and stoned police","cn":"年轻人烧汽车，并向警察扔石头。"}},{"pos":"N-COUNT 可数名词","cn":"英石(重量单位，相当于 14 磅或6.35公斤)","en":"A stone is a measurement of weight, especially the weight of a person, equal to 14 pounds or 6.35 kilograms. →see usage note at:","ex":{"en":"I weighed around 16 stone.","cn":"我体重约为16英石。"}},{"pos":"PHRASE 短语","cn":"离…不远的;在…附近的","en":"If you say that one place is a stone's throw from another, you mean that the places are close to each other.","ex":{"en":"...a two-bedroom apartment just a stone's throw from the beach","cn":"离海滩只有几步之遥的一套两居室公寓"}},{"pos":"PHRASE 短语","cn":"挖空心思;千方百计;用尽一切手段","en":"If you say that you will leave no stone unturned, you are emphasizing that you will try every way you can think of in order to achieve what you want.","ex":{"en":"He said he would leave no stone unturned in the search for peace.","cn":"他说他会尽一切努力去寻求和平。"}},{"pos":"","cn":"","en":"kill two birds with one stone→see: ;"}]},"examples":[{"en":"People should remember that our proposals aren't set in stone.","cn":"人们应该记住我们的建议不是一成不变的。"},{"en":"Most of the houses are built of stone.","cn":"这些房子多数是用石头建造的。"}]},"strugglings":{"oxford":{"phon":"ˈstrʌɡl","pos":"verb","senses":[{"en":"to try very hard to do sth when it is difficult or when there are a lot of problems","cn":"奋斗；努力；争取"},{"en":"to move somewhere or do sth with difficulty","cn":"艰难地行进；吃力地进行"}]}},"stress":{"media":{"uk":"media/uk/stress__gb_1.mp3","us":"media/us/stress__us_1.mp3"},"oxford":{"phon":"stres","pos":"noun","senses":[{"en":"pressure or worry caused by problems in somebody’s life or by having too much to do","cn":"精神压力；心理负担；紧张","g":"[uncountable, countable]","lab":"British English","sc":"mental pressure","ex":{"en":"emotional/mental stress","cn":"情感／精神压力"}},{"en":"physical pressure put on something that can damage it or make it lose its shape","cn":"压力；应力","g":"[uncountable, countable]","sc":"physical pressure","ex":{"en":"When you have an injury you start putting stress on other parts of your body.","cn":"一旦受伤，你便会让身体其他部位受力。"}},{"en":"an extra force used when pronouncing a particular word or syllable","cn":"重音；重读","g":"[uncountable, countable]","lab":"phonetics","sc":"on word/syllable","ex":{"en":"We worked on pronunciation, stress and intonation.","cn":"我们学习了语音、重读和语调。"}},{"en":"special importance given to something","cn":"强调；重要性","g":"[uncountable]","sc":"emphasis","ex":{"en":"She lays great stress on punctuality.","cn":"她十分注重守时。"}},{"en":"extra force used when making a particular sound in music","cn":"加强（音）","g":"[uncountable, countable]","sc":"in music"},{"en":"illness caused by difficult physical conditions","cn":"环境恶劣引起的疾病","g":"[uncountable]","sc":"illness","ex":{"en":"Those most vulnerable to heat stress are the elderly.","cn":"上了年纪的人最容易因受热而生病。"}},{"en":"to give extra force to a word or syllable when saying it","cn":"重读；用重音读","g":"[transitive]","sc":"word/syllable","ex":{"en":"You stress the first syllable in ‘happiness’.","cn":"happiness 一词重读第一个音节。"},"pos":"verb"},{"en":"to emphasize a fact, an idea, etc.","cn":"强调；着重","g":"[transitive]","sc":"emphasize","ex":{"en":"He stressed the importance of a good education.","cn":"他强调了良好教育的重要性。"},"pos":"verb"},{"en":"to become or make somebody become too anxious or tired to be able to relax","cn":"（使）焦虑不安，疲惫不堪","g":"[intransitive, transitive]","sc":"worry","ex":{"en":"I just need to get some sleep and stop stressing.","cn":"我只需要睡一会儿并停止压力。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"强调;着重指出","en":"If you stress a point in a discussion, you put extra emphasis on it because you think it is important.","ex":{"en":"The spokesman stressed that the measures did not amount to an overall ban","cn":"该发言人强调这些措施并不等同于全面禁止。"}},{"pos":"N-VAR 可变名词","cn":"精神压力;心理负担;紧张","en":"If you feel under stress, you feel worried and tense because of difficulties in your life.","ex":{"en":"Katy could think clearly when not under stress","cn":"在没有精神压力的情况下凯蒂思路清晰。"}},{"pos":"N-VAR 可变名词","cn":"压力;应力","en":"Stresses are strong physical pressures applied to an object.","ex":{"en":"Earthquakes happen when stresses in rock are suddenly released as the rocks fracture.","cn":"当岩石碎裂时其承受的压力突然释放出来，地震就发生了。"}},{"pos":"VERB 动词","cn":"重读;用重音读","en":"If you stress a word or part of a word when you say it, you put emphasis on it so that it sounds slightly louder.","ex":{"en":"'Sit down,' she replied, stressing each word.","cn":"“坐下，”她一字一顿地说道。"}}]},"examples":[{"en":"She failed to withstand the stresses and strains of public life.","cn":"她承受不了作为一个公众人物的生活压力和紧张。"},{"en":"I think the company places too much stress on cost and not enough on quality.","cn":"我认为公司对成本强调有余，而对质量重视不足。"}]},"statues":{"oxford":{"phon":"ˈstætʃuː","pos":"noun","senses":[{"en":"a figure of a person or an animal in stone, metal, etc., usually the same size as in real life or larger","cn":"雕塑，雕像，塑像（大小通常等于或大于真人或实物）"}]}},"street":{"media":{"uk":"media/uk/street__gb_1.mp3","us":"media/us/street__us_1.mp3"},"oxford":{"phon":"striːt","pos":"noun","senses":[{"en":"a public road in a city or town that has houses and buildings on one side or both sides","cn":"大街；街道","g":"[countable]","lab":"British English","ex":{"en":"I was just walking along the street when it happened.","cn":"那事发生时我正走在大街上。"}},{"en":"the ideas and opinions of ordinary people, especially people who live in cities, which are considered important","cn":"（尤指城市里）街头民意","g":"[singular]","ex":{"en":"The feeling I get from the street is that we have a good chance of winning this election.","cn":"我从街头民意调查感觉到我们很有机会赢得这场选举。"}},{"en":"working, living or taking place on the streets of a city; based on the daily life of ordinary people in cities","cn":"街头的","g":"[only before noun]","ex":{"en":"street vendors selling fruit, snacks and local handicrafts","cn":"卖水果、小吃和当地手工艺品的街头小贩"},"pos":"adjective"},{"en":"showing or connected with the attitude and way of life of fashionable young people in cities","cn":"街头流行的；时髦的","ex":{"en":"London street style","cn":"伦敦街头风"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"大街;街道","en":"A street is a road in a city, town, or village, usually with houses along it.","ex":{"en":"He lived at 66 Bingfield Street","cn":"他住在宾菲尔德大街 66 号。"}},{"pos":"N-COUNT 可数名词","cn":"户外;街头","en":"You can use street or streets when talking about activities that happen out of doors in a town rather than inside a building.","ex":{"en":"Changing money on the street is illegal — always use a bank","cn":"在街头兑换货币是违法的——无论何时都应该去银行。"}},{"pos":"PHRASE 短语","cn":"(比…)好得多","en":"If someone is streets ahead of you, they are much better at something than you are.","ex":{"en":"He was streets ahead of the other contestants.","cn":"他比其他参赛选手水平高出一大截。"}},{"pos":"PHRASE 短语","cn":"普通人;平民百姓","en":"If you talk about the man in the street or the man or woman in the street, you mean ordinary people in general.","ex":{"en":"The average man or woman in the street doesn't know very much about immune disorders.","cn":"普通人一般不是很了解何谓免疫机能紊乱。"}},{"pos":"PHRASE 短语","cn":"中…的意;和…对口","en":"If a job or activity is up your street, it is the kind of job or activity that you are very interested in.","ex":{"en":"She loved it, this was just up her street.","cn":"她喜欢这个，这正中她的意。"}}]},"examples":[{"en":"The feeling I get from the street is that we have a good chance of winning this election.","cn":"我从街头民意调查感觉到我们很有机会赢得这场选举。"},{"en":"a country that is streets ahead in the control of environmental pollution","cn":"一个在整治环境污染方面远远走在前面的国家"}]},"studied":{"media":{"uk":"media/uk/studied__gb_1.mp3","us":"media/us/studied__us_1.mp3"},"oxford":{"phon":"ˈstʌdid","pos":"adjective","senses":[{"en":"deliberate and carefully planned","cn":"刻意的；精心安排的","ex":{"en":"She introduced herself with studied casualness.","cn":"她故作轻松地做了自我介绍。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"精心安排的;刻意的","en":"A studied action is deliberate or planned.","ex":{"en":"'We both have an interesting 10 days coming up,' said Alex Ferguson with studied understatement.","cn":"亚历克斯·弗格森故作轻描淡写地说：“我们都即将迎来愉快的 10 天。”"}}]},"examples":[{"en":"She introduced herself with studied casualness.","cn":"她故作轻松地做了自我介绍。"},{"en":"She spoke with studied politeness.","cn":"她说话的时候故意装得很客气。"}]},"stars":{"oxford":{"phon":"stɑː(r)","pos":"noun","senses":[{"en":"a large ball of burning gas in space that we see as a point of light in the sky at night","cn":"恒星；星"},{"en":"an object, a decoration, a mark, etc., usually with five or six points, whose shape represents a star","cn":"星状物；星形饰物；星号"}]}},"strip":{"media":{"uk":"media/uk/strip__gb_1.mp3","us":"media/us/strip__us_1.mp3"},"oxford":{"phon":"strɪp","pos":"noun","senses":[{"en":"a long narrow piece of paper, metal, cloth, etc.","cn":"（纸、金属、织物等）条，带","sc":"long, narrow piece","ex":{"en":"a strip of material","cn":"一块布条"}},{"en":"a long narrow area of land, sea, etc.","cn":"（陆地、海域等）狭长地带；带状水域","sc":"long, narrow piece","ex":{"en":"the Gaza Strip","cn":"加沙地带"}},{"en":"the uniform that is worn by the members of a sports team when they are playing","cn":"队服","g":"[usually singular]","lab":"British English","sc":"of sports team","ex":{"en":"Juventus in their famous black and white strip","cn":"身穿他们闻名遐迩的黑白条队服的尤文图斯队"}},{"en":"an act of taking your clothes off, especially in a sexually exciting way and in front of an audience","cn":"脱衣舞","g":"[usually singular]","sc":"taking clothes off","ex":{"en":"to do a strip","cn":"表演脱衣舞"}},{"en":"a street that has many shops, stores, restaurants, etc. along it","cn":"商业街","lab":"North American English","sc":"street","ex":{"en":"Sunset Strip","cn":"森塞特商业街"}},{"en":"a series of drawings inside boxes that tell a story and are often published in newspapers","cn":"（常登载于报纸上的）连环漫画","lab":"North American English","sc":"picture story"},{"en":"to take off all or most of your clothes or another person’s clothes","cn":"脱光衣服；脱掉大部分衣服；扒光…的衣服","g":"[intransitive, transitive]","sc":"take off clothes","ex":{"en":"I stripped and washed myself all over.","cn":"我脱掉衣服，把全身洗了洗。"},"pos":"verb"},{"en":"to take off your clothes as a form of entertainment; to perform a striptease","cn":"进行脱衣表演；表演脱衣舞","g":"[intransitive]","sc":"take off clothes","pos":"verb"},{"en":"to remove a layer from something, especially so that it is completely exposed","cn":"除去，剥去（一层）；（尤指）剥光","g":"[transitive]","sc":"remove layer","ex":{"en":"Strip off all the existing paint.","cn":"把现有的油漆全部刮掉。"},"pos":"verb"},{"en":"to remove all the things from a place and leave it empty","cn":"从（某处）拿走所有东西；使（某处）空无一物","g":"[transitive]","lab":"figurative","sc":"remove everything","ex":{"en":"We had to strip out all the old wiring and start again.","cn":"我们不得不将原有的线路全部拆除，从头再来。"},"pos":"verb"},{"en":"to separate a machine, etc. into parts so that they can be cleaned or repaired","cn":"拆卸；拆开","g":"[transitive]","sc":"machine","ex":{"en":"He strips and cleans his rifle every morning.","cn":"每天早上他都会脱下并清洁他的步枪。"},"pos":"verb"},{"en":"to take away property or honours from somebody, as a punishment","cn":"剥夺；褫夺","g":"[transitive]","sc":"punishment","ex":{"en":"He was disgraced and stripped of his title.","cn":"他名誉扫地，被取消了头衔。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(纸、布、食物等的)条，带","en":"A strip of something such as paper, cloth, or food is a long, narrow piece of it.","ex":{"en":"...a new kind of manufactured wood made by pressing strips of wood together and baking them","cn":"一种用木条压紧并烘烤而制成的新型人造木材"}},{"pos":"N-COUNT 可数名词","cn":"狭长区域;带状(陆地、水域)","en":"A strip of land or water is a long narrow area of it.","ex":{"en":"The coastal cities of Liguria sit on narrow strips of land lying under steep mountains.","cn":"利古里亚的沿海城市坐落在陡峭山脉下的狭长地带上。"}},{"pos":"N-COUNT 可数名词","cn":"商业街","en":"A strip is a long street in a city or town, where there are a lot of stores, restaurants, and hotels.","ex":{"en":"...Goff's Charcoal Hamburgers on Lover's Lane, a busy commercial strip in North Dallas.","cn":"位于北达拉斯的一条名为“情人巷”的繁华商业街上的戈夫炭烤汉堡店"}},{"pos":"VERB 动词","cn":"脱衣服","en":"If you strip, you take off your clothes.","ex":{"en":"They stripped completely, and lay in the damp grass","cn":"他们脱光衣服，躺在潮湿的草地上。"}},{"pos":"VERB 动词","cn":"脱掉…的衣服","en":"If someone is stripped, their clothes are taken off by another person, for example in order to search for hidden or illegal things.","ex":{"en":"One prisoner claimed he'd been dragged to a cell, stripped and beaten.","cn":"一名犯人声称他曾被拖进一间牢房，全身被脱光并遭到毒打。"}},{"pos":"VERB 动词","cn":"除去;剥去","en":"To strip something means to remove everything that covers it.","ex":{"en":"After Mike left for work I stripped the beds and vacuumed the carpets","cn":"迈克去上班后，我扯下了床罩并用吸尘器清扫地毯。"}},{"pos":"VERB 动词","cn":"拆卸，拆开(引擎或设备)","en":"If you strip an engine or a piece of equipment, you take it to pieces so that it can be cleaned or repaired.","ex":{"en":"Volvo's three-man team stripped the car and restored it.","cn":"沃尔沃公司的 3 人小组将车拆开进行了维修。"}},{"pos":"VERB 动词","cn":"剥夺，褫夺(财产、权利、头衔)","en":"To strip someone of their property, rights, or titles means to take those things away from them.","ex":{"en":"The soldiers have stripped the civilians of their passports, and every other type of document","cn":"士兵们已经夺走了平民的护照以及所有其他类型的证件。"}},{"pos":"N-COUNT 可数名词","cn":"连环漫画","en":"In a newspaper or magazine, a strip is a series of drawings which tell a story. The words spoken by the characters are often written on the drawings.","ex":{"en":"...the Doonesbury strip.","cn":"杜尼斯伯理政治漫画"}},{"pos":"PHRASE 短语","cn":"怒斥;痛骂;把…骂得狗血淋头","en":"If you tear a strip off someone or if you tear them off a strip, you speak to them angrily and criticize them severely.","ex":{"en":"He heard Nora tearing a strip off an orderly for not returning the food bins to the kitchen soon enough","cn":"他听到诺拉正在破口大骂一名勤务兵没有将食品箱及时送回厨房。"}},{"pos":"","cn":"","en":"相关词组：strip away strip down strip off"}]},"examples":[{"en":"We had to strip out all the old wiring and start again.","cn":"我们不得不将原有的线路全部拆除，从头再来。"},{"en":"The movie aims to strip away the lies surrounding Kennedy's life.","cn":"这部电影旨在揭穿有关肯尼迪生平的种种谎言。"}]},"standstill":{"media":{"uk":"media/uk/standstill__gb_1.mp3","us":"media/us/standstill__us_1.mp3"},"oxford":{"phon":"ˈstændstɪl","pos":"noun","senses":[{"en":"a situation in which all activity or movement has stopped","cn":"停止；停顿；停滞","ex":{"en":"The security alert brought the airport to a standstill.","cn":"安全警戒使机场陷入停顿状态。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"停止;停顿;停滞","en":"If movement or activity comes to or is brought to a standstill, it stops completely.","ex":{"en":"Abruptly the group ahead of us came to a standstill","cn":"我们前面的小组突然停了下来。"}}]},"examples":[{"en":"The security alert brought the airport to a standstill.","cn":"安全警戒使机场陷入停顿状态。"},{"en":"Traffic in the northbound lane is at a complete standstill.","cn":"北行车道的交通完全堵塞。"}]},"string":{"media":{"img":["media/pic/rope_comp.jpg","media/thumb/string.jpg"],"uk":"media/uk/string__gb_1.mp3","us":"media/us/string__us_1.mp3"},"oxford":{"phon":"strɪŋ","pos":"noun","senses":[{"en":"long, thin material used for tying things together, made of several threads that have been twisted together; a piece of string used to fasten or pull something or keep something in place","cn":"细绳；线；带子","g":"[uncountable, countable]","sc":"for tying/fastening","ex":{"en":"a piece/length/ball of string","cn":"一根／一段／一团细绳"}},{"en":"a set or series of things that are joined together, for example on a string","cn":"一串","g":"[countable]","sc":"things joined","ex":{"en":"a string of pearls","cn":"一串珍珠"}},{"en":"a series of things or people that come closely one after another","cn":"一系列；一连串；一批","g":"[countable]","sc":"series","ex":{"en":"The band had a string of hits in the nineties.","cn":"该乐队在 90 年代有一系列热门单曲。"}},{"en":"a series of characters (= letters, numbers, etc.)","cn":"字符串","g":"[countable]","sc":"computing","ex":{"en":"to key in/enter a search string","cn":"键入／输入搜索字符串"}},{"en":"a tightly stretched piece of wire, nylon, or catgut on a musical instrument, that produces a musical note when the instrument is played","cn":"弦","g":"[countable]","sc":"musical instruments","ex":{"en":"Play it on the G string.","cn":"以 G 弦演奏。"}},{"en":"the group of musical instruments in an orchestra that have strings, for example violins; the people who play them","cn":"（管弦乐团的）弦乐器，弦乐器组","g":"[plural]","sc":"musical instruments","ex":{"en":"The opening theme is taken up by the strings.","cn":"开始的主旋律由弦乐继续发展。"}},{"en":"any of the tightly stretched pieces of nylon or natural gut in a racket, used for hitting balls in tennis and some other sports","cn":"弦","g":"[countable]","sc":"on tennis racket"},{"en":"special conditions or limits","cn":"特定条件（或限制）","g":"[plural]","sc":"conditions","ex":{"en":"Major loans like these always come with strings.","cn":"诸如此类的大宗贷款总有一些附带条件。"}},{"en":"to hang or tie something in place, especially as decoration","cn":"悬挂；系；扎","sc":"hang decoration","ex":{"en":"We strung paper lanterns up in the trees.","cn":"我们把纸灯笼挂在树上。"},"pos":"verb"},{"en":"to put a series of small objects on string, etc.; to join things together with string, etc.","cn":"用线（或细绳等）串，把…连在一起","lab":"figurative","sc":"join things","ex":{"en":"She had strung the shells on a silver chain.","cn":"她把贝壳串在一条银链子上。"},"pos":"verb"},{"en":"to put a string or strings on a racket or musical instrument","cn":"给…装弦","sc":"racket/musical instrument","pos":"verb"},{"en":"consisting of musical instruments that have strings; connected with these musical instruments","cn":"由弦乐器组成的；弦乐器的","sc":"musical instrument","ex":{"en":"a string quartet","cn":"弦乐四重奏"},"pos":"adjective"},{"en":"made of string or something like string","cn":"线织的；线的","sc":"made of string","ex":{"en":"a string bag/vest","cn":"网兜；网眼背心"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"细绳;线","en":"String is thin rope made of twisted threads, used for tying things together or tying up parcels.","ex":{"en":"He held out a small bag tied with string.","cn":"他拿出一个系着细绳的小袋子。"}},{"pos":"N-COUNT 可数名词","cn":"一串","en":"A string of things is a number of them on a piece of string, thread, or wire.","ex":{"en":"She wore a string of pearls around her neck.","cn":"她脖子上戴着一串珍珠。"}},{"pos":"N-COUNT 可数名词","cn":"一行;一列;一排","en":"A string of places or objects is a number of them that form a line.","ex":{"en":"The landscape is broken only by a string of villages","cn":"这片风景中只有一排村庄。"}},{"pos":"N-COUNT 可数名词","cn":"一系列，一连串(类似事件)","en":"A string of similar events is a series of them that happen one after the other.","ex":{"en":"The incident was the latest in a string of attacks","cn":"这是一连串袭击事件中最近的一起。"}},{"pos":"N-COUNT 可数名词","cn":"(乐器的)弦","en":"The strings on a musical instrument such as a violin or guitar are the thin pieces of wire or nylon stretched across it that make sounds when the instrument is played.","ex":{"en":"He went off to change a guitar string.","cn":"他出去换一根吉他弦。"}},{"pos":"N-PLURAL 复数名词","cn":"(管弦乐团的)弦乐器，弦乐器组","en":"The strings are the section of an orchestra which consists of stringed instruments played with a bow.","ex":{"en":"The strings provided a melodic background to the passages played by the soloist","cn":"弦乐组为独奏乐章配上了动听的背景乐。"}},{"pos":"N-COUNT 可数名词","cn":"(计算机技术中的)字符串，信息串","en":"In computing, a string is a particular series of letters, numbers, symbols, or spaces, for example a word or phrase that you want to search for in a document."},{"pos":"VERB 动词","cn":"悬挂;系;扎","en":"If you string something somewhere, you hang it up between two or more objects.","ex":{"en":"He had strung a banner across the wall.","cn":"他在墙上挂了条横幅。"}},{"pos":"PHRASE 短语","cn":"另有一手;两手准备","en":"If someone has more than one string to their bow, they have more than one ability or thing they can use if the first one they try is not successful.","ex":{"en":"I'm never out of work because I have so many strings to my bow.","cn":"我会很多手艺，永远都不会没饭吃。"}},{"pos":"PHRASE 短语","cn":"不带附加条件;无任何限制","en":"If something is offered to you with no strings attached or with no strings, it is offered without any special conditions.","ex":{"en":"Aid should be given to developing countries with no strings attached.","cn":"应该不带任何附加条件地向发展中国家提供援助。"}},{"pos":"PHRASE 短语","cn":"拉关系;走后门","en":"If you pull strings, you use your influence with other people in order to get something done, often unfairly.","ex":{"en":"Tony is sure he can pull a few strings and get you in.","cn":"托尼有把握可以托关系让你进去。"}},{"pos":"","cn":"","en":"apron strings→see: ;"},{"pos":"","cn":"","en":"相关词组：string along string together string up"}]},"examples":[{"en":"It's a business proposition, pure and simple. No strings attached.","cn":"这只是个业务建议，仅此而已。没有任何附带条件。"},{"en":"He wrapped the package in brown paper and tied it with string.","cn":"他用棕色包装纸把包裹包好，又用细绳捆上。"}]},"stomach":{"media":{"uk":"media/uk/stomach__gb_1.mp3","us":"media/us/stomach__us_1.mp3","img":["media/ldoce/img/body.jpg"]},"oxford":{"phon":"ˈstʌmək","pos":"noun","senses":[{"en":"the organ inside the body where food goes when you eat it","cn":"胃","lab":"British English also","ex":{"en":"stomach pains/cramps","cn":"胃疼；胃绞痛"}},{"en":"the front part of the body below the chest","cn":"肚子；腹部","ex":{"en":"The attacker kicked him in the stomach.","cn":"袭击者一脚踢在他肚子上。"}},{"en":"to approve of something and be able to enjoy it; to enjoy being with a person","cn":"欣赏；欣然接受；喜欢和…相处","ex":{"en":"I can't stomach violent films.","cn":"我不喜欢暴力片。"},"pos":"verb"},{"en":"to be able to eat something without feeling sick","cn":"能吃；吃得下","ex":{"en":"She couldn't stomach any breakfast.","cn":"她早上什么都吃不下。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胃","en":"Your stomach is the organ inside your body where food is digested before it moves into the intestines.","ex":{"en":"He had an upset stomach","cn":"他胃不舒服。"}},{"pos":"N-COUNT 可数名词","cn":"肚子;腹部","en":"You can refer to the front part of your body below your waist as your stomach .","ex":{"en":"The children lay down on their stomachs.","cn":"孩子们趴着躺下。"}},{"pos":"N-COUNT 可数名词","cn":"心窝;内脏","en":"If the front part of your body below your waist feels uncomfortable because you are feeling worried or frightened, you can refer to it as your stomach .","ex":{"en":"His stomach was in knots.","cn":"他的五脏六腑都揪在一起了。"}},{"pos":"N-COUNT 可数名词","cn":"(对令人反胃的东西的)承受能力","en":"If you say that someone has a strong stomach, you mean that they are not disgusted by things that disgust most other people.","ex":{"en":"Surgery often demands actual physical strength, as well as the possession of a strong stomach.","cn":"做外科手术常常要求有真正的体力和很强的承受恶心反胃的能力。"}},{"pos":"VERB 动词","cn":"忍受;忍耐","en":"If you cannot stomach something, you cannot accept it because you dislike it or disapprove of it.","ex":{"en":"I could never stomach the cruelty involved in the wounding of animals.","cn":"我永远都无法忍受伤害动物时的那种残忍。"}},{"pos":"PHRASE 短语","cn":"空腹地","en":"If you do something on an empty stomach, you do it without having eaten.","ex":{"en":"Avoid drinking on an empty stomach.","cn":"不要空腹饮酒。"}},{"pos":"PHRASE 短语","cn":"没有勇气;不敢","en":"If you have no stomach for something, you do not have the courage to do it.","ex":{"en":"America has no stomach for a fight","cn":"美国不敢打仗。"}},{"pos":"PHRASE 短语","cn":"非常生气;很反感","en":"If you say that you feel sick to your stomach about something, you mean that you feel very angry or upset about it.","ex":{"en":"She felt sick to her stomach just thinking about it.","cn":"她一想到这事就气不打一处来。"}},{"pos":"PHR-ERG","cn":"令人倒胃口;使人感到恶心","en":"If you say that something turns your stomach or makes your stomach turn, you mean that it is so unpleasant or offensive that it makes you feel sick.","ex":{"en":"The true facts will turn your stomach","cn":"真相会不堪入目。"}},{"pos":"","cn":"","en":"butterflies in your stomach→see: ;"}]},"examples":[{"en":"Pictures of the burnt corpses turned my stomach.","cn":"那些烧焦的尸体的照片让我直恶心。"},{"en":"The attacker kicked him in the stomach.","cn":"袭击者一脚踢在他肚子上。"}]},"stiff":{"media":{"uk":"media/uk/stiff__gb_1.mp3","us":"media/us/stiff__us_1.mp3"},"oxford":{"phon":"stɪf","pos":"adjective","senses":[{"en":"difficult to bend or move","cn":"不易弯曲（或活动）的","sc":"difficult to bend/move","ex":{"en":"a sheet of stiff black cardboard","cn":"一张黑色硬纸板"}},{"en":"when a person or a part of their body is stiff, their muscles hurt when they move them","cn":"僵硬的；一动就疼的","sc":"muscles","ex":{"en":"I'm really stiff after that bike ride yesterday.","cn":"昨天骑了那趟自行车，我觉得浑身酸痛。"}},{"en":"thick; difficult to stir (= move around with a spoon)","cn":"稠的；难搅动的","sc":"mixture","ex":{"en":"Whisk the egg whites until stiff.","cn":"把蛋清打稠。"}},{"en":"more difficult or severe than usual","cn":"困难的；艰难的；严厉的；激烈的","sc":"difficult/severe","ex":{"en":"It was a stiff climb to the top of the hill.","cn":"费了好大劲才爬到山顶。"}},{"en":"not friendly or relaxed","cn":"不友好的；生硬的","sc":"not friendly","ex":{"en":"The speech he made to welcome them was stiff and formal.","cn":"他那番欢迎他们的话讲得生硬刻板。"}},{"en":"costing a lot or too much","cn":"高昂的；过高的","lab":"informal","sc":"price","ex":{"en":"There's a stiff $30 entrance fee to the exhibition.","cn":"展览会的入场费高达 30 美元。"}},{"en":"strong; containing a lot of alcohol","cn":"烈性的；酒精度数高的","g":"[only before noun]","sc":"alcoholic drink","ex":{"en":"a stiff whisky","cn":"烈性威士忌"}},{"en":"very much; to an extreme degree","cn":"非常；极其","lab":"informal","ex":{"en":"be bored/scared/worried stiff","cn":"非常厌烦／害怕／担心"},"pos":"adverb"},{"en":"very cold and hard because the water has become ice","cn":"（冻）僵；（冻）硬","lab":"figurative","ex":{"en":"The clothes on the washing line were frozen stiff.","cn":"挂在晾衣绳上的衣服冻硬了。"},"pos":"adverb"},{"en":"the body of a dead person","cn":"死尸","pos":"noun"},{"en":"to cheat somebody or not pay them what you owe them, especially by not leaving any money as a tip","cn":"诈骗；不还钱；（尤指）不给小费","ex":{"en":"These people are taxed on the tips they make. When you stiff ’em, you cost them money.","cn":"这些人根据自己的小费纳税。当你僵化他们时，你就损失了他们的钱。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"硬的;不易弯曲的","en":"Something that is stiff is firm or does not bend easily.","ex":{"en":"The furniture was stiff, uncomfortable, too delicate, and too neat","cn":"家具又硬又不舒服，太不结实而且太小巧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(门、抽屉等)难打开的，不灵活的，发紧的","en":"Something such as a door or drawer that is stiff does not move as easily as it should.","ex":{"en":"Train doors have handles on the inside. They are stiff so that they cannot be opened accidentally.","cn":"火车车门内侧有把手。把手都很紧，防止意外开启。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(肌肉或关节)酸痛的，僵硬的","en":"If you are stiff, your muscles or joints hurt when you move, because of illness or because of too much exercise.","ex":{"en":"The Mud Bath is particularly recommended for relieving tension and stiff muscles","cn":"特别推荐想要放松情绪、缓解肌肉酸痛的人泡泥浆浴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)拘谨的，生硬的，不太友好的","en":"Stiff behaviour is rather formal and not very friendly or relaxed.","ex":{"en":"She looked at him with a stiff smile","cn":"她看着他，脸上挤出生硬的一笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"艰难的;严厉的;激烈的","en":"Stiff can be used to mean difficult or severe.","ex":{"en":"The film faces stiff competition for the Best Film nomination","cn":"这部电影在角逐最佳影片提名时面临着激烈的竞争。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(酒)烈性的，酒精度数高的","en":"A stiff drink is a large amount of a strong alcoholic drink.","ex":{"en":"...a stiff whisky.","cn":"一杯烈性的威士忌"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(风)强劲的，猛烈的","en":"A stiff wind is blowing quite strongly.","ex":{"en":"Next morning dawned clear and sunny, with a stiff breeze rustling the trees.","cn":"次日一大早,天空晴朗无云，大风吹得树木沙沙作响。"}},{"pos":"ADV 副词","cn":"十分;极其;完全","en":"If you are bored stiff, worried stiff, or scared stiff, you are extremely bored, worried, or scared.","ex":{"en":"Anna tried to look interested. Actually, she was bored stiff","cn":"安娜努力装出感兴趣的样子。实际上，她腻烦透了。"}},{"pos":"","cn":"","en":"stiff upper lip→see: ;"}]},"examples":[{"en":"I'm really stiff after that bike ride yesterday.","cn":"昨天骑了那趟自行车，我觉得浑身酸痛。"},{"en":"The speech he made to welcome them was stiff and formal.","cn":"他那番欢迎他们的话讲得生硬刻板。"}]},"stressed":{"media":{"uk":"media/uk/stressed__gb_1.mp3","us":"media/us/stressed__us_1.mp3"},"oxford":{"phon":"strest","pos":"adjective","senses":[{"en":"too anxious and tired to be able to relax","cn":"焦虑不安；心力交瘁","g":"[not before noun]","lab":"informal","ex":{"en":"He was feeling very stressed and tired.","cn":"他感觉十分焦虑，疲惫不堪。"}},{"en":"pronounced with emphasis","cn":"重读的"},{"en":"that has had a lot of physical pressure put on it","cn":"受压的；受应力的","g":"[only before noun]","lab":"specialist","ex":{"en":"stressed metal","cn":"受压金属"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"焦虑不安的;心力交瘁的","en":"If you are stressed, you feel tense and anxious because of difficulties in your life.","ex":{"en":"Work out what situations or people make you feel stressed and avoid them.","cn":"弄清是什么状况或什么人让你焦虑不安，然后避开他们。"}},{"pos":"ADJ 形容词","cn":"受重压的;受应力的","en":"A stressed object is affected by strong physical pressure which has been applied to it.","ex":{"en":"...stressed metal.","cn":"受压金属"}},{"pos":"ADJ 形容词","cn":"重读的","en":"If a word or part of a word is stressed, it is pronounced with emphasis."}]},"examples":[{"en":"stressed metal","cn":"受压金属"},{"en":"I always eat when I’m feeling stressed.","cn":"我总是一紧张就吃东西。"}]},"stamp":{"oxford":{"phon":"stæmp","pos":"noun","senses":[{"en":"a small piece of paper with a design on it that you buy and stick on an envelope or a package before you post it","cn":"邮票","g":"[countable]","lab":"formal","sc":"on letter/package","ex":{"en":"a 67p stamp","cn":"一枚 67 便士的邮票"}},{"en":"a tool for printing the date or a design or mark onto a surface","cn":"印；章；戳","g":"[countable]","sc":"printing tool","ex":{"en":"a date stamp","cn":"日期戳"}},{"en":"a design or words made by stamping something onto a surface","cn":"印记；戳记","g":"[countable]","lab":"figurative","sc":"printed design/words","ex":{"en":"The passports, with the visa stamps, were waiting at the embassy.","cn":"那些护照都加盖了签证章，在大使馆等待领取。"}},{"en":"a small piece of paper with a design on it, stuck on a document to show that a particular amount of money has been paid","cn":"印花","g":"[countable]","sc":"proof of payment","ex":{"en":"a TV licence stamp","cn":"电视收视许可证印花"}},{"en":"the mark or sign of a particular quality or person","cn":"特征；痕迹；烙印","g":"[singular]","lab":"formal","sc":"character/quality","ex":{"en":"All his work bears the stamp of authority.","cn":"他的一切工作都具有权威性。"}},{"en":"a kind or class, especially of people","cn":"类型，种类（尤指人）","g":"[singular]","lab":"formal","sc":"character/quality","ex":{"en":"men of a different stamp","cn":"另一类人"}},{"en":"an act or sound of stamping the foot","cn":"跺脚（声）；跺蹄（声）","g":"[singular]","sc":"of foot","ex":{"en":"The stamp of hoofs alerted Isabel.","cn":"马蹄声引起了伊莎贝尔的警觉。"}},{"en":"to put your foot down heavily and noisily on the ground","cn":"跺（脚）；重踩；重踏","g":"[transitive, intransitive]","sc":"foot","ex":{"en":"I tried stamping my feet to keep warm.","cn":"我跺了一阵脚想暖和暖和。"},"pos":"verb"},{"en":"to walk with loud heavy steps","cn":"迈着重重的步伐走","g":"[intransitive]","sc":"walk","ex":{"en":"She turned and stamped out of the room.","cn":"她扭身嗵嗵地走出了房间。"},"pos":"verb"},{"en":"to print letters, words, a design, etc. onto something using a special tool","cn":"在…上盖（字样或图案等）；把（字样或图案等）盖在…上","g":"[transitive, often passive]","lab":"figurative","sc":"print design/words","ex":{"en":"The box was stamped with the maker's name.","cn":"盒子上盖有制作者的印章。"},"pos":"verb"},{"en":"to make a feeling show clearly on somebody’s face, in their actions, etc.","cn":"显示出（感情）","g":"[transitive, usually passive]","sc":"show feeling/quality","ex":{"en":"Their faces were stamped with hostility.","cn":"他们的神情充满敌意。"},"pos":"verb"},{"en":"to show that somebody has a particular quality","cn":"表明（某人）是…","g":"[transitive]","sc":"show feeling/quality","ex":{"en":"Her success has stamped her as one of the country's top riders.","cn":"她的成功表明她是全国最出色的骑手之一。"},"pos":"verb"},{"en":"to stick a stamp on a letter or package","cn":"在…上贴邮票","g":"[transitive, usually passive]","sc":"on letter/package","pos":"verb"},{"en":"to cut and shape an object from a piece of metal or plastic using a special machine or tool","cn":"冲压","g":"[transitive]","sc":"cut out object","ex":{"en":"The hinges are stamped out of sheets of metal.","cn":"铰链由金属板冲压而成。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"邮票","en":"A stamp or a postage stamp is a small piece of paper which you lick and stick on an envelope or package before you post it to pay for the cost of the postage.","ex":{"en":"...a book of stamps","cn":"邮票册"}},{"pos":"N-COUNT 可数名词","cn":"印章;图章;印记;戳记","en":"A stamp is a small block of wood or metal which has a pattern or a group of letters on one side. You press it onto an pad of ink and then onto a piece of paper in order to produce a mark on the paper. The mark that you produce is also called a stamp .","ex":{"en":"...a date stamp and an ink pad","cn":"日期章和印台"}},{"pos":"VERB 动词","cn":"盖(章);打(戳记)","en":"If you stamp a mark or word on an object, you press the mark or word onto the object using a stamp or other device.","ex":{"en":"Car manufacturers stamp a vehicle identification number at several places on new cars to help track down stolen vehicles","cn":"汽车制造商在新车的好几处地方打上车辆识别号码，以便于追查被偷车辆。"}},{"pos":"VERB 动词","cn":"(因生气、双脚发冷等)跺(脚)","en":"If you stamp or stamp your foot, you lift your foot and put it down very hard on the ground, for example because you are angry or because your feet are cold.","ex":{"en":"Often he teased me till my temper went and I stamped and screamed, feeling furiously helpless","cn":"他经常和我开玩笑，直到我生气地跺脚尖叫，却又无可奈何。"}},{"pos":"VERB 动词","cn":"(因生气)跺着脚走，噔噔地走","en":"If you stamp somewhere, you walk there putting your feet down very hard on the ground because you are angry.","ex":{"en":"'I'm going before things get any worse!' he shouted as he stamped out of the bedroom","cn":"“我要走了，省得看见事情变得更糟！”他大叫着，噔噔地走出了卧室。"}},{"pos":"VERB 动词","cn":"用力踩;使劲踏","en":"If you stamp on something, you put your foot down on it very hard.","ex":{"en":"He received the original ban last week after stamping on the referee's foot during the supercup final.","cn":"他在超级杯决赛中踩踏裁判的脚后，于上周收到了书面的禁赛通知。"}},{"pos":"N-SING 单数名词","cn":"特征;痕迹;烙印","en":"If something bears the stamp of a particular quality or person, it clearly has that quality or was done by that person.","ex":{"en":"...lawns and flowerbeds that bore the stamp of years of confident care","cn":"显然多年来一直受到精心照料的草地和花床"}},{"pos":"VERB 动词","cn":"表明;显示出","en":"A quality, feature, or action that stamps someone or something as a particular thing shows clearly that they are this thing.","ex":{"en":"I talked to social workers and the police — that had stamped me as a bad woman","cn":"我和社会福利工作者及警方都谈过话——因此我便成了坏女人。"}},{"pos":"See also:","cn":"","en":"stamp of approval→see: ;"},{"pos":"","cn":"","en":"相关词组：stamp on stamp out"}]},"media":{"uk":"media/uk/stamp__gb_1.mp3","us":"media/us/stamp__us_1.mp3","img":["media/ldoce/img/ink_pad.jpg"]},"examples":[{"en":"All attempts at modernization were stamped on by senior officials.","cn":"旨在实现现代化的努力统统受到高级官员的压制。"},{"en":"The passports, with the visa stamps, were waiting at the embassy.","cn":"那些护照都加盖了签证章，在大使馆等待领取。"}]},"strips":{"oxford":{"phon":"strɪp","pos":"verb","senses":[{"en":"to take off all or most of your clothes or another person's clothes","cn":"脱光衣服；脱掉大部分衣服；扒光 … 的衣服"},{"en":"to take off your clothes as a form of entertainment; to perform a striptease","cn":"进行脱衣表演；表演脱衣舞"}]},"media":{"uk":"media/uk/strip__gb_1.mp3","us":"media/us/strip__us_1.mp3"}},"statement":{"media":{"uk":"media/uk/statement__gb_1.mp3","us":"media/us/statement__us_1.mp3"},"oxford":{"phon":"ˈsteɪtmənt","pos":"noun","senses":[{"en":"something that you say or write that gives information or an opinion","cn":"说明；说法；表白；表态","g":"[countable]","ex":{"en":"Are the following statements true or false?","cn":"下面的说法对不对？"}},{"en":"a formal or official account of facts or opinions","cn":"声明；陈述；报告","g":"[countable]","ex":{"en":"a joint/a written/an official statement","cn":"联合／书面／官方声明"}},{"en":"a printed record of money paid, received, etc.","cn":"结算单；清单；报表","g":"[countable]","ex":{"en":"The directors are responsible for preparing the company's financial statements.","cn":"几位总监负责填写公司的财务报表。"}},{"en":"a clear expression of an opinion or attitude that you make through your actions or appearance","cn":"（意见或态度的）表现，表达","g":"[countable, usually singular]","ex":{"en":"They decided to make a political statement by refusing to vote.","cn":"他们决定把拒绝投票作为一种政治声明。"}},{"en":"(in England and Wales) an official report on a child’s special needs made by a local education authority","cn":"（英格兰和威尔士地方教育部门针对儿童的特殊需求提供的）评估报告","g":"[countable]","ex":{"en":"a statement of special educational needs","cn":"特殊教育需求评估报告"}},{"en":"the act of stating or expressing something in words","cn":"（文字）陈述，表述","g":"[uncountable]","lab":"formal","ex":{"en":"When writing instructions, clarity of statement is the most important thing.","cn":"编写操作说明时，表述清晰明白至为重要。"}},{"en":"(in England and Wales) to officially decide and report that a child has special needs for his or her education","cn":"（英格兰和威尔士）对（儿童）做特殊教育需求评估","ex":{"en":"statemented children","cn":"评估认定须接受特殊教育的学童"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(正式或明确的口头或书面)陈述，声明","en":"A statement is something that you say or write which gives information in a formal or definite way.","ex":{"en":"Andrew now disowns that statement, saying he was depressed when he made it","cn":"安德鲁现在推翻了那个说法，说那是自己在情绪低落时说的话。"}},{"pos":"N-COUNT 可数名词","cn":"(为某一场合特别发表的)官方声明，正式声明","en":"A statement is an official or formal announcement that is issued on a particular occasion.","ex":{"en":"The statement by the military denied any involvement in last night's attack.","cn":"军方发表声明称其和昨晚的袭击无任何关系。"}},{"pos":"N-COUNT 可数名词","cn":"(嫌疑人或证人向警方提供的)陈述，证词","en":"You can refer to the official account of events which a suspect or a witness gives to the police as a statement .","ex":{"en":"The 350-page report was based on statements from witnesses to the events.","cn":"这份 350 页的报告是根据各位证人对这些事件的证词写成的。"}},{"pos":"N-COUNT 可数名词","cn":"(意见或观点的)表现，表达","en":"If you describe an action or thing as a statement, you mean that it clearly expresses a particular opinion or idea that you have.","ex":{"en":"The following recipe is a statement of another kind—food is fun!","cn":"下面的食谱是另一种观点的表现——食物可以带来乐趣！"}},{"pos":"N-COUNT 可数名词","cn":"财务报表;结算单","en":"A printed document showing how much money has been paid into and taken out of a bank or building society account is called a statement ."},{"pos":"VERB 动词","cn":"证明(儿童)有特殊教育需求","en":"If a child is statemented, social services staff write a document stating that the child has special educational needs, and the local education authority has to make sure that everything that is necessary is provided for that child.","ex":{"en":"Nearly a year later, it was agreed that Tom would be statemented","cn":"近一年后，汤姆被批准将获得特殊教育。"}}]},"examples":[{"en":"The cleaning staff extended their strike mainly to make a statement about how determined they were.","cn":"清洁工人延长了罢工时间，主要目的是表明他们的决心。"},{"en":"The prime minister is expected to issue a statement on the policy change this afternoon.","cn":"人们预计首相将在今天下午就政策的改变发表声明。"}]},"stage":{"media":{"uk":"media/uk/stage__gb_1.mp3","us":"media/us/stage__us_1.mp3"},"oxford":{"phon":"steɪdʒ","pos":"noun","senses":[{"en":"a period or state that something/somebody passes through while developing or making progress","cn":"（发展或进展的）时期，阶段，状态","g":"[countable]","sc":"period/state","ex":{"en":"I can't make a decision at this stage.","cn":"在现阶段我还不能做决定。"}},{"en":"a separate part that a process, etc. is divided into","cn":"段；步；步骤","g":"[countable]","sc":"part of process","ex":{"en":"We did the first stage of the trip by train.","cn":"旅行的第一段我们乘的是火车。"}},{"en":"a raised area, usually in a theatre, etc. where actors, dancers, etc. perform","cn":"（多指剧场中的）舞台","g":"[countable]","sc":"theatre","ex":{"en":"There were more than 50 people on stage in one scene.","cn":"有一场戏中舞台上的人有 50 多个。"}},{"en":"the theatre and the world of acting as a form of entertainment","cn":"戏剧；戏剧表演；戏剧界","g":"[singular]","sc":"theatre","ex":{"en":"The screenplay was originally written for the stage.","cn":"剧本最初是为舞台而写的。"}},{"en":"an area of activity where important things happen, especially in politics","cn":"（政治等活动的）领域；（政治）舞台","g":"[singular]","sc":"in politics","ex":{"en":"She was forced to the centre of the political stage.","cn":"她被推到了政治舞台的中心。"}},{"en":"a stagecoach (= a large carriage pulled by horses that was used in the past to carry passengers, and often mail, along a regular route)","cn":"（旧时的）驿站马车，公共马车","g":"[countable]","lab":"old-fashioned, informal，，","sc":"carriage"},{"en":"to organize and present a play or an event for people to see","cn":"上演；举办；举行","ex":{"en":"to stage a play/an event/an exhibition","cn":"举办戏剧表演／活动／展览"},"pos":"verb"},{"en":"to organize and take part in action that needs careful planning, especially as a public protest","cn":"组织；筹划","ex":{"en":"to stage a protest/demonstration/rally","cn":"组织抗议／示威／集会"},"pos":"verb"},{"en":"to make something happen","cn":"使发生；使出现","ex":{"en":"The dollar staged a recovery earlier today.","cn":"今天早些时候，美元出现回升。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(活动、过程或时期的)阶段，部分","en":"A stage of an activity, process, or period is one part of it.","ex":{"en":"The way children talk about or express their feelings depends on their age and stage of development","cn":"儿童谈论或表达自己感情的方式取决于他们的年龄和所处的发育阶段。"}},{"pos":"N-COUNT 可数名词","cn":"舞台;戏台","en":"In a theatre, the stage is an area where actors or other entertainers perform.","ex":{"en":"The road crew needed more than 24 hours to move and rebuild the stage after a concert","cn":"一场音乐会结束后，巡回乐队管理组需要用一天多时间搬走和重新搭起舞台。"}},{"pos":"N-SING 单数名词","cn":"舞台表演;戏剧演出","en":"You can refer to acting and the production of plays in a theatre as the stage .","ex":{"en":"Madge did not want to put her daughter on the stage","cn":"玛奇不想让自己的女儿从事戏剧表演。"}},{"pos":"VERB 动词","cn":"组织上演(戏剧、演出等)","en":"If someone stages a play or other show, they organize and present a performance of it.","ex":{"en":"Maya Angelou first staged the play 'And I Still Rise' in the late 1970s.","cn":"马娅·安杰卢在 20 世纪 70 年代后期第一次将戏剧《我还会站起来》搬上了舞台。"}},{"pos":"VERB 动词","cn":"组织(活动或仪式)","en":"If you stage an event or ceremony, you organize it and usually take part in it.","ex":{"en":"Russian workers have staged a number of strikes in protest at the republic's declaration of independence","cn":"俄罗斯工人已经举行了数次罢工，抗议该共和国宣布独立。"}},{"pos":"N-SING 单数名词","cn":"(尤指政治)舞台，活动领域","en":"You can refer to a particular area of activity as a particular stage, especially when you are talking about politics.","ex":{"en":"He was finally forced off the political stage last year by the deterioration of his physical condition","cn":"他最终因身体状况恶化被迫于去年离开了政治舞台。"}},{"pos":"","cn":"","en":"to set the stage→see: ;"}]},"examples":[{"en":"Don't worry about the baby not wanting to leave you — it's a stage they go through.","cn":"宝宝不肯离开你别担心，他们总要经过这个阶段。"},{"en":"At one stage it looked as though they would win.","cn":"有一段时间，他们好像大有获胜的希望。"}]},"step":{"media":{"uk":"media/uk/step__gb_1.mp3","us":"media/us/step__us_1.mp3","img":["media/ldoce/img/staircase.jpg"]},"oxford":{"phon":"step","pos":"noun","senses":[{"en":"one of a series of things that you do in order to achieve something","cn":"步骤；措施","g":"[countable]","sc":"in series/process","ex":{"en":"We are taking steps to prevent pollution.","cn":"我们正在采取措施防止污染。"}},{"en":"one of a series of things that somebody does or that happen, which forms part of a process","cn":"步；阶段","g":"[countable]","sc":"in series/process","ex":{"en":"Having completed the first stage, you can move on to step 2.","cn":"第一阶段完成后，你就可以接着进行第二步了。"}},{"en":"the act of lifting your foot and putting it down in order to walk or move somewhere; the sound this makes","cn":"迈步；脚步声","g":"[countable]","sc":"movement/sound","ex":{"en":"a baby’s first steps","cn":"婴儿学步"}},{"en":"the distance that you cover when you take a step","cn":"一步（的距离）","g":"[countable]","lab":"figurative","sc":"distance","ex":{"en":"It's only a few steps further.","cn":"再走几步就到了。"}},{"en":"a surface that you put your foot on in order to walk to a higher or lower level, especially one of a series","cn":"台阶；梯级","g":"[countable]","sc":"stair","ex":{"en":"She was sitting on the bottom step of the staircase.","cn":"她正坐在最下面一级楼梯上。"}},{"en":"a series of movements that you make with your feet and which form a dance","cn":"舞步","g":"[countable, usually plural]","sc":"in dance","ex":{"en":"Do you know the steps of this dance?","cn":"你知道这个舞蹈的舞步吗？"}},{"en":"the way that somebody walks","cn":"步伐；步态","g":"[countable, usually singular]","sc":"way of walking","ex":{"en":"He walked with a quick light step.","cn":"他迈着轻快的步子走着。"}},{"en":"a type of exercise that you do by stepping on and off a raised piece of equipment","cn":"踏板操","g":"[uncountable]","sc":"exercise","ex":{"en":"step aerobics","cn":"有氧踏板操"}},{"en":"a stepladder","cn":"折梯；梯子","g":"[plural]","lab":"British English","sc":"ladder","ex":{"en":"a pair of steps","cn":"一架折梯"}},{"en":"the interval between two notes that are next to each other in a scale","cn":"音级；度","g":"[countable]","lab":"North American English","sc":"in music"},{"en":"to lift your foot and move it in a particular direction or put it on or in something; to move a short distance","cn":"迈步；踩；踏；行走","lab":"figurative","ex":{"en":"to step onto/off a bus","cn":"上／下公共汽车"},"pos":"verb"},{"en":"related as a result of one parent marrying again","cn":"（因父母再婚而构成的亲缘关系）继…","ex":{"en":"stepmother","cn":"继母"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(脚)步;步子","en":"If you take a step, you lift your foot and put it down in a different place, for example when you are walking.","ex":{"en":"I took a step towards him","cn":"我朝他迈了一步。"}},{"pos":"VERB 动词","cn":"踩;踏;跨步;迈步","en":"If you step on something or step in a particular direction, you put your foot on the thing or move your foot in that direction.","ex":{"en":"This was the moment when Neil Armstrong became the first man to step on the Moon","cn":"就在此刻，内尔·阿姆斯特朗成了首位登上月球的人。"}},{"pos":"N-COUNT 可数名词","cn":"阶梯;台阶","en":"Steps are a series of surfaces at increasing or decreasing heights, on which you put your feet in order to walk up or down to a different level.","ex":{"en":"This little room was along a passage and down some steps","cn":"这个小房间在沿着走廊再下几级台阶的地方。"}},{"pos":"N-COUNT 可数名词","cn":"(门前的)平台","en":"A step is a raised flat surface in front of a door.","ex":{"en":"A little girl was sitting on the step of the end house","cn":"一个小女孩正坐在最顶头那幢房子门前的平台上。"}},{"pos":"N-COUNT 可数名词","cn":"步骤;措施","en":"A step is one of a series of actions that you take in order to achieve something.","ex":{"en":"He greeted the agreement as the first step towards peace","cn":"他称该协定是通向和平的第一步。"}},{"pos":"N-COUNT 可数名词","cn":"阶段;等级;进程","en":"A step in a process is one of a series of stages.","ex":{"en":"The next step is to put the theory into practice","cn":"下一步是要将理论付诸实践。"}},{"pos":"N-COUNT 可数名词","cn":"舞步","en":"The steps of a dance are the sequences of foot movements which make it up."},{"pos":"N-SING 单数名词","cn":"步态;步姿;步伐","en":"Someone's step is the way they walk.","ex":{"en":"He quickened his step","cn":"他加快了步伐。"}},{"pos":"N-PLURAL 复数名词","cn":"同 stepladder","en":"Steps are the same as a stepladder ."},{"pos":"PHRASE 短语","cn":"比…领先一步;避开","en":"If you stay one step ahead of someone or something, you manage to achieve more than they do or avoid competition or danger from them.","ex":{"en":"Successful travel is partly a matter of keeping one step ahead of the crowd","cn":"成功的旅行在某种程度上就是要比人群先走一步。"}},{"pos":"PHRASE 短语","cn":"步伐整齐/步伐不整齐;合拍/不合拍","en":"If people who are walking or dancing are in step, they are moving their feet forward at exactly the same time as each other. If they are out of step, their feet are moving forward at different times.","ex":{"en":"They were almost the same height and they moved perfectly in step","cn":"他们几乎一样高，而且走路时步调完全一致。"}},{"pos":"PHRASE 短语","cn":"(想法、意见等)与…一致/与…不一致","en":"If people are in step with each other, their ideas or opinions are the same. If they are out of step with each other, their ideas or opinions are different.","ex":{"en":"Moscow is anxious to stay in step with Washington","cn":"俄罗斯政府迫切希望和美国政府保持一致。"}},{"pos":"PHRASE 短语","cn":"快点;赶快","en":"If you tell someone to step on it, you are telling them to go faster or hurry up.","ex":{"en":"We've only got thirty-five minutes so step on it.","cn":"我们只有 35 分钟了，快点。"}},{"pos":"PHRASE 短语","cn":"一步一步地;逐步地","en":"If you do something step by step, you do it by progressing gradually from one stage to the next.","ex":{"en":"I am not rushing things and I'm taking it step by step","cn":"我不会仓促行事，我会一步一步地来。"}},{"pos":"PHRASE 短语","cn":"谨慎地行事(或说话)","en":"If someone tells you to watch your step, they are warning you to be careful about how you behave or what you say so that you do not get into trouble."},{"pos":"","cn":"","en":"相关词组：step aside step back step down step in step out step up"}]},"examples":[{"en":"It's important for world leaders to step up to the plate and honor their commitments on global warming.","cn":"对世界领导人来说，重要的是开始行动，兑现他们在全球变暖问题上的承诺。"},{"en":"We are learning to step back from ourselves and identify our strengths and weaknesses.","cn":"我们正努力学会走出自我的樊篱，认清我们自身的优点和缺点。"}]},"steady":{"media":{"uk":"media/uk/steady__gb_1.mp3","us":"media/us/steady__us_1.mp3"},"oxford":{"phon":"ˈstedi","pos":"adjective","senses":[{"en":"developing, growing, etc. gradually and in an even and regular way","cn":"（发展、增长等）稳步的，持续的，匀速的","ex":{"en":"We've had five years of steady economic growth.","cn":"我们已经经历了五年经济稳定增长。"}},{"en":"not changing and not interrupted","cn":"稳定的；恒定的","ex":{"en":"His breathing was steady.","cn":"他呼吸平稳。"}},{"en":"fixed in a place or position, supported or balanced; controlled and not shaking or likely to fall down","cn":"稳的；平稳的；稳固的","ex":{"en":"He held the boat steady as she got in.","cn":"他把船稳住，让她上了船。"}},{"en":"sensible; who can be relied on","cn":"沉稳的；可靠的"},{"en":"to stop yourself/somebody/something from moving, shaking or falling; to stop moving, shaking or falling","cn":"使稳；使平稳；稳住","g":"[transitive, intransitive]","ex":{"en":"She steadied herself against the wall.","cn":"她靠墙站稳。"},"pos":"verb"},{"en":"to stop changing and become regular again","cn":"恢复平稳；稳定下来","g":"[intransitive]","ex":{"en":"Her heartbeat steadied.","cn":"她的心跳平稳下来。"},"pos":"verb"},{"en":"to make somebody/something calm","cn":"使平静；使冷静；使镇定","g":"[transitive]","ex":{"en":"He took a few deep breaths to steady his nerves.","cn":"他深深地吸了几口气，让自己平静下来。"},"pos":"verb"},{"en":"in a way that is steady and does not change or shake","cn":"稳定地；持续地；稳固地","ex":{"en":"In trading today the dollar held steady against the yen.","cn":"在今天的交易中，美元对日元的汇率保持稳定。"},"pos":"adverb"},{"en":"used to tell somebody to be careful about what they are saying or doing, for example because it is extreme or not appropriate","cn":"（要求对方注意言行）哎，注意点","lab":"becoming old-fashioned","ex":{"en":"Steady on! You can't say things like that about somebody you've never met.","cn":"注意点！你从没见过的人，不要那样议论人家。"},"pos":"exclamation"},{"en":"used to tell somebody to be careful","cn":"（提醒对方小心）注意，当心，小心","ex":{"en":"Steady! Don't fall off.","cn":"小心！别摔下来。"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳步的;持续不断的","en":"A steady situation continues or develops gradually without any interruptions and is not likely to change quickly.","ex":{"en":"Despite the steady progress of building work, the campaign against it is still going strong","cn":"尽管建筑施工已在稳步进行，但反对活动仍然高涨。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"稳定的;牢固的;不摇晃的","en":"If an object is steady, it is firm and does not shake or move about.","ex":{"en":"Get as close to the subject as you can and hold the camera steady","cn":"尽量靠近拍摄对象，拿稳相机。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉着的;镇定的;冷静的","en":"If you look at someone or speak to them in a steady way, you look or speak in a calm, controlled way.","ex":{"en":"'Well, go on,' said Camilla, her voice fairly steady","cn":"“好吧，请继续，”卡米拉用很沉着的语气说道。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)稳重的，理智的，可靠的","en":"If you describe a person as steady, you mean that they are sensible and reliable.","ex":{"en":"He was firm and steady unlike other men she knew.","cn":"他坚定可靠，和她认识的其他男人不一样。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)稳定;(使)不摇晃","en":"If you steady something or if it steadies, it stops shaking or moving about.","ex":{"en":"Two men were on the bridge-deck, steadying a ladder","cn":"两名男子在船桥甲板上扶着一架梯子不让它摇晃。"}},{"pos":"VERB 动词","cn":"使镇定;使冷静;使平静","en":"If you steady yourself, you control your voice or expression, so that people will think that you are calm and not nervous.","ex":{"en":"Somehow she steadied herself and murmured, 'Have you got a cigarette?'","cn":"她设法让自己镇定下来，并小声问：“你有烟吗?”"}},{"pos":"EXCLAM 感叹语","cn":"冷静点;说话当心点","en":"You say 'steady on' to someone to tell them to calm down or to be careful about what they are saying.","ex":{"en":"'What if there's another murder?' — 'Steady on!'","cn":"“万一又有人被杀呢?”——“说话注意点！”"}},{"pos":"PHR-RECIP 相互短语","cn":"有确定的情侣关系;恋爱关系稳定","en":"If two people are going steady, they are having a long, fairly serious romantic relationship.","ex":{"en":"She's been going steady with Randolph for almost a year now.","cn":"她和伦道夫已经谈了近一年恋爱了。"}}]},"examples":[{"en":"In trading today the dollar held steady against the yen.","cn":"在今天的交易中，美元对日元的汇率保持稳定。"},{"en":"Steady on! You can't say things like that about somebody you've never met.","cn":"注意点！你从没见过的人，不要那样议论人家。"}]},"stimulate":{"media":{"uk":"media/uk/stimulate__gb_1.mp3","us":"media/us/stimulate__us_1.mp3"},"oxford":{"phon":"ˈstɪmjuleɪt","pos":"verb","senses":[{"en":"to make something develop or become more active; to encourage something","cn":"促进；激发；激励","ex":{"en":"The exhibition has stimulated interest in her work.","cn":"展览增进了人们对她作品的兴趣。"}},{"en":"to make somebody interested and excited about something","cn":"刺激；使兴奋","ex":{"en":"Parents should give children books that stimulate them.","cn":"父母应给孩子能启发他们的书。"}},{"en":"to make a part of the body function","cn":"促进（身体某部分）的功能","lab":"specialist","ex":{"en":"The women were given fertility drugs to stimulate the ovaries.","cn":"那些妇女得到了促进卵巢功能的生育药。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"刺激;激励;促使;促起","en":"To stimulate something means to encourage it to begin or develop further.","ex":{"en":"America's priority is rightly to stimulate its economy","cn":"美国的首要任务自然是刺激经济。"}},{"pos":"VERB 动词","cn":"激发;激励;使充满热情","en":"If you are stimulated by something, it makes you feel full of ideas and enthusiasm.","ex":{"en":"Bill was stimulated by the challenge","cn":"这个挑战让比尔热情高涨。"}},{"pos":"VERB 动词","cn":"刺激(身体部位);使活跃","en":"If something stimulates a part of a person's body, it causes it to move or start working.","ex":{"en":"Exercise stimulates the digestive and excretory systems","cn":"锻炼能促进消化和排泄系统的活动。"}}]},"examples":[{"en":"The conference stimulated him to study the subject in more depth.","cn":"这次会议促使他更深入地研究那个课题。"},{"en":"The women were given fertility drugs to stimulate the ovaries.","cn":"那些妇女得到了促进卵巢功能的生育药。"}]},"steadily":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"gradually and continually","cn":"稳步地，稳定地"},{"en":"in a calm way, without stopping","cn":"沉稳地，镇定地"}]},"examples":[{"en":"The company’s exports have grown steadily .","cn":"这家公司的出口额稳定增长。","src":"ld"},{"en":"Debt was increasing steadily .","cn":"债务一步步增加。","src":"ld"}],"media":{"uk":"media/uk/steadily__gb_1.mp3","us":"media/us/steadily__us_1.mp3"},"oxford":{"phon":"ˈstedəli","pos":"adverb","senses":[{"en":"gradually and in an even and regular way","cn":"稳步地；持续地；匀速地","ex":{"en":"The company's exports have been increasing steadily.","cn":"这家公司的出口量一直稳步增长。"}},{"en":"without changing or being interrupted","cn":"稳定地；恒定地","ex":{"en":"He looked at her steadily.","cn":"他一动不动地看着她。"}}]}},"standing":{"media":{"uk":"media/uk/standing__gb_1.mp3","us":"media/us/standing__us_1.mp3"},"oxford":{"phon":"ˈstændɪŋ","pos":"adjective","senses":[{"en":"done from a position in which you are standing rather than sitting or running","cn":"站着进行的","ex":{"en":"a standing jump/start","cn":"立定跳远；站立式起跑"}},{"en":"existing or arranged permanently, not formed or made for a particular situation","cn":"长期存在的；永久性的；常设的","lab":"British English","ex":{"en":"a standing army","cn":"常备军"}},{"en":"the position or reputation of somebody/something within a group of people or in an organization","cn":"地位；级别；身份；名声","g":"[uncountable]","ex":{"en":"the high/low standing of politicians with the public","cn":"在公众中声望高／低的政治人物"},"pos":"noun"},{"en":"the period of time that something has existed","cn":"持续时间","g":"[uncountable]","ex":{"en":"a friendship of many years’ standing","cn":"多年的友情"},"pos":"noun"},{"en":"a list of people, teams, etc. showing their positions in a sports competition","cn":"（运动员或运动队比赛成绩的）排名，名次","g":"[plural]","ex":{"en":"He remains at the top of the championship standings.","cn":"他仍然保持在冠军积分榜上的榜首位置。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"地位;身份;名声","en":"Someone's standing is their reputation or status.","ex":{"en":"...an artist of international standing","cn":"具有国际名望的艺术家"}},{"pos":"N-COUNT 可数名词","cn":"(党派或个人的)受欢迎程度，支持率","en":"A party's or person's standing is their popularity.","ex":{"en":"But, as the opinion poll shows, the party's standing with the people at large has never been so low","cn":"但是民意调查显示，该党在公众中的支持率从未这么低过。"}},{"pos":"ADJ 形容词","cn":"常设的;常备的","en":"You use standing to describe something which is permanently in existence.","ex":{"en":"Israel has a relatively small standing army and its strength is based on its reserves","cn":"以色列的常备军规模相对较小，其军事实力主要在于它的预备役部队。"}},{"pos":"N-PLURAL 复数名词","cn":"(比赛成绩的)名次表，排名表","en":"In a contest or competition, the list of competitors which shows their places during the event is called the standings .","ex":{"en":"Britain is 11th in the team standings.","cn":"英国在各队排名中位列第 11 位。"}},{"pos":"PHRASE 短语","cn":"已存在多年的","en":"You can use the expression of many years' standing to say that something has had a particular function or someone has had a particular role for many years. For example, if a place is your home of ten years' standing, it has been your home for ten years.","ex":{"en":"...a Congressman of 24 years' standing","cn":"有 24 年资历的国会议员"}}]},"examples":[{"en":"We have a standing invitation to visit them anytime.","cn":"他们邀请我们随时去他们家做客。"},{"en":"The speaker got a standing ovation (= people stood up to clap after the speech).","cn":"演讲者赢得了听众的起立鼓掌。"}]},"steam":{"media":{"img":["media/pic/cooking_methods_comp.jpg","media/thumb/steam.jpg"],"uk":"media/uk/steam__gb_1.mp3","us":"media/us/steam__us_1.mp3"},"oxford":{"phon":"stiːm","pos":"noun","senses":[{"en":"the hot gas that water changes into when it boils","cn":"水蒸气；蒸汽","ex":{"en":"Steam rose from the boiling kettle.","cn":"壶里的水开了，冒着蒸汽。"}},{"en":"the power that is produced from steam under pressure, used to operate engines, machines, etc.","cn":"蒸汽动力","ex":{"en":"the introduction of steam in the 18th century","cn":"18 世纪蒸汽动力的采用"}},{"en":"very small drops of water that form in the air or on cold surfaces when warm air suddenly cools","cn":"水汽","ex":{"en":"She wiped the steam from her glasses.","cn":"她擦去眼镜上的水汽。"}},{"en":"science, technology, engineering, arts and mathematics (used to refer to these subjects as a group in the context of education and jobs)","cn":"蒸汽：科学，技术，工程，艺术和数学（用于在教育和工作中将这些学科归为一类）","ex":{"en":"As a teacher, I'm excited by my school's developing STEAM program.","cn":"作为一名教师，我对学校开发的 STEAM 项目感到兴奋。"},"pos":"abbreviation"},{"en":"to send out steam","cn":"蒸发；散发蒸汽；冒水汽","g":"[intransitive]","ex":{"en":"Our damp clothes steamed in the heat.","cn":"我们的湿衣服在高温下冒着蒸汽。"},"pos":"verb"},{"en":"to place food over boiling water so that it cooks in the steam; to be cooked in this way","cn":"蒸（食物）","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"steamed fish","cn":"蒸鱼"},"pos":"verb"},{"en":"to move using the power produced by steam","cn":"依靠蒸汽动力行驶","g":"[intransitive]","ex":{"en":"The boat steamed across the lake.","cn":"汽船从湖上驶过。"},"pos":"verb"},{"en":"to go somewhere very quickly","cn":"快速行走；疾行","g":"[intransitive]","lab":"figurative","ex":{"en":"He spotted her steaming down the corridor towards him.","cn":"他看见她沿着走廊向他疾步走来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蒸汽;水蒸气","en":"Steam is the hot mist that forms when water boils. Steam vehicles and machines are operated using steam as a means of power.","ex":{"en":"In an electric power plant the heat converts water into high-pressure steam.","cn":"在发电厂里，热能将水转化成高压蒸汽。"}},{"pos":"VERB 动词","cn":"冒蒸汽;冒热气","en":"If something steams, it gives off steam.","ex":{"en":"...restaurants where coffee pots steamed on their burners.","cn":"咖啡壶在炉子上冒着热气的餐馆"}},{"pos":"V-ERG 及物/不及物动词","cn":"蒸(食物)","en":"If you steam food or if it steams, you cook it in steam rather than in water. →see usage note at:","ex":{"en":"Steam the carrots until they are just beginning to be tender","cn":"将胡萝卜蒸至刚好变软。"}},{"pos":"PHRASE 短语","cn":"进展迅速;全速前进","en":"If something such as a plan or a project goes full steam ahead, it progresses quickly.","ex":{"en":"The Government was determined to go full steam ahead with its privatisation programme","cn":"政府下决心要全力实施私有化计划。"}},{"pos":"PHRASE 短语","cn":"发泄怒火;宣泄情感","en":"If you let off steam, you get rid of your energy, anger, or strong emotions with physical activity or by behaving in a noisy or violent way.","ex":{"en":"Regular exercise helps to combat unwanted stress and is a good way of relaxing or letting off steam.","cn":"经常运动有助于摆脱多余的压力，也是放松或宣泄情感的好办法。"}},{"pos":"PHRASE 短语","cn":"(信念、计划、项目等)变得越来越重要，开始发展壮大","en":"If a belief, a plan, or a project picks up steam, it starts to develop and become more important.","ex":{"en":"Just as the presidential campaign was picking up steam, riots exploded in Los Angeles.","cn":"正当总统竞选活动的声势日益壮大时，洛杉矶爆发了暴乱。"}},{"pos":"PHRASE 短语","cn":"精疲力竭;丧失热情;泄气","en":"If you run out of steam, you stop doing something because you have no more energy or enthusiasm left.","ex":{"en":"I decided to paint the bathroom ceiling but ran out of steam halfway through.","cn":"我决定粉刷一下浴室的天花板，但干了一半就精疲力竭了。"}},{"pos":"PHRASE 短语","cn":"靠自己的力量","en":"If you do something under your own steam, you do it without any help from anyone else.","ex":{"en":"Patients who are well enough to turn up under their own steam are well enough to wait to be seen by a doctor.","cn":"让那些身体状况不那么糟、还能自己来看病的病人花点时间候诊没什么问题。"}},{"pos":"","cn":"","en":"相关词组：steam ahead steam up"}]},"examples":[{"en":"( figurative ) The company is steaming ahead with its investment programme.","cn":"公司正全力以赴实施自己的投资方案。"},{"en":"As he walked in, his glasses steamed up.","cn":"他进去的时候，眼镜上起了一层雾。"}]},"stocky":{"media":{"uk":"media/uk/stocky__gb_1.mp3","us":"media/us/stocky__us_1.mp3"},"oxford":{"phon":"ˈstɒki","pos":"adjective","senses":[{"en":"short, with a strong, solid body","cn":"矮壮的；敦实的","ex":{"en":"a stocky figure/build","cn":"矮胖的身材/身材"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"结实的;矮壮的;粗壮的","en":"A stocky person has a body that is broad, solid, and often short."}]},"examples":[{"en":"a stocky build","cn":"敦实的体格"}]},"strictly":{"media":{"uk":"media/uk/strictly__gb_1.mp3","us":"media/us/strictly__us_1.mp3"},"oxford":{"phon":"ˈstrɪktli","pos":"adverb","senses":[{"en":"with a lot of control and rules that must be obeyed","cn":"严格地","ex":{"en":"She was brought up very strictly.","cn":"她从小家教很严。"}},{"en":"used to emphasize that something happens or must happen in all circumstances","cn":"（强调在一切情况都是如此）绝对地，无论如何","ex":{"en":"Smoking is strictly forbidden.","cn":"严禁吸烟。"}},{"en":"in all details; exactly","cn":"完全地；确切地","ex":{"en":"This is not strictly true.","cn":"这不完全正确。"}},{"en":"used to emphasize that something only applies to one particular person, thing or situation","cn":"（强调只适用于某人、物或情况）只，仅限于","ex":{"en":"We'll look at the problem from a strictly legal point of view.","cn":"我们将只从法律的角度来看待这个问题。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"完全;只;仅限于","en":"You use strictly to emphasize that something is of one particular type, or intended for one particular thing or person, rather than any other.","ex":{"en":"He seemed fond of her in a strictly professional way","cn":"他似乎只是出于职业缘故而喜欢她。"}}]},"examples":[{"en":"Strictly speaking, the book is not a novel, but a short story.","cn":"严格说来，这部小说不能算长篇，而是短篇。"},{"en":"My letter is, of course, strictly private and confidential.","cn":"当然，我的信纯属私人信件，务须保密。"}]},"sticking":{"oxford":{"phon":"stɪk","pos":"verb","senses":[{"en":"to push sth, usually a sharp object, into sth; to be pushed into sth","cn":"将 … 刺入（或插入）；刺；戳；插入"},{"en":"to fix sth to sth else, usually with a sticky substance; to become fixed to sth in this way","cn":"粘贴；粘住"}]},"media":{"img":["media/pic/stick_comp.jpg","media/thumb/stick.jpg"],"uk":"media/uk/stick__gb_1.mp3","us":"media/us/stick__us_1.mp3"}},"stranger":{"media":{"uk":"media/uk/stranger__gb_1.mp3","us":"media/us/stranger__us_1.mp3"},"oxford":{"phon":"ˈstreɪndʒə(r)","pos":"noun","senses":[{"en":"a person that you do not know","cn":"陌生人","ex":{"en":"There was a complete stranger sitting at my desk.","cn":"我书桌前坐着一个从未见过的陌生人。"}},{"en":"a person who is in a place that they have not been in before","cn":"外地人；新来者","ex":{"en":"Sorry, I don't know where the bank is. I'm a stranger here myself.","cn":"不好意思，我不知道银行在哪儿。我也不是本地人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"陌生人","en":"A stranger is someone you have never met before.","ex":{"en":"Telling a complete stranger about your life is difficult","cn":"要对一个素昧平生的人谈自己的生活经历是比较困难。"}},{"pos":"N-PLURAL 复数名词","cn":"互不相识的人","en":"If two people are strangers, they do not know each other.","ex":{"en":"The women knew nothing of the dead girl. They were strangers.","cn":"女人们都对死去的女孩一无所知。她们互不相识。"}},{"pos":"N-COUNT 可数名词","cn":"外乡人;外地人","en":"If you are a stranger in a place, you do not know the place well.","ex":{"en":"'You don't know much about our town, do you?'—'No, I'm a stranger here.'","cn":"“你不太了解我们这个镇，是吗？”——“是的，我是外地人。”"}},{"pos":"N-COUNT 可数名词","cn":"生手;外行;(对…)一无所知的人","en":"If you are a stranger to something, you have had no experience of it or do not understand it.","ex":{"en":"He is no stranger to controversy","cn":"他是个颇具争议的人物。"}}]},"examples":[{"en":"Sorry, I don't know where the bank is. I'm a stranger here myself.","cn":"对不起，我不知道银行在哪儿。我不是本地人。"},{"en":"There was a complete stranger sitting at my desk.","cn":"我书桌前坐着一个从未见过的陌生人。"}]},"strong":{"media":{"uk":"media/uk/strong__gb_1.mp3","us":"media/us/strong__us_1.mp3"},"oxford":{"phon":"strɒŋ","pos":"adjective","senses":[{"en":"having a lot of physical power so that you can lift heavy weights, do hard physical work, etc.","cn":"强壮的；强健的","sc":"having physical power","ex":{"en":"He's strong enough to lift a car!","cn":"他力气大得能抬起一辆汽车！"}},{"en":"having great power","cn":"强的；强劲的","sc":"having physical power","ex":{"en":"Stay indoors in the middle of the day, when the sun is strongest.","cn":"中午阳光最强的时候待在室内。"}},{"en":"having a powerful effect on the body or mind","cn":"（对身、心影响）强烈的，深刻的","sc":"having physical power","ex":{"en":"a strong drug","cn":"强效药物"}},{"en":"having a lot of power or influence","cn":"有权势的；有影响的；有实力的","sc":"having power over people","ex":{"en":"a strong leader","cn":"强硬的领导人"}},{"en":"people who are rich or powerful","cn":"有钱人；有势者；强势群体","g":"[plural]","sc":"having power over people"},{"en":"difficult to attack or criticize","cn":"难以辩驳的；确凿的","sc":"hard to resist/defeat/attack","ex":{"en":"There is strong evidence of a link between exercise and a healthy heart.","cn":"有充分的证据证明锻炼有益于心脏健康。"}},{"en":"very powerful and difficult for people to fight against or defeat","cn":"强的；强大的；厉害的","sc":"hard to resist/defeat/attack","ex":{"en":"a strong team","cn":"强队"}},{"en":"very powerful","cn":"坚定的；强烈的；深厚的","sc":"opinion/belief/feeling","ex":{"en":"strong support for the government","cn":"对政府的坚决拥护"}},{"en":"holding an opinion or a belief very seriously","cn":"坚决的；不动摇的","g":"[only before noun]","sc":"opinion/belief/feeling","ex":{"en":"a strong supporter of the government","cn":"政府的坚决拥护者"}},{"en":"easy to see, hear, feel or smell; very great or intense","cn":"醒目的；响亮的；明显感觉得到的；浓烈的；强烈的","sc":"easy to see/hear/feel/smell","ex":{"en":"a strong smell","cn":"浓烈的气味"}},{"en":"having a lot of taste","cn":"味重的","sc":"food","ex":{"en":"strong cheese","cn":"味重的奶酪"}},{"en":"containing a lot of a substance","cn":"浓的；酽的","sc":"drinks","ex":{"en":"strong black coffee","cn":"不加牛奶的浓咖啡"}},{"en":"not easily broken or damaged; made well","cn":"坚固的；结实的","sc":"not easily broken","ex":{"en":"The box looks strong enough.","cn":"盒子看上去够结实。"}},{"en":"not easily upset or frightened; not easily influenced by other people","cn":"坚强的；不易受惊吓的；有主见的","sc":"not easily upset","ex":{"en":"You need strong nerves to ride a bike in London.","cn":"在伦敦骑自行车，你可得有胆量。"}},{"en":"likely to succeed or happen","cn":"有望成功的；可能性大的","sc":"likely to succeed","ex":{"en":"a strong candidate for the job","cn":"有望获得这份工作的人选"}},{"en":"having existed for a long time and functioning well; difficult to destroy","cn":"稳固的；坚固的；牢固的","sc":"difficult to destroy","ex":{"en":"a strong marriage","cn":"牢固的婚姻"}},{"en":"having a value that is high or increasing","cn":"坚挺的；行情看涨的；呈强势的","sc":"business","ex":{"en":"strong share prices","cn":"行情看涨的股票价格"}},{"en":"in a safe financial position","cn":"经营状况良好的；景气的","sc":"business","ex":{"en":"Their catering business remained strong despite the recession.","cn":"尽管出现经济衰退，他们的酒席承办生意仍然景气。"}},{"en":"good at something; done well","cn":"擅长的；突出的；做得好的","sc":"good at something","ex":{"en":"The play has a very strong cast.","cn":"这部剧演员阵容强大。"}},{"en":"great in number","cn":"大量的；众多的","sc":"number","ex":{"en":"There was a strong police presence at the demonstration.","cn":"示威现场有大批警察。"}},{"en":"used after numbers to show the size of a group","cn":"（用于数字后，表示某集体的规模）多达…的，计有…的","sc":"number","ex":{"en":"a 5 000-strong crowd","cn":"多达 5 000 人的人群"}},{"en":"not easily affected by disease; healthy","cn":"健康的；强壮的；身体好的","lab":"especially British English","sc":"healthy","ex":{"en":"These vitamins are meant to keep you healthy and strong.","cn":"这些维生素会让你保持健康强壮。"}},{"en":"having a lot of force, often causing offence to people","cn":"强硬的；冒犯的","sc":"words","ex":{"en":"The movie has been criticized for strong language (= swearing).","cn":"这部电影因有脏话而受到批评。"}},{"en":"forming the past tense and past participle by changing a vowel, not by adding a regular ending, for example sing, sang, sung","cn":"强变化的（通过改变元音而不是加规则的词尾来构成动词过去式和过去分词，如 sing、sang、sung）","g":"[usually before noun]","sc":"grammar"},{"en":"used to describe the way some words are pronounced when they have stress. For example, the strong form of and is /ænd/.","cn":"强读式的，重读的（某些词重读时的读音，如 and 的强式读音为 ænd）/ænd/）","g":"[usually before noun]","sc":"phonetics"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"强壮的;健壮的;力气大的","en":"Someone who is strong is healthy with good muscles and can move or carry heavy things, or do hard physical work.","ex":{"en":"I'm not strong enough to carry him","cn":"我力气不够大，抱不动他。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)坚定的，坚决的，自信的","en":"Someone who is strong is confident and determined, and is not easily influenced or worried by other people.","ex":{"en":"He is sharp and manipulative with a strong personality","cn":"他个性很强，为人精明且爱指使人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不易损坏的;坚固的;结实的","en":"Strong objects or materials are not easily broken and can support a lot of weight or resist a lot of strain.","ex":{"en":"The vacuum flask has a strong casing, which won't crack or chip","cn":"这种热水瓶瓶身坚固，不易断裂破碎。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(风、水流等)强劲的，迅猛的，狂奔的","en":"A strong wind, current, or other force has a lot of power or speed, and can cause heavy things to move.","ex":{"en":"Strong winds and torrential rain combined to make conditions terrible for golfers in the Scottish Open","cn":"狂风暴雨一齐袭来，致使苏格兰高尔夫球公开赛的比赛条件变得异常糟糕。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(印象、影响)强烈的，深刻的","en":"A strong impression or influence has a great effect on someone.","ex":{"en":"We're glad if our music makes a strong impression, even if it's a negative one","cn":"如果我们的音乐能给人留下深刻的印象，哪怕是负面的印象，我们都会很高兴。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观点、措辞)坚定的，强烈的，不动摇的","en":"If you have strong opinions on something or express them using strong words, you have extreme or very definite opinions which you are willing to express or defend.","ex":{"en":"She is known to hold strong views on Cuba","cn":"她在古巴问题上的鲜明观点人人皆知。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(当权者的行为)坚定的，强硬的，严厉的，不动摇的","en":"If someone in authority takes strong action, they act firmly and severely.","ex":{"en":"The government has said it will take strong action against any further strikes","cn":"政府声称要采取严厉行动制止罢工进一步发展。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(理由、论据)有说服力的，强有力的，充分的","en":"If there is a strong case or argument for something, it is supported by a lot of evidence.","ex":{"en":"The testimony presented offered a strong case for acquitting her on grounds of self-defense","cn":"当庭的证词为裁定她是正当防卫而无罪提供了强有力的证据。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(可能性、机会)极大的","en":"If there is a strong possibility or chance that something is true or will happen, it is very likely to be true or to happen.","ex":{"en":"There is a strong possibility that the cat contracted the condition by eating contaminated pet food.","cn":"猫很有可能是吃了受污染的宠物食品而染上这种疾病的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优秀的;精通的;擅长的","en":"Your strong points are your best qualities or talents, or the things you are good at.","ex":{"en":"Discretion is not Jeremy's strong point","cn":"小心谨慎不是杰里米的强项。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(竞争者、候选人、队伍)强大的，有望成功的，有实力的","en":"A strong competitor, candidate, or team is good or likely to succeed.","ex":{"en":"She was a strong contender for Britain's Olympic team","cn":"她是有望入选英国奥运代表团的有力竞争者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(关系)稳固的，持久的，牢固的","en":"If a relationship or link is strong, it is close and likely to last for a long time.","ex":{"en":"He felt he had a relationship strong enough to talk frankly to Sarah","cn":"他认为和萨拉的关系很紧密，足以推心置腹。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(货币)坚挺的;(经济)强劲的;(行业)景气的","en":"A strong currency, economy, or industry has a high value or is very successful.","ex":{"en":"The US dollar continued its strong performance in Tokyo today","cn":"美元今天在东京继续保持强劲的走势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(因素、成分)重要的，占很大比例的","en":"If something is a strong element or part of something else, it is an important or large part of it.","ex":{"en":"We are especially encouraged by the strong representation, this year, of women in information technology disciplines","cn":"今年，女性在信息技术领域的突出表现尤其让我们备受鼓舞。"}},{"pos":"ADJ 形容词","cn":"大量的;众多的;多达…的","en":"You can use strong when you are saying how many people there are in a group. For example, if a group is twenty strong, there are twenty people in it.","ex":{"en":"Ukraine indicated that it would establish its own army, 400,000 strong.","cn":"乌克兰表示将自己建立一支40 多万人的军队。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(饮品、化学品、药物)含量高的，浓的，酽的","en":"A strong drink, chemical, or drug contains a lot of the particular substance which makes it effective.","ex":{"en":"Strong coffee or tea late at night may cause sleeplessness","cn":"深夜喝浓咖啡或浓茶可能会导致失眠。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"醒目的;响亮的;浓烈的;强烈的","en":"A strong colour, flavour, smell, sound, or light is intense and easily noticed.","ex":{"en":"As she went past there was a gust of strong perfume","cn":"她走过时有一股浓烈的香水味。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(口音)浓重的","en":"If someone has a strong accent, they speak in a distinctive way that shows very clearly what country or region they come from.","ex":{"en":"'Good, Mr Ryle,' he said in English with a strong French accent.","cn":"“好的，赖尔先生，”他用带有浓重法国口音的英语说。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(面貌)轮廓分明的","en":"You can say that someone has strong features or a strong face if their face has large, distinctive features.","ex":{"en":"He had a strong Greek nose and olive-black eyes.","cn":"他有一个高挺的希腊式鼻子和一双墨橄榄绿色的眼睛。"}},{"pos":"PHRASE 短语","cn":"言行过分;情绪激烈","en":"If someone comes on strong, they make their intentions or feelings clear in an excessive or aggressive way.","ex":{"en":"'I come on strong sometimes. Don't know why.' She was beginning to feel like a bully.","cn":"“我有时言行很过分，不知道为什么。”她开始感觉自己像个恶霸。"}},{"pos":"PHRASE 短语","cn":"保持健康;依旧活跃;兴盛不衰","en":"If someone or something is still going strong, they are still alive, in good condition, or popular after a long time.","ex":{"en":"The old machinery was still going strong.","cn":"这台旧机器依然运转良好。"}}]},"examples":[{"en":"Their catering business remained strong despite the recession.","cn":"尽管出现经济衰退，他们的酒席承办生意仍然景气。"},{"en":"The report was strong on criticism, but short on practical suggestions.","cn":"这份报告批评的话说得多，但可行的建议提得少。"}]},"steer":{"oxford":{"phon":"stɪə(r)","pos":"verb","senses":[{"en":"to control the direction in which a boat, car, etc. moves","cn":"驾驶（船、汽车等）；掌控方向盘","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"He steered the boat into the harbour.","cn":"他把船开进港。"}},{"en":"to move in a particular direction","cn":"行驶","g":"[transitive, intransitive]","ex":{"en":"The ship steered a course between the islands.","cn":"船在岛屿之间穿行。"}},{"en":"to take control of a situation and influence the way in which it develops","cn":"操纵；控制；引导","g":"[transitive]","ex":{"en":"He managed to steer the conversation away from his divorce.","cn":"他设法避开他离婚这话题。"}},{"en":"a piece of advice or information that helps you do something or avoid a problem","cn":"建议；劝告；忠告","g":"[singular]","lab":"British English, informal，，","ex":{"en":"Can anyone give me a steer on this?","cn":"有人能就这一点给我个建议吗？"},"pos":"noun"},{"en":"a bull (= a male cow) that has been castrated (= had part of its sex organs removed), kept for its meat","cn":"阉公牛；肉用公牛","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"驾驶(车、船、飞机等)","en":"When you steer a car, boat, or plane, you control it so that it goes in the direction that you want.","ex":{"en":"What is it like to steer a ship this size?","cn":"驾驶这么大的船感觉怎么样？"}},{"pos":"VERB 动词","cn":"引导，指导(某人采取某种行动或态度)","en":"If you steer people towards a particular course of action or attitude, you try to lead them gently in that direction.","ex":{"en":"The new government is seen as one that will steer the country in the right direction","cn":"新政府被认为能将国家引向正确的方向。"}},{"pos":"VERB 动词","cn":"引导，带领(某人去某地)","en":"If you steer someone in a particular direction, you guide them there.","ex":{"en":"Nick steered them into the nearest seats.","cn":"尼克将他们领到最近的座位上。"}},{"pos":"VERB 动词","cn":"选择某种做法;采取某种方式","en":"If you steer a particular course, you take a particular line of action.","ex":{"en":"Prime Minister Hun Sen has sought to steer a course between the two groups","cn":"洪森首相设法游走于两个集团之间。"}},{"pos":"N-COUNT 可数名词","cn":"犍牛","en":"A steer is a bull that has been castrated."},{"pos":"PHRASE 短语","cn":"避开;躲避;绕开","en":"If you steer clear of someone or something, you deliberately avoid them.","ex":{"en":"I think a lot of people, women in particular, steer clear of these sensitive issues.","cn":"我认为很多人，特别是女性，都会回避这些敏感问题。"}}]},"media":{"uk":"media/uk/steer__gb_1.mp3","us":"media/us/steer__us_1.mp3"},"examples":[{"en":"The skill is in steering a middle course between the two extremes.","cn":"本领就在于避开这两个极端，走中间路线。"},{"en":"( figurative ) He took her arm and steered her towards the door.","cn":"他抓住她的胳膊，把她带往门口。"}]},"starry":{"media":{"uk":"media/uk/starry__gb_1.mp3","us":"media/us/starry__us_1.mp3"},"oxford":{"phon":"ˈstɑːri","pos":"adjective","senses":[{"en":"full of stars","cn":"布满星星的","ex":{"en":"a beautiful starry night","cn":"繁星满天的美丽夜晚"}},{"en":"looking like a star","cn":"像星星的","ex":{"en":"starry flowers","cn":"像星星似的花朵"}},{"en":"shining like stars","cn":"闪闪发光的；明亮的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"布满星星的","en":"A starry night or sky is one in which a lot of stars are visible.","ex":{"en":"She stared up at the starry sky.","cn":"她抬头凝视繁星点点的夜空。"}}]},"examples":[{"en":"a beautiful starry night","cn":"繁星满天的美丽夜晚"},{"en":"starry flowers","cn":"像星星似的花朵"}]},"stent":{"oxford":{"phon":"stent","pos":"noun","senses":[{"en":"a small support that is put inside a blood vessel (= tube) in the body, in order to keep the blood vessel open enough for blood to flow through","cn":"（防止血管栓塞而植入的）支架"}]},"media":{"uk":"media/uk/stent__gb_1.mp3","us":"media/us/stent__us_1.mp3"}},"state":{"media":{"uk":"media/uk/state__gb_1.mp3","us":"media/us/state__us_1.mp3"},"oxford":{"phon":"steɪt","pos":"noun","senses":[{"en":"a country considered as an organized political community controlled by one government","cn":"国家","g":"[countable]","lab":"British English","sc":"country","ex":{"en":"the Baltic States","cn":"波罗的海诸国"}},{"en":"an organized political community forming part of a country","cn":"州；邦","g":"[countable]","sc":"part of country","ex":{"en":"the states of Victoria and Western Australia","cn":"维多利亚州和西澳大利亚州"}},{"en":"the government of a country","cn":"政府","g":"[uncountable, singular]","sc":"government","ex":{"en":"matters/affairs of state","cn":"国家大事"}},{"en":"the mental, emotional or physical condition that a person or thing is in","cn":"状态；状况；情况","g":"[countable]","lab":"British English, informal，，","sc":"condition of somebody/something","ex":{"en":"a confused mental state","cn":"混乱的精神状态"}},{"en":"the formal ceremonies connected with high levels of government or with kings and queens","cn":"（适用于国家元首或政府首脑的）正式礼仪，隆重仪式","g":"[uncountable]","sc":"official ceremony","ex":{"en":"The president was driven in state through the streets.","cn":"总统乘车隆重地从街上穿过。"}},{"en":"the United States of America","cn":"美国","g":"[plural]","lab":"informal","sc":"the US","ex":{"en":"I've never been to the States.","cn":"我从未去过美国。"}},{"en":"provided or controlled by the government of a country","cn":"国家提供（或控制）的","sc":"government","ex":{"en":"state officials/agencies","cn":"国家官员／机构"},"pos":"adjective"},{"en":"provided or controlled by a particular state of a country, especially in the US","cn":"州的；邦的","sc":"part of country","ex":{"en":"the state government/legislature","cn":"州政府；州立法机构"},"pos":"adjective"},{"en":"connected with the leader of a country attending an official ceremony","cn":"国事礼仪（或规格）的","sc":"official","ex":{"en":"The queen is on a state visit to Berlin.","cn":"女王正在柏林进行国事访问。"},"pos":"adjective"},{"en":"to formally write or say something, especially in a careful and clear way","cn":"陈述；说明；声明","ex":{"en":"He has already stated his intention to run for election.","cn":"他已声明打算参加竞选。"},"pos":"verb"},{"en":"to fix or announce the details of something, especially on a written document","cn":"规定；公布","g":"[usually passive]","ex":{"en":"This is not one of their stated aims.","cn":"在他们宣布的目标里没有这一条。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤用于讨论政治事务时)国家","en":"You can refer to countries as states, particularly when you are discussing politics. →see usage note at:","ex":{"en":"Mexico is a secular state and does not have diplomatic relations with the Vatican","cn":"墨西哥是个世俗国家，和梵蒂冈没有外交关系。"}},{"pos":"N-COUNT 可数名词","cn":"(美国等大国的)州","en":"Some large countries such as the USA are divided into smaller areas called states .","ex":{"en":"Leaders of the Southern states are meeting in Louisville.","cn":"南部一些州的领导正在路易斯维尔开会。"}},{"pos":"N-PROPER 专有名词","cn":"美国","en":"The USA is sometimes referred to as the States ."},{"pos":"N-SING 单数名词","cn":"政府;国家","en":"You can refer to the government of a country as the state .","ex":{"en":"The state does not collect enough revenue to cover its expenditure","cn":"该国政府入不敷出。"}},{"pos":"ADJ 形容词","cn":"国有的;国家的","en":"State industries or organizations are financed and organized by the government rather than private companies. →see: ;","ex":{"en":"...reform of the state social-security system.","cn":"对国家社会保障制度的改革"}},{"pos":"ADJ 形容词","cn":"国事的;国事礼仪的","en":"A state occasion is a formal one involving the head of a country.","ex":{"en":"...the Queen's three-day state visit to France.","cn":"女王对法国为期 3 天的国事访问"}},{"pos":"N-COUNT 可数名词","cn":"状况;状态;情况","en":"When you talk about the state of someone or something, you are referring to the condition they are in or what they are like at a particular time.","ex":{"en":"For the first few months after Daniel died, I was in a state of clinical depression","cn":"丹尼尔去世后的最初几个月里，我一直处于临床抑郁症的状态。"}},{"pos":"VERB 动词","cn":"(以口头或书面形式正式或明确地)声称，宣称，声明","en":"If you state something, you say or write it in a formal or definite way.","ex":{"en":"Clearly state your address and telephone number","cn":"清楚地报上你的地址和电话号码。"}},{"pos":"PHRASE 短语","cn":"(因精神或健康状态不佳而)不适宜(做某事)","en":"If you say that someone is not in a fit state to do something, you mean that they are too upset or ill to do it.","ex":{"en":"When you left our place, you weren't in a fit state to drive.","cn":"你离开我们家时已经开不了车了。"}},{"pos":"PHRASE 短语","cn":"不快;紧张;焦虑;惊慌","en":"If you are in a state or if you get into a state, you are very upset or nervous about something.","ex":{"en":"I was in a terrible state because nobody could understand why I had this illness","cn":"我极度焦虑不安，因为谁也不知道为什么我会得这个病。"}},{"pos":"PHRASE 短语","cn":"(重要人物的遗体)停放供瞻仰","en":"If the dead body of an important person lies in state, it is publicly displayed for a few days before it is buried."}]},"examples":[{"en":"( BrE ) ( informal ) Look at the state of you! You can't go out looking like that.","cn":"看看你这副样子！你可不能就这么出去。"},{"en":"It was stated that standards at the hospital were dropping.","cn":"据称，那家医院的医疗水准在不断下降。"}]},"stooped":{"media":{"uk":"media/uk/stooped__gb_1.mp3","us":"media/us/stooped__us_1.mp3"},"oxford":{"phon":"stuːpt","pos":"adjective","senses":[{"en":"standing or walking with your head and shoulders bent forwards","cn":"弓背站立（或行走）的"},{"en":"stooped shoulders are bent forwards","cn":"曲背的"}]},"examples":[{"en":"a thin man with stooped shoulders","cn":"一个溜肩的瘦削男子"}]},"struggle":{"media":{"uk":"media/uk/struggle__gb_1.mp3","us":"media/us/struggle__us_1.mp3"},"oxford":{"phon":"ˈstrʌɡl","pos":"verb","senses":[{"en":"to try very hard to do something when it is difficult or when there are a lot of problems","cn":"奋斗；努力；争取","g":"[intransitive]","ex":{"en":"life as a struggling artist (= one who is very poor)","cn":"艺术家拮据的生活"}},{"en":"to move somewhere or do something with difficulty","cn":"艰难地行进；吃力地进行","g":"[intransitive]","ex":{"en":"I struggled up the hill with the heavy bags.","cn":"我背着几个沉重的包吃力地爬上山去。"}},{"en":"to fight against somebody/something in order to prevent a bad situation or result","cn":"斗争；抗争","g":"[intransitive]","ex":{"en":"Chloe continued to struggle, but her eyes began to close.","cn":"克洛伊继续挣扎，但她的眼睛开始闭上。"}},{"en":"to fight somebody or try to get away from them","cn":"搏斗；扭打；挣扎脱身","g":"[intransitive]","ex":{"en":"I struggled and screamed for help.","cn":"我挣扎着，高声呼救。"}},{"en":"to compete or argue with somebody/something, especially in order to get something","cn":"争夺；辩论","g":"[intransitive]","ex":{"en":"rival leaders struggling for power","cn":"互相对立的领导人争夺权力"}},{"en":"a hard fight in which people try to obtain or achieve something, especially something that somebody else does not want them to have","cn":"斗争；奋斗；努力","g":"[countable]","ex":{"en":"Marx wrote about the class struggle.","cn":"马克思论证了阶级斗争。"},"pos":"noun"},{"en":"a physical fight between two people or groups of people, especially when one of them is trying to escape, or to get something from the other","cn":"搏斗；扭打；（尤指）抢夺，挣扎脱身","g":"[countable]","ex":{"en":"There were no signs of a struggle at the murder scene.","cn":"凶杀现场没有搏斗痕迹。"},"pos":"noun"},{"en":"something that is difficult for you to do or achieve","cn":"难事","g":"[singular]","ex":{"en":"It was a real struggle to be ready on time.","cn":"要按时做好准备确非易事。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"奋力;努力;尽力","en":"If you struggle to do something, you try hard to do it, even though other people or things may be making it difficult for you to succeed.","ex":{"en":"They had to struggle against all kinds of adversity","cn":"他们不得不同一切困境做斗争。"}},{"pos":"N-VAR 可变名词","cn":"斗争;奋斗;努力","en":"A struggle is a long and difficult attempt to achieve something such as freedom or political rights.","ex":{"en":"Life became a struggle for survival.","cn":"生活成了一场奋力求生的斗争。"}},{"pos":"VERB 动词","cn":"挣扎;努力挣脱","en":"If you struggle when you are being held, you twist, kick, and move violently in order to get free.","ex":{"en":"I struggled, but he was a tall man, well-built.","cn":"我使劲挣扎，但他又高又壮。"}},{"pos":"V-RECIP 相互动词","cn":"搏斗;扭打","en":"If two people struggle with each other, they fight.","ex":{"en":"She screamed at him to 'stop it' as they struggled on the ground","cn":"他们在地上扭打成一团，她向他尖叫着“别打了”。"}},{"pos":"VERB 动词","cn":"艰难地做;吃力地做","en":"If you struggle to move yourself or to move a heavy object, you try to do it, but it is difficult.","ex":{"en":"I could see the young boy struggling to free himself","cn":"我看到小男孩正在奋力挣脱。"}},{"pos":"VERB 动词","cn":"艰难地行进","en":"If you struggle somewhere, you succeed in moving there, but only with great difficulty.","ex":{"en":"The pilot struggled out of the wreck almost uninjured","cn":"飞行员艰难地从失事的飞机中爬出来，几乎没有受伤。"}},{"pos":"VERB 动词","cn":"勉力维持;挣扎","en":"If a person or organization is struggling, they are likely to fail in what they are doing, even though they might be trying very hard.","ex":{"en":"The company is struggling to find buyers for its new product","cn":"该公司正竭力为其新产品寻找买主。"}},{"pos":"N-SING 单数名词","cn":"费力的事;难事","en":"An action or activity that is a struggle is very difficult to do.","ex":{"en":"Losing weight was a terrible struggle.","cn":"减肥是一件非常艰难的事。"}},{"pos":"","cn":"","en":"相关词组：struggle on"}]},"examples":[{"en":"He is engaged in a bitter struggle with his rival to get control of the company.","cn":"为取得对公司的控制权，他正同对手进行一场激烈的斗争。"},{"en":"Lisa struggled with her conscience before talking to the police.","cn":"莉萨经过一番良心上的斗争，终于对警方说了。"}]},"strengthens":{"oxford":{"phon":"ˈstreŋθn","pos":"verb","senses":[{"en":"to become stronger; to make sb/sth stronger","cn":"加强；增强；巩固"}]}},"stiffly":{"oxford":{"phon":"ˈstɪfli","pos":"adverb","senses":[{"en":"in a way that is formal, and not friendly or relaxed","cn":"不友好的；生硬的","ex":{"en":"‘Thank you,’ she replied stiffly.","cn":"“谢谢。”她生硬地回答。"}},{"en":"in a slow and uncomfortable way","cn":"僵硬地：缓慢而不舒服地","ex":{"en":"He got up stiffly to put more logs on the fire.","cn":"他僵硬地站起来，去往火上添更多的木头。"}},{"en":"in a way that is hard and difficult to bend or move","cn":"不易弯曲（或活动）的；硬的；挺的","ex":{"en":"The key turned stiffly in the lock.","cn":"钥匙在锁里转动不灵活。"}}]},"media":{"uk":"media/uk/stiffly__gb_1.mp3","us":"media/us/stiffly__us_1.mp3"},"examples":[{"en":"Her legs were stiff from kneeling.","cn":""},{"en":"Her fingers were stiff with cold.","cn":""}]},"strongly":{"oxford":{"phon":"ˈstrɒŋli","pos":"adverb","senses":[{"en":"in a way that shows definite and serious opinions or beliefs","cn":"坚决地；坚定地；不动摇地；始终不渝地","ex":{"en":"a strongly worded protest","cn":"措辞强硬的抗议"}},{"en":"to a great degree or extent","cn":"在很大程度上","ex":{"en":"Health spending is strongly linked to the country's wealth.","cn":"医疗支出与国家财富密切相关。"}},{"en":"in a way that is easy to notice","cn":"醒目地；明显感觉得到地；浓烈地；强烈地","ex":{"en":"The room smelt strongly of polish.","cn":"房间里散发着浓烈的上光剂的气味。"}},{"en":"with a lot of power or force","cn":"强劲地；有力地","ex":{"en":"a light shining strongly","cn":"耀眼的光"}},{"en":"in a way that means something cannot be easily broken or damaged","cn":"坚固地；结实地","ex":{"en":"a strongly built boat","cn":"造得牢固的船"}}]},"media":{"uk":"media/uk/strongly__gb_1.mp3","us":"media/us/strongly__us_1.mp3"},"examples":[{"en":"The room smelt strongly of polish.","cn":"那个房间里散发着浓浓的上光剂的气味。"},{"en":"This is an issue I feel strongly about (= I have firm opinions about).","cn":"这个问题我坚持自己的看法。"}]},"stricken":{"media":{"uk":"media/uk/stricken__gb_1.mp3","us":"media/us/stricken__us_1.mp3"},"oxford":{"phon":"ˈstrɪkən","pos":"adjective","senses":[{"en":"seriously affected by an unpleasant feeling or disease or by a difficult situation","cn":"受煎熬的；患病的；遭受挫折的","ex":{"en":"She raised her stricken face and begged for help.","cn":"她仰起苦闷的脸，乞求帮助。"}},{"en":"seriously affected by the thing mentioned","cn":"遭受…的；受…之困的","ex":{"en":"poverty-stricken families","cn":"贫困家庭"}}]},"collins":{"senses":[{"pos":"","cn":"(strike 某些义项的过去分词)","en":"Stricken is the past participle of some meanings of strike ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受煎熬的;患病的;遭受挫折的;受灾的","en":"If a person or place is stricken by something such as an unpleasant feeling, an illness, or a natural disaster, they are severely affected by it.","ex":{"en":"...a family stricken by genetically inherited cancer","cn":"受遗传性癌症折磨的一家"}}]},"examples":[{"en":"He was stricken by a heart attack on his fiftieth birthday.","cn":"他在五十岁生日那天心脏病发作。"},{"en":"She raised her stricken face and begged for help.","cn":"她仰起苦闷的脸，乞求帮助。"}]},"stoicism":{"oxford":{"phon":"ˈstəʊɪsɪzəm","pos":"noun","senses":[{"en":"the fact of not complaining or showing what you are feeling when you are suffering","cn":"对痛苦的默默承受或泰然处之；坚忍","ex":{"en":"She endured her long illness with stoicism.","cn":"她默默忍受长期的病痛。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"坦然淡定;坚忍克己","en":"Stoicism is stoical behaviour.","ex":{"en":"They bore their plight with stoicism and fortitude.","cn":"他们以坚忍刚毅的精神直面困境。"}}]},"media":{"uk":"media/uk/stoicism__gb_1.mp3","us":"media/us/stoicism__us_1.mp3"},"examples":[{"en":"She endured her long illness with stoicism.","cn":"她默默忍受长期的病痛。"}]},"stuck":{"media":{"uk":"media/uk/stuck__gb_2.mp3","us":"media/us/stuck__us_2.mp3"},"oxford":{"phon":"stʌk","pos":"adjective","senses":[{"en":"unable to move or to be moved","cn":"动不了；无法移动；卡住；陷住","ex":{"en":"The wheels were stuck in the mud.","cn":"车轮陷到了泥里。"}},{"en":"in an unpleasant situation or place that you cannot escape from","cn":"陷（入）；困（于）","ex":{"en":"We were stuck in traffic for over an hour.","cn":"我们堵车堵了一个多小时。"}},{"en":"unable to answer or understand something","cn":"被难住；答不上来；卡壳","ex":{"en":"I got stuck on the first question.","cn":"头一个问题我就答不上来。"}},{"en":"not knowing what to do in a particular situation","cn":"不知所措；（为某事）犯愁","ex":{"en":"If you're stuck for something to do tonight, come out with us.","cn":"你要是正愁今晚没事做，就跟我们一块儿出去吧。"}},{"en":"unable to get rid of somebody/something that you do not want","cn":"摆脱不了；甩不掉","lab":"informal","ex":{"en":"I was stuck with him for the whole journey.","cn":"一路上我一直没能摆脱他。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Stuck is the past tense and past participle of stick ."},{"pos":"ADJ 形容词","cn":"卡住的;动不了的;陷入…的","en":"If something is stuck in a particular position, it is fixed tightly in this position and is unable to move.","ex":{"en":"He said his car had got stuck in the snow","cn":"他说他的汽车陷在了雪地里。"}},{"pos":"ADJ 形容词","cn":"困住的;无法离开的","en":"If you are stuck in a place, you want to get away from it, but are unable to.","ex":{"en":"I was stuck at home with flu","cn":"感冒把我困在了家中。"}},{"pos":"ADJ 形容词","cn":"陷入(无聊或不愉快局面)的;受困的;无法脱身的","en":"If you are stuck in a boring or unpleasant situation, you are unable to change it or get away from it.","ex":{"en":"I don't want to get stuck in another job like that","cn":"我不想陷入另一份那样的工作中。"}},{"pos":"ADJ 形容词","cn":"停滞不前的;无所变化的","en":"If something is stuck at a particular level or stage, it is not progressing or changing.","ex":{"en":"The negotiations have got stuck on a number of key issues","cn":"谈判在一些重大问题上陷入了僵局。"}},{"pos":"ADJ 形容词","cn":"无法摆脱的;甩不掉的","en":"If you are stuck with something that you do not want, you cannot get rid of it.","ex":{"en":"Many people are now stuck with expensive fixed-rate mortgages","cn":"许多人目前都有高额的定息按揭缠身。"}},{"pos":"ADJ 形容词","cn":"难以继续的;被难倒的","en":"If you get stuck when you are trying to do something, you are unable to continue doing it because it is too difficult.","ex":{"en":"They will be there to help if you get stuck","cn":"如果你遇到难题的话他们会帮助你。"}},{"pos":"PHRASE 短语","cn":"起劲地干;下定决心做","en":"If you get stuck in, you do something with enthusiasm and determination.","ex":{"en":"We're bottom of the league and we have to get stuck in.","cn":"我们是联赛的最后一名，所以我们必须拼命赶超。"}}]},"examples":[{"en":"If you're stuck for something to do tonight, come out with us.","cn":"你要是正愁今晚没事做，就跟我们一块儿出去吧。"},{"en":"I've never known him to be stuck for words before.","cn":"我从不知道他也会有词穷句蹇的时候。"}]},"studded":{"media":{"uk":"media/uk/studded__gb_1.mp3","us":"media/us/studded__us_1.mp3"},"oxford":{"phon":"ˈstʌdɪd","pos":"adjective","senses":[{"en":"decorated with small raised pieces of metal","cn":"用饰钉装饰的","ex":{"en":"a studded leather belt","cn":"饰钉装饰的皮带"}},{"en":"having a lot of something on or in it","cn":"布满（或有很多）…的","ex":{"en":"The sky was clear and studded with stars.","cn":"天空晴朗，繁星点点。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"用类似饰钉物装饰的;带饰钉的","en":"Something that is studded is decorated with studs or things that look like studs.","ex":{"en":"...studded leather jackets.","cn":"镶有饰钉的皮夹克"}},{"pos":"ADJ 形容词","cn":"布满…的;有很多…的","en":"If you say that something is studded with another thing, you mean that there are a lot of the second thing in or on the first thing.","ex":{"en":"His collection was studded with Flemish masterpieces.","cn":"他的收藏里有许多佛兰芒人的杰作。"}}]},"examples":[{"en":"The sky was clear and studded with stars.","cn":"天空晴朗，繁星点点。"},{"en":"Stars studded the sky.","cn":"繁星满天。"}]},"strange":{"media":{"uk":"media/uk/strange__gb_1.mp3","us":"media/us/strange__us_1.mp3"},"oxford":{"phon":"streɪndʒ","pos":"adjective","senses":[{"en":"unusual or surprising, especially in a way that is difficult to understand","cn":"奇怪的；奇特的；异常的","ex":{"en":"A strange thing happened this morning.","cn":"今天上午发生了一件怪事。"}},{"en":"not familiar because you have not been there before or met the person before","cn":"陌生的；不熟悉的","ex":{"en":"I am still a stranger in a strange land.","cn":"我仍然是异乡的异乡人。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇怪的;怪异的;意料之外的","en":"Something that is strange is unusual or unexpected, and makes you feel slightly nervous or afraid.","ex":{"en":"Then a strange thing happened","cn":"然后一件奇怪的事发生了。"}},{"pos":"ADJ 形容词","cn":"陌生的;不熟悉的","en":"A strange place is one that you have never been to before. A strange person is someone that you have never met before.","ex":{"en":"I ended up alone in a strange city","cn":"结果，我独自一人来到了一个陌生的城市。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"局促不安的;不自在的;不舒服的","en":"If you feel strange, you have an unpleasant or uncomfortable feeling, either physical or emotional.","ex":{"en":"I felt all dizzy and strange.","cn":"我感到非常头晕、不舒服。"}}]},"examples":[{"en":"I'm looking forward to the exam, strange as it may seem.","cn":"别人可能感到奇怪，我在盼望这场考试。"},{"en":"It's strange how childhood impressions linger.","cn":"童年的印象经久不忘，真是不可思议。"}]},"stringent":{"media":{"uk":"media/uk/stringent__gb_1.mp3","us":"media/us/stringent__us_1.mp3"},"oxford":{"phon":"ˈstrɪndʒənt","pos":"adjective","senses":[{"en":"very strict and that must be obeyed","cn":"严格的；严厉的","ex":{"en":"stringent air quality regulations","cn":"严格的空气质量管理条例"}},{"en":"difficult and with very strict controls because there is not much money","cn":"紧缩的；短缺的；银根紧的","ex":{"en":"the government’s stringent economic policies","cn":"政府紧缩银根的经济政策"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(法律、规则、条件)严格的，严厉的，受严格约束的","en":"Stringent laws, rules, or conditions are very severe or are strictly controlled.","ex":{"en":"He announced that there would be more stringent controls on the possession of weapons","cn":"他宣布将对武器的持有实行更严格的控制。"}}]},"examples":[{"en":"The rules are stringently enforced.","cn":"这些条例得到严格执行。"},{"en":"stringent air quality regulations","cn":"严格的空气质量管理条例"}]},"strategy":{"media":{"uk":"media/uk/strategy__gb_1.mp3","us":"media/us/strategy__us_1.mp3"},"oxford":{"phon":"ˈstrætədʒi","pos":"noun","senses":[{"en":"a plan that is intended to achieve a particular purpose","cn":"策略；计策；行动计划","g":"[countable]","ex":{"en":"the government’s economic strategy","cn":"政府的经济策略"}},{"en":"the process of planning something or putting a plan into operation","cn":"策划；规划；部署；统筹安排","g":"[uncountable]","ex":{"en":"Poor marketing strategy was blamed for the failure of the service to catch on.","cn":"营销策略不当被认为是该业务没能打开局面的原因。"}},{"en":"the skill of planning the movements of armies in a battle or war; an example of doing this","cn":"战略；战略部署","g":"[uncountable, countable]","ex":{"en":"military strategy","cn":"军事战略"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指长期的)战略，策略，行动计划","en":"A strategy is a general plan or set of plans intended to achieve something, especially over a long period.","ex":{"en":"Next week, health ministers gather in Amsterdam to agree a strategy for controlling malaria","cn":"下周，卫生部长们将在阿姆斯特丹聚首共商防治疟疾的策略。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指战争中的)战略，战略学","en":"Strategy is the art of planning the best way to gain an advantage or achieve success, especially in war.","ex":{"en":"I've just been explaining the basic principles of strategy to my generals.","cn":"我刚刚一直在向各位将军解释战略学的基本原理。"}}]},"examples":[{"en":"It's all part of an overall strategy to gain promotion.","cn":"这都不过是一个争取提拔的完整计划的一部分。"},{"en":"to develop a strategy for dealing with unemployment","cn":"制订解决失业问题的对策"}]},"stove":{"media":{"uk":"media/uk/stove__gb_2.mp3","us":"media/us/stove__us_2.mp3"},"oxford":{"phon":"stəʊv","pos":"noun","senses":[{"en":"a piece of equipment that can burn various fuels and is used for heating rooms","cn":"（用于取暖的）炉子，火炉","ex":{"en":"a gas/wood-burning stove","cn":"烧煤气／木柴的火炉"}},{"en":"a large piece of equipment for cooking food, containing an oven and gas or electric rings on top","cn":"（带烤箱、燃气炉或电炉的）厨灶，炉具","lab":"British English also","ex":{"en":"She put a pan of water on the stove.","cn":"她在灶上放了一锅水。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(取暖或做饭用的)炉子，火炉","en":"A stove is a piece of equipment which provides heat, either for cooking or for heating a room.","ex":{"en":"She put the kettle on the gas stove.","cn":"她将水壶放在煤气炉上。"}},{"pos":"N-COUNT 可数名词","cn":"厨灶;炉头","en":"A stove is the top of a cooker."}]},"examples":[{"en":"( NAmE, BrE ) Most people don't want to spend hours slaving over a hot stove (= cooking).","cn":"人们大都不愿意老围着灶台转。"},{"en":"She put a pan of water on the stove.","cn":"她在灶上放了一锅水。"}]},"sted":{"oxford":{"phon":"","pos":"abbr.","senses":[{"en":"stone (a British measurement of weight)","cn":"英石（英国重量单位）"}]}},"stance":{"media":{"uk":"media/uk/stance__gb_1.mp3","us":"media/us/stance__us_1.mp3"},"oxford":{"phon":"stæns","pos":"noun","senses":[{"en":"the opinions that somebody has about something and expresses publicly","cn":"（公开表明的）观点，态度，立场","ex":{"en":"What is the newspaper's stance on the war?","cn":"那家报纸对这场战争持什么立场？"}},{"en":"the way in which somebody stands, especially when playing a sport","cn":"（尤指体育运动中的）站立姿势","ex":{"en":"Widen your stance (= move your feet wider apart) for greater stability when hitting the ball.","cn":"击球时两腿分开一些，这样站得更稳。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"态度;立场","en":"Your stance on a particular matter is your attitude to it.","ex":{"en":"The Congress had agreed to reconsider its stance on the armed struggle","cn":"国会已同意重新考虑其对武装斗争的态度。"}},{"pos":"N-COUNT 可数名词","cn":"站姿","en":"Your stance is the way that you are standing.","ex":{"en":"Take a comfortably wide stance and flex your knees a little","cn":"双腿适度分开站立，双膝稍稍弯曲。"}}]},"examples":[{"en":"What is the newspaper's stance on the war?","cn":"那家报纸对这场战争持什么立场？"},{"en":"What is your stance on environmental issues?","cn":"你在环境问题上持什么立场？"}]},"steals":{"oxford":{"phon":"stiːl","pos":"verb","senses":[{"en":"to take sth from a person, shop/store, etc. without permission and without intending to return it or pay for it","cn":"偷；窃取"},{"en":"to move secretly and quietly so that other people do not notice you","cn":"偷偷地（或悄悄地）移动"}]},"media":{"uk":"media/uk/steal__gb_1.mp3","us":"media/us/steal__us_1.mp3"}},"strike":{"media":{"uk":"media/uk/strike__gb_1.mp3","us":"media/us/strike__us_1.mp3"},"oxford":{"phon":"straɪk","pos":"verb","senses":[{"en":"to hit somebody/something hard or with force","cn":"撞；碰；撞击；碰撞","g":"[transitive, intransitive]","lab":"formal","sc":"hit somebody/something","ex":{"en":"The ship struck a rock.","cn":"船触礁了。"}},{"en":"to hit somebody/something with your hand or a weapon","cn":"打；击","g":"[transitive]","lab":"formal","sc":"hit somebody/something","ex":{"en":"She struck him in the face.","cn":"她掴了他一记耳光。"}},{"en":"to hit or kick a ball, etc.","cn":"击打，踢（球等）","g":"[transitive]","lab":"formal","sc":"kick/hit ball","ex":{"en":"He walked up to the penalty spot and struck the ball firmly into the back of the net.","cn":"他走到罚球点，稳稳地把球踢入网内。"}},{"en":"to attack somebody/something, especially suddenly","cn":"突击；攻击","g":"[intransitive]","sc":"attack","ex":{"en":"The lion crouched ready to strike.","cn":"狮子蹲身准备袭击。"}},{"en":"to happen suddenly and have a harmful or damaging effect on somebody/something","cn":"侵袭；爆发","g":"[intransitive, transitive]","sc":"of disaster/disease","ex":{"en":"Two days later tragedy struck.","cn":"两天后悲剧发生了。"}},{"en":"to come into somebody’s mind suddenly","cn":"突然想到；一下子想起；猛地意识到","g":"[transitive]","sc":"thought/idea/impression","ex":{"en":"An awful thought has just struck me.","cn":"刚才我脑子里突然闪过一个可怕的念头。"}},{"en":"to give somebody a particular impression","cn":"给（某人以…）印象；让（某人）觉得","g":"[transitive]","sc":"thought/idea/impression","ex":{"en":"Another part of his comment struck me.","cn":"他评论中的另一部分令我印象深刻。"}},{"en":"to refuse to work because of an argument over pay or conditions","cn":"罢工","g":"[intransitive]","sc":"of workers","ex":{"en":"Over 100 000 civil servants are set to strike on Tuesday.","cn":"10 万多名公务员计划在周二罢工。"}},{"en":"to fall on a surface","cn":"照在…上；照射","g":"[transitive]","sc":"of light","ex":{"en":"The windows sparkled as the sun struck the glass.","cn":"阳光照得玻璃窗熠熠闪光。"}},{"en":"to put somebody suddenly into a particular state","cn":"顿时使处于某状态","g":"[transitive]","sc":"dumb/deaf/blind","ex":{"en":"to be struck dumb/deaf/blind","cn":"一时什么也说不出／听不见／看不见"}},{"en":"to rub something such as a match against a surface so that it produces a flame; to produce a flame when rubbed against a rough surface","cn":"擦，划（火柴）；击出（火星）","g":"[transitive, intransitive]","sc":"match","ex":{"en":"to strike a match on a wall","cn":"在墙上擦火柴"}},{"en":"to show the time by making a ringing noise, etc.","cn":"敲；鸣；报时","g":"[intransitive, transitive]","sc":"of clock","ex":{"en":"Did you hear the clock strike?","cn":"你听见钟响了吗？"}},{"en":"to produce a musical note, sound, etc. by pressing a key or hitting something","cn":"弹奏；奏响；发出（声音）","g":"[transitive]","sc":"make sound","ex":{"en":"She struck a chord on the piano and the children began to sing.","cn":"她在钢琴上奏出和弦，孩子们开始唱歌。"}},{"en":"to discover gold, oil, etc. by digging or drilling","cn":"开采出；钻探到","g":"[transitive]","sc":"gold/oil, etc.","ex":{"en":"They had struck oil!","cn":"他们开采出了石油！"}},{"en":"to go somewhere with great energy or purpose","cn":"行进；加劲走","g":"[intransitive]","sc":"go with purpose","ex":{"en":"We left the road and struck off across the fields.","cn":"我们下了公路，穿过旷野往前走。"}},{"en":"a period of time when an organized group of employees of a company stops working because of an argument over pay or conditions","cn":"罢工；罢课；罢市","sc":"of workers","ex":{"en":"the miners'/firefighters'/teachers' strike","cn":"矿工／消防队员罢工；教师罢课"},"pos":"noun"},{"en":"a military attack, especially by aircraft dropping bombs","cn":"军事进攻；袭击；（尤指）空袭","sc":"attack","ex":{"en":"They decided to launch a pre-emptive strike.","cn":"他们决定发动先发制人的攻击。"},"pos":"noun"},{"en":"an act of hitting or kicking something/somebody","cn":"击；打；踢","g":"[usually singular]","sc":"hitting/kicking","ex":{"en":"His spectacular strike in the second half made the score 2–0.","cn":"他在下半场令人叹为观止的一脚射门把比分改写为 2:0。"},"pos":"noun"},{"en":"an unsuccessful attempt to hit the ball","cn":"好球（击球未中）","sc":"in baseball","pos":"noun"},{"en":"a situation in tenpin bowling when a player knocks down all the pins with the first ball","cn":"全中（第一球撞倒全部十柱球）","sc":"in bowling","pos":"noun"},{"en":"a sudden discovery of something valuable, especially oil","cn":"（珍贵东西的）意外发现；（尤指石油的）发现","g":"[usually singular]","sc":"discovery of oil","pos":"noun"},{"en":"a bad thing or action that damages somebody/something’s reputation","cn":"（有损声誉的）不利因素，打击","lab":"North American English","sc":"bad thing/action","ex":{"en":"The amount of fuel that this car uses is a big strike against it.","cn":"耗油量大是这辆车的一大缺点。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"罢工","en":"When there is a strike, workers stop doing their work for a period of time, usually in order to try to get better pay or conditions for themselves.","ex":{"en":"French air traffic controllers have begun a three-day strike in a dispute over pay","cn":"法国空中交通管制员因为薪资纠纷已开始了为期 3 天的罢工。"}},{"pos":"VERB 动词","cn":"罢工","en":"When workers strike, they go on strike.","ex":{"en":"...their recognition of the workers' right to strike","cn":"他们对工人罢工权的认同"}},{"pos":"VERB 动词","cn":"打;击","en":"If you strike someone or something, you deliberately hit them.","ex":{"en":"She took two quick steps forward and struck him across the mouth","cn":"她向前紧走两步，上去扇了他一嘴巴。"}},{"pos":"VERB 动词","cn":"撞;碰;撞击;碰撞","en":"If something that is falling or moving strikes something, it hits it.","ex":{"en":"His head struck the bottom when he dived into the 6ft end of the pool","cn":"他一头扎进 6 英尺深的游泳池时头撞到池底了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)撞击;(使)碰撞","en":"If you strike one thing against another, or if one thing strikes against another, the first thing hits the second thing.","ex":{"en":"Wilde fell and struck his head on the stone floor","cn":"怀尔德摔倒了，头撞在石头地上。"}},{"pos":"VERB 动词","cn":"(疾病、灾难等)侵袭，爆发","en":"If something such as an illness or disaster strikes, it suddenly happens.","ex":{"en":"Bank of England officials continued to insist that the pound would soon return to stability but disaster struck","cn":"英格兰银行官员仍然坚持说英镑不久就会恢复稳定，但结果灾难爆发了。"}},{"pos":"VERB 动词","cn":"突击;猛烈攻击","en":"To strike means to attack someone or something quickly and violently.","ex":{"en":"The attacker struck as she was walking near a housing estate at Monacurra","cn":"她行走到莫纳卡拉的一个居民区附近时遭人攻击。"}},{"pos":"N-COUNT 可数名词","cn":"(军事)打击，攻击;(尤指)空袭","en":"A military strike is a military attack, especially an air attack.","ex":{"en":"...a punitive air strike.","cn":"惩罚性空袭"}},{"pos":"VERB 动词","cn":"直击(要害);与…起(原则性)冲突","en":"If something strikes at the heart or root of something, it attacks or conflicts with the basic elements or principles of that thing.","ex":{"en":"...a rejection of her core beliefs and values, which strikes at the very heart of her being","cn":"对她的核心信念和价值观的否定，也就否定了她存在的根本"}},{"pos":"VERB 动词","cn":"突然想到，猛地意识到，一下子想起(想法或念头)","en":"If an idea or thought strikes you, it suddenly comes into your mind.","ex":{"en":"A thought struck her. Was she jealous of her mother, then?","cn":"她猛地冒出一个念头：那么难道她在嫉妒母亲吗？"}},{"pos":"VERB 动词","cn":"给…印象;让…觉得","en":"If something strikes you as being a particular thing, it gives you the impression of being that thing.","ex":{"en":"He struck me as a very serious but friendly person","cn":"他让我感觉他是一个十分严肃但友好的人。"}},{"pos":"VERB 动词","cn":"打动;把…迷住","en":"If you are struck by something, you think it is very impressive, noticeable, or interesting.","ex":{"en":"She was struck by his simple, spellbinding eloquence","cn":"她被他那率直、富有鼓动性的口才迷住了。"}},{"pos":"V-RECIP 相互动词","cn":"达成(交易或协议)","en":"If you strike a deal or a bargain with someone, you come to an agreement with them.","ex":{"en":"They struck a deal with their paper supplier, getting two years of newsprint on credit","cn":"他们同纸张供应商达成协议，可赊购两年的新闻用纸。"}},{"pos":"VERB 动词","cn":"达到(两全其美);找到(折中的办法)","en":"If you strike a balance, you do something that is halfway between two extremes.","ex":{"en":"At times like that you have to strike a balance between sleep and homework.","cn":"在这种情形下你得在休息和做作业之间找到一种平衡。"}},{"pos":"VERB 动词","cn":"摆出(姿态);表现出(态度)","en":"If you strike a pose or attitude, you put yourself in a particular position, for example when someone is taking your photograph.","ex":{"en":"She struck a pose, one hand on her hip and the other waving an imaginary cigarette.","cn":"她摆了个姿势，一只手叉腰，另一只手夹着一支假想的香烟。"}},{"pos":"VERB 动词","cn":"使感到(恐惧或惊慌)","en":"If something strikes fear into people, it makes them very frightened or anxious.","ex":{"en":"If there is a single subject guaranteed to strike fear in the hearts of parents, it is drugs.","cn":"如果只有一样东西定能让父母感到恐惧，那就是毒品。"}},{"pos":"VERB 动词","cn":"使顿时(看不见或说不出)","en":"If you are struck dumb or blind, you suddenly become unable to speak or to see.","ex":{"en":"I was struck dumb by this and had to think it over for a moment","cn":"这让我吃惊得说不出话来，我不得不仔细考虑一会儿。"}},{"pos":"VERB 动词","cn":"(钟表)敲，鸣，报时","en":"When a clock strikes, its bells make a sound to indicate what the time is.","ex":{"en":"The clock struck nine","cn":"钟敲了 9 下。"}},{"pos":"VERB 动词","cn":"删去;划掉","en":"If you strike words from a document or an official record, you remove them.","ex":{"en":"Strike that from the minutes","cn":"从备忘录中将之删去。"}},{"pos":"VERB 动词","cn":"擦，划(火柴)","en":"When you strike a match, you make it produce a flame by moving it quickly against something rough.","ex":{"en":"Robina struck a match and held it to the crumpled newspaper in the grate.","cn":"罗比娜划着一根火柴去点壁炉里揉皱的报纸。"}},{"pos":"VERB 动词","cn":"开采出;钻探到","en":"If someone strikes oil or gold, they discover it in the ground as a result of mining or drilling.","ex":{"en":"Hamilton Oil announced that it had struck oil in the Liverpool Bay area of the Irish Sea.","cn":"汉密尔顿石油公司宣布其已在爱尔兰海域的利物浦海湾地区开采出石油。"}},{"pos":"VERB 动词","cn":"铸造(硬币、奖牌)","en":"When a coin or medal is struck, it is made.","ex":{"en":"Another medal was specially struck for him.","cn":"专门为他铸造了另一枚奖章。"}},{"pos":"N-COUNT 可数名词","cn":"不利条件;挫折","en":"If someone has two strikes against them, things cause them to be in a bad situation or at a disadvantage.","ex":{"en":"The Hotel has two strikes against it. One, it's an immense ugly concrete building. Second, it lies in a rather awkward position","cn":"该旅馆有两个缺点。其一，它是个非常难看的大型混凝土建筑。其二，它位于一个相当偏僻的地段。"}},{"pos":"PHRASE 短语","cn":"近在咫尺","en":"If you are within striking distance of something, or if something is within striking distance, it is quite near, so it could be reached or achieved quite easily.","ex":{"en":"I believe we are within striking distance of an agreement","cn":"我相信我们即将达成协议。"}},{"pos":"PHRASE 短语","cn":"打开成功(或财富)之门;踏上通往成功(或财富)之路","en":"If you strike gold, you find, do, or produce something that brings you a lot of money or success.","ex":{"en":"The company has struck gold with its new holiday development, Center Parcs.","cn":"该公司凭借其新开发的“中央公园”度假村而赚了个盆满钵满。"}},{"pos":"PHRASE 短语","cn":"(尤指)暴富;发大财","en":"If you strike it rich, you make a lot of money, especially in a short time.","ex":{"en":"He hoped to strike it rich by investing in ginseng.","cn":"他希望通过投资人参发大财。"}},{"pos":"","cn":"","en":"to strike a chord→see: ; to strike home→see: ; to strike it lucky→see: ; to strike a happy medium→see: ;"},{"pos":"","cn":"","en":"相关词组：strike back strike down strike off strike out strike up"}]},"examples":[{"en":"His spectacular strike in the second half made the score 2–0.","cn":"他在下半场令人叹为观止的一脚射门把比分改写为 2:0。"},{"en":"In a recent article she strikes out at her critics.","cn":"她最近写了一篇文章，对批评她的人予以驳斥。"}]},"stillness":{"media":{"uk":"media/uk/stillness__gb_1.mp3","us":"media/us/stillness__us_1.mp3","img":["media/ldoce/img/ldoce_318.png"]},"oxford":{"phon":"ˈstɪlnəs","pos":"noun","senses":[{"en":"the quality of being quiet and not moving","cn":"静止；安静；宁静","ex":{"en":"The sound of footsteps on the path broke the stillness.","cn":"小路上的脚步声打破了宁静。"}}]},"examples":[{"en":"The sound of footsteps on the path broke the stillness.","cn":"小路上的脚步声打破了宁静。"},{"en":"We stood still and watched as the deer came closer.","cn":""}]},"steamship":{"media":{"uk":"media/uk/steamship__gb_1.mp3","us":"media/us/steamship__us_1.mp3"},"oxford":{"phon":"ˈstiːmʃɪp","pos":"noun","senses":[{"en":"a ship driven by steam","cn":"汽船；轮船"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"汽船;轮船","en":"A steamship is a ship that has an engine powered by steam."}]}},"strengthened":{"oxford":{"phon":"ˈstreŋθn","pos":"verb","senses":[{"en":"to become stronger; to make sb/sth stronger","cn":"加强；增强；巩固"}]}},"storage":{"media":{"uk":"media/uk/storage__gb_1.mp3","us":"media/us/storage__us_1.mp3"},"oxford":{"phon":"ˈstɔːrɪdʒ","pos":"noun","senses":[{"en":"the process of keeping something in a particular place until it is needed; the space where things can be kept","cn":"贮存，贮藏（空间）","ex":{"en":"tables that fold flat for storage","cn":"便于存放的折叠桌"}},{"en":"the process of keeping information, etc. on a computer; the way it is kept","cn":"存储（方式）","lab":"computing","ex":{"en":"the storage and retrieval of information","cn":"信息的存储与检索"}},{"en":"the process of paying to keep furniture, etc. in a special building until you want it","cn":"付费托管","ex":{"en":"When we moved we had to put our furniture in storage for a while.","cn":"搬家时我们不得不把家具送出去存放一阵子。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"储藏;贮存","en":"If you refer to the storage of something, you mean that it is kept in a special place until it is needed.","ex":{"en":"...the storage of toxic waste","cn":"有毒废弃物的存放"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(计算机的)存储","en":"Storage is the process of storing data in a computer.","ex":{"en":"His task is to ensure the fair use and storage of personal information held on computer.","cn":"他的任务是确保计算机里的个人信息得到合理利用和妥善存储。"}}]},"examples":[{"en":"When we moved we had to put our furniture in storage for a while.","cn":"搬家时我们不得不把家具送出去存放一阵子。"},{"en":"We need more storage now.","cn":"现在我们需要更多的贮存场所。"}]},"sting":{"oxford":{"phon":"stɪŋ","pos":"verb","senses":[{"en":"to touch your skin or make a very small hole in it so that you feel a sharp pain","cn":"刺；蜇；叮","g":"[transitive, intransitive]","ex":{"en":"I was stung on the arm by a wasp.","cn":"我的胳膊给黄蜂蜇了一下。"}},{"en":"to feel, or to make somebody feel, a sharp pain in a part of their body","cn":"（使）感觉刺痛，感觉灼痛","g":"[intransitive, transitive]","ex":{"en":"I put some antiseptic on the cut and it stung for a moment.","cn":"我在割破的地方抹了点抗菌剂，一时间十分刺痛。"}},{"en":"to make somebody feel angry or upset","cn":"激怒；使不安","g":"[transitive]","ex":{"en":"He was stung by their criticism.","cn":"他们的批评使他心烦意乱。"}},{"en":"to charge somebody more money than they expected; to charge somebody who did not expect to pay","cn":"对（某人）敲竹杠；敲诈；欺诈","g":"[transitive, often passive]","lab":"informal","ex":{"en":"I got stung for a £100 meal.","cn":"我挨宰了，一顿饭吃了 100 英镑。"}},{"en":"to borrow money from somebody","cn":"向某人借钱","lab":"British English, informal，，","ex":{"en":"Can I sting you for a couple of pounds?","cn":"我可以蜇你几磅吗？"}},{"en":"the sharp pointed part of an insect or creature that can go into the skin leaving a small, painful and sometimes poisonous wound","cn":"（昆虫的）螫针，刺；（植物的）刺，刺毛","g":"[countable]","lab":"North American English also","ex":{"en":"the sting of a bee","cn":"蜜蜂的螫针"},"pos":"noun"},{"en":"a wound that is made when an insect, a creature or a plant stings you","cn":"刺伤；蜇伤；叮伤","g":"[countable]","ex":{"en":"A wasp or bee sting is painful but not necessarily serious.","cn":"被黄蜂或蜜蜂蜇一下疼是疼，但未必碍事。"},"pos":"noun"},{"en":"any sharp pain in your body or mind","cn":"（身体或心灵的）剧痛，痛苦","g":"[countable, uncountable]","ex":{"en":"the sting of salt in a wound","cn":"伤口上撒盐引起的剧痛"},"pos":"noun"},{"en":"a clever secret plan by the police to catch criminals","cn":"（警察为抓捕罪犯而设的）圈套","g":"[countable]","ex":{"en":"The FBI conducted a sting operation to catch heroin dealers in Detroit.","cn":"联邦调查局设了圈套在底特律抓捕海洛因贩子。"},"pos":"noun"},{"en":"a clever plan by criminals to cheat people out of a lot of money","cn":"（罪犯诈骗钱财的）骗局，诡计","g":"[countable]","lab":"especially North American English","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"刺;叮;蜇","en":"If a plant, animal, or insect stings you, a sharp part of it, usually covered with poison, is pushed into your skin so that you feel a sharp pain.","ex":{"en":"The nettles stung their legs","cn":"荨麻扎了他们的腿。"}},{"pos":"N-COUNT 可数名词","cn":"(昆虫、动物的)螫刺，螫针，刺","en":"The sting of an insect or animal is the part that stings you.","ex":{"en":"Remove the bee sting with tweezers.","cn":"用镊子拔掉蜜蜂的螫刺。"}},{"pos":"N-COUNT 可数名词","cn":"刺伤;叮伤;蜇痛","en":"If you feel a sting, you feel a sharp pain in your skin or other part of your body.","ex":{"en":"This won't hurt — you will just feel a little sting.","cn":"这不痛——你只会感觉到像被轻轻叮了一下。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)感到刺痛;(使)感到灼痛","en":"If a part of your body stings, or if a substance stings it, you feel a sharp pain there.","ex":{"en":"His cheeks were stinging from the icy wind","cn":"刺骨的寒风吹得他脸颊生疼。"}},{"pos":"VERB 动词","cn":"(言谈)刺痛，刺伤，惹恼","en":"If someone's remarks sting you, they make you feel hurt and annoyed.","ex":{"en":"He's a sensitive lad and some of the criticism has stung him","cn":"他是个敏感的小伙子，有些批评刺痛了他。"}},{"pos":"N-COUNT 可数名词","cn":"(警方为抓捕罪犯精心设计的)圈套","en":"A sting is a clever secret plan carried out by the police in order to catch criminals.","ex":{"en":"The police ran a sting operation to crack down on illegal guns.","cn":"警方展开诱捕行动以严打非法枪支。"}},{"pos":"PHRASE 短语","cn":"煞风景的结局;令人不愉快的结尾","en":"If an announcement or decision has a sting in the tail or a sting in its tail, it contains a critical and unpleasant part, normally at the end."},{"pos":"PHRASE 短语","cn":"减少麻烦;减轻不愉快","en":"If something takes the sting out of a situation, it makes it less unpleasant."}]},"media":{"uk":"media/uk/sting__gb_1.mp3","us":"media/us/sting__us_1.mp3"},"examples":[{"en":"I put some antiseptic on the cut and it stung for a moment.","cn":"我在割破的地方抹了点抗菌剂，一时间十分刺痛。"},{"en":"He smiled at her, trying to take the sting out of his words (= trying to make the situation less painful or difficult).","cn":"他冲她微微一笑，想使他的话不至于刺痛她。"}]},"strength":{"media":{"uk":"media/uk/strength__gb_1.mp3","us":"media/us/strength__us_1.mp3"},"oxford":{"phon":"streŋkθ","pos":"noun","senses":[{"en":"the quality of being physically strong","cn":"体力；力气；力量","g":"[uncountable, singular]","sc":"being physically strong","ex":{"en":"He pushed against the rock with all his strength.","cn":"他用全力推那块石头。"}},{"en":"the ability that something has to resist force or hold heavy weights without breaking or being damaged","cn":"强度","g":"[uncountable]","sc":"being physically strong","ex":{"en":"the strength of a rope","cn":"绳子的强度"}},{"en":"the quality of being brave and determined in a difficult situation","cn":"毅力；坚强决心；意志力量","g":"[uncountable, singular]","sc":"being brave","ex":{"en":"During this ordeal he was able to draw strength from his faith.","cn":"在这次磨难中，他得以从自己的信仰中吸取力量。"}},{"en":"the power and influence that somebody/something has","cn":"实力","g":"[uncountable]","sc":"power/influence","ex":{"en":"Political power depends upon economic strength.","cn":"政治权力取决于经济实力。"}},{"en":"how strong or deeply felt an opinion or a feeling is","cn":"强烈程度；深度","g":"[uncountable]","sc":"of opinion/feeling","ex":{"en":"the strength of public opinion","cn":"公众舆论的强烈程度"}},{"en":"a quality or an ability that a person or thing has that gives them an advantage","cn":"优势；优点；长处","g":"[countable]","sc":"advantage","ex":{"en":"The ability to keep calm is one of her many strengths.","cn":"能够保持冷静是她的多项长处之一。"}},{"en":"how strong a natural force or a signal is","cn":"强度；力度","g":"[uncountable]","sc":"of natural force","ex":{"en":"the strength of the sun","cn":"太阳的强度"}},{"en":"how strong a particular taste or substance is","cn":"浓度；浓淡程度","g":"[uncountable, countable]","sc":"of taste/substance","ex":{"en":"Add more curry powder depending on the strength required.","cn":"按所要求的口味轻重再加点咖喱粉。"}},{"en":"how strong a country’s currency is in relation to other countries’ currencies","cn":"强弱（程度）","g":"[uncountable]","sc":"of currency","ex":{"en":"the relative strength of the euro against the dollar","cn":"欧元对美元的相对强弱程度"}},{"en":"the number of people in a group, a team or an organization","cn":"人数多寡；人力","g":"[uncountable]","sc":"number in group","ex":{"en":"The strength of the workforce is about to be doubled from 3 000 to 6 000.","cn":"职工人数将翻一番，由 3 000 人增加到 6 000 人。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"体力;力气;力量","en":"Your strength is the physical energy that you have, which gives you the ability to perform various actions, such as lifting or moving things.","ex":{"en":"She has always been encouraged to swim to build up the strength of her muscles","cn":"一直有人鼓励她去游泳以强健体魄。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(面对困境的)信心，勇气","en":"Someone's strength in a difficult situation is their confidence or courage.","ex":{"en":"Something gave me the strength to overcome the difficulty","cn":"有些事给了我克服困难的勇气。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强度","en":"The strength of an object or material is its ability to be treated roughly, or to carry heavy weights, without being damaged or destroyed.","ex":{"en":"He checked the strength of the cables.","cn":"他检查了一下钢索的强度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"实力;影响力","en":"The strength of a person, organization, or country is the power or influence that they have.","ex":{"en":"America values its economic leadership, and the political and military strength that goes with it","cn":"美国重视其经济领导地位以及随之产生的政治和军事实力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(情感、意见、信念的)深度，强烈程度，影响程度","en":"If you refer to the strength of a feeling, opinion, or belief, you are talking about how deeply it is felt or believed by people, or how much they are influenced by it.","ex":{"en":"He was surprised at the strength of his own feeling","cn":"他感情之强烈令他自己都很吃惊。"}},{"pos":"N-VAR 可变名词","cn":"优势;优点;长处","en":"Someone's strengths are the qualities and abilities that they have which are an advantage to them, or which make them successful.","ex":{"en":"Take into account your own strengths and weaknesses","cn":"考虑一下你自己的优缺点。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(货币、经济、工业的)坚挺","en":"If you refer to the strength of a currency, economy, or industry, you mean that its value or success is steady or increasing.","ex":{"en":"...the long-term competitive strength of the American economy","cn":"美国经济的长期竞争力"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人数;人力","en":"The strength of a group of people is the total number of people in it.","ex":{"en":"...elite forces, comprising about one-tenth of the strength of the army.","cn":"约占军队总人数1/10的精锐部队"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(风等的)强度，力度，速度","en":"The strength of a wind, current, or other force is its power or speed.","ex":{"en":"Its oscillation depends on the strength of the gravitational field","cn":"它的振动幅度取决于引力场的强度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(饮料、化学品、药品的)浓度，浓淡程度","en":"The strength of a drink, chemical, or drug is the amount of the particular substance in it that gives it its particular effect.","ex":{"en":"It is very alcoholic, sometimes near the strength of port","cn":"它的酒精浓度很高，有时接近波尔图葡萄酒的浓度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(味道、气味、颜色、声音、光照的)程度","en":"You can talk about the strength of a flavour, smell, colour, sound, or light to describe how intense or easily noticed it is.","ex":{"en":"The wine has lots of strength of flavour.","cn":"该酒口味醇厚。"}},{"pos":"PHRASE 短语","cn":"日益兴隆;不断取得成功;信心倍增","en":"If a person or organization goes from strength to strength, they become more and more successful or confident.","ex":{"en":"Since her heart and lung transplant operation she has gone from strength to strength","cn":"做过心肺移植手术后，她的身体不断好转。"}},{"pos":"PHRASE 短语","cn":"(队伍或军队的)全员，满员，最佳阵容","en":"If a team or army is at full strength, all the members that it needs or usually has are present.","ex":{"en":"He needed more time to bring US forces there up to full strength.","cn":"他需要更多时间来增派兵力，以确保驻扎在那里的美国军队兵力充足。"}},{"pos":"PHRASE 短语","cn":"大量，大批(聚集)","en":"If a group turns out in strength, they arrive in large numbers.","ex":{"en":"Mr Gore called on voters and party workers to turn out in strength","cn":"戈尔先生号召选民和政党工作人员积极前来投票。"}},{"pos":"PHRASE 短语","cn":"在…的影响下;凭借;依赖","en":"If one thing is done on the strength of another, it is done because of the influence of that other thing.","ex":{"en":"He was elected to power on the strength of his charisma","cn":"他凭借其个人魅力而当选掌权。"}},{"pos":"PHRASE 短语","cn":"(军队或队伍)人员不足，阵容不全","en":"If an army or team is under strength or below strength, it does not have all the members that it needs or usually has.","ex":{"en":"His regiments were considerably under strength","cn":"他的几个团兵力严重不足。"}}]},"examples":[{"en":"The strength of the workforce is about to be doubled from 3 000 to 6 000.","cn":"职工人数将翻一番，由 3 000 人增加为 6 000 人。"},{"en":"During this ordeal he was able to draw strength from his faith.","cn":"在这次磨难中，他得以从自己的信仰中吸取力量。"}]},"stocked":{"oxford":{"phon":"stɒk","pos":"noun","senses":[{"en":"a supply of goods that is available for sale in a shop/store （","cn":"商店的）现货，存货，库存"},{"en":"a supply of sth that is available for use","cn":"储备物；备用物；供应物"}]}},"stop":{"media":{"uk":"media/uk/stop__gb_1.mp3","us":"media/us/stop__us_1.mp3"},"oxford":{"phon":"stɒp","pos":"verb","senses":[{"en":"to no longer move; to make somebody/something no longer move","cn":"（使）停止，停下","g":"[intransitive, transitive]","sc":"not move","ex":{"en":"The car stopped at the traffic lights.","cn":"汽车在交通信号灯前停了下来。"}},{"en":"to no longer continue to do something; to make somebody/something no longer do something","cn":"（使）中断，停止","g":"[intransitive, transitive]","lab":"formal","sc":"not continue","ex":{"en":"Can't you just stop?","cn":"你就不能停一停吗？"}},{"en":"to end or finish; to make something end or finish","cn":"（使）结束，终止","g":"[intransitive, transitive]","sc":"end","ex":{"en":"When is this fighting going to stop?","cn":"这场战斗要打到什么时候？"}},{"en":"to prevent somebody from doing something; to prevent something from happening","cn":"阻止；阻碍；阻拦；防止","g":"[transitive]","sc":"prevent","ex":{"en":"I want to go and you can't stop me.","cn":"我要走，你拦不住我。"}},{"en":"to end an activity for a short time in order to do something","cn":"暂停，暂时中断（以便做某事）","g":"[intransitive]","sc":"for short time","ex":{"en":"I'm hungry. Let's stop for lunch.","cn":"我饿了。我们停下来吃午饭吧。"}},{"en":"to no longer be working or functioning; to make something be no longer working or functioning","cn":"（使）停止工作，停止运转","g":"[intransitive, transitive]","sc":"not function","ex":{"en":"Why has the engine stopped?","cn":"发动机怎么停了？"}},{"en":"to stay somewhere for a short time, especially at somebody’s house","cn":"逗留，待，留下（做某事）","g":"[intransitive]","lab":"British English, informal，，","sc":"stay","ex":{"en":"I'm not stopping. I just came to give you this message.","cn":"我不待了。我就是来告诉你这件事。"}},{"en":"to prevent money from being paid","cn":"止付；停付；扣除","g":"[transitive]","lab":"British English","sc":"money","ex":{"en":"to stop a cheque (= tell the bank not to pay it)","cn":"通知银行止付支票"}},{"en":"to block, fill or close a hole, an opening, etc.","cn":"堵塞；塞住；阻塞","g":"[transitive]","sc":"close hole","ex":{"en":"Stop up the other end of the tube, will you?","cn":"你把管子的另一头堵上好不好？"}},{"en":"a place where a bus or train stops regularly for passengers to get on or off","cn":"车站","lab":"North American English","sc":"of bus/train","ex":{"en":"I get off at the next stop.","cn":"我在下一站下车。"},"pos":"noun"},{"en":"an act of stopping or stopping something; the state of being stopped","cn":"停止；终止；停留；阻止","sc":"act of stopping","ex":{"en":"The trip included an overnight stop in Brussels.","cn":"这次旅行需要在布鲁塞尔停留过夜。"},"pos":"noun"},{"en":"the mark ( . ) used at the end of a sentence and in some abbreviations, for example e.g.","cn":"句点；句号","lab":"more frequent","sc":"punctuation","pos":"noun"},{"en":"a row of pipes on an organ that produce the different sounds","cn":"（管风琴的）音管","sc":"music","pos":"noun"},{"en":"a handle on an organ that the player pushes in or pulls out to control the sound produced by the pipes","cn":"（管风琴的）音栓","sc":"music","pos":"noun"},{"en":"a speech sound made by stopping the flow of air coming out of the mouth and then suddenly releasing it, for example /p/, /k/, /t/","cn":"塞音","sc":"phonetics","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"停止;停下","en":"If you have been doing something and then you stop doing it, you no longer do it.","ex":{"en":"Stop throwing those stones!","cn":"不要再扔那些石头了！"}},{"pos":"VERB 动词","cn":"阻止;使中断;使停止","en":"If you stop something happening, you prevent it from happening or prevent it from continuing.","ex":{"en":"He proposed a new diplomatic initiative to try to stop the war","cn":"他提出了一项新的外交计划以尽力阻止这场战争。"}},{"pos":"VERB 动词","cn":"(活动或过程)停下来，中止","en":"If an activity or process stops, it is no longer happening.","ex":{"en":"The rain had stopped and a star or two was visible over the mountains","cn":"雨停了，山顶上有一两颗星星在闪烁。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(机器等)停止运转;(使)停止工作","en":"If something such as machine stops or is stopped, it is no longer moving or working.","ex":{"en":"The clock had stopped at 2.12 a.m","cn":"钟在凌晨 2 点 12 分时停了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(移动着的人或车)停下;把…拦住","en":"When a moving person or vehicle stops or is stopped, they no longer move and they remain in the same place.","ex":{"en":"The car failed to stop at an army checkpoint","cn":"那辆车没有在军方检查站停车。"}},{"pos":"N-SING 单数名词","cn":"停住;停下","en":"If something that is moving comes to a stop or is brought to a stop, it slows down and no longer moves.","ex":{"en":"People often wrongly open doors before the train has come to a stop","cn":"人们经常在火车还尚未完全停好时就违规打开车门。"}},{"pos":"VERB 动词","cn":"停下来(思考或解释)","en":"If someone does not stop to think or to explain, they continue with what they are doing without taking any time to think about or explain it.","ex":{"en":"She doesn't stop to think about what she's saying","cn":"她都没有停下来想一想自己在说些什么。"}},{"pos":"VERB 动词","cn":"止于;结束","en":"If you say that a quality or state stops somewhere, you mean that it exists or is true up to that point, but no further.","ex":{"en":"The cafe owner has put up the required 'no smoking' signs, but thinks his responsibility stops there","cn":"咖啡馆老板已经按规定贴上了“禁止吸烟”的标志，但是他认为自己的责任就止于此。"}},{"pos":"N-COUNT 可数名词","cn":"车站;停车站","en":"A stop is a place where buses or trains regularly stop so that people can get on and off.","ex":{"en":"There was an Underground map above one of the windows and I counted the stops to West Hampstead","cn":"其中一扇窗户上方有一张地铁线路图，我数了数到西汉普斯特德站共有几站。"}},{"pos":"VERB 动词","cn":"(旅程中)逗留，停留","en":"If you stop somewhere on a journey, you stay there for a short while.","ex":{"en":"He insisted we stop at a small restaurant just outside of Atlanta","cn":"他坚持让我们在亚特兰大市外不远的一家小餐馆歇歇脚。"}},{"pos":"N-COUNT 可数名词","cn":"(旅程中的)停留时间，停留地","en":"A stop is a time or place at which you stop during a journey.","ex":{"en":"The last stop in Mr Cook's lengthy tour was Paris","cn":"库克先生漫长旅程中的最后一站是巴黎。"}},{"pos":"N-COUNT 可数名词","cn":"(风琴的)音栓","en":"In music, organ stops are the knobs at the side of the organ, which you pull or push in order to control the type of sound that comes out of the pipes."},{"pos":"PHRASE 短语","cn":"不择手段;无所顾忌","en":"If you say that someone will stop at nothing to get something, you are emphasizing that they are willing to do things that are extreme, wrong, or dangerous in order to get it.","ex":{"en":"Their motive is money, and they will stop at nothing to get it.","cn":"他们的动机是钱，为了钱他们会不择手段。"}},{"pos":"PHRASE 短语","cn":"全力以赴;竭尽全力","en":"If you pull out all the stops, you do everything you can to make something happen or succeed.","ex":{"en":"New Zealand police vowed yesterday to pull out all the stops to find the killer.","cn":"新西兰警方昨天发誓要竭尽全力抓到杀人凶手。"}},{"pos":"PHRASE 短语","cn":"制止;阻止","en":"If you put a stop to something that you do not like or approve of, you prevent it from happening or continuing.","ex":{"en":"His daughter should have stood up and put a stop to all these rumours.","cn":"他的女儿早该站出来平息所有这些谣言。"}},{"pos":"PHRASE 短语","cn":"做事很有分寸;懂得如何把持自己","en":"If you say that someone does not know when to stop, you mean that they do not control their own behaviour very well and so they often annoy or upset other people.","ex":{"en":"Like many politicians before him, Mr Bentley did not know when to stop","cn":"和过去的很多政客一样，本特利先生做事也没分寸。"}},{"pos":"","cn":"","en":"to stop dead→see: ; to stop short of→see: ; to stop someone in their tracks→see: ;"},{"pos":"","cn":"","en":"相关词组：stop by stop off stop up"}]},"examples":[{"en":"( BrE ) Dad threatened to stop £1 a week from our pocket money if we didn't clean our rooms.","cn":"父亲威胁说，我们要是不把自己的房间收拾干净，他就每星期扣我们 1 英镑的零花钱。"},{"en":"Babies do not grow at a steady rate but in stops and starts.","cn":"婴儿成长的速度并非一成不变，而是长长停停，停停长长。"}]},"steel":{"media":{"img":["media/pic/cutting_kitchenutensils_comp.jpg","media/thumb/steel.jpg"],"uk":"media/uk/steel__gb_1.mp3","us":"media/us/steel__us_1.mp3"},"oxford":{"phon":"stiːl","pos":"noun","senses":[{"en":"a strong, hard metal that is made of a mixture of iron and carbon","cn":"钢","g":"[uncountable]","ex":{"en":"the iron and steel industry","cn":"钢铁工业"}},{"en":"the industry that produces steel","cn":"钢铁工业","g":"[uncountable]","ex":{"en":"Steel used to be important in South Wales.","cn":"以前钢铁工业在南威尔士很重要。"}},{"en":"a long, thin, straight piece of steel with a rough surface, used for rubbing knives on to make them sharp","cn":"钢制磨刀棒","g":"[countable]"},{"en":"weapons that are used for fighting","cn":"兵器","g":"[uncountable]","lab":"old use or literary","ex":{"en":"the clash of steel","cn":"刀剑交击的哐当声"}},{"en":"to prepare yourself to deal with something unpleasant","cn":"准备对付；下决心应付","ex":{"en":"As she waited, she steeled herself for disappointment.","cn":"她等着的时候，就冷了心不指望了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"钢;钢铁","en":"Steel is a very strong metal which is made mainly from iron. Steel is used for making many things, for example bridges, buildings, vehicles, and cutlery.","ex":{"en":"...steel pipes.","cn":"钢管"}},{"pos":"N-UNCOUNT 不可数名词","cn":"钢铁工业;钢铁生产","en":"Steel is used to refer to the industry that produces steel and items made of steel.","ex":{"en":"...a three-month study of European steel","cn":"对欧洲钢铁工业为期 3 个月的考察研究"}},{"pos":"VERB 动词","cn":"准备应付(不愉快的事)","en":"If you steel yourself, you prepare to deal with something unpleasant.","ex":{"en":"Those involved are steeling themselves for the coming battle","cn":"那些参与者正准备迎接即将到来的战斗。"}}]},"examples":[{"en":"She felt a hand of steel (= a strong, firm hand) on her arm.","cn":"她感觉一只有力的手抓住了她的胳膊。"},{"en":"You need a cool head and nerves of steel (= great courage).","cn":"你需要有冷静的头脑、非常的魄力。"}]},"sth":{"oxford":{"phon":"ˈsʌmθɪŋ","pos":"pronoun","senses":[{"en":"a thing that is not known or mentioned by name","cn":"某事；某物"},{"en":"( informal ) a thing that is thought to be important or worth taking notice of","cn":"想来重要（或值得注意）的事物"}]}},"states":{"oxford":{"phon":"steɪt","pos":"noun","senses":[{"en":"the mental, emotional or physical condition that a person or thing is in","cn":"状态；状况；情况"},{"en":"a country considered as an organized political community controlled by one government","cn":"国家"}]},"media":{"uk":"media/ldoce/hwd/bre/d/p028-000011554.mp3","us":"media/ldoce/hwd/ame/d/p028-000011554.mp3"}},"strengths":{"oxford":{"phon":"streŋθ","pos":"noun","senses":[{"en":"the quality of being physically strong","cn":"体力；力气；力量"},{"en":"the ability that sth has to resist force or hold heavy weights without breaking or being damaged","cn":"强度"}]}},"stabilizing":{"oxford":{"phon":"ˈsteɪbəlaɪz","pos":"verb","senses":[{"en":"to become or to make sth become firm, steady and unlikely to change; to make sth stable （","cn":"使）稳定，稳固"}]}},"streets":{"oxford":{"phon":"striːt","pos":"noun","senses":[{"en":"a public road in a city or town that has houses and buildings on one side or both sides","cn":"大街；街道"},{"en":"the ideas and opinions of ordinary people, especially people who live in cities, which are considered important （","cn":"尤指城市里）街头民意"}]}},"stereotypes":{"oxford":{"phon":"ˈsteriətaɪp","pos":"noun","senses":[{"en":"a fixed idea or image that many people have of a particular type of person or thing, but which is often not true in reality","cn":"模式化观念（或形象）；老一套；刻板印象"},{"en":"to form a fixed idea about a person or thing which may not really be true","cn":"对 … 形成模式化（或类型化）的看法"}]}},"stepping":{"oxford":{"phon":"step","pos":"noun","senses":[{"en":"the act of lifting your foot and putting it down in order to walk or move somewhere; the sound this makes","cn":"迈步；脚步声"},{"en":"the way that sb walks","cn":"步伐；步态"}]}},"stronger":{"oxford":{"phon":"strɒŋ","pos":"adj.","senses":[{"en":"having a lot of physical power so that you can lift heavy weights, do hard physical work, etc.","cn":"强壮的；强健的"},{"en":"having great power","cn":"强的；强劲的"}]}},"storytellers":{"oxford":{"phon":"ˈstɔːritelə(r)","pos":"noun","senses":[{"en":"a person who tells or writes stories","cn":"讲故事的人；故事（或小说）作者"}]}},"stores":{"oxford":{"phon":"stɔː(r)","pos":"noun","senses":[{"en":"a large shop that sells many different types of goods （","cn":"大型）百货商店"},{"en":"( NAmE ) a shop, large or small","cn":"商店；店铺"}]}},"strongest":{"oxford":{"phon":"strɒŋ","pos":"adj.","senses":[{"en":"having a lot of physical power so that you can lift heavy weights, do hard physical work, etc.","cn":"强壮的；强健的"},{"en":"having great power","cn":"强的；强劲的"}]}},"styles":{"oxford":{"phon":"staɪl","pos":"noun","senses":[{"en":"the particular way in which sth is done","cn":"方式；作风"},{"en":"a particular design of sth, especially clothes","cn":"样式；款式"}]}},"stalks":{"oxford":{"phon":"stɔːk","pos":"noun","senses":[{"en":"a thin stem that supports a leaf, flower or fruit and joins it to another part of the plant or tree; the main stem of a plant （","cn":"叶）柄；（花）梗；（果实的）柄；（植物的）茎，秆"},{"en":"a long thin structure that supports sth, especially an organ in some animals, and joins it on to another part","cn":"柄；（动物的）肉柄，肉茎"}]}},"stomachs":{"oxford":{"phon":"ˈstʌmək","pos":"noun","senses":[{"en":"the organ inside the body where food goes when you swallow it; the front part of the body below the chest","cn":"胃；腹部"},{"en":"to not want to eat sth","cn":"不想吃 … ；对 … 没有胃口"}]}},"struggled":{"oxford":{"phon":"ˈstrʌɡl","pos":"verb","senses":[{"en":"to try very hard to do sth when it is difficult or when there are a lot of problems","cn":"奋斗；努力；争取"},{"en":"to move somewhere or do sth with difficulty","cn":"艰难地行进；吃力地进行"}]}},"stragglers":{"oxford":{"phon":"ˈstræɡlə(r)","pos":"noun","senses":[{"en":"a person or an animal that is among the last or the slowest in a group to do sth, for example, to finish a race or leave a place","cn":"掉队者；落在最后的人（或动物）"}]}},"stays":{"oxford":{"phon":"steɪ","pos":"verb","senses":[{"en":"to continue to be in a particular place for a period of time without moving away","cn":"停留；待"},{"en":"In spoken English stay can be used with and plus another verb, instead of with to and the infinitive, to show purpose or to tell somebody what to do.","cn":"英语口语中，stay 后面可接 and 加另一个动词，而不用 to 加不定式，以表示目的或要某人做某事"}]}},"statements":{"oxford":{"phon":"ˈsteɪtmənt","pos":"noun","senses":[{"en":"something that you say or write that gives information or an opinion","cn":"说明；说法；表白；表态"},{"en":"a formal or official account of facts or opinions","cn":"声明；陈述；报告"}]}},"stairs":{"oxford":{"phon":"steə(r)","pos":"noun","senses":[{"en":"a set of steps built between two floors inside a building","cn":"楼梯"},{"en":"one of the steps in a set of stairs","cn":"梯级"}]}},"stipulated":{"oxford":{"phon":"ˈstɪpjuleɪt","pos":"verb","senses":[{"en":"to state clearly and firmly that sth must be done, or how it must be done","cn":"规定；明确要求"}]}},"stations":{"oxford":{"phon":"ˈsteɪʃn","pos":"noun","senses":[{"en":"a place where trains stop so that passengers can get on and off; the buildings connected with this","cn":"火车站"},{"en":"( usually in compounds","cn":"通常构成复合词 ) a place where buses stop; the buildings connected with this 公共汽车站；长途汽车站"}]}},"stemmed":{"oxford":{"phon":"stem","pos":"noun","senses":[{"en":"the main long thin part of a plant above the ground from which the leaves or flowers grow; a smaller part that grows from this and supports flowers or leaves （","cn":"花草的）茎；（花或叶的）梗，柄"},{"en":"the long thin part of a wine glass between the bowl and the base （","cn":"高脚酒杯的）脚"}]}},"strangling":{"oxford":{"phon":"ˈstræŋɡl","pos":"verb","senses":[{"en":"to kill sb by squeezing or pressing on their throat and neck","cn":"扼死；勒死；掐死"},{"en":"to prevent sth from growing or developing","cn":"抑制；压制；扼杀"}]}},"strategies":{"oxford":{"phon":"ˈstrætədʒi","pos":"noun","senses":[{"en":"a plan that is intended to achieve a particular purpose","cn":"策略；计策；行动计划"},{"en":"the process of planning sth or putting a plan into operation in a skilful way","cn":"策划；规划；部署；统筹安排"}]}},"stouter":{"oxford":{"phon":"staʊt","pos":"adjective","senses":[{"en":"rather fat","cn":"肥胖的；肥壮的"},{"en":"strong and thick","cn":"粗壮结实的；厚实牢固的"}]}},"starting":{"oxford":{"phon":"stɑːt","pos":"verb","senses":[{"en":"to begin doing or using sth","cn":"开始，着手，动手（做或使用）"},{"en":"to start happening; to make sth start happening （","cn":"使）发生，开始进行"}]}},"storeys":{"oxford":{"phon":"ˈstɔːri","pos":"noun","senses":[{"en":"a level of a building; a floor","cn":"楼层"},{"en":"having the number of levels mentioned","cn":"有 … 层的"}]}},"stammered":{"oxford":{"phon":"ˈstæmə(r)","pos":"verb","senses":[{"en":"to speak with difficulty, repeating sounds or words and often stopping, before saying things correctly","cn":"口吃；结结巴巴地说"},{"en":"a problem that sb has in speaking in which they repeat sounds or words or often pause before saying things correctly","cn":"口吃；结巴"}]}},"studios":{"oxford":{"phon":"ˈstjuːdiəʊ","pos":"noun","senses":[{"en":"a room where radio or television programmes are recorded and broadcast from, or where music is recorded （","cn":"广播、电视的）录音室，录像室，演播室，制作室；（音乐）录音棚"},{"en":"a place where films/movies are made or produced","cn":"电影摄影棚"}]}},"stories":{"oxford":{"phon":"ˈstɔːri","pos":"noun","senses":[{"en":"a description of events and people that the writer or speaker has invented in order to entertain people （","cn":"虚构的）故事；小说"},{"en":"an account, often spoken, of what happened to sb or of how sth happened （","cn":"真实情况的）叙述，描述"}]}},"stolen":{"oxford":{"phon":"stiːl","pos":"verb","senses":[{"en":"to take sth from a person, shop/store, etc. without permission and without intending to return it or pay for it","cn":"偷；窃取"},{"en":"to move secretly and quietly so that other people do not notice you","cn":"偷偷地（或悄悄地）移动"}]},"media":{"uk":"media/ldoce/hwd/bre/8/stolen0205.mp3","us":"media/ldoce/hwd/ame/b/ld44stolen.mp3"},"examples":[{"en":"stolen cars","cn":"被盗的汽车"}],"collins":{"senses":[{"pos":"","cn":"","en":"Stolen is the past participle of steal."}]}},"stalked":{"oxford":{"phon":"stɔːk","pos":"noun","senses":[{"en":"a thin stem that supports a leaf, flower or fruit and joins it to another part of the plant or tree; the main stem of a plant （","cn":"叶）柄；（花）梗；（果实的）柄；（植物的）茎，秆"},{"en":"a long thin structure that supports sth, especially an organ in some animals, and joins it on to another part","cn":"柄；（动物的）肉柄，肉茎"}]}},"students":{"oxford":{"phon":"ˈstjuːdnt","pos":"noun","senses":[{"en":"a person who is studying at a university or college","cn":"大学生；研究生"},{"en":"a person who is studying at a school, especially a secondary school","cn":"学生；（尤指）中学生"}]}},"stretching":{"oxford":{"phon":"stretʃ","pos":"verb","senses":[{"en":"to make sth longer, wider or looser, for example by pulling it; to become longer, etc. in this way","cn":"拉长；拽宽；撑大；抻松"},{"en":"to become bigger or longer when you pull it and return to its original shape when you stop","cn":"有弹性（或弹力）"}]}},"stopping":{"oxford":{"phon":"stɒp","pos":"verb","senses":[{"en":"to no longer move; to make sb/sth no longer move （","cn":"使）停止，停下"},{"en":"to no longer continue to do sth; to make sb/sth no longer do sth （","cn":"使）中断，停止"}]}},"stabs":{"oxford":{"phon":"stæb","pos":"verb","senses":[{"en":"to push a sharp, pointed object, especially a knife, into sb, killing or injuring them （","cn":"用刀等锐器）刺，戳，捅"},{"en":"to make a short, aggressive or violent movement with a finger or pointed object （","cn":"用手指或尖物）戳，捅，刺"}]}},"stored":{"oxford":{"phon":"stɔː(r)","pos":"noun","senses":[{"en":"a large shop that sells many different types of goods （","cn":"大型）百货商店"},{"en":"( NAmE ) a shop, large or small","cn":"商店；店铺"}]}},"standardized":{"oxford":{"phon":"ˈstændədaɪz","pos":"verb","senses":[{"en":"to make objects or activities of the same type have the same features or qualities; to make sth standard","cn":"使标准化；使符合标准（或规格）"}]}},"strings":{"oxford":{"phon":"strɪŋ","pos":"noun","senses":[{"en":"material made of several threads twisted together, used for tying things together; a piece of string used to fasten or pull sth or keep sth in place","cn":"细绳；线；带子"},{"en":"a set or series of things that are joined together, for example on a string","cn":"一串"}]}},"stems":{"oxford":{"phon":"stem","pos":"noun","senses":[{"en":"the main long thin part of a plant above the ground from which the leaves or flowers grow; a smaller part that grows from this and supports flowers or leaves （","cn":"花草的）茎；（花或叶的）梗，柄"},{"en":"the long thin part of a wine glass between the bowl and the base （","cn":"高脚酒杯的）脚"}]}},"studying":{"oxford":{"phon":"ˈstʌdi","pos":"noun","senses":[{"en":"the activity of learning or gaining knowledge, either from books or by examining things in the world","cn":"学习；研究"},{"en":"( formal ) a particular person's learning activities, for example at a college or university","cn":"功课；课业；学业"}]}},"stables":{"oxford":{"phon":"ˈsteɪbl","pos":"adj.","senses":[{"en":"firmly fixed; not likely to move, change or fail","cn":"稳定的；稳固的；牢固的"},{"en":"calm and reasonable; not easily upset","cn":"稳重的；沉稳的；持重的"}]}},"steaks":{"oxford":{"phon":"steɪk","pos":"noun","senses":[{"en":"a thick slice of good quality beef","cn":"牛排"},{"en":"a thick slice of any type of meat","cn":"肉排；肉块"}]}},"strokes":{"oxford":{"phon":"strəʊk","pos":"noun","senses":[{"en":"an act of hitting a ball, for example with a bat or racket","cn":"击球（动作）"},{"en":"a single movement of the arm when hitting sb/sth （","cn":"打、击等的）一下，一击"}]}},"started":{"oxford":{"phon":"stɑːt","pos":"verb","senses":[{"en":"to begin doing or using sth","cn":"开始，着手，动手（做或使用）"},{"en":"to start happening; to make sth start happening （","cn":"使）发生，开始进行"}]}},"stresses":{"oxford":{"phon":"stres","pos":"noun","senses":[{"en":"pressure or worry caused by the problems in sb's life","cn":"精神压力；心理负担；紧张"},{"en":"pressure put on sth that can damage it or make it lose its shape","cn":"压力；应力"}]}},"straggling":{"oxford":{"phon":"ˈstræɡl","pos":"verb","senses":[{"en":"to grow, spread or move in an untidy way in different directions","cn":"蔓生；杂乱地蔓延；散布"},{"en":"to move slowly behind a group of people that you are with so that you become separated from them","cn":"掉队；落在后面"}]}},"stares":{"oxford":{"phon":"steə(r)","pos":"verb","senses":[{"en":"to look at sb/sth for a long time","cn":"盯着看；凝视；注视"},{"en":"to be obvious or easy to see","cn":"明摆着；显而易见"}]}},"statistics":{"oxford":{"phon":"stəˈtɪstɪk","pos":"noun","senses":[{"en":"a collection of information shown in numbers","cn":"统计数字；统计资料"},{"en":"the science of collecting and analysing statistics","cn":"统计学"}]}},"staffers":{"oxford":{"phon":"ˈstɑːfə(r)","pos":"noun","senses":[{"en":"a member of staff in a big organization","cn":"大机构的职员"}]}},"studies":{"oxford":{"phon":"ˈstʌdi","pos":"noun","senses":[{"en":"the activity of learning or gaining knowledge, either from books or by examining things in the world","cn":"学习；研究"},{"en":"( formal ) a particular person's learning activities, for example at a college or university","cn":"功课；课业；学业"}]}},"stretches":{"oxford":{"phon":"stretʃ","pos":"verb","senses":[{"en":"to make sth longer, wider or looser, for example by pulling it; to become longer, etc. in this way","cn":"拉长；拽宽；撑大；抻松"},{"en":"to become bigger or longer when you pull it and return to its original shape when you stop","cn":"有弹性（或弹力）"}]}},"stationers":{"oxford":{"phon":"ˈsteɪʃənə(r)","pos":"noun","senses":[{"en":"a person who owns or manages a shop selling stationery","cn":"文具商"},{"en":"a shop that sells stationery","cn":"文具店"}]}},"steps":{"oxford":{"phon":"step","pos":"noun","senses":[{"en":"the act of lifting your foot and putting it down in order to walk or move somewhere; the sound this makes","cn":"迈步；脚步声"},{"en":"the way that sb walks","cn":"步伐；步态"}]}},"strolled":{"oxford":{"phon":"strəʊl","pos":"verb","senses":[{"en":"to walk somewhere in a slow relaxed way","cn":"散步；遛达；闲逛"},{"en":"a slow relaxed walk","cn":"散步；遛达；闲逛"}]}},"sticks":{"oxford":{"phon":"stɪk","pos":"verb","senses":[{"en":"to push sth, usually a sharp object, into sth; to be pushed into sth","cn":"将 … 刺入（或插入）；刺；戳；插入"},{"en":"to fix sth to sth else, usually with a sticky substance; to become fixed to sth in this way","cn":"粘贴；粘住"}]}},"stacks":{"oxford":{"phon":"stæk","pos":"noun","senses":[{"en":"a pile of sth, usually neatly arranged （","cn":"通常指码放整齐的）一叠，一摞，一堆"},{"en":"( informal ) ( especially BrE ) a large number or amount of sth; a lot of sth","cn":"大量；许多；一大堆"}]}},"struggling":{"oxford":{"phon":"ˈstrʌɡl","pos":"verb","senses":[{"en":"to try very hard to do sth when it is difficult or when there are a lot of problems","cn":"奋斗；努力；争取"},{"en":"to move somewhere or do sth with difficulty","cn":"艰难地行进；吃力地进行"}]}},"strangers":{"oxford":{"phon":"ˈstreɪndʒə(r)","pos":"noun","senses":[{"en":"a person that you do not know","cn":"陌生人"},{"en":"a person who is in a place that they have not been in before","cn":"外地人；新来者"}]}},"stated":{"oxford":{"phon":"steɪt","pos":"noun","senses":[{"en":"the mental, emotional or physical condition that a person or thing is in","cn":"状态；状况；情况"},{"en":"a country considered as an organized political community controlled by one government","cn":"国家"}]}},"structures":{"oxford":{"phon":"ˈstrʌktʃə(r)","pos":"noun","senses":[{"en":"the way in which the parts of sth are connected together, arranged or organized; a particular arrangement of parts","cn":"结构；构造"},{"en":"a thing that is made of several parts, especially a building","cn":"结构体；（尤指）建筑物"}]}},"stalls":{"oxford":{"phon":"stɔːl","pos":"noun","senses":[{"en":"a table or small shop with an open front that people sell things from, especially at a market","cn":"货摊，摊位，售货亭（尤指集市上的）"},{"en":"a section inside a farm building that is large enough for one animal to be kept in","cn":"牲畜棚；马厩；牛棚"}]}},"stands":{"oxford":{"phon":"stænd","pos":"verb","senses":[{"en":"to be on your feet; to be in a vertical position","cn":"站立；立；直立"},{"en":"to get up onto your feet from another position","cn":"站起来；起立"}]}},"steamed":{"oxford":{"phon":"stiːm","pos":"noun","senses":[{"en":"the hot gas that water changes into when it boils","cn":"水蒸气；蒸汽"},{"en":"the power that is produced from steam under pressure, used to operate engines, machines, etc.","cn":"蒸汽动力"}]}},"standards":{"oxford":{"phon":"ˈstændəd","pos":"noun","senses":[{"en":"a level of quality, especially one that people think is acceptable （","cn":"品质的）标准，水平，规格，规范"},{"en":"a level of quality that is normal or acceptable for a particular person or in a particular situation","cn":"正常的水平；应达到的标准"}]}},"st":{"oxford":{"phon":"","pos":"abbreviation","senses":[{"en":"stone (a British measurement of weight)","cn":"英石（英国重量单位）","ex":{"en":"9st 2lb","cn":"9 英石 2 磅"}},{"en":"(used in written addresses) Street","cn":"（书写地址时用）街，路","lab":"British English","ex":{"en":"Fleet St","cn":"弗利特街（或译舰队街）"}},{"en":"State","cn":"州","lab":"North American English"},{"en":"saint","cn":"（基督教）圣人，圣徒","lab":"especially in North American English"}]},"media":{"uk":"media/ldoce/hwd/bre/2/lpd_st__st_.mp3","us":"media/ldoce/hwd/ame/2/lpd_st__st_.mp3"},"examples":[{"en":"Fleet St","cn":"弗利特街（或译舰队街）"},{"en":"Wall St.","cn":"华尔街"}],"collins":{"senses":[{"pos":"","cn":"","en":"St is a written abbreviation for (书面缩略=) Street .","ex":{"en":"...116 Princess St.","cn":"公主大街 116 号"}},{"pos":"","cn":"","en":"St is a written abbreviation for (书面缩略=) Saint .","ex":{"en":"...St Thomas.","cn":"圣托马斯"}}]}},"strides":{"oxford":{"phon":"straɪd","pos":"verb","senses":[{"en":"to walk with long steps in a particular direction","cn":"大步走；阔步行走"},{"en":"one long step; the distance covered by a step","cn":"大步；一步（的距离）"}]}},"stumbling":{"oxford":{"phon":"ˈstʌmbl","pos":"verb","senses":[{"en":"to hit your foot against sth while you are walking or running and almost fall","cn":"绊脚"},{"en":"to walk or move in an unsteady way","cn":"跌跌撞撞地走；蹒跚而行"}]}},"strolling":{"oxford":{"phon":"strəʊl","pos":"verb","senses":[{"en":"to walk somewhere in a slow relaxed way","cn":"散步；遛达；闲逛"},{"en":"a slow relaxed walk","cn":"散步；遛达；闲逛"}]},"media":{"uk":"media/ldoce/hwd/bre/6/strolling0205.mp3","us":"media/ldoce/hwd/ame/8/strolling.mp3"}},"stayed":{"oxford":{"phon":"steɪ","pos":"verb","senses":[{"en":"to continue to be in a particular place for a period of time without moving away","cn":"停留；待"},{"en":"In spoken English stay can be used with and plus another verb, instead of with to and the infinitive, to show purpose or to tell somebody what to do.","cn":"英语口语中，stay 后面可接 and 加另一个动词，而不用 to 加不定式，以表示目的或要某人做某事"}]}},"stewards":{"oxford":{"phon":"ˈstjuːəd","pos":"noun","senses":[{"en":"a man whose job is to take care of passengers on a ship, an aircraft or a train and who brings them meals, etc. （","cn":"轮船、飞机或火车上的）乘务员，服务员"},{"en":"a person who helps to organize a large public event, for example a race, public meeting, etc. （","cn":"比赛、集会等大型公众活动的）统筹人"}]}},"stopped":{"oxford":{"phon":"stɒp","pos":"verb","senses":[{"en":"to no longer move; to make sb/sth no longer move （","cn":"使）停止，停下"},{"en":"to no longer continue to do sth; to make sb/sth no longer do sth （","cn":"使）中断，停止"}]}},"stops":{"oxford":{"phon":"stɒp","pos":"verb","senses":[{"en":"to no longer move; to make sb/sth no longer move （","cn":"使）停止，停下"},{"en":"to no longer continue to do sth; to make sb/sth no longer do sth （","cn":"使）中断，停止"}]}},"steppes":{"oxford":{"phon":"step","pos":"noun","senses":[{"en":"a large area of land with grass but few trees, especially in SE Europe and Siberia （","cn":"尤指东南欧及西伯利亚树少的）大草原，干草原"}]}},"staying":{"oxford":{"phon":"steɪ","pos":"verb","senses":[{"en":"to continue to be in a particular place for a period of time without moving away","cn":"停留；待"},{"en":"In spoken English stay can be used with and plus another verb, instead of with to and the infinitive, to show purpose or to tell somebody what to do.","cn":"英语口语中，stay 后面可接 and 加另一个动词，而不用 to 加不定式，以表示目的或要某人做某事"}]}},"staged":{"oxford":{"phon":"steɪdʒ","pos":"noun","senses":[{"en":"a period or state that sth/sb passes through while developing or making progress （","cn":"发展或进展的）时期，阶段，状态"},{"en":"a separate part that a process, etc. is divided into","cn":"段；步；步骤"}]}},"stared":{"oxford":{"phon":"steə(r)","pos":"verb","senses":[{"en":"to look at sb/sth for a long time","cn":"盯着看；凝视；注视"},{"en":"to be obvious or easy to see","cn":"明摆着；显而易见"}]}},"starts":{"oxford":{"phon":"stɑːt","pos":"verb","senses":[{"en":"to begin doing or using sth","cn":"开始，着手，动手（做或使用）"},{"en":"to start happening; to make sth start happening （","cn":"使）发生，开始进行"}]}},"stones":{"oxford":{"phon":"stəʊn","pos":"noun","senses":[{"en":"( often used before nouns or in compounds","cn":"常用于名词前或构成复合词 ) a hard solid mineral substance that is found in the ground, often used for building 石头；石料；岩石"},{"en":"( especially BrE ) a small piece of rock of any shape","cn":"石块；石子"}]}},"structured":{"oxford":{"phon":"ˈstrʌktʃə(r)","pos":"noun","senses":[{"en":"the way in which the parts of sth are connected together, arranged or organized; a particular arrangement of parts","cn":"结构；构造"},{"en":"a thing that is made of several parts, especially a building","cn":"结构体；（尤指）建筑物"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41structured.mp3","us":"media/ldoce/hwd/ame/4/laadstructured.mp3"},"examples":[{"en":"The interviews were highly structured .","cn":"采访安排得很有条理。"},{"en":"a structured approach to teaching","cn":"周密的教学方法"}]},"stoke":{"collins":{"senses":[{"pos":"VERB 动词","cn":"给…添煤(或柴火)","en":"If you stoke a fire, you add coal or wood to it to keep it burning.","ex":{"en":"She was stoking the stove with sticks of maple.","cn":"她正在往炉子里添枫树枝。"}},{"pos":"VERB 动词","cn":"煽起;鼓动;激起","en":"If you stoke something such as a feeling, you cause it to be felt more strongly.","ex":{"en":"These demands are helping to stoke fears of civil war.","cn":"这些要求助长了人们对内战的恐惧。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to add more coal or wood to a fire","cn":"给…添加〔煤﹑柴火等燃料〕"},{"en":"to cause something to increase","cn":"加剧﹐激起"},{"en":"to add more coal or wood to a fire","cn":"给…添加〔煤﹑柴火等燃料〕"}]},"vocab":{"pos":"v","senses":[{"en":"To stoke is to poke a fire and fuel it so that it burns higher. It can also mean \"incite\"––a principal's impassive silence in the face of requests for more tater tots might stoke the flames of student anger."}]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdestoke.mp3","us":"media/ldoce/hwd/ame/c/stoke.mp3"},"examples":[{"en":"They were accused of stoking the crisis.","cn":"他们被指控对这次危机起了推波助澜的作用。"},{"en":"Stoke up for the day on a good breakfast.","cn":"早饭要吃得饱饱的，整整一天呢。"}],"oxford":{"phon":"stəʊk","pos":"verb","senses":[{"en":"to add fuel to a fire, etc.","cn":"给…添加（燃料）","ex":{"en":"to stoke up a fire with more coal","cn":"往火里再添一些煤"}},{"en":"to make people feel something more strongly","cn":"煽动；激起","ex":{"en":"to stoke up envy","cn":"激起妒忌"}},{"en":"to make something increase or develop more quickly","cn":"促使…的增加；刺激…的发展；加剧","ex":{"en":"They were accused of stoking the crisis.","cn":"他们被指控对这次危机起了推波助澜的作用。"}}]}},"steed":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骏马","en":"A steed is a large strong horse used for riding."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong fast horse","cn":"骏马"}]},"media":{"uk":"media/ldoce/hwd/bre/9/steed0205.mp3","us":"media/ldoce/hwd/ame/1/steed.mp3"},"oxford":{"phon":"stiːd","pos":"noun","senses":[{"en":"a horse to ride on","cn":"坐骑"}]}},"sternum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胸骨","en":"Your sternum is the long flat bone which goes from your throat to the bottom of your ribs and to which your ribs are attached."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a breastbone","cn":"胸骨"}]},"vocab":{"pos":"n","senses":[{"en":"Your sternum is your breastbone, the flat plate at the top of your rib cage. Mammals and birds — and even arachnids, or spiders — have a sternum ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41sternum.mp3","us":"media/ldoce/hwd/ame/0/sternum.mp3"},"oxford":{"phon":"ˈstɜːnəm","pos":"noun","senses":[{"en":"the breastbone","cn":"胸骨"}]}},"stud":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(固定在物体表面用于装饰的)嵌钉，饰钉","en":"A studs are small pieces of metal which are attached to a surface for decoration.","ex":{"en":"You see studs on lots of London front doors.","cn":"在伦敦，你能看到许多人家的大门上都装有饰钉。"}},{"pos":"N-COUNT 可数名词","cn":"耳钉","en":"A stud is an earring consisting of a small shape attached to a bar which goes through a hole in your ear.","ex":{"en":"...plain gold studs.","cn":"素金耳钉"}},{"pos":"N-COUNT 可数名词","cn":"(尤指运动靴的)防滑钉，鞋钉","en":"Studs are small round objects attached to the bottom of boots, especially sports boots, so that the person wearing them does not slip."},{"pos":"N-UNCOUNT 不可数名词","cn":"种马;种畜","en":"Horses or other animals that are kept for stud are kept to be used for breeding.","ex":{"en":"He was voted horse of the year and then was retired to stud.","cn":"这匹马被评为年度冠军后就退役成了种马。"}},{"pos":"N-COUNT 可数名词","cn":"性欲旺盛的男子;风流男子","en":"If you refer to a man as a stud, you mean that he is thought to be very active sexually and good at satisfying his partner's sexual desires."},{"pos":"N-COUNT 可数名词","cn":"同 stud farm","en":"A stud is the same as a stud farm ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to have sex with many different people over a period of time, usually without having a serious relationship with any of them","cn":""},{"en":"when someone has sex with someone without intending to have a serious relationship with them, especially when they do this many times","cn":""},{"en":"someone who is promiscuous has sex with many different people, usually without having a serious relationship with any of them","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"A stud is a metal piece that sticks out, usually for decoration. You might have studs spelling out \"Mom\" on your leather jacket. Straight, simple earrings — a single pearl on a straight post, for instance — are also called studs ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdestud.mp3","us":"media/ldoce/hwd/ame/2/stud1.mp3","img":["media/thumb/stud.jpg"]},"examples":[{"en":"The horse was retired from racing and put out to stud (= kept for breeding).","cn":"那匹赛马被淘汰下来，留作种马。"},{"en":"a leather jacket with studs on the back","cn":"后背有饰钉的皮夹克"}],"oxford":{"phon":"stʌd","pos":"noun","senses":[{"en":"a small piece of jewellery with a part that is pushed through a hole in your ear, nose, etc.","cn":"钉状首饰；耳钉；鼻钉","g":"[countable]","ex":{"en":"diamond studs","cn":"钻石耳钉"}},{"en":"a small, round piece of metal that is attached to the surface of something, especially for decoration","cn":"饰钉；（尤指装饰用的）嵌钉","g":"[countable]","ex":{"en":"a leather jacket with studs on the back","cn":"后背有饰钉的皮夹克"}},{"en":"one of several small metal or plastic objects that are fixed to the bottom part of a football boot or sports shoe","cn":"（足球鞋或跑鞋上的）鞋钉","g":"[countable, usually plural]","lab":"British English"},{"en":"a small metal object used in the past for fastening a collar onto a shirt","cn":"领扣","g":"[countable]"},{"en":"an animal, especially a horse, that is kept for breeding (= producing young); a place where animals, especially horses, are kept for breeding","cn":"种公畜；种马；种畜场；种马场","g":"[countable, uncountable]","ex":{"en":"a stud farm","cn":"种马场"}},{"en":"a man who has many sexual partners and who is thought to be sexually attractive","cn":"乱搞关系的男人；风流男子","g":"[countable]","lab":"informal"},{"en":"to be in many different parts of a place or area","cn":"螺柱：位于某个地方或区域的许多不同部分","ex":{"en":"Stars studded the sky.","cn":"繁星满天。"},"pos":"verb"}]}},"stealth":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"暗中行动;偷偷摸摸;鬼鬼祟祟","en":"If you use stealth when you do something, you do it quietly and carefully so that no one will notice what you are doing.","ex":{"en":"He claimed Tony Blair is trying to get us into the euro by stealth","cn":"他声称托尼·布莱尔正试图神不知鬼不觉地让我们加入欧元体系。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when you do something very quietly, slowly, or secretly, so that no one notices you","cn":"悄悄的行动﹐秘密行动"},{"en":"a system of making military aircraft that cannot be discovered by radar instruments 〔","cn":"战斗机的〕隐形技术"}]},"vocab":{"pos":"n","senses":[{"en":"Stealth means to do something so quietly and carefully that no one notices, like the stealth of a kitten sneaking up on a mouse."}]},"media":{"uk":"media/ldoce/hwd/bre/2/stealth0205.mp3","us":"media/ldoce/hwd/ame/5/stealth.mp3"},"examples":[{"en":"The government was accused of trying to introduce the tax by stealth.","cn":"有人指责政府想不事声张地开征这种税。"},{"en":"Lions rely on stealth when hunting.","cn":"狮子捕食全凭偷袭。"}],"oxford":{"phon":"stelθ","pos":"noun","senses":[{"en":"the fact of doing something in a quiet or secret way","cn":"偷偷摸摸；不声张的活动；秘密行动","ex":{"en":"The government was accused of trying to introduce the tax by stealth.","cn":"有人指责政府想不事声张地开征这种税。"}},{"en":"designed in a way that makes it difficult to be discovered by radar","cn":"隐形的","ex":{"en":"a stealth bomber","cn":"隐形轰炸机"},"pos":"adjective"}]}},"stewardess":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(船舶、飞机或火车上的)女服务员，女乘务员","en":"A stewardess is a woman who works on a ship, plane, or train, looking after passengers and serving meals to them."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who operates the controls of a plane","cn":""},{"en":"a pilot who shares the control of a plane with the main pilot","cn":""},{"en":"the pilot who is in charge of an aircraft","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/stewardess0205.mp3","us":"media/ldoce/hwd/ame/4/laadstewardess.mp3"},"oxford":{"phon":"ˌstjuːəˈdes","pos":"noun","senses":[{"en":"a female flight attendant","cn":"（飞机上的）女乘务员；空中小姐"},{"en":"a female steward on a ship or train","cn":"（轮船或火车上的）女乘务员，女服务员"}]}},"steeple":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(教堂的)尖塔","en":"A steeple is a tall pointed structure on top of the tower of a church."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall pointed tower on the roof of a church 〔","cn":"教堂的〕尖塔"}]},"vocab":{"pos":"n","senses":[{"en":"A steeple is a very tall tower that gets smaller and smaller as it goes up. Many churches have steeples . Steeples are really tall so people can find the church from anywhere in town."}]},"media":{"uk":"media/ldoce/hwd/bre/a/steeple0205.mp3","us":"media/ldoce/hwd/ame/2/steeple.mp3"},"oxford":{"phon":"ˈstiːpl","pos":"noun","senses":[{"en":"a tall pointed tower on the roof of a church, often with a spire on it","cn":"（教堂的）尖塔"}]}},"starving":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"饿极了的;饿得慌的","en":"If you say that you are starving, you mean that you are very hungry.","ex":{"en":"Apart from anything else I was starving.","cn":"别的不说，我饿坏了。"}}]}},"stutter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"口吃;结巴","en":"If someone has a stutter, they find it difficult to say the first sound of a word, and so they often hesitate or repeat it two or three times.","ex":{"en":"He spoke with a pronounced stutter.","cn":"他说话明显结巴。"}},{"pos":"VERB 动词","cn":"口吃;说话结结巴巴","en":"If someone stutters, they have difficulty speaking because they find it hard to say the first sound of a word.","ex":{"en":"I was trembling so hard, I thought I would stutter when I spoke.","cn":"我抖得厉害，感觉说话舌头会打结。"}},{"pos":"VERB 动词","cn":"缓慢地颠簸前进;曲折缓慢地进行","en":"If something stutters along, it progresses slowly and unevenly.","ex":{"en":"The old truck stuttered along the winding road","cn":"这辆旧卡车在蜿蜒的公路上缓慢地颠簸前行。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you've ever heard a young child stammer and trip over his words, you know what it means to stutter ."}]},"collocations":{"phrases":["ADJ. bad | slight | occasional","VERB + STUTTER have, speak with He spoke with a stutter, which got worse when he was angry."]},"media":{"uk":"media/ldoce/hwd/bre/b/stutter_n0205.mp3","us":"media/ldoce/hwd/ame/d/stutter1.mp3"},"examples":[{"en":"I managed to stutter a reply.","cn":"我结结巴巴，好不容易应了一句。"},{"en":"The car stuttered along in first gear.","cn":"汽车挂了一挡，突突地缓缓前进。"}],"oxford":{"phon":"ˈstʌtə(r)","pos":"verb","senses":[{"en":"to have difficulty speaking because you cannot stop yourself from repeating the first sound of some words several times","cn":"口吃；结结巴巴地说","g":"[transitive, intransitive]","ex":{"en":"‘W-w-what?’ he stuttered.","cn":"“什…什…什么？”他结结巴巴地说。"}},{"en":"to move or start with difficulty, making short sharp noises or movements","cn":"突突地吃力行驶（或艰难启动、艰难运转）","g":"[intransitive]","ex":{"en":"The car stuttered along in first gear.","cn":"汽车挂了一挡，突突地缓缓前进。"}},{"en":"a speech problem in which a person finds it difficult to say the first sound of a word and repeats it several times","cn":"口吃；结巴","ex":{"en":"He had a terrible stutter.","cn":"他患严重口吃。"},"pos":"noun"}]}},"strew":{"collins":{"senses":[{"pos":"VERB 动词","cn":"撒;散播;在…上布满(或撒满)","en":"To strew things somewhere, or to strew a place with things, means to scatter them there.","ex":{"en":"The racoons knock over the rubbish bins in search of food, and strew the contents all over the ground","cn":"浣熊弄翻垃圾箱找吃的，把垃圾弄得满地都是。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"things that are scattered are spread over a large area in an irregular or untidy way","cn":""},{"en":"things that are spread out are spread over a large area with a lot of space between them","cn":""},{"en":"spread across a wide area - use this about towns, buildings, or groups of buildings that you think take up too much space and are ugly or unpleasant","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you strew something, you scatter it all over the place. At a wedding, for example, the flower child's job is to strew the path with petals."}]},"media":{"uk":"media/ldoce/hwd/bre/7/strew0205.mp3","us":"media/ldoce/hwd/ame/6/strew.mp3"},"examples":[{"en":"( figurative ) The way ahead is strewn with difficulties.","cn":"前面的道路布满艰难险阻。"},{"en":"Clothes were strewn across the floor.","cn":"衣服扔得满地都是。"}],"oxford":{"phon":"struː","pos":"verb","senses":[{"en":"to cover a surface with things","cn":"把…布满（或散布在）；在…上布满（或散播）","g":"[usually passive]","lab":"figurative","ex":{"en":"Clothes were strewn across the floor.","cn":"衣服扔得满地都是。"}},{"en":"to be spread or lying over a surface","cn":"布满；撒满；散播在…上","ex":{"en":"Leaves strewed the path.","cn":"树叶落满小径。"}}]}},"statesmanlike":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有政治家风范的;有政治家才干的","en":"If you describe someone, especially a political leader, as statesmanlike, you approve of them because they give the impression of being very able and experienced.","ex":{"en":"He was widely respected as a wise and statesmanlike governor","cn":"他作为一位睿智、具备政治家才干的州长而广受尊崇。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing the qualities of a statesman – used to show approval","cn":"有政治家风范的﹐像政治家的〔含褒义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41statesmanlike.mp3","us":"media/ldoce/hwd/ame/6/ld41statesmanlike.mp3"},"examples":[{"en":"He was commended for his statesmanlike handling of the crisis.","cn":"他处理那场危机时，因表现出政治家的才干而受到称赞。"},{"en":"his statesmanlike handling of the crisis","cn":"他处理这场危机时表现出的政治家才干"}],"oxford":{"phon":"ˈsteɪtsmənlaɪk","pos":"adjective","senses":[{"en":"having or showing the qualities and abilities of a statesman","cn":"具有政治家风范的；像政治家的","ex":{"en":"He was commended for his statesmanlike handling of the crisis.","cn":"他处理那场危机时，因表现出政治家的才干而受到称赞。"}}]}},"stricture":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指摘;非难;反对","en":"You can use strictures to refer to severe criticism or disapproval of something.","ex":{"en":"...Mencken's strictures on the 1920s, with its self-righteous prohibition on alcohol and unconventional ideas","cn":"门肯对19世纪20年代自以为是的禁酒令和对非传统思想的禁锢的指摘"}},{"pos":"N-COUNT 可数名词","cn":"限制;约束;束缚","en":"You can refer to things that limit what you can do as strictures of a particular kind.","ex":{"en":"Your goals are hindered by financial strictures.","cn":"你的目标受制于经济困难。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a rule that strictly limits what you can do","cn":"约束﹔限制﹔束缚"},{"en":"a severe criticism","cn":"严厉批评"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"One meaning of stricture is a nasty criticism, while the other is a sharp contraction of a tube or canal in the body. Either meaning can mean great pain to the person experiencing the stricture ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stricture.mp3","us":"media/ldoce/hwd/ame/d/stricture.mp3"},"examples":[{"en":"strictures against civil servants expressing political opinions","cn":"对于公务员发表政治见解的禁令"},{"en":"religious strictures on marriage","cn":"对婚姻的宗教约束"}],"oxford":{"phon":"ˈstrɪktʃə(r)","pos":"noun","senses":[{"en":"a severe criticism, especially of somebody’s behaviour","cn":"指摘；非难","g":"[usually plural]","ex":{"en":"She merely ignored any strictures on the way she dressed.","cn":"她只是忽略了对她着装方式的任何限制。"}},{"en":"a rule or situation that limits your behaviour","cn":"限制；约束；束缚","ex":{"en":"strictures against civil servants expressing political opinions","cn":"对于公务员发表政治见解的禁令"}}]}},"stun":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使震惊;使目瞪口呆;使惊愕","en":"If you are stunned by something, you are extremely shocked or surprised by it and are therefore unable to speak or do anything.","ex":{"en":"Many cinema-goers were stunned by the film's violent and tragic end.","cn":"许多来看电影的人都被这部影片暴力而悲惨的结局所震惊。"}},{"pos":"VERB 动词","cn":"使昏迷;使眩晕;打昏","en":"If something such as a blow on the head stuns you, it makes you unconscious or confused and unsteady.","ex":{"en":"Sam stood his ground and got a blow that stunned him.","cn":"萨姆站在原地，被一下打昏了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel very surprised and upset","cn":""},{"en":"if something unpleasant comes as a shock , it makes you feel surprised and upset because you were not expecting it at all","cn":""},{"en":"if something stuns you, especially a piece of news, it makes you feel so surprised and upset that you cannot speak or do anything immediately afterwards","cn":""}]},"collocations":{"phrases":["ADV. absolutely | almost | briefly, momentarily","PREP. into The assault was so unexpected that he was briefly stunned into submission.","PHRASES stun sb into silence The guests were stunned into silence."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdestun.mp3","us":"media/ldoce/hwd/ame/c/stun.mp3"},"examples":[{"en":"There was a stunned silence when I told them the news.","cn":"我把消息讲了后，他们惊愕得哑然一片。"},{"en":"They were stunned by the view from the summit.","cn":"在峰顶看到的景色使他们惊叹不已。"}],"oxford":{"phon":"stʌn","pos":"verb","senses":[{"en":"to make a person or an animal unconscious for a short time, especially by hitting them on the head","cn":"使昏迷；（尤指）打昏","ex":{"en":"The fall stunned me for a moment.","cn":"那一下摔得我昏迷了片刻。"}},{"en":"to surprise or shock somebody so much that they cannot think clearly or speak","cn":"使震惊（或惊愕、目瞪口呆）","ex":{"en":"Her words stunned me—I had no idea she felt that way.","cn":"她的话令我目瞪口呆，我没想到她会那么想。"}},{"en":"to impress somebody very much","cn":"给（某人）以深刻印象；使深深感动","ex":{"en":"They were stunned by the view from the summit.","cn":"在峰顶看到的景色使他们惊叹不已。"}}]}},"stereotypical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"典型的;带有成见的;已成定型的","en":"A stereotypical idea of a type of person or thing is a fixed general idea that a lot of people have about it, that may be false in many cases.","ex":{"en":"Dara challenges our stereotypical ideas about gender and femininity.","cn":"达拉对我们老一套的性别和女性特质观念提出了异议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is representative of the group that they belong to is typical of it, and shows what the others in the group are like","cn":""},{"en":"the archetypal person or thing is the most typical example of that kind of person or thing, and has all their most important qualities","cn":""},{"en":"a classic example of something is a very typical and very good example of it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Stereotypical describes an action or a characterization that is oversimplified, widely imitated, or handed down by tradition."}]},"media":{"uk":"media/ldoce/hwd/bre/3/stereotype_n0205.mp3","us":"media/ldoce/hwd/ame/4/stereotype1.mp3"},"examples":[{"en":"the stereotypical image of feminine behaviour","cn":"关于女性行为举止的模式化观念"}],"oxford":{"phon":"ˌsteriəˈtɪpɪkl","pos":"adjective","senses":[{"en":"based on a fixed idea or image that many people have of a particular type of person or thing, but which is often not true in reality","cn":"模式化观念（或形象）；老一套；刻板印象","ex":{"en":"the stereotypical image of feminine behaviour","cn":"关于女性行为举止的模式化观念"}}]}},"strap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"带子;皮带;布带","en":"A strap is a narrow piece of leather, cloth, or other material. Straps are used to carry things, fasten things together, or to hold a piece of clothing in place.","ex":{"en":"Nancy gripped the strap of her beach bag","cn":"南希抓住了自己沙滩包的带子。"}},{"pos":"VERB 动词","cn":"用带子系(或绑、捆、扎)","en":"If you strap something somewhere, you fasten it there with a strap.","ex":{"en":"Strapping the skis on the roof, we boarded the hovercraft in Dover","cn":"用带子把滑水板绑在船顶后，我们就在多佛登上了气垫船。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a narrow band of strong material that is used to fasten, hang, or hold onto something","cn":"带子"},{"en":"to fasten something or someone in place with one or more straps","cn":"用带子束住﹐捆绑"},{"en":"to tie bandage s firmly round a part of your body that has been hurt 〔","cn":"用绷带〕包扎〔伤口〕"}]},"collocations":{"phrases":["ADJ. broad, wide | narrow | tight | loose | adjustable, detachable The bag comes with detachable straps. | elastic, elasticated, padded | ca","VERB + STRAP buckle (up), do up, fasten | unbuckle, undo, unfasten | tighten | loosen | adjust | attach, clip on, fit He clipped on his safe","PREP. on a/the ~ His binoculars were on a strap round his neck. | ~ across, ~ around/round, etc. She had a wide leather strap around her wri"]},"media":{"img":["media/ldoce/img/watch.jpg"],"uk":"media/ldoce/hwd/bre/2/strap_n0205.mp3","us":"media/ldoce/hwd/ame/a/strap1.mp3"},"examples":[{"en":"Everything had to be strapped down to stop it from sliding around.","cn":"所有东西必须绑定，免得来回滑动。"},{"en":"I have to keep my leg strapped up for six weeks.","cn":"我的腿必须打六星期绷带。"}],"oxford":{"phon":"stræp","pos":"noun","senses":[{"en":"a narrow piece of leather, cloth or other material that is used to fasten something, keep something in place, carry something or hold onto something","cn":"带子","ex":{"en":"the shoulder straps of her dress","cn":"她连衣裙上的肩带"}},{"en":"to fasten somebody/something in place using a strap or straps","cn":"用带子系（或捆、扎、扣）好","ex":{"en":"He strapped the knife to his leg.","cn":"他把刀绑到腿上。"},"pos":"verb"},{"en":"to wrap long, narrow pieces of material around a wound or an injured part of the body","cn":"包扎；给…打绷带","ex":{"en":"I have to keep my leg strapped up for six weeks.","cn":"我的腿必须打六星期绷带。"},"pos":"verb"}]}},"stewardship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"照管财产的职责","en":"Stewardship is the responsibility of looking after property."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone’s stewardship of something is the way that they control or protect it","cn":"管理方式；看管[保护]工作"}]},"vocab":{"pos":"n","senses":[{"en":"Stewardship means the management or care of something, particularly the kind that works. If your company is making money, there’s probably been careful stewardship — or, a lot of luck."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41stewardship.mp3","us":"media/ldoce/hwd/ame/2/laadstewardship.mp3"},"examples":[{"en":"The organization certainly prospered under his stewardship.","cn":"不可否认，这个组织在他的管理下兴旺了起来。"},{"en":"Some critics have doubts about his stewardship of the nation.","cn":"一些批评者对他管理国家的方式提出质疑。"}],"oxford":{"phon":"ˈstjuːədʃɪp","pos":"noun","senses":[{"en":"the act of taking care of or managing something, for example property, an organization, money or valuable objects","cn":"管理；看管；组织工作","ex":{"en":"The organization certainly prospered under his stewardship.","cn":"不可否认，这个组织在他的管理下兴旺了起来。"}}]}},"standard-bearer":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an important leader in a moral argument or political group 〔","cn":"道德观念或政治团体的〕领导者，领袖，旗手"},{"en":"a soldier in past times who carried the standard (= flag ) at the front of an army 〔","cn":"旧时军队的〕旗手"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41standard-beare.mp3","us":"media/ldoce/hwd/ame/6/standard-bearer.mp3"},"oxford":{"phon":"ˈstændəd beərə(r)","pos":"noun","senses":[{"en":"a leader in a political group or campaign","cn":"旗手；领袖"}]}},"stranglehold":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"控制;约束;钳制","en":"To have a stranglehold on something means to have control over it and prevent it from being free or from developing.","ex":{"en":"These companies are determined to keep a stranglehold on the banana industry","cn":"这些公司决心要垄断香蕉业。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be the most powerful or important person or thing in a situation and therefore able to control it completely","cn":""},{"en":"to completely control an activity, situation etc and unfairly prevent other people or organizations from having any control over it at all","cn":""},{"en":"a situation in which one person or organization unfairly has complete control","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/stranglehold0205.mp3","us":"media/ldoce/hwd/ame/2/stranglehold.mp3"},"examples":[{"en":"The company now had a stranglehold on the market.","cn":"这家公司现在垄断了市场。"},{"en":"Just a few firms have a stranglehold on the market for this software.","cn":"只有少数几家公司完全控制着这种软件的市场。"}],"oxford":{"phon":"ˈstræŋɡlhəʊld","pos":"noun","senses":[{"en":"a strong hold around somebody’s neck that makes it difficult for them to breathe","cn":"掐脖子；卡脖子","ex":{"en":"Both arms were around his neck in a stranglehold.","cn":"双臂掐住了他的脖子。"}},{"en":"complete control over something that makes it impossible for it to grow or develop well","cn":"压制；束缚","ex":{"en":"The company now had a stranglehold on the market.","cn":"这家公司现在垄断了市场。"}}]}},"stabilizer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"稳定装置;稳定器;稳定剂","en":"A stabilizer is a device, mechanism, or chemical that makes something stable."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical that helps something such as a food to stay in the same state, for example to prevent it from separating into different liquids 〔","cn":"食物等的〕稳定剂"},{"en":"a piece of equipment that helps make something such as a plane or ship steady 〔","cn":"飞机﹑轮船等的〕稳定装置"},{"en":"one of a pair of small wheels that are fastened to the back wheel of a child’s bicycle to prevent it from falling over 〔","cn":"儿童自行车车后轮两侧的〕稳定轮"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41stabilizer.mp3","us":"media/ldoce/hwd/ame/f/stabilizer.mp3"},"oxford":{"phon":"ˈsteɪbəlaɪzə(r)","pos":"noun","senses":[{"en":"a device that keeps something steady, especially one that stops an aircraft or a ship from rolling to one side","cn":"稳定装置；（航空器的）安定面；（船舶的）减摇装置","g":"[countable]"},{"en":"small wheels that are fitted at each side of the back wheel on a child’s bicycle to stop it from falling over","cn":"（儿童自行车后轮两侧的）稳定轮","g":"[plural]","lab":"British English","ex":{"en":"She can ride her bike without stabilizers now.","cn":"她现在可以在没有稳定器的情况下骑自行车了。"}},{"en":"a chemical that is sometimes added to food or paint to stop the various substances in it from becoming separate","cn":"稳定剂","g":"[countable]","lab":"specialist"}]}},"stifling":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人窒息的;闷热的","en":"Stifling heat is so intense that it makes you feel uncomfortable. You can also use stifling to describe a place that is extremely hot.","ex":{"en":"The stifling heat of the little room was beginning to make me nauseous.","cn":"小房间里令人窒息的热气开始让我感到恶心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(情况)令人窒息的，令人感到压抑的","en":"If a situation is stifling, it makes you feel uncomfortable because you cannot do what you want.","ex":{"en":"Life at home with her parents and two sisters was stifling.","cn":"和父母及两个姐妹生活在一起让她感到很压抑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a room or building that is stuffy does not have enough fresh air, often because it is small or there are too many people in it","cn":""},{"en":"a room or building that is airless feels like it does not have enough air in it for you to breathe properly","cn":""},{"en":"very hot and uncomfortable, and without enough air for you to breathe properly","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"Something stifling makes you feel suffocated. If your mother insists on accompanying you on your first date, that will probably feel stifling ."}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdestifling.mp3","us":"media/ldoce/hwd/ame/a/laadstifling.mp3"},"examples":[{"en":"‘ It's stifling in here — can we open a window?’ “","cn":"这里闷得人难受，我们能不能开一扇窗户？”"},{"en":"At 25, she found family life stifling.","cn":"她 25 岁时感到家庭生活令人窒息。"}],"oxford":{"phon":"ˈstaɪflɪŋ","pos":"adjective","senses":[{"en":"making you feel unable to breathe, because it is too hot and/or there is no fresh air","cn":"让你觉得无法呼吸，因为太热和/或没有新鲜空气","ex":{"en":"a stifling room","cn":"闷得让人透不过气来的房间"}},{"en":"making you feel trapped and unable to do or say what you want","cn":"窒息：使您感到受困，无法做或说出自己想说的话","ex":{"en":"At 25, she found family life stifling.","cn":"她 25 岁时感到家庭生活令人窒息。"}}]}},"stash":{"collins":{"senses":[{"pos":"VERB 动词","cn":"存放，储藏，藏匿(贵重物品)","en":"If you stash something valuable in a secret place, you store it there to keep it safe.","ex":{"en":"We went for the bottle of whiskey that we had stashed behind the bookcase","cn":"我们去拿那瓶藏在书架后面的威士忌。"}},{"pos":"N-COUNT 可数名词","cn":"藏匿的物品","en":"A stash of something valuable is a secret store of it.","ex":{"en":"A large stash of drugs had been found aboard the yacht.","cn":"在游艇上找到了一大批藏匿的毒品。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something difficult to see or find, for example by putting it somewhere secret, or by covering it","cn":""},{"en":"to hide something carefully, especially by covering it","cn":""},{"en":"to hide money or something that you should not have","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you stash something, you stow it away to use it later. Your little brother might stash his Halloween candy under his bed, for example."}]},"media":{"uk":"media/ldoce/hwd/bre/0/stash_v0205.mp3","us":"media/ldoce/hwd/ame/6/l3stash.mp3"},"examples":[{"en":"She has a fortune stashed away in various bank accounts.","cn":"她有一大笔钱存在几个不同的银行账户下。"},{"en":"a stash of money","cn":"一笔存款"}],"oxford":{"phon":"stæʃ","pos":"verb","senses":[{"en":"to store something in a safe or secret place","cn":"存放；贮藏；隐藏","ex":{"en":"She has a fortune stashed away in various bank accounts.","cn":"她有一大笔钱存在几个不同的银行账户下。"}},{"en":"an amount of something that is kept secretly","cn":"一批贮藏物","ex":{"en":"a stash of money","cn":"一笔存款"},"pos":"noun"}]}},"stain":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"污迹;污渍","en":"A stain is a mark on something that is difficult to remove.","ex":{"en":"Remove stains by soaking in a mild solution of bleach.","cn":"用温和的漂白剂浸泡以去除污迹。"}},{"pos":"VERB 动词","cn":"在…上留下污迹;玷污;染污","en":"If a liquid stains something, the thing becomes coloured or marked by the liquid.","ex":{"en":"Some foods can stain the teeth, as of course can smoking.","cn":"某些食物会在牙齿上留下污渍，吸烟当然也会。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a large mark on something, which is difficult to remove","cn":""},{"en":"to damage the surface of something by making a mark on it","cn":""},{"en":"to make a mark or stain on something, often without realizing you have done this","cn":""}]},"collocations":{"phrases":["ADJ. stubborn | dark | coffee, grass, etc.","VERB + STAIN leave | get out, remove","STAIN + VERB spread The glass fell off the table and a dark stain spread over the carpet.","PREP. ~ on The coffee left a stain on his shirt."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdestain.mp3","us":"media/ldoce/hwd/ame/e/stain1.mp3"},"examples":[{"en":"Stain the specimen before looking at it under the microscope.","cn":"先把标本染色，再放到显微镜下观察。"},{"en":"The events had stained the city's reputation unfairly.","cn":"这些事件使该市背上了不应有的恶名。"}],"oxford":{"phon":"steɪn","pos":"verb","senses":[{"en":"to leave a mark that is difficult to remove on something; to be marked in this way","cn":"（被）玷污；留下污渍","g":"[transitive, intransitive]","ex":{"en":"I hope it doesn't stain the carpet.","cn":"希望它别把地毯弄脏。"}},{"en":"to change the colour of something using a coloured liquid","cn":"给…染色（或着色）","g":"[transitive]","ex":{"en":"to stain wood","cn":"给木料上色"}},{"en":"to damage the opinion that people have of something","cn":"玷污，败坏（名声）","g":"[transitive]","lab":"formal","ex":{"en":"The events had stained the city's reputation unfairly.","cn":"这些事件使该市背上了不应有的恶名。"}},{"en":"a dirty mark on something, that is difficult to remove","cn":"污点；污渍","g":"[countable]","ex":{"en":"a blood/a coffee/an ink stain","cn":"血渍；咖啡渍；墨痕"},"pos":"noun"},{"en":"a liquid used for changing the colour of wood or cloth","cn":"染色剂；着色剂","g":"[uncountable, countable]","ex":{"en":"wood stain","cn":"木材染色剂"},"pos":"noun"},{"en":"something that damages a person’s reputation, so that people think badly of them","cn":"（名声上的）污点","g":"[singular]","lab":"formal","ex":{"en":"He left the court without a stain on his character.","cn":"他经法庭一役，人格丝毫无损。"},"pos":"noun"}]}},"stole":{"collins":{"senses":[{"pos":"","cn":"","en":"Stole is the past tense of steal ."},{"pos":"N-COUNT 可数名词","cn":"女用长披肩;女用长围巾","en":"A stole is a long wide piece of cloth or fur that women wear round their shoulders.","ex":{"en":"...fur stoles.","cn":"毛皮长围巾"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the past tense of steal 1 steal","cn":"的过去式"},{"en":"a long straight piece of cloth or fur that a woman wears across her shoulders","cn":"女用披肩"}]},"media":{"uk":"media/ldoce/hwd/bre/b/stole0205.mp3","us":"media/ldoce/hwd/ame/2/ld44stole.mp3"},"oxford":{"phon":"stəʊl","pos":"noun","senses":[{"en":"a piece of clothing consisting of a wide band of cloth or fur, worn around the shoulders; a similar piece of clothing worn by a priest","cn":"女用披肩；（司祭佩戴的）圣带"}]}},"stingy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"吝啬的;小气的","en":"If you describe someone as stingy, you are criticizing them for being unwilling to spend money.","ex":{"en":"The West is stingy with aid","cn":"西方在援助上有点吝啬。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not generous, especially in small ways, when you could easily afford to be generous","cn":""},{"en":"someone who is mean does not like spending money or sharing what they have with other people","cn":""},{"en":"someone who is tight or tight-fisted is not at all generous and tries hard to avoid spending money","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are looking to describe someone with a Scrooge or Grinch-like tendency to pinch his pennies, then stingy can be your adjective of choice. Or, if you are looking to describe something you have too little of — like a 43-second coffee break — you can use stingy as well."}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdestingy.mp3","us":"media/ldoce/hwd/ame/d/stingy.mp3"},"examples":[{"en":"Don't be so stingy with the cream!","cn":"别那么舍不得放奶油！"},{"en":"You're stingy! (= not willing to spend money)","cn":"你真小气！"}],"oxford":{"phon":"ˈstɪndʒi","pos":"adjective","senses":[{"en":"not given or giving willingly; not generous, especially with money","cn":"小气的；吝啬的","ex":{"en":"You're stingy! (= not willing to spend money)","cn":"你真小气！"}}]}},"strangle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"勒死;扼死;绞死;掐死","en":"To strangle someone means to kill them by squeezing their throat tightly so that they cannot breathe.","ex":{"en":"He tried to strangle a border policeman and steal his gun","cn":"他企图勒死一名边防警察并偷走他的枪。"}},{"pos":"VERB 动词","cn":"抑制;制止;扼杀","en":"To strangle something means to prevent it from succeeding or developing.","ex":{"en":"The country's economic plight is strangling its scientific institutions","cn":"该国的经济困境阻碍了其科研机构的工作进展。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone die, especially deliberately or violently","cn":""},{"en":"to deliberately kill someone, especially after planning to do it","cn":""},{"en":"to murder an important or famous person, especially for political reasons","cn":""}]},"collocations":{"phrases":["ADV. almost, half, nearly","VERB + STRANGLE try to","PREP. with He was strangled with a scarf.","PHRASES be found strangled"]},"media":{"uk":"media/ldoce/hwd/bre/5/strangle0205.mp3","us":"media/ldoce/hwd/ame/6/strangle.mp3"},"examples":[{"en":"The current monetary policy is strangling the economy.","cn":"现行货币政策抑制了经济的发展。"},{"en":"He strangled her with her own scarf.","cn":"他用她自己的围巾把她勒死了。"}],"oxford":{"phon":"ˈstræŋɡl","pos":"verb","senses":[{"en":"to kill somebody by pressing their throat and neck hard, especially with your fingers","cn":"（尤指）扼死，掐死；勒死","ex":{"en":"to strangle somebody to death","cn":"把某人掐死"}},{"en":"to prevent something from growing or developing","cn":"抑制；压制；扼杀","ex":{"en":"The current monetary policy is strangling the economy.","cn":"现行货币政策抑制了经济的发展。"}}]}},"stymie":{"collins":{"senses":[{"pos":"VERB 动词","cn":"妨碍;阻挠;阻碍","en":"If you are stymied by something, you find it very difficult to take action or to continue what you are doing.","ex":{"en":"Companies have been stymied by the length of time it takes to reach an agreement","cn":"由于耗时过长，各公司一直未能达成协议。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to prevent someone from doing what they have planned or want to do","cn":"阻碍﹐妨碍﹐使不能实施"}]},"vocab":{"pos":"v n","senses":[{"en":"The verb stymie means to obstruct or hinder. Constantly texting with your friends will stymie your effort to finish your homework."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41stymie.mp3","us":"media/ldoce/hwd/ame/c/stymie.mp3"},"examples":[{"en":"Investigators have been stymied by uncooperative witnesses.","cn":"由于目击者不合作﹐调查人员的工作受阻。"}],"oxford":{"phon":"ˈstaɪmi","pos":"verb","senses":[{"en":"to prevent somebody from doing something that they have planned or want to do; to prevent something from happening","cn":"阻挠；阻碍；阻止；妨碍","ex":{"en":"He found himself stymied by an old opponent.","cn":"他发现自己被一个老对手挡住了。"}}]}},"standpipe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(在街头等公共场所供水的)竖管","en":"A standpipe is a vertical pipe that is connected to a water supply and stands in a street or other public place."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pipe that provides water in a public place in the street 〔","cn":"街头用于给公共场所供水的〕竖管"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41standpipe.mp3","us":"media/ldoce/hwd/ame/a/laadstandpipe.mp3"},"oxford":{"phon":"ˈstændpaɪp","pos":"noun","senses":[{"en":"a pipe that is connected to a public water supply and used to provide water outside a building","cn":"公用水管（用于在户外公共场所供水）"}]}},"stigma":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"耻辱;污名","en":"If something has a stigma attached to it, people think it is something to be ashamed of.","ex":{"en":"There is a strong argument for remaining an unmarried mother. There's no stigma attached any more","cn":"有强有力的理由来支持未婚妈妈。这再也不是什么丢脸的事了。"}},{"pos":"N-COUNT 可数名词","cn":"(花朵的)柱头","en":"The stigma of a flower is the top of the centre part which takes in pollen."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when you feel guilty and embarrassed because you, or someone who is close to you, have done something wrong","cn":""},{"en":"a feeling of shame and embarrassment because you have been made to look weak or stupid in front of other people","cn":""},{"en":"the loss of other people’s respect because you have done something bad, or you have been unsuccessful","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If something has a negative association attached to it, call this a stigma. Bed-wetting can lead to a social stigma for a six year old, while chewing tobacco might have the same effect for a sixty year old."}]},"collocations":{"phrases":["ADJ. social","VERB + STIGMA carry Being an unmarried mother used to carry a social stigma. | remove Wider knowledge of the disease removed some of the sti","STIGMA + VERB be attached to sth, be associated with sth There is still a lot of stigma attached to suicide.","PREP. ~ to There is no stigma to being made redundant."]},"media":{"uk":"media/ldoce/hwd/bre/4/stigma0205.mp3","us":"media/ldoce/hwd/ame/7/stigma.mp3"},"examples":[{"en":"There is no longer any stigma attached to being divorced.","cn":"离婚不再是什么丢脸的事。"},{"en":"the social stigma of alcoholism","cn":"酗酒在社会上的恶名"}],"oxford":{"phon":"ˈstɪɡmə","pos":"noun","senses":[{"en":"negative feelings that people have about particular circumstances or characteristics that somebody may have","cn":"耻辱；羞耻","g":"[uncountable, countable, usually singular]","ex":{"en":"the social stigma of alcoholism","cn":"酗酒在社会上的恶名"}},{"en":"the part in the middle of a flower where pollen is received","cn":"（花的）柱头","g":"[countable]","lab":"biology"}]}},"steelmaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钢铁公司","en":"A steelmaker is a company that makes steel."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company that makes steel","cn":"钢铁公司"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41steelmaker.mp3","us":"media/ldoce/hwd/ame/7/laadsteelmaker.mp3"}},"stunned":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling surprised and upset by something very unexpected and unpleasant","cn":""},{"en":"shocked because something very unpleasant or frightening has happened – used when the experience has made you feel weak or nervous","cn":""},{"en":"to feel shocked and unable to do normal things","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When you're stunned , you're thrown for a loop: either by shocking news or a blow to the head."}]},"collocations":{"phrases":["VERBS appear, be, feel, look, seem, sit, sound, stand Morton stood stunned, unable to believe his ears. | leave sb Leaving them all stunned,","ADV. deeply | absolutely, completely, quite | almost | a bit, a little, slightly, somewhat | briefly, momentarily","PREP. at They seemed stunned at his outburst. | by She was a bit stunned by the news. | with stunned with grief"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41stunned.mp3","us":"media/ldoce/hwd/ame/8/laadstunned.mp3"},"examples":[{"en":"There was a stunned silence when I told them the news.","cn":"我把消息讲了后，他们惊愕得哑然一片。"},{"en":"She was too stunned to speak.","cn":"她惊愕得说不出话来。"}],"oxford":{"phon":"stʌnd","pos":"adjective","senses":[{"en":"very surprised or shocked; showing this","cn":"惊呆了：非常惊讶或震惊；显示这个","ex":{"en":"She was too stunned to speak.","cn":"她惊愕得说不出话来。"}}]}},"stoneware":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(在高温下烧制的)粗陶器","en":"Stoneware is hard clay pottery which is baked at a high temperature.","ex":{"en":"...hand-painted blue-and-white stoneware.","cn":"手绘青花粗陶器"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"pots, bowls etc that are made from a special hard clay","cn":"粗陶器"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41stoneware.mp3","us":"media/ldoce/hwd/ame/f/stoneware.mp3"},"oxford":{"phon":"ˈstəʊnweə(r)","pos":"noun","senses":[{"en":"pots, dishes, etc. made from clay that contains a small amount of the hard stone called flint","cn":"炻器；粗陶器；缸瓦器"}]}},"stratagem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常指蒙蔽别人的)花招，计谋，诡计","en":"A stratagem is a plan that is intended to achieve a particular effect, often by deceiving people.","ex":{"en":"Trade discounts may be used as a competitive stratagem to secure customer loyalty.","cn":"商业折扣可以用作维护顾客忠诚度的一种竞争手段。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a trick or plan to deceive an enemy or gain an advantage 〔","cn":"蒙蔽敌人或谋取利益的〕计谋﹐策略﹐花招"}]},"vocab":{"pos":"n","senses":[{"en":"A stratagem is a scheme or a clever plot. You can have a stratagem for winning a chess game, getting the girl (or boy), and avoiding a punishment. However, your opponents, crushes, and parents may have a trick or two of their own."}]},"media":{"uk":"media/ldoce/hwd/bre/a/stratagem0205.mp3","us":"media/ldoce/hwd/ame/a/stratagem.mp3"},"oxford":{"phon":"ˈstrætədʒəm","pos":"noun","senses":[{"en":"a trick or plan that you use to gain an advantage or to trick an opponent","cn":"（为取胜或迷惑对手的）计策，计谋","ex":{"en":"to adopt a clever stratagem","cn":"采取巧妙的策略"}}]}},"stone-dead":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"彻底地，完全地(扼杀)","en":"If you kill something such as an idea or emotion stone-dead, you completely destroy it.","ex":{"en":"The prospect of having to pay a graduate tax until retirement would kill the students' enthusiasm stone dead.","cn":"想到今后一直到退休为止都要缴毕业税，学生们的积极性会被彻底打消。"}}]},"oxford":{"phon":"ˌstəʊn ˈded","pos":"adjective","senses":[{"en":"completely dead or completely destroyed","cn":"完全死了的；完全毁坏的","ex":{"en":"Any feeling he had left for her was now stone dead.","cn":"他留给她的任何感情现在都已经死了。"}}]}},"stalactite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钟乳石","en":"A stalactite is a long piece of rock which hangs down from the roof of a cave. Stalactites are formed by the slow dropping of water containing the mineral lime."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sharp pointed object hanging down from the roof of a cave , which is formed gradually by water that contains minerals as it drops slowly from the roof","cn":"钟乳石"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41stalactite.mp3","us":"media/ldoce/hwd/ame/c/stalactite.mp3"},"oxford":{"phon":"ˈstæləktaɪt","pos":"noun","senses":[{"en":"a long pointed piece of rock hanging down from the roof of a cave (= a hollow place underground), formed over a long period of time as water containing lime runs off the roof","cn":"钟乳石（向下悬垂）"}]}},"stuffing":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(烹饪前塞入鸡或辣椒等食物内的)填料","en":"Stuffing is a mixture of food that is put inside a bird such as a chicken, or a vegetable such as a pepper, before it is cooked.","ex":{"en":"Chestnuts can be used at Christmas time, as a stuffing for turkey, guinea fowl or chicken.","cn":"栗子可以在圣诞节时作火鸡、珍珠鸡或家鸡的填料。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(垫子、玩具等的)填充物","en":"Stuffing is material that is used to fill things such as cushions or toys in order to make them firm or solid."},{"pos":"PHRASE 短语","cn":"挫败…的锐气;使扫兴;使一蹶不振","en":"If something knocks the stuffing out of you when you are feeling enthusiastic or confident about something, it causes you to lose your enthusiasm or confidence.","ex":{"en":"Men have had a hard time for the last fifteen years. The women's movement knocked the stuffing out of them.","cn":"男性在过去的 15 年中一直灰头土脸。妇女运动挫败了男人的傲气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mixture of bread or rice, onion etc that you put inside a chicken, pepper etc before cooking it 〔","cn":"烹饪前塞入鸡﹑甜椒等中的〕填料"},{"en":"soft material that is used to fill something such as a cushion 〔","cn":"垫子等中的〕填料﹐填充物"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdestuffing.mp3","us":"media/ldoce/hwd/ame/b/stuffing.mp3"},"examples":[{"en":"sage and onion stuffing","cn":"洋苏叶和洋葱填料"}],"oxford":{"phon":"ˈstʌfɪŋ","pos":"noun","senses":[{"en":"a mixture of food such as bread, onions and herbs, cut into very small pieces and placed inside a chicken, etc. before it is cooked","cn":"（烹饪前塞入鸡等膛内的）填料","lab":"North American English also"},{"en":"soft material used to fill cushions, toys, etc.","cn":"（垫子、玩具等的）填充物"}]}},"starlit":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"星光照耀的;星光灿烂的","en":"Starlit means made lighter or brighter by the stars.","ex":{"en":"...a clear starlit sky.","cn":"星光灿烂的晴朗天空"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made brighter by light from the stars","cn":"星光照耀的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/starlit0205.mp3","us":"media/ldoce/hwd/ame/a/starlit.mp3"},"examples":[{"en":"a starlit night","cn":"星光照耀的夜晚"}],"oxford":{"phon":"ˈstɑːlɪt","pos":"adjective","senses":[{"en":"with light from the stars","cn":"星光照耀的","ex":{"en":"a starlit night","cn":"星光照耀的夜晚"}}]}},"stylish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有风度的;时尚的;有格调的;优雅的","en":"Someone or something that is stylish is smart, elegant, and fashionable.","ex":{"en":"...a very attractive and very stylish woman of 27.","cn":"气质迷人、格调高雅的 27 岁女子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"popular at a particular time","cn":""},{"en":"modern and fashionable – often used in a slightly disapproving or joking way","cn":""},{"en":"fashionable and well-designed in an attractive way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A stylish person is someone who has a bold sense of fashion, like a queen with flowing robes and gowns, or your friend who always wears the best-looking jeans."}]},"media":{"uk":"media/ldoce/hwd/bre/d/stylish0205.mp3","us":"media/ldoce/hwd/ame/3/stylish.mp3"},"examples":[{"en":"It was a stylish performance by both artists.","cn":"这是两位艺术家演出的一场高雅节目。"},{"en":"his stylish wife","cn":"他那时髦的妻子"}],"oxford":{"phon":"ˈstaɪlɪʃ","pos":"adjective","senses":[{"en":"fashionable and attractive","cn":"时髦迷人的；漂亮的","ex":{"en":"You look very stylish.","cn":"你看起来很时尚。"}}]}},"stupefy":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使震惊;使惊呆;使惊愕;使神志不清","en":"If something stupefies you, it shocks or surprises you so much that you cannot think properly for a while.","ex":{"en":"...a violent slap on the side of the head, which stunned and stupefied him.","cn":"他的一边脑袋上猛地挨了一掌，使他顿时觉得晕头转向，昏天黑地"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel extremely surprised, tired, or bored","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Don't be embarrassed if the magician's tricks stupefy you. It means you're amazed. Who doesn't want to be stopped in his tracks sometimes?"}]},"media":{"uk":"media/ldoce/hwd/bre/a/stupefying0205.mp3","us":"media/ldoce/hwd/ame/e/laadstupefying.mp3"},"examples":[{"en":"He was stupefied by the amount they had spent.","cn":"得知他们花了那么多钱，他都惊呆了。"},{"en":"She was stupefied with cold.","cn":"她给冻迷糊了。"}],"oxford":{"phon":"ˈstjuːpɪfaɪ","pos":"verb","senses":[{"en":"to surprise or shock somebody; to make somebody unable to think clearly","cn":"使惊讶（或惊呆、思维不清、神志不清）","ex":{"en":"He was stupefied by the amount they had spent.","cn":"得知他们花了那么多钱，他都惊呆了。"}}]}},"stew":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"炖煮的菜肴","en":"A stew is a meal which you make by cooking meat and vegetables in liquid at a low temperature.","ex":{"en":"She served him a bowl of beef stew","cn":"她为他端上了一碗炖牛肉。"}},{"pos":"VERB 动词","cn":"炖;煨;焖","en":"When you stew meat, vegetables, or fruit, you cook them slowly in liquid in a closed dish.","ex":{"en":"Stew the apple and blackberries to make a thick pulp.","cn":"将苹果和黑莓炖成稠浆。"}},{"pos":"PHRASE 短语","cn":"深感不安的;焦虑的;担心的","en":"If you are in a stew, you feel very worried.","ex":{"en":"He's been in a stew since early this morning","cn":"他从今天一大早就焦虑不安。"}},{"pos":"PHRASE 短语","cn":"(故意)让…独自烦恼(而不加劝慰)","en":"If you let a person stew or if you leave them to stew, you deliberately allow them to worry about something for a while, rather than telling them something which would make them feel better.","ex":{"en":"I'd rather let him stew","cn":"我宁可让他一个人去烦恼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a hot meal made by cooking meat and vegetables slowly in liquid for a long time","cn":"炖煮的菜肴"},{"en":"confused or worried about a difficult situation you are in 〔","cn":"为困境而〕困惑的﹐焦虑的"},{"en":"to cook something slowly in liquid","cn":"炖﹐煨﹐焖"}]},"vocab":{"pos":"v n","senses":[{"en":"To stew is to slowly cook food, which results in a soup-like food called a stew . To stew also means to brood angrily."}]},"media":{"uk":"media/ldoce/hwd/bre/9/stew_v0205.mp3","us":"media/ldoce/hwd/ame/0/stew1.mp3"},"examples":[{"en":"I've been stewing over the problem for a while.","cn":"这个问题我已经考虑了一会儿。"},{"en":"I'm making a stew for lunch.","cn":"我炖个菜中午吃。"}],"oxford":{"phon":"stjuː","pos":"noun","senses":[{"en":"a dish of meat and/or vegetables cooked slowly in liquid in a container that has a lid (= cover)","cn":"炖的菜，煨的菜（可荤可素）","ex":{"en":"beef stew and dumplings","cn":"牛肉炖丸子"}},{"en":"to cook something slowly in liquid in a closed dish; (of food) to be cooked in this way","cn":"炖；煨","g":"[transitive, intransitive]","ex":{"en":"stewed apples","cn":"炖苹果"},"pos":"verb"},{"en":"to think or worry about something","cn":"思考；担忧","g":"[intransitive]","ex":{"en":"I've been stewing over the problem for a while.","cn":"这个问题我已经考虑了一会儿。"},"pos":"verb"}]}},"stub":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"残根;残端;(铅笔)头;(烟)蒂","en":"The stub of a cigarette or a pencil is the last short piece of it which remains when the rest has been used.","ex":{"en":"He pulled the stub of a pencil from behind his ear.","cn":"他从耳后拿出一小段铅笔头。"}},{"pos":"N-COUNT 可数名词","cn":"票根;存根","en":"A ticket stub is the part that you keep when you go in to watch a performance.","ex":{"en":"Fans who still have their original ticket stubs should contact Sheffield Arena by July 3.","cn":"仍保留原始票根的球迷请于 7 月 3 号前和谢菲尔德体育馆联系。"}},{"pos":"N-COUNT 可数名词","cn":"(支票的)存根","en":"A cheque stub is the small part that you keep as a record of what you have paid."},{"pos":"VERB 动词","cn":"不小心踢到(脚趾)","en":"If you stub your toe, you hurt it by accidentally kicking something.","ex":{"en":"I stubbed my toes against a table leg.","cn":"我不小心踢到桌子腿上。"}},{"pos":"","cn":"","en":"相关词组：stub out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the short part of something long and thin, such as a cigarette or pencil, that is left when the rest has been used 〔","cn":"烟﹑铅笔等的〕残头﹐残根"},{"en":"the part of a ticket that is given back to you after it has been torn, as proof that you have paid","cn":"票根﹐存根"},{"en":"a piece of a cheque left in a cheque book as a record after the main part has been torn out 〔","cn":"支票的〕存根"}]},"media":{"uk":"media/ldoce/hwd/bre/9/stub_n0205.mp3","us":"media/ldoce/hwd/ame/a/stub1.mp3"},"examples":[{"en":"a pencil stub","cn":"铅笔头"},{"en":"a ticket stub","cn":"票根"}],"oxford":{"phon":"stʌb","pos":"noun","senses":[{"en":"a short piece of a cigarette, pencil, etc. that is left when the rest of it has been used","cn":"（烟、铅笔等的）残余部分，残端"},{"en":"the small part of a ticket, cheque, etc. that you keep as a record when you have given the main part to somebody","cn":"存根；票根"},{"en":"to hurt your toe by accident by hitting it against something hard","cn":"脚趾不小心踢到…上","ex":{"en":"She stubbed her toe on the step.","cn":"她的脚趾绊到了台阶。"},"pos":"verb"}]}},"streak":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"条纹;条痕","en":"A streak is a long stripe or mark on a surface which contrasts with the surface because it is a different colour.","ex":{"en":"There are these dark streaks on the surface of the moon","cn":"月球表面有这样一些黑色的条痕。"}},{"pos":"VERB 动词","cn":"在…上留下条纹(或条痕);使布满条纹(或条痕)","en":"If something streaks a surface, it makes long stripes or marks on the surface.","ex":{"en":"Rain had begun to streak the windowpanes","cn":"雨水已经开始在窗玻璃上冲出道道条痕。"}},{"pos":"N-COUNT 可数名词","cn":"性格特征;特点","en":"If someone has a streak of a particular type of behaviour, they sometimes behave in that way.","ex":{"en":"We're both alike—there is a streak of madness in us both","cn":"我们俩很像——都有点疯。"}},{"pos":"VERB 动词","cn":"飞奔;疾驰","en":"If something or someone streaks somewhere, they move there very quickly.","ex":{"en":"A meteorite streaked across the sky","cn":"一颗流星划过天空。"}},{"pos":"N-COUNT 可数名词","cn":"(赌博或体育比赛等中的)运气，手气","en":"A winning streak or a lucky streak is a continuous series of successes, for example in gambling or sport. A losing streak or an unlucky streak is a series of failures or losses.","ex":{"en":"The casinos had better watch out since I'm obviously on a lucky streak!","cn":"很明显我现在手气正旺，赌场最好当心了！"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of colour, especially one of several lines of colour all close together","cn":""},{"en":"a coloured line or thin mark, especially one that is not straight or has been made accidentally","cn":""},{"en":"a thick line of colour that is different from the areas around it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A streak is a mark or characteristic. What makes you keep trying to wipe the streak of permanent marker off the white couch — your clean streak or your stubborn streak ?"}]},"collocations":{"phrases":["ADJ. dark There were dark streaks down her cheeks where she had been crying. | faint, pale","PREP. ~ of The last streaks of light faded from the sky.","PHRASES a streak of lightning A streak of lightning forked across the sky. | a streak of red, white, etc. She had a few streaks of grey in h","ADJ. strong | hidden | adventurous, competitive, independent, mean, puritanical, rebellious, ruthless, selfish, stubborn, vicious","VERB + STREAK have Most of the players have a strong competitive streak. | reveal, show She suddenly revealed a mean streak in her character","PREP. with a ~ Holidays in the Australian outback are for those with an adventurous streak. | ~ of There was a streak of insanity in the fam","ADJ. winning | losing","VERB + STREAK be on The team has been on a winning streak since it won against Lazio."]},"media":{"uk":"media/ldoce/hwd/bre/1/streak_v0205.mp3","us":"media/ldoce/hwd/ame/5/streak1.mp3"},"examples":[{"en":"A car pulled out and streaked off down the road.","cn":"一辆汽车驶出后沿着公路疾驰而去。"},{"en":"His face was streaked with mud.","cn":"他脸上满是一条条的污泥。"}],"oxford":{"phon":"striːk","pos":"noun","senses":[{"en":"a long, thin mark or line that is a different colour from the surface it is on","cn":"条纹；条痕","ex":{"en":"There was a streak of blood on his face.","cn":"他脸上有一道血痕。"}},{"en":"a part of a person’s character, especially an unpleasant part","cn":"（尤指不好的）性格特征","ex":{"en":"a ruthless/vicious/mean streak","cn":"冷酷／邪恶／卑鄙的性格"}},{"en":"a series of successes or failures, especially in a sport or in gambling","cn":"（尤指体育比赛或赌博中）顺（或背）的时候，运气，手气","ex":{"en":"a streak of good luck","cn":"运气好"}},{"en":"to mark or cover something with streaks","cn":"在…上画条纹（或留下条痕）；使布满条纹（或条痕）","g":"[transitive]","ex":{"en":"Tears streaked her face.","cn":"她脸上是道道泪痕。"},"pos":"verb"},{"en":"to move very fast in a particular direction","cn":"（向某个方向）飞奔，疾驰","g":"[intransitive]","ex":{"en":"A car pulled out and streaked off down the road.","cn":"一辆汽车驶出后沿着公路疾驰而去。"},"pos":"verb"},{"en":"to run through a public place with no clothes on as a way of getting attention","cn":"裸奔","g":"[intransitive]","lab":"informal","pos":"verb"}]}},"strawberry":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"草莓","en":"A strawberry is a small red fruit which is soft and juicy and has tiny yellow seeds on its skin.","ex":{"en":"...strawberries and cream.","cn":"奶油草莓"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft red juicy fruit with small seeds on its surface, or the plant that grows this fruit","cn":"草莓"}]},"collocations":{"phrases":["QUANT. punnet I bought a punnet of strawberries.","STRAWBERRY + NOUN bed, plant •"]},"media":{"img":["media/ldoce/img/strawberry.jpg","media/thumb/strawberry.jpg"],"uk":"media/ldoce/hwd/bre/7/strawberry0205.mp3","us":"media/ldoce/hwd/ame/3/strawberry.mp3"},"examples":[{"en":"strawberries and cream","cn":"奶油草莓"},{"en":"strawberry plants","cn":"草莓植株"}],"oxford":{"phon":"ˈstrɔːbəri","pos":"noun","senses":[{"en":"a soft red fruit with very small yellow seeds on the surface, that grows on a low plant","cn":"草莓","ex":{"en":"strawberries and cream","cn":"草莓奶油"}}]}},"stimulation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to encourage or help an activity to begin or develop further","cn":""},{"en":"to encourage someone by making them excited about and interested in something","cn":""},{"en":"to make a plant or part of the body become active or stronger","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Stimulation spurs an organism to act. It can also be any specific event that causes someone to do something."}]},"collocations":{"phrases":["ADJ. direct | electrical electrical stimulation of nervous tissue | auditory, sensory, visual | sexual | intellectual, mental","VERB + STIMULATION get You don't get any intellectual stimulation in this job. | give sb, provide (sb with) The playgroup provides plenty of","PHRASES a lack of stimulation"]},"media":{"uk":"media/ldoce/hwd/bre/8/stimulate0205.mp3","us":"media/ldoce/hwd/ame/9/stimulate.mp3"},"examples":[{"en":"sensory/intellectual/sexual/visual/physical stimulation","cn":"感官/智力/性/视觉/身体刺激"},{"en":"the president’s plan to stimulate economic growth","cn":""}],"oxford":{"phon":"ˌstɪmjuˈleɪʃn","pos":"noun","senses":[{"en":"the act of encouraging of something so that it develops or becomes more active","cn":"刺激：鼓励某事物以使其发展或变得更加活跃的行为","ex":{"en":"the stimulation of economic growth","cn":"刺激经济增长"}},{"en":"the act of making somebody interested and excited about something by engaging their mind or their physical senses","cn":"刺激；使兴奋","ex":{"en":"Kids' interest is often caught by visual stimulation.","cn":"孩子们的兴趣往往是通过视觉刺激来吸引的。"}},{"en":"the act of making a part of the body function","cn":"促进（身体某部分）的功能","lab":"specialist","ex":{"en":"stimulation of the ovaries","cn":"刺激卵巢"}}]}},"stagnate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"停滞不前;不发展;无变化","en":"If something such as a business or society stagnates, it stops changing or progressing.","ex":{"en":"Industrial production is stagnating","cn":"工业生产正停滞不前。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not progress at all with a piece of work or activity","cn":""},{"en":"to not progress at all, even though you have worked hard","cn":""},{"en":"if a piece of work or activity goes badly , it does not make progress or develop in the way you would like it to","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If after high school you choose to live in your parents' house, keep the same job, and spend time with the same friends, your mother might worry that you've decided to stagnate , or stop moving forward."}]},"media":{"uk":"media/ldoce/hwd/bre/a/stagnate0205.mp3","us":"media/ldoce/hwd/ame/e/stagnate.mp3"},"examples":[{"en":"I feel I'm stagnating in this job.","cn":"我觉得，干这份工作我没有长进。"},{"en":"The water in the pond was stagnating.","cn":"池塘里的水逐渐变成了死水。"}],"oxford":{"phon":"stæɡˈneɪt","pos":"verb","senses":[{"en":"to stop developing or making progress","cn":"停滞；不发展；不进步","g":"[intransitive]","ex":{"en":"Profits have stagnated.","cn":"利润原地踏步。"}},{"en":"to be or become stagnant","cn":"因不流动而变得污浊","g":"[intransitive]","ex":{"en":"The water in the pond was stagnating.","cn":"池塘里的水逐渐变成了死水。"}}]}},"stablemate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"来自同一养马场的赛马","en":"Stablemates are race horses that come from the same stables and often compete against each other.","ex":{"en":"The head groom is responsible for seeing that Milton and his stablemates have safe journeys.","cn":"马夫长负责确保密尔顿及其他来自同一养马场的赛马都安全到达。"}},{"pos":"N-COUNT 可数名词","cn":"同一组织的人;同一公司生产的产品","en":"A person's stablemate is someone who is managed by the same organization. A product's stablemate is something which is produced by the same company.","ex":{"en":"Tomorrow he will play his Cuemasters stablemate.","cn":"明天他将迎战同是台球大师俱乐部出道的球手。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something produced by the same company, or someone who works for the same company","cn":"某人的同事/同机构的某物"}]},"media":{"uk":"media/ldoce/hwd/bre/5/stablemate0205.mp3","us":"media/ldoce/hwd/ame/b/laadstablemate.mp3"},"examples":[{"en":"the ‘Daily Mirror’ newspaper and its Scottish stablemate the ‘Daily Record’ 《","cn":"每日镜报》及其苏格兰姊妹报《每日纪事报》"},{"en":"the Daily Mirror’s Scottish stablemate, the Daily Record 《","cn":"每日镜报》的苏格兰姊妹报——《每日纪事报》"}],"oxford":{"phon":"ˈsteɪblmeɪt","pos":"noun","senses":[{"en":"a horse, especially a racing horse, from the same stable as another horse","cn":"同一马厩的马（尤指赛马）"},{"en":"a person or product from the same organization as another person or product","cn":"同机构的人（或产品）；同事；同伙","ex":{"en":"the VW corporate stablemate, Audi","cn":"大众汽车公司旗下的另一品牌——奥迪"}}]}},"stall":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)(进程)暂停;(使)推后","en":"If a process stalls, or if someone or something stalls it, the process stops but may continue at a later time.","ex":{"en":"The Social Democratic Party has vowed to try to stall the bill until the current session ends.","cn":"社会民主党誓言要将该议案拖到本次议会会议结束之后。"}},{"pos":"VERB 动词","cn":"拖延","en":"If you stall, you try to avoid doing something until later.","ex":{"en":"Some parties have accused the governor of stalling","cn":"有些党派指责州长在拖延时间。"}},{"pos":"VERB 动词","cn":"暂时阻止;把…拖住","en":"If you stall someone, you prevent them from doing something until a later time.","ex":{"en":"Shop manager Brian Steel stalled the man until the police arrived.","cn":"商店经理布赖恩·斯蒂尔将那名男子拖住，直到警方赶到。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)突然熄火","en":"If a vehicle stalls or if you accidentally stall it, the engine stops suddenly.","ex":{"en":"The engine stalled","cn":"发动机突然熄火了。"}},{"pos":"N-COUNT 可数名词","cn":"货摊;摊位;咨询台","en":"A stall is a large table on which you put goods that you want to sell, or information that you want to give people.","ex":{"en":"...market stalls selling local fruits.","cn":"出售当地水果的市场摊位"}},{"pos":"N-PLURAL 复数名词","cn":"(戏院、音乐厅的)正厅前排座位","en":"The stalls in a theatre or concert hall are the seats on the ground floor directly in front of the stage."},{"pos":"N-COUNT 可数名词","cn":"(淋浴间等房间里的)小分隔间","en":"A stall is a small enclosed area in a room which is used for a particular purpose, for example a shower."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large shop that sells a wide range of things, especially food, cleaning materials, and other things that people buy regularly","cn":""},{"en":"a shop in your local area that sells food, alcohol, magazines etc and is often open 24 hours a day","cn":""},{"en":"a small local shop, usually on the corner of a street, that sells food, newspapers, cigarettes etc","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 v n","senses":[{"en":"Stall means to stop or delay. If your car stalls, it comes to a stop. When you want a horse to stop, you put him in a stall, or small enclosure inside a barn."}]},"collocations":{"phrases":["ADV. effectively Discussions were effectively stalled by the union's refusal to participate.","PHRASES stall for time He asked them all kinds of pointless questions, stalling for time."]},"media":{"uk":"media/ldoce/hwd/bre/7/stall_v0205.mp3","us":"media/ldoce/hwd/ame/a/stall1.mp3"},"examples":[{"en":"See if you can stall her while I finish searching her office.","cn":"你看能不能拖住她，我好把她的办公室搜查完。"},{"en":"‘What do you mean?’ she asked, stalling for time. “","cn":"你这是什么意思？”她问，故意拖延着时间。"}],"oxford":{"phon":"stɔːl","pos":"noun","senses":[{"en":"a table or small shop with an open front that people sell things from, especially at a market","cn":"（尤指集市上的）货摊，摊位，售货亭","g":"[countable]","ex":{"en":"He works on a market stall in the Square.","cn":"他在广场上的一个集市售货亭工作。"}},{"en":"a section inside a farm building that is large enough for one animal to be kept in","cn":"牲畜棚；马厩；牛棚","g":"[countable]","ex":{"en":"We had to muck out stalls and groom the horses.","cn":"我们必须得打扫马厩，刷洗马匹。"}},{"en":"a small area in a room, surrounded by glass, walls, etc., that contains a shower or toilet","cn":"（房间内的）小隔间，淋浴室，洗手间","g":"[countable]","lab":"especially North American English","ex":{"en":"a bathroom stall","cn":"洗手间的淋浴区"}},{"en":"the seats that are nearest to the stage in a theatre","cn":"（剧场的）正厅前排座位","g":"[plural]","lab":"both British English","ex":{"en":"the front row of the stalls","cn":"正厅第一排"}},{"en":"the seats at the front of a church where the choir (= singers) and priests sit","cn":"（教堂内）唱诗班和牧师的座位","g":"[countable, usually plural]"},{"en":"a situation in which a vehicle’s engine suddenly stops because it is not getting enough power","cn":"（车辆发动机的）熄火；（车辆的）抛锚","g":"[countable, usually singular]"},{"en":"a situation in which an aircraft loses speed and goes steeply downwards","cn":"（飞机的）失速","g":"[countable, usually singular]","ex":{"en":"The plane went into a stall.","cn":"这架飞机进入失速状态。"}},{"en":"to stop suddenly because of a lack of power or speed; to make a vehicle or an engine do this","cn":"（使）熄火，抛锚","g":"[intransitive, transitive]","ex":{"en":"The car stalled and refused to start again.","cn":"汽车熄火打不着了。"},"pos":"verb"},{"en":"to try to avoid doing something or answering a question so that you have more time","cn":"故意拖延（以赢得时间）","g":"[intransitive]","ex":{"en":"They are still stalling on the deal.","cn":"他们仍在拖时间，而不急于达成协议。"},"pos":"verb"},{"en":"to make somebody wait so that you have more time to do something","cn":"拖住（以赢得时间做某事）","g":"[transitive]","ex":{"en":"See if you can stall her while I finish searching her office.","cn":"你看能不能拖住她，我好把她的办公室搜查完。"},"pos":"verb"},{"en":"to stop something from happening until a later date; to stop making progress","cn":"暂缓；搁置；停顿","g":"[transitive, intransitive]","ex":{"en":"There have been several attempts to revive the stalled peace plan.","cn":"重新启动搁置的和平方案的尝试已有多次。"},"pos":"verb"}]}},"stilt":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指在潮湿或松软的地面竖起的)木桩，金属桩，支柱","en":"Stilts are long upright pieces of wood or metal on which some buildings are built, especially where the ground is wet or very soft.","ex":{"en":"They inhabit reed huts built on stilts above the water.","cn":"他们住在建于水中木桩之上的芦苇草屋里。"}},{"pos":"N-COUNT 可数名词","cn":"高跷","en":"Stilts are two long pieces of wood with pieces for the feet fixed high up on the sides so that people can stand on them and walk high above the ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of a set of poles that support a building above the ground or above water 〔","cn":"将建筑物撑离地面或水面的〕支撑物﹐支材﹐桩子"},{"en":"one of two poles which you can stand on and walk high above the ground","cn":"高跷"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41stilt.mp3","us":"media/ldoce/hwd/ame/d/stilt.mp3"},"examples":[{"en":"a circus performer on stilts","cn":"马戏团里踩高跷的演员"},{"en":"a house built on stilts","cn":"建在桩子上的房子"}],"oxford":{"phon":"stɪlt","pos":"noun","senses":[{"en":"one of a set of posts that support a building so that it is high above the ground or water","cn":"（支撑建筑物高出地面或水面的）桩子，支柱","ex":{"en":"The houses are built on stilts to prevent flooding during the rainy season.","cn":"这些房屋建在高跷上，以防止雨季洪水泛滥。"}},{"en":"one of two long pieces of wood that have a step on the side that you can stand on, so that you can walk above the ground","cn":"高跷","ex":{"en":"a circus performer on stilts","cn":"马戏团里踩高跷的演员"}}]}},"stubble":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(作物收割后的)茬","en":"Stubble is the short stalks which are left standing in fields after corn or wheat has been cut.","ex":{"en":"The stubble was burning in the fields.","cn":"地里的麦茬正在燃烧。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"胡子茬","en":"The very short hairs on a man's face when he has not shaved recently are referred to as stubble .","ex":{"en":"His face was covered with the stubble of several nights.","cn":"他几天没刮胡子，脸上胡子拉碴。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"short stiff hairs that grow on a man’s face if he does not shave","cn":"胡子茬﹐须茬﹐短须"},{"en":"short stiff pieces left in the fields after wheat, corn etc has been cut 〔","cn":"作物收割后遗留在地里的〕残茎﹐茬（子）"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Stubble is the prickly hair that grows back after being shaved. You might find stubble on a man's chin or on a woman's leg."}]},"media":{"uk":"media/ldoce/hwd/bre/f/stubble0205.mp3","us":"media/ldoce/hwd/ame/7/stubble.mp3"},"oxford":{"phon":"ˈstʌbl","pos":"noun","senses":[{"en":"the lower short, stiff part of the stems of crops such as wheat that are left in the ground after the top part has been cut and collected","cn":"（作物收割后留在地里的）茬","ex":{"en":"There was a mouse hiding in the stubble.","cn":"茬里藏着一只老鼠。"}},{"en":"the short, stiff hairs that grow on a man’s face when he has not shaved recently","cn":"胡子茬","ex":{"en":"He had a two-day growth of dark stubble on his chin.","cn":"他的下巴上已经两天长出了黑胡茬。"}}]}},"statuesque":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(女性)高挑的，挺拔的","en":"A statuesque woman is big and tall, and stands straight.","ex":{"en":"She was a statuesque brunette.","cn":"她有着一头深褐色头发，身材高挑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"large and beautiful in an impressive way, like a statue","cn":"高大漂亮的﹐雕像般端庄优美的"}]},"vocab":{"pos":"adj","senses":[{"en":"If your favorite teacher is as beautiful and impressive as a statue in a museum, go ahead and describe her as statuesque ."}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41statuesque.mp3","us":"media/ldoce/hwd/ame/c/statuesque.mp3"},"examples":[{"en":"a statuesque woman","cn":"一位端庄优雅的高挑女子"}],"oxford":{"phon":"ˌstætʃuˈesk","pos":"adjective","senses":[{"en":"tall and beautiful in an impressive way; like a statue","cn":"又高又美的；雕塑般的"}]}},"stapler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"订书机","en":"A stapler is a device used for putting staples into sheets of paper."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tool used for putting staples into paper","cn":"订书机"}]},"media":{"img":["media/ldoce/img/stapler.jpg","media/thumb/stapler.jpg"],"uk":"media/ldoce/hwd/bre/e/stapler0205.mp3","us":"media/ldoce/hwd/ame/2/stapler.mp3"},"oxford":{"phon":"ˈsteɪplə(r)","pos":"noun","senses":[{"en":"a small device used for putting staples into paper, etc.","cn":"订书机"}]}},"std":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"","en":"STD is an abbreviation for (缩略=) 'sexually transmitted disease'.","ex":{"en":"...an STD clinic.","cn":"性传播疾病诊疗所"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disease that one person passes to another through having sex, such as AIDS or herpes","cn":"性传播疾病"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41std.mp3","us":"media/ldoce/hwd/ame/c/std2.mp3"},"oxford":{"phon":"ˌes tiː ˈdiː","pos":"noun","senses":[{"en":"a disease that is passed from one person to another during sexual activity (the abbreviation for ‘sexually transmitted disease’)","cn":"性传播疾病（全写为 sexually transmitted disease）"}]}},"stretchy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有弹性的;有弹力的","en":"Stretchy material is slightly elastic and stretches easily."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"material that is stretchy can stretch when you pull it and then return to its original shape","cn":"有弹性的﹐可伸缩的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stretchy.mp3","us":"media/ldoce/hwd/ame/a/stretchy.mp3"},"examples":[{"en":"stretchy fabric","cn":"有弹性的织物"},{"en":"stretchy cotton leggings","cn":"女式棉质弹性紧身裤"}],"oxford":{"phon":"ˈstretʃi","pos":"adjective","senses":[{"en":"that can easily be made longer or wider without tearing or breaking","cn":"有弹性的","ex":{"en":"stretchy fabric","cn":"有弹性的织物"}}]}},"starter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一餐中的)第一道菜，开胃小吃","en":"A starter is a small quantity of food that is served as the first course of a meal."},{"pos":"N-COUNT 可数名词","cn":"(汽车的)发动装置","en":"The starter of a car is the device that starts the engine.","ex":{"en":"A car's starter is basically an electric motor.","cn":"汽车的启动装置基本上是个电动机。"}},{"pos":"N-COUNT 可数名词","cn":"(不一定坚持到比赛结束的)参赛者，参赛动物","en":"The starters in a race are the people or animals who take part at the beginning even if they do not finish.","ex":{"en":"Of the 10 starters, four were eliminated or retired.","cn":"10 名参赛者中有 4 名被淘汰或自行退出了。"}},{"pos":"PHRASE 短语","cn":"作为开端;首先;第一","en":"You use for starters when you mention something to indicate that it is the first item or point in a series.","ex":{"en":"These prizes are just for starters. Other exciting offers are flooding in","cn":"这些奖只是个开始。其他激动人心的奖励还会接踵而至。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the parts of a meal that are served one after the other","cn":""},{"en":"a particular kind of food cooked in a particular way and served at a meal","cn":""},{"en":"the first part of a meal in a restaurant","cn":""}]},"collocations":{"phrases":["ADJ. cold, hot","VERB + STARTER eat, have Are you having a starter? | choose, order I've chosen a hot starter. | serve sth as This dish can be served as a st"]},"media":{"uk":"media/ldoce/hwd/bre/f/starter0205.mp3","us":"media/ldoce/hwd/ame/0/starter.mp3"},"examples":[{"en":"Only 8 of the 28 starters completed the course. * 28","cn":"名参赛者中，只有 8 人完成了全程。"},{"en":"He was a late starter in the theatre (= older than most people when they start).","cn":"他从事戏剧表演起步较晚。"}],"oxford":{"phon":"ˈstɑːtə(r)","pos":"noun","senses":[{"en":"a small dish of food that is served before the main course of a meal","cn":"（主菜之前的）开胃小吃，开胃品","lab":"especially British English","ex":{"en":"This dish serves 4–6 people as a starter.","cn":"这道菜适合4-6人作为开胃菜。"}},{"en":"a person, horse, car, etc. that is in a race at the beginning","cn":"参赛人；参赛的马（或汽车等）","ex":{"en":"Only 8 of the 28 starters completed the course.","cn":"28 名参赛者中，只有 8 人完成了全程。"}},{"en":"a person who gives the signal for a race to start","cn":"（赛跑等的）发令员","ex":{"en":"the starter’s gun","cn":"发令枪"}},{"en":"a device used for starting the engine of a vehicle","cn":"（发动机的）启动装置，启动器","ex":{"en":"the starter button","cn":"启动按钮"}},{"en":"a person who begins doing a particular activity in the way mentioned","cn":"起步（或启动）…的人","ex":{"en":"He was a late starter in the theatre (= older than most people when they start).","cn":"他从事戏剧表演起步较晚。"}},{"en":"something that is intended to be used by somebody who is starting to do something","cn":"在起步阶段使用的；启动时用的","ex":{"en":"a starter home (= a small home for somebody who is buying property for the first time)","cn":"供初次购房者购买的房屋"}}]}},"stitch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"缝;绣;缝补","en":"If you stitch cloth, you use a needle and thread to join two pieces together or to make a decoration.","ex":{"en":"Fold the fabric and stitch the two layers together","cn":"将布料对折，然后将两层缝在一起。"}},{"pos":"N-COUNT 可数名词","cn":"(布料上的)针脚，线迹","en":"Stitches are the short pieces of thread that have been sewn in a piece of cloth.","ex":{"en":"...a row of straight stitches","cn":"一排直直的针脚"}},{"pos":"N-COUNT 可数名词","cn":"(编织或钩针法中的)一针","en":"In knitting and crochet, a stitch is a loop made by one turn of wool around a knitting needle or crochet hook.","ex":{"en":"Her mother counted the stitches on her knitting needles","cn":"她母亲数了数编织针上的针数。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"针法;编织花样;缝法","en":"If you sew or knit something in a particular stitch, you sew or knit in a way that produces a particular pattern.","ex":{"en":"The design can be worked in cross stitch.","cn":"这个图案可以用十字针法绣出来。"}},{"pos":"VERB 动词","cn":"缝合(伤口)","en":"When doctors stitch a wound, they use a special needle and thread to sew the skin together.","ex":{"en":"Jill washed and stitched the wound.","cn":"吉尔清洗并缝合了伤口。"}},{"pos":"N-COUNT 可数名词","cn":"(缝合伤口的)缝线","en":"A stitch is a piece of thread that has been used to sew the skin of a wound together.","ex":{"en":"He had six stitches in a head wound.","cn":"他头上的伤口缝了 6 针。"}},{"pos":"N-SING 单数名词","cn":"(通常指因奔跑或大笑引起的)肋部剧痛，岔气","en":"A stitch is a sharp pain in your side, usually caused by running or laughing a lot."},{"pos":"PHRASE 短语","cn":"捧腹大笑;大笑不止","en":"If you are in stitches, you cannot stop laughing.","ex":{"en":"Here's a book that will have you in stitches.","cn":"这是一本会让你笑破肚皮的书。"}},{"pos":"","cn":"","en":"相关词组：stitch up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short piece of thread that has been sewn into a piece of cloth, or the action of the thread going into and out of the cloth 〔","cn":"缝纫中的〕一针﹔缝"},{"en":"a piece of special thread which has been used to sew the edges of a wound together 〔","cn":"缝合伤口的〕缝线"},{"en":"a sharp pain in the side of your body, which you can get by running or laughing a lot 〔","cn":"跑步或大笑引起的胁部的〕剧痛"}]},"collocations":{"phrases":["ADJ. blanket, chain, cross, running, seam, tacking, zigzag, etc.","VERB + STITCH do, put, sew (sth) with Can you do chain stitch? Put a stitch in the corner of the pocket to keep it in place. The edge was se","ADJ. knitted | cable, garter, plain, purl, slip, stocking, tuck, etc.","VERB + STITCH knit | cast on, cast off | drop, pick up 3 in a wound","ADJ. dissolvable, dissolving, self-dissolving","VERB + STITCH have I had to have five stitches when I cut my finger. | insert, put in | remove, take out | have out When are you having your","STITCH + VERB dissolve","PREP. ~ in He had twenty stitches in a head wound."]},"media":{"uk":"media/ldoce/hwd/bre/6/stitch_n0205.mp3","us":"media/ldoce/hwd/ame/b/stitch1.mp3"},"examples":[{"en":"They think they have the US market stitched up.","cn":"他们觉得美国市场已是万无一失。"},{"en":"Can we slow down? I've got a stitch.","cn":"我们慢一点好不好？我岔气了。"}],"oxford":{"phon":"stɪtʃ","pos":"noun","senses":[{"en":"one of the small lines of thread that you can see on a piece of cloth after it has been sewn; the action that produces this","cn":"（缝纫的）一针，针脚；缝","g":"[countable]","ex":{"en":"Try to keep the stitches small and straight.","cn":"针脚要尽量缝得小而直。"}},{"en":"one of the small circles of wool that you make around the needle when you are knitting (= making clothing out of wool with two long needles)","cn":"（编织的）一针","g":"[countable]","ex":{"en":"to drop a stitch (= to lose one that you have made)","cn":"漏一针"}},{"en":"a particular style of sewing or knitting that you use to make the pattern you want","cn":"缝法；针法；编织法","g":"[countable, uncountable]","ex":{"en":"chain stitch","cn":"链式线步"}},{"en":"a short piece of thread, etc. that doctors use to sew the edges of a wound together","cn":"（缝合伤口的）缝线","g":"[countable]","lab":"especially British English","ex":{"en":"The cut needed eight stitches.","cn":"这道伤口需要缝八针。"}},{"en":"a sudden pain in the side of your body, usually caused by running or laughing","cn":"肋部突然的疼痛（多由奔跑或笑引起）；岔气","g":"[countable, usually singular]","ex":{"en":"Can we slow down? I've got a stitch.","cn":"我们慢一点好不好？我岔气了。"}},{"en":"to use a needle and thread to repair, join, or decorate pieces of cloth","cn":"缝；缝补","g":"[often passive]","lab":"figurative","ex":{"en":"Her wedding dress was stitched by hand.","cn":"她的婚纱是手工缝制的。"},"pos":"verb"},{"en":"to sew the edges of a wound together","cn":"缝合（伤口）","ex":{"en":"The cut will need to be stitched.","cn":"这伤口需要缝合。"},"pos":"verb"}]}},"stentorian":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)洪亮的","en":"A stentorian voice is very loud and strong.","ex":{"en":"He bellowed in a stentorian voice.","cn":"他用洪亮的声音大声喊叫。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a stentorian voice is very loud and powerful 〔","cn":"声音〕洪亮的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective stentorian describes a booming voice. If you're teaching a group of unruly kids, you'll need to practice a stentorian voice to be heard above the din."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41stentorian.mp3","us":"media/ldoce/hwd/ame/e/stentorian.mp3"},"oxford":{"phon":"stenˈtɔːriən","pos":"adjective","senses":[{"en":"loud and powerful","cn":"响亮的；洪亮的","ex":{"en":"He spoke in stentorian tones.","cn":"他说话声音洪亮。"}}]}},"stool":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"凳子","en":"A stool is a seat with legs but no support for your arms or back.","ex":{"en":"O'Brien sat on a bar stool and leaned his elbows on the counter.","cn":"奥布赖恩坐在一张吧凳上，胳膊肘靠在吧台上。"}},{"pos":"PHRASE 短语","cn":"两头落空;鸡飞蛋打","en":"If someone has fallen between two stools, they are unable to decide which of two courses of action to take and as a result they have not done either of them successfully."},{"pos":"N-COUNT 可数名词","cn":"大便;粪便","en":"Stools are the pieces of solid waste matter that are passed out of a person's body through their bowels."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is part of or closely connected with a criminal organization but who secretly tells the police about its activities","cn":""},{"en":"someone who secretly gives the police information about someone who is responsible for a crime, in return for money, when this seems disloyal","cn":""},{"en":"someone who is friendly with criminals and who secretly tells the police about their activities, especially activities involving illegal drugs","cn":""}]},"collocations":{"phrases":["ADJ. high, tall | three-legged | folding, fold-up | bar, kitchen, music, piano","VERB + STOOL perch on/be perched on, sit (down) on He was perched on a bar stool, ordering a beer. | get off | drag up, pull up She pulled u"]},"media":{"img":["media/ldoce/img/bar_stool.jpg"],"uk":"media/ldoce/hwd/bre/b/stool0205.mp3","us":"media/ldoce/hwd/ame/c/stool.mp3"},"examples":[{"en":"a bar stool","cn":"酒吧高凳"},{"en":"a piano stool","cn":"钢琴凳"}],"oxford":{"phon":"stuːl","pos":"noun","senses":[{"en":"a seat with legs but with nothing to support your back or arms","cn":"凳子","ex":{"en":"a bar stool","cn":"酒吧高凳"}},{"en":"a piece of solid waste from your body","cn":"粪便；大便","lab":"medical"}]}},"stimulating":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"keeping your attention and making you want to know more","cn":""},{"en":"very interesting","cn":""},{"en":"giving you new ideas or experiences in a way that is interesting and enjoyable","cn":""}]},"collocations":{"phrases":["VERBS be, sound | find sb/sth","ADV. extremely, really, very | intellectually, visually The programme contains some creative and visually stimulating material."]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdestimulating.mp3","us":"media/ldoce/hwd/ame/b/stimulating.mp3"},"examples":[{"en":"shower gel containing plant extracts that have a stimulating effect on the skin","cn":"含有对皮肤有益的植物精华的沐浴凝胶"},{"en":"a stimulating teacher","cn":"能够引发兴趣的老师"}],"oxford":{"phon":"ˈstɪmjuleɪtɪŋ","pos":"adjective","senses":[{"en":"full of interesting or exciting ideas; making people feel enthusiastic","cn":"趣味盎然的；激励人的；振奋人心的","ex":{"en":"Thank you for a most stimulating discussion.","cn":"感谢你们妙趣横生的讨论。"}},{"en":"making you feel more active and healthy","cn":"增加活力的；增进健康的","ex":{"en":"shower gel containing plant extracts that have a stimulating effect on the skin","cn":"含有对皮肤有益的植物精华的沐浴凝胶"}}]}},"streaky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有条纹(或条痕)的","en":"Something that is streaky is marked with long stripes that are a different colour to the rest of it.","ex":{"en":"She has streaky fair hair and blue eyes.","cn":"她有一双蓝色的眼睛，头上有一缕缕的金发。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"marked with streaks","cn":"有条纹的﹔有纹理的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41streaky.mp3","us":"media/ldoce/hwd/ame/d/streaky.mp3"},"examples":[{"en":"The wallpaper was streaky with grease.","cn":"壁纸上道道油渍。"},{"en":"( BrE ) streaky bacon (= with layers of fat in it)","cn":"五花咸肉"}],"oxford":{"phon":"ˈstriːki","pos":"adjective","senses":[{"en":"marked with lines of a different colour","cn":"有条纹（或条痕）的","lab":"British English","ex":{"en":"streaky blonde hair","cn":"挑染的金发"}}]}},"statewide":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(美国)全州范围的，遍及全州的","en":"Statewide means across or throughout the whole of one of the states of the United States.","ex":{"en":"Each year they compete in a prominent statewide bicycle race","cn":"每年他们都要参加著名的全州自行车大赛。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"affecting or involving the whole of a US state 〔","cn":"美国〕影响全州的[地]﹔全州范围的[地]"}]},"media":{"uk":"media/ldoce/hwd/bre/8/statewide0205.mp3","us":"media/ldoce/hwd/ame/f/statewide.mp3"},"examples":[{"en":"She won 10% of the vote statewide.","cn":"她赢得全州 10% 的选票。"},{"en":"a statewide election","cn":"州选举"}],"oxford":{"phon":"ˈsteɪtwaɪd","pos":"adjective, adverb","senses":[{"en":"happening or existing in all parts of a state of the US","cn":"（美国）全州性的（地），在全州范围内的（地）","ex":{"en":"a statewide election","cn":"州选举"}}]}},"stupidity":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"behaviour or actions that show a lack of good sense or good judgment","cn":"愚蠢的行为"},{"en":"the quality of being stupid","cn":"愚蠢﹐愚笨﹔糊涂"}]},"vocab":{"pos":"n","senses":[{"en":"Stupidity is the quality of being stupid. It’s the opposite of intelligence. Stupidity is responsible for many acts that follow the words, “Hey, watch this!”"}]},"collocations":{"phrases":["ADJ. complete, crass, incredible, sheer, utter","VERB + STUPIDITY demonstrate, show Her answer showed the most incredible stupidity.","PREP. through (your) ~ Through his own stupidity, he missed an excellent opportunity."]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41stupidity.mp3","us":"media/ldoce/hwd/ame/9/stupidity.mp3"},"examples":[{"en":"I couldn't believe my own stupidity.","cn":"我干的蠢事我自己都不能相信。"},{"en":"the errors and stupidities of youth","cn":"年轻时犯的错误和做的蠢事"}],"oxford":{"phon":"stjuːˈpɪdəti","pos":"noun","senses":[{"en":"behaviour that shows a lack of thought or good judgement","cn":"愚蠢行为；糊涂","g":"[uncountable, countable, usually plural]","ex":{"en":"I couldn't believe my own stupidity.","cn":"我干的蠢事我自己都不能相信。"}},{"en":"the state or quality of being slow to learn and not clever or intelligent","cn":"愚蠢；笨","g":"[uncountable]","ex":{"en":"He faked stupidity to try to escape punishment for the crime.","cn":"他装傻以逃避因犯罪而受到的惩罚。"}}]}},"strife":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"严重不和;冲突;争斗","en":"Strife is strong disagreement or fighting.","ex":{"en":"Money is a major cause of strife in many marriages","cn":"金钱是造成很多婚姻不和的一个主要原因。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"trouble between two or more people or groups 〔","cn":"两个或两个以上的人或团体之间的〕冲突﹐纠纷﹐争斗"},{"en":"SYN conflict ethnic/religious/civil etc strife a time of political strife","cn":"政治纷争四起的时代"}]},"vocab":{"pos":"n","senses":[{"en":"Strife is the act or state of fighting or arguing violently. The years leading up to the U.S. Civil War were characterized by great strife between northern and southern states over slavery and the role of a federal government."}]},"collocations":{"phrases":["ADJ. internal | ethnic, factional, internecine, sectarian | civil, industrial, political, religious, social | domestic, marital","VERB + STRIFE cause, provoke | be torn (apart) by The country has been torn apart by years of civil strife. | end","PREP. during/in the ~ He lost his job during last year's industrial strife. | ~ among/between internecine strife among the nationalities of ","PHRASES an end to the strife, a time of strife"]},"media":{"uk":"media/ldoce/hwd/bre/f/strife0205.mp3","us":"media/ldoce/hwd/ame/1/strife.mp3"},"examples":[{"en":"The country was torn apart by strife.","cn":"这个国家被内部纷争搞得四分五裂。"},{"en":"civil strife","cn":"内乱"}],"oxford":{"phon":"straɪf","pos":"noun","senses":[{"en":"anger or violence between two people or groups of people who disagree","cn":"冲突；争斗；倾轧","g":"[uncountable]","lab":"formal or literary","ex":{"en":"civil strife","cn":"内乱"}},{"en":"trouble or difficulty of any kind","cn":"麻烦；纠纷；困难","lab":"Australian English, New Zealand English，，"}]}},"stability":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the condition of being steady and not changing","cn":"稳固﹐稳定"},{"en":"the ability of a substance to stay in the same state 〔","cn":"物质的〕稳定性"}]},"vocab":{"pos":"n","senses":[{"en":"Stability is the quality of being unchanging. You know you should be congratulated on your commitment to stability when you’ve lived in the same place your whole life."}]},"collocations":{"phrases":["ADJ. greater | relative | long-term | internal | economic, financial, monetary, price | political, social | emotional","VERB + STABILITY achieve, bring, ensure, give sb, provide (sb with) The policy should bring greater monetary stability to the country. | lac","PHRASES a period of stability The country was enjoying a period of political stability. | a threat to stability The conflict is becoming a t"]},"media":{"uk":"media/ldoce/hwd/bre/0/stability0205.mp3","us":"media/ldoce/hwd/ame/f/stability.mp3"},"examples":[{"en":"Being back with their family should provide emotional stability for the children.","cn":"回到家人身边会使儿童的情绪稳定下来。"},{"en":"the stability of the dollar on the world's money markets","cn":"美元在世界货币市场上的稳定性"}],"oxford":{"phon":"stəˈbɪləti","pos":"noun","senses":[{"en":"the quality or state of being steady and not changing or being upset in any way (= the quality of being stable)","cn":"稳定（性）；稳固（性）","ex":{"en":"political/economic/social stability","cn":"政治／经济／社会稳定"}}]}},"stigmatize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"侮辱;污蔑;使蒙羞","en":"If someone or something is stigmatized, they are unfairly regarded by many people as being bad or having something to be ashamed of.","ex":{"en":"Children in single-parent families must not be stigmatised","cn":"单亲家庭的孩子们不应该受到歧视。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be treated by society as if you should feel ashamed of your situation or behaviour","cn":"被视为可耻﹐受到蔑视"}]},"vocab":{"pos":"v","senses":[{"en":"If you stigmatize someone, you have given that person a label — and it's usually a label that is limiting in some way."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41stigmatize.mp3","us":"media/ldoce/hwd/ame/4/stigmatize.mp3"},"examples":[{"en":"Single mothers often feel that they are stigmatized by society.","cn":"单身母亲常常觉得自己受社会歧视。"}],"oxford":{"phon":"ˈstɪɡmətaɪz","pos":"verb","senses":[{"en":"to describe or consider somebody/something in a way that unfairly suggests that they are bad or do not deserve respect","cn":"使感到羞耻；侮蔑"}]}},"stalk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茎;秆;柄;梗","en":"The stalk of a flower, leaf, or fruit is the thin part that joins it to the plant or tree.","ex":{"en":"A single pale blue flower grows up from each joint on a long stalk.","cn":"一条长长的茎秆的每个节上都会长出一朵浅蓝色的花。"}},{"pos":"VERB 动词","cn":"悄悄跟踪(敌人或野兽)","en":"If you stalk a person or a wild animal, you follow them quietly in order to kill them, catch them, or observe them carefully.","ex":{"en":"He stalks his victims like a hunter after a deer.","cn":"他像猎手跟踪鹿一样悄悄跟踪受害人。"}},{"pos":"VERB 动词","cn":"跟踪骚扰，不断纠缠(名人、分手恋人等)","en":"If someone stalks someone else, especially a famous person or a person they used to have a relationship with, they keep following them or contacting them in an annoying and frightening way.","ex":{"en":"Even after their divorce he continued to stalk and threaten her.","cn":"即使在离婚后他仍继续纠缠和威胁她。"}},{"pos":"VERB 动词","cn":"高视阔步;怒气冲冲地走","en":"If you stalk somewhere, you walk there in a stiff, proud, or angry way.","ex":{"en":"If his patience is tried at meetings he has been known to stalk out.","cn":"大家都知道如果他在会议上失去耐心，便会愤怒离席。"}},{"pos":"VERB 动词","cn":"(死亡、恐惧、罪恶等)笼罩，蔓延，肆虐","en":"If you say that something bad such as death, fear, or evil stalks a place, you mean it is there.","ex":{"en":"The spectre of neo-fascism, as he put it, was stalking the streets of Sofia and other big cities.","cn":"用他的话来说，新法西斯主义的幽灵正在索非亚和其他大城市中游荡。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow part of a plant that supports leaves, fruits, or flowers 〔","cn":"植物的〕茎﹐柄﹐梗"},{"en":"a thin upright object","cn":"柄状物"},{"en":"if your eyes are out on stalks, you are very surprised or shocked","cn":"某人眼珠子都要掉出来了〔形容非常吃惊或震惊〕"}]},"vocab":{"pos":"1 n 2 n v","senses":[{"en":"A stalk is a long, vertical stem or connecting part of a plant. When you eat celery, do you like the inner stalks , which are paler and more tender, or the tough outer ones?"}]},"media":{"img":["media/ldoce/img/rose.jpg"],"uk":"media/ldoce/hwd/bre/b/stalk_v0205.mp3","us":"media/ldoce/hwd/ame/1/stalk1.mp3"},"examples":[{"en":"He stalked his victim as she walked home, before attacking and robbing her.","cn":"她步行回家时，他偷偷地接近然后下手袭击，并且抢劫了她。"},{"en":"The gunmen stalked the building, looking for victims.","cn":"这些持枪歹徒凶神恶煞地打楼里走过，寻找袭击的目标。"}],"oxford":{"phon":"stɔːk","pos":"noun","senses":[{"en":"a thin stem that supports a leaf, flower or fruit and joins it to another part of the plant or tree; the main stem of a plant","cn":"（叶）柄；（花）梗；（果实的）柄；（植物的）茎，秆","ex":{"en":"flowers on long stalks","cn":"长茎上的花"}},{"en":"a long, thin structure that supports something, especially an organ in some animals, and joins it on to another part","cn":"柄；（动物的）肉柄，肉茎","ex":{"en":"Crabs have eyes on stalks.","cn":"螃蟹的眼睛长在肉柄上。"}},{"en":"to move slowly and quietly towards an animal or a person, in order to kill, catch or harm it or them","cn":"偷偷接近，潜近（猎物或人）","g":"[transitive, intransitive]","ex":{"en":"The lion was stalking a zebra.","cn":"狮子偷偷接近斑马。"},"pos":"verb"},{"en":"to illegally follow and watch somebody over a long period of time, in a way that is annoying or frightening","cn":"（非法）跟踪，盯梢","g":"[transitive]","ex":{"en":"She claimed that he had been stalking her over a period of three years.","cn":"她声称，三年来他一直在盯她的梢。"},"pos":"verb"},{"en":"to walk in an angry or proud way","cn":"怒冲冲地走；趾高气扬地走","g":"[intransitive]","ex":{"en":"He stalked off without a word.","cn":"他一言未发，怒冲冲地走了。"},"pos":"verb"},{"en":"to move through a place in an unpleasant or threatening way","cn":"令人厌恶地穿过；威胁地通过","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"The gunmen stalked the building, looking for victims.","cn":"这些持枪歹徒凶神恶煞般地打楼里走过，寻找袭击的目标。"},"pos":"verb"}]}},"starlight":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"星光","en":"Starlight is the light that comes from the stars at night."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the light that comes from the stars in the night sky","cn":"星光"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41starlight.mp3","us":"media/ldoce/hwd/ame/3/starlight.mp3"},"examples":[{"en":"We walked home by starlight.","cn":"我们借着星光走回家。"}],"oxford":{"phon":"ˈstɑːlaɪt","pos":"noun","senses":[{"en":"light from the stars","cn":"星光","ex":{"en":"We walked home by starlight.","cn":"我们借着星光走回家。"}}]}},"starfish":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海星","en":"A starfish is a flat, star-shaped creature with five arms that lives in the sea."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat sea animal that has five arms forming the shape of a star","cn":"海星"}]},"media":{"img":["media/ldoce/img/starfish.jpg"],"uk":"media/ldoce/hwd/bre/5/starfish0205.mp3","us":"media/ldoce/hwd/ame/1/starfish.mp3"},"oxford":{"phon":"ˈstɑːfɪʃ","pos":"noun","senses":[{"en":"a flat sea creature in the shape of a star with five arms","cn":"海星；星鱼"}]}},"stride":{"collins":{"senses":[{"pos":"VERB 动词","cn":"大步走;阔步行走","en":"If you stride somewhere, you walk there with quick, long steps.","ex":{"en":"They were joined by a newcomer who came striding across a field","cn":"一个新来的人大步穿过一片田地，加入到他们的行列。"}},{"pos":"N-COUNT 可数名词","cn":"步幅;大步;一步(的距离)","en":"A stride is a long step which you take when you are walking or running.","ex":{"en":"With every stride, runners hit the ground with up to five times their body-weight","cn":"赛跑者每一步落地时对地面的压力最大能达到其体重的 5 倍。"}},{"pos":"N-SING 单数名词","cn":"步态;步伐","en":"Someone's stride is their way of walking with long steps.","ex":{"en":"He lengthened his stride to keep up with her.","cn":"他迈大步追上她。"}},{"pos":"N-COUNT 可数名词","cn":"(快速的)进展，进步，发展","en":"If you make strides in something that you are doing, you make rapid progress in it.","ex":{"en":"The country has made enormous strides politically but not economically.","cn":"该国在政治上取得了巨大的发展，但经济却跟不上去。"}},{"pos":"PHRASE 短语","cn":"进入状态;开始走上轨道;驾轻就熟","en":"If you get into your stride or hit your stride, you start to do something easily and confidently, after being slow and uncertain.","ex":{"en":"The campaign is just getting into its stride","cn":"运动刚开始有点起色。"}},{"pos":"PHRASE 短语","cn":"从容处理;泰然处之","en":"In British English, if you take a problem or difficulty in your stride, you deal with it calmly and easily. The American expression is take something in stride .","ex":{"en":"Beth was struck by how Naomi took the mistake in her stride.","cn":"娜奥米在失误面前表现得处乱不惊，给贝丝留下了深刻印象。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to deal successfully with a fairly difficult but ordinary situation","cn":""},{"en":"to succeed in dealing with difficult problems in your life, your job, or your relationships","cn":""},{"en":"to live through an unhappy or unpleasant time in your life, and deal with the problems that it brings","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"The noun stride means \"significant progress.\" You might make a huge stride towards making peace with the rival school by hosting a block party and inviting their students."}]},"collocations":{"phrases":["ADV. briskly, quickly | confidently | purposefully | angrily | ahead, away, back, forward, in, off, out, over, past He strode off in search ","PREP. across, along, away, down, into, out of, over, past, through, towards, up She strode purposefully towards the door.","PHRASES come striding He came striding up the path."]},"media":{"uk":"media/ldoce/hwd/bre/b/stride_v0205.mp3","us":"media/ldoce/hwd/ame/4/stride1.mp3"},"examples":[{"en":"We're making great strides in the search for a cure.","cn":"在探索治疗办法方面，我们正不断取得重大进展。"},{"en":"She did not slow her stride until she was face to face with us.","cn":"她没有放慢脚步，径直走到我们面前。"}],"oxford":{"phon":"straɪd","pos":"verb","senses":[{"en":"to walk with long steps in a particular direction","cn":"大步走；阔步行走","ex":{"en":"We strode across the snowy fields.","cn":"我们大步流星地穿过雪封的旷野。"}},{"en":"one long step; the distance covered by a step","cn":"大步；一步（的距离）","ex":{"en":"He crossed the room in two strides.","cn":"他两大步跨到屋子另一头。"},"pos":"noun"},{"en":"your way of walking or running","cn":"步态；步伐","ex":{"en":"his familiar purposeful stride","cn":"他那熟悉而坚定的步伐"},"pos":"noun"},{"en":"an improvement in the way something is developing","cn":"进展；进步；发展","ex":{"en":"We're making great strides in the search for a cure.","cn":"在探索治疗办法方面，我们正不断取得重大进展。"},"pos":"noun"},{"en":"trousers","cn":"裤子","g":"[plural]","lab":"Australian English, informal，，","pos":"noun"}]}},"stoat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鼬鼠","en":"A stoat is a small, thin, wild animal that has brown fur. Some stoats that live in northern Europe have fur that turns white in winter."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small wild animal, similar to a weasel , that has a long thin body and brown fur","cn":"白鼬﹐扫雪鼬"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41stoat.mp3","us":"media/ldoce/hwd/ame/6/stoat.mp3"},"oxford":{"phon":"stəʊt","pos":"noun","senses":[{"en":"a small wild animal with a long body and brown fur that, in northern areas, turns white in winter. The white fur is called ermine.","cn":"白鼬"}]}},"structuralism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"结构主义(语学、文学、社会学等的研究方法，关注结构中的对立观点或因素，并试图说明它们与整体结构的关系)","en":"Structuralism is a method of interpreting and analysing such things as language, literature, and society, which focuses on contrasting ideas or elements of structure and attempts to show how they relate to the whole structure."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a method of studying language, literature, society etc in which you examine the relationships of the different parts or ideas in order to determine their meaning","cn":"结构主义〔指语言学﹑文学﹑社会学等学科中通过分析不同部分或观点之间的关系以确定其含义的研究方法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41structuralism.mp3","us":"media/ldoce/hwd/ame/7/structuralism.mp3"},"examples":[{"en":"a structuralist approach","cn":"结构主义方法"}],"oxford":{"phon":"ˈstrʌktʃərəlɪzəm","pos":"noun","senses":[{"en":"a theory that considers any text as a structure whose various parts only have meaning when they are considered in relation to each other","cn":"结构主义（认为任何一篇文字为一结构体系，其各个部分只有在相互关系中才有意义）"}]}},"stripling":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"年轻男子;小伙子","en":"People sometimes refer to a young man as a stripling when they want to indicate in a slightly humorous way that although he is no longer a boy, he is not yet really a man.","ex":{"en":"...a stripling of 20.","cn":"20 岁的小伙子"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a boy who is almost a young man – sometimes used humorously about a man who is quite old","cn":"青年男子﹐小伙子〔有时幽默地指年龄相当大的人〕"}]},"vocab":{"pos":"n","senses":[{"en":"You can use the old-fashioned noun stripling to talk about a teenager, though few people these days will know what you're talking about."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41stripling.mp3","us":"media/ldoce/hwd/ame/c/stripling.mp3"},"oxford":{"phon":"ˈstrɪplɪŋ","pos":"noun","senses":[{"en":"a young man who is older than a boy but who does not seem to be a real man yet","cn":"年轻男子；小伙子"}]}},"straggle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"散乱地移动;零星地走","en":"If people straggle somewhere, they move there slowly, in small groups with large, irregular gaps between them.","ex":{"en":"They came straggling up the cliff road","cn":"他们零零散散地沿着悬崖小路走上来。"}},{"pos":"VERB 动词","cn":"散乱地分布;散布","en":"If a small quantity of things straggle over an area, they cover it in an uneven or untidy way.","ex":{"en":"Her grey hair straggled in wisps about her face","cn":"她那灰白的头发一缕缕地披散在脸旁。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if the people in a group straggle somewhere, they go there fairly slowly and with large spaces between them","cn":"散乱地慢慢走﹐零星地走﹔落后"},{"en":"to move, grow, or spread out untidily in different directions","cn":"蔓延﹐蔓生﹔零乱地散布"}]},"vocab":{"pos":"v n","senses":[{"en":"To straggle is to wander in an indirect, meandering way. Lions often go for the small antelopes that straggle behind the herd."}]},"media":{"uk":"media/ldoce/hwd/bre/5/straggle0205.mp3","us":"media/ldoce/hwd/ame/2/straggle.mp3"},"examples":[{"en":"The town straggled to an end and the fields began.","cn":"城边上横七竖八的建筑不再蔓延，田野展现出来。"},{"en":"On the way the kids straggled behind us.","cn":"在路上，那几个孩子落在了我们后面。"}],"oxford":{"phon":"ˈstræɡl","pos":"verb","senses":[{"en":"to grow, spread or move in an untidy way in different directions","cn":"蔓生；杂乱地蔓延；散布","g":"[intransitive]","ex":{"en":"Her hair was straggling over her eyes.","cn":"她的头发凌乱地搭盖在双眼上。"}},{"en":"to move slowly behind a group of people that you are with so that you become separated from them","cn":"落伍；掉队；落在后面","g":"[intransitive]","ex":{"en":"On the way the kids straggled behind us.","cn":"在路上，那几个孩子落在了我们后面。"}}]}},"statuette":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常置于台、架上的)小雕像，小雕塑","en":"A statuette is a very small sculpture of a person or an animal which is often displayed on a shelf or stand."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very small statue that can be put on a table or shelf 〔","cn":"放在桌子或架子上的〕小雕像﹐小塑像"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41statuette.mp3","us":"media/ldoce/hwd/ame/9/statuette.mp3"},"oxford":{"phon":"ˌstætʃuˈet","pos":"noun","senses":[{"en":"a small statue","cn":"小雕像；小塑像","ex":{"en":"A china statuette of a shepherdess stood on the table.","cn":"桌上有一个牧羊女的小瓷像。"}}]}},"stereotype":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"模式化的形象(或特征);固定模式;刻板印象;陈规老套","en":"A stereotype is a fixed general image or set of characteristics that a lot of people believe represent a particular type of person or thing.","ex":{"en":"There's always been a stereotype about successful businessmen","cn":"人们对于成功商人一直都有一种固定印象。"}},{"pos":"VERB 动词","cn":"使模式化;使定型","en":"If someone is stereotyped as something, people form a fixed general idea or image of them, so that it is assumed that they will behave in a particular way.","ex":{"en":"He was stereotyped by some as a rebel","cn":"他被一些人认定为叛逆者。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is representative of the group that they belong to is typical of it, and shows what the others in the group are like","cn":""},{"en":"the archetypal person or thing is the most typical example of that kind of person or thing, and has all their most important qualities","cn":""},{"en":"a classic example of something is a very typical and very good example of it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A stereotype is a preconceived notion, especially about a group of people. Many stereotypes are racist, sexist, or homophobic."}]},"collocations":{"phrases":["ADJ. common, popular, traditional, usual | negative | cultural, national, racial | gender, sexual | social","VERB + STEREOTYPE create, produce | perpetuate, reinforce Jokes perpetuate various national stereotypes. | conform to, fit Not all areas of ","PREP. ~ about common stereotypes about the French | ~ of the stereotype of women as passive victims"]},"media":{"uk":"media/ldoce/hwd/bre/3/stereotype_n0205.mp3","us":"media/ldoce/hwd/ame/4/stereotype1.mp3"},"examples":[{"en":"He doesn't conform to the usual stereotype of the businessman with a dark suit and briefcase.","cn":"他不同于人们一般印象中穿黑色西装、提公文包的商人形象。"},{"en":"Children from certain backgrounds tend to be stereotyped by their teachers.","cn":"教师往往模式化地根据学生的某些背景把他们归类。"}],"oxford":{"phon":"ˈsteriətaɪp","pos":"noun","senses":[{"en":"a fixed idea or image that many people have of a particular type of person or thing, but which is often not true in reality and may cause hurt and offence","cn":"模式化观念（或形象）；老一套；刻板印象","lab":"British English","ex":{"en":"cultural/gender/racial stereotypes","cn":"有关文化的／性别的／种族的旧框框"}},{"en":"to form a fixed idea about a person or thing which may not really be true","cn":"对…形成模式化（或类型化）的看法","ex":{"en":"Children from certain backgrounds tend to be stereotyped by their teachers.","cn":"教师往往模式化地根据学生的某些背景把他们归类。"},"pos":"verb"}]}},"stopover":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"中途停留","en":"A stopover is a short stay in a place in between parts of a journey.","ex":{"en":"The President had talks during a brief stopover in Lisbon with his Portuguese counterpart","cn":"总统在里斯本作短暂停留期间和葡萄牙总统进行了会谈。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short stay somewhere between parts of a journey, especially on a long plane journey 〔","cn":"尤指长途飞行中的〕中途停留"}]},"collocations":{"phrases":["ADJ. brief","VERB + STOPOVER have","PREP. at a/the ~ We had our tickets checked at each stopover. | during a/the ~ During our two-day stopover in Bangkok we saw most of the sig"]},"media":{"uk":"media/ldoce/hwd/bre/f/stopover0205.mp3","us":"media/ldoce/hwd/ame/d/stopover.mp3"},"examples":[{"en":"We had a two-day stopover in Fiji on the way to Australia.","cn":"我们去澳大利亚时中途在斐济停留了两天。"},{"en":"a two-day stopover in Hong Kong","cn":"中途在香港停留两天"}],"oxford":{"phon":"ˈstɒpəʊvə(r)","pos":"noun","senses":[{"en":"a short stay somewhere between two parts of a journey","cn":"中途停留","lab":"British English","ex":{"en":"We had a two-day stopover in Fiji on the way to Australia.","cn":"我们去澳大利亚时中途在斐济停留了两天。"}}]}},"stock-in-trade":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"习惯性行为;惯用伎俩","en":"If you say that something is someone's stock-in-trade, you mean that it is a usual part of their behaviour or work.","ex":{"en":"Patriotism is every politician's stock-in-trade","cn":"爱国主义是政客们的惯用伎俩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is typical of a particular person or thing, especially what they say or do","cn":"惯用言辞﹔惯有行为﹔惯用手段[伎俩]"},{"en":"the things you need to do your job","cn":"职业所需的事物"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41stock-in-trade.mp3","us":"media/ldoce/hwd/ame/9/stock-in-trade.mp3"},"examples":[{"en":"Famous people and their private lives are the stock-in-trade of the popular newspapers.","cn":"名人和名人的私生活是通俗报纸惯有的内容。"},{"en":"Stewart’s stock-in-trade was the face-to-face interview.","cn":"斯图尔特的习惯做法是面对面的采访。"}],"oxford":{"phon":"ˌstɒk ɪn ˈtreɪd","pos":"noun","senses":[{"en":"a person’s stock-in-trade is something that they do, say or use very often or too often","cn":"惯做的事（或说的话、用的东西）","ex":{"en":"Famous people and their private lives are the stock-in-trade of the popular newspapers.","cn":"名人和名人的私生活是通俗报纸惯有的内容。"}}]}},"straighten":{"collins":{"senses":[{"pos":"VERB 动词","cn":"把…整理好;使端正","en":"If you straighten something, you make it tidy or put it in its proper position.","ex":{"en":"She sipped her coffee and straightened a picture on the wall.","cn":"她抿了口咖啡，然后把墙上的一幅画扶正。"}},{"pos":"VERB 动词","cn":"挺直，端正(身体)","en":"If you are standing in a relaxed or slightly bent position and then you straighten, you make your back or body straight and upright.","ex":{"en":"The three men straightened and stood waiting.","cn":"3 个男人挺直身体，站着等候。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变直;(使)变正","en":"If you straighten something, or it straightens, it becomes straight.","ex":{"en":"Straighten both legs until they are fully extended","cn":"挺直双腿直至完全伸展开。"}},{"pos":"","cn":"","en":"相关词组：straighten out straighten up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to change the way you behave, and start being obedient, hard-working etc, after behaving badly for a long time","cn":""},{"en":"to decide that you will change the way you behave, because you really want to stop behaving badly, breaking the law etc","cn":""},{"en":"to start behaving better after a situation in which people did not trust you because you were behaving illegally or dishonestly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/straighten0205.mp3","us":"media/ldoce/hwd/ame/1/straighten.mp3"},"examples":[{"en":"Straighten up slowly, then repeat the exercise ten times.","cn":"慢慢挺直身体，然后把这个动作重复十次。"},{"en":"The road bends here then straightens out.","cn":"公路在这儿拐弯，然后就直了。"}],"oxford":{"phon":"ˈstreɪtn","pos":"verb","senses":[{"en":"to become straight; to make something straight","cn":"（使）变直，变正","g":"[transitive, intransitive]","ex":{"en":"I straightened my tie and walked in.","cn":"我把领带拉正，走了进去。"}},{"en":"to make your body straight without bending any part of it","cn":"挺直，端正（身体）","g":"[transitive, intransitive]","ex":{"en":"He stood up and straightened his shoulders.","cn":"他站起身，挺起肩膀。"}}]}},"sturdy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚固的;结实的;强壮的","en":"Someone or something that is sturdy looks strong and is unlikely to be easily injured or damaged.","ex":{"en":"She was a short, sturdy woman in her early sixties","cn":"她是个 60 岁出头、身材矮小结实的女人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easily broken or damaged","cn":""},{"en":"strong – used especially about something that can be used a lot without damaging it or making it weaker","cn":""},{"en":"extremely strong – used about materials, tools, machines etc that are made especially to be used a lot without being easily damaged","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Describe something that is firmly constructed or strongly made as sturdy . That house you built was not sturdy at all. It blew down in the last wind storm. Fortunately, it was only a dog house and the dog wasn't in it."}]},"media":{"uk":"media/ldoce/hwd/bre/7/sturdy0205.mp3","us":"media/ldoce/hwd/ame/1/sturdy.mp3"},"examples":[{"en":"The village has always maintained a sturdy independence.","cn":"这个村子始终顽强地保持着独立。"},{"en":"The boat was sturdily made.","cn":"这艘船造得结实。"}],"oxford":{"phon":"ˈstɜːdi","pos":"adjective","senses":[{"en":"strong and not easily damaged","cn":"结实的；坚固的","ex":{"en":"a sturdy pair of boots","cn":"一双结实的靴子"}},{"en":"physically strong and healthy","cn":"强壮的；健壮的","g":"[usually before noun]","ex":{"en":"a man of sturdy build","cn":"体格健壮的男人"}},{"en":"not easily influenced or changed by other people","cn":"坚决的；坚定的；顽强的","ex":{"en":"The village has always maintained a sturdy independence.","cn":"这个村子始终顽强地保持着独立。"}}]}},"storey":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(楼房的)层，楼层","en":"A storey of a building is one of its different levels, which is situated above or below other levels.","ex":{"en":"Houses must not be more than two storeys high.","cn":"房子的高度不得超过两层。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the levels in a building","cn":""},{"en":"used when saying how many levels a building has","cn":""},{"en":"the floor of a building that is at ground level","cn":""}]},"collocations":{"phrases":["ADJ. lower | top, upper","VERB + STOREY have The house has three storeys. | occupy The kitchen occupies the lower storey.","PREP. on a/the ~ I live on the top storey.","PHRASES 5/10, etc. storeys high The building is four storeys high."]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdestorey.mp3","us":"media/ldoce/hwd/ame/c/story1.mp3"},"examples":[{"en":"the upper/lower storey of the house","cn":"房子的上面/下面一层"},{"en":"The office building is five storeys high.","cn":"办公大楼有五层楼高。"}],"oxford":{"phon":"ˈstɔːri","pos":"noun","senses":[{"en":"a level of a building; a floor","cn":"楼层","lab":"British English","ex":{"en":"the upper/lower storey of the house","cn":"房子的上面／下面一层"}},{"en":"having the number of levels mentioned","cn":"有…层的","lab":"British English","ex":{"en":"a four-storeyed building","cn":"四层楼房"}}]}},"stale":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)不新鲜的，变味的","en":"Stale food is no longer fresh or good to eat.","ex":{"en":"Their daily diet consisted of a lump of stale bread, a bowl of rice and stale water.","cn":"他们的日常饮食包括一块不新鲜的面包、一碗米饭和变味的水。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(空气、气味)不新鲜的，污浊的","en":"Stale air or a stale smells is unpleasant because it is no longer fresh.","ex":{"en":"A layer of smoke hung low in the stale air.","cn":"一层烟雾低悬在污浊的空气中。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厌倦的;腻烦的","en":"If you feel stale, you are bored because you have no new ideas or enthusiasm for what you are doing.","ex":{"en":"I believe in progression, in taking risks, in never getting stale.","cn":"我崇尚进取、冒险和永不倦怠。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方、活动或观点)令人厌倦的，缺乏新鲜感的","en":"If you say that a place, an activity, or an idea is stale, you mean that it has become boring because it is always the same.","ex":{"en":"Her relationship with Mark has become stale","cn":"她和马克之间已经没有新鲜感了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if food goes off or goes bad , it starts to decay because it has been kept for too long","cn":""},{"en":"food that is bad is not good to eat, because it has started to decay","cn":""},{"en":"bread, cake etc that is stale is hard, dry, and unpleasant to eat","cn":""}]},"vocab":{"pos":"1 adj 2 v","senses":[{"en":"If something is stale , it's no longer fresh. Ever bite into a piece of bread that's been left out a little too long? Chances are it's stale , or dry and hard to eat. Try making some croutons out of it."}]},"collocations":{"phrases":["VERBS be, look, smell, taste The room smelled musty and stale. | become, go, turn This bread's going stale.","ADV. extremely, very | a bit, a little, rather, slightly","PREP. with The atmosphere was stale with cigarette smoke."]},"media":{"uk":"media/ldoce/hwd/bre/9/stale0205.mp3","us":"media/ldoce/hwd/ame/3/stale1.mp3"},"examples":[{"en":"After ten years in the job, she felt stale and needed a change.","cn":"在那个岗位干了十年之后，她觉得腻了，需要换换工作。"},{"en":"Their marriage had gone stale.","cn":"他们的婚姻已了无热情。"}],"oxford":{"phon":"steɪl","pos":"adjective","senses":[{"en":"no longer fresh and therefore unpleasant to eat","cn":"不新鲜的","ex":{"en":"This bread's going stale.","cn":"面包不新鲜了。"}},{"en":"no longer fresh; smelling unpleasant","cn":"不新鲜的；污浊的；难闻的","ex":{"en":"The atmosphere was stale with cigarette smoke.","cn":"烟味令空气污浊。"}},{"en":"something that is stale has been said or done too many times before and is no longer interesting or exciting","cn":"陈腐的；没有新意的；老掉牙的","ex":{"en":"stale jokes","cn":"老掉牙的笑话"}},{"en":"a person who is stale has done the same thing for too long and so is unable to do it well or produce any new ideas","cn":"（因持续做某事时间太长）厌倦的，腻烦的","ex":{"en":"After ten years in the job, she felt stale and needed a change.","cn":"在那个岗位干了十年之后，她觉得腻了，需要换换工作。"}}]}},"sterile":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"消过毒的;无菌的","en":"Something that is sterile is completely clean and free from germs.","ex":{"en":"He always made sure that any cuts were protected by sterile dressings","cn":"他总是坚持要用无菌纱布包扎伤口。"}},{"pos":"ADJ 形容词","cn":"无生殖能力的;不育的","en":"A person or animal that is sterile is unable to have or produce babies.","ex":{"en":"George was sterile.","cn":"乔治没有生育能力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无生气的;缺乏新意的","en":"A sterile situation is lacking in energy and new ideas.","ex":{"en":"Too much time has been wasted in sterile debate.","cn":"在毫无新意的辩论上已经浪费了太多时间。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without any dirt or marks","cn":""},{"en":"water or air that is pure does not contain any dirt, pollution, or bacteria","cn":""},{"en":"completely clean, with no bacteria, and therefore safe for medical or scientific use","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A sterile person can't have kids, and a sterile environment is bland and boring. In both cases, sterile means lifeless."}]},"collocations":{"phrases":["VERBS be | become | remain | make sth | keep sth This top fits over the bottle and keeps the teat sterile.","ADV. completely | virtually 2 not able to produce young animals/babies","VERBS be | become | remain | leave sb, make sb","ADV. permanently Male workers were made permanently sterile by this pesticide. 3 with no interest or life","VERBS be | become, grow Their relationship had grown sterile over the years.","ADV. very | increasingly the increasingly sterile debate on constitutional reform | largely | rather, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/5/sterile0205.mp3","us":"media/ldoce/hwd/ame/c/sterile.mp3"},"examples":[{"en":"He felt creatively and emotionally sterile.","cn":"他感觉自己既缺乏创意又没有充沛的感情。"},{"en":"The room felt cold and sterile.","cn":"那房间让人觉得阴冷而没有生气。"}],"oxford":{"phon":"ˈsteraɪl","pos":"adjective","senses":[{"en":"not able to produce children or young animals","cn":"不能生育的；不育的"},{"en":"completely clean and free from bacteria","cn":"无菌的；消过毒的","ex":{"en":"sterile bandages","cn":"消毒绷带"}},{"en":"not producing any useful result","cn":"无结果的；没有实际价值的","ex":{"en":"We need to focus on solving the problem rather than continuing the sterile debate on how it came about.","cn":"我们需要集中精力解决问题，而不是继续就问题是如何产生的进行毫无结果的争论。"}},{"en":"not having individual personality, imagination or new ideas","cn":"刻板的；无个性的；缺乏新意的","ex":{"en":"The room felt cold and sterile.","cn":"那房间让人觉得阴冷而没有生气。"}},{"en":"not good enough to produce crops","cn":"贫瘠的"}]}},"stowaway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无票偷乘者;偷渡者","en":"A stowaway is a person who hides in a ship, aeroplane, or other vehicle in order to make a journey secretly or without paying.","ex":{"en":"The crew discovered the stowaway about two days into their voyage.","cn":"船员在开船约两天后发现了那名偷乘者。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who hides on a vehicle in order to travel secretly or to avoid paying","cn":"无票偷乘者﹐逃票者"}]},"media":{"uk":"media/ldoce/hwd/bre/7/stowaway0205.mp3","us":"media/ldoce/hwd/ame/5/stowaway.mp3"},"oxford":{"phon":"ˈstəʊəweɪ","pos":"noun","senses":[{"en":"a person who hides in a ship or plane before it leaves, in order to travel without paying or being seen","cn":"偷乘船（或飞机）者"}]}},"steadfast":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚定的;坚信的;坚贞不渝的","en":"If someone is steadfast in something that they are doing, they are convinced that what they are doing is right and they refuse to change it or to give up.","ex":{"en":"He remained steadfast in his belief that he had done the right thing.","cn":"他一直坚信自己做得对。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing to support a person, party, belief etc for a long time","cn":""},{"en":"supporting a particular person, party, set of beliefs, etc – used especially about someone you can can trust and depend on to support you","cn":""},{"en":"strongly supporting someone or something because you admire them, love them, or enjoy what they do","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who is firm and determined in a belief or a position can be called steadfast in that view, like your mom when she thinks you really shouldn’t wear that outfit."}]},"media":{"uk":"media/ldoce/hwd/bre/1/steadfast0205.mp3","us":"media/ldoce/hwd/ame/b/steadfast.mp3"},"examples":[{"en":"He remained steadfast in his determination to bring the killers to justice.","cn":"他要将杀人凶手绳之以法的决心一直没有动摇。"},{"en":"steadfast loyalty","cn":"忠贞不渝"}],"oxford":{"phon":"ˈstedfɑːst","pos":"adjective","senses":[{"en":"not changing in your attitudes or aims","cn":"坚定的；不动摇的","ex":{"en":"steadfast loyalty","cn":"忠贞不渝"}}]}},"stasis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"停滞;静止","en":"Stasis is a state in which something remains the same, and does not change or develop.","ex":{"en":"Rock'n'roll had entered a period of stasis.","cn":"摇滚乐已经进入了一个停滞期。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a state or period in which there is no change or development","cn":"停滞（期）﹔静止（期）"}]},"vocab":{"pos":"n","senses":[{"en":"When nothing's moving, that's stasis . If your negotiations about who does the dishes have reached a standstill, you know what stasis is. Yet the kitchen sink looks worse every day."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41stasis.mp3","us":"media/ldoce/hwd/ame/5/laadstasis.mp3"},"oxford":{"phon":"ˈsteɪsɪs","pos":"noun","senses":[{"en":"a situation in which there is no change or development","cn":"停滞；静止"}]}},"stately":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"雄伟的;庄严的;高贵的;优雅的","en":"Something or someone that is stately is impressive and graceful or dignified.","ex":{"en":"Instead of moving at his usual stately pace, he was almost running.","cn":"他没像平时那样优雅庄重地走着，而是几乎跑了起来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done slowly and with a lot of ceremony","cn":"缓慢而庄严的﹔正式的"},{"en":"impressive in style and size","cn":"雄伟的﹔高贵的﹔堂皇的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be stately is to appear noble and impressive, almost in a larger than life kind of way. You may encounter a stately gentleman or a stately statue. If you do, take a little bow."}]},"media":{"uk":"media/ldoce/hwd/bre/4/stately0205.mp3","us":"media/ldoce/hwd/ame/a/stately.mp3"},"examples":[{"en":"The procession made its stately progress through the streets of the city.","cn":"游行队伍缓慢而庄严地穿过城市的街道。"},{"en":"an avenue of stately chestnut trees","cn":"两边有雄伟高大栗树的林荫道"}],"oxford":{"phon":"ˈsteɪtli","pos":"adjective","senses":[{"en":"impressive in size, appearance or manner","cn":"宏大的；壮观的；气宇不凡的；仪态高贵的","ex":{"en":"an avenue of stately chestnut trees","cn":"两边有雄伟高大栗树的林荫道"}},{"en":"slow and formal","cn":"缓慢庄严的；优雅从容的","ex":{"en":"a stately dance","cn":"缓慢优雅的舞蹈"}}]}},"stalemate":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"僵局;僵持","en":"Stalemate is a situation in which neither side in an argument or contest can win or in which no progress is possible.","ex":{"en":"President Bush has ended the stalemate over moves to cut the country's budget deficit","cn":"布什总统已结束了在削减国家预算赤字的措施上形成的僵局。"}},{"pos":"N-VAR 可变名词","cn":"(国际象棋的)和棋","en":"In chess, stalemate is a position in which a player cannot make any move which is allowed by the rules, so that the game ends and no one wins."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which no further progress can be made because two groups or organizations cannot find a way to end a disagreement","cn":""},{"en":"a situation in which progress has stopped completely, especially because people cannot agree on what to do next","cn":""},{"en":"to slowly stop making any progress","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A stalemate is an impasse in a contest, a point where neither player — usually in chess — can win or lose."}]},"collocations":{"phrases":["ADJ. political","VERB + STALEMATE end in, reach, result in The talks reached (a) stalemate. | break Efforts to break the stalemate in the peace talks continu","STALEMATE + VERB continue","PREP. ~ between a stalemate between management and unions | ~ in The stalemate in the trade talks continues. | ~ on/over a stalemate over ec"]},"media":{"uk":"media/ldoce/hwd/bre/d/stalemate0205.mp3","us":"media/ldoce/hwd/ame/d/stalemate1.mp3"},"examples":[{"en":"The talks ended in (a) stalemate.","cn":"谈判陷入僵局，无果而终。"},{"en":"an attempt to break the stalemate","cn":"打破僵局的努力"}],"oxford":{"phon":"ˈsteɪlmeɪt","pos":"noun","senses":[{"en":"a disagreement or a situation in a competition in which neither side is able to win or make any progress","cn":"（辩论或竞赛中出现的）僵局，僵持局面","g":"[uncountable, countable, usually singular]","ex":{"en":"The talks ended in (a) stalemate.","cn":"谈判陷入僵局，无果而终。"}},{"en":"a situation in which a player cannot successfully move any of their pieces and the game ends without a winner","cn":"僵局；和棋","g":"[uncountable, singular]","ex":{"en":"The match ended in (a) stalemate","cn":"比赛以平局告终"}}]}},"statesmanship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"政治家风范;政治家的才干;政治家活动","en":"Statesmanship is the skill and activities of a statesman.","ex":{"en":"He praised the two leaders warmly for their statesmanship.","cn":"他热情地称赞了两位领导人的政治家风范。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works in politics, especially an elected member of the government","cn":""},{"en":"a political or government leader, especially one who is well-respected","cn":""},{"en":"in Britain, someone who has been elected to a parliament to represent people from a particular area of the country","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/statesman0205.mp3","us":"media/ldoce/hwd/ame/1/statesman.mp3"},"examples":[{"en":"a respected elder statesman","cn":""}],"oxford":{"phon":"ˈsteɪtsmənʃɪp","pos":"noun","senses":[{"en":"skill in managing state affairs","cn":"政治才能；治国才干"}]}},"stagger":{"collins":{"senses":[{"pos":"VERB 动词","cn":"蹒跚;摇晃地走","en":"If you stagger, you walk very unsteadily, for example because you are ill or drunk.","ex":{"en":"He lost his balance, staggered back against the rail and toppled over","cn":"他失去平衡，往后趔趄了一下，撞到栏杆摔倒了。"}},{"pos":"VERB 动词","cn":"勉强维持","en":"If you say that someone or something staggers on, you mean that it is only just succeeds in continuing.","ex":{"en":"Truman allowed him to stagger on for nearly another two years.","cn":"杜鲁门允许他又硬撑了近两年。"}},{"pos":"VERB 动词","cn":"使震惊;让…大吃一惊","en":"If something staggers you, it surprises you very much.","ex":{"en":"The whole thing staggers me.","cn":"整个事件让我震惊。"}},{"pos":"VERB 动词","cn":"使(假期或工作时间)错开","en":"To stagger things such as people's holidays or hours of work means to arrange them so that they do not all happen at the same time.","ex":{"en":"During the past few years the government has staggered the summer vacation periods for students.","cn":"在过去几年里，政府将学生放暑假的时间相互错开。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk with difficulty because one leg hurts, so that you put most of your weight on the other leg","cn":""},{"en":"to walk or move unsteadily, almost falling over, especially because you are drunk or have been injured","cn":""},{"en":"to walk with difficulty in a slow and unsteady way because your legs or feet hurt or have been injured","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"If you see someone stagger out of a bar, or walk unsteadily, like he's about to fall, chances are he's had a few too many drinks."}]},"collocations":{"phrases":["ADV. almost | a little, slightly | blindly She staggered blindly off into the darkness. | about, around, away, back, backwards, forward, off","PREP. from, into, out of, through, towards, under, etc. He was staggering under the weight of the sack.","PHRASES stagger to your feet She staggered to her feet and tottered unsteadily across the room."]},"media":{"uk":"media/ldoce/hwd/bre/f/stagger_n0205.mp3","us":"media/ldoce/hwd/ame/8/stagger1.mp3"},"examples":[{"en":"( figurative ) The company is staggering under the weight of a £10m debt.","cn":"公司在 1 000 万英镑债务的重压下步履艰难。"},{"en":"There were so many runners that they had to stagger the start.","cn":"参加赛跑的选手很多，他们不得不把起跑的时间错开。"}],"oxford":{"phon":"ˈstæɡə(r)","pos":"noun","senses":[{"en":"a weak unsteady way of walking, as if you are about to fall","cn":"走路摇摇晃晃，好像快要摔倒一样","ex":{"en":"to walk with a stagger","cn":"步履蹒跚"}},{"en":"to walk with weak unsteady steps, as if you are about to fall","cn":"摇摇晃晃地走；蹒跚；踉跄","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"The injured woman staggered to her feet.","cn":"受伤的女人摇摇晃晃地站起身来。"},"pos":"verb"},{"en":"to shock or surprise somebody very much","cn":"使震惊；使大吃一惊","g":"[transitive]","ex":{"en":"Her remarks staggered me.","cn":"她的话让我震惊。"},"pos":"verb"},{"en":"to arrange for events that would normally happen at the same time to start or happen at different times","cn":"使交错；使错开","g":"[transitive]","ex":{"en":"There were so many runners that they had to stagger the start.","cn":"参加赛跑的选手很多，他们不得不把起跑点错开。"},"pos":"verb"}]}},"stereo":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"立体声的","en":"Stereo is used to describe a sound system in which the sound is played through two speakers.","ex":{"en":"...loudspeakers that give all-around stereo sound.","cn":"具有环绕立体声效果的扩音器"}},{"pos":"N-COUNT 可数名词","cn":"立体声磁带播放机;立体声激光唱片播放机;立体音响","en":"A stereo is a cassette or CD player with two speakers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a machine for playing records, CD s etc that produces sound from two speaker s","cn":"立体声音响（设备）"},{"en":"if sound is played or broadcast in stereo, it is directed through two speakers","cn":"用立体声播放的"},{"en":"using a recording or broadcasting system in which the sound is directed through two speaker s","cn":"立体声的"}]},"media":{"img":["media/ldoce/img/stereo.jpg"],"uk":"media/ldoce/hwd/bre/6/stereo_n0205.mp3","us":"media/ldoce/hwd/ame/9/l3stereo.mp3"},"examples":[{"en":"Let's put some music on the stereo.","cn":"我们在立体声音响上放点音乐吧。"},{"en":"a car/personal stereo","cn":"车用/个人立体声音响"}],"oxford":{"phon":"ˈsteriəʊ","pos":"adjective","senses":[{"en":"using a sound system that has two separate speakers so that you hear different sounds from each; produced by a system of this type","cn":"立体声音响（系统）","ex":{"en":"stereo speakers/headphones","cn":"立体声扬声器/耳机"}},{"en":"the system for playing recorded music, speech, etc. in which the sound is directed through two channels","cn":"立体声","g":"[uncountable]","ex":{"en":"to broadcast in stereo","cn":"用立体声广播"},"pos":"noun"},{"en":"a machine that plays CDs, etc., sometimes with a radio, that has two separate speakers so that you hear different sounds from each","cn":"立体声音响（系统）","g":"[countable]","lab":"old-fashioned","ex":{"en":"a car/personal stereo","cn":"车用／个人立体声音响"},"pos":"noun"}]}},"stetson":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(牛仔戴的)斯特森宽边帽;牛仔帽","en":"A Stetson is a type of hat with a wide brim that is traditionally worn by cowboys."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall hat with a wide brim (= edge ) , worn especially in the American West 〔","cn":"尤指美国西部的〕斯泰特森帽"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41stetson.mp3","us":"media/ldoce/hwd/ame/9/laadstetson.mp3"},"oxford":{"phon":"ˈstetsn","pos":"noun","senses":[{"en":"a tall hat with a wide brim, worn especially by American cowboys","cn":"斯特森高顶宽边帽；牛仔帽"}]}},"strikebreaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"破坏罢工者;顶替罢工者工作的人;工贼","en":"A strike-breaker is a person who continues to work during a strike, or someone who takes over the work of a person who is on strike."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who continues working during a strike – used to show disapproval","cn":"破坏罢工者﹐工贼"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41strikebreaker.mp3","us":"media/ldoce/hwd/ame/5/strikebreaker.mp3"}},"strapping":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"高大健壮的;强健的","en":"If you describe someone as strapping, you mean that they are tall and strong, and look healthy.","ex":{"en":"He was a bricklayer—a big, strapping fellow.","cn":"他是位砌砖工——一个高大健壮的小伙子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is strong has big muscles and can lift heavy things, do a lot of physical work etc","cn":""},{"en":"very strong - use this about someone's body, arms, muscles etc","cn":""},{"en":"someone who is muscular looks strong because you can see that they have big muscles","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/strapping0205.mp3","us":"media/ldoce/hwd/ame/7/strapping.mp3"},"examples":[{"en":"a strapping lad","cn":"身材魁梧的小伙子"},{"en":"a strapping young lad","cn":"一个魁梧的小伙子"}],"oxford":{"phon":"ˈstræpɪŋ","pos":"adjective","senses":[{"en":"big, tall and strong","cn":"魁梧的；高大健壮的","ex":{"en":"a strapping lad","cn":"身材魁梧的小伙子"}}]}},"stooge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"傀儡;走狗;奴才","en":"If you refer to someone as a stooge, you are criticizing them because they are used by someone else to do unpleasant or dishonest tasks.","ex":{"en":"He has vehemently rejected claims that he is a government stooge","cn":"他言辞激烈地驳斥了称自己是政府的狗奴才的说法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is used by a more powerful person or group as part of their plans for getting power, especially when the person being used does not realize this","cn":""},{"en":"a ruler or government that seems to be independent but is really controlled by the government of another more powerful country","cn":""},{"en":"someone who is controlled and used unfairly by another person or group, especially to do something bad","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41stooge.mp3","us":"media/ldoce/hwd/ame/4/stooge.mp3"},"oxford":{"phon":"stuːdʒ","pos":"noun","senses":[{"en":"a person who is used by somebody to do things that are unpleasant or dishonest","cn":"受人驱使的人；奴才；走狗","lab":"informal, usually disapproving，，"},{"en":"a performer in a show whose role is to appear silly so that the other performers can make jokes about him or her","cn":"（供其他演员作弄打趣的）丑角"}]}},"stallion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成年雄马;(尤指)种马","en":"A stallion is a male horse, especially one kept for breeding."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male horse that is fully grown, especially one that is used for breeding","cn":"种马"}]},"media":{"uk":"media/ldoce/hwd/bre/d/stallion0205.mp3","us":"media/ldoce/hwd/ame/4/stallion.mp3"},"oxford":{"phon":"ˈstæliən","pos":"noun","senses":[{"en":"a fully grown male horse, especially one that is used for breeding (= producing young)","cn":"牡马；（尤指）种马"}]}},"stillborn":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"死产的;出生时已夭折的","en":"A stillborn baby is dead when it is born.","ex":{"en":"It was a miracle that she survived the birth of her stillborn baby","cn":"她生了死胎还能活下来，真是奇迹。"}},{"pos":"ADJ 形容词","cn":"完全无效的;完全失败的","en":"An idea, action, or attempt which is stillborn is completely ineffective or unsuccessful.","ex":{"en":"The ceasefire itself could prove stillborn if rebel units in the bush keep on fighting.","cn":"如果丛林地带的叛军继续开火，那停火协议本身就可能起不到任何作用。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a woman has a miscarriage the baby comes out of her body far too early for it to be able to live","cn":""},{"en":"a baby that is stillborn is born dead but fully developed","cn":""},{"en":"if a baby is born dead , it is not alive when it is born","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/stillborn0205.mp3","us":"media/ldoce/hwd/ame/4/stillborn.mp3"},"examples":[{"en":"a stillborn baby","cn":"死产儿"},{"en":"a stillborn romance","cn":"夭折的恋情"}],"oxford":{"phon":"ˈstɪlbɔːn","pos":"adjective","senses":[{"en":"born dead","cn":"死产的","ex":{"en":"a stillborn baby","cn":"死产儿"}},{"en":"not successful; not developing","cn":"失败的；夭折的","ex":{"en":"The proposal was stillborn.","cn":"该提议胎死腹中。"}}]}},"stagehand":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"舞台工作人员;后台工作人员","en":"A stagehand is a person whose job is to move the scenery and equipment on the stage in a theatre."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works on a theatre stage, getting it ready for a play or for the next part of a play","cn":"舞台工作人员"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41stagehand.mp3","us":"media/ldoce/hwd/ame/b/stagehand.mp3"},"oxford":{"phon":"ˈsteɪdʒhænd","pos":"noun","senses":[{"en":"a person whose job is to help move scenery, etc. in a theatre, to prepare the stage for the next play or the next part of a play","cn":"舞台工作人员（负责移动布景、准备道具等）"}]}},"straggly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)散乱的;(植物)蔓生的","en":"Straggly hair or a straggly plant is thin and grows or spreads out untidily in different directions.","ex":{"en":"Her long fair hair was knotted and straggly","cn":"她那长长的金发散乱而打缕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"growing untidily and spreading out in different directions","cn":"蔓延的﹔散落的﹔零乱的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/straggly0205.mp3","us":"media/ldoce/hwd/ame/d/straggly.mp3"},"examples":[{"en":"a thin woman with grey, straggly hair","cn":"灰发蓬乱的瘦女人"},{"en":"straggly hair","cn":"凌乱的头发"}],"oxford":{"phon":"ˈstræɡli","pos":"adjective","senses":[{"en":"growing or hanging in a way that does not look tidy or attractive","cn":"蔓生的；杂乱地蔓延的","ex":{"en":"She was a thin woman with straggly grey hair.","cn":"她身体瘦削，灰发蓬乱。"}}]}},"strong-willed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"意志坚强的;坚持己见的","en":"Someone who is strong-willed has a lot of determination and always tries to do what they want, even though other people may advise them not to.","ex":{"en":"He is a very determined and strong-willed person.","cn":"他是个有决心有毅力的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you are determined to do something, you have decided that you are definitely going to do it, and you will not let anything stop you. Determined is also used about someone’s character, when they usually behave in this way","cn":""},{"en":"determined not to change what you are doing, especially when other people think you are behaving in an unreasonable way. Stubborn is often used when you disapprove of someone. It is also sometimes used when you admire them","cn":""},{"en":"someone who is single-minded works very hard in order to achieve one particular thing, and thinks that everything else is much less important","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone strong-willed doesn’t give up easily. A strong-willed person is determined."}]},"media":{"uk":"media/ldoce/hwd/bre/9/strong_willed0205.mp3","us":"media/ldoce/hwd/ame/9/laadstrong-willed.mp3"},"oxford":{"phon":"ˌstrɒŋ ˈwɪld","pos":"adjective","senses":[{"en":"determined to do what you want to do, even if other people advise you not to","cn":"意志坚强的；坚持己见的","ex":{"en":"She was a fiercely independent and strong-willed woman.","cn":"她是个特别独立且意志坚强的女性。"}}]}},"steamroller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(蒸汽)压路机","en":"A steamroller is a large, heavy vehicle with wide, solid metal wheels, which is used to make the surface of a road flat. In the past steamrollers were powered by steam."},{"pos":"VERB 动词","cn":"(以权利、压力)迫使，逼迫，强行","en":"If you steamroller someone who disagrees with you or opposes you, you defeat them or you force them to do what you want by using your power or by putting a lot of pressure on them.","ex":{"en":"They could simply steamroller all opposition.","cn":"他们可以直接镇压所有反抗。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a heavy vehicle with very wide wheels that is driven over road surfaces to make them flat","cn":"蒸汽压路机"},{"en":"someone who uses their power and influence to make sure that something happens the way they want it to","cn":"以势压人者﹐使用高压手段者"},{"en":"to make sure something happens by using all your power and influence, or to defeat your opponents badly 〔","cn":"以权势和影响力〕强迫﹐迫使﹐使屈服﹐击垮"}]},"media":{"uk":"media/ldoce/hwd/bre/8/steamroller_v0205.mp3","us":"media/ldoce/hwd/ame/8/steamroller1.mp3"},"examples":[{"en":"The team steamrollered their way to victory.","cn":"这支队以不可阻挡之势获得胜利。"},{"en":"She knew that she'd let herself be steamrollered.","cn":"她知道自己会屈服于对方的威势。"}],"oxford":{"phon":"ˈstiːmrəʊlə(r)","pos":"noun","senses":[{"en":"a large slow vehicle with a heavy roller, used for making roads flat","cn":"蒸汽压路机"},{"en":"to defeat somebody or force them to do something, using your power or authority","cn":"（凭借力量或权威）打败，压服，迫使","ex":{"en":"The team steamrollered their way to victory.","cn":"这支队以不可阻挡之势获得胜利。"},"pos":"verb"}]}},"streetwalker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"街头拉客的妓女","en":"A streetwalker is a prostitute who stands or walks in the streets in order to get customers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a prostitute","cn":"娼妓﹐妓女"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41streetwalker.mp3","us":"media/ldoce/hwd/ame/9/streetwalker.mp3"},"oxford":{"phon":"ˈstriːtwɔːkə(r)","pos":"noun","senses":[{"en":"a person working as a prostitute who looks for customers on the streets","cn":"街头拉客的妓女"}]}},"stye":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"睑腺炎;麦粒肿","en":"If you have a stye, your eyelid is red and swollen because part of it is infected."}]}},"stimulant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"兴奋剂;引起兴奋的药物","en":"A stimulant is a drug that makes your body work faster, often increasing your heart rate and making you less likely to sleep."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug or substance that makes you feel more active and full of energy","cn":"兴奋剂[药]﹔引起兴奋的物质"},{"en":"something that encourages more of a particular activity","cn":"刺激（物）"}]},"vocab":{"pos":"n adj","senses":[{"en":"A stimulant is a drug that speeds up your body or an event that spurs you to action. Both types of stimulant get you going."}]},"media":{"uk":"media/ldoce/hwd/bre/8/stimulant0205.mp3","us":"media/ldoce/hwd/ame/b/stimulant.mp3"},"examples":[{"en":"Coffee and tea are mild stimulants.","cn":"咖啡和茶是轻度兴奋剂。"},{"en":"Increases in new construction would be a stimulant to the economy.","cn":"新建设项目的增加对经济可能是一种刺激。"}],"oxford":{"phon":"ˈstɪmjələnt","pos":"noun","senses":[{"en":"a drug or substance that makes you feel more active and gives you more energy","cn":"兴奋剂","ex":{"en":"Coffee and tea are mild stimulants.","cn":"咖啡和茶是轻度兴奋剂。"}},{"en":"an event or activity that encourages more activity","cn":"有激励作用的事物"}]}},"stagecraft":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"编剧艺术;戏剧导演艺术","en":"Stagecraft is skill in writing or producing or directing plays in the theatre."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"skill and experience in writing, or organizing the performance of, a play","cn":"编剧技巧﹔戏剧导演技巧"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stagecraft.mp3","us":"media/ldoce/hwd/ame/6/laadstagecraft.mp3"},"oxford":{"phon":"ˈsteɪdʒkrɑːft","pos":"noun","senses":[{"en":"skill in presenting plays in a theatre","cn":"舞台表演技巧；剧场表演艺术"}]}},"stenographer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"速记员","en":"A stenographer is a person who types and writes shorthand, usually in an office."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to write down what someone else is saying, using stenography, and then type a copy of it","cn":"速记员"}]},"vocab":{"pos":"n","senses":[{"en":"A stenographer is someone who types what people say. You have to listen carefully and type very fast to be a stenographer ."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41stenographer.mp3","us":"media/ldoce/hwd/ame/3/stenographer.mp3"},"oxford":{"phon":"stəˈnɒɡrəfə(r)","pos":"noun","senses":[{"en":"a person whose job is to write down what somebody else says, using a quick system of signs or abbreviations","cn":"速记员"}]}},"stoker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指旧时船上或蒸汽火车上的)添煤工，司炉","en":"In former times a stoker was a person whose job was to stoke fires, especially on a ship or a steam train."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to put coal or other fuel on a fire or into a furnace , for example on a steamship or a steam train","cn":"烧火工﹐司炉"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41stoker.mp3","us":"media/ldoce/hwd/ame/b/stoker.mp3"},"oxford":{"phon":"ˈstəʊkə(r)","pos":"noun","senses":[{"en":"a person whose job is to add coal or other fuel to a fire, etc., especially on a ship or a steam train","cn":"（尤指轮船或蒸汽机车上的）司炉"}]}},"stodgy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)硬实的，难消化的，使人胀饱的","en":"Stodgy food is very solid and heavy. It makes you feel very full, and is difficult to digest.","ex":{"en":"He was disgusted with the stodgy pizzas on sale in London.","cn":"他讨厌吃伦敦卖的难以下咽的比萨饼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"古板的;令人厌烦的;枯燥乏味的","en":"If you describe someone or something as stodgy, you dislike them or are bored by them because they are very old-fashioned or serious.","ex":{"en":"They're not cultured or interesting, they are boring stodgy old things.","cn":"他们没修养，很乏味，是一群无聊古板的老家伙。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"food that is filling makes your stomach feel full very quickly, especially when it does not look as though it will","cn":""},{"en":"food that is stodgy makes you feel full, is bad for your health, and usually has very little taste","cn":""},{"en":"food that is heavy makes your stomach feel full and you can feel it lying in your stomach for a long time after you have eaten it","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The Queen's guards outside Buckingham Palace might seem stodgy (or stuffy and stuck-up), but they are only doing their job."}]},"media":{"uk":"media/ldoce/hwd/bre/3/stodgy0205.mp3","us":"media/ldoce/hwd/ame/c/stodgy.mp3"},"examples":[{"en":"a stodgy play","cn":"枯燥无味的戏剧"}],"oxford":{"phon":"ˈstɒdʒi","pos":"adjective","senses":[{"en":"heavy and making you feel very full","cn":"吃下去感觉撑的；易饱的","ex":{"en":"stodgy puddings","cn":"稠厚的布丁"}},{"en":"serious and boring; not exciting","cn":"滞涩的；古板的；枯燥无味的","ex":{"en":"The article was rather stodgy—too many facts.","cn":"这篇文章相当乏味——事实太多。"}}]}},"strong-minded":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指女性)意志坚强的，果断的，有主见的","en":"If you describe someone, especially a woman, as strong-minded, you approve of them because they have their own firm attitudes and opinions, and are not easily influenced by other people.","ex":{"en":"She is a strong-minded, independent woman.","cn":"她是一个独立、有主见的女人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easily influenced by other people to change what you believe or want","cn":"意志坚强的﹐果断的﹐坚定的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41strong-minded.mp3","us":"media/ldoce/hwd/ame/c/strong-minded.mp3"},"examples":[{"en":"They were both strong-minded women.","cn":"她们两个都是意志坚强的女人。"}],"oxford":{"phon":"ˌstrɒŋ ˈmaɪndɪd","pos":"adjective","senses":[{"en":"having strong opinions that are not easily influenced by what other people think or say","cn":"有主见的；坚持己见的","ex":{"en":"My mother was a very strong-minded woman who always got her own way.","cn":"我的母亲是一个意志坚强的女人，她总是按自己的意愿行事。"}}]}},"stilted":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(言谈)呆板的，生硬的，不自然的","en":"If someone speaks in a stilted way, they speak in a formal or unnatural way, for example because they are not relaxed.","ex":{"en":"We made polite, stilted conversation","cn":"我们客套了一番。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a stilted style of writing or speaking is formal and unnatural 〔","cn":"文体﹑言谈〕呆板的﹐生硬的﹐不自然的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective stilted describes something—usually a style of writing or speaking—that is unnaturally formal. It also refers to something raised on stilts , such as some lake houses that are stilted , or resting on stilts over the water."}]},"media":{"uk":"media/ldoce/hwd/bre/3/stilted0205.mp3","us":"media/ldoce/hwd/ame/d/stilted.mp3"},"examples":[{"en":"We made stilted conversation for a few moments.","cn":"我们不自然地客套了几句。"},{"en":"a stilted conversation","cn":"生硬的对话"}],"oxford":{"phon":"ˈstɪltɪd","pos":"adjective","senses":[{"en":"not natural or relaxed; too formal","cn":"生硬的；不自然的","ex":{"en":"We made stilted conversation for a few moments.","cn":"我们不自然地客套了一会儿。"}}]}},"stolid":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷漠的;感情不外露的;无趣的","en":"If you describe someone as stolid, you mean that they do not show much emotion or are not very exciting or interesting.","ex":{"en":"He glanced furtively at the stolid faces of the two detectives.","cn":"他偷偷地瞄了一下两名侦探面无表情的脸孔。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is stolid does not react to situations or seem excited by them when most people would react – used to show disapproval","cn":"不易激动的﹔麻木不仁的﹔无动于衷的〔含贬义〕"}]},"vocab":{"pos":"adj","senses":[{"en":"A stolid person can’t be moved to smile or show much sign of life, in much the same way as something solid, like a giant boulder, is immovable. Both are expressionless."}]},"media":{"uk":"media/ldoce/hwd/bre/1/stolid0205.mp3","us":"media/ldoce/hwd/ame/0/stolid.mp3"},"oxford":{"phon":"ˈstɒlɪd","pos":"adjective","senses":[{"en":"not showing much emotion or interest; remaining always the same and not reacting or changing","cn":"不动感情的；不关心的；淡漠的；无动于衷的","ex":{"en":"Mark sat stolid and silent.","cn":"马克冷漠地坐着，一言不发。"}}]}},"stethoscope":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"听诊器","en":"A stethoscope is an instrument that a doctor uses to listen to your heart and breathing. It consists of a small disc that is placed on your body, connected to a hollow tube with two pieces that the doctor puts in his or her ears."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument that a doctor uses to listen to your heart or breathing","cn":"听诊器"}]},"media":{"img":["media/ldoce/img/stethoscope.jpg"],"uk":"media/ldoce/hwd/bre/0/stethoscope0205.mp3","us":"media/ldoce/hwd/ame/a/stethoscope.mp3"},"oxford":{"phon":"ˈsteθəskəʊp","pos":"noun","senses":[{"en":"an instrument that a doctor uses to listen to somebody’s heart and breathing","cn":"听诊器"}]}},"starve":{"collins":{"senses":[{"pos":"VERB 动词","cn":"挨饿;饿死","en":"If people starve, they suffer greatly from lack of food which sometimes leads to their death.","ex":{"en":"A number of the prisoners we saw are starving","cn":"我们看到的一些囚犯快要饿死了。"}},{"pos":"VERB 动词","cn":"使挨饿","en":"To starve someone means not to give them any food.","ex":{"en":"He said the only alternative was to starve the people, and he said this could not be allowed to happen","cn":"他说唯一的其他选择就是让人们挨饿，又说这是绝对不允许发生的。"}},{"pos":"VERB 动词","cn":"使极其缺乏;使迫切需要","en":"If a person or thing is starved of something that they need, they are suffering because they are not getting enough of it.","ex":{"en":"The electricity industry is not the only one to have been starved of investment","cn":"投资严重缺乏的不光是电力工业。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not have enough money to do something","cn":""},{"en":"to not have enough of something that is necessary, such as money or food","cn":""},{"en":"to have less than you should have of a useful or important quality","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"The verb starve means suffering or death caused by a lack of food, though people also use it as a dramatic way to say they are hungry, as in, \"If we don't start cooking dinner now, I think I'll starve .\""}]},"collocations":{"phrases":["ADV. literally She refused food and literally starved herself to death.","VERB + STARVE leave sb to He locked them in and left them to starve.","PHRASES be half starved The poor cat was half starved. | starve to death"]},"media":{"uk":"media/ldoce/hwd/bre/1/starve0205.mp3","us":"media/ldoce/hwd/ame/0/starve.mp3"},"examples":[{"en":"The new job doesn't pay as much but we won't starve!","cn":"新工作的工资没有过去多，不过我们不至于挨饿！"},{"en":"I felt starved of intelligent conversation.","cn":"让我感到痛苦的是无法与有识之士交谈。"}],"oxford":{"phon":"stɑːv","pos":"verb","senses":[{"en":"to suffer or die because you do not have enough food to eat; to make somebody suffer or die in this way","cn":"（使）挨饿，饿死","g":"[intransitive, transitive]","ex":{"en":"The animals were left to starve to death.","cn":"那些动物只能等着饿死。"}},{"en":"not having something that you need","cn":"缺乏…的；急需…的","ex":{"en":"supply-starved rebels","cn":"补给匮乏的反叛者"}}]}},"storybook":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"儿童故事书;童话书","en":"A storybook is a book of stories for children.","ex":{"en":"As a child she learned to draw by tracing pictures out of her mother's old storybooks.","cn":"小时候她通过描摹母亲旧童话书里的插图学会了画画。"}},{"pos":"ADJ 形容词","cn":"童话般美好的;结局圆满的;皆大欢喜的","en":"A storybook relationship, situation, or life is one that is perfect and ends happily, just as many fairy stories do.","ex":{"en":"In many ways it was a storybook life. Summers in Salzburg. Weekends hunting in Connecticut","cn":"在很多方面，这都是种童话般的生活。夏天在萨尔茨堡度过。周末在康涅狄格打猎。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book of stories for children 〔","cn":"为儿童编写的〕故事书"},{"en":"an ending etc that is so happy or perfect that it is like one in a children’s story","cn":"童话式的结局/浪漫史等"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41storybook2.mp3","us":"media/ldoce/hwd/ame/e/storybook.mp3"},"examples":[{"en":"storybook adventures (= like the ones in stories for children)","cn":"故事书里那种神奇的历险"},{"en":"a picture in a storybook","cn":"故事书中的插图"}],"oxford":{"phon":"ˈstɔːribʊk","pos":"noun","senses":[{"en":"a book of stories for children","cn":"儿童故事书；童话书","ex":{"en":"a picture in a storybook","cn":"故事书中的插图"}}]}},"steamboat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(蒸)汽(机)船，汽艇","en":"A steamboat is a boat or ship that has an engine powered by steam."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a boat that uses steam for power and is sailed along rivers and coasts","cn":"汽船﹐汽艇"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41steamboat.mp3","us":"media/ldoce/hwd/ame/6/steamboat.mp3"},"oxford":{"phon":"ˈstiːmbəʊt","pos":"noun","senses":[{"en":"a boat driven by steam, used especially in the past on rivers and along coasts","cn":"汽船；轮船"}]}},"stipendiary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(地方法官或神职人员)领薪金的，有生活津贴的","en":"A stipendiary magistrate or member of the clergy receives a stipend."}]},"oxford":{"phon":"staɪˈpendiəri","pos":"noun","senses":[{"en":"(in the UK) a magistrate who was paid for his or her work","cn":"（英国）受薪治安法官"}]}},"stumpy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"短而粗的","en":"Stumpy things are short and thick.","ex":{"en":"Does this dress make my legs look too stumpy?","cn":"这条裙子会使我的腿看上去又短又粗吗?"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is short , there is only a small length or distance from one end of it to the other","cn":""},{"en":"body parts that are stubby or stumpy are short and thick","cn":""},{"en":"stumpy legs, fingers etc are short and thick in an unattractive way 〔","cn":"腿﹑手指等〕粗短的﹐敦实的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41stumpy.mp3","us":"media/ldoce/hwd/ame/7/stumpy.mp3"},"examples":[{"en":"stumpy fingers","cn":"又短又粗的手指"},{"en":"a stumpy tail","cn":"短而粗的尾巴"}],"oxford":{"phon":"ˈstʌmpi","pos":"adjective","senses":[{"en":"short and thick","cn":"短而粗的","ex":{"en":"stumpy fingers","cn":"又短又粗的手指"}}]}},"standoffish":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冷漠的;冷淡的;疏远的","en":"If you say that someone is stand-offish, you mean that they behave in a formal and rather unfriendly way.","ex":{"en":"He can be quite stand-offish and rude, even to his friends.","cn":"他有时会很冷淡，很粗鲁，甚至对自己的朋友也是如此。"}}]}},"stratum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"社会阶层","en":"A stratum of society is a group of people in it who are similar in their education, income, or social status.","ex":{"en":"It was an enormous task that affected every stratum of society","cn":"这是一项影响到社会各阶层的重大工作。"}},{"pos":"N-COUNT 可数名词","cn":"岩层","en":"Strata are different layers of rock.","ex":{"en":"Contained within the rock strata is evidence that the region was intensely dry 15,000 years ago.","cn":"岩层中有证据表明，该地区在 15,000 年前曾经非常干旱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a layer of rock or earth","cn":"岩层﹔地层"},{"en":"a social class in a society","cn":"社会阶层"}]},"vocab":{"pos":"n","senses":[{"en":"A stratum is a layer of something, whether abstract, like a social stratum composed of only billionaires, or physical, like the different strata (that’s the plural version) of clouds that an airplane passes through."}]},"media":{"uk":"media/ldoce/hwd/bre/1/stratum0205.mp3","us":"media/ldoce/hwd/ame/5/stratum.mp3"},"examples":[{"en":"people from all social strata","cn":"来自不同社会阶层的人"},{"en":"people of different social strata","cn":"各个社会阶层的人"}],"oxford":{"phon":"ˈstrɑːtəm","pos":"noun","senses":[{"en":"a layer or set of layers of rock, earth, etc.","cn":"层；岩层；地层","lab":"geology","ex":{"en":"a thick stratum of flint","cn":"厚厚的燧石层"}},{"en":"a class in a society","cn":"阶层","lab":"formal","ex":{"en":"people from all social strata","cn":"来自不同社会阶层的人"}}]}},"stubbly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"胡子拉碴的","en":"If a man has not shaved recently, he has a stubbly chin.","ex":{"en":"He had long unkempt hair and a stubbly chin.","cn":"他的头发又长又乱，脸上胡子拉碴。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"short stiff hairs that grow on a man’s face if he does not shave","cn":""},{"en":"short stiff pieces left in the fields after wheat, corn etc has been cut","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/stubble0205.mp3","us":"media/ldoce/hwd/ame/7/stubble.mp3"},"oxford":{"phon":"ˈstʌbli","pos":"adjective","senses":[{"en":"covered with or consisting of stubble (= the short stiff hairs that grow on a man's face when he has not shaved recently)","cn":"胡子茬","ex":{"en":"a stubbly chin/beard","cn":"下巴胡茬/胡须"}}]}},"stopwatch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(计时用的)跑表，秒表","en":"A stopwatch is a watch with buttons which you press at the beginning and end of an event, so that you can measure exactly how long it takes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a watch used for measuring the exact time it takes to do something, especially to finish a race 〔","cn":"尤用于竞速赛的〕秒表﹐跑表"}]},"media":{"img":["media/ldoce/img/stopwatch.jpg"],"uk":"media/ldoce/hwd/bre/a/stopwatch0205.mp3","us":"media/ldoce/hwd/ame/a/stopwatch.mp3"},"oxford":{"phon":"ˈstɒpwɒtʃ","pos":"noun","senses":[{"en":"a watch that you can stop and start by pressing buttons, in order to time a race, etc. accurately, or an app on a phone that can perform the same function","cn":"（赛跑等计时用的）秒表，跑表；（手机）秒表应用程序"}]}},"stateless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无国籍的","en":"A person who is stateless is not a citizen of any country and therefore has no nationality.","ex":{"en":"If I went back I'd be a stateless person","cn":"如果我回去，我就是个没有国籍的人了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not officially being a citizen of any country","cn":"无国籍的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41stateless.mp3","us":"media/ldoce/hwd/ame/9/stateless.mp3"},"examples":[{"en":"Millions of refugees remain stateless.","cn":"数百万难民仍未取得国籍。"}],"oxford":{"phon":"ˈsteɪtləs","pos":"adjective","senses":[{"en":"not officially a citizen of any country","cn":"无国籍的","ex":{"en":"The children of illegal immigrants will in many cases be born stateless.","cn":"在许多情况下，非法移民的孩子一出生就没有国籍。"}}]}},"stab":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(用刀等锋利物)刺，戳，捅","en":"If someone stabs you, they push a knife or sharp object into your body.","ex":{"en":"Somebody stabbed him in the stomach","cn":"有人朝他肚子上捅了一刀。"}},{"pos":"VERB 动词","cn":"(用手指或手中的尖物)戳，捅","en":"If you stab something or stab at it, you push at it with your finger or with something pointed that you are holding.","ex":{"en":"Bess stabbed a slice of cucumber","cn":"贝丝叉起一片黄瓜。"}},{"pos":"N-SING 单数名词","cn":"尝试;试图","en":"If you have a stab at something, you try to do it.","ex":{"en":"Several tennis stars have had a stab at acting.","cn":"好几位网球明星都尝试过从事演艺。"}},{"pos":"N-SING 单数名词","cn":"(通常指令人不快的感觉的)突发的一阵","en":"You can refer to a sudden, usually unpleasant feeling as a stab of that feeling.","ex":{"en":"...a stab of pain just above his eye","cn":"他眼睛上方突然的一阵疼痛"}},{"pos":"PHRASE 短语","cn":"背后捅刀子;暗地中伤","en":"If you say that someone has stabbed you in the back, you mean that they have done something very harmful to you when you thought that you could trust them. You can refer to an action of this kind as a stab in the back .","ex":{"en":"She felt betrayed, as though her daughter had stabbed her in the back","cn":"她感到被出卖了，就像女儿在自己背后捅了一刀似的。"}},{"pos":"","cn":"","en":"a stab in the dark→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use violence against someone and try to hurt them","cn":""},{"en":"if a group of people ambush someone, they hide and wait for them and then attack them","cn":""},{"en":"to attack someone and take money from them in a public place such as a street","cn":""}]},"collocations":{"phrases":["ADV. repeatedly He is accused of repeatedly stabbing a sixteen-year-old boy.","VERB + STAB threaten to | try to","PREP. at, in He was stabbed in the chest. | with I stabbed at my meat with my fork.","PHRASES be found stabbed He was found stabbed in his car. | stab sb to death"]},"media":{"uk":"media/ldoce/hwd/bre/b/stab_n0205.mp3","us":"media/ldoce/hwd/ame/8/stab1.mp3"},"examples":[{"en":"He found the test difficult but nevertheless made a good stab at it.","cn":"尽管他觉得试题很难，但还是尽力去做了。"},{"en":"He was stabbed to death in a racist attack.","cn":"他遭到种族主义者的袭击，被刺死了。"}],"oxford":{"phon":"stæb","pos":"verb","senses":[{"en":"to push a sharp, pointed object, especially a knife, into somebody, killing or injuring them","cn":"（用刀等锐器）刺，戳，捅","g":"[transitive]","ex":{"en":"He was stabbed to death in a racist attack.","cn":"他遭到种族主义者的袭击，被刺死了。"}},{"en":"to make a short, aggressive or violent movement with a finger or pointed object","cn":"（用手指或尖物）戳，捅，刺","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"He stabbed his finger angrily at my chest.","cn":"他气呼呼地用指头戳我的胸口。"}},{"en":"an act of stabbing or trying to stab somebody/something; a wound caused by stabbing","cn":"刺；戳；捅；刺（或戳、捅）的伤口","ex":{"en":"He received several stabs in the chest.","cn":"他胸部被刺了几刀。"},"pos":"noun"},{"en":"a sudden sharp pain or unpleasant feeling","cn":"突然一阵剧痛（或难受的感觉）","ex":{"en":"She felt a sudden stab of pain in the chest.","cn":"她胸部突然感到一阵剧痛。"},"pos":"noun"},{"en":"an attempt to do something","cn":"尝试；企图","g":"[usually singular]","lab":"informal","ex":{"en":"He found the test difficult but nevertheless made a good stab at it.","cn":"尽管他觉得试题很难，但还是尽力去做了。"},"pos":"noun"}]}},"stonework":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"石方工程;砌石工程;(建筑物的)石造部分","en":"Stonework consists of objects or parts of a building that are made of stone.","ex":{"en":"...the crumbling stonework of the derelict church.","cn":"废弃教堂摇摇欲坠的石结构"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the parts of a building that are made of stone 〔","cn":"建筑物的〕石制部分"}]},"media":{"uk":"media/ldoce/hwd/bre/5/stonework0205.mp3","us":"media/ldoce/hwd/ame/d/stonework.mp3"},"oxford":{"phon":"ˈstəʊnwɜːk","pos":"noun","senses":[{"en":"the parts of a building that are made of stone","cn":"（建筑物的）石造部分","ex":{"en":"the crumbling stonework of the castle","cn":"城堡摇摇欲坠的石雕"}}]}},"stung":{"collins":{"senses":[{"pos":"","cn":"","en":"Stung is the past tense and past participle of sting."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the past tense and past participle of sting 1 sting","cn":"的过去式和过去分词"}]},"media":{"uk":"media/ldoce/hwd/bre/8/stung0205.mp3","us":"media/ldoce/hwd/ame/5/ld41stung.mp3"}},"storehouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常指储存食物的)仓库，栈房","en":"A storehouse is a building in which things, usually food, are stored.","ex":{"en":"Some of the cottages were still lived in by old folk; others had been turned into barns and storehouses.","cn":"有些村舍里仍住着老人;有些已经改作粮仓和仓库。"}},{"pos":"N-COUNT 可数名词","cn":"宝库;宝藏","en":"When a lot of things can be found together in one place, you can refer to this place as a storehouse of a particular kind.","ex":{"en":"This book is a veritable storehouse of information","cn":"这本书是名副其实的信息宝库。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that contains a lot of information etc","cn":"信息/记忆等的宝库"},{"en":"a building where things are stored","cn":"仓库﹐栈房"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41storehouse.mp3","us":"media/ldoce/hwd/ame/c/storehouse.mp3"},"examples":[{"en":"The local archives service offers a storehouse of material.","cn":"当地的档案馆提供大量的资料。"}],"oxford":{"phon":"ˈstɔːhaʊs","pos":"noun","senses":[{"en":"a building where things are stored","cn":"仓库；货栈","ex":{"en":"This product must not get wet and should be stored in big, dry storehouses.","cn":"本品不得受潮，应贮存在大而干燥的库房内。"}},{"en":"a place or thing that has or contains a lot of information","cn":"（信息或知识等的）宝库","ex":{"en":"This book is a storehouse of useful information.","cn":"本书载有大量有用的信息。"}}]}},"stiff-necked":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"傲慢而顽固的;倔强的;犟的","en":"If you say that someone is stiff-necked, you mean that they are proud and unwilling to do what other people want."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too proud, and refusing to change or obey","cn":"顽固而傲慢的﹐倔强的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41stiff-necked.mp3","us":"media/ldoce/hwd/ame/a/stiff-necked.mp3"},"oxford":{"phon":"ˌstɪf ˈnekt","pos":"adjective","senses":[{"en":"proud and refusing to change","cn":"固执的；倔强的；犟的"}]}},"stockpile":{"collins":{"senses":[{"pos":"VERB 动词","cn":"大量贮备，囤积(食品或武器)","en":"If people stockpile things such as food or weapons, they store large quantities of them for future use.","ex":{"en":"People are stockpiling food for the coming winter.","cn":"人们正在为即将到来的冬天贮备大量食物。"}},{"pos":"N-COUNT 可数名词","cn":"大量的储备;囤积","en":"A stockpile of things is a large quantity of them that have been stored for future use.","ex":{"en":"The two leaders also approved treaties to cut stockpiles of chemical weapons.","cn":"两位领导人还同意签署削减化学武器储备的几项条约。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large supply of things that is kept ready for use in the future 〔","cn":"大量的〕储备物资"},{"en":"to keep adding to a supply of goods, weapons etc that you are keeping ready to use if you need them in the future","cn":"贮存﹐积聚〔物资﹑武器等〕"}]},"vocab":{"pos":"n v","senses":[{"en":"A stockpile is a large amount of something that you save for later. If you're worried about running out of your favorite flavor of bubble gum, you might decide to keep a stockpile of it."}]},"media":{"uk":"media/ldoce/hwd/bre/5/stockpile_n0205.mp3","us":"media/ldoce/hwd/ame/4/stockpile1.mp3"},"examples":[{"en":"the world's stockpile of nuclear weapons","cn":"全世界的核武器储备"},{"en":"An enormous volume of explosives was stockpiled inside one of the buildings.","cn":"其中一栋大楼内贮存了大量的炸药。"}],"oxford":{"phon":"ˈstɒkpaɪl","pos":"noun","senses":[{"en":"a large supply of something that is kept to be used in the future if necessary","cn":"囤聚的物资","ex":{"en":"How large is the world's stockpile of nuclear weapons?","cn":"全球核武器库存有多少？"}},{"en":"to collect and keep a large supply of something","cn":"大量储备","ex":{"en":"to stockpile food","cn":"储存食物"},"pos":"verb"}]}},"stone-cold":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"冰冷的;凉透的","en":"If something that should be warm is stone-cold, it is very cold.","ex":{"en":"Hillsden took a sip of tea, but it was stone cold.","cn":"希尔斯登啜了一口茶，但茶是冰冷的。"}},{"pos":"PHRASE 短语","cn":"滴酒未沾的;完全清醒的","en":"If someone is stone-cold sober, they are not drunk at all."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is stone-cold, it is completely cold even though it should be warm or hot","cn":"冰冷的﹐完全凉的"},{"en":"having drunk no alcohol at all","cn":"完全清醒的﹐滴酒未沾的"},{"en":"if a player or sports team is stone-cold, they are not able to get any points 〔","cn":"选手或运动队〕一分未得的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41stone-cold.mp3","us":"media/ldoce/hwd/ame/b/stone-cold.mp3"},"examples":[{"en":"Dinner was stone-cold by the time I got home.","cn":"我到家时﹐晚饭已经完全凉了。"}],"oxford":{"phon":"ˌstəʊn ˈkəʊld","pos":"adjective","senses":[{"en":"completely cold, when it should be warm or hot","cn":"冰凉的；凉透的","ex":{"en":"The soup was stone cold.","cn":"汤全凉了。"}}]}},"strangled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(说话声、哭声)哽塞的，哽咽的，顿住的","en":"A strangled voice or cry sounds unclear because the throat muscles of the person speaking or crying are tight.","ex":{"en":"In a strangled voice he said, 'This place is going to be unthinkable without you.'","cn":"他哽咽地说道：“没有你这个地方会变得不可想象。”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a cry or other sound that is suddenly stopped before it is finished","cn":"突然止住的喊叫/喘息/说话声等"}]},"media":{"uk":"media/ldoce/hwd/bre/7/strangled0205.mp3","us":"media/ldoce/hwd/ame/0/laadstrangled.mp3"},"examples":[{"en":"There was a strangled cry from the other room.","cn":"隔壁传来一声哽咽。"},{"en":"Ed gave a strangled cry.","cn":"埃德刚喊了一声便顿住了。"}],"oxford":{"phon":"ˈstræŋɡld","pos":"adjective","senses":[{"en":"not clear because it stops before it has completely finished","cn":"哽塞的；哽咽的；顿住的","ex":{"en":"There was a strangled cry from the other room.","cn":"隔壁传来一声哽咽。"}}]}},"studiously":{"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"刻意地;小心地;成心地","en":"If you do something studiously, you do it carefully and deliberately.","ex":{"en":"When I looked at Clive, he studiously avoided my eyes.","cn":"当我朝克莱夫看去时，他刻意地避开了我的目光。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who wants to work all the time and who cannot relax when they are not working","cn":""},{"en":"someone who is industrious works hard and effectively","cn":""},{"en":"someone who is dedicated works very hard at something because they care about it a lot, even though the job is difficult or does not earn them much money","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/studious0205.mp3","us":"media/ldoce/hwd/ame/f/studious.mp3"},"examples":[{"en":"He studiously avoided answering the question.","cn":"他刻意不去回答那个问题。"},{"en":"a quiet, studious young man","cn":""}],"oxford":{"phon":"ˈstjuːdiəsli","pos":"adverb","senses":[{"en":"in a way that is carefully planned and deliberate","cn":"刻意地；成心","ex":{"en":"He studiously avoided answering the question.","cn":"他刻意不去回答那个问题。"}}]}},"straightaway":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"at once","cn":"立即﹐立刻﹐马上"},{"en":"the straight part of a racetrack 〔","cn":"跑道的〕直道（部分）"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld44straightaway.mp3","us":"media/ldoce/hwd/ame/e/l3straightaway.mp3"},"examples":[{"en":"We need to start work straightaway.","cn":"我们得马上开始工作。"}],"oxford":{"phon":"ˌstreɪtəˈweɪ","pos":"adverb","senses":[{"en":"immediately; without delay","cn":"立即；马上"},{"en":"a straight part of a racetrack or road","cn":"直道部分；直道","pos":"noun"}]}},"stiffen":{"collins":{"senses":[{"pos":"VERB 动词","cn":"变得僵硬;变得紧张;绷紧","en":"If you stiffen, you stop moving and stand or sit with muscles that are suddenly tense, for example because you feel afraid or angry.","ex":{"en":"Ada stiffened at the sound of his voice","cn":"埃达听到他的声音吓得人都僵住了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(肌肉或关节)变得僵硬;(使)变得不易弯曲;(使)变得不灵活","en":"If your muscles or joints stiffen, or if something stiffens them, they become difficult to bend or move.","ex":{"en":"The blood supply to the skin is reduced when muscles stiffen.","cn":"当肌肉变得僵硬时，皮肤的供血量就减少了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(态度或行为)变得更强硬，变得更严厉;(使)变得更坚定","en":"If attitudes or behaviour stiffen, or if something stiffens them, they become stronger or more severe, and less likely to be changed.","ex":{"en":"Russian resistance suddenly stiffened because there was no room for retreat","cn":"俄罗斯的反抗突然变得强硬起来，因为已经没有退路了。"}},{"pos":"VERB 动词","cn":"使(布料等)变挺;使变硬","en":"If something such as cloth is stiffened, it is made firm so that it does not bend easily.","ex":{"en":"This special paper was actually thin, soft Sugiwara paper that had been stiffened with a kind of paste","cn":"这种特殊的纸实际是一种糨糊浆过的又薄又软的杉原纸。"}},{"pos":"","cn":"","en":"相关词组：stiffen up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a liquid such as melted metal or wax solidifies , it becomes hard","cn":""},{"en":"if a liquid substance sets , it becomes harder - use this to talk about something that slowly becomes harder after it is mixed with water, for example, food or building materials","cn":""},{"en":"if a liquid freezes , it becomes hard because it has become very cold","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/stiffen0205.mp3","us":"media/ldoce/hwd/ame/2/stiffen.mp3"},"examples":[{"en":"The threat of punishment has only stiffened their resolve (= made them even more determined to do sth).","cn":"惩罚的威胁益发坚定了他们的决心。"},{"en":"My muscles had stiffened up after the climb.","cn":"爬上去以后我两腿都发僵了。"}],"oxford":{"phon":"ˈstɪfn","pos":"verb","senses":[{"en":"to make yourself or part of your body straight and still, especially because you are angry or frightened","cn":"（使身体部位）变僵硬，变僵直，绷紧（尤指因气愤或害怕）","g":"[intransitive, transitive]","ex":{"en":"She stiffened with fear.","cn":"她吓呆了。"}},{"en":"to become, or to make something become, difficult to bend or move","cn":"（使）难以弯曲，难以活动，发僵","g":"[intransitive, transitive]","ex":{"en":"My muscles had stiffened up after the climb.","cn":"爬上去以后我肌肉都发僵了。"}},{"en":"to make an attitude or idea stronger or more powerful; to become stronger","cn":"（使）变强硬，变坚定","g":"[transitive, intransitive]","ex":{"en":"The threat of punishment has only stiffened their resolve (= made them even more determined to do something).","cn":"惩罚的威胁益发坚定了他们的决心。"}},{"en":"to make something, such as cloth, hard and unable to bend","cn":"使硬挺","g":"[transitive]"}]}},"stepdaughter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继女","en":"Someone's step-daughter is a daughter that was born to their husband or wife during a previous relationship."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a daughter that your husband or wife has from a relationship before your marriage","cn":"继女"}]},"media":{"uk":"media/ldoce/hwd/bre/a/stepdaughter0205.mp3","us":"media/ldoce/hwd/ame/7/stepdaughter.mp3"},"oxford":{"phon":"ˈstepdɔːtə(r)","pos":"noun","senses":[{"en":"a daughter that your husband or wife has from an earlier marriage or relationship with another person","cn":"继女"}]}},"starlet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"未来的女电影明星;女影坛新秀","en":"A starlet is a young actress who is expected to become a film star in the future."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a young actress who plays small parts in films and hopes to become famous","cn":"尚未成名的年轻女演员，小明星"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41starlet.mp3","us":"media/ldoce/hwd/ame/2/starlet.mp3"},"oxford":{"phon":"ˈstɑːlət","pos":"noun","senses":[{"en":"a young woman actor hoping to become famous","cn":"渴望成名的年轻女演员","ex":{"en":"Hollywood starlets of the 1940s","cn":"20 世纪 40 年代好莱坞那些渴望成名的年轻女演员"}}]}},"stowage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(船、飞机上的)装载空间","en":"Stowage is the space that is available for stowing things on a ship or aeroplane.","ex":{"en":"Stowage is provided in lined lockers beneath the berths.","cn":"铺位下方有成排的储物柜可以存放东西。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"space available in a vehicle, especially a boat, for storing things 〔","cn":"尤指船舶的〕装载空间"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41stowage.mp3","us":"media/ldoce/hwd/ame/d/stowage.mp3"},"oxford":{"phon":"ˈstəʊɪdʒ","pos":"noun","senses":[{"en":"space provided for stowing things away, in a boat or a plane","cn":"（船或飞机上）存放物品处"}]}},"standpoint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"角度;立场;立足点","en":"From a particular standpoint means looking at an event, situation, or idea in a particular way.","ex":{"en":"He believes that from a military standpoint, the situation is under control","cn":"他认为从军事角度看，形势已得到了控制。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"what you think about something, especially when this is influenced by the situation you are in","cn":""},{"en":"a particular way of thinking about a problem or subject","cn":""},{"en":"a particular way of thinking about something, especially of someone who is involved in a situation or who has to make a professional judgment about it","cn":""}]},"collocations":{"phrases":["ADJ. different We must approach the problem from a different standpoint. | positive | practical | ideological, theoretical | economic, histo","VERB + STANDPOINT adopt We should try to adopt a more positive standpoint. | approach sth from, view sth from","PREP. from a/the ~ (of) From the standpoint of women, this looks like a policy of discrimination."]},"media":{"uk":"media/ldoce/hwd/bre/6/standpoint0205.mp3","us":"media/ldoce/hwd/ame/d/standpoint.mp3"},"examples":[{"en":"He is writing from the standpoint of someone who knows what life is like in prison.","cn":"他从一个了解监狱生活的人的立场写作。"},{"en":"a political/theoretical, etc. standpoint","cn":"政治、理论等观点"}],"oxford":{"phon":"ˈstændpɔɪnt","pos":"noun","senses":[{"en":"an opinion or a way of thinking about ideas or situations","cn":"立场；观点","ex":{"en":"a political/theoretical standpoint","cn":"政治／理论观点"}}]}},"strangely":{"collins":{"senses":[{"pos":"ADV 副词","cn":"(表示强调)奇怪地，异常地，不可思议地","en":"You use strangely to emphasize that what you are saying is surprising.","ex":{"en":"Strangely, the race didn't start until 8.15pm","cn":"很奇怪，赛跑直到晚上 8 点 15 分才开始。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in a way that is very different from what you expect or from what usually happens, so that you feel a little frightened or surprised","cn":""},{"en":"if something happens as if by magic , it happens in a sudden and surprising way that seems impossible to explain","cn":""},{"en":"in an unusual or surprising way","cn":"奇怪地﹐不寻常地"}]},"media":{"uk":"media/ldoce/hwd/bre/1/strangely0205.mp3","us":"media/ldoce/hwd/ame/c/laadstrangely.mp3"},"examples":[{"en":"Strangely enough, I don't feel at all nervous.","cn":"真奇怪，我一点也不紧张。"},{"en":"She's been acting very strangely lately.","cn":"近来她举止十分反常。"}],"oxford":{"phon":"ˈstreɪndʒli","pos":"adverb","senses":[{"en":"in an unusual or surprising way","cn":"异常地；奇怪地；不可思议地","ex":{"en":"She's been acting very strangely lately.","cn":"近来她举止十分反常。"}}]}},"stockist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"零售商;经销商","en":"A stockist of a particular product is someone who sells this product in their shop.","ex":{"en":"The name of your nearest stockist is available from the company.","cn":"从公司可以查到离你最近的零售商的名字。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person, shop, or company that keeps a particular product to sell 〔","cn":"专卖某种商品的〕零售商﹐专营商店﹐专营公司"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41stockist.mp3","us":"media/ldoce/hwd/ame/1/ld41stockist.mp3"},"examples":[{"en":"Call us to order or to get details of local stockists .","cn":"请来电订购或垂询当地零售商信息。"}],"oxford":{"phon":"ˈstɒkɪst","pos":"noun","senses":[{"en":"a shop or company that sells a particular product or type of goods","cn":"（某种产品或某类货品的）专营商店，专营公司","ex":{"en":"The paints are available from stockists throughout the UK.","cn":"这些涂料可从英国各地的库存商处购买。"}}]}},"stockbroker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"股票(或证券)经纪人","en":"A stockbroker is a person whose job is to buy and sell stocks and shares for people who want to invest money."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or organization whose job is to buy and sell share s , bond s etc for people","cn":"证券[股票]经纪人"}]},"vocab":{"pos":"n","senses":[{"en":"A stockbroker is someone who buys, sells, and trades stocks — or shares in companies — for a living. Most stockbrokers work for brokerage firms."}]},"collocations":{"phrases":["ADJ. large | leading | private client | City","VERB + STOCKBROKER consult","PREP. through a ~ The bonds were sold through a stockbroker.","PHRASES a firm of stockbrokers • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdestockbroker.mp3","us":"media/ldoce/hwd/ame/b/stockbroker.mp3"},"oxford":{"phon":"ˈstɒkbrəʊkə(r)","pos":"noun","senses":[{"en":"a person or an organization that buys and sells shares for other people","cn":"证券（或股票）经纪人；证券（或股票）经纪商","ex":{"en":"The bonds were sold through a stockbroker.","cn":"债券是通过证券经纪人卖出的。"}}]}},"stanford":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a famous American university in California, south of San Francisco","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000011521.mp3","us":"media/ldoce/hwd/ame/7/p028-000011521.mp3"}},"stepladder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"活动梯子;折梯","en":"A stepladder is a portable ladder that is made of two sloping parts that are hinged together at the top so that it will stand up on its own."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ladder which has two sloping parts that are joined at the top so that it can stand without support, and which can be folded flat","cn":"活（动）梯（子）﹐折梯"}]},"media":{"img":["media/ldoce/img/stepladder.jpg","media/ldoce/img/ldoce_192.png"],"uk":"media/ldoce/hwd/bre/0/stepladder0205.mp3","us":"media/ldoce/hwd/ame/9/stepladder.mp3"},"oxford":{"phon":"ˈsteplædə(r)","pos":"noun","senses":[{"en":"a short ladder that is made of two parts, one with steps, that are joined together at the top, so that it can stand on its own or be folded flat for carrying or storing","cn":"折梯；梯子"}]}},"stridency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"强硬;咄咄逼人;坚定","en":"Stridency is the quality of being strident.","ex":{"en":"Many voters were alarmed by the President's new stridency.","cn":"很多选民对总统最近表现出来的强势感到不安。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"forceful and determined, especially in a way that is offensive or annoying","cn":""},{"en":"a strident sound or voice is loud and unpleasant","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/strident0205.mp3","us":"media/ldoce/hwd/ame/5/strident.mp3"},"examples":[{"en":"the strident calls of seagulls","cn":""}],"oxford":{"phon":"ˈstraɪdənsi","pos":"noun","senses":[{"en":"the fact of being aggressive and determined","cn":"强硬的；咄咄逼人的","ex":{"en":"the stridency of her attacks on the government","cn":"她对政府的猛烈攻击"}},{"en":"the fact of being loud, rough and unpleasant","cn":"刺耳的","ex":{"en":"The kitchen rang with the stridency of her voice.","cn":"厨房里响起了她刺耳的声音。"}}]}},"strung":{"collins":{"senses":[{"pos":"","cn":"","en":"Strung is the past tense and past participle of string."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the past tense and past participle of string 2 string","cn":"的过去式和过去分词"}]},"media":{"uk":"media/ldoce/hwd/bre/4/strung0205.mp3","us":"media/ldoce/hwd/ame/c/strung.mp3"}},"storefront":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(临街的)店面，铺面","en":"A storefront is the outside part of a shop which faces the street, including the door and windows."},{"pos":"N-COUNT 可数名词","cn":"临街店铺(或办公室)","en":"A storefront is a small shop or office that opens onto the street and is part of a row of shops or offices.","ex":{"en":"Main Street in Great Barrington is lined with small storefronts and restaurants.","cn":"大巴灵顿的主街两侧林立着许多小的店铺和餐馆。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a store that faces the street 〔","cn":"临街的〕店面﹐铺面"},{"en":"a small church etc in a shopping area 〔","cn":"购物区内〕临街的教堂/小型律师事务所/学校等"}]},"media":{"uk":"media/ldoce/hwd/bre/c/storefront0205.mp3","us":"media/ldoce/hwd/ame/5/storefront.mp3"},"examples":[{"en":"They run their business from a small storefront.","cn":"他们在一间狭小的铺面房中做生意。"},{"en":"Welcome to our online storefront.","cn":"欢迎到我们的网上店铺。"}],"oxford":{"phon":"ˈstɔːfrʌnt","pos":"noun","senses":[{"en":"the outside of a shop that faces the street","cn":"商店门面；店面","lab":"British English"},{"en":"a room at the front of a shop","cn":"店面；铺面；铺面房","ex":{"en":"They run their business from a small storefront.","cn":"他们在一间狭小的铺面房中做生意。"}},{"en":"a place on the internet where you can buy goods and services","cn":"网上店铺；虚拟店面","ex":{"en":"Welcome to our online storefront.","cn":"欢迎到我们的网上店铺。"}}]}},"stagnant":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"停滞不前的;不发展的;无变化的","en":"If something such as a business or society is stagnant, there is little activity or change.","ex":{"en":"He is seeking advice on how to revive the stagnant economy","cn":"他正在就如何振兴低迷的经济征求意见。"}},{"pos":"ADJ 形容词","cn":"(水)不流动而污浊的","en":"Stagnant water is not flowing, and therefore often smells unpleasant and is dirty."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"stagnant water or air does not move or flow and often smells bad 〔","cn":"水或空气〕不流动的﹐污浊的﹐发臭的"},{"en":"not changing or making progress, and continuing to be in a bad condition","cn":"不发展的﹐停滞不前的"}]},"vocab":{"pos":"adj","senses":[{"en":"There is a tone to the word stagnant that sounds like what it is: lacking movement, stale, and inactive, especially with exaggerated pronunciation, \"staaaagnant.\""}]},"media":{"uk":"media/ldoce/hwd/bre/5/stagnant0205.mp3","us":"media/ldoce/hwd/ame/0/stagnant.mp3"},"examples":[{"en":"a stagnant economy","cn":"停滞的经济"},{"en":"a government plan to revive the stagnant economy","cn":"政府振兴低迷经济的计划"}],"oxford":{"phon":"ˈstæɡnənt","pos":"adjective","senses":[{"en":"stagnant water or air is not moving and therefore smells unpleasant","cn":"（水或空气）不流动而污浊的","ex":{"en":"Few fish survive in the stagnant waters of the lake.","cn":"很少有鱼能够在死水湖中生存。"}},{"en":"not developing, growing or changing","cn":"停滞的；不发展的；无变化的","ex":{"en":"a stagnant economy","cn":"停滞的经济"}}]}},"standoff":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"僵持","en":"A stand-off is a situation in which neither of two opposing groups or forces will make a move until the other one does something, so nothing can happen until one of them gives way.","ex":{"en":"There is no sign of an end to the stand-off between Mohawk Indians and the Quebec provincial police","cn":"莫霍克印第安人和魁北克省警方之间的僵持局面仍没有结束的迹象。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which neither side in a fight or battle can gain an advantage 〔","cn":"战斗双方的〕僵持（状态）"}]},"media":{"uk":"media/ldoce/hwd/bre/d/standoff0205.mp3","us":"media/ldoce/hwd/ame/2/laadstandoff.mp3"}},"stockade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(防御野生动物或敌人用的)栅栏，围栏","en":"A stockade is a wall of large wooden posts built around an area to keep out enemies or wild animals.","ex":{"en":"...the inner stockade.","cn":"内层围栏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fence built from long thick pieces of wood pushed into the ground, used to defend a place 〔","cn":"防御用的〕栅栏﹐围桩"}]},"vocab":{"pos":"n v","senses":[{"en":"A stockade is an enclosed pen used to herd cattle and other livestock. Stockades can also house men, in the sense of a penal camp. In both cases, the treatment tends to be on the rough side."}]},"media":{"uk":"media/ldoce/hwd/bre/8/stockade0205.mp3","us":"media/ldoce/hwd/ame/2/stockade1.mp3"},"oxford":{"phon":"stɒˈkeɪd","pos":"noun","senses":[{"en":"a line or wall of strong wooden posts built to defend a place","cn":"（防御用的）栅栏，围桩"}]}},"strenuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费力的;繁重的;艰苦的","en":"A strenuous activity or action involves a lot of energy or effort.","ex":{"en":"Avoid strenuous exercise in the evening","cn":"晚上不要做剧烈运动。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"tiring and needing a lot of work, energy, or physical effort","cn":""},{"en":"needing a lot of physical effort","cn":""},{"en":"backbreaking work, especially work that involves carrying and lifting heavy things, is extremely hard and needs a lot of physical effort","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something strenuous requires all your effort and strength, like a hard workout at the gym or carrying a backpack full of heavy books."}]},"media":{"uk":"media/ldoce/hwd/bre/1/strenuous0205.mp3","us":"media/ldoce/hwd/ame/2/strenuous.mp3"},"examples":[{"en":"The ship went down although strenuous efforts were made to save it.","cn":"尽管人们为营救这条船作了很大的努力，它还是沉了。"},{"en":"How about a stroll in the park? Nothing too strenuous.","cn":"在公园里散散步怎么样？不会太累的。"}],"oxford":{"phon":"ˈstrenjuəs","pos":"adjective","senses":[{"en":"needing great effort and energy","cn":"费力的；繁重的；艰苦的","ex":{"en":"a strenuous climb","cn":"艰难的攀登"}},{"en":"determined and showing great energy","cn":"劲头十足的；奋力的；顽强的","ex":{"en":"The ship went down although strenuous efforts were made to save it.","cn":"尽管人们为营救这条船作了很大的努力，它还是沉了。"}}]}},"stench":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"臭味;恶臭","en":"A stench is a strong and very unpleasant smell.","ex":{"en":"The stench of burning rubber was overpowering.","cn":"烧焦的橡胶臭气熏天。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you can recognize by breathing in through your nose","cn":""},{"en":"something that you smell for a short time","cn":""},{"en":"a smell – used especially about the pleasant smell from flowers, plants, or fruit. Also used about the smell left by an animal","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you pass a dump, you might hold your nose and say, \"Oh, I can't handle the stench .\" A stench is a bad smell."}]},"collocations":{"phrases":["ADJ. overpowering, powerful | unmistakable | appalling, foul, nauseating, sickening, terrible, unpleasant | acrid, fetid, putrid","STENCH + VERB fill sth The air was filled with the overpowering stench of decomposing vegetation."]},"media":{"uk":"media/ldoce/hwd/bre/d/stench0205.mp3","us":"media/ldoce/hwd/ame/c/stench.mp3"},"examples":[{"en":"( figurative ) The stench of treachery hung in the air.","cn":"到处都是可耻的叛变的气息。"},{"en":"an overpowering stench of rotting fish","cn":"腐烂的鱼臭气熏天"}],"oxford":{"phon":"stentʃ","pos":"noun","senses":[{"en":"a strong, very unpleasant smell","cn":"臭气；恶臭","lab":"figurative","ex":{"en":"an overpowering stench of rotting fish","cn":"腐烂的鱼臭气熏天"}}]}},"stamen":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(花的)雄蕊","en":"The stamens of a flower are the small, delicate stalks which grow at the flower's centre and produce pollen."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the male part of a flower that produces pollen 〔","cn":"花的〕雄蕊"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stamen.mp3","us":"media/ldoce/hwd/ame/6/stamen.mp3"},"oxford":{"phon":"ˈsteɪmən","pos":"noun","senses":[{"en":"a small, thin male part in the middle of a flower that produces pollen and is made up of a stalk supporting an anther. The centre of each flower usually has several stamens.","cn":"雄蕊"}]}},"stargazing":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"天体观察;天文学;占星学","en":"Star-gazing is the activity of studying the stars as an astronomer or astrologer."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who studies astronomy or astrology","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41stargazer.mp3","us":"media/ldoce/hwd/ame/8/stargazer.mp3"},"oxford":{"phon":"ˈstɑːɡeɪzɪŋ","pos":"noun","senses":[{"en":"the study of astronomy or astrology","cn":"观星：天文学或占星学的研究"}]}},"stationmaster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火车站站长","en":"A stationmaster is the official who is in charge of a railway station."}]},"oxford":{"phon":"ˈsteɪʃnmɑːstə(r)","pos":"noun","senses":[{"en":"a person in charge of a train station","cn":"（火车站）站长"}]}},"steroid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"类固醇(运动员服用后可增强体力)","en":"A steroid is a type of chemical substance found in your body. Steroids can be artificially introduced into the bodies of athletes to improve their strength."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a chemical that the body produces naturally or that can be made as a drug to treat illness and injuries. Steroids are sometimes used illegally by people doing sports to improve their performance","cn":"类固醇﹐甾族化合物"},{"en":"used to say that something is much bigger, stronger, more impressive etc than something else that is similar to it – used humorously","cn":"某物大[强壮﹐出色等]得多〔幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/steroid0205.mp3","us":"media/ldoce/hwd/ame/b/steroid.mp3"},"examples":[{"en":"They sell cinnamon rolls on steroids.","cn":"他们出售超大的肉桂面包。"},{"en":"a body builder on steroids","cn":"服用类固醇的健美运动员"}],"oxford":{"phon":"ˈsterɔɪd","pos":"noun","senses":[{"en":"a chemical substance produced naturally in the body. There are several different steroids and they can be used to treat various diseases and are also sometimes used illegally by people playing sports to improve their performance.","cn":"类固醇；甾族化合物"}]}},"stylistic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(写作、音乐或艺术作品)风格上的，创作技巧的","en":"Stylistic describes things relating to the methods and techniques used in creating a piece of writing, music, or art.","ex":{"en":"There are some stylistic elements in the statue that just don't make sense.","cn":"这座雕像上的一些风格元素让人完全捉摸不透。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the particular way an artist, writer, musician etc makes or performs something, especially the technical features or methods they use","cn":"文体上的﹔艺术风格上的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/stylistic0205.mp3","us":"media/ldoce/hwd/ame/a/stylistic.mp3"},"examples":[{"en":"stylistic analysis","cn":"风格分析"},{"en":"stylistic features","cn":"风格特点"}],"oxford":{"phon":"staɪˈlɪstɪk","pos":"adjective","senses":[{"en":"connected with the style an artist uses in a particular piece of art, writing or music","cn":"风格上的；文体上的","ex":{"en":"stylistic analysis","cn":"风格分析"}}]}},"stagnation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not progress at all with a piece of work or activity","cn":""},{"en":"to not progress at all, even though you have worked hard","cn":""},{"en":"if a piece of work or activity goes badly , it does not make progress or develop in the way you would like it to","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Stagnation is the state of being still, or not moving, like a sitting puddle of water where stagnation attracts mosquitoes."}]},"collocations":{"phrases":["ADJ. economic, political","VERB + STAGNATION lead to","PHRASES a period/years of stagnation Poor economic policies led to a long period of stagnation and decline."]},"media":{"uk":"media/ldoce/hwd/bre/a/stagnate0205.mp3","us":"media/ldoce/hwd/ame/e/stagnate.mp3"},"examples":[{"en":"a period of economic stagnation","cn":"经济停滞时期"},{"en":"Growth is expected to stagnate next year.","cn":""}],"oxford":{"phon":"stæɡˈneɪʃn","pos":"noun","senses":[{"en":"the fact of no longer developing or making progress","cn":"停滞；不发展；不进步","ex":{"en":"a period of economic stagnation","cn":"经济停滞期"}},{"en":"the fact of not moving and therefore smelling unpleasant","cn":"（水或空气）不流动而污浊的","ex":{"en":"water/air stagnation","cn":"水/空气停滞"}}]}},"stout":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肥胖的;肥壮的","en":"A stout person is rather fat.","ex":{"en":"He was a tall, stout man with gray hair.","cn":"他是个又高又胖、头发灰白的男子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"结实的;厚实的;粗壮的","en":"Stout shoes, branches, or other objects are thick and strong.","ex":{"en":"I hope you've both got stout shoes","cn":"我希望你们俩都有结实的鞋子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动、态度或信念)坚定的，坚决的，强有力的","en":"If you use stout to describe someone's actions, attitudes, or beliefs, you approve of them because they are strong and determined.","ex":{"en":"He produced a stout defence of the car business","cn":"他为汽车业进行了坚决的辩护。"}},{"pos":"N-MASS 物质名词","cn":"烈性黑啤酒","en":"Stout is a strong dark-coloured beer.","ex":{"en":"...Guinness and other Irish stouts.","cn":"吉尼斯黑啤酒及其他爱尔兰烈性黑啤酒"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone, especially a woman or child, who is dumpy , is short and fat","cn":""},{"en":"someone who is tubby is short and has a fat, round stomach","cn":""},{"en":"someone, especially a middle-aged person, who is stout is short and fat","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Stout describes something fat, dependable, or rugged. If someone calls you stout , ask them exactly what they mean before bursting into tears and skipping dinner. It could be a compliment!"}]},"media":{"uk":"media/ldoce/hwd/bre/c/stout_adj0205.mp3","us":"media/ldoce/hwd/ame/4/stout1.mp3"},"examples":[{"en":"‘I disagree,’ said Polly stoutly. “","cn":"我不同意。”波利拒不妥协地说。"},{"en":"He put up a stout defence in court.","cn":"他在法庭上进行了顽强的辩护。"}],"oxford":{"phon":"staʊt","pos":"adjective","senses":[{"en":"rather fat","cn":"肥胖的；肥壮的"},{"en":"strong and thick","cn":"粗壮结实的；厚实牢固的","g":"[usually before noun]","ex":{"en":"a stout pair of shoes","cn":"一双厚实耐穿的鞋"}},{"en":"brave and determined","cn":"勇敢坚毅的；顽强不屈的","g":"[usually before noun]","ex":{"en":"He put up a stout defence in court.","cn":"他在法庭上进行了顽强的辩护。"}},{"en":"strong dark beer made with malt or barley","cn":"烈性黑啤酒","pos":"noun"}]}},"stalker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"跟踪骚扰者(尤针对名人或分手恋人)","en":"A stalker is someone who keeps following or contacting someone else, especially a famous person or a person they used to have a relationship with, in an annoying and frightening way."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if someone such as a police officer tails someone, they secretly follow that person to find out where they are going or what they are doing","cn":""},{"en":"to follow close behind someone, especially in order to watch or catch them","cn":""},{"en":"to follow someone or something very closely in order to watch all their movements without them realizing that they are being followed","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"You might joke about your neighborhood stalker who always seems to know where you've been and what time you get home from work every day, but it can actually be a little creepy to know that someone's watching you."}]},"media":{"uk":"media/ldoce/hwd/bre/e/stalker0205.mp3","us":"media/ldoce/hwd/ame/f/laadstalker.mp3"},"oxford":{"phon":"ˈstɔːkə(r)","pos":"noun","senses":[{"en":"a person who follows and watches another person over a long period of time in a way that is annoying or frightening","cn":"跟踪者；盯梢者"},{"en":"a person who follows an animal quietly and slowly, especially in order to kill or capture it","cn":"悄悄接近猎物的猎人"}]}},"stroll":{"collins":{"senses":[{"pos":"VERB 动词","cn":"散步;溜达;闲逛","en":"If you stroll somewhere, you walk there in a slow, relaxed way.","ex":{"en":"He collected some orange juice from the refrigerator and, glass in hand, strolled to the kitchen window","cn":"他从冰箱里拿了点橘子汁，然后手拿杯子溜达到厨房的窗口。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk somewhere for pleasure","cn":""},{"en":"to walk in a relaxed way, especially for pleasure","cn":""},{"en":"to walk a long way in the mountains or countryside as an activity you enjoy","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"As a noun, a stroll is a leisurely walk. After a heavy meal, you may want to go out for a stroll to help you work off some of the calories. You also will take a stroll on your day off and the weather is nice."}]},"collocations":{"phrases":["ADJ. little, short | five-minute, etc. The shops are only a ten-minute stroll away. | casual, easy, gentle, leisurely | pleasant | moonlit, ","VERB + STROLL be/go out for, go for, take They took a leisurely stroll along the river bank.","PHRASES a stroll around (sth)/away The beach is only a short stroll away."]},"media":{"uk":"media/ldoce/hwd/bre/8/stroll0205.mp3","us":"media/ldoce/hwd/ame/c/stroll.mp3"},"examples":[{"en":"We went for a stroll in the park.","cn":"我们去公园散了散步。"},{"en":"People were strolling along the beach.","cn":"人们在海滩漫步。"}],"oxford":{"phon":"strəʊl","pos":"verb","senses":[{"en":"to walk somewhere in a slow relaxed way","cn":"散步；溜达；闲逛","ex":{"en":"People were strolling along the beach.","cn":"人们在海滩漫步。"}},{"en":"a slow relaxed walk","cn":"散步；溜达；闲逛","ex":{"en":"We went for a stroll in the park.","cn":"我们去公园散了散步。"},"pos":"noun"}]}},"stargazer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"天文学家;占星家","en":"A star-gazer is someone who studies the stars as an astronomer or astrologer."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who studies astronomy or astrology","cn":"天文学家﹔占星家"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41stargazer.mp3","us":"media/ldoce/hwd/ame/8/stargazer.mp3"},"oxford":{"phon":"ˈstɑːɡeɪzə(r)","pos":"noun","senses":[{"en":"a person who studies astrology or astronomy","cn":"占星术士；天文学家"}]}},"stratification":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指社会的)分层，形成阶层","en":"Stratification is the division of something, especially society, into different classes or layers.","ex":{"en":"She was concerned about the stratification of American society.","cn":"她很关注美国社会的阶层分化。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when society is divided into separate social classes 〔","cn":"社会的〕分层﹐阶层形成"},{"en":"the way in which earth, rocks etc form layers over time 〔","cn":"土壤﹑岩石等的〕层理﹔地层"}]},"vocab":{"pos":"n","senses":[{"en":"Stratification means arranging something, or something that has been arranged, into categories. By the time you figure out the complex social stratification of your high school class, from jocks to nerds and everything between, you’re ready to graduate."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stratification.mp3","us":"media/ldoce/hwd/ame/3/stratification.mp3"},"examples":[{"en":"social stratification","cn":"社会阶层化"},{"en":"The Indian caste system is an example of social stratification .","cn":"印度的种姓制度是社会阶层化的一个例子。"}],"oxford":{"phon":"ˌstrætɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the division of something into different layers or groups","cn":"分层；成层","ex":{"en":"social stratification","cn":"社会阶层化"}}]}},"strut":{"collins":{"senses":[{"pos":"VERB 动词","cn":"趾高气扬地走;昂首阔步","en":"Someone who struts walks in a proud way, with their head held high and their chest out, as if they are very important.","ex":{"en":"He struts around town like he owns the place.","cn":"他在城里大摇大摆地晃荡，好像那是他的地盘。"}},{"pos":"N-COUNT 可数名词","cn":"撑杆;支杆;支柱;支撑","en":"A strut is a piece of wood or metal which holds the weight of other pieces in a building or other structure.","ex":{"en":"...the struts of a suspension bridge.","cn":"吊桥的支柱"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to keep doing things and saying things in order to show people how clever you are, how brave or strong you are etc - use this especially when you disapprove of this behaviour","cn":""},{"en":"to do something that you do well, usually in a way that shows you are proud of yourself","cn":""},{"en":"to walk proudly, swinging your shoulders, in a way that shows too much self-confidence","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you strut , you walk with a proud swagger that has a little arrogance thrown in, like the prance of a running back who has just flown past the 250-pound linebackers and planted the ball in the end zone."}]},"media":{"uk":"media/ldoce/hwd/bre/3/strut_v0205.mp3","us":"media/ldoce/hwd/ame/4/strut1.mp3"},"examples":[{"en":"The players strutted and posed for the cameras.","cn":"运动员昂首阔步，摆好姿势让记者拍照。"},{"en":"I strutted around Chicago as if I were really somebody.","cn":"我在芝加哥街头昂首阔步﹐好像自己真是个人物似的。"}],"oxford":{"phon":"strʌt","pos":"verb","senses":[{"en":"to walk proudly with your head up and chest out to show that you think you are important","cn":"趾高气扬地走；高视阔步","ex":{"en":"The players strutted and posed for the cameras.","cn":"运动员昂首阔步，摆好姿势让人拍照。"}},{"en":"a long, thin piece of wood or metal used to support or make part of a vehicle or building stronger","cn":"支柱；撑杆；支杆；撑材","ex":{"en":"wheel struts","cn":"车轮支柱"},"pos":"noun"},{"en":"an act of walking in a proud and confident way","cn":"趾高气扬的步态；高视阔步的样子","g":"[singular]","lab":"disapproving","ex":{"en":"She recognized his arrogant strut.","cn":"她认出了他傲慢的姿态。"},"pos":"noun"}]}},"strained":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"焦虑的;紧张的;担忧的","en":"If someone's appearance, voice, or behaviour is strained, they seem worried and nervous.","ex":{"en":"She looked a little pale and strained","cn":"她看起来面色有点苍白，神情忧虑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（关系）紧张的，不友好的，互相猜测的","en":"If relations between people are strained, those people do not like or trust each other.","ex":{"en":"...a period of strained relations between the prime minister and his deputy.","cn":"总理和副总理之间关系紧张的时期"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a tense situation makes people feel nervous and anxious, especially because they are worried about what might happen next or what someone might do","cn":""},{"en":"a situation that is strained makes people feel nervous, embarrassed, and uncomfortable, and unable to behave naturally","cn":""},{"en":"a situation that is uneasy makes people feel a little nervous because they are uncertain about what will happen next or what someone might do","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound","ADV. very | a bit, a little, rather She looked rather strained and miserable. 2 not natural or friendly","VERBS be | become, grow | remain The atmosphere remained somewhat strained all evening.","ADV. extremely, severely, very Relations between the two countries had become severely strained. | increasingly | a bit, a little, rather, s"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdestrained.mp3","us":"media/ldoce/hwd/ame/3/strained.mp3"},"examples":[{"en":"Her face looked strained and weary.","cn":"她的脸色显得憔悴疲惫。"},{"en":"There was a strained atmosphere throughout the meeting.","cn":"会议自始至终气氛紧张。"}],"oxford":{"phon":"streɪnd","pos":"adjective","senses":[{"en":"showing the effects of worry or pressure","cn":"神色不宁的；紧张的；憔悴的","ex":{"en":"Her face looked strained and weary.","cn":"她的脸色显得憔悴疲惫。"}},{"en":"not relaxed or friendly","cn":"紧张的；不友好的","ex":{"en":"There was a strained atmosphere throughout the meeting.","cn":"会议自始至终气氛紧张。"}},{"en":"not natural; produced by a deliberate effort","cn":"不自然的；做作的；勉强的","ex":{"en":"She gave a strained laugh.","cn":"她不自然地大笑了一声。"}}]}},"stronghold":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(持共同态度或信仰的人的)大本营，据点","en":"If you say that a place or region is a stronghold of a particular attitude or belief, you mean that most people there share this attitude or belief.","ex":{"en":"The westernmost part of north Wales is a stronghold of Welsh-speakers","cn":"北威尔士最西部是说威尔士语人的聚居区。"}},{"pos":"N-COUNT 可数名词","cn":"(某种动物的)主要栖息地","en":"If you say that a place is a stronghold of a particular type of animal, you mean that more of that type of animal live there than in other places.","ex":{"en":"Shetland is the last stronghold of otters in the British Isles.","cn":"设得兰群岛是水獭在不列颠群岛上最后的栖息地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area where there is a lot of support for a particular way of life, political party etc 〔","cn":"某一生活方式﹑政党等〕备受支持的地方﹔据点﹐大本营"},{"en":"an area that is strongly defended by a military group","cn":"堡垒﹔要塞﹔据点"},{"en":"an area where there are large numbers of a rare animal 〔","cn":"珍稀动物的〕主要栖息地"}]},"vocab":{"pos":"n","senses":[{"en":"A stronghold is a building or other structure that is safe from attack. A fortress is a perfect example of a stronghold ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/stronghold0205.mp3","us":"media/ldoce/hwd/ame/c/stronghold.mp3"},"examples":[{"en":"This valley is one of the last strongholds of the Siberian tiger.","cn":"这条山谷是西伯利亚虎最后的几个主要栖息地之一。"},{"en":"a Republican stronghold/a stronghold of Republicanism","cn":"共和党势力强大的地区"}],"oxford":{"phon":"ˈstrɒŋhəʊld","pos":"noun","senses":[{"en":"an area in which there is a lot of support for a particular belief or group of people, especially a political party","cn":"有广泛支持的地方；势力强大的地方","ex":{"en":"a Republican stronghold/a stronghold of Republicanism","cn":"共和党势力强大的地区"}},{"en":"a castle or a place that is strongly built and difficult to attack","cn":"堡垒；要塞；据点","ex":{"en":"The castle was an important royal stronghold for hundreds of years.","cn":"这座城堡曾经作为重要的皇家要塞达数百年之久。"}},{"en":"an area where there are a large number of a particular type of animal","cn":"（某种动物的）主要栖息地","ex":{"en":"This valley is one of the last strongholds of the Siberian tiger.","cn":"这条山谷是西伯利亚虎最后的几个主要栖息地之一。"}}]}},"stray":{"collins":{"senses":[{"pos":"VERB 动词","cn":"迷路;偏离;走失","en":"If someone strays somewhere, they wander away from where they are supposed to be.","ex":{"en":"Tourists often get lost and stray into dangerous areas","cn":"游客常会迷路并误入危险区域。"}},{"pos":"ADJ 形容词","cn":"(狗、猫)走失的，迷路的，无主的","en":"A stray dog or cat has wandered away from its owner's home.","ex":{"en":"A stray dog came up to him.","cn":"一条野狗走近他。"}},{"pos":"VERB 动词","cn":"走神;(视线)偏离，往别处看","en":"If your mind or your eyes stray, you do not concentrate on or look at one particular subject, but start thinking about or looking at other things.","ex":{"en":"Even with the simplest cases I find my mind straying","cn":"即使在处理最简单的案例时我也老走神。"}},{"pos":"ADJ 形容词","cn":"零星的;离散的;散落的","en":"You use stray to describe something that exists separated from other similar things.","ex":{"en":"An 8-year-old boy was killed by a stray bullet","cn":"一名 8 岁男孩儿被流弹打死。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move away from the main subject that you have been talking or writing about, especially for a short time during a speech or story","cn":""},{"en":"if you are talking about something and are sidetracked or get sidetracked , you allow yourself to start talking or thinking about something else, especially something less important","cn":""},{"en":"if you stray from the subject you are talking about, you start talking about other things instead, for example, because you cannot keep your attention on the main subject","cn":""}]},"vocab":{"pos":"v n adj","senses":[{"en":"Little Red Riding Hood strayed from the path and ended up getting eaten by the Big Bad Wolf. When you stray , you wander off without paying attention to where you're going, and sometimes you get in trouble."}]},"collocations":{"phrases":["ADV. far The animals hadn't strayed too far. | accidentally, involuntarily Her eyes strayed involuntarily.","VERB + STRAY allow sth to new penalties for owners who allow their dogs to stray","PREP. from Be careful not to stray from the path. | into, off, to His eyes strayed to the telephone. (figurative) Her thoughts strayed to th"]},"media":{"uk":"media/ldoce/hwd/bre/b/stray_n0205.mp3","us":"media/ldoce/hwd/ame/c/stray1.mp3"},"examples":[{"en":"My mind kept straying back to our last talk together.","cn":"我老走神，一再回想起我们上次在一起交谈的情景。"},{"en":"He strayed into the path of an oncoming car.","cn":"他偏到了一辆迎面驶来的汽车的行车路线上。"}],"oxford":{"phon":"streɪ","pos":"verb","senses":[{"en":"to move away from the place where you should be, without intending to","cn":"迷路；偏离；走失","g":"[intransitive]","ex":{"en":"He strayed into the path of an oncoming car.","cn":"他偏到了一辆迎面驶来的汽车的行车路线上。"}},{"en":"to begin to think about or discuss a different subject from the one you should be thinking about or discussing","cn":"偏离正题；走神；离题","g":"[intransitive]","ex":{"en":"My mind kept straying back to our last talk together.","cn":"我老走神，一再回想起我们上次在一起交谈的情景。"}},{"en":"to have a sexual relationship with somebody who is not your usual partner","cn":"有外遇；拈花惹草","g":"[intransitive]","ex":{"en":"Were you ever tempted to stray when you were away from home?","cn":"当你离家在外时，你有没有想过出轨？"}},{"en":"away from home and lost; having no home","cn":"走失的；无主的","ex":{"en":"stray dogs","cn":"走失的狗"},"pos":"adjective"},{"en":"separated from other things or people of the same kind","cn":"零星的；孤立的；离群的；走散的","ex":{"en":"A civilian was killed by a stray bullet.","cn":"一个平民被流弹打死。"},"pos":"adjective"},{"en":"an animal that has got lost or separated from its owner or that has no owner","cn":"走失的宠物（或家畜）；无主的宠物（或家畜）","pos":"noun"},{"en":"a person or thing that is not in the right place or is separated from others of the same kind","cn":"离群者；走散者；不在原位置的东西","pos":"noun"}]}},"statistical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"统计的;统计学的","en":"Statistical means relating to the use of statistics.","ex":{"en":"The report contains a great deal of statistical information","cn":"报告中包含很多统计资料。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to statistics","cn":"统计（学）的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you can say it with numbers, then it is probably statistical . Statistical information (or \"stats\") can tell the chance of rain tomorrow or what percentage or your allowance gets spent on texting."}]},"media":{"uk":"media/ldoce/hwd/bre/7/ldoce6statistical.mp3","us":"media/ldoce/hwd/ame/b/statistical_adj.mp3"},"examples":[{"en":"statistical analysis","cn":"统计分析"},{"en":"statistical evidence","cn":"统计证据"}],"oxford":{"phon":"stəˈtɪstɪkl","pos":"adjective","senses":[{"en":"connected with or based on statistics","cn":"统计的；统计学的","ex":{"en":"statistical analysis","cn":"统计分析"}}]}},"streetwise":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适应大城市生活的;在大城市混得开的","en":"Someone who is streetwise knows how to deal with difficult or dangerous situations in big cities.","ex":{"en":"Salt and Peppa are two streetwise and sassy girls from Queens.","cn":"索尔特和佩帕是两个来自皇后区的精明泼辣的女孩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you say that someone has been around , you mean that they have had experience of many different situations and many different types of people and so they can deal with new situations confidently and easily","cn":""},{"en":"to be someone who knows a lot about life, has had a lot of different experiences etc and is not easily shocked by things","cn":""},{"en":"someone who is sophisticated has a lot of knowledge and experience of clever, fashionable things, and shows this by the way they talk and behave","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41streetwise.mp3","us":"media/ldoce/hwd/ame/a/streetwise.mp3"},"oxford":{"phon":"ˈstriːtwaɪz","pos":"adjective","senses":[{"en":"having the knowledge and experience that is needed to deal with the difficulties and dangers of life in a big city","cn":"适应都市生活的；有都市人的精明劲儿的","ex":{"en":"Kids seem much more streetwise these days.","cn":"如今的孩子们比以前精明了。"}}]}},"strongman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"铁腕人物;独裁者","en":"If you refer to a male political leader as a strongman, you mean that he has great power and control over his country, although his methods may sometimes be violent or morally wrong.","ex":{"en":"He was a military strongman who ruled the country after a coup.","cn":"他是个军事独裁者，在一场军事政变后成为这个国家的统治者。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a politician or leader who uses violence or threats to get what they want","cn":"铁腕人物﹔独裁者"},{"en":"a very strong man who performs in a circus 〔","cn":"马戏团里的〕大力士"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41strongman.mp3","us":"media/ldoce/hwd/ame/b/laadstrongman.mp3"},"oxford":{"phon":"ˈstrɒŋmæn","pos":"noun","senses":[{"en":"a leader who uses threats or violence to rule a country","cn":"铁腕人物；独裁者","ex":{"en":"The country has been under the control of military strongmen for a long time.","cn":"该国长期处于军事强人的控制之下。"}},{"en":"a physically very strong man, especially somebody who performs in a circus","cn":"（尤指马戏团里的）大力士"}]}},"stiletto":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"细高跟女鞋","en":"Stilettos are women's shoes that have high, very narrow heels."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman’s shoe that has a very high thin heel","cn":"细高跟女鞋"},{"en":"the heel of a stiletto shoe 〔","cn":"女鞋上的〕细高跟"},{"en":"a small knife with a thin blade","cn":"短剑﹐匕首"}]},"vocab":{"pos":"n","senses":[{"en":"A killer in an old British mystery novel might carry a stiletto — a long, sharp, needle-like knife that's used for stabbing."}]},"media":{"uk":"media/ldoce/hwd/bre/7/stiletto0205.mp3","us":"media/ldoce/hwd/ame/3/l3stiletto.mp3","img":["media/thumb/stiletto.jpg"]},"oxford":{"phon":"stɪˈletəʊ","pos":"noun","senses":[{"en":"a shoe with a very high narrow heel; the heel on such a shoe","cn":"细高跟女鞋","lab":"especially British English"},{"en":"a small knife with a narrow pointed blade (= cutting edge)","cn":"短剑；匕首"}]}},"stepson":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继子","en":"Someone's stepson is a son born to their husband or wife during a previous relationship."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a son that your husband or wife has from a relationship before your marriage","cn":"继子"}]},"media":{"uk":"media/ldoce/hwd/bre/3/stepson0205.mp3","us":"media/ldoce/hwd/ame/a/laadstepson.mp3"},"oxford":{"phon":"ˈstepsʌn","pos":"noun","senses":[{"en":"a son that your husband or wife has from an earlier marriage or relationship with another person","cn":"继子"}]}},"stubborn":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"倔强的;固执的;顽固的;执拗的","en":"Someone who is stubborn or who behaves in a stubborn way is determined to do what they want and is very unwilling to change their mind.","ex":{"en":"He is a stubborn character used to getting his own way","cn":"他性格固执，惯于一意孤行。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(污渍)顽固的，难以去除的;(问题)棘手的，难以解决的","en":"A stubborn stain or problem is difficult to remove or to deal with.","ex":{"en":"This treatment removes the most stubborn stains","cn":"这个方法能清除大多数顽固污渍。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"refusing to change your mind, even when people think you are wrong or are being unreasonable","cn":""},{"en":"very stubborn, in way that is annoying and unreasonable","cn":""},{"en":"refusing to change your mind, even when people think that what you want to do is stupid","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective stubborn to describe someone who is not open to new ideas or ways of doing things, like your uncle who refuses to listen to any music made after 1990. Stubborn is the opposite of flexible ."}]},"media":{"uk":"media/ldoce/hwd/bre/a/stubborn0205.mp3","us":"media/ldoce/hwd/ame/5/stubborn.mp3"},"examples":[{"en":"She can be as stubborn as a mule.","cn":"她可以倔得像头骡子。"},{"en":"She stubbornly refused to pay.","cn":"她怎么都不肯付钱。"}],"oxford":{"phon":"ˈstʌbən","pos":"adjective","senses":[{"en":"determined not to change your opinion or attitude","cn":"固执的；执拗的；顽固的；倔强的","lab":"often disapproving","ex":{"en":"He was too stubborn to admit that he was wrong.","cn":"他死不认错。"}},{"en":"difficult to get rid of or deal with","cn":"棘手的；难以去除的；难以对付的","g":"[usually before noun]","ex":{"en":"a stubborn cough/stain","cn":"久治不愈的咳嗽；顽渍"}}]}},"strum":{"collins":{"senses":[{"pos":"VERB 动词","cn":"弹奏，拨弄(吉他等弦乐器)","en":"If you strum a stringed instrument such as a guitar, you play it by moving your fingers backwards and forwards across the strings.","ex":{"en":"In the corner, one youth sat alone, softly strumming a guitar","cn":"一个青年独自坐在角落里，轻轻地弹着吉他。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to play an instrument such as a guitar by moving your fingers up and down across its strings","cn":"弹奏﹐拨弄〔吉他等弦乐器〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/strum0205.mp3","us":"media/ldoce/hwd/ame/a/strum.mp3"},"examples":[{"en":"As she sang she strummed on a guitar.","cn":"她边唱边弹吉他。"}],"oxford":{"phon":"strʌm","pos":"verb","senses":[{"en":"to play a guitar or similar instrument by moving your fingers up and down across the strings","cn":"弹奏（吉他等乐器）","ex":{"en":"As she sang she strummed on a guitar.","cn":"她边唱边弹吉他。"}}]}},"strafe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(从低空)扫射，轰炸","en":"To strafe an enemy means to attack them with a lot of bombs or bullets from a low-flying aircraft.","ex":{"en":"It seemed that the plane was going to swoop down and strafe the town, so we dived for cover.","cn":"飞机看起来好像要俯冲下来轰炸小镇，所以我们赶紧蹲下躲避。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to attack a place from an aircraft by flying low and firing a lot of bullets","cn":"低空（飞行）扫射[袭击]"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41strafe.mp3","us":"media/ldoce/hwd/ame/7/strafe.mp3"},"oxford":{"phon":"streɪf","pos":"verb","senses":[{"en":"to attack a place with bullets or bombs from an aircraft flying low","cn":"低空扫射（或轰炸）","ex":{"en":"Military aircraft strafed the village.","cn":"军机从低空扫射这个村庄。"}}]}},"strip-search":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常指为检查是否携带毒品或武器而)对…进行裸体搜查","en":"If a person is strip-searched, someone such as a police officer makes them take off all their clothes and searches them, usually to see if they are carrying drugs or weapons.","ex":{"en":"All 23 of them were strip-searched for drugs.","cn":"他们 23 个人均被裸体搜查，看是否携带毒品。"}}]},"oxford":{"phon":"ˈstrɪp sɜːtʃ","pos":"noun","senses":[{"en":"an act of searching a person for illegal drugs, weapons, etc., for example at an airport or in a prison, after they have been made to take off all their clothes","cn":"（对怀疑非法携带毒品、武器等的人进行的）光身搜查"},{"en":"to search a person for illegal drugs, weapons, etc, for example at an airport or in a prison, after they have been made to take off all their clothes","cn":"（对怀疑非法携带毒品、武器等的人进行的）光身搜查","pos":"verb"}]}},"startled":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel afraid","cn":""},{"en":"to frighten someone. Scare is less formal than frighten , and is the usual word to use in everyday English","cn":""},{"en":"to make someone feel extremely frightened","cn":""}]},"collocations":{"phrases":["VERBS be, look, seem, sound","ADV. very | a bit, a little, quite, rather, slightly, somewhat | for a moment, momentarily She was momentarily startled by the sight before ","PREP. at She was obviously a little startled at this idea. | by startled by his sudden appearance in the doorway"]},"media":{"uk":"media/ldoce/hwd/bre/8/startle0205.mp3","us":"media/ldoce/hwd/ame/a/startle.mp3"},"examples":[{"en":"She jumped back like a startled rabbit.","cn":"她像受惊的兔子似的跳了回去。"},{"en":"She looked at him with startled eyes.","cn":"她用吃惊的目光看着他。"}],"oxford":{"phon":"ˈstɑːtld","pos":"adjective","senses":[{"en":"slightly shocked or frightened because of a sudden surprise","cn":"吓了一跳：由于突然的惊奇而略为震惊或害怕","ex":{"en":"She looked at him with startled eyes.","cn":"她用吃惊的目光看着他。"}}]}},"stare":{"collins":{"senses":[{"pos":"VERB 动词","cn":"凝视;盯着看","en":"If you stare at someone or something, you look at them for a long time.","ex":{"en":"Tamara stared at him in disbelief, shaking her head","cn":"塔玛拉一边狐疑地盯着他看，一边摇着头。"}},{"pos":"PHRASE 短语","cn":"(局势、解决办法等)非常明显的，明摆在眼前","en":"If a situation or the answer to a problem is staring you in the face, it is very obvious, although you may not be immediately aware of it.","ex":{"en":"Then the answer hit me. It had been staring me in the face ever since Lullington.","cn":"接着我突然想到了答案。从在路林顿起它就一直摆在我的眼前。"}},{"pos":"","cn":"","en":"相关词组：stare out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to turn your eyes towards someone or something, so that you can see them","cn":""},{"en":"to look at something quickly, especially in order to find or check something","cn":""},{"en":"to look at someone or something for a short time and then look quickly away","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To stare is to fix your eyes on a subject. As hard as it might be to resist looking at them for long periods of time, it's not polite to stare at celebrities."}]},"collocations":{"phrases":["ADV. fixedly, hard, intently, unblinkingly I could see a man staring at me intently. | steadily | impassively | absently, blankly, blearily,","VERB + STARE can/could only She could only stare at him with pain in her eyes. | seem to | continue to | turn to Everyone in the room turned","PREP. across, after She stalked off, leaving them all staring after her. | around/round, at, in I stared in horror at his bloody mouth. | in","PHRASES sit/stand staring, stand/stop and stare It was too cold to stand and stare. | stare into space She was just sitting there, staring i"]},"media":{"uk":"media/ldoce/hwd/bre/5/stare_v0205.mp3","us":"media/ldoce/hwd/ame/f/stair.mp3"},"examples":[{"en":"I looked at her and she glared stonily back.","cn":"我看了她一眼，她便冷冷地回瞪着我。"},{"en":"She looked at them with dark staring eyes.","cn":"她那双深邃的眼睛专注地看着他们。"}],"oxford":{"phon":"steə(r)","pos":"verb","senses":[{"en":"to look at somebody/something for a long time","cn":"盯着看；凝视；注视","ex":{"en":"I screamed and everyone stared.","cn":"我尖叫一声，众人都盯着我看。"}},{"en":"an act of looking at somebody/something for a long time, especially in a way that is unfriendly or that shows surprise","cn":"（尤指不友好或吃惊的）盯，凝视，注视","ex":{"en":"She gave him a blank stare.","cn":"她面无表情地直视着他。"},"pos":"noun"}]}},"stringency":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"银根紧缩;财政紧缩;手头紧","en":"Financial stringency is a situation in which a government or person does not have much money or is trying not to spend much.","ex":{"en":"In times of financial stringency it is clear that public expenditure has to be closely scrutinized.","cn":"财政紧缩时期，无疑要对公共支出进行严格审查。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a strict order or rule is one that must be obeyed","cn":""},{"en":"tight controls or limits are very strict about what is allowed and what is not allowed","cn":""},{"en":"tough laws or rules are very strict","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/stringent0205.mp3","us":"media/ldoce/hwd/ame/4/stringent.mp3"},"examples":[{"en":"a period of financial stringency","cn":"财政紧缩时期"}],"oxford":{"phon":"ˈstrɪndʒənsi","pos":"noun","senses":[{"en":"the quality of being very strict","cn":"非常严格的品质","ex":{"en":"the stringency of environmental regulations","cn":"环境法规的严格性"}},{"en":"the fact of conditions being difficult and having very strict controls because there is not much money","cn":"因为没有多少钱，条件艰苦，控制非常严格","ex":{"en":"a period of financial stringency","cn":"财政紧缩期"}}]}},"stumble":{"collins":{"senses":[{"pos":"VERB 动词","cn":"绊脚;跌跌撞撞地走;踉跄;步履蹒跚","en":"If you stumble, you put your foot down awkwardly while you are walking or running and nearly fall over.","ex":{"en":"He stumbled and almost fell","cn":"他差点被绊倒。"}},{"pos":"VERB 动词","cn":"(朗读或说话时)结巴，磕磕巴巴","en":"If you stumble while you are reading aloud or speaking, you make a mistake, and have to pause before saying the words properly.","ex":{"en":"...his voice wavered and he stumbled over the words at one point.","cn":"他声音颤抖，一度说话磕磕巴巴的"}},{"pos":"","cn":"","en":"相关词组：stumble across"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to suddenly go down onto the floor when standing, walking, or running","cn":""},{"en":"to fall or almost fall when you hit your foot against something","cn":""},{"en":"to fall or almost fall when you are walking on a wet or very smooth surface","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To stumble means to nearly fall by tripping or missing a step. When you walk over uneven cobblestones, it’s easy to stumble , so please be careful."}]},"collocations":{"phrases":["ADV. almost, nearly | a little, slightly She stumbled a little on the uneven path. | blindly He stumbled blindly on through the dark buildin","PREP. against, along, down, from, into, out of, over, towards, etc. They stumbled over the ploughed field.","PHRASES stumble to your feet The train stopped, and several passengers stumbled to their feet. PHRASAL VERBS stumble across/on/upon sth","ADV. accidentally, by chance, unwittingly I stumbled across the place quite by chance."]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdestumble.mp3","us":"media/ldoce/hwd/ame/c/stumble1.mp3"},"examples":[{"en":"I stumbled through the piano piece with difficulty.","cn":"我断断续续地好不容易弹完了那支钢琴曲。"},{"en":"Police have stumbled across a huge drugs ring.","cn":"警方无意中发现一个庞大的贩毒集团。"}],"oxford":{"phon":"ˈstʌmbl","pos":"noun","senses":[{"en":"a problem or temporary failure when you are on the way to achieving something","cn":"绊倒：在实现目标的过程中出现问题或暂时失败","lab":"informal","ex":{"en":"There were good reasons for the team's first-round stumble against Los Angeles.","cn":"球队首轮输给洛杉矶队是有充分理由的。"}},{"en":"an act of falling or almost falling, especially because you hit your foot against something","cn":"跌倒：跌倒或几乎跌倒的动作，尤其是因为您的脚撞到某物上","ex":{"en":"After a slight stumble backwards, he regained his balance.","cn":"稍微向后踉踉跄跄后，他才恢复了平衡。"}},{"en":"a mistake that causes you to stop when you are reading, speaking or playing music","cn":"（不顺畅地）说，读，演奏","ex":{"en":"verbal stumbles","cn":"言语结巴"}},{"en":"to hit your foot against something while you are walking or running and almost fall","cn":"绊脚","g":"[intransitive]","lab":"figurative","ex":{"en":"The child stumbled and fell.","cn":"孩子绊了一下，摔倒了。"},"pos":"verb"},{"en":"to walk or move in an unsteady way","cn":"跌跌撞撞地走；蹒跚而行","g":"[intransitive]","ex":{"en":"Max stumbled out of bed sleepily.","cn":"马克斯睡眼惺忪地从床上爬起来。"},"pos":"verb"},{"en":"to make a mistake or mistakes and stop while you are speaking, reading to somebody or playing music","cn":"（不顺畅地）说，读，演奏","g":"[intransitive]","ex":{"en":"In her nervousness she stumbled over her words.","cn":"她因紧张说话结结巴巴的。"},"pos":"verb"}]}},"stepchild":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继子;继女","en":"Someone's stepchild is a child that was born to their husband or wife during a previous relationship."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stepdaughter or stepson","cn":"继女﹔继子"}]},"media":{"uk":"media/ldoce/hwd/bre/5/stepchild0205.mp3","us":"media/ldoce/hwd/ame/f/stepchild.mp3"},"oxford":{"phon":"ˈsteptʃaɪld","pos":"noun","senses":[{"en":"a child that your husband or wife has from an earlier marriage or relationship with another person","cn":"继子；继女"}]}},"stinky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有臭味的;味道极其难闻的","en":"If something is stinky, it smells extremely unpleasant.","ex":{"en":"...sweaty, stinky socks.","cn":"汗津津的臭袜子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"smelling unpleasant","cn":"难闻的﹐恶臭的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/stinky0205.mp3","us":"media/ldoce/hwd/ame/2/laadstinky.mp3"},"examples":[{"en":"stinky socks","cn":"臭袜子"}],"oxford":{"phon":"ˈstɪŋki","pos":"adjective","senses":[{"en":"having an extremely bad smell","cn":"发恶臭的；十分难闻的"},{"en":"extremely unpleasant or bad","cn":"令人厌恶的；糟糕透顶的"}]}},"stationary":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"静止的;不动的","en":"Something that is stationary is not moving.","ex":{"en":"Stationary cars in traffic jams cause a great deal of pollution","cn":"交通堵塞中静止不动的汽车产生了大量污染。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not moving - use this especially about people who are not moving, or about places where there is no wind","cn":""},{"en":"a car, vehicle etc that is not moving","cn":""},{"en":"if traffic is at a standstill it is not moving. If rail or bus services are at a standstill they have stopped operating","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Stationary means not moving. A stationary bike is the kind you find in the gym –– you pedal and pedal, but you just don’t go anywhere."}]},"media":{"uk":"media/ldoce/hwd/bre/4/stationary0205.mp3","us":"media/ldoce/hwd/ame/1/stationary.mp3"},"examples":[{"en":"The car collided with a stationary vehicle.","cn":"小汽车撞到一辆停着的车上。"},{"en":"I remained stationary.","cn":"我待着没动。"}],"oxford":{"phon":"ˈsteɪʃənri","pos":"adjective","senses":[{"en":"not moving; not intended to be moved","cn":"不动的；静止的；固定的；不可移动的","ex":{"en":"I remained stationary.","cn":"我待着没动。"}},{"en":"not changing in condition or quantity","cn":"不变的；稳定的","ex":{"en":"a stationary population","cn":"稳定的人口"}}]}},"stepfather":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继父","en":"Someone's stepfather is the man who has married their mother after the death or divorce of their father."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a male parent","cn":""},{"en":"used when talking to your father, or about someone’s father","cn":""},{"en":"a name for father, which is used especially by young children or when you are talking to young children","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/stepfather0205.mp3","us":"media/ldoce/hwd/ame/d/laadstepfather.mp3"},"oxford":{"phon":"ˈstepfɑːðə(r)","pos":"noun","senses":[{"en":"a man who is the husband or partner of your mother but who is not your birth father","cn":"继父","ex":{"en":"He lives at home with his mother and stepfather.","cn":"他跟母亲和继父一起住在家里。"}}]}},"standby":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"常备物;后备人选","en":"A standby is something or someone that is always ready to be used if they are needed.","ex":{"en":"Canned varieties of beans and pulses are a good standby","cn":"各种豆类罐头制品是很好的常备食品。"}},{"pos":"PHRASE 短语","cn":"常备的;备用的","en":"If someone or something is on standby, they are ready to be used if they are needed.","ex":{"en":"Five ambulances are on standby at the port","cn":"5 辆救护车在港口待命。"}},{"pos":"ADJ 形容词","cn":"(戏票或机票)最后时刻廉价出售的，剩余的","en":"A standby ticket for something such as the theatre or a plane journey is a cheap ticket that you buy just before the performance starts or the plane takes off, if there are still some seats left.","ex":{"en":"Access International books standby flights from New York to Europe.","cn":"全球通达公司可以预订从纽约到欧洲的剩余机票。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to be ready to take action or provide something when it is needed","cn":""},{"en":"if a group of people, especially soldiers or police are on standby , they are waiting, ready to go somewhere if they are needed when something happens that is expected to happen soon","cn":""},{"en":"if someone such as a doctor or engineer is on call , they are ready to give advice on the phone or go and help where they are needed, as part of their job","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/standby_n0205.mp3","us":"media/ldoce/hwd/ame/b/standby.mp3"},"examples":[{"en":"The emergency services were put on standby after a bomb warning.","cn":"接到炸弹警报后，各紧急救助部门进入待命状态。"},{"en":"I always keep a pizza in the freezer as a standby.","cn":"我总会在冰箱里放一个比萨饼应急。"}],"oxford":{"phon":"ˈstændbaɪ","pos":"noun","senses":[{"en":"a person or thing that can always be used if needed, for example if somebody/something else is not available or if there is an emergency","cn":"后备人员；备用物品","ex":{"en":"I always keep a pizza in the freezer as a standby.","cn":"我总会在冰箱里放一个比萨饼以备不时之需。"}},{"en":"a standby ticket for a flight, concert, etc. cannot be bought in advance and is only available a very short time before the plane leaves or the performance starts","cn":"（机票、音乐会门票等）最后时刻出售的","pos":"adjective"}]}},"starchy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"淀粉含量高的","en":"Starchy foods contain a lot of starch.","ex":{"en":"...starchy and sticky glutinous rices.","cn":"含大量淀粉、黏性大的糯米"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"containing a lot of starch 1 (1)","cn":"含大量淀粉的"},{"en":"very formal and correct in your behaviour – used to show disapproval","cn":"古板的﹐拘谨的﹐生硬的〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/starchy0205.mp3","us":"media/ldoce/hwd/ame/7/starchy.mp3"},"examples":[{"en":"She spoke in a rather starchy manner.","cn":"她说话时态度很生硬。"},{"en":"starchy foods","cn":"含大量淀粉的食物"}],"oxford":{"phon":"ˈstɑːtʃi","pos":"adjective","senses":[{"en":"containing a lot of starch","cn":"富含淀粉的","ex":{"en":"starchy foods like rice and bread","cn":"淀粉类食物，如米饭和面包"}},{"en":"very formal; not friendly or relaxed","cn":"拘束的；古板的；拘泥的","lab":"informal, disapproving，，","ex":{"en":"My boss has a starchy manner.","cn":"我的老板态度刻板。"}}]}},"strain":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"压力;负担;重负","en":"If strain is put on an organization or system, it has to do more than it is able to do.","ex":{"en":"The prison service is already under considerable strain","cn":"监狱系统已经承受了巨大的压力。"}},{"pos":"VERB 动词","cn":"使不堪承受;使紧张","en":"To strain something means to make it do more than it is able to do.","ex":{"en":"The volume of scheduled flights is straining the air traffic control system","cn":"定期航班的数量正让空中交通指挥系统不堪重负。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(精神上的)压力，重负，紧张","en":"Strain is a state of worry and tension caused by a difficult situation.","ex":{"en":"She was tired and under great strain.","cn":"她身心疲惫，压力很大。"}},{"pos":"N-SING 单数名词","cn":"带来压力的情况;造成紧张的因素","en":"If you say that a situation is a strain, you mean that it makes you worried and tense.","ex":{"en":"I sometimes find it a strain to be responsible for the mortgage.","cn":"我有时觉得背负这笔抵押贷款很有压力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"应力;张力;拉力;作用力;压力","en":"Strain is a force that pushes, pulls, or stretches something in a way that may damage it.","ex":{"en":"Place your hands under your buttocks to take some of the strain off your back","cn":"将手放在臀部下面，减轻背部的一些压力。"}},{"pos":"N-VAR 可变名词","cn":"(肌肉的)扭伤，拉伤，劳损","en":"Strain is an injury to a muscle in your body, caused by using the muscle too much or twisting it.","ex":{"en":"Avoid muscle strain by warming up with slow jogging.","cn":"先慢跑热热身，免得拉伤肌肉。"}},{"pos":"VERB 动词","cn":"扭伤，拉伤，损伤(肌肉)","en":"If you strain a muscle, you injure it by using it too much or twisting it.","ex":{"en":"He strained his back during a practice session.","cn":"他在一次锻炼中扭伤了背部。"}},{"pos":"VERB 动词","cn":"努力做;竭力做;费力做事","en":"If you strain to do something, you make a great effort to do it when it is difficult to do.","ex":{"en":"I had to strain to hear","cn":"我不得不使劲去听。"}},{"pos":"VERB 动词","cn":"过滤;滤掉(食物中)的液体","en":"When you strain food, you separate the liquid part of it from the solid parts.","ex":{"en":"Strain the stock and put it back into the pan.","cn":"滤出原汁，将它放回到平底锅中。"}},{"pos":"N-SING 单数名词","cn":"气质;特性;风格;作风","en":"You can use strain to refer to a particular quality in someone's character, remarks, or work.","ex":{"en":"There was a strain of bitterness in his voice.","cn":"他的声音听起来有些愤愤不平。"}},{"pos":"N-COUNT 可数名词","cn":"(病菌的)类型;(植物或其他有机物的)系，品系，品种","en":"A strain of a germ, plant, or other organism is a particular type of it.","ex":{"en":"Every year new strains of influenza develop.","cn":"每年都有新的流感病毒出现。"}},{"pos":"N-PLURAL 复数名词","cn":"旋律;曲调","en":"If you hear the strains of music, you hear music being played.","ex":{"en":"She could hear the tinny strains of a chamber orchestra.","cn":"她能听见室内管弦乐队尖细的旋律。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"damage to part of your body caused by an accident or an attack","cn":""},{"en":"an injury, especially a deep cut in your skin made by a knife, bullet, or bomb","cn":""},{"en":"a small injury made when a sharp object cuts your skin","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v 4 n ","senses":[{"en":"The noun strain is a stretch, effort, or exertion — you can strain your ankle or patience."}]},"collocations":{"phrases":["ADJ. considerable, enormous, great, heavy, real, severe, terrible, tremendous It's a real strain having to get up so early! | slight | incre","VERB + STRAIN be/come under, feel, suffer (from) Television newsreaders come under enormous strain. After weeks of overtime, she was startin","STRAIN + VERB show, take its toll (on sb), tell (on sb) After six weeks of uncertainty, the strain was beginning to take its toll.","PREP. under the ~ The ice gave way under the strain. He broke under the strain of having to work twelve hours a day. | ~ on There's too much","PHRASES a bit of a strain I found it a bit of a strain making conversation with her. | signs of strain After three years, their marriage was","ADJ. bad | slight | back, eye, muscle, thigh, etc.","VERB + STRAIN have, be suffering from | get You'll get eye strain if you don't put the light on. | recover from, shake off Gerrard will play"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdestrain.mp3","us":"media/ldoce/hwd/ame/a/strain1.mp3"},"examples":[{"en":"The transport service cannot cope with the strain of so many additional passengers.","cn":"运输部门无法应对临时增加这么多乘客所带来的紧张局面。"},{"en":"You will learn to cope with the stresses and strains of public life.","cn":"你要学会怎样应付公众人物生活的紧张和辛劳。"}],"oxford":{"phon":"streɪn","pos":"noun","senses":[{"en":"pressure on a system or relationship because great demands are being placed on it","cn":"压力；重负","g":"[uncountable, countable]","sc":"pressure","ex":{"en":"The transport service cannot cope with the strain of so many additional passengers.","cn":"运输部门不堪重负，无法应对大量增加的乘客。"}},{"en":"mental pressure or worry felt by somebody because they have too much to do or manage; something that causes this pressure","cn":"（精神上的）压力，紧张，担忧，重负","g":"[countable, uncountable]","sc":"pressure","ex":{"en":"You will learn to cope with the stresses and strains of public life.","cn":"你要学会应付公众人物生活的紧张和辛劳。"}},{"en":"the pressure that is put on something when a physical force stretches, pushes, or pulls it","cn":"压力；拉力；张力；应力","g":"[uncountable, countable]","sc":"pressure","ex":{"en":"The rope broke under the strain.","cn":"绳子给拉断了。"}},{"en":"an injury to a part of your body, such as a muscle, that is caused by using it too much or by twisting it","cn":"劳损；拉伤；扭伤","g":"[countable, uncountable]","sc":"injury","ex":{"en":"a calf/groin/leg strain","cn":"腿肚子／腹股沟／腿部拉伤"}},{"en":"a particular type of plant or animal, or of a disease caused by bacteria, etc.","cn":"（动、植物的）系，品系，品种；（疾病的）类型","g":"[countable]","sc":"type of plant/animal/disease","ex":{"en":"a new strain of mosquitoes resistant to the poison","cn":"对这种毒药有抗药性的新品种蚊子"}},{"en":"a particular feature of the character of a person or group, or a quality in their manner","cn":"个性特点；性格倾向；秉性","g":"[countable, usually singular]","sc":"in somebody’s character","ex":{"en":"He had a definite strain of snobbery in him.","cn":"他这个人明显有一股势利小人的气味。"}},{"en":"the sound of music being played or sung","cn":"乐曲；曲调；旋律","g":"[countable, usually plural]","lab":"formal","sc":"of music","ex":{"en":"She could hear the strains of Mozart through the window.","cn":"她听见从窗户飘出的莫扎特的旋律。"}},{"en":"to injure yourself or part of your body by making it work too hard","cn":"损伤；拉伤；扭伤","g":"[transitive]","lab":"especially British English","sc":"injure","ex":{"en":"to strain a muscle","cn":"拉伤肌肉"},"pos":"verb"},{"en":"to make an effort to do something, using all your mental or physical strength","cn":"尽力；竭力；使劲","g":"[transitive, intransitive]","sc":"make effort","ex":{"en":"I strained my ears (= listened very hard) to catch what they were saying.","cn":"我竖起耳朵去听他们在说些什么。"},"pos":"verb"},{"en":"to try to make something do more than it is able to do","cn":"过度使用；使不堪承受","g":"[transitive]","sc":"stretch to limit","ex":{"en":"The sudden influx of visitors is straining hotels in the town to the limit.","cn":"游客突然涌入，城里的旅馆全都爆满。"},"pos":"verb"},{"en":"to push hard against something; to pull hard on something","cn":"用力推（或拉）；拉紧","g":"[intransitive]","sc":"push/pull hard","ex":{"en":"She strained against the ropes that held her.","cn":"她使劲挣了挣拴着她的绳子。"},"pos":"verb"},{"en":"to pour food, etc. through something with very small holes in it, for example a sieve, in order to separate the solid part from the liquid part","cn":"滤；过滤","g":"[transitive]","sc":"separate solid from liquid","ex":{"en":"Use a colander to strain the vegetables.","cn":"把蔬菜放在漏筐里控控水。"},"pos":"verb"}]}},"stylized":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非写实的;有艺术效果的","en":"Something that is stylized is shown or done in a way that is not natural in order to create an artistic effect.","ex":{"en":"Some of it has to do with recent stage musicals, which have been very, very stylised.","cn":"其中一些与最近几部有着浓厚艺术气息的舞台音乐剧有关。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"drawn, written, or performed in an artificial style that does not look natural or real, but that is still pleasant to look at 〔","cn":"绘画﹑写作或表演〕非写实的"}]},"vocab":{"pos":"adj","senses":[{"en":"If something is stylized it means it's represented in a non-naturalistic conventional form. The heart-shaped symbol in the popular phrase \"I heart NY,\" for example, is a classic stylized representation of a real heart."}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdestylized.mp3","us":"media/ldoce/hwd/ame/6/laadstylized.mp3"},"examples":[{"en":"the highly stylized form of acting in Japanese theatre","cn":"日本戏剧中高度非写实的表演形式"},{"en":"a stylized drawing of a house","cn":"用非写实手法画的一座房子"}],"oxford":{"phon":"ˈstaɪlaɪzd","pos":"adjective","senses":[{"en":"drawn, written, etc. in a way that is not natural or realistic","cn":"（绘画、写作等手法）非写实的","ex":{"en":"a stylized drawing of a house","cn":"用非写实手法画的一座房子"}}]}},"sturgeon":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"鲟","en":"A sturgeon is a large fish which lives in northern parts of the world. Sturgeon are usually caught for their eggs, which are known as caviar."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large fish, from which caviar is obtained, or the meat of this fish","cn":"鲟（鱼）〔其卵可制鱼子酱〕﹔鲟鱼肉"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41sturgeon.mp3","us":"media/ldoce/hwd/ame/2/sturgeon.mp3"},"oxford":{"phon":"ˈstɜːdʒən","pos":"noun","senses":[{"en":"a large sea and freshwater fish that lives in northern regions. Sturgeon are used for food and the eggs (called caviar) are also eaten.","cn":"鲟"}]}},"stubby":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"短而粗的;矮壮的","en":"An object that is stubby is shorter and thicker than usual.","ex":{"en":"He pointed a stubby finger at a wooden chair opposite him.","cn":"他伸出一根粗短的手指指向他对面的一把木椅。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is short is not as tall as most people","cn":""},{"en":"quite short. This phrase sounds more gentle than saying that someone is short","cn":""},{"en":"short and with a small body","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/stubby0205.mp3","us":"media/ldoce/hwd/ame/0/stubby.mp3"},"examples":[{"en":"stubby fingers","cn":"又短又粗的指头"}],"oxford":{"phon":"ˈstʌbi","pos":"adjective","senses":[{"en":"short and thick","cn":"短而粗的","ex":{"en":"stubby fingers","cn":"又短又粗的手指"}},{"en":"a small, fat bottle of beer usually holding 0.375 litres","cn":"小啤酒瓶（容量通常为 0.375 升）","g":"[countable]","lab":"informal","pos":"noun"},{"en":"a pair of short shorts (= short trousers)","cn":"男式短裤","g":"[plural]","pos":"noun"}]}},"storekeeper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"店主;商店经理","en":"A storekeeper is a shopkeeper."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who owns or manages a shop","cn":"店主﹔管商店的人"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41storekeeper.mp3","us":"media/ldoce/hwd/ame/1/storekeeper.mp3"},"oxford":{"phon":"ˈstɔːkiːpə(r)","pos":"noun","senses":[{"en":"a person who owns or manages a store, usually a small one","cn":"店主：拥有或经营商店的人，通常是一小部分"}]}},"starling":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"椋鸟","en":"A starling is a very common bird with greenish-black feathers covered in pale spots which is found in Europe and North America. Starlings often fly around in large groups."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a common bird with shiny black feathers that lives especially in cities","cn":"椋鸟"}]},"media":{"uk":"media/ldoce/hwd/bre/f/starling0205.mp3","us":"media/ldoce/hwd/ame/0/starling.mp3"},"oxford":{"phon":"ˈstɑːlɪŋ","pos":"noun","senses":[{"en":"a common bird with dark shiny feathers and a noisy call","cn":"椋鸟","ex":{"en":"a flock of starlings","cn":"一群八哥"}}]}},"strategist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指军事)战略家，善于策划的人","en":"A strategist is someone who is skilled in planning the best way to gain an advantage or to achieve success, especially in war.","ex":{"en":"Military strategists had devised a plan that guaranteed a series of stunning victories.","cn":"军事战略家们制订出的计划确保了一连串的辉煌胜利。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is good at planning things, especially military or political actions","cn":"善于策划的人﹔〔尤指军事或政治行动的〕战略家"}]},"vocab":{"pos":"n","senses":[{"en":"That guy who's really good at making a detailed plan for winning at Monopoly? He's a strategist , or an expert at strategy, or planning."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41strategist.mp3","us":"media/ldoce/hwd/ame/7/strategist.mp3"},"oxford":{"phon":"ˈstrætədʒɪst","pos":"noun","senses":[{"en":"a person who shows skill at planning things, especially military activities","cn":"战略家；善于筹划部署的人","ex":{"en":"a military strategist","cn":"军事战略家"}}]}},"stretcher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"担架","en":"A stretcher is a long piece of canvas with a pole along each side, which is used to carry an injured or sick person.","ex":{"en":"The two ambulance attendants quickly put Plover on a stretcher and got him into the ambulance.","cn":"两名救护人员迅速地将普洛弗放到担架上抬进救护车里。"}},{"pos":"V-PASSIVE 被动动词","cn":"用担架抬","en":"If someone is stretchered somewhere, they are carried there on a stretcher.","ex":{"en":"I was close by as Lester was stretchered into the ambulance","cn":"莱斯特被用担架抬进救护车时我就在旁边。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of bed used for carrying someone who is too injured or ill to walk","cn":"担架﹔担架床"},{"en":"to carry someone on a stretcher","cn":"用担架抬送〔某人〕"}]},"media":{"img":["media/ldoce/img/ldoce_321.png"],"uk":"media/ldoce/hwd/bre/8/brelasdestretcher.mp3","us":"media/ldoce/hwd/ame/d/stretcher.mp3"},"examples":[{"en":"He was stretchered off the pitch with a broken leg.","cn":"他腿骨折了，从球场上抬了下去。"},{"en":"He was carried off on a stretcher.","cn":"他被人用担架抬走了。"}],"oxford":{"phon":"ˈstretʃə(r)","pos":"noun","senses":[{"en":"a long piece of strong cloth with a pole on each side, used for carrying somebody who is sick or injured and who cannot walk","cn":"担架","ex":{"en":"He was carried off on a stretcher.","cn":"他被人用担架抬走了。"}},{"en":"a wooden frame over which cloth is spread and pulled tight ready for painting","cn":"担架：木制框架，布在该框架上展开并拉紧，准备绘画","ex":{"en":"Staple the canvas to the stretchers, prime it with ochre, then you're ready to paint.","cn":"将画布钉在担架上，涂上赭色底漆，然后就可以开始绘画了。"}},{"en":"to carry somebody somewhere on a stretcher","cn":"用担架抬","ex":{"en":"He was stretchered off the pitch with a broken leg.","cn":"他腿骨折了，从球场上抬了下去。"},"pos":"verb"}]}},"stickler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"坚持…的人","en":"If you are a stickler for something, you always demand or require it.","ex":{"en":"I'm a bit of a stickler for accuracy","cn":"我总是要求精确。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is strict makes people obey rules and refuses to let people disobey them - use this especially about parents, teachers, or organizations","cn":""},{"en":"if you are firm with someone, you tell them that they must accept what you say because you are not going to change it","cn":""},{"en":"determined that your orders or decisions will be obeyed, especially in order to make sure a situation or someone's progress improves - use this especially when you think that someone is right to be strict","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A stickler is someone who insists that things are done in a certain way. Say you’re getting married and want to write your own vows, but your partner’s mother demands that you have a traditional ceremony. The mother is a stickler for tradition."}]},"media":{"uk":"media/ldoce/hwd/bre/d/stickler0205.mp3","us":"media/ldoce/hwd/ame/1/stickler.mp3"},"examples":[{"en":"a stickler for punctuality","cn":"非常注重守时的人"}],"oxford":{"phon":"ˈstɪklə(r)","pos":"noun","senses":[{"en":"a person who thinks that a particular quality or type of behaviour is very important and expects other people to think and behave in the same way","cn":"非常看重（某品质或行为）的人","ex":{"en":"a stickler for punctuality","cn":"非常注重守时的人"}}]}},"streamer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"装饰彩纸条;彩带","en":"Streamers are long rolls of coloured paper used for decorating rooms at parties."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long narrow piece of coloured paper, used for decoration on special occasions 〔","cn":"装饰用的〕彩色纸带﹐饰带"},{"en":"a long narrow flag","cn":"横幅﹔长条旗"}]},"media":{"uk":"media/ldoce/hwd/bre/0/streamer0205.mp3","us":"media/ldoce/hwd/ame/7/streamer.mp3"},"oxford":{"phon":"ˈstriːmə(r)","pos":"noun","senses":[{"en":"a long, narrow piece of coloured paper, used to decorate a place for a party or other celebration","cn":"装饰彩纸条","ex":{"en":"The room was decorated with balloons and streamers.","cn":"房间里装饰着气球和彩带。"}},{"en":"a long, narrow piece of cloth or other material","cn":"条幅；横幅"}]}},"sterilize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"对…作灭菌(或消毒)处理","en":"If you sterilize a thing or a place, you make it completely clean and free from germs.","ex":{"en":"Sulphur is also used to sterilize equipment","cn":"硫也可用来给器材消毒。"}},{"pos":"VERB 动词","cn":"使绝育","en":"If a person or an animal is sterilized, they have a medical operation that makes it impossible for them to have or produce babies.","ex":{"en":"My wife was sterilized after the birth of her fourth child.","cn":"我妻子生完第4个孩子后做了绝育手术。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the practice of keeping yourself and the place where you live or work clean, so that diseases cannot spread","cn":""},{"en":"to use chemicals to clean a place, a piece of equipment, or a wound, in order to prevent disease","cn":""},{"en":"to make something safe to use by heating it or using chemicals, in order to kill all bacteria and prevent disease - use this about medical or scientific equipment, or babies' bottles","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"When you sterilize something, you make it completely clean and free from any contaminant. It's important to sterilize tools, hands, and furniture in hospitals so germs don't get spread between patients."}]},"media":{"uk":"media/ldoce/hwd/bre/5/sterilize0205.mp3","us":"media/ldoce/hwd/ame/7/sterilize.mp3"},"examples":[{"en":"to sterilize surgical instruments","cn":"给外科手术器械消毒"},{"en":"sterilized milk/water","cn":"消过毒的牛奶/水"}],"oxford":{"phon":"ˈsterəlaɪz","pos":"verb","senses":[{"en":"to kill the bacteria in or on something","cn":"灭菌；消毒","g":"[often passive]","ex":{"en":"to sterilize surgical instruments","cn":"给外科手术器械消毒"}},{"en":"to make a person or an animal unable to have babies, especially by removing or blocking their sex organs","cn":"使绝育","g":"[usually passive]"}]}},"stopcock":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"活塞;活栓;旋塞阀","en":"A stopcock is a tap on a pipe, which you turn in order to allow something to pass through the pipe or to stop it from passing through."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tap that controls the flow of a liquid or gas through a pipe 〔","cn":"控制管道中液体或气体流量的〕管闩﹐活栓﹐阀门"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41stopcock.mp3","us":"media/ldoce/hwd/ame/d/stopcock.mp3"},"oxford":{"phon":"ˈstɒpkɒk","pos":"noun","senses":[{"en":"a tap that controls the flow of liquid or gas through a pipe","cn":"（调节管道流量的）旋塞，活栓","ex":{"en":"If you have a burst pipe, turn off the stopcock immediately.","cn":"如果管道爆裂，请立即关闭旋塞阀。"}}]}},"stringy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)多筋的，纤维多而不嫩的，柴的","en":"Stringy food contains long, thin pieces that are difficult or unpleasant to eat.","ex":{"en":"The meat was stringy","cn":"这肉嚼不烂。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)干枯的，稀疏的","en":"Stringy hair is thin and unattractive.","ex":{"en":"...an enormously fat man with long, stringy gray hair.","cn":"留着稀疏的灰白长发、身形臃肿的男子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"stringy meat, fruit, or vegetables are full of long thin pieces that are difficult to eat 〔","cn":"肉﹑水果或蔬菜〕纤维多的，有筋的"},{"en":"stringy hair is very thin and looks like string, especially because it is dirty 〔","cn":"尤指毛发因脏而〕细长而稀疏的﹐呈一缕缕的"},{"en":"tall and thin","cn":"瘦长的﹐青筋毕露的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stringy.mp3","us":"media/ldoce/hwd/ame/f/stringy.mp3"},"examples":[{"en":"a stringy neck","cn":"瘦得青筋毕露的脖子"},{"en":"tough, stringy meat","cn":"又老筋又多的肉"}],"oxford":{"phon":"ˈstrɪŋi","pos":"adjective","senses":[{"en":"long and thin and looking as if it has not been washed","cn":"细长而干枯的；细长而稀疏的"},{"en":"containing long thin pieces like string and difficult to chew","cn":"多筋的；纤维多而不嫩的；柴的","ex":{"en":"tough, stringy meat","cn":"又老筋又多的肉"}},{"en":"thin so that you can see the muscles","cn":"瘦得露出筋的","ex":{"en":"a stringy neck","cn":"瘦得青筋毕露的脖子"}}]}},"starry-eyed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满幻想的;想入非非的;不切实际的","en":"If you say that someone is starry-eyed, you mean that they have such a positive or hopeful view of a situation that they do not see what it is really like.","ex":{"en":"I'm not starry-eyed about Europe.","cn":"我对欧洲没抱什么幻想。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happy and hopeful about things in a way that is silly or unrealistic","cn":"过分乐观的﹔不切实际的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/starry_eyed0205.mp3","us":"media/ldoce/hwd/ame/8/starry-eyed.mp3"},"oxford":{"phon":"ˌstɑːri ˈaɪd","pos":"adjective","senses":[{"en":"full of emotion, hopes or dreams about somebody/something in a way that is not realistic","cn":"天真的；空想的","ex":{"en":"a starry-eyed plan","cn":"不切实际的计划"}}]}},"standardize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使标准化;使合乎标准","en":"To standardize things means to change them so that they all have the same features.","ex":{"en":"There is a drive both to standardise components and to reduce the number of models on offer","cn":"正在为实现零部件标准化和减少推出的型号数量而努力。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make sure that a particular type of product, service, activity etc is always made or done in exactly the same way","cn":""},{"en":"to change something such as a rule or system so that it is the same as another generally accepted rule or system","cn":""},{"en":"to make all the things of one particular type the same as each other","cn":"使标准化[统一规格]"}]},"vocab":{"pos":"v","senses":[{"en":"To standardize something is to make it fit a certain guideline or requirement. If a school decides to standardize its grading system, it makes sure every teacher gives grades in exactly the same way."}]},"media":{"uk":"media/ldoce/hwd/bre/9/standardize0205.mp3","us":"media/ldoce/hwd/ame/e/standardize.mp3"},"examples":[{"en":"a standardized contract/design/test","cn":"标准化合同/设计/考试"},{"en":"the standardization of components","cn":"部件的标准化"}],"oxford":{"phon":"ˈstændədaɪz","pos":"verb","senses":[{"en":"to make objects or activities of the same type have the same features or qualities; to make something standard","cn":"使标准化；使符合标准（或规格）","ex":{"en":"a standardized contract/design/test","cn":"标准化合同／设计／考试"}}]}},"staid":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"严肃的;无聊的;古板的","en":"If you say that someone or something is staid, you mean that they are serious, dull, and rather old-fashioned.","ex":{"en":"...a staid seaside resort.","cn":"了无生气的海滨度假胜地"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"serious, old-fashioned, and boring","cn":"严肃呆板的﹔古板的﹔枯燥的"}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is staid is dignified, respectable — possibly even boring, like a staid dinner party that is heavy on the important guests but light on the laughs."}]},"collocations":{"phrases":["VERBS be, feel, look, seem | become, get, grow He had grown staid and dull.","ADV. positively, very The locals were a very staid lot. | rather a rather staid and old-fashioned hotel"]},"media":{"uk":"media/ldoce/hwd/bre/b/staid0205.mp3","us":"media/ldoce/hwd/ame/c/staid.mp3"},"examples":[{"en":"a staid old bachelor","cn":"一个古板的老光棍"}],"oxford":{"phon":"steɪd","pos":"adjective","senses":[{"en":"not fun or interesting; boring and old-fashioned","cn":"没意思的；古板的；一本正经的","ex":{"en":"The museum is trying to get rid of its staid image.","cn":"这家博物馆正努力摆脱古板的形象。"}}]}},"stringer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"特约记者","en":"A stringer is a journalist who is employed part-time by a newspaper or news service in order to report on a particular area.","ex":{"en":"He picked up extra money as a local stringer for the New York Herald.","cn":"他做《纽约先驱报》的当地特约记者来赚些外快。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who regularly sends in news stories to a newspaper, but who is not employed by that newspaper","cn":"特约记者[通讯员]"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41stringer.mp3","us":"media/ldoce/hwd/ame/7/stringer.mp3"},"oxford":{"phon":"ˈstrɪŋə(r)","pos":"noun","senses":[{"en":"a journalist who is not on the regular staff of a newspaper, but who often supplies stories for it","cn":"特约记者"}]}},"stardom":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"明星地位(或身份)","en":"Stardom is the state of being very famous, usually as an actor, musician, or sports player.","ex":{"en":"In 1929 she shot to stardom on Broadway in a Noel Coward play.","cn":"1929 年，她因出演诺埃尔·科沃德的一部剧而在百老汇一炮走红。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the success and attention people get when they are famous","cn":""},{"en":"when someone is very famous, especially in music, films, or sport","cn":""},{"en":"fame and admiration that someone has because of something good such as great skill, knowledge, or bravery","cn":""}]},"collocations":{"phrases":["ADJ. Hollywood, international","VERB + STARDOM achieve, rise to, rocket to, shoot (sb) to Her number one single shot her to stardom. | be tipped for This young tennis playe","PHRASES sb's rise to stardom her meteoric rise to stardom | the road to stardom He set out on the lonely road to stardom early in life."]},"media":{"uk":"media/ldoce/hwd/bre/f/stardom0205.mp3","us":"media/ldoce/hwd/ame/9/stardom.mp3"},"examples":[{"en":"She shot to stardom in a Broadway musical.","cn":"她在一部百老汇音乐剧中一炮而红。"},{"en":"The group is being tipped for stardom (= people say they will be famous).","cn":"这支乐队被誉为明日之星。"}],"oxford":{"phon":"ˈstɑːdəm","pos":"noun","senses":[{"en":"the state of being famous as an actor, a singer, etc.","cn":"明星的地位（或身份）","ex":{"en":"The group is being tipped for stardom (= people say they will be famous).","cn":"这支乐队被誉为明日之星。"}}]}},"stonemason":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"石匠;石工","en":"A stonemason is a person who is skilled at cutting and preparing stone so that it can be used for walls and buildings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is cutting stone into pieces to be used in buildings","cn":"石匠﹐石工"}]},"media":{"uk":"media/ldoce/hwd/bre/7/stonemason0205.mp3","us":"media/ldoce/hwd/ame/3/stonemason.mp3"},"oxford":{"phon":"ˈstəʊnmeɪsn","pos":"noun","senses":[{"en":"a person whose job is cutting and preparing stone for buildings","cn":"石工；石匠"}]}},"streetcar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有轨电车","en":"A streetcar is an electric vehicle for carrying people which travels on rails in the streets of a town."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of bus that runs on electricity along metal tracks in the road","cn":"有轨电车"}]},"media":{"uk":"media/ldoce/hwd/bre/0/streetcar0205.mp3","us":"media/ldoce/hwd/ame/6/streetcar.mp3"},"oxford":{"phon":"ˈstriːtkɑː(r)","pos":"noun","senses":[{"en":"a vehicle driven by electricity, that runs on rails along the streets of a town and carries passengers","cn":"有轨电车"}]}},"stoned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(吸毒后)飘飘然的，神志恍惚的","en":"If someone is stoned, their mind is greatly affected by a drug such as cannabis."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling very excited, happy, and full of energy because of the effects of a drug","cn":""},{"en":"feeling very relaxed or happy and not able to behave normally because of the effect of a drug","cn":""},{"en":"feeling very excited and nervous as a result of taking a drug","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdestoned.mp3","us":"media/ldoce/hwd/ame/1/stoned.mp3"},"oxford":{"phon":"stəʊnd","pos":"adjective","senses":[{"en":"not behaving or thinking normally because of the effects of a drug such as marijuana or alcohol","cn":"（在毒品或酒精作用下）晕晕乎乎，飘飘然"}]}},"stairwell":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"楼梯井","en":"The stairwell is the part of a building that contains the staircase."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the space going up through all the floors of a building, where the stairs go up","cn":"楼梯井〔指建筑物内楼梯所占的空间〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41stairwell.mp3","us":"media/ldoce/hwd/ame/b/stairwell.mp3"},"oxford":{"phon":"ˈsteəwel","pos":"noun","senses":[{"en":"the space in a building in which the stairs are built","cn":"楼梯井（建筑物内楼梯占用的空间）"}]}},"stifle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扼杀;压制;抑止","en":"If someone stifles something you consider to be a good thing, they prevent it from continuing.","ex":{"en":"Regulations on children stifled creativity","cn":"给孩子们定的各种规矩扼杀了他们的创造力。"}},{"pos":"VERB 动词","cn":"克制住，忍住(哈欠、笑)","en":"If you stifle a yawn or laugh, you prevent yourself from yawning or laughing.","ex":{"en":"She makes no attempt to stifle a yawn","cn":"她忍不住打了个哈欠。"}},{"pos":"VERB 动词","cn":"克制;压抑","en":"If you stifle your natural feelings or behaviour, you prevent yourself from having those feelings or behaving in that way.","ex":{"en":"It is best to stifle curiosity and leave birds' nests alone","cn":"最好能克制住好奇心，不要去碰鸟巢。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try hard to stop yourself laughing, crying, or showing anger","cn":""},{"en":"to try to stop yourself showing that you are tired, amused etc especially because you do not want to seem rude","cn":""},{"en":"to make a strong effort to stop yourself from showing feelings of anger, sadness etc","cn":""}]},"vocab":{"pos":"1 v 2 n 3 v","senses":[{"en":"To stifle is to cut off, hold back, or smother. You may stifle your cough if you don't want to interrupt a lecture or you may stifle the competition if you fear losing."}]},"media":{"uk":"media/ldoce/hwd/bre/c/stifle0205.mp3","us":"media/ldoce/hwd/ame/b/stifle.mp3"},"examples":[{"en":"‘ It's stifling in here — can we open a window?’ “","cn":"这里闷得人难受，我们能不能开一扇窗户？”"},{"en":"I felt I was stifling in the airless room.","cn":"在那间闷气的房间里我感觉都快憋死了。"}],"oxford":{"phon":"ˈstaɪfl","pos":"verb","senses":[{"en":"to prevent something from happening; to prevent a feeling from being expressed","cn":"压制；扼杀；阻止；抑制","g":"[transitive]","ex":{"en":"She managed to stifle a yawn.","cn":"她忍住了哈欠。"}},{"en":"to feel unable to breathe, or to make somebody unable to breathe, because it is too hot and/or there is no fresh air","cn":"（使）窒息，无法自如地呼吸，感觉窒闷","g":"[intransitive, transitive]","ex":{"en":"I felt I was stifling in the airless room.","cn":"在那间闷气的房间里我感觉都快憋死了。"}}]}},"stock-still":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"静止的;一动不动的","en":"If someone stands or sits stock-still, they do not move at all.","ex":{"en":"The lieutenant stopped and stood stock-still.","cn":"上尉停住了，站着一动不动。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"not moving at all","cn":"静止﹐一动不动"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41stock-still.mp3","us":"media/ldoce/hwd/ame/3/laadstock-still.mp3"},"examples":[{"en":"We stood stock-still watching the animals.","cn":"我们一动不动地站着观看那些动物。"},{"en":"Oscar stood stock-still and listened.","cn":"奥斯卡站在那儿一动不动地听着。"}],"oxford":{"phon":"ˌstɒk ˈstɪl","pos":"adverb","senses":[{"en":"without moving at all","cn":"静止地；一动不动地","ex":{"en":"He stood stock-still, hardly daring to breathe.","cn":"他一动不动地站着，几乎不敢呼吸。"}}]}},"straggler":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"掉队者;落伍者;拖后腿的人","en":"The stragglers are the people in a group who are moving more slowly or making less progress than the others.","ex":{"en":"There were two stragglers twenty yards back","cn":"两名掉队者落后了 20 码。"}},{"pos":"N-COUNT 可数名词","cn":"(某项活动中)留到最后的人","en":"The stragglers at an event such as a party are the people who are still there after most of the other people have left.","ex":{"en":"...round about two o'clock in the morning when there were only a few stragglers left.","cn":"大约在凌晨两点钟只剩下几个人时"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to finish a race or competition in the last position","cn":""},{"en":"to be last in a line or group of people, cars, ships etc that is moving forward","cn":""},{"en":"a person who is too slow to keep the same speed as the rest of the group they are with, so that they move along some distance behind","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/straggler0205.mp3","us":"media/ldoce/hwd/ame/0/laadstraggler.mp3"},"examples":[{"en":"Wait for the stragglers to catch up.","cn":"等那些掉队的人赶上来。"}],"oxford":{"phon":"ˈstræɡlə(r)","pos":"noun","senses":[{"en":"a person or an animal that is among the last or the slowest in a group to do something, for example, to finish a race or leave a place","cn":"落伍者；掉队者；落在最后的人（或动物）","ex":{"en":"The tour guide came back for the stragglers who were still taking pictures.","cn":"导游回来接那些还在拍照的掉队者。"}}]}},"stupor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指由于醉酒或吸毒而出现的)神志不清，恍惚，不省人事","en":"Someone who is in a stupor is almost unconscious and is unable to act or think normally, especially as a result of drink or drugs.","ex":{"en":"He fell back onto the sofa in a drunken stupor","cn":"他烂醉如泥，瘫倒在沙发上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a state in which you cannot think, speak, see, or hear clearly, usually because you have drunk too much alcohol or taken drugs 〔","cn":"尤因过量喝酒或吸毒引起的〕昏迷﹐恍惚﹐不省人事"}]},"vocab":{"pos":"n","senses":[{"en":"A person in a stupor is considered barely conscious or stunned; or, if you consult Led Zeppelin lyrics: dazed and confused."}]},"collocations":{"phrases":["ADJ. drunken","VERB + STUPOR drink yourself into, fall into, go into, sink into As the whisky took effect, he gradually fell into a drunken stupor. | come ","PREP. in a ~ He fell to the groun d in a stupor ."]},"media":{"uk":"media/ldoce/hwd/bre/9/stupor0205.mp3","us":"media/ldoce/hwd/ame/d/stupor.mp3"},"examples":[{"en":"He drank himself into a stupor.","cn":"他喝得烂醉。"},{"en":"a drunken stupor","cn":"酩酊大醉"}],"oxford":{"phon":"ˈstjuːpə(r)","pos":"noun","senses":[{"en":"a state in which you are unable to think, hear, etc. clearly, especially because you have drunk too much alcohol, taken drugs or had a shock","cn":"（尤指由于醉酒、吸毒或惊吓而出现的）神志不清，恍惚，麻痹状态","ex":{"en":"He drank himself into a stupor.","cn":"他喝得烂醉。"}}]}},"stroppy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易怒难处的;性情暴躁的;脾气坏的","en":"Someone who is stroppy is bad-tempered and gets angry or upset with people.","ex":{"en":"A mother I knew was going through a really unpleasant time with a stroppy teenage son","cn":"我认识的一位母亲因为十几岁的儿子脾气暴躁、任性叛逆而过得很不开心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to suddenly become angry, especially after you have been trying not to","cn":""},{"en":"to suddenly become very angry","cn":""},{"en":"to suddenly become very angry","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/stroppy0205.mp3","us":"media/ldoce/hwd/ame/a/ld41stroppy.mp3"},"examples":[{"en":"Don't get stroppy with me — it isn't my fault!","cn":"别冲我生气，这不是我的错！"},{"en":"I try not to get stroppy, but sometimes I just can’t help it.","cn":"我尽量不让自己生气﹐但有时就是忍不住。"}],"oxford":{"phon":"ˈstrɒpi","pos":"adjective","senses":[{"en":"easily annoyed and difficult to deal with","cn":"动辄生气的；性情暴躁的；易怒难处的","ex":{"en":"Don't get stroppy with me—it isn't my fault!","cn":"别冲我生气，这不是我的错！"}}]}},"stipulate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"规定;明确要求","en":"If you stipulate a condition or stipulate that something must be done, you say clearly that it must be done.","ex":{"en":"She could have stipulated that she would pay when she collected the computer","cn":"她本可以要求她来取电脑时付钱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if an agreement, law, or rule stipulates something, it must be done 〔","cn":"协议﹑法律﹑规则等〕规定﹐约定"}]},"vocab":{"pos":"v","senses":[{"en":"To stipulate something means to demand that it be part of an agreement. So when you make a contract or deal, you can stipulate that a certain condition must be met."}]},"media":{"uk":"media/ldoce/hwd/bre/8/stipulate0205.mp3","us":"media/ldoce/hwd/ame/8/stipulate.mp3"},"examples":[{"en":"The only stipulation is that the topic you choose must be related to your studies.","cn":"唯一的要求是所选的题目必须与你的研究科目有关。"},{"en":"The job advertisement stipulates that the applicant must have three years' experience.","cn":"招聘广告明确要求应聘者必须有三年工作经验。"}],"oxford":{"phon":"ˈstɪpjuleɪt","pos":"verb","senses":[{"en":"to state clearly and definitely that something must be done, or how it must be done","cn":"规定；明确要求","ex":{"en":"A delivery date is stipulated in the contract.","cn":"合同中规定了交货日期。"}}]}},"steepen":{"collins":{"senses":[{"pos":"VERB 动词","cn":"变得陡峭;变得陡直","en":"If a slope or an angle steepens, it becomes steeper.","ex":{"en":"The road steepened and then levelled out suddenly.","cn":"路变得陡直起来，然后又突然变平坦了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a slope, road etc steepens, or if something steepens it, it becomes steeper （","cn":"使）变得陡峭"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41steepen.mp3","us":"media/ldoce/hwd/ame/f/steepen.mp3"},"examples":[{"en":"After a mile, the slope steepened.","cn":"过了一英里后，山坡变陡了。"}],"oxford":{"phon":"ˈstiːpən","pos":"verb","senses":[{"en":"to become or to make something become steeper","cn":"（使）变陡","ex":{"en":"After a mile, the slope steepened.","cn":"过了一英里后，山坡变陡了。"}}]}},"step-by-step":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a step-by-step plan, method etc explains or does something carefully and in a particular order","cn":"一步接着一步的﹐循序渐进的"},{"en":"step-by-step guide/approach/instructions etc a step-by-step guide to making it in the music business","cn":"对如何在音乐界获得成功的循序渐进的指导"}]},"media":{"uk":"media/ldoce/hwd/bre/0/step_by_step0205.mp3","us":"media/ldoce/hwd/ame/9/laadstep-by-step.mp3"}},"statute":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"成文法;法令;法规","en":"A statute is a rule or law which has been made by a government or other organization and formally written down.","ex":{"en":"The new statute covers the care for, bringing up and protection of children","cn":"新法令涵盖了儿童保育、养育和保护的相关内容。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instruction that says what people are allowed to do or not allowed to do, for example in a game, school, or company","cn":""},{"en":"an official rule that everyone in a country, city, or state must obey","cn":""},{"en":"an official rule or order, which is part of a set of rules made by a government or organization","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A statute is a formal law or rule. Whether it's enacted by a government, company, or other organization, a statute is typically written down."}]},"collocations":{"phrases":["ADJ. legal | federal, parliamentary | criminal","VERB + STATUTE pass | comply with","STATUTE + NOUN law the obligations of the employer in common and statute law | book This archaic law remained on the statute books until las","PREP. by ~ Local authorities are required by statute to provide care homes for the elderly. | under (a/the) ~ a trading company formed under"]},"media":{"uk":"media/ldoce/hwd/bre/2/statute0205.mp3","us":"media/ldoce/hwd/ame/9/statute.mp3"},"examples":[{"en":"Under the statutes of the university they had no power to dismiss him.","cn":"按大学的规章制度，校方无权开除他。"},{"en":"Penalties are laid down in the statute.","cn":"法规中有关于惩罚措施的规定。"}],"oxford":{"phon":"ˈstætʃuːt","pos":"noun","senses":[{"en":"a law that is passed by a parliament, council, etc. and formally written down","cn":"成文法；法令；法规","g":"[countable, uncountable]","ex":{"en":"Penalties are laid down in the statute.","cn":"法规中有关于惩罚措施的规定。"}},{"en":"a formal rule of an organization or institution","cn":"章程；条例；规程","g":"[countable]","ex":{"en":"Under the statutes of the university they had no power to dismiss him.","cn":"按大学的规章制度，校方无权开除他。"}}]}},"strand":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(头发、电线或纱线等的)股，缕","en":"A strand of something such as hair, wire, or thread is a single thin piece of it.","ex":{"en":"She tried to blow a gray strand of hair from her eyes.","cn":"她竭力想把眼前的一缕白发吹开。"}},{"pos":"N-COUNT 可数名词","cn":"(计划或理论的)部分，方面","en":"A strand of a plan or theory is a part of it.","ex":{"en":"There had been two strands to his tactics","cn":"他的策略分两个部分。"}},{"pos":"VERB 动词","cn":"(坏天气等)使滞留，使搁浅","en":"If you are stranded, you are prevented from leaving a place, for example because of bad weather.","ex":{"en":"The climbers had been stranded by a storm","cn":"登山者被暴风雨困住了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a single thin piece of thread, wire, hair etc 〔","cn":"线﹑绳﹑毛发等的〕股﹐缕"},{"en":"one of the parts of a story, idea, plan etc 〔","cn":"故事﹑观点﹑计划等的〕部分"}]},"vocab":{"pos":"1 n 2 v n","senses":[{"en":"A single hair, a noodle, even a line of thought — any of these things could be called a strand , a long thin length of something."}]},"collocations":{"phrases":["ADJ. long | thick, thin | loose | single","VERB + STRAND twist (together), weave (together) She wove the four coloured strands together into a ribbon.","PREP. ~ of a loose strand of hair 2 one part of a story, idea, etc.","ADJ. important, main | different, distinct, separate, various At the end, all the different strands of the story are brought together.","VERB + STRAND bring together, draw together, pull together, weave together | disentangle, unravel","STRAND + VERB come together","PREP. ~ to There are three main strands to the policy. | ~ in/within There are various strands in feminist thinking.","PHRASES strands of opinion/thought"]},"media":{"uk":"media/ldoce/hwd/bre/5/strand0205.mp3","us":"media/ldoce/hwd/ame/3/strand1.mp3"},"examples":[{"en":"The author draws the different strands of the plot together in the final chapter.","cn":"作者在最后一章把不同的情节线索归拢到了一起。"},{"en":"The strike left hundreds of tourists stranded at the airport.","cn":"这场罢工使成百上千的游客滞留在机场。"}],"oxford":{"phon":"strænd","pos":"noun","senses":[{"en":"a single thin piece of thread, wire, hair, etc.","cn":"（线、绳、金属线、毛发等的）股，缕","ex":{"en":"He pulled at a loose strand of wool in his sweater.","cn":"他拉扯毛衣里的一缕松散的羊毛。"}},{"en":"one of the different parts of an idea, a plan, a story, etc.","cn":"（观点、计划、故事等的）部分，方面","ex":{"en":"We heard every strand of political opinion.","cn":"各派的政治观点我们都听到了。"}},{"en":"the land along the edge of the sea or ocean, or of a lake or river","cn":"（海洋、湖或河的）岸，滨","lab":"literary or Irish English"},{"en":"to leave somebody in a place from which they have no way of leaving","cn":"使滞留","ex":{"en":"The strike left hundreds of tourists stranded at the airport.","cn":"这场罢工使成百上千的游客滞留在机场。"},"pos":"verb"},{"en":"to make a boat, fish, whale, etc. be left on land and unable to return to the water","cn":"使搁浅","ex":{"en":"The ship was stranded on a sandbank.","cn":"船在沙洲上搁浅了。"},"pos":"verb"}]}},"streamlined":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"流线型的","en":"A streamlined vehicle, animal, or object has a shape that allows it to move quickly or efficiently through air or water.","ex":{"en":"...these beautifully streamlined and efficient cars.","cn":"这些漂亮的流线型高性能汽车"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make the processes of a business or system simpler so that it operates more quickly and more efficiently","cn":""},{"en":"to make a business or system more efficient by making it quicker, more modern, and less wasteful","cn":""},{"en":"to make something better","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that works better because it's been made more efficient or modern is streamlined . Your streamlined system for printing flyers advertising your yard sale means you can print them much faster than before."}]},"media":{"uk":"media/ldoce/hwd/bre/6/streamline0205.mp3","us":"media/ldoce/hwd/ame/3/streamline.mp3"},"examples":[{"en":"efforts to streamline the production process","cn":""},{"en":"All these new cars have been streamlined.","cn":""}]},"stuffy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或组织机构)一本正经的，古板的，保守的","en":"Stuffy people or institutions are formal and old-fashioned.","ex":{"en":"Why were grown-ups always so stuffy and slow to recognize good ideas?","cn":"为什么成年人总是那么一本正经，对好点子反应那么迟缓呢？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"通风不畅的;闷热的;空气不新鲜的","en":"If it is stuffy in a place, it is unpleasantly warm and there is not enough fresh air.","ex":{"en":"It was hot and stuffy in the classroom.","cn":"教室里很闷热。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(鼻子)不通的，堵塞的","en":"If you have a stuffy nose, your nose is blocked, usually because you have a cold.","ex":{"en":"Aromatic capsules are great for easing the discomfort of a stuffy nose.","cn":"芳香胶囊对缓解鼻塞有奇效。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a room or building that is stuffy does not have enough fresh air, often because it is small or there are too many people in it","cn":""},{"en":"a room or building that is airless feels like it does not have enough air in it for you to breathe properly","cn":""},{"en":"very hot and uncomfortable, and without enough air for you to breathe properly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/stuffy0205.mp3","us":"media/ldoce/hwd/ame/6/stuffy.mp3"},"examples":[{"en":"It gets very hot and stuffy in here in summer.","cn":"这里夏天很热很闷。"},{"en":"a stuffy, formal family","cn":"一本正经而又古板的一家人"}],"oxford":{"phon":"ˈstʌfi","pos":"adjective","senses":[{"en":"warm in an unpleasant way and without enough fresh air","cn":"闷热的；闷人的；通风不畅的","ex":{"en":"a stuffy room","cn":"闷热的房间"}},{"en":"very serious, formal, boring or old-fashioned","cn":"一本正经的；古板的；无聊的；保守的","lab":"informal, disapproving，，","ex":{"en":"a stuffy, formal family","cn":"一本正经而又古板的一家人"}},{"en":"if you have a stuffy nose, your nose is blocked because you have a cold","cn":"（鼻子）不通的，堵住的；鼻塞的","lab":"especially North American English"}]}},"stagecoach":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"驿站马车","en":"Stagecoaches were large carriages pulled by horses which carried passengers and mail."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a vehicle pulled by horses that was used in past times for carrying passengers and letters 〔","cn":"旧时的〕驿马车"}]},"media":{"uk":"media/ldoce/hwd/bre/4/stagecoach0205.mp3","us":"media/ldoce/hwd/ame/7/stagecoach.mp3"},"oxford":{"phon":"ˈsteɪdʒkəʊtʃ","pos":"noun","senses":[{"en":"a large carriage pulled by horses that was used in the past to carry passengers, and often mail, along a regular route","cn":"（旧时的）驿站马车，公共马车","ex":{"en":"Stagecoaches were often attacked by robbers and bandits.","cn":"驿马车经常遭到强盗和强盗的袭击。"}}]}},"stimulative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有刺激作用的;激励性的","en":"If a government policy has a stimulative effect on the economy, it encourages the economy to grow.","ex":{"en":"It is possible that a tax cut might have some stimulative effect.","cn":"减税或许会产生某种刺激作用——这是可能的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to encourage or help an activity to begin or develop further","cn":""},{"en":"to encourage someone by making them excited about and interested in something","cn":""},{"en":"to make a plant or part of the body become active or stronger","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/stimulate0205.mp3","us":"media/ldoce/hwd/ame/9/stimulate.mp3"},"examples":[{"en":"the president’s plan to stimulate economic growth","cn":""},{"en":"Her interest in art was stimulated by her father.","cn":""}]},"stow":{"collins":{"senses":[{"pos":"VERB 动词","cn":"保存;妥善放置","en":"If you stow something somewhere, you carefully put it there until it is needed.","ex":{"en":"I helped her stow her bags in the boot of the car","cn":"我帮她将包放进汽车行李箱里。"}},{"pos":"","cn":"","en":"相关词组：stow away"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go somewhere where you cannot be easily found or seen","cn":""},{"en":"to go to a safe place where you can hide for a long time because you are in danger or because the police are looking for you","cn":""},{"en":"to hide from people who are trying to catch you, and to make sure you do not attract any attention until it is safe to come out","cn":""}]},"collocations":{"phrases":["ADV. carefully, neatly, safely | away","PREP. in The luggage was now safely stowed away in the back of the truck."]},"media":{"uk":"media/ldoce/hwd/bre/8/stow0205.mp3","us":"media/ldoce/hwd/ame/e/stow.mp3"},"examples":[{"en":"She found a seat, stowed her backpack and sat down.","cn":"她找到一个座位，把背包放好，坐了下来。"},{"en":"I stowed my bag under the seat.","cn":"我把包收好放到座位底下。"}],"oxford":{"phon":"stəʊ","pos":"verb","senses":[{"en":"to put something in a safe place","cn":"妥善放置；把…收好","ex":{"en":"She found a seat, stowed her backpack and sat down.","cn":"她找到一个座位，把背包放好，坐了下来。"}}]}},"streetlight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"街灯;路灯","en":"A streetlight is a tall post with a light at the top, which stands by the side of a road to light it up, usually in a town.","ex":{"en":"As the day darkened the streetlights came on.","cn":"天色渐暗，街灯亮了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light at the top of a tall post in the street","cn":"街灯﹐路灯"}]},"media":{"img":["media/ldoce/img/lamp_post.jpg"],"uk":"media/ldoce/hwd/bre/f/streetlight0205.mp3","us":"media/ldoce/hwd/ame/5/laadstreetlight.mp3"}},"stomachache":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"pain in your stomach or near your stomach","cn":"胃痛﹔肚子痛"},{"en":"pain or uncomfortable feelings that you get when your stomach cannot break down food that you have eaten","cn":""},{"en":"a stomach illness caused by eating food that contains harmful bacteria, so that you vomit","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41stomachache.mp3","us":"media/ldoce/hwd/ame/2/stomachache.mp3"}},"stylised":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"stockholder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"股东;持股人","en":"A stockholder is a person who owns shares in a company."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who owns stock s in a business","cn":"股票持有人﹐股东"}]},"vocab":{"pos":"n","senses":[{"en":"A stockholder is someone who has shares in a company. Stockholders own a piece of that company. If you’re a stockholder in the latest, greatest, financially sound new start-up company, your stock is probably worth a lot of money!"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41stockholder.mp3","us":"media/ldoce/hwd/ame/3/stockholder.mp3"},"oxford":{"phon":"ˈstɒkhəʊldə(r)","pos":"noun","senses":[{"en":"a person who owns stocks and shares in a business","cn":"股票持有人；股东","ex":{"en":"The corporations' goal is to enrich their stockholders.","cn":"公司的目标是让股东受益。"}}]}},"strangulation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勒死;扼死;绞死;掐死","en":"Strangulation is the act of killing someone by squeezing their throat tightly so that they cannot breathe.","ex":{"en":"He is charged with the strangulation of two students.","cn":"他被指控勒死了两名学生。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of killing someone by pressing on their throat, or the fact of being killed in this way","cn":"扼死﹔勒死﹔绞死"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41strangulation.mp3","us":"media/ldoce/hwd/ame/8/strangulation.mp3"},"examples":[{"en":"the strangulation of the human spirit","cn":"对人的精神压制"},{"en":"to die of slow strangulation","cn":"被缓慢勒死"}],"oxford":{"phon":"ˌstræŋɡjuˈleɪʃn","pos":"noun","senses":[{"en":"the act of killing somebody by pressing their throat hard; the state of being killed in this way","cn":"扼死；勒死；掐死","ex":{"en":"to die of slow strangulation","cn":"被缓慢勒死"}},{"en":"the act of preventing something from growing or developing","cn":"抑制；压制；扼杀","lab":"disapproving","ex":{"en":"the strangulation of the human spirit","cn":"对人的精神压制"}}]}},"stinker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"令人讨厌的人;恶劣之事;坏蛋","en":"If you describe someone or something as a stinker, you mean that you think they are very unpleasant or bad.","ex":{"en":"I think he's an absolute stinker to do that to her","cn":"我认为他那样对待她真太缺德了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is very unpleasant or difficult","cn":"讨厌的人﹔棘手的事"},{"en":"a film, book, performance etc that is very bad","cn":"质量低劣的事物〔极糟的电影﹑书﹑表演等〕"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41stinker.mp3","us":"media/ldoce/hwd/ame/1/stinker.mp3"},"examples":[{"en":"This cold I’ve got is a real stinker .","cn":"我这次得的感冒真是令人难受。"},{"en":"You really are a stinker.","cn":"你这个人真讨厌。"}],"oxford":{"phon":"ˈstɪŋkə(r)","pos":"noun","senses":[{"en":"a person or thing that is very unpleasant or difficult","cn":"讨厌的人；棘手的事","ex":{"en":"It’s been a real stinker of a day.","cn":"这一天真让人受不了。"}}]}},"streaming":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"串流;流式传播","en":"Streaming is a method of transmitting data from the Internet directly to a user's computer screen without the need to download it.","ex":{"en":"...web sites that feature streaming media.","cn":"以流式媒体为主要特色的网站"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to flow quickly and in great amounts","cn":""},{"en":"to move in a continuous flow in the same direction","cn":""},{"en":"to produce a continuous flow of liquid","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/stream_v0205.mp3","us":"media/ldoce/hwd/ame/b/stream1.mp3"},"examples":[{"en":"Streaming within comprehensive schools is common practice.","cn":"综合中学常把学生按能力分班。"},{"en":"Water came streaming out of the burst pipe.","cn":""}],"oxford":{"phon":"ˈstriːmɪŋ","pos":"noun","senses":[{"en":"the policy of dividing school students into groups of the same level of ability","cn":"（把学生按能力）分班，分组","lab":"both British English","ex":{"en":"Streaming within comprehensive schools is common practice.","cn":"综合中学常把学生按能力分班。"}},{"en":"a method of sending or receiving data, especially video, over a computer network","cn":"流媒体（经计算机网络发送或接受数据的一种方法，尤指视频）","ex":{"en":"Internet video streaming has not replaced television.","cn":"互联网视频流尚未取代电视。"}}]}},"stead":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"代替(某人)","en":"If you do something in someone's stead, you replace them and do it instead of them.","ex":{"en":"We hope you will consent to act in his stead","cn":"我们希望你会同意代理他的职务。"}},{"pos":"PHRASE 短语","cn":"对…很有用;对…很有利","en":"If you say that something will stand someone in good stead, you mean that it will be very useful to them in the future.","ex":{"en":"These two games here will stand them in good stead for the future","cn":"现在的这两场比赛将对他们今后很有利。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to do something that someone else usually does or was going to do","cn":"代替某人做某事"},{"en":"to be very useful to someone when needed 〔","cn":"需要时〕对某人很有用"}]},"vocab":{"pos":"n","senses":[{"en":"Someone's stead is their position, or occupation. The eager understudy to starring role leapt at the chance to serve in the lead actor's stead when he mysteriously got food poisoning."}]},"media":{"uk":"media/ldoce/hwd/bre/2/stead0205.mp3","us":"media/ldoce/hwd/ame/3/stead.mp3"},"examples":[{"en":"Foxton was dismissed and John Smith was appointed in his stead.","cn":"福克斯顿被解职，受命接替他的是约翰 · 史密斯。"},{"en":"Your languages will stand you in good stead when it comes to finding a job.","cn":"你懂得几种语言，找工作时就会显出优势。"}]},"strong-arm":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(策略、方法)强硬的，铁拳的，使用暴力强制的，横施淫威的","en":"If you refer to someone's behaviour as strong-arm tactics or methods, you disapprove of it because it consists of using threats or force in order to achieve something.","ex":{"en":"The money has been recovered without resorting to verbal abuse or strong-arm tactics","cn":"没有恶语相向也没有大动干戈就把这笔钱要回来了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the use of force or violence, especially when this is not necessary 〔","cn":"尤指不必要的〕暴力策略/手段等"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41strong-arm.mp3","us":"media/ldoce/hwd/ame/8/laadstrong-arm.mp3"},"examples":[{"en":"to use strong-arm tactics against your political opponents","cn":"用强制手段对付政敌"}],"oxford":{"phon":"ˈstrɒŋ ɑːm","pos":"adjective","senses":[{"en":"using threats or violence in order to make people do what you want","cn":"横施淫威的；以暴力强制的","ex":{"en":"to use strong-arm tactics against your political opponents","cn":"用强制手段对付政敌"}}]}},"stepparent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继父;继母","en":"Someone's stepparent is their stepmother or stepfather."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stepfather or stepmother","cn":"继父﹐后父﹔继母﹐后母"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41stepparent.mp3","us":"media/ldoce/hwd/ame/d/stepparent.mp3"}},"striker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(足球等的)前锋","en":"In football and some other team sports, a striker is a player who mainly attacks and scores goals, rather than defends.","ex":{"en":"...and the England striker scored his sixth goal of the season.","cn":"这名英格兰队前锋踢进了他在本赛季的第 6 个进球"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is not working because they are on strike","cn":"罢工者﹔罢市者"},{"en":"a player in football whose main job is to score goal s 〔","cn":"足球队的〕前锋（队员），射手"}]},"media":{"uk":"media/ldoce/hwd/bre/a/striker0205.mp3","us":"media/ldoce/hwd/ame/1/striker.mp3"},"oxford":{"phon":"ˈstraɪkə(r)","pos":"noun","senses":[{"en":"a worker who has stopped working because of argument over pay or conditions","cn":"罢工者；罢课者；罢市者"},{"en":"a player whose main job is to attack and try to score goals","cn":"前锋"}]}},"stirrup":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马蹬","en":"Stirrups are the two metal loops which are attached to a horse's saddle by long pieces of leather. You place your feet in the stirrups when riding a horse."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the rings of metal in which someone riding a horse rests their feet","cn":"马镫"}]},"collocations":{"phrases":["VERB + STIRRUP adjust | rise in, stand (up) in She stood up in her stirrups to see where the others had gone.","STIRRUP + NOUN leather She had to lengthen her stirrup leathers.","PREP. in a/the ~ He put his feet in the stirrups."]},"media":{"uk":"media/ldoce/hwd/bre/c/stirrup0205.mp3","us":"media/ldoce/hwd/ame/d/stirrup.mp3"},"oxford":{"phon":"ˈstɪrəp","pos":"noun","senses":[{"en":"one of the metal rings that hang down on each side of a horse’s saddle, used to support the rider’s foot","cn":"马镫","ex":{"en":"He put his feet in the stirrups.","cn":"他把脚伸进马镫里。"}},{"en":"the third of three small bones in the middle ear that carry sound to the inner ear","cn":"镫骨（三个最小的骨头之一，从耳膜携带声音到内耳中）","lab":"anatomy"}]}},"steelworks":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炼钢厂;钢铁厂","en":"A steelworks is a factory where steel is made."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a factory where steel is made","cn":"炼钢厂﹐钢铁厂"}]},"media":{"uk":"media/ldoce/hwd/bre/e/steelworks0205.mp3","us":"media/ldoce/hwd/ame/4/steelworks.mp3"},"oxford":{"phon":"ˈstiːlwɜːks","pos":"noun","senses":[{"en":"a factory where steel is made","cn":"炼钢厂"}]}},"stencil":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(镂有图案的)模版，蜡纸","en":"A stencil is a piece of paper, plastic, or metal which has a design cut out of it. You place the stencil on a surface and paint it so that paint goes through the holes and leaves a design on the surface."},{"pos":"VERB 动词","cn":"(用模版)印制(图案)","en":"If you stencil a design or if you stencil a surface with a design, you put a design on a surface using a stencil.","ex":{"en":"He then stencilled the ceiling with a moon and stars motif.","cn":"他随后用模版在天花板上印上了月亮和繁星图案。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of plastic, metal, or paper in which designs or letters have been cut out, that you put over a surface and paint over, so that the design is left on the surface 〔","cn":"镂有图案或文字的〕模版"},{"en":"a design made on something using a stencil 〔","cn":"用模版印制的〕图案﹐文字"},{"en":"to make a design, letters etc using a stencil","cn":"用模版印制"}]},"media":{"uk":"media/ldoce/hwd/bre/1/stencil_v0205.mp3","us":"media/ldoce/hwd/ame/a/stencil1.mp3"},"oxford":{"phon":"ˈstensl","pos":"noun","senses":[{"en":"a thin piece of metal, plastic or card with a design cut out of it, that you put onto a surface and paint over so that the design is left on the surface; the pattern or design that is produced in this way","cn":"（印文字或图案用的）模板；（用模板印的）文字，图案"},{"en":"to make letters or a design on something using a stencil","cn":"用模板印（文字或图案）","pos":"verb"}]}},"stellar":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"星的;星球的","en":"Stellar is used to describe anything connected with stars.","ex":{"en":"A stellar wind streams outward from the star.","cn":"从那颗恒星上不断吹出恒星风。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"杰出的;优秀的;出色的","en":"A stellar person or thing is considered to be very good.","ex":{"en":"...a stellar education at Eton and Oxford","cn":"伊顿和牛津的精英教育"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to the stars","cn":"星的﹐关于星的"},{"en":"extremely good","cn":"极出色的﹐优秀的"},{"en":"if a pop band, actor etc goes stellar, they become very popular and famous 〔","cn":"流行乐队﹑演员等〕变得极受欢迎﹐出名"}]},"vocab":{"pos":"adj","senses":[{"en":"Meaning outstanding, wonderful, better than everything else, stellar is a word of praise or excitement. Thomas Edison invented many things, but his stellar achievement might have been the light bulb."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41stellar.mp3","us":"media/ldoce/hwd/ame/d/stellar.mp3"},"examples":[{"en":"a stellar performance","cn":"精彩的演出"},{"en":"McKellen gave a stellar performance .","cn":"麦克凯伦的表演极为精彩。"}],"oxford":{"phon":"ˈstelə(r)","pos":"adjective","senses":[{"en":"connected with the stars","cn":"星的；恒星的","lab":"specialist"},{"en":"excellent","cn":"优秀的；精彩的；杰出的","lab":"informal","ex":{"en":"a stellar performance","cn":"精彩的演出"}}]}},"stocktaking":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"清点存货;存货盘点","en":"Stocktaking is the activity of counting and checking all the goods that a shop or business has."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a company or shop checks the quantities of materials and goods that it has a supply of","cn":"盘货﹐清点存货"}]},"media":{"uk":"media/ldoce/hwd/bre/0/stocktaking0205.mp3","us":"media/ldoce/hwd/ame/f/ld41stocktaking.mp3"},"oxford":{"phon":"ˈstɒkteɪkɪŋ","pos":"noun","senses":[{"en":"the process of making a list of all the goods in a shop or business","cn":"盘点；清点存货；盘货","lab":"especially British English","ex":{"en":"closed for stocktaking","cn":"关闭盘点"}},{"en":"the process of thinking carefully about your own situation or position","cn":"（自我）总结，评估，反思","ex":{"en":"She had some mental stocktaking to do.","cn":"她需要做一些心理盘点。"}}]}},"stile":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(篱笆或围墙两侧供人跨越的)梯磴，台阶","en":"A stile is an entrance to a field or path consisting of a step on either side of a fence or wall to help people climb over it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of steps that helps people climb over a fence in the countryside 〔","cn":"乡间设于篱笆两侧供人跨越的〕梯磴﹐台阶"}]},"media":{"uk":"media/ldoce/hwd/bre/4/stile0205.mp3","us":"media/ldoce/hwd/ame/6/stile.mp3","img":["media/thumb/stile.jpg"]},"oxford":{"phon":"staɪl","pos":"noun","senses":[{"en":"a set of steps that help people climb over a fence or gate in a field, etc.","cn":"（供人翻越田地等处所设的围栏、栅栏门等的）台阶，梯磴"}]}},"stigmata":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"圣痕，圣伤(人体出现的与耶稣被钉在十字架时相同部位的伤痕)","en":"Stigmata are marks that appear on a person's body in the same places where Christ was wounded when he was nailed to the cross. Some Christians believe that these marks are a sign of holiness."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"marks that appear on the hands and feet of some holy people, and which look like the wounds made by nails on the body of Christ","cn":"圣痕﹐圣伤〔某些圣徒手足上的伤痕﹐与耶稣身上的钉痕相似〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/stigmata0205.mp3","us":"media/ldoce/hwd/ame/4/stigmata.mp3"},"oxford":{"phon":"stɪɡˈmɑːtə","pos":"noun","senses":[{"en":"marks that look like the wounds made by nails on the body of Jesus Christ, believed by some Christians to have appeared as holy marks on the bodies of some saints","cn":"圣伤，圣痕（据信出现在某些圣徒身上，与耶稣身上钉子留下的伤痕相似）"}]}},"statutory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"法令的;法规的","en":"Statutory means relating to rules or laws which have been formally written down.","ex":{"en":"We had a statutory duty to report to Parliament.","cn":"我们有向议会报告的法定义务。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"your legal rights, duties etc are the ones that the law says you have","cn":""},{"en":"a right, duty etc that the law says you have","cn":""},{"en":"legal, according to the system of rules of a country","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If something is statutory , it is related to or set by laws or statutes. Statutory restrictions on air pollution require drivers to have the emissions from their cars check every few years."}]},"media":{"uk":"media/ldoce/hwd/bre/2/statutory0205.mp3","us":"media/ldoce/hwd/ame/7/statutory.mp3"},"examples":[{"en":"When you buy foods you have certain statutory rights.","cn":"在购买食物时，你有一定的法定权利。"},{"en":"The authority failed to carry out its statutory duties.","cn":"主管部门未履行自己的法定职责。"}],"oxford":{"phon":"ˈstætʃətri","pos":"adjective","senses":[{"en":"fixed by law; that must be done by law","cn":"法定的；依法必须执行的","ex":{"en":"The authority failed to carry out its statutory duties.","cn":"主管部门未履行自己的法定职责。"}}]}},"stratosphere":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"平流层;同温层","en":"The stratosphere is the layer of the earth's atmosphere which lies between 10 and 50 kilometres above the earth."},{"pos":"N-SING 单数名词","cn":"最高层;最高水平;顶峰","en":"If you say that someone or something climbs or is sent into the stratosphere, you mean that they reach a very high level.","ex":{"en":"This was enough to launch their careers into the stratosphere","cn":"这足以让他们的事业平步青云了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the outer part of the air surrounding the Earth, from 10 to 50 kilometres above the Earth","cn":"平流层"},{"en":"a very high position, level, or amount","cn":"极高档﹔极高层﹔极高水平﹔极大量"}]},"vocab":{"pos":"n","senses":[{"en":"When an astronomer talks about the stratosphere , she means the second layer of Earth's atmosphere, about six miles above the surface of our planet."}]},"media":{"uk":"media/ldoce/hwd/bre/5/stratosphere0205.mp3","us":"media/ldoce/hwd/ame/4/stratosphere.mp3"},"examples":[{"en":"The technology boom sent share prices into the stratosphere.","cn":"科技热潮使得股价飙升到极高的水平。"},{"en":"stratospheric clouds","cn":"平流层云"}]},"stakeholder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"利益相关者;股东","en":"Stakeholders are people who have an interest in a company's or organization's affairs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has invest ed money into something, or who has some important connection with it, and therefore is affected by its success or failure","cn":"参与人﹐投资者﹐有权益关系者"},{"en":"someone, usually a lawyer, who takes charge of a property during a quarrel or a sale 〔","cn":"争执或出售时期的〕财产保管人〔一般为律师〕"},{"en":"someone chosen to hold the money that is risked by people on a race, competition etc and to give all of it to the winner","cn":"赌金保管人"}]},"vocab":{"pos":"n","senses":[{"en":"A stakeholder is a person interested in a company. If you become CEO of a big company, you'll have to keep the interests of every stakeholder in mind, from the employees to the customers to the investors, whenever you make decisions."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41stakeholder.mp3","us":"media/ldoce/hwd/ame/c/stakeholder.mp3"},"examples":[{"en":"The government has said it wants to create a stakeholder economy in which all members of society feel that they have an interest in its success.","cn":"政府表示希望建立一种人人参与的经济模式，让社会全体成员觉得其繁荣将给每个人带来利益。"},{"en":"Citizens should be stakeholders in the society they live in.","cn":"公民应该是与所处的社会休戚相关的一分子。"}],"oxford":{"phon":"ˈsteɪkhəʊldə(r)","pos":"noun","senses":[{"en":"a person or company that is involved in a particular organization, project, system, etc., especially because they have invested money in it","cn":"（某组织、工程、体系等的）参与人，参与方，利益相关者","ex":{"en":"All our employees are stakeholders in the company.","cn":"我们所有的员工都是公司的利益共享人。"}},{"en":"a person who holds all the bets placed on a game or race and who pays the money to the winner","cn":"赌金保管人"}]}},"staggering":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人大吃一惊的;令人震惊的","en":"Something that is staggering is very surprising.","ex":{"en":"...a three-year contract reputed to be worth a staggering £5,000-a-week","cn":"据称高达每周 5,000 英镑的三年期合同"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel surprised","cn":""},{"en":"very surprising. Astounding sounds a little more formal and a little stronger than astonishing","cn":""},{"en":"very unusual and surprising","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A staggering amount is an astonishing, astounding, stupefying amount. Anything staggering blows your mind."}]},"collocations":{"phrases":["VERBS be","ADV. absolutely, quite The public response was absolutely staggering. | fairly, pretty"]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdestaggering.mp3","us":"media/ldoce/hwd/ame/5/staggering.mp3"},"examples":[{"en":"staggeringly beautiful/expensive","cn":"漂亮/昂贵得令人难以置信"},{"en":"The cost was a staggering $10 million.","cn":"费用竟高达1,000万美元。"}],"oxford":{"phon":"ˈstæɡərɪŋ","pos":"adjective","senses":[{"en":"so great, shocking or surprising that it is difficult to believe","cn":"令人难以相信的","ex":{"en":"They paid a staggering £5 million for the house.","cn":"他们为这所房子支付了惊人的 500 万英镑。"}}]}},"stitching":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"针脚;线迹","en":"Stitching is a row of stitches that have been sewn in a piece of cloth.","ex":{"en":"The stitching had begun to fray at the edges","cn":"边沿上的针脚已经开始磨损了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of stitches in a piece of material","cn":"针脚"}]},"media":{"uk":"media/ldoce/hwd/bre/7/stitching0205.mp3","us":"media/ldoce/hwd/ame/3/laadstitching.mp3"},"oxford":{"phon":"ˈstɪtʃɪŋ","pos":"noun","senses":[{"en":"a row of stitches","cn":"（一行）针脚","ex":{"en":"The stitching has come undone.","cn":"针脚开线了。"}}]}},"stadium":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"(周围设有看台的)露天体育场","en":"A stadium is a large sports ground with rows of seats all round it.","ex":{"en":"...a baseball stadium.","cn":"棒球场"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large area of ground, usually covered with grass, where team sports are played","cn":""},{"en":"a large sports field with seats all around it for people to watch team sports or track and field competitions","cn":""},{"en":"a sports field and the seats and buildings around it, belonging to a particular football, rugby, or cricket team","cn":""}]},"collocations":{"phrases":["ADJ. packed | all-seater | indoor | sports | Olympic | baseball, football, greyhound","VERB + STADIUM fill, pack (into) Thousands packed into the stadium to watch the final.","PREP. at a/the ~"]},"media":{"uk":"media/ldoce/hwd/bre/c/stadium0205.mp3","us":"media/ldoce/hwd/ame/0/stadium.mp3"},"examples":[{"en":"a football/sports stadium","cn":"足球场；运动场"},{"en":"an all-seater stadium","cn":"全坐席体育场"}],"oxford":{"phon":"ˈsteɪdiəm","pos":"noun","senses":[{"en":"a large sports ground surrounded by rows of seats and usually other buildings","cn":"体育场；运动场","ex":{"en":"a football/sports stadium","cn":"足球场；运动场"}}]}},"straightforward":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简单明了的;易懂的","en":"If you describe something as straightforward, you approve of it because it is easy to do or understand.","ex":{"en":"Disposable nappies are fairly straightforward to put on","cn":"一次性尿布很容易穿上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坦率的;率直的;坦诚的","en":"If you describe a person or their behaviour as straightforward, you approve of them because they are honest and direct, and do not try to hide their feelings.","ex":{"en":"She is very blunt, very straightforward and very honest","cn":"她非常直率，很坦诚，也非常诚实。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not difficult to do, and not needing much effort","cn":""},{"en":"easy and not complicated – used about things such as instructions and explanations, or about machines and systems","cn":""},{"en":"easy to understand or do, and unlikely to cause you any problems","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Straightforward means direct in your approach. When you have a favor to ask of a friend, don't beat around the bush––say what you need in a straightforward way."}]},"collocations":{"phrases":["VERBS appear, be, look, prove, seem, sound | find sth I think you'll find it all quite straightforward.","ADV. extremely, remarkably, very | absolutely, entirely, perfectly, quite Look, it's perfectly straightforward?just multiply everything by f","VERBS be, seem","ADV. very | quite | refreshingly a refreshingly straightforward attitude","PREP. about, with He was quite straightforward with us about the difficulties involved."]},"media":{"uk":"media/ldoce/hwd/bre/d/straightforwar0205.mp3","us":"media/ldoce/hwd/ame/7/straightforward.mp3"},"examples":[{"en":"Let me put it more straightforwardly.","cn":"我来把它说得更直截了当一些。"},{"en":"It's quite straightforward to get here.","cn":"来这儿相当容易。"}],"oxford":{"phon":"ˌstreɪtˈfɔːwəd","pos":"adjective","senses":[{"en":"easy to do or to understand; not complicated","cn":"简单的；易懂的；不复杂的","ex":{"en":"It's a relatively straightforward process.","cn":"那是个相对简单的过程。"}},{"en":"honest and open; not trying to trick somebody or hide something","cn":"坦诚的；坦率的；率直的","ex":{"en":"She's nice: very straightforward and easy to get on with.","cn":"她人不错，很坦诚，易相处。"}}]}},"straitjacket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(用以约束行为狂暴者的)约束服，紧身衣","en":"A straitjacket is a special jacket used to tie the arms of a violent person tightly around their body.","ex":{"en":"Occasionally his behavior became so uncontrollable that he had to be placed in a straitjacket.","cn":"他的行为偶尔会变得如此失控，不得不给他穿上约束服。"}},{"pos":"N-COUNT 可数名词","cn":"约束;桎梏;束缚","en":"If you describe an idea or a situation as a straitjacket, you mean that it is very limited and restricting.","ex":{"en":"The national curriculum must be a guide, not a straitjacket.","cn":"国家课程设置必须是指导性的，而不是约束性的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special piece of clothing that prevents someone from moving their arms, used to control someone who is being violent or, in the past, someone who was mentally ill 〔","cn":"用于束缚行为暴力者或过去束缚精神病人的〕约束衣﹐紧身衣"},{"en":"something such as a law or set of ideas that puts very strict or unfair limits on someone","cn":"束缚﹐桎梏"}]},"media":{"uk":"media/ldoce/hwd/bre/4/straitjacket0205.mp3","us":"media/ldoce/hwd/ame/3/laadstraitjacket.mp3"},"examples":[{"en":"the straitjacket of taxation","cn":"纳税的束缚"},{"en":"the straitjacket of censorship","cn":"审查制度的桎梏"}],"oxford":{"phon":"ˈstreɪtdʒækɪt","pos":"noun","senses":[{"en":"a piece of clothing like a jacket with long arms that can be tied together, used to control a person who is violent and thought to be likely to harm themselves or others","cn":"约束衣，紧身衣（有时用以束缚精神病患者）"},{"en":"a thing that stops something from growing or developing","cn":"束缚；桎梏；约束","lab":"disapproving","ex":{"en":"The government has been caught in the straitjacket of debt.","cn":"政府债务缠身。"}}]}},"stomp":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(常指因生气而)跺着脚走，迈着重重的步伐","en":"If you stomp somewhere, you walk there with very heavy steps, often because you are angry.","ex":{"en":"He turned his back on them and stomped off up the hill","cn":"他转身不理他们，噔噔噔地爬上了山。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move forward by putting one foot in front of the other","cn":""},{"en":"to walk without any clear purpose or direction","cn":""},{"en":"to walk with long steps in a determined, confident, or angry way","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you stomp , you thud your feet down heavily as you walk. An angry teenager might stomp down the hall and slam the door to his room."}]},"media":{"uk":"media/ldoce/hwd/bre/b/stomp_las3_br.mp3","us":"media/ldoce/hwd/ame/b/stomp.mp3"},"examples":[{"en":"She stomped angrily out of the office.","cn":"她怒气冲冲，重步走出办公室。"},{"en":"Alex stomped angrily out of the meeting.","cn":"亚历克斯怒气冲冲地重步走出会场。"}],"oxford":{"phon":"stɒmp","pos":"verb","senses":[{"en":"to walk, dance, or move with heavy steps","cn":"迈着重重的步子走（或跳舞、移动）","ex":{"en":"She stomped angrily out of the office.","cn":"她怒气冲冲，重步走出办公室。"}}]}},"strident":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"强硬的;咄咄逼人的;坚定的","en":"If you use strident to describe someone or the way they express themselves, you mean that they make their feelings or opinions known in a very strong way that perhaps makes people uncomfortable.","ex":{"en":"She was increasingly seen as a strident feminist.","cn":"她愈加被视为强硬的女权主义者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"刺耳的;尖锐的","en":"If a voice or sound is strident, it is loud, harsh, and unpleasant to listen to.","ex":{"en":"She tried to laugh, and the sound was harsh and strident","cn":"她想笑，但声音听起来尖锐刺耳。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"forceful and determined, especially in a way that is offensive or annoying","cn":"强烈的﹔坚定的﹔咄咄逼人的"},{"en":"a strident sound or voice is loud and unpleasant 〔","cn":"声音〕刺耳的﹐尖厉的"}]},"vocab":{"pos":"adj","senses":[{"en":"Feminists are often characterized by people who don't like them as strident . Strident describes their voices, raised in anger, as loud and harsh. Being a strident feminist isn't very ladylike. But making less money than a man when you do the same work is worse."}]},"media":{"uk":"media/ldoce/hwd/bre/5/strident0205.mp3","us":"media/ldoce/hwd/ame/5/strident.mp3"},"examples":[{"en":"He is a strident advocate of nuclear power.","cn":"他是发展核能的坚定拥护者。"},{"en":"a strident voice","cn":"刺耳的嗓音"}],"oxford":{"phon":"ˈstraɪdnt","pos":"adjective","senses":[{"en":"having a loud, rough and unpleasant sound","cn":"刺耳的","ex":{"en":"a strident voice","cn":"刺耳的嗓音"}},{"en":"aggressive and determined","cn":"强硬的；咄咄逼人的","ex":{"en":"He is a strident advocate of nuclear power.","cn":"他是发展核能的坚定拥护者。"}}]}},"stipulation":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is stated in an agreement or contract as being necessary before something else can happen or be allowed","cn":""},{"en":"the conditions that are stated in a written agreement, contract, or legal document","cn":""},{"en":"a set of things that you must do or must achieve in order to be officially allowed to do or have something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If all stipulations aren't met, the deal's off. By not reading the contract's fine print, you overlooked the stipulation that you perform in a clown suit. At least you can juggle."}]},"collocations":{"phrases":["VERB + STIPULATION make The only stipulation the building society makes is that house must be insured. | drop","PREP. with the ~ He left all his money to the town with the stipulation that it should be used to build a new football stadium. | ~ about/as"]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41stipulation.mp3","us":"media/ldoce/hwd/ame/d/stipulation.mp3"},"examples":[{"en":"The only stipulation is that the topic you choose must be related to your studies.","cn":"唯一的要求是所选的题目必须与你的研究科目有关。"},{"en":"The agreement included a stipulation that half of the money had to be spent on housing for lower-income families.","cn":"协议中包含一项条款﹐规定这笔钱有一半必须用于低收入家庭的住房供给。"}],"oxford":{"phon":"ˌstɪpjuˈleɪʃn","pos":"noun","senses":[{"en":"a clear and definite statement that something must be done, or about how it must be done","cn":"规定，约定；明确的要求","ex":{"en":"The only stipulation is that the topic you choose must be related to your studies.","cn":"唯一的要求是你选择的题目必须和你的研究科目相关。"}}]}},"stultify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使思维迟钝;使厌烦;使呆滞","en":"If something stultifies you, it makes you feel empty or dull in your mind, because it is so boring.","ex":{"en":"This attitude stultifies scientific progress","cn":"这种态度会扼杀科学的进步。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"so boring that you feel as though you are losing your ability to think","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When something stultifies you, it drains you of your energy, enthusiasm, or pleasure. A well-acted Shakespeare play can be a thrill. A poorly-acted one can stultify like nothing else."}]},"media":{"uk":"media/ldoce/hwd/bre/b/stultifying0205.mp3","us":"media/ldoce/hwd/ame/7/laadstultifying.mp3"},"examples":[{"en":"a stultifying office environment","cn":""}],"oxford":{"phon":"ˈstʌltɪfaɪ","pos":"verb","senses":[{"en":"to make somebody feel very bored and unable to think of new ideas","cn":"乏味得使人呆滞的；使人思维迟钝的","ex":{"en":"Cults stultify their members' critical thinking abilities.","cn":"邪教会愚弄其成员的批判性思维能力。"}}]}},"stepsister":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继姐;继妹","en":"Someone's stepsister is the daughter of their stepfather or stepmother."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the daughter of your stepmother or stepfather","cn":"继姐﹔继妹"}]},"media":{"uk":"media/ldoce/hwd/bre/0/stepsister0205.mp3","us":"media/ldoce/hwd/ame/f/stepsister.mp3"},"oxford":{"phon":"ˈstepsɪstə(r)","pos":"noun","senses":[{"en":"the daughter from an earlier marriage or relationship of your stepmother or stepfather","cn":"继姐，继妹（继母与其前夫或继父与其前妻所生的女儿）"}]}},"stanchion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"立柱;支柱","en":"A stanchion is a pole or bar that stands upright and is used as a support."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong upright bar used to support something","cn":"立柱﹐支柱"}]},"vocab":{"pos":"n","senses":[{"en":"A stanchion is a post or rod used to support something. Stanchions hold things up."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41stanchion.mp3","us":"media/ldoce/hwd/ame/6/stanchion.mp3"},"oxford":{"phon":"ˈstæntʃən","pos":"noun","senses":[{"en":"a long thin vertical piece of wood or metal used to support something","cn":"（用以支撑的）杆，支柱"}]}},"stakeout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(警方对大楼的)持续监视","en":"If police officers are on a stakeout, they are secretly watching a building for evidence of criminal activity."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when the police watch a place secretly and continuously in order to catch someone who is doing something illegal 〔","cn":"警察对某处的〕监视"}]},"vocab":{"pos":"n","senses":[{"en":"When police officers watch a suspect's house, keeping an eye on who's coming and going, they call it a stakeout . Most stakeouts are done stealthily, with the officers trying to avoid being seen."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41stakeout.mp3","us":"media/ldoce/hwd/ame/f/laadstakeout.mp3"}},"streaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"裸奔者","en":"A streaker is someone who runs quickly through a public place wearing no clothes, as a joke."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who runs across a public place with no clothes on as a joke or in order to shock people","cn":"裸奔者"}]},"media":{"uk":"media/ldoce/hwd/bre/8/streaker0205.mp3","us":"media/ldoce/hwd/ame/5/streaker.mp3"},"oxford":{"phon":"ˈstriːkə(r)","pos":"noun","senses":[{"en":"a person who runs through a public place with no clothes on as a way of getting attention","cn":"裸奔者"}]}},"stagflation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"滞胀","en":"If an economy is suffering from stagflation, inflation is high but there is no increase in the demand for goods or in the number of people who have jobs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an economic situation in which there is inflation (= a continuing rise in prices ) but many people do not have jobs and businesses are not doing well","cn":"停滞性通货膨胀﹐滞胀〔指出现通货膨胀﹐但许多人失业﹑商业萧条的一种经济状况〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41stagflation.mp3","us":"media/ldoce/hwd/ame/d/stagflation.mp3"},"oxford":{"phon":"stæɡˈfleɪʃn","pos":"noun","senses":[{"en":"an economic situation where there is high inflation (= prices rising continuously) but no increase in the jobs that are available or in business activity","cn":"滞胀（高通胀与低就业率或经济低迷并存）"}]}},"stripe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"条纹;线条","en":"A stripe is a long line which is a different colour from the areas next to it.","ex":{"en":"She wore a bright green jogging suit with a white stripe down the sides","cn":"她身穿一套裤腿两边有白色条纹的亮绿色慢跑服。"}},{"pos":"N-COUNT 可数名词","cn":"(军装或警服上表示等级或服役年限的 V 型)臂章","en":"In the armed forces or the police, stripes are V-shaped bands of material sewn onto a uniform to indicate the rank of corporal or sergeant. In the United States, stripes can also show the length of time that a person has served in an organization.","ex":{"en":"...a soldier with a corporal's stripes on his arms","cn":"胳膊上别着下士臂章的士兵"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a line of colour, especially one of several lines of colour all close together","cn":"条纹﹐线条"},{"en":"a coloured line or thin mark, especially one that is not straight or has been made accidentally","cn":""},{"en":"a thick line of colour that is different from the areas around it","cn":""}]},"collocations":{"phrases":["ADJ. broad, wide | fine, narrow, thin | bold | subtle | distinctive | horizontal, vertical","STRIPE + VERB run The butterfly is black and white with a blue stripe running down each wing.","PREP. with ~s a white tablecloth with red stripes | ~ across/down, etc. The toad has a distinctive yellow stripe down its back."]},"media":{"uk":"media/ldoce/hwd/bre/a/stripe0205.mp3","us":"media/ldoce/hwd/ame/b/stripe.mp3"},"examples":[{"en":"She's an educator of a very different stripe.","cn":"她完全是另外一种类型的教育家。"},{"en":"a zebra's black and white stripes","cn":"斑马的黑白条纹"}],"oxford":{"phon":"straɪp","pos":"noun","senses":[{"en":"a long narrow line of colour, that is a different colour from the areas next to it","cn":"条纹；线条","ex":{"en":"a zebra’s black and white stripes","cn":"斑马的黑白条纹"}},{"en":"a narrow piece of cloth, often in the shape of a V, that is worn on the uniform of a soldier or police officer to show their rank","cn":"（军装或警服上表示等级的）条，杠","ex":{"en":"a uniform with a sergeant’s stripes on the sleeve","cn":"袖子上有中士条纹的制服"}},{"en":"a type, category or opinion","cn":"种类；类型；观点","lab":"especially North American English","ex":{"en":"politicians of every stripe","cn":"形形色色的政界人士"}}]}},"statehouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(美国的)州议会大厦","en":"In the United States, a statehouse is where the governor of a state has his or her offices, and where the state legislature meets."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the building where people who make laws in a US state do their work","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41statehouse.mp3","us":"media/ldoce/hwd/ame/4/laadstatehouse.mp3"}},"stay-at-home":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(不去工作或旅行)守在家里的人","en":"If you describe someone as a stay-at-home, you mean that they stay at home rather than going out to work or travelling.","ex":{"en":"I was a stay-at-home mum until 1980 when my husband lost his job.","cn":"1980 年我丈夫失业之前，我一直是个家庭主妇。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"staying at home, rather than working somewhere else, usually in order to take care of children 〔","cn":"通常为了照顾孩子〕待在家里的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41stay-at-home.mp3","us":"media/ldoce/hwd/ame/b/stay-at-home.mp3"},"examples":[{"en":"a stay-at-home mom","cn":"全职妈妈"}],"oxford":{"phon":"ˈsteɪ ət həʊm","pos":"adjective","senses":[{"en":"a stay-at-home mother or father is one who stays at home to take care of their children instead of going out to work","cn":"全职照顾家庭的"},{"en":"a person who rarely goes out or does anything exciting","cn":"不爱出门的人；恋家的人；死气沉沉的人","pos":"noun"}]}},"steelworker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"炼钢工人","en":"A steelworker is a person who works in a factory where steel is made."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works in a factory where steel is made","cn":"炼钢工人"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41steelworker.mp3","us":"media/ldoce/hwd/ame/0/laadsteelworker.mp3"},"oxford":{"phon":"ˈstiːlwɜːkə(r)","pos":"noun","senses":[{"en":"a person who works in a place where steel is made","cn":"炼钢工人"}]}},"stick-on":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(标签、物体等)一面带粘胶的，可粘贴的","en":"Stick-on labels, tapes, and objects have a sticky material on one side so that they will stick to things."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"stick-on things have a sticky back so that you can attach them to something","cn":"可粘贴的﹐背后带胶的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41stick-on.mp3","us":"media/ldoce/hwd/ame/8/stick-on.mp3"},"examples":[{"en":"stick-on labels","cn":"背胶标签"},{"en":"stick-on sequins","cn":"粘贴性闪光饰片"}],"oxford":{"phon":"ˈstɪk ɒn","pos":"adjective","senses":[{"en":"with glue on one side so that it sticks to something","cn":"一面带黏胶的","ex":{"en":"stick-on labels","cn":"背胶标签"}}]}},"steeplechase":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"越野障碍赛马","en":"A steeplechase is a long horse race in which the horses have to jump over obstacles such as hedges and water jumps."},{"pos":"N-COUNT 可数名词","cn":"(3000 米)障碍赛跑","en":"A steeplechase is a 3000 metres race around a track, during which people jump over obstacles and water jumps."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long race in which horses jump over gates, water etc","cn":"越野障碍赛马"},{"en":"a long race in which people run and jump over fences, water etc","cn":"障碍赛跑"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41steeplechase.mp3","us":"media/ldoce/hwd/ame/e/steeplechase.mp3"},"oxford":{"phon":"ˈstiːpltʃeɪs","pos":"noun","senses":[{"en":"a long race in which horses have to jump over fences, water, etc.","cn":"越野障碍赛马"},{"en":"a long race in which people run and jump over gates and water, etc. around a track","cn":"障碍赛跑"}]}},"staunch":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚定的;忠诚的;虔诚的","en":"A staunch supporter or believer is very loyal to a person, organization, or set of beliefs, and supports them strongly.","ex":{"en":"He's a staunch supporter of controls on government spending.","cn":"他坚决支持控制政府开支。"}},{"pos":"VERB 动词","cn":"止住…的流动","en":"To staunch the flow of something means to stop it.","ex":{"en":"The government claims this is the only way to staunch the annual flow to Germany of hundreds of thousands of refugees","cn":"政府称这是阻止每年数十万难民涌入德国的唯一办法。"}},{"pos":"VERB 动词","cn":"给…止血","en":"To staunch a wound, or to staunch the blood from a wound, means to stop the wound from bleeding.","ex":{"en":"Tom tried to staunch the blood with his handkerchief.","cn":"汤姆试图用手帕来止血。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"continuing to support a person, party, belief etc for a long time","cn":""},{"en":"supporting a particular person, party, set of beliefs, etc – used especially about someone you can can trust and depend on to support you","cn":""},{"en":"strongly supporting someone or something because you admire them, love them, or enjoy what they do","cn":""}]},"vocab":{"pos":"1 adj 2 v","senses":[{"en":"As an adjective, staunch means firm. You might want to go to that concert Friday night, but your parents' staunch opposition prevents you."}]},"media":{"uk":"media/ldoce/hwd/bre/5/staunch_v0205.mp3","us":"media/ldoce/hwd/ame/0/l2staunch.mp3"},"examples":[{"en":"The family was staunchly Protestant.","cn":"那一家人是忠实的新教徒。"},{"en":"a staunch supporter of the monarchy","cn":"坚定地拥护君主制的人"}],"oxford":{"phon":"stɔːntʃ","pos":"adjective","senses":[{"en":"always showing strong support in your opinions and attitude","cn":"忠实的；坚定的","ex":{"en":"a staunch supporter of the monarchy","cn":"坚定地拥护君主制的人"}},{"en":"to stop the flow of something, especially blood","cn":"止住（血等的）流出","ex":{"en":"Customs officers are struggling to staunch the flow of illegal imports.","cn":"海关官员正在努力阻止非法进口的流动。"},"pos":"verb"}]}},"steamer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"汽船;轮船","en":"A steamer is a ship that has an engine powered by steam."},{"pos":"N-COUNT 可数名词","cn":"蒸锅;蒸笼","en":"A steamer is a special container used for steaming food such as vegetables and fish."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a steamship","cn":"汽船﹐大轮船"},{"en":"a container used to cook food in steam","cn":"汽锅﹐蒸锅"},{"en":"a member of a large group of young people who go into a public place, surprise and frighten the people there, and then rob them 〔","cn":"大批涌入公共场所﹐对人实施恐吓抢劫的〕结帮抢劫者﹐团伙抢劫者"}]},"collocations":{"phrases":["ADJ. paddle | lake, river | pleasure | tramp","PREP. by ~, on (board) a/the ~"]},"media":{"uk":"media/ldoce/hwd/bre/d/steamer0205.mp3","us":"media/ldoce/hwd/ame/4/steamer.mp3"},"oxford":{"phon":"ˈstiːmə(r)","pos":"noun","senses":[{"en":"a boat or ship driven by steam","cn":"汽船；轮船","ex":{"en":"In 1926 they boarded the steamer for home.","cn":"1926 年，他们登上了回乡的客轮。"}},{"en":"a metal container with small holes in it, that is placed over a pan of boiling water in order to cook food in the steam","cn":"蒸锅；蒸笼"}]}},"stippled":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"带有小圆点的;布满斑点的","en":"A surface that is stippled is covered with tiny spots.","ex":{"en":"The room remains simple with bare, stippled green walls.","cn":"房间仍然很简朴，四面都是饰有圆点的绿色空墙。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to draw or paint a picture or pattern using short stroke s or spots instead of lines","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41stipple.mp3","us":"media/ldoce/hwd/ame/0/stipple.mp3"}},"stag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(成年的)牡鹿，雄鹿","en":"A stag is an adult male deer belonging to one of the larger species of deer. Stags usually have large branch-like horns called antlers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a fully grown male deer","cn":"成年雄鹿﹐牡鹿"},{"en":"if a man goes stag, he goes to a party without a woman 〔","cn":"男子〕不带女伴参加社交聚会"}]},"vocab":{"pos":"n v","senses":[{"en":"A stag is another word for a buck, or a male deer. If you spot a family of deer in the woods, the stag is the one with the largest antlers."}]},"media":{"uk":"media/ldoce/hwd/bre/1/brelasdestag.mp3","us":"media/ldoce/hwd/ame/d/stag.mp3"},"oxford":{"phon":"stæɡ","pos":"noun","senses":[{"en":"a male deer","cn":"雄鹿"}]}},"straddle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"骑;跨坐;叉开双腿坐","en":"If you straddle something, you put or have one leg on either side of it.","ex":{"en":"He sat down, straddling the chair.","cn":"他跨坐在椅子上。"}},{"pos":"VERB 动词","cn":"横跨，跨越(河流、道路、边境等)","en":"If something straddles a river, road, border, or other place, it stretches across it or exists on both sides of it.","ex":{"en":"A small wooden bridge straddled the dike.","cn":"一座小木桥横跨在排水渠上。"}},{"pos":"VERB 动词","cn":"横跨，跨越，同属(不同时期、群体或活动领域等)","en":"Someone or something that straddles different periods, groups, or fields of activity exists in, belongs to, or takes elements from them all.","ex":{"en":"Our lives have straddled a period of greater change than perhaps any since the end of the Roman Empire","cn":"我们生活的这个时期所经历的变革可能是罗马帝国灭亡以来最巨大的。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be or move into a position in which your knees are on the floor and your body is upright","cn":""},{"en":"to sit on the ground or floor with your knees bent and your feet crossed in front of you","cn":""},{"en":"to put your body into a position in which your feet are flat on the ground, your knees are bent up to your chest, and your bottom is off the ground, or to move into this position","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you straddle something, you're sitting on it with one leg on each side — like straddling a horse or a fence."}]},"media":{"uk":"media/ldoce/hwd/bre/e/straddle0205.mp3","us":"media/ldoce/hwd/ame/d/straddle.mp3"},"examples":[{"en":"He swung his leg over the motorcycle, straddling it easily.","cn":"他一骗腿轻而易举地骑上摩托车。"},{"en":"The mountains straddle the French-Swiss border.","cn":"这座山脉横跨法国和瑞士边界。"}],"oxford":{"phon":"ˈstrædl","pos":"verb","senses":[{"en":"to sit or stand with one of your legs on either side of somebody/something","cn":"骑；跨坐；分腿站立","ex":{"en":"He swung his leg over the motorcycle, straddling it easily.","cn":"他一骗腿轻而易举地骑上摩托车。"}},{"en":"to cross, or exist on both sides of, a river, a road or an area of land","cn":"跨过，横跨（河流、道路或一片土地）","ex":{"en":"The mountains straddle the French-Swiss border.","cn":"这座山脉横跨法国和瑞士边界。"}},{"en":"to exist within, or include, different periods of time, activities or groups of people","cn":"横跨，同属（不同时期、活动或群体）；两栖于（不同活动）","ex":{"en":"a writer who straddles two cultures","cn":"横贯两种文化的作家"}}]}},"stand-up":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(喜剧演员)单人表演的","en":"A stand-up comic or comedian stands alone in front of an audience and tells jokes.","ex":{"en":"He does all kinds of accents, he can do jokes—he could be a stand-up comic","cn":"他会模仿各种口音，还会讲笑话——他可以当个独角喜剧演员。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"单人滑稽表演;单口相声","en":"Stand-up is stand-up comedy.","ex":{"en":"...getting by on likeability, professionalism and the kind of nerve you need to do stand-up.","cn":"凭借个人魅力、精湛的技艺和进行单人喜剧表演所需要的勇气过活"}},{"pos":"ADJ 形容词","cn":"(争吵、打斗)激烈的","en":"If people have a stand-up argument or fight, they stand up and shout at each other or hit each other violently."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"stand-up comedy involves one person telling jokes alone as a performance 〔","cn":"喜剧〕单人表演的"},{"en":"a stand-up meeting, meal etc is one in which people stand up","cn":"站着做的﹔站着使用的"},{"en":"a stand-up fight, argument etc is one in which people shout loudly at each other or are violent 〔","cn":"打斗﹑争论等〕激烈的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/stand_up_adj0205.mp3","us":"media/ldoce/hwd/ame/8/stand-up.mp3"},"examples":[{"en":"When did you start doing stand-up?","cn":"你什么时候开始表演独白喜剧的？"},{"en":"She started out as a stand-up.","cn":"她出道时是个独角喜剧演员。"}],"oxford":{"phon":"ˈstænd ʌp","pos":"noun","senses":[{"en":"stand-up comedy","cn":"独角喜剧；脱口秀","g":"[uncountable]","ex":{"en":"When did you start doing stand-up?","cn":"你什么时候开始表演脱口秀的？"}},{"en":"a person who performs stand-up comedy","cn":"独角喜剧演员；脱口秀演员","g":"[countable]","ex":{"en":"She started out as a stand-up.","cn":"她出道时是个脱口秀演员。"}},{"en":"stand-up comedy consists of one person standing in front of an audience and telling jokes","cn":"（喜剧节目）单人表演的","ex":{"en":"a stand-up act","cn":"单人说笑表演"},"pos":"adjective"},{"en":"a stand-up row (= argument) or fight is one in which people shout loudly at each other or are violent towards each other","cn":"（争论、打斗等）激烈的","lab":"especially British English","pos":"adjective"},{"en":"worn, used, etc. in a vertical position","cn":"直立的；挺立的","ex":{"en":"a stand-up collar","cn":"立领"},"pos":"adjective"},{"en":"held, used, etc. while standing up","cn":"站着进行（或使用等）的","ex":{"en":"a stand-up meeting","cn":"站会"},"pos":"adjective"}]}},"statistic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"统计数字(或资料)","en":"Statistics are facts which are obtained from analysing information expressed in numbers, for example information about the number of times that something happens.","ex":{"en":"Official statistics show real wages declining by 24%","cn":"官方统计数字表明实际工资下降了 24%。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"统计学","en":"Statistics is a branch of mathematics concerned with the study of information that is expressed in numbers.","ex":{"en":"...a professor of Mathematical Statistics.","cn":"数学统计学教授"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of numbers which represent facts or measurements","cn":"统计数字[资料]"},{"en":"the science of collecting and examining such numbers","cn":"统计学"},{"en":"a single number which represents a fact or measurement （","cn":"一项）统计数据"}]},"vocab":{"pos":"n","senses":[{"en":"A statistic is a numerical piece of information. If you are trying to prove a point, and you want your argument to have a sense of authority, you might want to use a statistic to back up your claim."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41statistic.mp3","us":"media/ldoce/hwd/ame/2/statistic.mp3"},"examples":[{"en":"Statistics show that far more people are able to ride a bicycle than can drive a car.","cn":"统计资料表明，会骑自行车的人比会开汽车的人多得多。"},{"en":"According to official statistics the disease killed over 500 people.","cn":"根据官方的统计数字，500 多人死于这种疾病。"}],"oxford":{"phon":"stəˈtɪstɪk","pos":"noun","senses":[{"en":"a collection of information shown in numbers","cn":"统计数字；统计资料","g":"[plural]","lab":"informal","ex":{"en":"Analysis of crime statistics showed high levels of violent crime within the area.","cn":"犯罪统计数据分析显示该地区暴力犯罪率很高。"}},{"en":"the science of collecting and analysing statistics","cn":"统计学","g":"[uncountable]","lab":"informal","ex":{"en":"There is a compulsory course in statistics.","cn":"有一门统计学的必修课。"}},{"en":"a piece of information shown in numbers","cn":"（一项）统计数据","g":"[countable]","lab":"informal","ex":{"en":"An important statistic is that 94 per cent of crime relates to property.","cn":"一个重要数据是 94% 的犯罪同财产有关。"}}]}},"stint":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(在某地的)工作时间，活动时间","en":"A stint is a period of time which you spend doing a particular job or activity or working in a particular place.","ex":{"en":"He is returning to this country after a five-year stint in Hong Kong.","cn":"他在香港工作了5 年后即将回国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a particular length of time with a beginning and an end","cn":""},{"en":"a period of time - use this especially to talk about a period in the past, or when you are not saying whether the period was long or short","cn":""},{"en":"a length of time that is officially fixed for someone's period of responsibility or power, for someone's period in prison, or for a business contract","cn":""}]},"vocab":{"pos":"1 v n 2 n","senses":[{"en":"The noun stint means a set amount of time in which you do something — often work of some sort. \"She served a stint in the army, followed by a stint in an office setting, before settling on a career as a lounge singer.\""}]},"collocations":{"phrases":["ADJ. long | brief","VERB + STINT do He's doing a brief stint at the World Bank in Washington. | start | finish","PREP. during a/the ~ She met her husband during her stint at the London office."]},"media":{"uk":"media/ldoce/hwd/bre/f/stint_n0205.mp3","us":"media/ldoce/hwd/ame/e/stint1.mp3"},"examples":[{"en":"He did a stint abroad early in his career.","cn":"他刚参加工作时在国外干过一段时间。"},{"en":"She never stints on the food at her parties.","cn":"她举办聚会吃的东西从不小气。"}],"oxford":{"phon":"stɪnt","pos":"noun","senses":[{"en":"a period of time that you spend working somewhere or doing a particular activity","cn":"从事某项工作（或活动）的时间","ex":{"en":"He did a stint abroad early in his career.","cn":"他刚参加工作时在国外干过一段时间。"}},{"en":"to provide or use only a small amount of something","cn":"节省；吝惜","ex":{"en":"She never stints on the food at her parties.","cn":"她举办聚会吃的东西从不小气。"},"pos":"verb"}]}},"steely":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)坚强的，坚决的，强硬的","en":"Steely is used to emphasize that a person is hard, strong, and determined.","ex":{"en":"Their indecision has been replaced by confidence and steely determination","cn":"他们的优柔寡断已经被自信和钢铁般的决心所取代。"}},{"pos":"ADJ 形容词","cn":"铁灰色的;灰蓝色的","en":"You use steely to describe something that has the grey colour of steel.","ex":{"en":"...steely grey hair.","cn":"铁灰色头发"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely determined and very strong","cn":"坚定的﹔钢铁般的"},{"en":"if someone has steely eyes or is steely-eyed, they look very determined 〔","cn":"目光〕坚决的﹐坚毅的"},{"en":"having a grey colour like steel","cn":"钢一样灰白的﹐铁灰色的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/steely0205.mp3","us":"media/ldoce/hwd/ame/2/steely.mp3"},"examples":[{"en":"a look of steely determination","cn":"一副下定决心、不可动摇的神态"},{"en":"a cold, steely voice","cn":"冷冰冰的腔调"}],"oxford":{"phon":"ˈstiːli","pos":"adjective","senses":[{"en":"strong, hard and unfriendly","cn":"强硬的；冷冰冰的","ex":{"en":"a cold, steely voice","cn":"冷冰冰的腔调"}},{"en":"like steel in colour","cn":"（色泽）似钢的","ex":{"en":"steely blue eyes","cn":"灰蓝色的眼睛"}}]}},"stack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一堆;一叠","en":"A stack of things is a pile of them.","ex":{"en":"There were stacks of books on the bedside table and floor.","cn":"床头桌和地板上有几摞书。"}},{"pos":"VERB 动词","cn":"将…码放整齐","en":"If you stack a number of things, you arrange them in neat piles.","ex":{"en":"Mme Cathiard was stacking the clean bottles in crates","cn":"凯西亚德夫人正在将干净的瓶子整齐地码放在板条箱里。"}},{"pos":"N-PLURAL 复数名词","cn":"一大堆;许多","en":"If you say that someone has stacks of something, you mean that they have a lot of it.","ex":{"en":"If the job's that good, you'll have stacks of money.","cn":"如果这个工作真有那么好，你将会赚很多钱。"}},{"pos":"VERB 动词","cn":"在(某组织机构中)安插(对自己有利的人员)","en":"If someone in authority stacks an organization or body, they fill it with their own supporters so that the decisions it makes will be the ones they want it to make.","ex":{"en":"They said they were going to stack the court with anti-abortion judges","cn":"他们说将会往法院中安排一些反对堕胎的法官。"}},{"pos":"PHRASE 短语","cn":"情况对…不利","en":"If you say that the odds are stacked against someone, or that particular factors are stacked against them, you mean that they are unlikely to succeed in what they want to do because the conditions are not favourable.","ex":{"en":"The odds are stacked against civilians getting a fair trial","cn":"平民难以得到公正的审判。"}},{"pos":"","cn":"","en":"相关词组：stack up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of things of the same type that are put on top of each other","cn":""},{"en":"a neat pile of things of the same type","cn":""},{"en":"a large messy pile of things","cn":""}]},"collocations":{"phrases":["ADV. carefully, neatly | away, up The wood was collected up and carefully stacked away. Stack the chairs up over there.","PREP. against The cases were stacked against the wall. | in The paintings were stacked in a corner of the room. | on The plates were neatly ","PHRASES be stacked in piles Boxes were stacked in piles all round the room."]},"media":{"img":["media/ldoce/img/stack.jpg"],"uk":"media/ldoce/hwd/bre/6/stack_n0205.mp3","us":"media/ldoce/hwd/ame/8/stack1.mp3"},"examples":[{"en":"Let's try him in the job and see how he stacks up.","cn":"咱们让他干这活儿试试，看看他比别人干得怎么样。"},{"en":"I tried a spin on the ice and stacked it.","cn":"我试图在冰面上旋转，结果笨拙地跌倒了。"}],"oxford":{"phon":"stæk","pos":"noun","senses":[{"en":"a pile of something, usually neatly arranged","cn":"（通常指码放整齐的）一叠，一摞，一堆","g":"[countable]","ex":{"en":"a stack of books","cn":"一摞书"}},{"en":"a large number or amount of something; a lot of something","cn":"大量；许多；一大堆","g":"[countable]","lab":"informal, especially British English，，","ex":{"en":"stacks of money","cn":"许多钱"}},{"en":"a tall chimney, especially on a factory","cn":"（尤指工厂的）大烟囱","g":"[countable]"},{"en":"the part of a library, sometimes not open to the public, where books that are not often needed are stored","cn":"（图书馆中贮藏使用频率较低的书的）书库","g":"[plural]","ex":{"en":"The books you need will have to be brought up from the stacks.","cn":"你需要的书必须从书架上拿出来。"}},{"en":"a way of storing information in a computer in which the most recently stored item is the first to be retrieved (= found or got back)","cn":"栈；堆栈","g":"[countable]","lab":"computing"},{"en":"a tall thin part of a cliff that has been separated from the land and stands on its own in the sea","cn":"海蚀柱","g":"[countable]","lab":"geology"},{"en":"to arrange objects neatly in a pile; to be arranged in this way","cn":"（使）放成整齐的一叠（或一摞、一堆）","g":"[transitive, intransitive]","ex":{"en":"to stack boxes","cn":"把箱子摞起来"},"pos":"verb"},{"en":"to fill something with piles of things","cn":"使成叠（或成摞、成堆）地放在…；使码放在…","g":"[transitive]","ex":{"en":"They were busy stacking the shelves with goods.","cn":"他们正忙着摆货物上架呢。"},"pos":"verb"},{"en":"if aircraft stack (up) or are stacked (up) over an airport, there are several flying around waiting for their turn to land","cn":"（令飞机）分层盘旋等待着陆","g":"[intransitive, transitive]","pos":"verb"}]}},"steamy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"色情的;激情热辣的","en":"Steamy means involving exciting sex.","ex":{"en":"...a steamy thriller set in France","cn":"以法国为背景的情色惊悚片"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方)闷热潮湿的，充满水汽的","en":"A steamy place has hot, wet air.","ex":{"en":"...a steamy cafe","cn":"闷热潮湿的咖啡馆"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"films, magazines, or pictures that show sexual acts and are intended to make people feel sexually excited","cn":""},{"en":"a pornographic film, magazine, or picture shows or describes sexual acts in order to make people sexually excited","cn":""},{"en":"an erotic book, film, painting etc shows or describes sexual acts in a way that is deliberately sexually exciting but is also artistic","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/steamy0205.mp3","us":"media/ldoce/hwd/ame/b/laadsteamy.mp3"},"examples":[{"en":"steamy windows","cn":"蒙着一层水汽的窗户"},{"en":"a steamy bathroom","cn":"水汽弥漫的浴室"}],"oxford":{"phon":"ˈstiːmi","pos":"adjective","senses":[{"en":"full of steam; covered with steam","cn":"充满蒸汽的；蒙着水汽的","ex":{"en":"a steamy bathroom","cn":"水汽弥漫的浴室"}},{"en":"sexually exciting","cn":"色情的","lab":"informal","ex":{"en":"a steamy love scene","cn":"淫荡的做爱场面"}}]}},"stammer":{"collins":{"senses":[{"pos":"VERB 动词","cn":"口吃;结结巴巴地说","en":"If you stammer, you speak with difficulty, hesitating and repeating words or sounds.","ex":{"en":"Five per cent of children stammer at some point","cn":"5%的儿童在某个时期会口吃。"}},{"pos":"N-SING 单数名词","cn":"口吃;结巴","en":"Someone who has a stammer tends to stammer when they speak.","ex":{"en":"A speech-therapist cured his stammer.","cn":"一位言语矫治师治愈了他的口吃。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To stammer — or to have a stammer — is to speak haltingly and to have trouble getting the words out. A stammer is also called a \"stutter.\""}]},"collocations":{"phrases":["ADJ. bad, nervous, severe | slight","VERB + STAMMER develop | have, speak with"]},"media":{"uk":"media/ldoce/hwd/bre/9/stammer_v0205.mp3","us":"media/ldoce/hwd/ame/0/stammer1.mp3"},"examples":[{"en":"She was barely able to stammer out a description of her attacker.","cn":"她只能勉强结结巴巴地说一说袭击她的人是什么模样。"},{"en":"Many children stammer but grow out of it.","cn":"很多小孩口吃，但长大后就改过来了。"}],"oxford":{"phon":"ˈstæmə(r)","pos":"verb","senses":[{"en":"to speak with difficulty, repeating sounds or words and often stopping, before saying things correctly","cn":"口吃；结结巴巴地说","ex":{"en":"Many children stammer but grow out of it.","cn":"很多小孩口吃，但长大后就改过来了。"}},{"en":"a problem that somebody has in speaking in which they repeat sounds or words or often stop, before saying things correctly","cn":"口吃；结巴","ex":{"en":"She spoke with a stammer.","cn":"她结结巴巴地说话。"},"pos":"noun"}]}},"stunt":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"引人注意的花招;噱头","en":"A stunt is something interesting that is done in order to attract attention and get publicity for the person or company responsible for it.","ex":{"en":"In a bold promotional stunt for the movie, he smashed his car into a passing truck.","cn":"为了给电影制造噱头以吸引眼球，他把汽车猛地撞向一辆驶过的卡车。"}},{"pos":"N-COUNT 可数名词","cn":"(电影中的)特技表演","en":"A stunt is a dangerous and exciting piece of action in a film.","ex":{"en":"Sean Connery insisted on living dangerously for his new film by performing his own stunts.","cn":"肖恩·康纳利在他的新片中为求真实，坚持自己出演特技部分。"}},{"pos":"VERB 动词","cn":"阻碍(生长);妨碍(发展);遏制","en":"If something stunts the growth or development of a person or thing, it prevents it from growing or developing as much as it should.","ex":{"en":"The heart condition had stunted his growth a bit","cn":"心脏病已经多少影响了他的成长。"}},{"pos":"PHRASE 短语","cn":"冒险;逞能;干傻事","en":"If someone pulls a stunt, they do something silly or risky.","ex":{"en":"The days when they needed to pull publicity stunts to get noticed are long gone.","cn":"他们靠作秀出名的日子早已过去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dangerous action that is done to entertain people, especially in a film 〔","cn":"尤指电影中的〕特技表演﹐特技"},{"en":"something that is done to attract people’s attention, especially in advertising or politics 〔","cn":"尤指广告或政治中的〕噱头﹐引人注目的花招"},{"en":"to do something that is silly or that is slightly dangerous","cn":"做愚蠢[有点危险]的事"}]},"vocab":{"pos":"1 v n 2 n v","senses":[{"en":"To stunt is to slow or hinder. Some people say that drinking coffee will stunt your growth when you're a teenager — they worry that you won't grow any taller."}]},"collocations":{"phrases":["ADJ. publicity","VERB + STUNT arrange, organize She arranged a publicity stunt to make the public aware of the product. | pull What do you hope to gain by pu","PREP. as a ~ They jumped off London Bridge as a publicity stunt. 2 dangerous act","ADJ. dangerous, daredevil | dramatic, spectacular | film","VERB + STUNT carry out, do, perform The actor performed all the stunts himself. | attempt","STUNT + VERB backfire, go wrong","STUNT + NOUN artist, man (also stuntman ), woman (also stuntwoman ) | driver, pilot, rider"]},"media":{"uk":"media/ldoce/hwd/bre/5/stunt_las3_br.mp3","us":"media/ldoce/hwd/ame/1/stunt1.mp3"},"examples":[{"en":"I've had enough of her childish stunts.","cn":"她那些幼稚的愚蠢行为我受够了。"},{"en":"The constant winds had stunted the growth of plants and bushes.","cn":"老是刮风，花草、灌木长不大。"}],"oxford":{"phon":"stʌnt","pos":"noun","senses":[{"en":"a dangerous and difficult action that somebody does to entertain people, especially as part of a film","cn":"（尤指电影中的）特技表演","lab":"British English","ex":{"en":"He did all his own stunts.","cn":"所有特技都是他自己演的。"}},{"en":"something that is done in order to attract people’s attention","cn":"意在引人注意的花招；噱头","lab":"sometimes disapproving","ex":{"en":"They jumped off London Bridge as a publicity stunt.","cn":"他们跳伦敦桥作为宣传噱头。"}},{"en":"a stupid or dangerous act","cn":"愚蠢行为；危险举动","lab":"informal","ex":{"en":"I've had enough of her childish stunts.","cn":"她那些幼稚的愚蠢行为我受够了。"}},{"en":"to prevent somebody/something from growing or developing as much as they/it should","cn":"阻碍生长；妨碍发展；遏制","ex":{"en":"The constant winds had stunted the growth of plants and bushes.","cn":"老是刮风，花草、灌木长不大。"},"pos":"verb"}]}},"stratified":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有不同社会阶层的;等级分化的","en":"A stratified society is one that is divided into different classes or social layers.","ex":{"en":"...a highly stratified, unequal and class-divided society.","cn":"等级森严、阶级分化的不平等社会"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having different social classes","cn":"有不同社会等级的﹐分层的"},{"en":"having several layers of earth, rock etc 〔","cn":"土壤﹑岩石等〕成层的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective stratified to describe something with many layers, either physically (like the layers of your skin) or socially (a kingdom with the king at the top and peasants at the bottom)."}]},"media":{"uk":"media/ldoce/hwd/bre/d/stratified0205.mp3","us":"media/ldoce/hwd/ame/d/laadstratified.mp3"},"examples":[{"en":"a stratified society","cn":"等级社会"},{"en":"stratified rock","cn":"成层岩"}]},"stillbirth":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"死产;死胎","en":"A stillbirth is the birth of a dead baby."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a birth in which the baby is born dead","cn":"死产"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41stillbirth.mp3","us":"media/ldoce/hwd/ame/0/stillbirth.mp3"},"oxford":{"phon":"ˈstɪlbɜːθ","pos":"noun","senses":[{"en":"a birth in which the baby is born dead","cn":"死产"}]}},"stalagmite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"石笋","en":"A stalagmite is a long piece of rock which sticks up from the floor of a cave. Stalagmites are formed by the slow dropping of water containing the mineral lime."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sharp pointed object coming up from the floor of a cave , formed by drops from a stalactite","cn":"石笋"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41stalagmite.mp3","us":"media/ldoce/hwd/ame/0/stalagmite.mp3"},"oxford":{"phon":"ˈstæləɡmaɪt","pos":"noun","senses":[{"en":"a piece of rock pointing upwards from the floor of a cave (= a hollow place underground), that is formed over a long period of time from drops of water containing lime that fall from the roof","cn":"石笋（向上生长）"}]}},"stopper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"塞子;瓶塞;栓","en":"A stopper is a piece of glass, plastic, or cork that fits into the top of a bottle or jar to close it.","ex":{"en":"...a bottle of colourless liquid sealed with a cork stopper.","cn":"用软木塞封口的一瓶无色液体"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the thing that you put in the top part of a bottle to close it","cn":"瓶塞﹐栓"}]},"media":{"img":["media/ldoce/img/stopper.jpg"],"uk":"media/ldoce/hwd/bre/a/stopper0205.mp3","us":"media/ldoce/hwd/ame/9/stopper.mp3"},"oxford":{"phon":"ˈstɒpə(r)","pos":"noun","senses":[{"en":"an object that fits into the top of a bottle to close it","cn":"瓶塞","ex":{"en":"He pulled out the stopper and took a long drink of water.","cn":"他拔掉瓶塞，喝了一大口水。"}},{"en":"to close something with a stopper","cn":"塞子：用塞子塞住东西","ex":{"en":"to stopper a flask/bottle","cn":"塞住烧瓶/瓶子"},"pos":"verb"}]}},"strychnine":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"士的宁;马钱子碱","en":"Strychnine is a very poisonous drug which is sometimes used in very small amounts as a medicine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very poisonous substance sometimes used in small amounts as a medicine","cn":"士的宁﹐马钱子碱〔有剧毒﹐微量可作药用〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41strychnine.mp3","us":"media/ldoce/hwd/ame/5/strychnine.mp3"},"oxford":{"phon":"ˈstrɪkniːn","pos":"noun","senses":[{"en":"a poisonous substance used in very small amounts as a medicine","cn":"士的宁；马钱子碱"}]}},"stepbrother":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继兄;继弟","en":"Someone's stepbrother is the son of their stepfather or stepmother."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the son of your stepmother or stepfather","cn":"继兄﹐继弟〔继母或继父与过去的配偶所生的儿子〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/stepbrother0205.mp3","us":"media/ldoce/hwd/ame/6/stepbrother.mp3"},"oxford":{"phon":"ˈstepbrʌðə(r)","pos":"noun","senses":[{"en":"the son from an earlier marriage or relationship of your stepmother or stepfather","cn":"继兄，继弟（继母与其前夫或继父与其前妻所生的儿子）"}]}},"sticker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(正面有字或画的)小贴纸，不粘胶贴纸","en":"A sticker is a small piece of paper or plastic, with writing or a picture on one side, which you can stick onto a surface."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of paper or plastic with a picture or writing on it that you can stick on to something 〔","cn":"有图或文字的〕粘贴标签﹐贴纸"},{"en":"→ label : Children get stickers for good work.","cn":"学习好的孩子可以得到贴纸。 bumper sticker (= a sticker on the back of a car )"}]},"media":{"uk":"media/ldoce/hwd/bre/d/sticker0205.mp3","us":"media/ldoce/hwd/ame/5/sticker.mp3"},"examples":[{"en":"a sticker album (= to collect stickers in)","cn":"粘贴标签收集册"},{"en":"bumper stickers (= on cars)","cn":"汽车保险杠粘贴标签"}],"oxford":{"phon":"ˈstɪkə(r)","pos":"noun","senses":[{"en":"a sticky label with a picture or message on it, that you stick onto something","cn":"粘贴标签；贴纸","ex":{"en":"The pack will contain a membership card, car stickers and a newsletter.","cn":"包里会有一张会员卡、一些汽车贴纸和一份内部通讯。"}},{"en":"a small digital image that you can use to express an idea or emotion on social media or on a messaging app. Stickers are often animated (= made to look as if they are moving).","cn":"您可以使用它在社交媒体或消息应用程序上表达想法或情感的小型数字图像。贴纸通常是动画的（= 看起来好像在移动）。","ex":{"en":"Many people today use stickers to express their feelings about things they see on the internet.","cn":"如今，许多人使用贴纸来表达他们对在互联网上看到的事物的感受。"}}]}},"staccato":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(噪音)断断续续的，短促不连贯的","en":"A staccato noise consists of a series of short, sharp, separate sounds.","ex":{"en":"He spoke in Arabic, a short staccato burst.","cn":"他突然用阿拉伯语叽里呱啦说了一串话。"}},{"pos":"ADV-GRADED 副词","cn":"(乐谱上)以断音，以断奏方式","en":"The instruction staccato on a piece of music means that the notes should be played or sung very briefly with gaps between them.","ex":{"en":"...a rapid staccato passage.","cn":"快速断奏乐段"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"if music is played staccato, the notes are cut short 〔","cn":"音乐〕断断续续地﹐不连贯地"}]},"vocab":{"pos":"adv adj","senses":[{"en":"Staccato is a musical term for notes that are played quickly and sharply. It can also refer to anything characterized by similar beats, such as the staccato clacking of a woman's high heels on a tile floor."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41staccato.mp3","us":"media/ldoce/hwd/ame/3/staccato.mp3"},"examples":[{"en":"a peculiar staccato voice","cn":"特有的不连贯而且刺耳的嗓音"},{"en":"staccato bursts of gunfire","cn":"一阵阵劈里啪啦的枪炮声"}],"oxford":{"phon":"stəˈkɑːtəʊ","pos":"adjective, adverb","senses":[{"en":"with each note played separately in order to produce short, sharp sounds","cn":"断音的；断奏的；以断奏方式","lab":"music, from Italian，，","ex":{"en":"staccato sounds","cn":"断奏音调"}},{"en":"with short, sharp sounds or movements","cn":"短促刺耳（的）；剧烈波动（的）","ex":{"en":"a peculiar staccato voice","cn":"特有的不连贯而且刺耳的嗓音"}}]}},"stockroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指商店或工厂的)仓库，贮藏室","en":"A stockroom is a room, especially in a shop or a factory, where a stock of goods is kept."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room for storing things in a shop or office 〔","cn":"商店或办公室的〕仓库﹐储藏室"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41stockroom.mp3","us":"media/ldoce/hwd/ame/1/stockroom.mp3"},"oxford":{"phon":"ˈstɒkruːm","pos":"noun","senses":[{"en":"a room for storing things in a shop, an office, etc.","cn":"仓库；贮藏室"}]}},"statistician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"统计学家;统计员","en":"A statistician is a person who studies statistics or who works using statistics."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works with statistics","cn":"统计学家﹔统计员"}]},"vocab":{"pos":"n","senses":[{"en":"Numbers, numbers and more numbers. A statistician is a math expert who uses huge amounts of data to figure out how likely it is that something will happen, like your chances of winning the lottery."}]},"media":{"uk":"media/ldoce/hwd/bre/e/statistician0205.mp3","us":"media/ldoce/hwd/ame/1/statistician.mp3"},"oxford":{"phon":"ˌstætɪˈstɪʃn","pos":"noun","senses":[{"en":"a person who studies or works with statistics","cn":"统计学家；统计员"}]}},"studious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勤奋的;好学的;用功的","en":"Someone who is studious spends a lot of time reading and studying books.","ex":{"en":"I was a very quiet, studious little girl.","cn":"我那时是个非常安静、勤奋好学的小女孩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who wants to work all the time and who cannot relax when they are not working","cn":""},{"en":"someone who is industrious works hard and effectively","cn":""},{"en":"someone who is dedicated works very hard at something because they care about it a lot, even though the job is difficult or does not earn them much money","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you are studious, you study a lot and you probably even enjoy it. Your studious habits might bring you excellent grades and \"your\" table at the library."}]},"media":{"uk":"media/ldoce/hwd/bre/b/studious0205.mp3","us":"media/ldoce/hwd/ame/f/studious.mp3"},"examples":[{"en":"a studious young man","cn":"勤奋的小伙子"},{"en":"a quiet, studious young man","cn":"一个文静好学的年轻人"}],"oxford":{"phon":"ˈstjuːdiəs","pos":"adjective","senses":[{"en":"spending a lot of time studying or reading","cn":"勤奋的；好学的；用功的","ex":{"en":"a studious young man","cn":"勤奋的小伙子"}}]}},"state-of-the-art":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"使用最先进技术的;体现最高水平的","en":"If you describe something as state-of-the-art, you mean that it is the best available because it has been made using the most modern techniques and technology.","ex":{"en":"...the production of state-of-the-art military equipment.","cn":"最先进军事装备的生产"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"using very modern technology and ideas","cn":""},{"en":"very advanced, and working in a better but often more complicated way than other things","cn":""},{"en":"using very advanced technology, especially electronic equipment and computers","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/state_of_the_a0205.mp3","us":"media/ldoce/hwd/ame/8/state-of-the-art.mp3"},"examples":[{"en":"His new laptop is state-of-the-art.","cn":"他那台新笔记本电脑是顶尖配置。"},{"en":"state-of-the-art technology","cn":"最先进的技术"}],"oxford":{"phon":"ˌsteɪt əv ði ˈɑːt","pos":"adjective","senses":[{"en":"using the most modern or advanced techniques or methods; as good as it can be at the present time","cn":"应用最先进技术（或方法）的；最先进的","ex":{"en":"The system was state of the art.","cn":"这一系统是当时最先进的。"}}]}},"stationer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"文具商","en":"A stationer is a person who sells paper, envelopes, pens, and other equipment used for writing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shop that sells stationery","cn":"文具店"},{"en":"someone in charge of a shop that sells stationery","cn":"文具商﹐文具店店主"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41stationer.mp3","us":"media/ldoce/hwd/ame/6/stationer.mp3"},"examples":[{"en":"Is there a stationer's near here?","cn":"这附近有没有文具店？"}],"oxford":{"phon":"ˈsteɪʃənə(r)","pos":"noun","senses":[{"en":"a person who owns or manages a shop selling stationery","cn":"文具商"},{"en":"a shop that sells stationery","cn":"文具店","ex":{"en":"Is there a stationer's near here?","cn":"这附近有没有文具店？"}}]}},"stunner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"极有魅力的女人;大美人","en":"A stunner is an extremely attractive woman.","ex":{"en":"One of the girls was an absolute stunner.","cn":"其中有一个女孩非常迷人。"}},{"pos":"N-COUNT 可数名词","cn":"令人震惊的事情;令人印象深刻的事物","en":"If you say that something is a stunner, you mean that it is very surprising or impressive.","ex":{"en":"Their debut single is a stunner.","cn":"他们的首张单曲成绩斐然。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is very attractive, especially a woman","cn":"极具吸引力的人[物]﹔〔尤指〕极漂亮的女人"},{"en":"a situation or event that surprises you","cn":"令人震惊的情形[事情]"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41stunner.mp3","us":"media/ldoce/hwd/ame/1/stunner.mp3"},"examples":[{"en":"Lucy was a real stunner.","cn":"露西十分美丽动人。"}],"oxford":{"phon":"ˈstʌnə(r)","pos":"noun","senses":[{"en":"a person (especially a woman) or a thing that is very attractive or exciting to look at","cn":"魅力十足的人（尤指女子）；绝妙的事物","ex":{"en":"The singer is an absolute stunner.","cn":"这位歌手绝对是一个令人惊叹的人。"}},{"en":"something, such as a piece of news, that surprises or shocks you very much","cn":"令人震惊的事情（如新闻等）"}]}},"steakhouse":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a restaurant that serves steak","cn":"牛排餐厅"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41steakhouse.mp3","us":"media/ldoce/hwd/ame/8/steakhouse.mp3"},"oxford":{"phon":"ˈsteɪkhaʊs","pos":"noun","senses":[{"en":"a restaurant that serves mainly steak","cn":"牛排餐馆"}]}},"sty":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 pigsty","en":"A sty is the same as a pigsty ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where pigs are kept","cn":"猪圈﹐猪栏"},{"en":"an infected place on the edge of your eyelid , which becomes red and swollen","cn":"睑腺炎﹐麦粒肿"}]},"media":{"uk":"media/ldoce/hwd/bre/2/sty0205.mp3","us":"media/ldoce/hwd/ame/6/sty1.mp3"},"oxford":{"phon":"staɪ","pos":"noun","senses":[{"en":"a small building or area where pigs are kept","cn":"猪圈；猪场","lab":"North American English also"},{"en":"a very dirty or untidy place","cn":"肮脏的地方；猪窝般邋遢的地方","g":"[singular]","lab":"North American English also"},{"en":"an infection of the eyelid (= the skin above or below the eye) which makes it red and painful","cn":"睑腺炎；麦粒肿"}]}},"stirring":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(活动、演出或描述)激动人心的，鼓舞人心的","en":"A stirring event, performance, or account of something makes people very excited or enthusiastic.","ex":{"en":"The Prime Minister made a stirring speech","cn":"首相发表了一篇鼓舞人心的演讲。"}},{"pos":"N-COUNT 可数名词","cn":"(感情、想法的)萌生，出现，酝酿","en":"A stirring of a feeling or thought is the beginning of one.","ex":{"en":"I feel a stirring of curiosity.","cn":"我开始产生了好奇心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"producing strong feelings or excitement in someone","cn":"激动人心的﹐令人振奋的"},{"en":"an early sign that something is starting to happen","cn":"开始[出现﹐酝酿]的征兆"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdestirring.mp3","us":"media/ldoce/hwd/ame/a/stirring.mp3"},"examples":[{"en":"She felt a stirring of anger.","cn":"她感觉自己忍不住要生气了。"},{"en":"stirring memories","cn":"令人心潮澎湃的回忆"}],"oxford":{"phon":"ˈstɜːrɪŋ","pos":"noun","senses":[{"en":"the beginning of a feeling, an idea or a development","cn":"（感情、想法或发展的）开始，出现，萌动，酝酿","ex":{"en":"She felt a stirring of anger.","cn":"她感觉自己忍不住要生气了。"}},{"en":"causing strong feelings; exciting","cn":"令人激情澎湃的；激动人心的","ex":{"en":"a stirring performance","cn":"动人的表演"},"pos":"adjective"}]}},"stump":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"残余部分;残段;残根","en":"A stump is a small part of something that remains when the rest of it has been removed or broken off.","ex":{"en":"If you have a tree stump, check it for fungus","cn":"要是有树桩的话，检查一下上面有没有长菌类。"}},{"pos":"N-COUNT 可数名词","cn":"(板球三柱门的)柱","en":"In cricket, the stumps are the three wooden sticks that are placed upright in the ground to form the wicket."},{"pos":"VERB 动词","cn":"把…难住;难倒;使…一筹莫展","en":"If you are stumped by a question or problem, you cannot think of any solution or answer to it.","ex":{"en":"John is stumped by an unexpected question","cn":"一个意想不到的问题把约翰难住了。"}},{"pos":"VERB 动词","cn":"迈着沉重的步子走;跺着脚走","en":"If you stump somewhere, you walk there with heavy steps.","ex":{"en":"The Marshal stepped over the vacuum-cleaner and stumped out of the room.","cn":"元帅迈过真空吸尘器，脚步沉重地走出了房间。"}},{"pos":"VERB 动词","cn":"(在选举前)作巡回演说，游说","en":"If politicians stump the country or stump for a candidate, they travel around making campaign speeches before an election.","ex":{"en":"When candidates went stumping around the country, people traveled for miles on foot, by horse, by carriage to hear them speak","cn":"当竞选人在全国作巡回演说时，人们会步行、骑马或坐车数英里赶去听他们的演讲。"}},{"pos":"PHRASE 短语","cn":"(选举前)作巡回演说，在游说","en":"If politicians are on the stump, they are campaigning for an election.","ex":{"en":"The presidential candidates are on the stump today.","cn":"总统候选人今天在作巡回演说。"}},{"pos":"","cn":"","en":"相关词组：stump up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bottom part of a tree that is left in the ground after the rest of it has been cut down 〔","cn":"树被砍倒后留下的〕树桩﹐树墩"},{"en":"the short part of someone’s leg, arm etc that remains after the rest of it has been cut off","cn":"残肢"},{"en":"the small useless part of something that remains after most of it has broken off or worn away","cn":"残余部分﹔残段﹔残根"}]},"vocab":{"pos":"n v","senses":[{"en":"There are three ways to stump : you can ask someone a question they can't answer, you can travel making political speeches, or you can stomp."}]},"media":{"uk":"media/ldoce/hwd/bre/0/stump_v0205.mp3","us":"media/ldoce/hwd/ame/3/stump1.mp3"},"examples":[{"en":"I'm stumped. I don't know how they got here before us.","cn":"我搞不懂了。我不知道他们怎么比我们来得还早。"},{"en":"The senator gave his standard stump speech.","cn":"那位参议员举行了一次公式化的竞选巡回演说。"}],"oxford":{"phon":"stʌmp","pos":"noun","senses":[{"en":"the bottom part of a tree left in the ground after the rest has fallen or been cut down","cn":"树墩；树桩","g":"[countable]"},{"en":"the end of something or the part that is left after the main part has been cut, broken off or worn away","cn":"残余部分；残根；残段","g":"[countable]","ex":{"en":"the stump of a pencil","cn":"铅笔头"}},{"en":"the short part of somebody’s leg or arm that is left after the rest has been cut off","cn":"残肢","g":"[countable]"},{"en":"one of the set of three wooden sticks (called the stumps) that stand in the ground and form the wicket","cn":"（三柱门的）柱","g":"[countable, usually plural]","ex":{"en":"The ball went past the batsman and hit the stumps.","cn":"球越过了击球手并击中了树桩。"}},{"en":"the fact of a politician going to different places before an election and trying to get people’s support by making speeches","cn":"（政治人物在选举前的）巡回演说","g":"[singular]","lab":"informal, especially North American English，，","ex":{"en":"politicians on the stump","cn":"作巡回演说的政治人物"}},{"en":"to ask somebody a question that is too difficult for them to answer or give them a problem that they cannot solve","cn":"把…难住；难倒","g":"[transitive, usually passive]","lab":"informal","ex":{"en":"I'm stumped. I don't know how they got here before us.","cn":"我搞不懂了。我不知道他们怎么比我们来得还早。"},"pos":"verb"},{"en":"to walk in a noisy, heavy way, especially because you are angry or upset","cn":"（尤指愤怒或烦恼时）脚步重重地走","g":"[intransitive]","ex":{"en":"He stumped off, muttering under his breath.","cn":"他嘴里嘟哝着，脚步重重地走了。"},"pos":"verb"},{"en":"to travel around making political speeches, especially before an election","cn":"（尤指在选举前）作巡回演说","g":"[intransitive, transitive]","lab":"North American English","ex":{"en":"He stumped (around) the country trying to build up support.","cn":"他在全国各地巡回演讲，争取更多的支持。"},"pos":"verb"},{"en":"(of a wicketkeeper) to put a batsman out of the game by knocking off either of the bails (= the two pieces of wood that bridge the stumps) with the ball, when they are out of the area in which the ball can be hit, but not running","cn":"（三柱门守门员用球打掉三柱门上的横木）使（击球手）出局","g":"[transitive]","pos":"verb"}]}},"stuck-up":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"傲慢无礼的;自命不凡的","en":"If you say that someone is stuck-up, you mean that are very proud and unfriendly because they think they are very important.","ex":{"en":"She was a famous actress, but she wasn't a bit stuck-up.","cn":"她是著名演员，却丝毫没有明星架子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is snobbish thinks that they are better than people from a lower social class","cn":""},{"en":"someone who thinks that they are better than people from a lower social class, and does not want to talk to them or be friends with them","cn":""},{"en":"proud and unfriendly because you think you are better and more important than other people","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41stuck-up.mp3","us":"media/ldoce/hwd/ame/8/stuck-up.mp3"},"examples":[{"en":"His wife was a bit stuck-up.","cn":"他的妻子有点自以为是。"}],"oxford":{"phon":"ˌstʌk ˈʌp","pos":"adjective","senses":[{"en":"thinking that you are more important than other people and behaving in an unfriendly way towards them","cn":"自命不凡的；趾高气扬的"}]}},"sterling":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"英国货币;英镑","en":"Sterling is the money system of Great Britain.","ex":{"en":"The stamps had to be paid for in sterling.","cn":"这些邮票必须用英镑购买。"}},{"pos":"ADJ 形容词","cn":"(人的品格或工作)优异的，出色的","en":"Sterling means very good in quality; used to describe someone's work or character.","ex":{"en":"Those are sterling qualities to be admired in anyone.","cn":"那些是在任何人身上都值得敬佩的优秀品质。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the standard unit of money in the United Kingdom, based on the pound","cn":"英镑〔英国本位货币单位〕"},{"en":"silver that is at least 92% pure","cn":"标准纯银〔至少达到92%的纯度〕"},{"en":"very good","cn":"极棒的﹐极好的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Sterling is British money, but it also describes anything of very high quality. A sterling report card has all A’s, and sterling manners are needed for a visit with the Queen of England."}]},"collocations":{"phrases":["PHRASES pounds sterling 50 pounds sterling • Note at CURRENCY"]},"media":{"uk":"media/ldoce/hwd/bre/2/sterling_adj0205.mp3","us":"media/ldoce/hwd/ame/b/sterling1.mp3"},"examples":[{"en":"You can be paid in pounds sterling or American dollars.","cn":"可以付你英镑，也可以付你美元。"},{"en":"He has done sterling work on the finance committee.","cn":"他在财务委员会工作优异。"}],"oxford":{"phon":"ˈstɜːlɪŋ","pos":"noun","senses":[{"en":"the money system of the UK, based on the pound","cn":"英镑（英国货币）","ex":{"en":"the value of sterling","cn":"英镑的价值"}},{"en":"of excellent quality","cn":"优秀的；杰出的","ex":{"en":"He has done sterling work on the finance committee.","cn":"他在财务委员会工作优异。"},"pos":"adjective"}]}},"stirrer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"煽动者;制造麻烦的人","en":"If you refer to someone as a stirrer, you disapprove of them because they often try to cause trouble."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who likes to cause trouble between people by spreading false or secret information – used to show disapproval","cn":"爱搬弄是非的人﹐喜欢制造事端者〔含贬义〕"},{"en":"an object shaped like a stick, that is used to mix liquids 〔","cn":"搅拌液体的〕搅棒"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41stirrer.mp3","us":"media/ldoce/hwd/ame/d/ld41stirrer.mp3"},"oxford":{"phon":"ˈstɜːrə(r)","pos":"noun","senses":[{"en":"a person who likes causing trouble, especially between other people, by spreading secrets","cn":"喜欢制造事端的人；（尤指）好拨弄是非者"}]}},"stealthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"悄悄的;偷偷摸摸的;鬼鬼祟祟的","en":"Stealthy actions or movements are performed quietly and carefully, so that no one will notice what you are doing.","ex":{"en":"I would creep in and with stealthy footsteps explore the second-floor","cn":"我会偷偷溜进去，轻手轻脚地查看一下二楼。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"moving or doing something quietly and secretly","cn":"悄悄的﹐鬼鬼祟祟的﹐偷偷的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective stealthy to describe something or someone that is marked by secrecy, even sneakiness. Ninjas are stealthy , moving quietly and cautiously, which makes them excellent spies."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41stealthy.mp3","us":"media/ldoce/hwd/ame/8/stealthy.mp3"},"examples":[{"en":"a stealthy animal","cn":"行动诡秘的动物"},{"en":"a stealthy movement","cn":"隐蔽的移动"}],"oxford":{"phon":"ˈstelθi","pos":"adjective","senses":[{"en":"doing things quietly and secretly; done quietly and secretly","cn":"偷偷摸摸的；不声张的；秘密的","ex":{"en":"a stealthy animal","cn":"行动诡秘的动物"}}]}},"styrofoam":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"聚苯乙烯泡沫塑料(尤用于制造器皿)","en":"Styrofoam is a very light, plastic substance, used especially to make containers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a soft light plastic material that prevents heat or cold from passing through it, used especially to make containers","cn":"舒泰龙泡沫塑料〔有隔热保温作用﹐尤用于制造容器〕"}]},"vocab":{"pos":"n","senses":[{"en":"Styrofoam is a type of polystyrene (a type of plastic) foam that's light yet strong. It’s often used to make take-out coffee cups and packing materials."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41styrofoam.mp3","us":"media/ldoce/hwd/ame/f/laadstyrofoam.mp3"},"examples":[{"en":"Styrofoam cups","cn":"舒泰龙泡沫塑料杯"},{"en":"a Styrofoam cup","cn":"舒泰龙泡沫塑料杯"}],"oxford":{"phon":"ˈstaɪrəfəʊm","pos":"noun","senses":[{"en":"a very light soft plastic that is usually white, used especially for making containers that prevent heat loss","cn":"聚苯乙烯","ex":{"en":"Styrofoam cups","cn":"舒泰龙泡沫塑料杯"}}]}},"stoical":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"坚忍的;坦然的;不以为苦的","en":"If you say that someone behaves in a stoical way, you approve of them because they do not complain or show they are upset in bad situations.","ex":{"en":"She never ceased to admire the stoical courage of those in Northern Ireland","cn":"她一直很敬佩爱尔兰北部人民的坚忍和勇敢。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not showing emotion or not complaining when bad things happen to you","cn":"坚忍的﹔不以苦乐为意的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41stoical.mp3","us":"media/ldoce/hwd/ame/9/stoical.mp3"}},"strait":{"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"海峡;(连接两大海域的)水道","en":"You can refer to a narrow strip of sea which joins two large areas of sea as a strait or the straits .","ex":{"en":"An estimated 1600 vessels pass through the strait annually.","cn":"估计每年有 1,600 艘船通过该海峡。"}},{"pos":"N-PLURAL 复数名词","cn":"(通常指因缺钱造成的)困境，窘迫","en":"If someone is in dire or desperate straits, they are in a very difficult situation, usually because they do not have much money.","ex":{"en":"If we had a child, we'd be in really dire straits","cn":"假如我们有了小孩，我们会真正陷入困境。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a narrow passage of water between two areas of land, usually connecting two seas","cn":"海峡﹔〔狭窄的〕水道"},{"en":"to be in a very difficult situation, especially a financial one","cn":"陷于极度的困境中〔尤指财务困境〕"}]},"vocab":{"pos":"1 n adj 2 n","senses":[{"en":"A strait is a narrow sea channel or a difficult situation — remember that both are difficult to navigate. If you're stranded on a strait off the Black Sea, you might also say that you're in dire straits ."}]},"collocations":{"phrases":["ADJ. narrow","VERB + STRAIT go through, pass through | enter","STRAIT + VERB separate sth The oil terminal is in the narrow strait that separates the island from the mainland.","PREP. across the ~ He tried to swim across the Straits of Gibraltar. | in the ~ a ship anchored in the Straits of Hormuz | on the ~ The town","ADJ. desperate, dire, serious | financial","PREP. in ~ The business is in dire financial straits."]},"media":{"uk":"media/ldoce/hwd/bre/1/strait0205.mp3","us":"media/ldoce/hwd/ame/4/straight1.mp3"},"examples":[{"en":"She found herself in desperate financial straits.","cn":"她发觉自己经济状况极为窘迫。"},{"en":"The factory is in dire straits.","cn":"工厂岌岌可危。"}],"oxford":{"phon":"streɪt","pos":"noun","senses":[{"en":"a narrow passage of water that connects two seas or large areas of water","cn":"海峡；（连结两大水域的）水道","g":"[plural]","ex":{"en":"the Strait(s) of Gibraltar","cn":"直布罗陀海峡"}},{"en":"a very difficult situation especially because of lack of money","cn":"（尤指经济拮据引起的）困境，境况窘迫","g":"[plural]","ex":{"en":"The factory is in dire straits.","cn":"工厂岌岌可危。"}}]}},"stormy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有暴风雨的","en":"If there is stormy weather, there are strong winds and heavy rain.","ex":{"en":"It had been a night of stormy weather, with torrential rain and high winds.","cn":"这是一个暴风雨之夜，大雨倾盆，强风呼啸。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(大海)波涛汹涌的，波浪滔天的","en":"Stormy seas have very large strong waves because there are strong winds.","ex":{"en":"They make the treacherous journey across stormy seas.","cn":"他们穿越了波浪滔天的大海，完成了这次危险之旅。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"争吵激烈的;群情激愤的","en":"If you describe a situation as stormy, you mean it involves a lot of angry argument or criticism.","ex":{"en":"The letter was read at a stormy meeting","cn":"这封信是在一次争吵激烈的会议上念的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if it is windy, there is a lot of wind","cn":""},{"en":"blustery weather is very windy, with sudden strong winds","cn":""},{"en":"if the weather is breezy, the wind blows fairly strongly","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Whether it’s your temper or the month of May, something characterized by turmoil and unpredictable outbursts can be called stormy ."}]},"media":{"uk":"media/ldoce/hwd/bre/f/stormy0205.mp3","us":"media/ldoce/hwd/ame/d/stormy.mp3"},"examples":[{"en":"stormy seas (= with big waves)","cn":"波涛汹涌的大海"},{"en":"a dark and stormy night","cn":"黑暗的暴风雨之夜"}],"oxford":{"phon":"ˈstɔːmi","pos":"adjective","senses":[{"en":"with strong winds and heavy rain or snow","cn":"有暴风雨（或暴风雪）的","ex":{"en":"a dark and stormy night","cn":"黑暗的暴风雨之夜"}},{"en":"full of strong feelings and angry arguments","cn":"群情激愤的；激烈争吵的","ex":{"en":"a stormy debate","cn":"唇枪舌剑的辩论"}}]}},"steward":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(船舶、飞机或火车上的)男服务员，男乘务员","en":"A steward is a man who works on a ship, plane, or train, looking after passengers and serving meals to them."},{"pos":"N-COUNT 可数名词","cn":"（财产）管理员;管家","en":"A steward is someone who has the responsibility for looking after property.","ex":{"en":"The Earl didn't have the money or good judgement to employ a steward to manage the place for him.","cn":"这位伯爵既没钱也没有良好的判断力去雇用一名管家替自己管理这所房子。"}},{"pos":"N-COUNT 可数名词","cn":"(协助组织赛马、游行及其他公共活动的)负责人，管事","en":"A steward is a man or woman who helps to organize a race, march, or other public event.","ex":{"en":"The steward at the march stood his ground while the rest of the marchers decided to run.","cn":"当其他的游行者决定逃跑时，游行活动的负责人坚守着阵地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who operates the controls of a plane","cn":""},{"en":"a pilot who shares the control of a plane with the main pilot","cn":""},{"en":"the pilot who is in charge of an aircraft","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A steward is someone who takes care of the grounds or animals of a particular place. If your parents are always traveling and you have to take care of your six younger siblings, you probably feel like the steward of the house."}]},"media":{"uk":"media/ldoce/hwd/bre/3/steward0205.mp3","us":"media/ldoce/hwd/ame/9/steward.mp3"},"examples":[{"en":"Kissinger was now chief steward of US foreign policy.","cn":"基辛格现在是美国外交政策的主要负责人了。"},{"en":"race stewards","cn":"比赛管理人员"}],"oxford":{"phon":"ˈstjuːəd","pos":"noun","senses":[{"en":"a person whose job is to take care of passengers on a ship, an aircraft or a train and who brings them meals, etc.","cn":"（轮船、飞机或火车上的）乘务员，服务员","ex":{"en":"a ship’s steward","cn":"船舶管家"}},{"en":"a person who helps at a large public event, for example a race or public meeting, by keeping order, showing people where to go, etc.","cn":"（比赛、集会等大型公众活动的）统筹人","ex":{"en":"The race stewards will investigate the incident.","cn":"比赛干事将对此事展开调查。"}},{"en":"a person whose job is to arrange for the supply of food to a college, club, etc.","cn":"（大学、俱乐部等的）伙食管理员"},{"en":"a person employed to manage another person’s property, especially a large house or land","cn":"（私人家中的）管家","ex":{"en":"Moore was acting as steward to Fleming.","cn":"穆尔当时是弗莱明的管家。"}},{"en":"a person whose responsibility it is to take care of something","cn":"看守者；管理者","lab":"figurative","ex":{"en":"Farmers pride themselves on being stewards of the countryside.","cn":"农民为自己是乡村的守望者感到自豪。"}}]}},"stair":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"楼梯","en":"Stairs are a set of steps inside a building which go from one floor to another.","ex":{"en":"Nancy began to climb the stairs","cn":"南希开始爬楼梯。"}},{"pos":"N-SING 单数名词","cn":"一层楼梯;一段楼梯","en":"A stair is a flight of stairs.","ex":{"en":"I followed her down the stair.","cn":"我跟着她下了楼梯。"}},{"pos":"N-COUNT 可数名词","cn":"一级楼梯","en":"A stair is one of the steps in a flight of stairs.","ex":{"en":"Terry was sitting on the bottom stair.","cn":"特里正坐在最下面的一级楼梯上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of steps built for going from one level of a building to another","cn":"楼梯"},{"en":"one of the steps in a set of stairs","cn":"梯级"},{"en":"a staircase 〔","cn":"室内的〕楼梯"}]},"collocations":{"phrases":["ADJ. steep | wide | narrow | rickety | main | back","QUANT. flight We went up three flights of stairs.","VERB + STAIR ascend, climb, go/run, etc. up, mount | descend, go/run, etc. down | take, use Take the back stairs.","STAIR + VERB lead to sth | creak","STAIR + NOUN rod The carpet was held in place by brass stair rods. | gate","PREP. under the ~ a cupboard under the stairs | ~ (down/up) to the stairs to the third floor","PHRASES the bottom/foot/head/top of the stairs, take the stairs two, etc. at a time He rushed up to the bedroom, taking the stairs two at a ","ADJ. top | bottom"]},"media":{"img":["media/ldoce/img/staircase.jpg"],"uk":"media/ldoce/hwd/bre/9/brelasdestair.mp3","us":"media/ldoce/hwd/ame/f/stair.mp3"},"examples":[{"en":"The house had a panelled hall and a fine oak stair.","cn":"房子的门厅装有镶板墙裙，楼梯是用高级栎木建造的。"},{"en":"We had to carry the piano up three flights of stairs.","cn":"我们不得不抬着钢琴上了三段楼梯。"}],"oxford":{"phon":"steə(r)","pos":"adjective","senses":[{"en":"on, of or for stairs","cn":"梯级","ex":{"en":"the stair carpet","cn":"楼梯地毯"}},{"en":"a set of steps built between two floors inside a building","cn":"楼梯","g":"[plural]","ex":{"en":"We had to carry the piano up three flights of stairs.","cn":"我们不得不抬着钢琴上了三段楼梯。"},"pos":"noun"},{"en":"one of the steps in a set of stairs","cn":"梯级","g":"[countable]","ex":{"en":"How many stairs are there up to the second floor?","cn":"上到第三层一共有多少磴楼梯？"},"pos":"noun"},{"en":"a set of stairs inside a building including the banisters (= posts and bars that are fixed at the side)","cn":"（建筑物内带扶手的）楼梯","g":"[singular]","lab":"literary","ex":{"en":"The house had a panelled hall and a fine oak stair.","cn":"房子的门厅装有镶板墙裙，楼梯是用高级栎木建造的。"},"pos":"noun"}]}},"stopgap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"权宜之计;临时替代物","en":"A stopgap is something that serves a purpose for a short time, but is replaced as soon as possible.","ex":{"en":"Gone are the days when work was just a stopgap between leaving school and getting married","cn":"工作曾经只是毕业和结婚之间的临时过渡，但这样的日子已经一去不复返了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"continuing, or intended to continue, for only a short time","cn":""},{"en":"a provisional arrangement is temporary and can be changed or replaced in the future","cn":""},{"en":"an interim report, measure, arrangement etc is one that is used temporarily until a final or complete one is ready","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A stopgap is a temporary solution to a problem, like a piece of cardboard taped over the broken window in your car. Until you can get it fixed, you need a stopgap ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/stopgap0205.mp3","us":"media/ldoce/hwd/ame/7/stopgap.mp3"},"examples":[{"en":"The arrangement was only intended as a stopgap.","cn":"这种安排不过是权宜之计而已。"},{"en":"a stopgap measure","cn":"临时措施"}],"oxford":{"phon":"ˈstɒpɡæp","pos":"noun","senses":[{"en":"something that you use or do for a short time while you are looking for something better","cn":"权宜之计；临时替代的东西","ex":{"en":"The arrangement was only intended as a stopgap.","cn":"这种安排不过是权宜之计而已。"}}]}},"stranded":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"fixed or trapped in a particular position or place and unable to move or be moved","cn":""},{"en":"stuck and impossible to move – used especially about parts of a machine, or something trapped between two surfaces","cn":""},{"en":"twisted together and unable to be separated – used especially about things such as hair, wire, or string getting caught around something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you’re stuck somewhere with no way of getting anywhere else, you’re stranded . If you run out of gas while driving in the desert, you'll be stranded until someone finds you. Good luck!"}]},"collocations":{"phrases":["VERBS be | become, end up, find yourself, get We ended up stranded in Paris with no money. Some people found themselves stranded in the lift"]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdestranded.mp3","us":"media/ldoce/hwd/ame/5/amelasdestranded.mp3"},"examples":[{"en":"Air travellers were left stranded because of icy conditions.","cn":"飞机乘客因冰冻天气而滞留。"},{"en":"There I was, stranded in Rome with no money.","cn":"我当时就那样身无分文地被困在罗马。"}]},"statuary":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"雕像群;雕塑群","en":"If you talk about the statuary in a place, you are referring to all the statues and sculpture there."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"statues","cn":"雕像﹔塑像﹔雕塑作品"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41statuary.mp3","us":"media/ldoce/hwd/ame/2/statuary.mp3"},"examples":[{"en":"a collection of marble statuary","cn":"一批大理石雕像"},{"en":"a fine collection of Greek statuary","cn":"一批精美的希腊雕塑藏品"}],"oxford":{"phon":"ˈstætʃuəri","pos":"noun","senses":[{"en":"statues","cn":"雕塑；雕像；塑像","ex":{"en":"a collection of marble statuary","cn":"一批大理石雕像"}}]}},"stairway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(室内外的)楼梯，台阶","en":"A stairway is a staircase or a flight of steps, inside or outside a building."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a staircase, especially a large or impressive one 〔","cn":"尤指大的或有气派的〕楼梯"}]},"media":{"uk":"media/ldoce/hwd/bre/3/stairway0205.mp3","us":"media/ldoce/hwd/ame/b/laadstairway.mp3"},"oxford":{"phon":"ˈsteəweɪ","pos":"noun","senses":[{"en":"a set of stairs inside or outside a building","cn":"（建筑物内或外的）楼梯，阶梯"}]}},"stave":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指用作武器的)棍，棒，杖","en":"A stave is a strong stick, especially one that is used as a weapon.","ex":{"en":"Many of the men had armed themselves with staves and pieces of iron.","cn":"很多人用棍棒和铁器将自己武装起来。"}},{"pos":"N-COUNT 可数名词","cn":"五线谱","en":"A stave is the five lines that music is written on."},{"pos":"","cn":"","en":"相关词组：stave off"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the set of five lines on which music is written","cn":"五线谱"},{"en":"one of the thin curved pieces of wood fitted close together to form the sides of a barrel 〔","cn":"桶边上呈弧形的〕桶板﹐侧板"},{"en":"to break something inwards 〔","cn":"从外向里〕打破﹐砸破"}]},"vocab":{"pos":"n v","senses":[{"en":"A stave is the crosspiece between the legs of a chair or a wooden slat forming the side of a barrel. In music, it's the five lines you write notes on."}]},"media":{"uk":"media/ldoce/hwd/bre/7/stave_v0205.mp3","us":"media/ldoce/hwd/ame/2/stave1.mp3"},"examples":[{"en":"The side of the boat was staved in when it hit the rocks.","cn":"船触礁把船舷撞扁了。"},{"en":"to stave off hunger","cn":"暂时解饿"}],"oxford":{"phon":"steɪv","pos":"noun","senses":[{"en":"a strong stick or pole","cn":"棍；棒；木柱","ex":{"en":"fence staves","cn":"篱笆桩"}},{"en":"a set of five lines on which music is written","cn":"五线谱","lab":"music"}]}},"stamina":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"持久力;耐力;毅力","en":"Stamina is the physical or mental energy needed to do a tiring activity for a long time.","ex":{"en":"You have to have a lot of stamina to be a top-class dancer.","cn":"你必须有很强的毅力才能成为一流的舞蹈演员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to lift or carry heavy things, to do a lot of physical work etc","cn":""},{"en":"a lot of physical strength in a particular part of your body","cn":""},{"en":"physical strength, use this especially to compare strength with intelligence or skill","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you can run for a really long time, or carry a heavy box a really long way, you have stamina . Stamina is staying power or enduring strength."}]},"collocations":{"phrases":["ADJ. great | mental, physical","VERB + STAMINA have She didn't the stamina to complete the course. | lack | need, require | build (up), increase Aerobic exercise helps to b","PHRASES reserves of stamina Emma Walton had to call on all her reserves of stamina to win the 10,000 metres. | a test of stamina Final exams"]},"media":{"uk":"media/ldoce/hwd/bre/5/stamina0205.mp3","us":"media/ldoce/hwd/ame/d/stamina.mp3"},"examples":[{"en":"It takes a lot of stamina to run a marathon.","cn":"跑马拉松需要很大的耐力。"},{"en":"You need stamina to be a long-distance runner.","cn":"当长跑运动员需要耐力。"}],"oxford":{"phon":"ˈstæmɪnə","pos":"noun","senses":[{"en":"the physical or mental strength that enables you to do something difficult for long periods of time","cn":"耐力；耐性；持久力","lab":"British English","ex":{"en":"It takes a lot of stamina to run a marathon.","cn":"跑马拉松需要很大的耐力。"}}]}},"streamline":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使(机构或过程)效率更高;精简","en":"To streamline an organization or process means to make it more efficient by removing unnecessary parts of it.","ex":{"en":"They're making efforts to streamline their normally cumbersome bureaucracy","cn":"他们正努力精简本来繁冗复杂的官僚体制。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make the processes of a business or system simpler so that it operates more quickly and more efficiently","cn":""},{"en":"to make a business or system more efficient by making it quicker, more modern, and less wasteful","cn":""},{"en":"to make something better","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you streamline something, you're simplifying it to make it more efficient or profitable."}]},"collocations":{"phrases":["ADV. perfectly","PREP. for Dolphins are perfectly streamlined for movement in the water."]},"media":{"uk":"media/ldoce/hwd/bre/6/streamline0205.mp3","us":"media/ldoce/hwd/ame/3/streamline.mp3"},"examples":[{"en":"The cars all have a new streamlined design.","cn":"这些汽车都是流线型新款。"},{"en":"The production process is to be streamlined.","cn":"生产流程还需改进。"}],"oxford":{"phon":"ˈstriːmlaɪn","pos":"verb","senses":[{"en":"to give something a smooth, even shape so that it can move quickly and easily through air or water","cn":"使成流线型","ex":{"en":"The cars all have a new streamlined design.","cn":"这些汽车都是流线型新款。"}},{"en":"to make a system, an organization, etc. work better, especially in a way that saves money","cn":"使（系统、机构等）效率更高；（尤指）使增产节约","ex":{"en":"The production process is to be streamlined.","cn":"生产流程还需改进。"}}]}},"stonewall":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(为隐瞒或逃避某事而)暂不作决定，迟迟不作答复，态度骑墙","en":"If you say that someone stonewalls, you disapprove of them because they delay giving a clear answer or making a clear decision, often because there is something that they want to hide or avoid doing.","ex":{"en":"The administration is just stonewalling in an attempt to hide their political embarrassment","cn":"政府只是在模棱两可地拖延时间，企图掩盖自己的政治窘态。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to delay a discussion, decision etc by talking a lot and refusing to answer questions 〔","cn":"用冗长的发言和拒绝回答问题的办法〕拖延[阻碍]议事[作出决定]"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41stonewall.mp3","us":"media/ldoce/hwd/ame/e/stonewall.mp3"},"oxford":{"phon":"ˈstəʊnwɔːl","pos":"verb","senses":[{"en":"(especially in politics) to delay a discussion or decision by refusing to answer questions or by talking a lot","cn":"防守挡击（政治上指通过沉默或冗长发言等手段阻碍议事或拖延决议）","ex":{"en":"He stonewalled successfully on the Prime Minister’s behalf.","cn":"他成功地代表首相进行了阻挠。"}},{"en":"fighting between the police and gay people that took place after the New York police raided a gay bar, the Stonewall Inn in Greenwich Village in 1969. It was the first time that large numbers of gay people had resisted arrest and the Gay Liberation Front was formed soon afterwards. The riot is considered as the event that marked the beginning of the gay rights movement.","cn":"石墙：1969年纽约警察突袭了一家同性恋酒吧，格林威治村的石墙旅馆后，警察与同性恋者之间发生了战斗。这是许多同性恋者第一次拒绝逮捕，而同性恋解放阵线则是第一次不久之后成立。骚乱被认为是标志着同性恋权利运动开始的事件。","pos":""},{"en":"a group formed in 1989 which campaigns for the rights of LGBT people in Britain. It is involved in political lobbying (= trying to influence the government), carries out research into issues such as discrimination, and fights legal cases to support equal rights for LGBT people. It is now recognized as a charity.","cn":"石墙：成立于1989年的组织，其活动是为英国的LGBT人民争取权利。它参与政治游说（试图影响政府），对歧视等问题进行研究，并为支持LGBT人民平等权利而进行法律诉讼。现在被公认为慈善机构。","pos":""}]}},"stripy":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有条纹的;有斑纹的","en":"Something that is stripy has stripes on it.","ex":{"en":"He was wearing a stripy shirt and baggy blue trousers.","cn":"他身着一件条纹衬衫和一条宽松的蓝裤子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"striped","cn":"有（彩色）条纹的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/stripy0205.mp3","us":"media/ldoce/hwd/ame/d/amelasdestripy.mp3"},"examples":[{"en":"a stripy jumper","cn":"条纹套头毛衣"},{"en":"He was wearing jeans and a stripy T-shirt.","cn":"他穿着牛仔裤和条纹T恤衫。"}],"oxford":{"phon":"ˈstraɪpi","pos":"adjective","senses":[{"en":"marked with a pattern of stripes","cn":"有条纹的","ex":{"en":"a stripy jumper","cn":"条纹套头毛衣"}}]}},"stroller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿手推车","en":"A stroller is a small chair on wheels, in which a baby or small child can sit and be wheeled around."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small chair on wheels, in which a small child sits and is pushed along （","cn":"手推）轻便婴儿车"},{"en":"someone who is strolling","cn":"散步者﹔闲逛者"}]},"vocab":{"pos":"n","senses":[{"en":"A stroller is a small carriage with wheels meant for pushing a baby or toddler around. For a baby, there is no better ride than a stroller ."}]},"media":{"img":["media/ldoce/img/stroller.jpg"],"uk":"media/ldoce/hwd/bre/4/ld41stroller.mp3","us":"media/ldoce/hwd/ame/a/stroller.mp3"},"examples":[{"en":"evening strollers on the promenade","cn":"傍晚在滨海大道散步的人"}],"oxford":{"phon":"ˈstrəʊlə(r)","pos":"noun","senses":[{"en":"a person who is enjoying a slow relaxed walk","cn":"散步者；闲逛者","ex":{"en":"The street was crowded with evening strollers.","cn":"街道上挤满了傍晚的婴儿车。"}},{"en":"a small folding seat on wheels in which a small child sits and is pushed along","cn":"折叠式幼儿车；童车","lab":"North American English"}]}},"stinking":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极其讨厌的;很糟糕的","en":"You use stinking to describe something that is unpleasant or bad.","ex":{"en":"I had a stinking cold.","cn":"我得了该死的感冒。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to be extremely rich","cn":""},{"en":"extremely rich - use this especially when you think this is unfair","cn":""},{"en":"to be extremely rich, especially because you have earned a lot of money in business, or through sport, entertainment etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/stinking_adj0205.mp3","us":"media/ldoce/hwd/ame/3/stinking1.mp3"},"examples":[{"en":"I was pushed into a filthy, stinking room.","cn":"我被推进一间又脏又臭的屋子里。"},{"en":"I wrote them a stinking letter to complain.","cn":"我给他们去信气愤地抱怨了一通。"}],"oxford":{"phon":"ˈstɪŋkɪŋ","pos":"adjective","senses":[{"en":"having a very strong, unpleasant smell","cn":"臭的；发恶臭的；十分难闻的","ex":{"en":"I was pushed into a filthy, stinking room.","cn":"我被推进一间又脏又臭的屋子里。"}},{"en":"very bad or unpleasant","cn":"很糟糕的；令人讨厌的","g":"[only before noun]","lab":"informal, especially British English，，","ex":{"en":"I've got a stinking cold.","cn":"我得了这该死的感冒。"}},{"en":"showing a lot of anger","cn":"愤怒不已的；气急败坏的","g":"[only before noun]","lab":"British English, informal，，","ex":{"en":"I wrote them a stinking letter to complain.","cn":"我给他们去信气愤地抱怨了一通。"}},{"en":"extremely","cn":"极其；非常","ex":{"en":"They must be stinking rich.","cn":"他们一定富得流油。"},"pos":"adverb"}]}},"stockinged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"穿袜而未穿鞋的","en":"If someone is in their stockinged feet, they are wearing socks, tights, or stockings, but no shoes.","ex":{"en":"He tiptoed to the door in his stockinged feet.","cn":"他踮着脚尖走到门口，只穿着袜子没穿鞋。"}}]}},"strobe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"频闪闪光灯","en":"A strobe or a strobe light is a very bright light which flashes on and off very quickly.","ex":{"en":"The band left their strobes on for 20 minutes.","cn":"该乐队演出时闪光灯曾 20 分钟频闪不息。"}}]},"oxford":{"phon":"strəʊb","pos":"noun","senses":[{"en":"a bright light that flashes rapidly on and off","cn":"频闪灯"}]}},"storyteller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"讲故事的人;说书人;小说作家","en":"A storyteller is someone who tells or writes stories.","ex":{"en":"He was the one who first set down the stories of the Celtic storytellers.","cn":"他是首位将凯尔特说书人讲的故事记载下来的人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to tell a story by describing all the events in order, especially at the same time as actors act them out","cn":""},{"en":"a person who tells stories for entertainment","cn":""},{"en":"the person in a story who seems to speak directly to the reader and who describes everything that happens - used especially when you write about literature","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/storyteller0205.mp3","us":"media/ldoce/hwd/ame/f/storyteller.mp3"},"oxford":{"phon":"ˈstɔːritelə(r)","pos":"noun","senses":[{"en":"a person who tells or writes stories","cn":"讲故事的人；故事（或小说）作者"}]}},"stucco":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(粉刷墙壁或装饰天花板用的)粉饰灰泥","en":"Stucco is a type of plaster used for covering walls and decorating ceilings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of plaster that is used especially to cover the outside walls of buildings 〔","cn":"尤用于涂抹外墙的〕灰泥"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41stucco.mp3","us":"media/ldoce/hwd/ame/0/stucco.mp3"},"examples":[{"en":"a stuccoed wall","cn":"拉毛粉饰的墙"}],"oxford":{"phon":"ˈstʌkəʊ","pos":"noun","senses":[{"en":"a type of plaster that is used for covering ceilings and the outside walls of buildings","cn":"（涂墙壁或天花板用的）拉毛灰泥"}]}},"stripper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指参加演出的)脱衣舞演员，脱衣舞者","en":"A stripper is a person who earns money by taking their clothes off in public, especially as part of a show.","ex":{"en":"She worked as a stripper and did some acting.","cn":"她以跳脱衣舞为职业，有时也演些戏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance that is used to remove stains, marks, make-up etc","cn":""},{"en":"a substance that is used to remove paint or wallpaper","cn":""},{"en":"someone whose job is to take off their clothes in a sexually exciting way in order to entertain people","cn":"脱衣舞演员"}]},"media":{"uk":"media/ldoce/hwd/bre/4/stripper0205.mp3","us":"media/ldoce/hwd/ame/d/stripper.mp3"},"examples":[{"en":"a male stripper","cn":"脱衣舞男演员"},{"en":"paint stripper","cn":"脱漆剂"}],"oxford":{"phon":"ˈstrɪpə(r)","pos":"noun","senses":[{"en":"a performer who takes his or her clothes off in a sexually exciting way in front of an audience","cn":"脱衣舞演员","g":"[countable]","ex":{"en":"a male stripper","cn":"脱衣舞男演员"}},{"en":"a substance or tool that is used for removing paint, etc. from something","cn":"剥离剂；脱漆剂；剥离器","g":"[uncountable, countable]","ex":{"en":"paint stripper","cn":"脱漆剂"}}]}},"stalwart":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指某个政党的)忠实拥护者，坚定分子","en":"A stalwart is a loyal worker or supporter of an organization, especially a political party.","ex":{"en":"His free-trade policies aroused suspicion among Tory stalwarts","cn":"他的自由贸易政策在保守党的忠实拥护者中间引起了怀疑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忠实的;坚定的;完全可靠的","en":"A stalwart supporter or worker is loyal, steady, and completely reliable.","ex":{"en":"...a stalwart supporter of the colonial government","cn":"殖民政府的忠实拥护者"}},{"pos":"ADJ 形容词","cn":"强壮的;雄健的","en":"A stalwart man is strong.","ex":{"en":"I knew I was never in any danger with my stalwart bodyguard around me.","cn":"我知道有强壮的保镖在我的周围，我永远不会有什么危险。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is very loyal to a particular organization or set of ideas, and works hard for them 〔","cn":"某组织或思想的〕忠实拥护者﹐坚定分子"},{"en":"a very loyal and strong supporter etc","cn":"忠实拥护者/盟友等"},{"en":"strong in appearance","cn":"强壮的﹔雄健的"}]},"vocab":{"pos":"adj n","senses":[{"en":"To be stalwart is to be loyal, no matter what, like your friend who remains a devoted fan of an actor she's admired since childhood, even if that was the last time the guy made a decent movie."}]},"media":{"uk":"media/ldoce/hwd/bre/9/stalwart_adj0205.mp3","us":"media/ldoce/hwd/ame/8/stalwart1.mp3"},"examples":[{"en":"stalwart supporters","cn":"忠实的拥护者"},{"en":"Rob’s a stalwart of the school’s chess club.","cn":"罗布是学校国际象棋俱乐部的铁杆成员。"}],"oxford":{"phon":"ˈstɔːlwət","pos":"noun","senses":[{"en":"a loyal supporter who does a lot of work for an organization, especially a political party","cn":"（政党等组织的）忠诚拥护者，坚定分子","ex":{"en":"a Labour/Tory stalwart","cn":"工党/保守党的坚定支持者"}},{"en":"always showing support and able to be relied on, even in a difficult situation","cn":"忠诚的；可靠的","ex":{"en":"stalwart supporters","cn":"忠实的拥护者"},"pos":"adjective"},{"en":"physically strong","cn":"健壮的；强壮的","lab":"formal","pos":"adjective"}]}},"stanza":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诗节","en":"A stanza is one of the parts into which a poem is divided."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of words or sentences that form one part of a poem","cn":""},{"en":"a group of lines in a repeated pattern, which form part of a poem","cn":""},{"en":"a group of lines in a repeated pattern forming part of a poem 〔","cn":"诗的〕节﹐段"}]},"vocab":{"pos":"n","senses":[{"en":"Stanzas are the building blocks of formal poetry, like paragraphs in a story or verses in a song. They usually have the same number of lines each time, and often use a rhyming pattern that repeats with each new stanza ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/stanza0205.mp3","us":"media/ldoce/hwd/ame/c/stanza.mp3"},"oxford":{"phon":"ˈstænzə","pos":"noun","senses":[{"en":"a group of lines in a repeated pattern that form a unit in some types of poem","cn":"（诗的）节，段"}]}},"stork":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鹳(一种长喙长腿的大鸟，通常生活在水边)","en":"A stork is a large bird with a long beak and long legs, which lives near water."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall white bird with long legs and a long beak （","cn":"白）鹳"}]},"media":{"uk":"media/ldoce/hwd/bre/1/stork0205.mp3","us":"media/ldoce/hwd/ame/8/stork.mp3"},"oxford":{"phon":"stɔːk","pos":"noun","senses":[{"en":"a large black and white bird with a long beak and neck and long legs, that lives near water but often builds its nest on the top of a high building. There is a tradition that says that it is storks that bring people their new babies.","cn":"鹳"},{"en":"a British make of margarine (= a substance like butter, but usually made from vegetable oil)","cn":"英国制造的人造黄油"}]}},"stake":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"处于危险境地;处于成败关头","en":"If something is at stake, it is being risked and might be lost or damaged if you are not successful.","ex":{"en":"The tension was naturally high for a game with so much at stake","cn":"对于一场成败攸关的比赛来说气氛自然非常紧张。"}},{"pos":"N-PLURAL 复数名词","cn":"(比赛或行动的)赌注，风险","en":"The stakes involved in a contest or a risky action are the things that can be gained or lost.","ex":{"en":"The game was usually played for high stakes between two large groups","cn":"游戏通常在两大集团之间进行，下的赌注一般都很大。"}},{"pos":"VERB 动词","cn":"将…押(在…);以…打赌;拿…冒险","en":"If you stake something such as your money or your reputation on the result of something, you risk your money or reputation on it.","ex":{"en":"He has staked his political future on an election victory","cn":"他把自己的政治前途押在竞选获胜上。"}},{"pos":"N-COUNT 可数名词","cn":"利害关系;重大利益;(企业等中的)股本，股份","en":"If you have a stake in something such as a business, it matters to you, for example because you own part of it or because its success or failure will affect you.","ex":{"en":"He was eager to return to a more entrepreneurial role in which he had a big financial stake in his own efforts","cn":"他渴望回到一个更多参与创业的角色，那样他所付出的努力会与自己的经济利益息息相关。"}},{"pos":"N-PLURAL 复数名词","cn":"比赛;竞赛","en":"You can use stakes to refer to something that is like a contest. For example, you can refer to the choosing of a leader as the leadership stakes .","ex":{"en":"Britain lags behind in the European childcare stakes.","cn":"英国在儿童保育方面落后于欧洲其他国家。"}},{"pos":"N-COUNT 可数名词","cn":"桩","en":"A stake is a pointed wooden post which is pushed into the ground, for example in order to support a young tree."},{"pos":"PHRASE 短语","cn":"提出权利要求;主张权利","en":"If you stake a claim, you say that something is yours or that you have a right to it.","ex":{"en":"Jane is determined to stake her claim as an actress","cn":"简决心主张自己作为一名女演员的权利。"}},{"pos":"","cn":"","en":"相关词组：stake out"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you own something, especially something big like a house, a car, or a company, it is your property and you have the legal right to have it","cn":""},{"en":"to own something, especially something that ordinary people are likely to own","cn":""},{"en":"to own something - use this especially in negative sentences to say that someone does not own something that most people own","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n v","senses":[{"en":"A stake is a wooden stick, sharpened on one end and used to mark property lines (or slay a vampire)."}]},"collocations":{"phrases":["ADJ. big, high | low, small | political","VERB + STAKE play for They always play for high stakes. | raise | lower","PREP. at ~ The minister will face the enquiry with his reputation at stake. 2 share of a company, etc.","ADJ. controlling, large, majority, significant, substantial | minority, small | direct | financial, equity","VERB + STAKE have | acquire, buy, take | sell | build up, increase, lift, raise | cut, reduce","PREP. ~ in She acquired a four per cent direct stake in the business."]},"media":{"uk":"media/ldoce/hwd/bre/c/stake_n0205.mp3","us":"media/ldoce/hwd/ame/9/stake1.mp3"},"examples":[{"en":"Adams staked his claim for a place in the Olympic team with his easy win yesterday.","cn":"亚当斯昨天轻松获胜，这无异于告诉人们奥运代表队中应有他的位置。"},{"en":"She staked her political career on tax reform, and lost.","cn":"她把自己的政治前程押在税制改革上，结果赌输了。"}],"oxford":{"phon":"steɪk","pos":"noun","senses":[{"en":"money that somebody invests in a company","cn":"股本；股份","g":"[countable]","ex":{"en":"a 20 per cent stake in the business","cn":"那家公司 20% 的股份"}},{"en":"a part or share in a business, plan, etc. that will bring you money or other benefits if it succeeds","cn":"（在公司、计划等中的）利益，利害关系","g":"[singular]","ex":{"en":"She has a personal stake in the success of the play.","cn":"这出戏成功与否对她个人有重大利害关系。"}},{"en":"something that you risk losing, especially money, when you try to predict the result of a race, game, etc., or when you are involved in an activity that can succeed or fail","cn":"赌注","g":"[countable]","ex":{"en":"How much was the stake (= how much did you bet)?","cn":"下了多少注？"}},{"en":"a wooden or metal post that is pointed at one end and pushed into the ground in order to support something, mark a particular place, etc.","cn":"桩；标桩；篱笆桩","g":"[countable]","ex":{"en":"Tall plants can be secured by tying them to stakes.","cn":"高大的植物可以通过将它们绑在木桩上来固定。"}},{"en":"a wooden post that somebody could be tied to in former times before being burnt to death (= killed by fire) as a punishment","cn":"火刑柱","g":"[singular]","ex":{"en":"Joan of Arc was burnt at the stake.","cn":"圣女贞德被处以火刑。"}},{"en":"the money that is paid to the winners in horse racing","cn":"赛马奖金","g":"[plural]"},{"en":"used in the names of some horse races","cn":"（用于某些赛马赛事的名称）…赛","g":"[uncountable]"},{"en":"to risk money or something important on the result of something","cn":"（就某事）以…打赌，拿…冒险","ex":{"en":"He staked £25 on the favourite (= for example, in horse racing).","cn":"他在那匹众人看好的马上押了 25 英镑。"},"pos":"verb"},{"en":"to support something with a stake","cn":"用桩支撑","ex":{"en":"to stake newly planted trees","cn":"用木桩支撑新植的树"},"pos":"verb"}]}},"stink":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出恶臭;散发难闻气味","en":"To stink means to smell extremely unpleasant.","ex":{"en":"Get away from me —your breath stinks","cn":"离我远点——你有口臭。"}},{"pos":"VERB 动词","cn":"令人讨厌;让人反感;让人感觉糟糕","en":"If you say that something stinks, you mean that you disapprove of it because it involves ideas, feelings, or practices that you do not like.","ex":{"en":"I think their methods stink","cn":"我认为他们的方法糟透了。"}},{"pos":"N-SING 单数名词","cn":"(引人注意的)发怒，大吵大闹，泄愤","en":"If someone makes a stink about something they are angry about, they show their anger in order to make people take notice.","ex":{"en":"The family's making a hell of a stink","cn":"这家人正在大吵大闹。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have an unpleasant smell","cn":""},{"en":"to have a strong and unpleasant smell","cn":""},{"en":"to have a very strong smell of something unpleasant","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When things stink , they smell terrible. If you throw food scraps in your kitchen trash can, it will eventually start to stink ."}]},"collocations":{"phrases":["ADJ. acrid, overpowering","STINK + NOUN bomb","PREP. ~ of the acrid stink of cordite 2 very strong complaint about sth","ADJ. tremendous","VERB + STINK cause, kick up, make, raise The parents of the pupils say they'll kick up a stink if the school roof isn't repaired before the "]},"media":{"uk":"media/ldoce/hwd/bre/5/stink_v0205.mp3","us":"media/ldoce/hwd/ame/0/stink1.mp3"},"examples":[{"en":"‘What do you think of the idea?’ ‘I think it stinks. ’ “","cn":"你觉得这个主意怎么样？” “我觉得是个馊主意。”"},{"en":"We'll kick up a stink (= complain a lot and cause trouble) if they try to close the school down.","cn":"假如他们想关闭这所学校，我们就要大闹一场。"}],"oxford":{"phon":"stɪŋk","pos":"verb","senses":[{"en":"to have a strong, unpleasant smell","cn":"有臭味；有难闻的气味","g":"[intransitive]","ex":{"en":"Her breath stank of garlic.","cn":"她嘴里有股大蒜味。"}},{"en":"to seem very bad, unpleasant or dishonest","cn":"让人觉得很糟糕；令人厌恶；似乎有不正当行为","g":"[intransitive]","ex":{"en":"The whole business stank of corruption.","cn":"这件事从头到尾都有腐败嫌疑。"}},{"en":"a very unpleasant smell","cn":"恶臭；难闻气味","g":"[countable, usually singular]","ex":{"en":"The room was filled with the stink of sweat and urine.","cn":"房间里弥漫着难闻的汗味和尿味。"},"pos":"noun"},{"en":"a lot of trouble and anger about something","cn":"吵闹；争吵","g":"[singular]","ex":{"en":"The whole business caused quite a stink.","cn":"整件事引起了轩然大波。"},"pos":"noun"}]}},"stampede":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(人群的)蜂拥，狂奔;(动物的)惊逃，乱窜","en":"If there is a stampede, a group of people or animals run in a wild, uncontrolled way.","ex":{"en":"There was a stampede for the exit.","cn":"大家都争先恐后地朝出口涌去。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)争先恐后地奔逃;(使)惊逃","en":"If a group of animals or people stampede or if something stampedes them, they run in a wild, uncontrolled way.","ex":{"en":"The crowd stampeded and many were crushed or trampled underfoot","cn":"人群争先恐后地奔逃，很多人被压伤或踩踏。"}},{"pos":"N-COUNT 可数名词","cn":"热潮;风尚;争先恐后的现象","en":"If a lot of people all do the same thing at the same time, you can describe it as a stampede .","ex":{"en":"Generous redundancy terms had triggered a stampede of staff wanting to leave.","cn":"优厚的裁员条件引发了职员争先恐后地要求辞职的现象。"}},{"pos":"VERB 动词","cn":"迫使;强迫","en":"If people are stampeded into doing something, they are forced into doing it by pressure from other people, even though they do not think it is the right thing to do.","ex":{"en":"Do we really want to be stampeded in such a way?","cn":"我们真的愿意被这样逼迫吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a group of people all want to do the same thing at the same time 〔","cn":"人群的〕蜂拥﹐争先恐后"},{"en":"when a group of large animals or people suddenly start running in the same direction because they are frightened or excited 〔","cn":"人群的〕奔逃﹐蜂拥﹔〔动物的〕逃窜﹐狂奔"},{"en":"if a group of large animals or people stampede, they suddenly start running together in the same direction because they are frightened or excited （","cn":"使）奔逃﹔（使）蜂拥﹔（使）狂奔"}]},"vocab":{"pos":"n v","senses":[{"en":"Do you see hundreds of cattle thundering toward you? Then stop reading and get out of there! A stampede is coming."}]},"media":{"uk":"media/ldoce/hwd/bre/6/stampede_v0205.mp3","us":"media/ldoce/hwd/ame/9/stampede1.mp3"},"examples":[{"en":"Falling interest rates has led to a stampede to buy property.","cn":"不断下降的利率引发了一场购房热。"},{"en":"A huge bunch of kids came stampeding down the corridor.","cn":"一大群孩子顺着走廊涌了过来。"}],"oxford":{"phon":"stæmˈpiːd","pos":"noun","senses":[{"en":"a situation in which a group of people or large animals such as horses suddenly start running in the same direction, especially because they are frightened or excited","cn":"（人群的）奔逃，蜂拥；（兽群的）惊跑，狂奔","ex":{"en":"A stampede broke out when the doors opened.","cn":"门一开，人们蜂拥而出。"}},{"en":"a situation in which a lot of people are trying to do or achieve the same thing at the same time","cn":"热潮；风尚；风气","ex":{"en":"Falling interest rates has led to a stampede to buy property.","cn":"不断下降的利率引发了一场购房热。"}},{"en":"to run in a stampede; to make animals do this","cn":"（使）狂奔，涌向","g":"[intransitive, transitive]","ex":{"en":"a herd of stampeding elephants","cn":"一群狂奔的大象"},"pos":"verb"},{"en":"to make somebody rush into doing something without giving them time to think about it","cn":"使仓促行事","g":"[transitive, usually passive]","ex":{"en":"I refuse to be stampeded into making any hasty decisions.","cn":"我不愿仓促行事，草率作决定。"},"pos":"verb"}]}},"starch":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"淀粉","en":"Starch is a substance that is found in foods such as bread, potatoes, pasta, and rice and gives you energy.","ex":{"en":"She reorganised her eating so that she was taking more fruit and vegetables and less starch, salt, and fat.","cn":"她重新调整了自己的饮食，多吃水果、蔬菜，少吃淀粉、盐和脂肪。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(给布上浆用的)淀粉浆","en":"Starch is a substance that is used for making cloth stiffer, especially cotton and linen."},{"pos":"VERB 动词","cn":"给(布)上浆","en":"If you starch cloth, you make it stiffer using starch.","ex":{"en":"I took down the curtains, washed, and starched them.","cn":"我摘下窗帘，洗了洗，然后给它们上了浆。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance which provides your body with energy and is found in foods such as grain, rice, and potatoes, or a food that contains this substance","cn":"淀粉﹔含淀粉的食物"},{"en":"a substance that is mixed with water and is used to make cloth stiff 〔","cn":"用于浆布料的〕浆粉"},{"en":"to make cloth stiff, using starch","cn":"给〔布料〕上浆"}]},"vocab":{"pos":"n v","senses":[{"en":"Starch is the stuff that makes your shirt collar look crisp and fresh. It's also the complex carbohydrate that potatoes and rice — foods that are called starches — have lots of."}]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdestarch.mp3","us":"media/ldoce/hwd/ame/6/starch1.mp3"},"examples":[{"en":"There's too much starch in your diet.","cn":"你的日常饮食中淀粉含量太高。"},{"en":"You need to cut down on starches.","cn":"你得少吃些含淀粉的东西。"}],"oxford":{"phon":"stɑːtʃ","pos":"noun","senses":[{"en":"a white carbohydrate food substance found in potatoes, flour, rice, etc.; food containing this","cn":"淀粉；含淀粉的食物","g":"[uncountable, countable]","ex":{"en":"There's too much starch in your diet.","cn":"你的日常饮食中淀粉含量太高。"}},{"en":"starch prepared in powder form or as a spray and used for making clothes, sheets, etc. stiff","cn":"（浆衣服、床单等用的）淀粉浆","g":"[uncountable]","ex":{"en":"Spray starch on the shirt collars before ironing them.","cn":"熨衬衫领要先喷些粉浆再熨。"}},{"en":"to make clothes, sheets, etc. stiff using starch","cn":"把（衣服、床单等）浆一浆","ex":{"en":"a starched white shirt","cn":"浆过的白衬衫"},"pos":"verb"}]}},"staple":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(食物、产品或活动)主要的，基本的","en":"A staple food, product, or activity is one that is basic and important in people's everyday lives.","ex":{"en":"Rice is the staple food of more than half the world's population","cn":"稻米是全世界一半以上人口的主食。"}},{"pos":"N-COUNT 可数名词","cn":"主要部分;重要内容","en":"A staple is something that forms an important part of something else.","ex":{"en":"Political reporting has become a staple of American journalism.","cn":"政治新闻已成为美国新闻报道的主要内容。"}},{"pos":"N-COUNT 可数名词","cn":"订书钉","en":"Staples are small pieces of bent wire that are used mainly for holding sheets of paper together firmly. You put the staples into the paper using a device called a stapler."},{"pos":"VERB 动词","cn":"用订书机订","en":"If you staple something, you fasten it to something else or fix it in place using staples.","ex":{"en":"Staple some sheets of paper together into a book.","cn":"用订书机将几页纸装订成册。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of thin wire that is pushed into sheets of paper and bent over to hold them together","cn":"订书钉"},{"en":"a small U-shaped piece of metal with pointed ends, used to hold something in place U","cn":"形钉"},{"en":"a food that is needed and used all the time","cn":"基本食物﹔主食"}]},"vocab":{"pos":"1 n adj 2 n v","senses":[{"en":"Bread. Milk. Gasoline. Xboxes. What do these all have in common? They're all a staple of most people's consumption — basic products for which there will always be a demand."}]},"media":{"uk":"media/ldoce/hwd/bre/b/staple_n0205.mp3","us":"media/ldoce/hwd/ame/5/staple1.mp3","img":["media/thumb/staple.jpg"]},"examples":[{"en":"Aid workers helped distribute corn, milk and other staples.","cn":"救助人员协助分发谷物、牛奶及其他必需的食物。"},{"en":"Royal gossip is a staple of the tabloid press.","cn":"围绕王室成员的蜚短流长是小报的主要内容。"}],"oxford":{"phon":"ˈsteɪpl","pos":"adjective","senses":[{"en":"forming a basic, large or important part of something","cn":"主要的；基本的；重要的","ex":{"en":"The staple crop is rice.","cn":"主要农作物为水稻。"}},{"en":"a small piece of wire that is used in a device called a stapler and is pushed through pieces of paper and bent over at the ends in order to fasten the pieces of paper together","cn":"订书钉","pos":"noun"},{"en":"a small piece of metal in the shape of a U that is hit into wooden surfaces using a hammer, used especially for holding electrical wires in place","cn":"U 形钉；U 形电线卡","pos":"noun"},{"en":"a basic type of food that is used a lot","cn":"基本食物；主食","ex":{"en":"Aid workers helped distribute corn, milk and other staples.","cn":"救助人员协助分发谷物、牛奶及其他基本食物。"},"pos":"noun"},{"en":"something that is produced by a country and is important for its economy","cn":"（某国的）主要产品，支柱产品","ex":{"en":"Rubber became the staple of the Malayan economy.","cn":"橡胶成了马来亚经济的支柱产品。"},"pos":"noun"},{"en":"a large or important part of something","cn":"主要部分；重要内容","ex":{"en":"Royal gossip is a staple of the tabloid press.","cn":"围绕王室成员的飞短流长是小报的主要内容。"},"pos":"noun"},{"en":"to attach one thing to another using a staple or staples","cn":"用订书钉装订","ex":{"en":"Staple the invoice to the receipt.","cn":"把发票订到收据上。"},"pos":"verb"}]}},"stepmother":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"继母","en":"Someone's stepmother is the woman who has married their father after the death or divorce of their mother."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a female parent","cn":""},{"en":"used when talking to your father, or about someone’s father","cn":""},{"en":"a name for mother, which is used especially by young children or when you are talking to young children","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/stepmother0205.mp3","us":"media/ldoce/hwd/ame/a/laadstepmother.mp3"},"oxford":{"phon":"ˈstepmʌðə(r)","pos":"noun","senses":[{"en":"a woman who is the wife or partner of your father but who is not your birth mother","cn":"继母"}]}},"stogie":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"细支雪茄","en":"A stogie is a long thin cigar."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cigar , especially a thick cheap one","cn":"雪茄〔尤指廉价的粗雪茄〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/stogie0205.mp3","us":"media/ldoce/hwd/ame/e/laadstogie.mp3"}},"stir":{"collins":{"senses":[{"pos":"VERB 动词","cn":"搅动;搅拌;搅和","en":"If you stir a liquid or other substance, you move it around or mix it in a container using something such as a spoon.","ex":{"en":"Stir the soup for a few seconds","cn":"将汤搅和几秒钟。"}},{"pos":"VERB 动词","cn":"(因不舒服)稍稍活动;(睡醒前)挪动身体","en":"If you stir, you move slightly, for example because you are uncomfortable or beginning to wake up.","ex":{"en":"Eileen shook him, and he started to stir","cn":"艾琳晃了晃他，他开始醒过来。"}},{"pos":"VERB 动词","cn":"离开","en":"If you do not stir from a place, you do not move from it.","ex":{"en":"She had not stirred from the house that evening","cn":"她那天晚上没有离开过那座房子。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)轻轻拂动","en":"If something stirs or if the wind stirs it, it moves gently in the wind.","ex":{"en":"Palm trees stir in the soft Pacific breeze","cn":"棕榈树在太平洋和煦的微风中轻轻地摇动。"}},{"pos":"VERB 动词","cn":"(使)行动;(使)开始做;激励","en":"If you stir yourself, or if something stirs you into action, you move in order to start doing something.","ex":{"en":"Stir yourself! We've got a visitor","cn":"动起来！有客人来了。"}},{"pos":"VERB 动词","cn":"打动;激起，激发(强烈的感情)","en":"If something stirs you, it makes you react with a strong emotion.","ex":{"en":"The voice, less coarse now, stirred her as it had then","cn":"现在那声音已不那么刺耳，它又如当年一样让她怦然心动。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(回忆、感情或情绪)产生，苏醒，萌动;引发;唤起","en":"If a particular memory, feeling, or mood stirs or is stirred in you, you begin to think about it or feel it.","ex":{"en":"Then a memory stirs in you and you start feeling anxious","cn":"接着一段回忆涌上心头，你开始感到焦虑不安。"}},{"pos":"N-SING 单数名词","cn":"轰动;骚动;骚乱","en":"If an event causes a stir, it causes great excitement, shock, or anger among people.","ex":{"en":"His film has caused a stir in America.","cn":"他的电影已在美国引起了轰动。"}},{"pos":"PHRASE 短语","cn":"受到轻微影响;小受打击","en":"If you say that someone has been shaken but not stirred by an experience, you mean that they have been slightly disturbed or emotionally affected by it, but not deeply enough to change their behaviour or way of thinking.","ex":{"en":"A clash with America over farm subsidies had left the Europeans and their common agricultural policy shaken but not stirred.","cn":"在农场补贴问题上和美国之间的冲突使得欧洲人以及其共同的农业政策略受冲击。"}},{"pos":"","cn":"","en":"相关词组：stir up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put different substances or liquids together so that they can no longer be separated","cn":""},{"en":"to mix things together so that they form a single substance. Combine is more formal than mix","cn":""},{"en":"to move a spoon or stick around in a liquid, a pan etc, especially when you are mixing things together","cn":""}]},"collocations":{"phrases":["ADJ. good","VERB + STIR give sth Give the mixture a good stir. 2 general excitement or shock","ADJ. considerable, great, real","VERB + STIR cause, create","PREP. ~ about/over There was quite a stir about the book. | ~ among/amongst The discovery caused something of a stir among physicists.","PHRASES quite a/something of a stir"]},"media":{"uk":"media/ldoce/hwd/bre/3/stir_v0205.mp3","us":"media/ldoce/hwd/ame/4/stir1.mp3"},"examples":[{"en":"We've got enough problems without you trying to stir things up.","cn":"我们麻烦事儿已经够多的了，你就别再挑拨是非了。"},{"en":"Whenever he's around, he always manages to stir up trouble.","cn":"什么时候只要有他在，他就总要挑起点事来。"}],"oxford":{"phon":"stɜː(r)","pos":"verb","senses":[{"en":"to move a liquid or substance around, using a spoon or something similar, in order to mix it completely","cn":"搅动；搅和；搅拌","g":"[transitive]","lab":"British English","sc":"mix","ex":{"en":"She stirred her tea.","cn":"她搅了搅茶。"}},{"en":"to move, or to make something move, slightly","cn":"（使）微动","g":"[intransitive, transitive]","sc":"move","ex":{"en":"She heard the baby stir in the next room.","cn":"她听见婴儿在隔壁动弹。"}},{"en":"to move, or to make somebody move, in order to do something","cn":"（使）行动，活动","g":"[intransitive, transitive]","sc":"move","ex":{"en":"You haven't stirred from that chair all evening!","cn":"你坐在那把椅子上一晚上没动了！"}},{"en":"to make somebody excited or make them feel something strongly","cn":"打动；激发","g":"[transitive]","sc":"feelings","ex":{"en":"It's a book that really stirs the imagination.","cn":"这是一本真正能够激发想象力的书。"}},{"en":"to begin to be felt","cn":"开始感到；逐渐产生；萌动；被唤起","g":"[intransitive]","sc":"feelings","ex":{"en":"A feeling of guilt began to stir in her.","cn":"她心里渐渐生出了内疚感。"}},{"en":"to try to cause trouble","cn":"拨弄是非","g":"[transitive, intransitive]","lab":"British English, informal, disapproving，，，，","sc":"cause trouble","ex":{"en":"You're just stirring it!","cn":"你这不是搬弄是非吗！"}},{"en":"excitement, anger or shock that is felt by a number of people","cn":"（一些人感到的）激动，愤怒，震动","g":"[singular]","ex":{"en":"Her resignation caused quite a stir.","cn":"她的辞职引起很大震动。"},"pos":"noun"},{"en":"the action of stirring something","cn":"搅动；搅和；搅拌","g":"[countable, usually singular]","ex":{"en":"Could you give the rice a stir?","cn":"你把米饭搅一搅好吗？"},"pos":"noun"}]}},"statesman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"政治家","en":"A statesman is an important and experienced politician, especially one who is widely known and respected.","ex":{"en":"Hamilton is a great statesman and political thinker.","cn":"汉密尔顿是个伟大的政治家和政治思想家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works in politics, especially an elected member of the government","cn":""},{"en":"a political or government leader, especially one who is well-respected","cn":""},{"en":"in Britain, someone who has been elected to a parliament to represent people from a particular area of the country","cn":""}]},"collocations":{"phrases":["ADJ. great, leading | elder, senior Political power resided with the nation's elder statesman and party leader. | international, world his r"]},"media":{"uk":"media/ldoce/hwd/bre/5/statesman0205.mp3","us":"media/ldoce/hwd/ame/1/statesman.mp3"},"examples":[{"en":"the party's elder statesman","cn":"该党元老"},{"en":"a respected elder statesman","cn":"一位受人尊敬的政界元老"}],"oxford":{"phon":"ˈsteɪtsmən","pos":"noun","senses":[{"en":"a man who is a wise, experienced and respected political leader","cn":"政治家","ex":{"en":"the party’s elder statesman","cn":"该党元老"}}]}},"stacked":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"堆满了…的","en":"If a place or surface is stacked with objects, it is filled with piles of them.","ex":{"en":"Shops in Ho Chi Minh City are stacked with goods.","cn":"胡志明市的商店里堆满了商品。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to have something that makes you more likely to succeed than other people","cn":""},{"en":"if someone is at an advantage , they have experience or qualities which make them more likely to succeed in doing something or more likely to do something well","cn":""},{"en":"used to say that someone has a big advantage in a competition, election etc so that they are very likely to win","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/stacked0205.mp3","us":"media/ldoce/hwd/ame/f/stacked.mp3"},"examples":[{"en":"a table stacked with glasses","cn":"摆满了玻璃杯的桌子"}],"oxford":{"phon":"stækt","pos":"adjective","senses":[{"en":"if a surface is stacked with objects, there are large numbers or piles of them on it","cn":"放有大量…；放有成叠（或成摞、成堆）…","ex":{"en":"a table stacked with glasses","cn":"摆满了玻璃杯的桌子"}}]}},"stingray":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"魟鱼;刺魟","en":"A stingray is a type of large flat fish with a long tail which it can use as a weapon."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large flat fish that has a long tail with sharp poisonous points on it","cn":"刺魟"}]},"media":{"img":["media/ldoce/img/stingray.jpg"],"uk":"media/ldoce/hwd/bre/5/ld41stingray.mp3","us":"media/ldoce/hwd/ame/d/stingray.mp3"},"oxford":{"phon":"ˈstɪŋreɪ","pos":"noun","senses":[{"en":"a large, wide, flat sea fish that has a long tail with a sharp sting in it that can cause serious wounds","cn":"魟鱼，魔鬼鱼（大型扁宽海鱼，尾长，有尖刺）"}]}},"strapless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(连衣裙或胸罩)无肩带的，无吊带的","en":"A strapless dress or bra does not have the usual narrow bands of material over the shoulders.","ex":{"en":"...a black, strapless evening dress.","cn":"黑色的无肩带女式晚礼服"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"one that does not have straps over the shoulders","cn":"无肩带连衣裙/礼服/胸罩"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41strapless.mp3","us":"media/ldoce/hwd/ame/5/strapless.mp3"},"oxford":{"phon":"ˈstræpləs","pos":"adjective","senses":[{"en":"without straps","cn":"无肩带的；无吊带的"}]}},"stateroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(客轮上的)房舱，特等客舱","en":"On a passenger ship, a stateroom is a private room, especially one that is large and comfortable."},{"pos":"N-COUNT 可数名词","cn":"(宫殿等建筑物的)大厅","en":"In a palace or other impressive building, a stateroom is a large room for use on formal occasions."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a private room or place for sleeping on a ship 〔","cn":"船上的〕特等客舱﹐房舱"},{"en":"one of the large rooms in a palace 〔","cn":"宫殿里的〕大房间﹐豪华厅室"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41stateroom.mp3","us":"media/ldoce/hwd/ame/b/stateroom.mp3"},"oxford":{"phon":"ˈsteɪtruːm","pos":"noun","senses":[{"en":"a private room on a large ship","cn":"（轮船上的）特等客舱"},{"en":"a room used by important government members, members of a royal family, etc. on formal occasions","cn":"（政府要员或王室成员等使用的）会客厅，议事厅，国事活动厅"}]}},"storeroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贮藏室","en":"A storeroom is a room in which you keep things until they are needed.","ex":{"en":"...a storeroom filled with massive old furniture covered with dust.","cn":"堆满了尘封的大件旧式家具的贮藏室"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room where goods are stored","cn":"贮藏室"}]},"media":{"uk":"media/ldoce/hwd/bre/4/storeroom0205.mp3","us":"media/ldoce/hwd/ame/3/storeroom.mp3"},"oxford":{"phon":"ˈstɔːruːm","pos":"noun","senses":[{"en":"a room used for storing things","cn":"贮藏室","ex":{"en":"The room at the back was a storeroom for spare cables and lighting equipment.","cn":"后面的房间是贮藏室，存放着备用电缆和照明设备。"}}]}},"starboard":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(船舶的)右舷的，右侧的","en":"In sailing, the starboard side of a ship is the right side when you are on it and facing towards the front.","ex":{"en":"He detected a ship moving down the starboard side of the submarine.","cn":"他发现有一艘船正在潜艇的右侧航行。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the side of a ship or aircraft that is on your right when you are facing forwards 〔","cn":"船或飞机的〕右舷﹐右侧"}]},"vocab":{"pos":"n adj v","senses":[{"en":"The starboard is the right side of a boat or plane. You can also say that anything on the right side of a ship is starboard ."}]},"media":{"uk":"media/ldoce/hwd/bre/7/starboard0205.mp3","us":"media/ldoce/hwd/ame/1/starboard.mp3"},"oxford":{"phon":"ˈstɑːbəd","pos":"noun","senses":[{"en":"the side of a ship or an aircraft that is on the right when you are facing forward","cn":"（船舶或飞机的）右舷，右侧"}]}},"stoppage":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"停工;罢工","en":"When there is a stoppage, people stop working because of a disagreement with their employers.","ex":{"en":"Mineworkers in the Ukraine have voted for a one-day stoppage next month.","cn":"乌克兰矿工们已投票决定下个月罢工一天。"}},{"pos":"N-COUNT 可数名词","cn":"(足球等体育运动中的)中断比赛，暂停","en":"In football and some other sports, when there is a stoppage, the game stops for a short time, for example because a player is injured. The referee may add some extra time at the end of the game because of this."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of time when a group of workers stop working because of a disagreement about pay, working conditions etc","cn":""},{"en":"activities such as strikes, or doing less work than usual, as a way of trying to persuade an employer to improve pay, conditions etc","cn":""},{"en":"a short strike, especially one that lasts for one day","cn":""}]},"collocations":{"phrases":["ADJ. complete | work","VERB + STOPPAGE call The stoppage was called to protest against wage cuts. | threaten | be involved in | end","PREP. during a/the ~"]},"media":{"uk":"media/ldoce/hwd/bre/9/stoppage0205.mp3","us":"media/ldoce/hwd/ame/7/stoppage.mp3"},"examples":[{"en":"Play resumed quickly after the stoppage.","cn":"比赛中断后不久又继续进行。"},{"en":"a stoppage of blood to the heart","cn":"通往心脏血液的阻塞"}],"oxford":{"phon":"ˈstɒpɪdʒ","pos":"noun","senses":[{"en":"a situation in which people stop working as part of a protest or strike","cn":"停工；罢工","g":"[countable]","ex":{"en":"400 workers were involved in the stoppage.","cn":"400名工人参与了罢工。"}},{"en":"a situation in which a game is interrupted for a particular reason","cn":"比赛中断","g":"[countable]","lab":"sport","ex":{"en":"Play resumed quickly after the stoppage.","cn":"比赛中断后不久又继续进行。"}},{"en":"a situation in which something does not move forward or is blocked","cn":"堵塞；阻塞","g":"[countable]","ex":{"en":"a stoppage of blood to the heart","cn":"通往心脏血液的阻塞"}},{"en":"an amount of money that an employer takes from people’s wages for tax and other payments","cn":"（工资中用于纳税等的）扣除款","g":"[plural]","lab":"British English, old-fashioned, formal，，，，"}]}},"strainer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滤器;滤网","en":"A strainer is an object with holes which you pour a liquid through in order to separate the liquid from the solids in it.","ex":{"en":"Pour the broth through a strainer.","cn":"把肉汤倒进滤网滤一下。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a kitchen tool with lots of small holes in it, that is used for separating solids from liquids","cn":"滤器﹐滤网"}]},"media":{"img":["media/ldoce/img/tea_strainer.jpg"],"uk":"media/ldoce/hwd/bre/2/strainer0205.mp3","us":"media/ldoce/hwd/ame/a/strainer.mp3"},"examples":[{"en":"a tea-strainer","cn":"滤茶器"},{"en":"a tea strainer","cn":"滤茶器"}],"oxford":{"phon":"ˈstreɪnə(r)","pos":"noun","senses":[{"en":"a kitchen utensil (= a tool) with a lot of small holes in it, used for separating solids from liquids","cn":"滤器；滤盆；滤网","ex":{"en":"a tea-strainer","cn":"滤茶器"}}]}},"stoplight":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"交通信号灯;红绿灯","en":"A stoplight is a set of coloured lights which controls the flow of traffic on a road."},{"pos":"N-COUNT 可数名词","cn":"(车辆的)后灯，尾灯","en":"The stoplights on a car or other vehicle are the two red lights at the back."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of coloured lights used to control and direct traffic","cn":"交通信号灯﹐红绿灯"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41stoplight.mp3","us":"media/ldoce/hwd/ame/b/stoplight.mp3"}},"stick-in-the-mud":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"顽固守旧者;墨守成规者","en":"If you describe someone as a stick-in-the-mud, you disapprove of them because they do not like doing anything that is new or fun."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who refuses to try anything new – used to show disapproval","cn":"守旧的人﹐墨守成规的人〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41stick-in-the-m.mp3","us":"media/ldoce/hwd/ame/5/stick-in-the-mud.mp3"},"oxford":{"phon":"ˈstɪk ɪn ðə mʌd","pos":"noun","senses":[{"en":"a person who refuses to try anything new or exciting","cn":"守旧的人；墨守成规的人"}]}},"straw-coloured":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指头发)麦秆色的，淡黄色的","en":"If you describe something, especially hair, as straw-coloured, you mean that it is pale yellow."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"light yellow","cn":"浅黄色的﹐麦秆色的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld44straw-colour.mp3","us":"media/ldoce/hwd/ame/c/ld44straw-colour.mp3"},"oxford":{"phon":"ˈstrɔː kʌləd","pos":"adjective","senses":[{"en":"light yellow in colour","cn":"稻草色：浅黄色","ex":{"en":"straw-coloured hair","cn":"浅黄色的头发"}}]}},"stabbing":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"持刀伤人事件","en":"A stabbing is an incident in which someone stabs someone else with a knife."},{"pos":"ADJ 形容词","cn":"(疼痛)剧烈突发的","en":"A stabbing pain is a sudden sharp pain.","ex":{"en":"He was struck by a stabbing pain in his midriff.","cn":"他突然感到腹部一阵剧烈疼痛。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a stabbing pain is sharp and sudden 〔","cn":"疼痛〕突然而剧烈的﹐如刀刺的"},{"en":"a crime in which someone is stabbed","cn":"持刀[利器]伤人"}]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdestabbing.mp3","us":"media/ldoce/hwd/ame/f/stabbing1.mp3"},"examples":[{"en":"a fatal stabbing","cn":"持刀伤人致死事件"}],"oxford":{"phon":"ˈstæbɪŋ","pos":"noun","senses":[{"en":"an occasion when a person is stabbed with a knife or other pointed object","cn":"持刀（或其他利器）伤人事件","ex":{"en":"a fatal stabbing","cn":"持刀伤人致死事件"}},{"en":"very sharp, sudden and strong","cn":"突然而剧烈的；刀刺似的","ex":{"en":"a stabbing pain in the chest","cn":"胸部的一阵刺痛。"},"pos":"adjective"}]}},"standalone":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a standalone computer works on its own without being part of a network 〔","cn":"计算机〕独立运行的"},{"en":"a standalone company is one that is not part of a larger company 〔","cn":"公司〕独立的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/standalone0205.mp3","us":"media/ldoce/hwd/ame/a/laadstandalone.mp3"}},"strapped":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"手头拮据的;缺钱的","en":"If someone is strapped for money, they do not have enough money to buy or pay for the things they want or need.","ex":{"en":"My husband and I are really strapped for cash.","cn":"我和丈夫真的手头很紧。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no money or very little money to spend at the moment","cn":""},{"en":"having no money at the moment","cn":""},{"en":"not having enough money at the moment","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdestrapped.mp3","us":"media/ldoce/hwd/ame/a/strapped.mp3"},"examples":[{"en":"Can you lend me ten dollars? I’m a little strapped for cash.","cn":"你能借我十美元吗？我手头有点紧。"}],"oxford":{"phon":"stræpt","pos":"adjective","senses":[{"en":"having little or not enough money","cn":"缺钱的；手头紧的","ex":{"en":"I’m strapped for cash at the moment—can I pay you later?","cn":"我现在手头拮据——我可以稍后再付给你吗？"}}]}}});
